  function enemyCosmeticFrameIdFor(enemy = {}) {
    const explicit = String(enemy?.cosmeticFrameId || enemy?.enemyCosmeticFrameId || "").trim();
    if (explicit) return explicit;
    const rawKey = String(enemy?.key || enemy?.id || enemy?.enemyKey || "").trim();
    if (rawKey && ENEMY_COSMETIC_FRAME_BY_KEY[rawKey]) return ENEMY_COSMETIC_FRAME_BY_KEY[rawKey];
    const compactKey = rawKey.replace(/[\s_\-・·．.]/g, "").toLowerCase();
    if (compactKey && ENEMY_COSMETIC_FRAME_BY_KEY[compactKey]) return ENEMY_COSMETIC_FRAME_BY_KEY[compactKey];
    const nameKey = String(enemy?.name || enemy?.displayName || "").replace(/[\s_\-・·．.]/g, "");
    return ENEMY_COSMETIC_FRAME_BY_NAME[nameKey] || "";
  }

