  function normalizeBoardMapVisualStyle(value) {
    const normalized = String(value || "").trim().toLowerCase();
    return BOARD_MAP_VISUAL_STYLES.has(normalized) ? normalized : BOARD_MAP_VISUAL_STYLE_DEFAULT;
  }

  function applyBoardMapVisualStyle(value = boardMapVisualStyle) {
    boardMapVisualStyle = normalizeBoardMapVisualStyle(value);
    const map = refs.boardGameMap;
    if (!map) return boardMapVisualStyle;
    map.classList.toggle("map-visual-vintage", boardMapVisualStyle === "vintage");
    map.dataset.mapVisualStyle = boardMapVisualStyle;
    return boardMapVisualStyle;
  }

  function setBoardMapVisualStyle(value, options = {}) {
    const style = applyBoardMapVisualStyle(value);
    if (options.updateUrl !== false) {
      const url = new URL(location.href);
      url.searchParams.set("map_visual", style);
      history.replaceState(history.state, "", url);
    }
    return style;
  }
