  function tierLabel(tier) {
    return TIER_LABELS[String(tier || "").trim()] || String(tier || "");
  }

  function tierListLabel(tiers) {
    return (tiers || []).map(tierLabel).join(" / ");
  }

  function legacyTier(tier) {
    const value = String(tier || "").trim();
    return LEGACY_TIER_BY_LABEL[value] || value;
  }

  function tierRank(tier) {
    const value = legacyTier(tier);
    return Number(String(value || "T5").replace("T", "")) || 5;
  }

  function battleCarryItemImage(itemOrId) {
    const rawId = typeof itemOrId === "string" ? itemOrId : itemOrId?.id;
    const id = String(rawId || "").trim();
    const explicitImage = typeof itemOrId === "object" ? String(itemOrId?.image || "").trim() : "";
    if (explicitImage) return explicitImage;
    const gameItem = GAME_ITEMS[id];
    if (gameItem?.image) return gameItem.image;
    const def = BATTLE_CARRY_ITEM_DEFS[id];
    if (BATTLE_CARRY_ITEM_IMAGE_ALIASES[id]) return `images/board/items/${id}.webp`;
    const sameNameItem = def?.name
      ? Object.values(GAME_ITEMS).find((item) => normalizeGameItemCategory(item.category) === "held" && item.name === def.name)
      : null;
    if (sameNameItem?.image) return sameNameItem.image;
    const alias = BATTLE_CARRY_ITEM_IMAGE_ALIASES[id];
    return alias ? `images/board/items/${alias}.webp` : "";
  }

  function battleCarryItemDef(itemOrId) {
    const rawId = typeof itemOrId === "string" ? itemOrId : itemOrId?.id;
    const id = String(rawId || "").trim();
    if (!id) return null;
    if (BATTLE_CARRY_ITEM_DEFS[id]) {
      const def = BATTLE_CARRY_ITEM_DEFS[id];
      return { ...def, image: battleCarryItemImage(def) };
    }
    const gameItem = GAME_ITEMS[id];
    if (!gameItem || normalizeGameItemCategory(gameItem.category) !== "held") return null;
    return {
      id: gameItem.id,
      name: gameItem.name,
      category: gameItem.subType === "shell" ? "貝類戰鬥攜帶物" : (ITEM_CATEGORY_LABELS.held || "角色攜帶物"),
      rarity: gameItem.rarity || "C",
      summary: gameItem.uiSummary || gameItem.description || "戰鬥中自動生效。",
      image: battleCarryItemImage(gameItem),
      effect: gameItem.effect || { kind: "todo" },
      gameItem,
    };
  }

  function normalizeBattleCarryItem(item) {
    if (!item) return null;
    if (typeof item === "string") {
      const direct = battleCarryItemDef(item);
      if (direct) return { type: BATTLE_CARRY_ITEM_TYPE, id: direct.id, bound: false };
      const byName = [
        ...Object.values(BATTLE_CARRY_ITEM_DEFS),
        ...Object.values(GAME_ITEMS)
          .filter((entry) => normalizeGameItemCategory(entry.category) === "held")
          .map((entry) => ({
            id: entry.id,
            name: entry.name,
          })),
      ].find((entry) => entry.name === item);
      return byName ? { type: BATTLE_CARRY_ITEM_TYPE, id: byName.id, bound: false } : null;
    }
    const def = battleCarryItemDef(item);
    if (!def) return null;
    const normalized = {
      type: BATTLE_CARRY_ITEM_TYPE,
      id: def.id,
      bound: !!item.bound,
    };
    if (def.id === BULLET_ARSENAL_ITEM_ID) {
      const source = Array.isArray(item.arsenalItems) ? item.arsenalItems : [];
      normalized.arsenalItems = Array.from({ length: BULLET_ARSENAL_SLOT_LIMIT }, (_, index) => {
        const entry = normalizeBattleCarryItem(source[index]);
        return entry && entry.id !== BULLET_ARSENAL_ITEM_ID ? { ...entry, arsenalItems: undefined } : null;
      });
    }
    return normalized;
  }

  function createBattleCarryItem(id, options = {}) {
    const def = battleCarryItemDef(id);
    if (!def) return null;
    const item = {
      type: BATTLE_CARRY_ITEM_TYPE,
      id: def.id,
      bound: !!options.bound,
    };
    if (def.id === BULLET_ARSENAL_ITEM_ID) {
      const source = Array.isArray(options.arsenalItems) ? options.arsenalItems : [];
      item.arsenalItems = Array.from({ length: BULLET_ARSENAL_SLOT_LIMIT }, (_, index) => {
        const entry = normalizeBattleCarryItem(source[index]);
        return entry && entry.id !== BULLET_ARSENAL_ITEM_ID ? { ...entry, arsenalItems: undefined } : null;
      });
    }
    return item;
  }

  function battleCarryArsenalItems(item) {
    const normalized = normalizeBattleCarryItem(item);
    return normalized?.id === BULLET_ARSENAL_ITEM_ID
      ? (normalized.arsenalItems || []).slice(0, BULLET_ARSENAL_SLOT_LIMIT).filter(Boolean)
      : [];
  }

  function battleCarryArsenalSlots(item) {
    const normalized = normalizeBattleCarryItem(item);
    return normalized?.id === BULLET_ARSENAL_ITEM_ID
      ? Array.from({ length: BULLET_ARSENAL_SLOT_LIMIT }, (_, index) => normalized.arsenalItems?.[index] || null)
      : Array.from({ length: BULLET_ARSENAL_SLOT_LIMIT }, () => null);
  }

  function battleCarryItemsForCard(card) {
    const outer = normalizeBattleCarryItem(card?.battleCarryItem);
    if (!outer) return [];
    return outer.id === BULLET_ARSENAL_ITEM_ID ? battleCarryArsenalItems(outer) : [outer];
  }

  function battleCarryEquippedEntriesForCard(card) {
    const outer = normalizeBattleCarryItem(card?.battleCarryItem);
    if (!outer) return [];
    if (outer.id !== BULLET_ARSENAL_ITEM_ID) return [{ item: outer, slotIndex: -1, container: null }];
    return battleCarryArsenalSlots(outer)
      .map((item, slotIndex) => ({ item, slotIndex, container: outer }))
      .filter((entry) => entry.item);
  }

  function cardHasBattleCarryItem(card, itemId) {
    return battleCarryItemsForCard(card).some((item) => item.id === itemId);
  }

  function isBattleCarryItem(item) {
    return !!normalizeBattleCarryItem(item);
  }

  function battleCarryItemName(itemOrId) {
    return battleCarryItemDef(itemOrId)?.name || "未知攜帶物";
  }

  function battleCarryItemSummary(itemOrId) {
    return battleCarryItemDef(itemOrId)?.summary || "沒有登錄效果。";
  }

  function battleCarryItemEffect(itemOrId) {
    return battleCarryItemDef(itemOrId)?.effect || gameItemDef(typeof itemOrId === "string" ? itemOrId : itemOrId?.id)?.effect || {};
  }

  function battleCarryInventoryEntries(player) {
    return (player?.items || [])
      .map((item, index) => ({ item: normalizeBattleCarryItem(item), index }))
      .filter((entry) => entry.item);
  }

  function countBattleCarryItemsInBackpack(player, itemOrId) {
    const def = battleCarryItemDef(itemOrId);
    if (!def) return 0;
    return battleCarryInventoryEntries(player)
      .filter(({ item }) => item.id === def.id)
      .length;
  }

  function addBattleCarryItemToBackpack(player, itemOrId, options = {}) {
    const normalized = normalizeBattleCarryItem(itemOrId) || createBattleCarryItem(itemOrId, options);
    const def = battleCarryItemDef(normalized);
    if (!player || !def) return null;
    ensurePlayerInventoryState(player);
    player.items = Array.isArray(player.items) ? player.items : [];
    const item = createBattleCarryItem(def.id, {
      bound: normalized.bound || options.bound,
      arsenalItems: normalized.arsenalItems,
    });
    if (!item) return null;
    player.items.push(item);
    addInventoryItem(player, def.id, 1);
    return item;
  }

  function removeOneRegularBackpackItem(player) {
    if (!player) return false;
    const inventory = ensurePlayerInventoryState(player);
    const inventoryItem = Object.keys(inventory.items || {})
      .map(gameItemDef)
      .find((item) => item && !["held", "key"].includes(normalizeGameItemCategory(item.category)) && inventoryItemCount(player, item.id) > 0);
    if (inventoryItem) return removeFormalItemFromPlayer(player, inventoryItem.id, 1);
    if (!Array.isArray(player.items)) return false;
    const index = player.items.findIndex((item) => !isBattleCarryItem(item) && normalizeGameItemCategory(gameItemDef(item)?.category) !== "key");
    if (index < 0) return false;
    player.items.splice(index, 1);
    return true;
  }

  function isDevilFruitCharacter(card) {
    if (!card) return false;
    if (DEVIL_FRUIT_CHARACTER_IDS.has(String(card.id || ""))) return true;
    const name = String(card.name || "");
    return DEVIL_FRUIT_CHARACTER_NAME_PATTERNS.some((pattern) => name.includes(pattern));
  }

  function isDevilFruitEnemyInput(key, name, role = "") {
    if (DEVIL_FRUIT_ENEMY_KEYS.has(String(key || ""))) return true;
    if (DEVIL_FRUIT_ENEMY_NAMES.has(String(name || ""))) return true;
    return /果實能力者/.test(String(role || ""));
  }

  function ensureCardBattleCarrySlot(card) {
    if (!card) return null;
    card.battleCarryItem = normalizeBattleCarryItem(card.battleCarryItem);
    return card.battleCarryItem;
  }

  function ensureUniqueBattleCarryArsenalItems(player, card) {
    const arsenal = ensureCardBattleCarrySlot(card);
    if (arsenal?.id !== BULLET_ARSENAL_ITEM_ID) return arsenal;
    const previousMaxHp = cardMaxHp(card);
    const previousHp = Math.max(0, Number(card.currentHp ?? previousMaxHp));
    const slots = battleCarryArsenalSlots(arsenal);
    const seenIds = new Set();
    let changed = false;
    slots.forEach((item, index) => {
      if (!item || !seenIds.has(item.id)) {
        if (item) seenIds.add(item.id);
        return;
      }
      addBattleCarryItemToBackpack(player, { ...item, bound: false });
      slots[index] = null;
      changed = true;
    });
    if (changed) {
      arsenal.arsenalItems = slots;
      card.battleCarryItem = arsenal;
      const nextMaxHp = cardMaxHp(card);
      card.currentHp = previousHp <= 0 ? 0 : Math.max(1, Math.min(nextMaxHp, Math.round(previousHp * nextMaxHp / previousMaxHp)));
    }
    return arsenal;
  }

  function itemRarityLabel(rarity) {
    return { C: "C", B: "B", A: "A", S: "S" }[String(rarity || "").trim()] || "C";
  }

  function gameItemDef(itemOrId) {
    const rawId = typeof itemOrId === "string" ? itemOrId : itemOrId?.id || itemOrId?.name || itemOrId?.title;
    const id = String(rawId || "").trim();
    if (!id) return null;
    if (GAME_ITEMS[id]) return GAME_ITEMS[id];
    const byName = Object.values(GAME_ITEMS).find((item) => item.name === id);
    if (byName) return byName;
    const legacyMap = {
      "小補給": "heal_2",
      "戰鬥糧食": "battle_food",
      "防具": "guard_charm",
      "守護護符": "guard_charm",
      "防具 / 守護護符": "guard_charm",
      "航海指針": "pointer",
      "指定步數券": "fixed_step",
      "歷史本文拓本": "road_poneglyph",
      "東之歷史本文拓本": "road_poneglyph_east",
      "西之歷史本文拓本": "road_poneglyph_west",
      "南之歷史本文拓本": "road_poneglyph_south",
      "北之歷史本文拓本": "road_poneglyph_north",
      "被打穿的旗幟": "pierced_flag",
      "巔峰生命卡": "prime_vivre_card",
      "傳說的生命紙": "prime_vivre_card",
      "舊時代的記憶": "prime_vivre_card",
    };
    return GAME_ITEMS[legacyMap[id]] || null;
  }

  function itemDisplaySource(itemOrId) {
    const def = gameItemDef(itemOrId);
    if (def) return def;
    if (itemOrId && typeof itemOrId === "object") return itemOrId;
    return { name: String(itemOrId || "道具"), category: "key", image: "" };
  }

  function itemFallbackBadge(itemOrId, fallback = "") {
    const source = itemDisplaySource(itemOrId);
    if (fallback) return String(fallback).slice(0, 2);
    if (source.id === "pierced_flag") return "旗";
    if (source.id === "new_world_newspaper_3d2y") return "報";
    if (source.id === "prime_vivre_card") return "憶";
    if (source.id === "road_poneglyph") return "拓";
    if (source.id === "road_poneglyph_east") return "東";
    if (source.id === "road_poneglyph_west") return "西";
    if (source.id === "road_poneglyph_south") return "南";
    if (source.id === "road_poneglyph_north") return "北";
    const category = normalizeGameItemCategory(source.category || source.pocket);
    return {
      navigation: "航",
      battle: "戰",
      ship: "船",
      held: "攜",
      key: "重",
    }[category] || String(source.name || "道").slice(0, 1);
  }

  function itemFallbackIconPath(itemOrId) {
    const source = itemDisplaySource(itemOrId);
    const category = normalizeGameItemCategory(source.category || source.pocket);
    return {
      navigation: "images/board/attribute_icons/neutral.webp",
      battle: "images/board/move_learn_ui/move_type_icons/physical_attack.webp?v=20260828-v3-game-style",
      ship: "images/board/ship_info_ui/upgrade_icons/sail.webp",
      held: "images/board/training_ui/stat_icons/atk.webp",
      key: "images/board/judicial_raid_ui/reward_icons/unknown.webp",
    }[category] || "images/board/judicial_raid_ui/reward_icons/unknown.webp";
  }

  function itemImageForDisplay(itemOrId) {
    const source = itemDisplaySource(itemOrId);
    return String(source.image || "").trim();
  }

  function itemIconMarkup(itemOrId, className = "item-thumb", options = {}) {
    const source = itemDisplaySource(itemOrId);
    const image = String(options.image || itemImageForDisplay(source) || "").trim();
    const badge = itemFallbackBadge(source, options.badge || "");
    const alt = options.alt || source.name || "道具";
    const lineageFrameImage = String(options.frameImage || source.frameImage || "").trim();
    const lineagePortraitImage = String(options.portraitImage || source.portraitImage || image || "").trim();
    const isPostgameClue = source.kind === "postgame-clue" || source.effect?.kind === "postgame_york_clue";
    if (isPostgameClue) {
      const bossDef = postgameBossDef(source.effect?.bossKey || source.bossKey);
      const clueNumber = Math.max(1, Number(source.effect?.clueNumber || source.clueNumber || bossDef?.clueNumber || 1));
      const clueBadge = postgameClueCardLabel(clueNumber);
      const clueFrameImage = String(options.frameImage || source.frameImage || source.image || "images/board/postgame_clue_ui/york_clue_playing_card_frame_v2.webp").trim();
      const clueIslandImage = String(options.portraitImage || source.portraitImage || bossDef?.islandImage || ISLAND_IMAGE_MAP.postgame_boss).trim();
      const classes = `${className} item-thumb postgame-clue-icon`.trim();
      return `
        <span class="${escapeModalText(classes)}" data-item-fallback="${escapeModalText(clueBadge)}">
          ${clueFrameImage ? `<img class="postgame-clue-icon-frame" src="${escapeModalText(clueFrameImage)}" alt="" aria-hidden="true" loading="lazy" onerror="this.remove();">` : ""}
          <span class="postgame-clue-island-window">
            ${clueIslandImage ? `<img class="postgame-clue-island" src="${escapeModalText(clueIslandImage)}" alt="${escapeModalText(alt)}" loading="lazy" data-fallback-src="${escapeModalText(ISLAND_IMAGE_MAP.postgame_boss)}" onerror="if(this.dataset.fallbackSrc){this.src=this.dataset.fallbackSrc;this.dataset.fallbackSrc='';}else{this.remove();}">` : ""}
          </span>
          <span class="postgame-clue-card-rank corner-top${clueBadge.length > 1 ? " double" : ""}" aria-label="線索牌 ${escapeModalText(clueBadge)}">${escapeModalText(clueBadge)}</span>
          <span class="postgame-clue-card-rank corner-bottom${clueBadge.length > 1 ? " double" : ""}" aria-hidden="true">${escapeModalText(clueBadge)}</span>
          <span class="item-thumb-fallback">${escapeModalText(clueBadge)}</span>
        </span>
      `;
    }
    if (source.kind === "lineage-factor" && (lineageFrameImage || lineagePortraitImage)) {
      const classes = `${className} item-thumb lineage-factor-icon`.trim();
      return `
        <span class="${escapeModalText(classes)}" data-item-fallback="${escapeModalText(badge)}">
          <span class="lineage-factor-portrait-window">
            ${lineagePortraitImage ? `<img class="lineage-factor-portrait" src="${escapeModalText(lineagePortraitImage)}" alt="${escapeModalText(alt)}" loading="lazy" onerror="this.remove();">` : ""}
          </span>
          ${lineageFrameImage ? `<img class="lineage-factor-icon-frame" src="${escapeModalText(lineageFrameImage)}" alt="" aria-hidden="true" loading="lazy" onerror="this.remove();">` : ""}
          <span class="item-thumb-fallback"><img src="${itemFallbackIconPath(source)}" alt=""></span>
        </span>
      `;
    }
    const classes = `${className} item-thumb${image ? "" : " fallback"}`.trim();
    return `
      <span class="${escapeModalText(classes)}" data-item-fallback="${escapeModalText(badge)}">
        ${image ? `<img src="${escapeModalText(image)}" alt="${escapeModalText(alt)}" loading="lazy" onerror="this.remove();this.parentElement.classList.add('fallback');">` : ""}
        <span class="item-thumb-fallback"><img src="${itemFallbackIconPath(source)}" alt=""></span>
      </span>
    `;
  }

  function setItemIconElement(element, itemOrId, fallback = "") {
    if (!element) return;
    element.innerHTML = itemIconMarkup(itemOrId || { name: "道具", category: "key", image: "" }, "inline-item-thumb", { badge: fallback });
  }

  const ITEM_BOUNTY_UNLOCKS = {
    C: 100000000,
    B: 1000000000,
    A: 3000000000,
    S: 3000000000,
  };

  function playerBountyValue(player) {
    return Math.max(0, Math.floor(Number(player?.bounty || 0)));
  }

  function itemUnlockBounty(itemOrId) {
    const item = gameItemDef(itemOrId) || itemOrId;
    return ITEM_BOUNTY_UNLOCKS[itemRarityLabel(item?.rarity)] ?? 0;
  }

  function itemUnlockedByBounty(player, itemOrId) {
    return playerBountyValue(player) >= itemUnlockBounty(itemOrId);
  }

  function bountyUnlockStage(player) {
    const bounty = playerBountyValue(player);
    if (bounty >= ITEM_BOUNTY_UNLOCKS.S) return "S";
    if (bounty >= ITEM_BOUNTY_UNLOCKS.A) return "A";
    if (bounty >= ITEM_BOUNTY_UNLOCKS.B) return "B";
    return "C";
  }

  function unknownGameItemDef(itemOrId) {
    const id = typeof itemOrId === "string" ? itemOrId : itemOrId?.id || itemOrId?.name || itemOrId?.title || "unknown_item";
    const name = typeof itemOrId === "string" ? itemOrId : itemOrId?.name || itemOrId?.title || itemOrId?.id || "未知道具";
    return {
      id: String(id || "unknown_item"),
      name: String(name || "未知道具"),
      category: "key",
      rarity: "C",
      internalTier: "unknown",
      stackable: true,
      sellable: false,
      usableInBattle: false,
      usableOnMap: false,
      equippable: false,
      description: "舊存檔或尚未登錄的道具，效果會被略過。",
      uiSummary: "未知道具，效果略過。",
      effect: { kind: "unknown" },
      obtain: { shops: [], seaEvents: [], enemyDrop: { commonPool: false, devilFruitExtraPool: false } },
    };
  }

  function ensurePlayerInventoryState(player) {
    if (!player) return { items: {}, equipped: {} };
    player.items = Array.isArray(player.items) ? player.items : [];
    player.inventory = player.inventory && typeof player.inventory === "object" ? player.inventory : {};
    player.inventory.items = player.inventory.items && typeof player.inventory.items === "object" ? player.inventory.items : {};
    player.inventory.equipped = player.inventory.equipped && typeof player.inventory.equipped === "object" ? player.inventory.equipped : {};
    player.activeMapBuffs = Array.isArray(player.activeMapBuffs) ? player.activeMapBuffs : [];

    const addLegacyCount = (itemId, amount) => {
      const def = gameItemDef(itemId);
      const count = Math.max(0, Math.round(Number(amount || 0)));
      if (!def || count <= 0) return;
      player.inventory.items[def.id] = Math.max(0, Math.round(Number(player.inventory.items[def.id] || 0))) + count;
    };

    if (!player.inventory.__legacySynced) {
      addLegacyCount("heal_2", player.smallSupplies);
      addLegacyCount("fixed_step", player.fixedStepTokens);
      addLegacyCount("pointer", player.routeInsight);
      addLegacyCount("guard_charm", player.guardCharm);
      addLegacyCount("battle_food", player.battleFood);
      player.items.forEach((item) => {
        const carry = normalizeBattleCarryItem(item);
        if (carry) {
          addLegacyCount(carry.id, 1);
          return;
        }
        const rawLegacyItem = typeof item === "string" ? item : item?.id || item?.name || item?.title || "";
        if (rawLegacyItem === "judicial_pass" || rawLegacyItem === "司法島突破證") {
          addLegacyCount("pierced_flag", 1);
          return;
        }
        const def = gameItemDef(item);
        if (def) addLegacyCount(def.id, 1);
      });
      if (Array.isArray(player.roadPoneglyphs) && player.roadPoneglyphs.length > 0) {
        player.roadPoneglyphs.forEach((glyphId) => addLegacyCount(roadPoneglyphItemIdForGlyph(glyphId), 1));
      }
      player.inventory.__legacySynced = true;
    }

    player.inventory.equipped = {};
    (player.crew || []).forEach((card, index) => {
      const carry = ensureCardBattleCarrySlot(card);
      if (carry) player.inventory.equipped[card?.id || `crew_${index}`] = carry.id;
    });
    if (Number(player.inventory.items.judicial_pass || 0) > 0) {
      player.inventory.items.pierced_flag = Math.max(0, Math.round(Number(player.inventory.items.pierced_flag || 0)))
        + Math.max(0, Math.round(Number(player.inventory.items.judicial_pass || 0)));
      delete player.inventory.items.judicial_pass;
    }
    if (Number(player.inventory.items.rare_passive_capsule || 0) > 0) {
      player.inventory.items.passive_capsule = Math.max(0, Math.round(Number(player.inventory.items.passive_capsule || 0)))
        + Math.max(0, Math.round(Number(player.inventory.items.rare_passive_capsule || 0)));
      delete player.inventory.items.rare_passive_capsule;
    }
    Object.entries(player.inventory.items).forEach(([id, count]) => {
      const maxStack = Math.max(0, Math.round(Number(gameItemDef(id)?.maxStack || 0)));
      const normalized = Math.min(
        maxStack > 0 ? maxStack : Number.POSITIVE_INFINITY,
        Math.max(0, Math.round(Number(count || 0)))
      );
      if (normalized <= 0) delete player.inventory.items[id];
      else player.inventory.items[id] = normalized;
    });
    return player.inventory;
  }

  function normalizeCosmeticFrameId(value = "") {
    const raw = String(value || "").trim();
    if (!raw) return "";
    if (COSMETIC_FRAME_DEFS[raw]) return raw;
    const key = raw.replace(/[\s_-]+/g, "").toLowerCase();
    return COSMETIC_FRAME_ALIAS[key] || "";
  }

  function cosmeticFrameDef(frameId = "") {
    const id = normalizeCosmeticFrameId(frameId);
    return id ? COSMETIC_FRAME_DEFS[id] || null : null;
  }

  function ensurePlayerCosmeticFrameState(player) {
    if (!player) return [];
    const seen = new Set();
    player.ownedCosmeticFrameIds = (Array.isArray(player.ownedCosmeticFrameIds) ? player.ownedCosmeticFrameIds : [])
      .map((id) => normalizeCosmeticFrameId(id))
      .filter((id) => {
        if (!id || seen.has(id)) return false;
        seen.add(id);
        return true;
      });
    const activeId = normalizeCosmeticFrameId(player.activeCosmeticFrameId);
    player.activeCosmeticFrameId = activeId && seen.has(activeId)
      ? activeId
      : (player.ownedCosmeticFrameIds[0] || "");
    return player.ownedCosmeticFrameIds;
  }

  function isNikaCosmeticFrameCard(card = {}) {
    const activeForm = activeEvolutionForm(card);
    const tokens = [
      card.id,
      card.key,
      card.cardId,
      card.characterId,
      card.formId,
      card.evolutionFormId,
      card.formKey,
      card.evolutionId,
      card.evolutionKey,
      card.baseId,
      card.name,
      card.displayName,
      activeForm?.id,
      activeForm?.name,
      activeForm?.displayName,
    ];
    const haystack = tokens
      .filter((token) => token != null && token !== "")
      .map((token) => String(token))
      .join("|")
      .replace(/\s+/g, "");
    return haystack.includes("luffy_gear_fifth") || haystack.includes("五檔") || haystack.includes("尼卡");
  }

  function cosmeticFrameCardHasAnyToken(card = {}, values = []) {
    const activeForm = activeEvolutionForm(card);
    const tokens = [
      card.id,
      card.key,
      card.cardId,
      card.characterId,
      card.formId,
      card.evolutionFormId,
      card.formKey,
      card.evolutionId,
      card.evolutionKey,
      card.baseId,
      card.name,
      card.displayName,
      activeForm?.id,
      activeForm?.key,
      activeForm?.name,
      activeForm?.displayName,
    ]
      .filter((token) => token != null && token !== "")
      .map((token) => String(token).replace(/\s+/g, ""));
    const wanted = (Array.isArray(values) ? values : [values])
      .filter((value) => value != null && value !== "")
      .map((value) => String(value).replace(/\s+/g, ""));
    return wanted.some((value) => tokens.includes(value));
  }

  function defaultCharacterCosmeticFrameId(card = {}) {
    const def = Object.values(COSMETIC_FRAME_DEFS)
      .find((entry) => (
        entry.scope === "character"
        && entry.id !== "nikaFrame"
        && cosmeticFrameCanEquipCard(entry, card, { includeInherited: false })
      ));
    if (def) return def.id;
    return isNikaCosmeticFrameCard(card) ? "nikaFrame" : "";
  }

  function cosmeticFrameCanEquipCard(def, card, options = {}) {
    if (def?.scope === "character") {
      if (def.characterKind === "nika") return isNikaCosmeticFrameCard(card);
      if (def.formIds && cosmeticFrameCardHasAnyToken(card, def.formIds)) return true;
      if (options.includeInherited !== false && def.inheritToFormIds) {
        return cosmeticFrameCardHasAnyToken(card, def.inheritToFormIds);
      }
      return false;
    }
    return !!def && !!card;
  }

  function isCharacterCosmeticFrameForCard(def, card) {
    return !!def && def.scope === "character" && cosmeticFrameCanEquipCard(def, card);
  }

  function characterCosmeticFrameDefsForCard(card) {
    return Object.values(COSMETIC_FRAME_DEFS).filter((def) => isCharacterCosmeticFrameForCard(def, card));
  }

  function availableCosmeticFrameDefsForCard(player, card) {
    const byId = new Map();
    ensurePlayerCosmeticFrameState(player)
      .map((frameId) => cosmeticFrameDef(frameId))
      .filter((def) => cosmeticFrameCanEquipCard(def, card))
      .forEach((def) => byId.set(def.id, def));
    characterCosmeticFrameDefsForCard(card).forEach((def) => byId.set(def.id, def));
    return Array.from(byId.values());
  }

  function normalizeCrewCosmeticFrameId(player, card) {
    if (!player || !card) return "";
    const owned = new Set(ensurePlayerCosmeticFrameState(player));
    const frameId = normalizeCosmeticFrameId(card.cosmeticFrameId || "");
    const def = cosmeticFrameDef(frameId);
    if (frameId && (owned.has(frameId) || isCharacterCosmeticFrameForCard(def, card)) && cosmeticFrameCanEquipCard(def, card)) {
      card.cosmeticFrameId = frameId;
      return frameId;
    }
    card.cosmeticFrameId = "";
    return "";
  }

  function activeCrewCosmeticFrameId(player, card) {
    return normalizeCrewCosmeticFrameId(player, card);
  }

  function crewCosmeticFrameLine(player, card) {
    const ownedCount = ensurePlayerCosmeticFrameState(player).length;
    const frameId = activeCrewCosmeticFrameId(player, card);
    const def = cosmeticFrameDef(frameId);
    if (def) return `外觀框：${def.label}`;
    return ownedCount > 0 ? "外觀框：未裝備" : "外觀框：尚未解鎖";
  }

  function equipCrewCosmeticFrame(player, cardIndex, frameId, options = {}) {
    const card = player?.crew?.[cardIndex];
    if (!card) return { ok: false, reason: "找不到角色。" };
    const normalizedId = normalizeCosmeticFrameId(frameId);
    if (!normalizedId) {
      const previousId = activeCrewCosmeticFrameId(player, card);
      card.cosmeticFrameId = "";
      if (previousId && options.log !== false) addLog(`${cardDisplayName(card)} 卸下外觀框。`);
      return { ok: true, reason: "" };
    }
    const owned = ensurePlayerCosmeticFrameState(player);
    const def = cosmeticFrameDef(normalizedId);
    const isCharacterFrame = isCharacterCosmeticFrameForCard(def, card);
    if (!def || (!owned.includes(normalizedId) && !isCharacterFrame)) return { ok: false, reason: "尚未解鎖這個外觀框，或這名角色不能裝備。" };
    if (!cosmeticFrameCanEquipCard(def, card)) return { ok: false, reason: `${cardDisplayName(card)} 不能裝備這個外觀框。` };
    card.cosmeticFrameId = normalizedId;
    if (!isCharacterFrame) player.activeCosmeticFrameId = normalizedId;
    if (options.log !== false) addLog(`${cardDisplayName(card)} 裝備了 ${def.label}。`);
    return { ok: true, reason: "" };
  }

  function applyDefaultCosmeticFrameToCrew(player, frameId, options = {}) {
    const normalizedId = normalizeCosmeticFrameId(frameId);
    const owned = ensurePlayerCosmeticFrameState(player);
    if (!player || !normalizedId || !owned.includes(normalizedId)) return 0;
    let applied = 0;
    (player.crew || []).forEach((card, index) => {
      if (activeCrewCosmeticFrameId(player, card)) return;
      const result = equipCrewCosmeticFrame(player, index, normalizedId, { log: false });
      if (result.ok) applied += 1;
    });
    if (applied > 0 && options.log) {
      const def = cosmeticFrameDef(normalizedId);
      addLog(`${player.name} 的 ${applied} 名船員自動裝備 ${def?.label || "外觀框"}。`);
    }
    return applied;
  }

  function grantCosmeticFrameToPlayer(player, frameId, options = {}) {
    const def = cosmeticFrameDef(frameId);
    if (!player || !def) return false;
    const owned = ensurePlayerCosmeticFrameState(player);
    const alreadyOwned = owned.includes(def.id);
    if (!alreadyOwned) owned.push(def.id);
    if (options.autoEquip !== false) {
      player.activeCosmeticFrameId = def.id;
      applyDefaultCosmeticFrameToCrew(player, def.id, { log: false });
    }
    if (!alreadyOwned && options.log !== false) {
      addLog(`${player.name} 解鎖外觀框：${def.label}（${def.unlockText}）。`);
    }
    return !alreadyOwned;
  }

  function gameHasJudicialClearForCosmeticFrame() {
    const game = state.gameState;
    if (!game) return false;
    const raid = game.judicialRaid && typeof game.judicialRaid === "object" ? game.judicialRaid : {};
    if (raid.cleared || Number(raid.clearCount || 0) > 0) return true;
    const islandState = game.boardData?.islandStates?.[JUDICIAL_ISLAND_ID];
    if (islandState?.isDefeated || islandState?.isJudicialDefeated) return true;
    return (Array.isArray(game.log) ? game.log : []).some((line) => /司法島.*(通關|攻破|討伐戰第.+次通關)/.test(String(line || "")));
  }

  function playerHasMarinefordClearForCosmeticFrame(player) {
    if (!player) return false;
    const hold = player.marinefordHold && typeof player.marinefordHold === "object" ? player.marinefordHold : {};
    const rewards = Array.isArray(hold.rewards) ? hold.rewards.map((item) => String(item || "")) : [];
    if (hold.win || rewards.some((item) => item.includes("3D2Y"))) return true;
    if (inventoryItemCount(player, "new_world_newspaper_3d2y") > 0) return true;
    const playerName = String(player.name || "").trim();
    return (Array.isArray(state.gameState?.log) ? state.gameState.log : []).some((line) => {
      const text = String(line || "");
      return text.includes("3D2Y") && text.includes("海軍本部") && (!playerName || text.includes(playerName));
    });
  }

  function playerHasImpelDownMagellanClearForCosmeticFrame(player) {
    if (!player) return false;
    if (normalizeDefeatedEnemies(player).some((entry) => {
      if (Number(entry.count || 0) <= 0) return false;
      const key = String(entry.key || "").toLowerCase();
      const name = String(entry.name || "");
      return key === "magellan" || key.includes("magellan") || name.includes("麥哲倫");
    })) {
      return true;
    }
    const playerName = String(player.name || "").trim();
    return (Array.isArray(state.gameState?.log) ? state.gameState.log : []).some((line) => {
      const text = String(line || "");
      return text.includes("麥哲倫") && /(擊敗|擊退|打倒)/.test(text) && (!playerName || text.includes(playerName));
    });
  }

  function playerHasYonkoGlyphClearForCosmeticFrame(player, glyphId) {
    if (!player || !glyphId) return false;
    normalizePlayerYonkoRewardState(player);
    if (player.defeatedYonkoGlyphs.includes(glyphId)) return true;
    if (syncPlayerRoadPoneglyphsFromInventory(player).includes(glyphId)) return true;
    const info = ROAD_PONEGLYPH_BY_GLYPH[glyphId];
    if (info && inventoryItemCount(player, info.itemId) > 0) return true;
    return false;
  }

  function playerHasAllYonkoGlyphClearsForCosmeticFrame(player) {
    if (!player) return false;
    const owned = new Set(ensurePlayerCosmeticFrameState(player));
    return Object.entries(YONKO_COSMETIC_FRAME_BY_GLYPH).every(([glyphId, frameId]) => (
      owned.has(frameId) || playerHasYonkoGlyphClearForCosmeticFrame(player, glyphId)
    ));
  }

  function playerHasFinalImuClearForCosmeticFrame(player) {
    if (!player) return false;
    if (player.finalGateDefeated || state.gameState?.finalGateDefeatedBy?.[player.id]) return true;
    const playerName = String(player.name || "").trim();
    return (Array.isArray(state.gameState?.log) ? state.gameState.log : []).some((line) => {
      const text = String(line || "");
      return text.includes("伊姆") && /(擊敗|擊退|打倒|倒下)/.test(text) && (!playerName || text.includes(playerName));
    });
  }

  function syncEarnedCosmeticFramesFromInventory(player) {
    if (!player) return;
    ensurePlayerInventoryState(player);
    const hadActive = !!normalizeCosmeticFrameId(player.activeCosmeticFrameId);
    if (inventoryItemCount(player, "judicial_clear_chest") > 0 || gameHasJudicialClearForCosmeticFrame()) {
      grantCosmeticFrameToPlayer(player, "goldenDenDen", { autoEquip: false, log: false });
    }
    if (playerHasMarinefordClearForCosmeticFrame(player)) {
      grantCosmeticFrameToPlayer(player, "threeDTwoY", { autoEquip: false, log: false });
    }
    if (playerHasImpelDownMagellanClearForCosmeticFrame(player)) {
      grantCosmeticFrameToPlayer(player, "impelDownMagellan", { autoEquip: false, log: false });
    }
    Object.entries(YONKO_COSMETIC_FRAME_BY_GLYPH).forEach(([glyphId, frameId]) => {
      if (playerHasYonkoGlyphClearForCosmeticFrame(player, glyphId)) {
        grantCosmeticFrameToPlayer(player, frameId, { autoEquip: false, log: false });
      }
    });
    if (playerHasAllYonkoGlyphClearsForCosmeticFrame(player)) {
      grantCosmeticFrameToPlayer(player, "yonkoAllClear", { autoEquip: false, log: false });
    }
    if (playerHasFinalImuClearForCosmeticFrame(player)) {
      grantCosmeticFrameToPlayer(player, "finalImu", { autoEquip: false, log: false });
    }
    if (playerHasDefeatedRocks(player)) {
      grantCosmeticFrameToPlayer(player, "rocksConqueror", { autoEquip: false, log: false });
    }
    ensurePlayerCosmeticFrameState(player);
    if (!hadActive) {
      if (player.ownedCosmeticFrameIds.includes("rocksConqueror")) player.activeCosmeticFrameId = "rocksConqueror";
      else if (player.ownedCosmeticFrameIds.includes("finalImu")) player.activeCosmeticFrameId = "finalImu";
      else if (player.ownedCosmeticFrameIds.includes("yonkoAllClear")) player.activeCosmeticFrameId = "yonkoAllClear";
      else if (player.ownedCosmeticFrameIds.includes("threeDTwoY")) player.activeCosmeticFrameId = "threeDTwoY";
      else if (player.ownedCosmeticFrameIds.includes("goldenDenDen")) player.activeCosmeticFrameId = "goldenDenDen";
      else if (player.ownedCosmeticFrameIds.includes("impelDownMagellan")) player.activeCosmeticFrameId = "impelDownMagellan";
      else {
        const yonkoFrameId = Object.values(YONKO_COSMETIC_FRAME_BY_GLYPH)
          .find((frameId) => player.ownedCosmeticFrameIds.includes(frameId));
        if (yonkoFrameId) player.activeCosmeticFrameId = yonkoFrameId;
      }
    }
    if (player.activeCosmeticFrameId) applyDefaultCosmeticFrameToCrew(player, player.activeCosmeticFrameId, { log: false });
  }

  function activePlayerCosmeticFrameId(player) {
    ensurePlayerCosmeticFrameState(player);
    return normalizeCosmeticFrameId(player?.activeCosmeticFrameId);
  }

  function addInventoryItem(player, itemOrId, quantity = 1) {
    const def = gameItemDef(itemOrId);
    if (!player || !def) return 0;
    const inventory = ensurePlayerInventoryState(player);
    const count = Math.max(1, Math.round(Number(quantity || 1)));
    inventory.items[def.id] = Math.max(0, Math.round(Number(inventory.items[def.id] || 0))) + count;
    rememberPostgameBossClueForVoyage(player, def);
    return inventory.items[def.id];
  }

  function removeInventoryItem(player, itemOrId, quantity = 1) {
    const def = gameItemDef(itemOrId);
    if (!player || !def) return false;
    const inventory = ensurePlayerInventoryState(player);
    const count = Math.max(1, Math.round(Number(quantity || 1)));
    const current = Math.max(0, Math.round(Number(inventory.items[def.id] || 0)));
    if (current < count) return false;
    inventory.items[def.id] = current - count;
    if (inventory.items[def.id] <= 0) delete inventory.items[def.id];
    return true;
  }

  function adjustLegacyItemCount(player, itemOrId, delta) {
    const def = gameItemDef(itemOrId);
    if (!player || !def || !delta) return;
    const next = (value) => Math.max(0, Math.round(Number(value || 0)) + delta);
    if (def.id === "heal_2") player.smallSupplies = next(player.smallSupplies);
    if (def.id === "battle_food") player.battleFood = next(player.battleFood);
    if (def.id === "guard_charm") player.guardCharm = next(player.guardCharm);
    if (def.id === "pointer") player.routeInsight = next(player.routeInsight);
    if (def.id === "fixed_step") player.fixedStepTokens = next(player.fixedStepTokens);
  }

  function removeFormalItemFromPlayer(player, itemOrId, quantity = 1) {
    const def = gameItemDef(itemOrId);
    if (!def || !removeInventoryItem(player, def.id, quantity)) return false;
    adjustLegacyItemCount(player, def.id, -Math.max(1, Math.round(Number(quantity || 1))));
    return true;
  }

  function inventoryItemCount(player, itemOrId) {
    const def = gameItemDef(itemOrId);
    if (!player || !def) return 0;
    const inventory = ensurePlayerInventoryState(player);
    return Math.max(0, Math.round(Number(inventory.items[def.id] || 0)));
  }

  function isPostgameBossClueItem(itemOrId) {
    const def = gameItemDef(itemOrId);
    return Boolean(def && (def.kind === "postgame-clue" || def.effect?.kind === "postgame_york_clue"));
  }

  function rememberPostgameBossClueForVoyage(player, itemOrId) {
    const def = gameItemDef(itemOrId);
    if (!player || !def || !isPostgameBossClueItem(def)) return false;
    player.unlockedPostgameBossClueItemIds = Array.isArray(player.unlockedPostgameBossClueItemIds)
      ? player.unlockedPostgameBossClueItemIds.map(String)
      : [];
    if (player.unlockedPostgameBossClueItemIds.includes(def.id)) return false;
    player.unlockedPostgameBossClueItemIds.push(def.id);
    return true;
  }

  function normalizePlayerPostgameBossVoyageState(player) {
    if (!player) return [];
    const known = new Set(
      (Array.isArray(player.unlockedPostgameBossClueItemIds) ? player.unlockedPostgameBossClueItemIds : [])
        .map((itemId) => String(itemId || ""))
        .filter((itemId) => isPostgameBossClueItem(itemId))
    );
    const inventory = ensurePlayerInventoryState(player);
    Object.entries(inventory.items || {}).forEach(([itemId, quantity]) => {
      if (Number(quantity || 0) > 0 && isPostgameBossClueItem(itemId)) known.add(itemId);
    });
    player.unlockedPostgameBossClueItemIds = [...known];
    return player.unlockedPostgameBossClueItemIds;
  }

  function normalizeYorkDecoderTier(value) {
    return Math.max(0, Math.min(3, Math.floor(Number(value) || 0)));
  }

  function yorkDecoderTierForItemId(itemId) {
    const index = YORK_DECODER_ITEM_IDS.indexOf(String(itemId || ""));
    return index >= 0 ? index + 1 : 0;
  }

  function normalizePlayerYorkDecoderState(player) {
    if (!player) return 0;
    const inventory = ensurePlayerInventoryState(player);
    const inventoryTier = YORK_DECODER_ITEM_IDS.reduce((highest, itemId, index) => (
      Math.max(highest, Number(inventory.items[itemId] || 0) > 0 ? index + 1 : 0)
    ), 0);
    const legacyTier = (player.items || []).reduce((highest, item) => {
      const rawId = typeof item === "string" ? item : item?.id;
      return Math.max(highest, yorkDecoderTierForItemId(rawId));
    }, 0);
    const tier = Math.max(normalizeYorkDecoderTier(player.yorkDecoderTier), inventoryTier, legacyTier);
    YORK_DECODER_ITEM_IDS.forEach((itemId) => delete inventory.items[itemId]);
    player.items = (player.items || []).filter((item) => {
      const rawId = typeof item === "string" ? item : item?.id;
      return yorkDecoderTierForItemId(rawId) <= 0;
    });
    if (tier > 0) inventory.items[YORK_DECODER_ITEM_IDS[tier - 1]] = 1;
    player.yorkDecoderTier = tier;
    return tier;
  }

  function yorkDecoderDropRate(playerOrTier) {
    const tier = typeof playerOrTier === "object"
      ? normalizePlayerYorkDecoderState(playerOrTier)
      : normalizeYorkDecoderTier(playerOrTier);
    return YORK_CLUE_PUZZLE_API?.eclipseDropRateForTier?.(tier) ?? [0.1, 0.2, 0.3, 0.4][tier];
  }

  function grantYorkDecoderTier(player, requestedTier, options = {}) {
    if (!player) return null;
    const currentTier = normalizePlayerYorkDecoderState(player);
    const targetTier = normalizeYorkDecoderTier(requestedTier);
    if (targetTier <= currentTier) return null;
    const itemId = YORK_DECODER_ITEM_IDS[targetTier - 1];
    const itemDef = gameItemDef(itemId);
    if (!itemDef) return null;
    const inventory = ensurePlayerInventoryState(player);
    YORK_DECODER_ITEM_IDS.forEach((id) => delete inventory.items[id]);
    inventory.items[itemId] = 1;
    player.yorkDecoderTier = targetTier;
    recordMissionEvent(player, {
      type: "obtain_item",
      itemId,
      itemName: itemDef.name,
      category: "key",
      amount: 1,
      source: options.source || "york_clue_puzzle",
    }, 1);
    return {
      previousTier: currentTier,
      tier: targetTier,
      itemId,
      itemDef,
      dropRate: yorkDecoderDropRate(targetTier),
    };
  }

  function formalItemMaxStack(itemOrId) {
    const def = gameItemDef(itemOrId);
    return Math.max(0, Math.round(Number(def?.maxStack || 0)));
  }

  function formalItemGrantCapacity(player, itemOrId) {
    const maxStack = formalItemMaxStack(itemOrId);
    return maxStack > 0 ? Math.max(0, maxStack - inventoryItemCount(player, itemOrId)) : Number.POSITIVE_INFINITY;
  }

  function addMapBuffFromItem(player, itemDef) {
    if (!player || !itemDef?.effect) return false;
    const effect = itemDef.effect;
    player.activeMapBuffs = Array.isArray(player.activeMapBuffs) ? player.activeMapBuffs : [];
    if (effect.exclusiveWithOtherLures) {
      player.activeMapBuffs = player.activeMapBuffs.filter((buff) => !buff?.data?.exclusiveWithOtherLures);
    }
    player.activeMapBuffs.push({
      itemId: itemDef.id,
      kind: effect.kind,
      remainingSteps: Math.max(0, Number(effect.steps || 0)),
      remainingTurns: Math.max(0, Number(effect.turns || (effect.kind === "scare_low_level_enemy" ? 1 : 0))),
      data: { ...effect },
      createdAtTurn: state.gameState?.round || 1,
    });
    return true;
  }

  function mapBuffAppliesToSeaZone() {
    return true;
  }

  function tickPlayerMapBuffSteps(player, steps = 1) {
    if (!player || !Array.isArray(player.activeMapBuffs)) return;
    const delta = Math.max(1, Math.round(Number(steps || 1)));
    player.activeMapBuffs = player.activeMapBuffs
      .map((buff) => ({
        ...buff,
        remainingSteps: Number(buff.remainingSteps || 0) > 0 ? Math.max(0, Number(buff.remainingSteps || 0) - delta) : Number(buff.remainingSteps || 0),
      }))
      .filter((buff) => Number(buff.remainingSteps || 0) > 0 || Number(buff.remainingTurns || 0) > 0);
  }

  function tickPlayerMapBuffTurns(player, turns = 1) {
    if (!player || !Array.isArray(player.activeMapBuffs)) return;
    const delta = Math.max(1, Math.round(Number(turns || 1)));
    player.activeMapBuffs = player.activeMapBuffs
      .map((buff) => ({
        ...buff,
        remainingTurns: Number(buff.remainingTurns || 0) > 0 ? Math.max(0, Number(buff.remainingTurns || 0) - delta) : Number(buff.remainingTurns || 0),
      }))
      .filter((buff) => Number(buff.remainingSteps || 0) > 0 || Number(buff.remainingTurns || 0) > 0);
  }

  function ensurePlayerBattleCarryState(player) {
    if (!player) return;
    player.items = Array.isArray(player.items) ? player.items : [];
    player.crew = Array.isArray(player.crew) ? player.crew : [];
    ensurePlayerInventoryState(player);
    player.crew.forEach((card) => ensureUniqueBattleCarryArsenalItems(player, card));
  }

  function battleCarryItemLine(item) {
    const normalized = normalizeBattleCarryItem(item);
    if (!normalized) return "攜帶物：無";
    if (normalized.id === BULLET_ARSENAL_ITEM_ID) {
      const loadout = battleCarryArsenalItems(normalized).map(battleCarryItemName);
      return `攜帶物：${battleCarryItemName(normalized)}（兵裝：${loadout.length ? loadout.join("、") : "尚未裝入"}） - ${battleCarryItemSummary(normalized)}`;
    }
    return `攜帶物：${battleCarryItemName(normalized)} - ${battleCarryItemSummary(normalized)}`;
  }

  function battleCarryLootLabel(item) {
    const normalized = normalizeBattleCarryItem(item);
    const def = battleCarryItemDef(normalized);
    return def ? `${def.name}（${def.rarity}）` : "";
  }

  function cloneBattleRewardPayload(reward) {
    const carryDrop = normalizeBattleCarryItem(reward?.battleCarryDrop);
    return {
      ...reward,
      shipRewards: Array.isArray(reward?.shipRewards)
        ? reward.shipRewards.map((entry) => ({ ...entry, quantity: Math.max(1, Math.round(Number(entry?.quantity || 1))) }))
        : [],
      battleCarryDrop: carryDrop,
      battleCarryDropName: carryDrop ? battleCarryItemName(carryDrop) : "",
      battleCarryDropLabel: carryDrop ? battleCarryLootLabel(carryDrop) : "",
    };
  }

  function cacheBattleRewardPayload(battle, rewardFactory) {
    if (!battle) return cloneBattleRewardPayload(rewardFactory());
    if (battle.resolvedRewards) return cloneBattleRewardPayload(battle.resolvedRewards);
    const reward = cloneBattleRewardPayload(rewardFactory());
    battle.resolvedRewards = reward;
    return cloneBattleRewardPayload(reward);
  }

  function battleCarryEnemyLootPool(enemyTier, isDevilFruitUser) {
    const weights = BATTLE_CARRY_DROP_STRENGTH_WEIGHTS[enemyTier] || BATTLE_CARRY_DROP_STRENGTH_WEIGHTS.T5;
    const table = BATTLE_CARRY_ENEMY_LOOT_TABLE[enemyTier] || BATTLE_CARRY_ENEMY_LOOT_TABLE.T5;
    return BATTLE_CARRY_ITEM_ORDER
      .filter((id) => id !== "seastone_bullet" || isDevilFruitUser)
      .map((id) => {
        const strength = BATTLE_CARRY_ITEM_DROP_STRENGTH[id] || "common";
        const baseWeight = Number(weights[strength] || 0);
        const seastoneBonus = id === "seastone_bullet" ? Number(table.seastoneWeight || 0) : 0;
        return { id, weight: baseWeight + seastoneBonus };
      })
      .filter((entry) => entry.weight > 0);
  }

  function rollBattleCarryEnemyLoot(battle, rand = Math.random) {
    if (!battle || battle.isJudicialRaid || battle.islandKind === "judicial") return null;
    const table = BATTLE_CARRY_ENEMY_LOOT_TABLE[battle.enemyTier] || BATTLE_CARRY_ENEMY_LOOT_TABLE.T5;
    const enemy = battle.enemyCombatant || {};
    const isDevilFruitUser = Boolean(enemy.isDevilFruitUser ?? isDevilFruitEnemyInput(enemy.key, enemy.name, enemy.role));
    const seaEncounterBonus = battle.isSeaEncounter || battle.islandKind === "sea-encounter" ? 0.1 : 0;
    const chance = Math.min(0.85, Number(table.chance || 0) + seaEncounterBonus + (isDevilFruitUser ? 0.06 : 0));
    if (rand() >= chance) return null;
    const pool = battleCarryEnemyLootPool(battle.enemyTier, isDevilFruitUser);
    if (!pool.length) return null;
    const itemId = pickWeighted(pool, rand);
    return createBattleCarryItem(itemId);
  }

  function itemDropRate(poolName, rarity, enemyTier) {
    const poolRates = ITEM_DROP_RATES[poolName] || {};
    const rarityRates = poolRates[itemRarityLabel(rarity)] || {};
    return Number(rarityRates[legacyTier(enemyTier)] ?? rarityRates.T5 ?? 0);
  }

  function rollItemFromDropPool(poolName, battle, rand = Math.random) {
    const ids = ITEM_DROP_POOLS[poolName] || [];
    if (!ids.length) return null;
    const enemyTier = legacyTier(battle?.enemyTier || battle?.enemyCombatant?.tier || "T5");
    const player = state.gameState?.players?.find((entry) => entry.id === battle?.playerId) || null;
    const battleSeaTile = battle?.seaTileId
      ? state.gameState?.boardData?.seaTiles?.find((tile) => tile.id === battle.seaTileId)
      : null;
    const dropBuff = (player?.activeMapBuffs || []).find((buff) => buff?.data?.rareDropBonus && mapBuffAppliesToSeaZone(buff, battleSeaTile?.zone || ""));
    const rareDropBonus = Math.max(0, Number(dropBuff?.data?.rareDropBonus || 0));
    const rarityOrder = poolName === "devil_fruit_user_extra_drop_pool" ? ["S", "A", "B", "C"] : ["A", "B", "C"];
    for (const rarity of rarityOrder) {
      const chance = Math.min(0.95, itemDropRate(poolName, rarity, enemyTier) + rareDropBonus);
      if (chance <= 0 || rand() >= chance) continue;
      const candidates = ids.map(gameItemDef).filter((item) => item && itemRarityLabel(item.rarity) === rarity);
      if (!candidates.length) continue;
      return candidates[Math.floor(rand() * candidates.length)];
    }
    return null;
  }

  function rollEnemyItemDrop(battle, rand = Math.random) {
    if (!battle || battle.isJudicialRaid || battle.islandKind === "judicial") return null;
    const enemy = battle.enemyCombatant || {};
    const isDevilFruitUser = Boolean(enemy.isDevilFruitUser === true || (Array.isArray(enemy.tags) && enemy.tags.includes("devil_fruit_user")));
    const drops = [];
    const common = rollItemFromDropPool("common_enemy_drop_pool", battle, rand);
    if (common) drops.push(common);
    if (isDevilFruitUser) {
      const extra = rollItemFromDropPool("devil_fruit_user_extra_drop_pool", battle, rand);
      if (extra) drops.push(extra);
    }
    if (!drops.length) return null;
    const rarityRank = { C: 1, B: 2, A: 3, S: 4 };
    return drops.sort((a, b) => (rarityRank[itemRarityLabel(b.rarity)] || 0) - (rarityRank[itemRarityLabel(a.rarity)] || 0))[0];
  }

  function grantFormalItemToPlayer(player, itemOrId, quantity = 1, options = {}) {
    const def = gameItemDef(itemOrId);
    if (!player || !def) return null;
    const requestedCount = Math.max(1, Math.round(Number(quantity || 1)));
    const count = Math.min(requestedCount, formalItemGrantCapacity(player, def));
    if (count <= 0) return null;
    if (normalizeGameItemCategory(def.category) === "held") {
      for (let index = 0; index < count; index += 1) addBattleCarryItemToBackpack(player, def.id);
    } else {
      addInventoryItem(player, def.id, count);
      if (def.id === "heal_2") player.smallSupplies = Math.max(0, Number(player.smallSupplies || 0)) + count;
      if (def.id === "battle_food") player.battleFood = Math.max(0, Number(player.battleFood || 0)) + count;
      if (def.id === "guard_charm") player.guardCharm = Math.max(0, Number(player.guardCharm || 0)) + count;
      if (def.id === "pointer") player.routeInsight = Math.max(0, Number(player.routeInsight || 0)) + count;
      if (def.id === "fixed_step") player.fixedStepTokens = Math.max(0, Number(player.fixedStepTokens || 0)) + count;
    }
    recordMissionEvent(player, { type: "obtain_item", itemId: def.id, itemName: def.name, category: normalizeGameItemCategory(def.category), amount: count }, count);
    if (options?.reveal) queueImportantItemReveal(def, count);
    return def;
  }

  function grantRandomEventPoolItem(player, poolName, rand = Math.random) {
    const pool = ITEM_EVENT_POOLS[poolName] || [];
    const baseCandidates = pool.map(gameItemDef).filter(Boolean);
    const fallbackCandidates = poolName === "basic_supply_pool" || poolName === "safe_sea_pool"
      ? []
      : (ITEM_EVENT_POOLS.basic_supply_pool || ITEM_EVENT_POOLS.safe_sea_pool || []).map(gameItemDef).filter(Boolean);
    const candidates = baseCandidates.filter((item) => itemUnlockedByBounty(player, item));
    const availableCandidates = candidates.length
      ? candidates
      : fallbackCandidates.filter((item) => itemUnlockedByBounty(player, item));
    if (!availableCandidates.length) return null;
    const rarityWeight = { C: 34, B: 16, A: 5, S: poolName === "rare_pool" ? 1 : 0.35 };
    const weighted = availableCandidates
      .map((item) => ({ id: item.id, weight: Number(rarityWeight[itemRarityLabel(item.rarity)] || 1) }))
      .filter((entry) => entry.weight > 0);
    if (!weighted.length) return null;
    const item = gameItemDef(pickWeighted(weighted, rand));
    return grantFormalItemToPlayer(player, item?.id || item, 1);
  }

