  function rollSeaEncounterShipRewardEntry(pool, filterKind, rand = Math.random) {
    const candidates = pool
      .map((entry) => ({ ...entry, item: gameItemDef(entry.id) }))
      .filter((entry) => entry.item && normalizeGameItemCategory(entry.item.category) === "ship" && entry.item.effect?.kind === filterKind);
    if (!candidates.length) return null;
    const pickedId = pickWeighted(candidates.map((entry) => ({ id: entry.id, weight: Number(entry.weight || 1) })), rand);
    const picked = candidates.find((entry) => entry.id === pickedId);
    if (!picked) return null;
    const quantityRange = Array.isArray(picked.quantity) ? picked.quantity : [picked.quantity || 1, picked.quantity || 1];
    const min = Math.max(1, Math.round(Number(quantityRange[0] || 1)));
    const max = Math.max(min, Math.round(Number(quantityRange[1] || min)));
    const quantity = min === max ? min : Math.floor(rand() * (max - min + 1)) + min;
    return {
      id: picked.item.id,
      name: picked.item.name,
      category: normalizeGameItemCategory(picked.item.category),
      rarity: itemRarityLabel(picked.item.rarity),
      quantity,
    };
  }

  function rollSeaEncounterShipRewards(battle, rand = Math.random) {
    const tier = legacyTier(battle?.enemyTier || battle?.enemyCombatant?.tier || "T5");
    const materialPool = SEA_ENCOUNTER_SHIP_MATERIAL_POOL[tier] || SEA_ENCOUNTER_SHIP_MATERIAL_POOL.T5;
    const gearPool = SEA_ENCOUNTER_SHIP_EQUIPMENT_POOL[tier] || SEA_ENCOUNTER_SHIP_EQUIPMENT_POOL.T5;
    const rewards = [rollSeaEncounterShipRewardEntry(materialPool, "ship_material", rand)].filter(Boolean);
    const gearChance = Number(SEA_ENCOUNTER_SHIP_EQUIPMENT_CHANCE[tier] || SEA_ENCOUNTER_SHIP_EQUIPMENT_CHANCE.T5);
    if (rand() <= gearChance) {
      const gearReward = rollSeaEncounterShipRewardEntry(gearPool, "ship_equipment", rand);
      if (gearReward) rewards.push(gearReward);
    }
    return rewards;
  }

  function shipRewardSummaryText(rewards) {
    return (rewards || []).map((entry) => {
      const item = gameItemDef(entry.id);
      const quantity = Math.max(1, Math.round(Number(entry.quantity || 1)));
      return `${item?.name || entry.name || entry.id} x${quantity}`;
    }).join("、");
  }

  function addBattleCarryEnemyLootToReward(battle, reward) {
    const itemDrop = rollEnemyItemDrop(battle);
    if (itemDrop) {
      const categoryLabel = ITEM_CATEGORY_LABELS[normalizeGameItemCategory(itemDrop.category)] || "道具";
      const label = `${itemDrop.name}（${itemDrop.rarity}）`;
      const carryDrop = normalizeGameItemCategory(itemDrop.category) === "held" ? createBattleCarryItem(itemDrop.id) : null;
      return {
        ...reward,
        item: "",
        itemDrop: { id: itemDrop.id, name: itemDrop.name, category: itemDrop.category, rarity: itemDrop.rarity },
        battleCarryDrop: carryDrop,
        battleCarryDropName: carryDrop ? battleCarryItemName(carryDrop) : "",
        battleCarryDropLabel: carryDrop ? battleCarryLootLabel(carryDrop) : "",
        itemText: `${categoryLabel}：${label}`,
        summary: `${reward.summary}，並獲得${categoryLabel}：${label}`,
      };
    }
    return {
      ...reward,
      item: "",
      itemText: "無道具",
    };
  }

