    if (gridCoordinates.some((entry) => entry.row === 1)) return ["north_yonko"];
    if (gridCoordinates.some((entry) => entry.row === 7)) return ["south_yonko"];
    if (from && to && from.row === to.row && Math.abs(from.columnIndex - to.columnIndex) === 1) {
      const left = from.columnIndex < to.columnIndex ? from : to;
      const right = left === from ? to : from;
      const leftLetter = String.fromCharCode(97 + left.columnIndex);
      const rightLetter = String.fromCharCode(97 + right.columnIndex);
      return uniqueRegionalSpawnIds([
        `route_${leftLetter}`,
        `route_${leftLetter}_east`,
        `route_${rightLetter}_west`,
        `route_${rightLetter}`,
      ]);
    }
    return uniqueRegionalSpawnIds(gridCoordinates.flatMap((entry) => regionalSpawnIdsForColumn(entry.columnIndex)));
