  function impelDownPrisonerLateMoves(prisoner) {
    const realNames = IMPEL_DOWN_REAL_LATE_MOVE_NAMES[prisoner.id] || (prisoner.moves || []).map((entry) => entry.name).filter(Boolean);
    return impelDownPrisonerLateBlueprints(prisoner.roleType).map((blueprint, index) => {
      const [slug, suffix, type, pp, power, effectText, effects = {}, extra = {}] = blueprint;
      return enemyMove(
        `${prisoner.id}_late_${slug}`,
        realNames[index] || realNames[index % Math.max(1, realNames.length)] || `${prisoner.name}・${suffix}`,
        type,
        pp,
        power,
        effectText,
        effects,
        { ...extra, unlockLevel: IMPEL_DOWN_LATE_MOVE_LEVELS[index], attribute: prisoner.attribute },
      );
    });
  }

  IMPEL_DOWN_PRISONERS.forEach((prisoner) => {
    prisoner.unlockLevel = IMPEL_DOWN_PRISONER_UNLOCK_LEVELS[prisoner.id] || 6;
    prisoner.image = IMPEL_DOWN_PRISONER_IMAGES[prisoner.id] || `images/board/battle/portraits/${prisoner.id}/normal.webp`;
    const existingMoveIds = new Set((prisoner.moves || []).map((entry) => entry.id));
    impelDownPrisonerLateMoves(prisoner).forEach((moveEntry) => {
      if (!existingMoveIds.has(moveEntry.id)) prisoner.moves.push(moveEntry);
    });
  });
  const IMPEL_DOWN_PRISONER_ENEMY_KEY_BY_ID = Object.fromEntries(
    IMPEL_DOWN_PRISONERS.map((prisoner) => [prisoner.id, prisoner.enemyKey]).filter((entry) => entry[1])
  );

  function prisonerCrewEnemyKeys(game = state.gameState) {
    const blocked = new Set();
    (game?.players || []).forEach((player) => {
      (player?.crew || []).forEach((card) => {
        const enemyKey = IMPEL_DOWN_PRISONER_ENEMY_KEY_BY_ID[card?.id];
        if (enemyKey) blocked.add(String(enemyKey));
      });
    });
    return blocked;
  }

  function enemyBlockedByPrisonerCrew(enemyKey, game = state.gameState) {
    return prisonerCrewEnemyKeys(game).has(String(enemyKey || ""));
  }

