  function gameItemShopCost(item) {
    if (Number(item?.price || 0) > 0) return Number(item.price);
    const rarityBase = { C: 120, B: 320, A: 720, S: 0 }[itemRarityLabel(item?.rarity)] || 120;
    const categoryMod = { navigation: 1, battle: 1.05, ship: 1.2, held: 1.35, key: 1.1 }[normalizeGameItemCategory(item?.category)] || 1;
    return Math.max(1, Math.round(rarityBase * categoryMod));
  }

  const TRADE_NON_TRADABLE_ITEM_IDS = new Set(["road_poneglyph", ...ROAD_PONEGLYPH_ITEM_IDS]);

  function tradeRarityLabel(item) {
    const raw = String(item?.rarity || "").trim();
    const normalized = itemRarityLabel(raw);
    if (/[sS]|傳說|夢幻|四皇|最高/.test(raw)) return "S";
    if (/[aA]|高級|史詩|稀有/.test(raw)) return "A";
    if (/[bB]|進階|優良/.test(raw)) return "B";
    return normalized;
  }

  function tradeItemCategory(itemOrId) {
    const item = gameItemDef(itemOrId) || battleCarryItemDef(itemOrId) || itemOrId;
    if (!item) return "";
    if (battleCarryItemDef(item.id)) return "held";
    return normalizeGameItemCategory(item.category);
  }

  function tradeMinimumPriceForItem(itemOrId) {
    const item = gameItemDef(itemOrId) || battleCarryItemDef(itemOrId) || itemOrId;
    if (!item) return 0;
    const explicit = Number(item.tradeMinPrice || item.minTradePrice || item.tradeFloor || 0);
    if (explicit > 0) return Math.max(1, Math.round(explicit));
    const rarity = tradeRarityLabel(item);
    const category = tradeItemCategory(item);
    const rarityFloor = { C: 80, B: 220, A: 520, S: 1200 }[rarity] || 80;
    const categoryMod = { navigation: 1, battle: 1.08, ship: 1.18, held: 1.3, key: 1.6 }[category] || 1;
    const shopFloor = Math.ceil(gameItemShopCost(item) * 0.5);
    return Math.max(10, Math.ceil(Math.max(rarityFloor * categoryMod, shopFloor) / 10) * 10);
  }

  function isTradableItemDef(itemOrId) {
    const item = gameItemDef(itemOrId) || battleCarryItemDef(itemOrId) || itemOrId;
    if (!item?.id) return false;
    if (TRADE_NON_TRADABLE_ITEM_IDS.has(item.id)) return false;
    if (item.uniqueQuestItem || item.noTrade || item.tradable === false) return false;
    if (item.tradable !== true && item.important) return false;
    if (item.tradable !== true && tradeItemCategory(item) === "key") return false;
    return tradeMinimumPriceForItem(item) > 0;
  }

  function equippedShipGearCount(player, itemId) {
    if (!player || !itemId) return 0;
    const view = getWaterSevenView(player);
    return (view?.equippedShipGear || []).filter((id) => id === itemId).length;
  }

  function tradeableInventoryEntries(player) {
    if (!player) return [];
    const inventory = ensurePlayerInventoryState(player);
    const entries = [];
    Object.entries(inventory.items || {}).forEach(([id, rawCount]) => {
      const item = gameItemDef(id);
      if (!item || !isTradableItemDef(item)) return;
      if (normalizeGameItemCategory(item.category) === "held") return;
      const count = Math.max(0, Math.round(Number(rawCount || 0))) - equippedShipGearCount(player, item.id);
      if (count <= 0) return;
      entries.push({
        id: item.id,
        item,
        name: item.name,
        category: tradeItemCategory(item),
        rarity: tradeRarityLabel(item),
        count,
        source: "formal",
        minimumPrice: tradeMinimumPriceForItem(item),
      });
    });
    const carryGroups = new Map();
    battleCarryInventoryEntries(player).forEach(({ item }) => {
      const def = battleCarryItemDef(item);
      if (!def || !isTradableItemDef(def)) return;
      const row = carryGroups.get(def.id) || {
        id: def.id,
        item: def,
        name: def.name,
        category: "held",
        rarity: tradeRarityLabel(def),
        count: 0,
        source: "held",
        minimumPrice: tradeMinimumPriceForItem(def),
      };
      row.count += 1;
      carryGroups.set(def.id, row);
    });
    entries.push(...carryGroups.values());
    const categoryRank = { battle: 0, navigation: 1, held: 2, ship: 3 };
    const rarityRank = { C: 0, B: 1, A: 2, S: 3 };
    return entries.sort((a, b) => {
      const categoryDelta = (categoryRank[a.category] ?? 9) - (categoryRank[b.category] ?? 9);
      if (categoryDelta) return categoryDelta;
      const rarityDelta = (rarityRank[b.rarity] ?? 0) - (rarityRank[a.rarity] ?? 0);
      if (rarityDelta) return rarityDelta;
      return String(a.name).localeCompare(String(b.name), "zh-Hant");
    });
  }

  function playersOnSameSeaTile(player) {
    if (!player || player.location?.kind !== "route") return [];
    return (state.gameState.players || []).filter((other) => (
      other?.id !== player.id
      && other.location?.kind === "route"
      && other.location.routeId === player.location.routeId
      && Number(other.location.tileIndex) === Number(player.location.tileIndex)
    ));
  }

  function canPlayerParticipateInSeaTrade(player) {
    return !!player
      && !isCpuPlayer(player)
      && player.location?.kind === "route"
      && !isPlayerInBattleOnMap(player);
  }

  function tradeablePlayersOnSameSeaTile(player) {
    return playersOnSameSeaTile(player).filter((other) => canPlayerParticipateInSeaTrade(other));
  }

  function activeSeaTradePromptForPlayer(player) {
    const prompt = state.gameState?.tradePrompt;
    if (!prompt || !player || String(prompt.playerId) !== String(player.id)) return null;
    if (player.location?.kind !== "route") return null;
    if (String(prompt.routeId) !== String(player.location.routeId)) return null;
    if (Number(prompt.tileIndex) !== Number(player.location.tileIndex)) return null;
    return prompt;
  }

  function playerTradeContext(player) {
    if (!player) return { ok: false, reason: "找不到目前玩家。", partners: [] };
    if (player.location?.kind !== "route") return { ok: false, reason: "交易只能在海格進行，島嶼上不能交易。", partners: [] };
    const prompt = activeSeaTradePromptForPlayer(player);
    if (!prompt) return { ok: false, reason: "只有後來踩上同一海格的玩家可以選擇交易。", partners: [] };
    if (isGameActionLocked() && !state.gameState?.tradePrompt) return { ok: false, reason: "目前流程尚未結束，不能交易。", partners: [] };
    const allowedIds = new Set((prompt.partnerIds || []).map((id) => String(id)));
    const partners = tradeablePlayersOnSameSeaTile(player).filter((entry) => allowedIds.has(String(entry.id)));
    if (!partners.length) return { ok: false, reason: "同一個海格上沒有可交易的玩家，戰鬥中的玩家不能交易。", partners: [] };
    return { ok: true, reason: "", partners };
  }

  function removeBattleCarryItemForTrade(player, itemId) {
    const def = battleCarryItemDef(itemId);
    if (!player || !def) return false;
    const index = (player.items || []).findIndex((item) => normalizeBattleCarryItem(item)?.id === def.id);
    if (index < 0) return false;
    player.items.splice(index, 1);
    if (inventoryItemCount(player, def.id) > 0) removeInventoryItem(player, def.id, 1);
    return true;
  }

  function transferTradeItemBetweenPlayers(seller, buyer, itemId, quantity, options = {}) {
    const item = gameItemDef(itemId) || battleCarryItemDef(itemId);
    const count = Math.max(1, Math.round(Number(quantity || 1)));
    if (!seller || !buyer || !item || !isTradableItemDef(item)) return { ok: false, reason: "這個道具不能交易。" };
    const category = tradeItemCategory(item);
    if (category === "held") {
      if (countBattleCarryItemsInBackpack(seller, item.id) < count) return { ok: false, reason: "可交易的未裝備攜帶物數量不足。" };
      for (let index = 0; index < count; index += 1) {
        if (!removeBattleCarryItemForTrade(seller, item.id)) return { ok: false, reason: "移除攜帶物失敗。" };
        addBattleCarryItemToBackpack(buyer, item.id);
      }
      return { ok: true, item, count };
    }
    const available = Math.max(0, inventoryItemCount(seller, item.id) - equippedShipGearCount(seller, item.id));
    if (available < count) return { ok: false, reason: "可交易數量不足。" };
    const maxStack = formalItemMaxStack(item);
    if (!options.skipCapacityCheck && maxStack > 0 && inventoryItemCount(buyer, item.id) + count > maxStack) {
      return { ok: false, reason: `${buyer.name} 的 ${item.name} 會超過持有上限 ${maxStack} 個。` };
    }
    if (!removeFormalItemFromPlayer(seller, item.id, count)) return { ok: false, reason: "移除道具失敗。" };
    addInventoryItem(buyer, item.id, count);
    adjustLegacyItemCount(buyer, item.id, count);
    return { ok: true, item, count };
  }

  function executePlayerTrade(seller, buyer, itemId, quantity, unitPrice) {
    const item = gameItemDef(itemId) || battleCarryItemDef(itemId);
    const count = Math.max(1, Math.round(Number(quantity || 1)));
    const price = Math.max(0, Math.round(Number(unitPrice || 0)));
    if (!seller || !buyer || !item) return { ok: false, reason: "交易資料不完整。" };
    const context = playerTradeContext(seller);
    if (!context.ok || !context.partners.some((player) => player.id === buyer.id)) return { ok: false, reason: context.reason || "雙方不在同一海格。" };
    const minimum = tradeMinimumPriceForItem(item);
    if (price < minimum) return { ok: false, reason: `成交單價不能低於底價 ${formatCoin(minimum)} 貝里。` };
    const total = price * count;
    if (Number(buyer.coins || 0) < total) return { ok: false, reason: `${buyer.name} 貝里不足。` };
    const transfer = transferTradeItemBetweenPlayers(seller, buyer, item.id, count);
    if (!transfer.ok) return transfer;
    buyer.coins = Math.max(0, Math.round(Number(buyer.coins || 0)) - total);
    seller.coins = Math.max(0, Math.round(Number(seller.coins || 0)) + total);
    addLog(`${seller.name} 以 ${formatCoin(total)} 貝里將 ${item.name} x${count} 交易給 ${buyer.name}。`);
    recordMissionEvent(seller, { type: "player_trade_sell", itemId: item.id, itemName: item.name, category: tradeItemCategory(item), amount: count, berries: total }, count);
    recordMissionEvent(buyer, { type: "player_trade_buy", itemId: item.id, itemName: item.name, category: tradeItemCategory(item), amount: count, berries: total }, count);
    return { ok: true, item, count, total };
  }

  function shopItemFromGameItem(itemId) {
    const item = gameItemDef(itemId);
    if (!item) return null;
    return {
      id: item.id,
      name: item.name,
      cost: gameItemShopCost(item),
      type: normalizeGameItemCategory(item.category),
      category: normalizeGameItemCategory(item.category),
      rarity: item.rarity,
      unlockBounty: 0,
      image: item.image || "",
      desc: `${item.uiSummary || item.description || ""}${normalizeGameItemCategory(item.category) === "key" ? keyItemDetailText(item) : ""}`.trim(),
    };
  }

