  const POSTGAME_BULLET_SLOT_LABELS = Object.freeze(["頭", "胸", "左手", "右手", "左腳", "右腳"]);
  const POSTGAME_LUCCI_POWER_MULTIPLIER = 1.8;
  const POSTGAME_LUCCI_SIX_POWER_DEFS = Object.freeze([
    Object.freeze({ id: "soru", name: "剃", stat: "spd", statLabel: "速度", image: "images/board/battle/postgame_mechanics/lucci_six_powers/soru.webp" }),
    Object.freeze({ id: "tekkai", name: "鐵塊", stat: "def", statLabel: "防禦", image: "images/board/battle/postgame_mechanics/lucci_six_powers/tekkai.webp" }),
    Object.freeze({ id: "kamie", name: "紙繪", stat: "evasion", statLabel: "閃避", image: "images/board/battle/postgame_mechanics/lucci_six_powers/kamie.webp" }),
    Object.freeze({ id: "geppo", name: "月步", stat: "sdef", statLabel: "特防", image: "images/board/battle/postgame_mechanics/lucci_six_powers/geppo.webp" }),
    Object.freeze({ id: "shigan", name: "指槍", stat: "atk", statLabel: "攻擊", image: "images/board/battle/postgame_mechanics/lucci_six_powers/shigan.webp" }),
    Object.freeze({ id: "rankyaku", name: "嵐腳", stat: "satk", statLabel: "特攻", image: "images/board/battle/postgame_mechanics/lucci_six_powers/rankyaku.webp" }),
  ]);
  const POSTGAME_LUCCI_SIX_POWERS = Object.freeze(POSTGAME_LUCCI_SIX_POWER_DEFS.map((entry) => entry.name));
  const POSTGAME_OARS_SALT_TARGET = 15;

  function postgameBossMechanicFor(battle = state.battleState) {
    if (!battle?.isPostgameBoss && battle?.islandKind !== "postgame_boss") return null;
    return battle.postgameBossMechanic && typeof battle.postgameBossMechanic === "object"
      ? battle.postgameBossMechanic
      : null;
  }

  function postgameOarsLotteryOutcomes(player, battle) {
    const firstMax = Math.max(1, 6 - Math.max(0, Number(battle?.playerRoundEffects?.diceCapDown || 0)));
    const extraRule = extraBattleDiceRule("player", player, battle);
    const firstThreshold = Math.max(0, Number(extraRule?.threshold || 0));
    const thirdThreshold = firstThreshold ? rocksEclipseThirdDiceThreshold("player", player, battle, firstThreshold) : 0;
    const outcomes = [];
    for (let first = 1; first <= firstMax; first += 1) {
      const firstProbability = 1 / firstMax;
      if (!firstThreshold || first < firstThreshold) {
        outcomes.push({ dice: [first], total: first, probability: firstProbability });
        continue;
      }
      for (let second = 1; second <= 6; second += 1) {
        const secondProbability = firstProbability / 6;
        if (!thirdThreshold || second < thirdThreshold) {
          outcomes.push({ dice: [first, second], total: first + second, probability: secondProbability });
          continue;
        }
        for (let third = 1; third <= 6; third += 1) {
          outcomes.push({ dice: [first, second, third], total: first + second + third, probability: secondProbability / 6 });
        }
      }
    }
    return { outcomes, firstMax, firstThreshold, thirdThreshold };
  }

  function postgameOarsActionKey(player, battle) {
    return `${Math.max(1, Number(battle?.roundIndex || 1))}:${String(player?.id || battle?.playerId || "player")}`;
  }

  function postgameOarsLotteryOptions(player, battle) {
    const { outcomes, firstMax, firstThreshold, thirdThreshold } = postgameOarsLotteryOutcomes(player, battle);
    const probabilityFor = (predicate) => outcomes.reduce((sum, outcome) => sum + (predicate(outcome) ? outcome.probability : 0), 0);
    const payoutFor = (probability, fixed = 0) => fixed || Math.max(2, Math.min(15, Math.round(1 / Math.max(0.0001, probability))));
    const options = [];
    const add = (id, group, label, predicate, fixed = 0, detail = "") => {
      const probability = probabilityFor(predicate);
      if (probability <= 0) return;
      options.push({ id, group, label, payout: payoutFor(probability, fixed), probability, detail });
    };
    add("first_small", "第一骰大小", "小（1～3）", (outcome) => outcome.dice[0] <= 3, 2);
    add("first_big", "第一骰大小", "大（4～6）", (outcome) => outcome.dice[0] >= 4, 2);
    for (let face = 1; face <= firstMax; face += 1) {
      add(`first_exact_${face}`, "第一骰點數", `第一骰 ${face} 點`, (outcome) => outcome.dice[0] === face, 6);
    }
    if (firstThreshold) {
      add("second_yes", "第二骰", "會出現第二顆骰", (outcome) => outcome.dice.length >= 2, 0, `第一骰達 ${firstThreshold}+`);
      add("second_no", "第二骰", "不會出現第二顆骰", (outcome) => outcome.dice.length < 2);
      for (let face = 1; face <= 6; face += 1) {
        add(`second_exact_${face}`, "第二骰點數", `第二骰 ${face} 點`, (outcome) => outcome.dice[1] === face);
      }
    }
    if (thirdThreshold) {
      add("third_yes", "第三骰", "會出現第三顆骰", (outcome) => outcome.dice.length >= 3, 0, `第二骰達 ${thirdThreshold}+`);
      add("third_no", "第三骰", "不會出現第三顆骰", (outcome) => outcome.dice.length < 3);
      for (let face = 1; face <= 6; face += 1) {
        add(`third_exact_${face}`, "第三骰點數", `第三骰 ${face} 點`, (outcome) => outcome.dice[2] === face);
      }
    }
    const totals = [...new Set(outcomes.map((outcome) => outcome.total))].sort((a, b) => a - b);
    totals.forEach((total) => add(`total_exact_${total}`, "最終總點數", `總點數 ${total}`, (outcome) => outcome.total === total));
    return options;
  }

  function postgameOarsPredictionMatches(optionId, dice, total) {
    const first = Number(dice?.[0] || 0);
    const second = Number(dice?.[1] || 0);
    const third = Number(dice?.[2] || 0);
    if (optionId === "first_small") return first >= 1 && first <= 3;
    if (optionId === "first_big") return first >= 4 && first <= 6;
    if (optionId === "second_yes") return dice.length >= 2;
    if (optionId === "second_no") return dice.length < 2;
    if (optionId === "third_yes") return dice.length >= 3;
    if (optionId === "third_no") return dice.length < 3;
    if (optionId.startsWith("first_exact_")) return first === Number(optionId.slice(12));
    if (optionId.startsWith("second_exact_")) return second === Number(optionId.slice(13));
    if (optionId.startsWith("third_exact_")) return third === Number(optionId.slice(12));
    if (optionId.startsWith("total_exact_")) return Number(total || 0) === Number(optionId.slice(12));
    return false;
  }

  function normalizePostgameOarsBetRequests(input) {
    const source = Array.isArray(input)
      ? input
      : Array.isArray(input?.bets)
        ? input.bets
        : input == null ? [] : [input];
    const merged = new Map();
    source.forEach((entry) => {
      const optionId = String(typeof entry === "string" ? entry : entry?.optionId || entry?.id || "").trim();
      const stake = Math.floor(Number(typeof entry === "string" ? 1 : entry?.stake ?? 1));
      if (!optionId || !Number.isFinite(stake) || stake <= 0) return;
      merged.set(optionId, (merged.get(optionId) || 0) + stake);
    });
    return [...merged.entries()].map(([optionId, stake]) => ({ optionId, stake }));
  }

  function lockPostgameOarsPredictions(betRequests) {
    const battle = state.battleState;
    const mechanic = postgameBossMechanicFor(battle);
    if (!battle || mechanic?.key !== "postgame_oars" || battle.animating || battle.result || mechanic.saltBags >= POSTGAME_OARS_SALT_TARGET || mechanic.lockedPredictions?.length) return false;
    const player = isCoopBattle(battle) ? battleCommandPlayer(battle) : battlePlayer(null, battle);
    if (!player || (isCoopBattle(battle) ? warnBoardLanBattleLocked(player, battle) : warnBoardLanTurnLocked(player))) return false;
    const requested = normalizePostgameOarsBetRequests(betRequests);
    const available = Math.max(0, Math.floor(Number(mechanic.saltBags || 0)));
    const stakeTotal = requested.reduce((sum, entry) => sum + entry.stake, 0);
    if (!requested.length || stakeTotal <= 0 || stakeTotal > available) return false;
    const optionMap = new Map(postgameOarsLotteryOptions(player, battle).map((entry) => [entry.id, entry]));
    const selected = requested.map((request) => ({ option: optionMap.get(request.optionId), stake: request.stake }));
    if (selected.some((entry) => !entry.option)) return false;
    const saltBefore = available;
    mechanic.saltBags = Math.max(0, saltBefore - stakeTotal);
    mechanic.lockedSaltBefore = saltBefore;
    mechanic.lockedPredictions = selected.map(({ option, stake }) => ({
      id: option.id,
      label: option.label,
      group: option.group,
      payout: option.payout,
      stake,
      playerId: String(player.id || ""),
      roundIndex: Math.max(1, Number(battle.roundIndex || 1)),
    }));
    mechanic.lastResult = null;
    battle.log.push(`${player.name} 投入 ${stakeTotal} 包鹽袋：${selected.map(({ option, stake }) => `${option.label}押 ${stake} 包（×${option.payout}）`).join("、")}；剩餘 ${mechanic.saltBags} 包。`);
    notifyBattleWindow();
    renderBattleInterface();
    scheduleBattleLanStatePush("oars-prediction", 40);
    return true;
  }

  function settlePostgameOarsPrediction(player, battle, dice, total) {
    const mechanic = postgameBossMechanicFor(battle);
    const bets = mechanic?.key === "postgame_oars" && Array.isArray(mechanic.lockedPredictions) ? mechanic.lockedPredictions : [];
    if (!bets.length) return null;
    const beforePayout = Math.max(0, Number(mechanic.saltBags || 0));
    const results = bets.map((bet) => ({
      ...safeJsonClone(bet),
      won: postgameOarsPredictionMatches(bet.id, dice, total),
    }));
    const stakeTotal = results.reduce((sum, bet) => sum + Math.max(0, Number(bet.stake ?? 1)), 0);
    const wonBets = results.filter((bet) => bet.won);
    const payoutTotal = wonBets.reduce((sum, bet) => sum + Math.max(0, Number(bet.stake ?? 1)) * Math.max(1, Number(bet.payout || 1)), 0);
    mechanic.saltBags = Math.min(POSTGAME_OARS_SALT_TARGET, beforePayout + payoutTotal);
    const gained = Math.max(0, mechanic.saltBags - beforePayout);
    mechanic.lastResult = {
      bets: results,
      won: wonBets.length > 0,
      wonCount: wonBets.length,
      lostCount: results.length - wonBets.length,
      stake: stakeTotal,
      gained,
      payoutTotal,
      dice: Array.isArray(dice) ? dice.slice(0, 3).map(Number) : [],
      total: Number(total || 0),
      saltBefore: Math.max(beforePayout + stakeTotal, Number(mechanic.lockedSaltBefore || 0)),
      saltAfterStake: beforePayout,
      saltAfter: mechanic.saltBags,
    };
    mechanic.lockedPredictions = [];
    mechanic.lockedSaltBefore = 0;
    mechanic.predictionResolvedRound = Math.max(1, Number(battle.roundIndex || 1));
    mechanic.predictionResolvedKey = postgameOarsActionKey(player, battle);
    if (beforePayout < POSTGAME_OARS_SALT_TARGET && mechanic.saltBags >= POSTGAME_OARS_SALT_TARGET) {
      mechanic.purificationInterruptPending = true;
      battle.log.push("十五袋巨型鹽已集齊；歐斯的下一次行動中止，現在可施放巨型鹽彈。");
    }
    battle.log.push(`鹽袋下注結算：${results.map((bet) => `${bet.label}押 ${Math.max(0, Number(bet.stake ?? 1))} 包${bet.won ? `命中 ×${bet.payout}` : "落空"}`).join("、")}；本次骰鏈 ${(dice || []).join(" + ")} = ${total}，回收 ${gained} 包，目前 ${mechanic.saltBags}/${POSTGAME_OARS_SALT_TARGET}。`);
    return mechanic.lastResult;
  }

  function voidPostgameOarsPrediction(battle, reason = "本次行動不擲戰鬥骰") {
    const mechanic = postgameBossMechanicFor(battle);
    const bets = mechanic?.key === "postgame_oars" && Array.isArray(mechanic.lockedPredictions) ? mechanic.lockedPredictions : [];
    if (!bets.length) return false;
    const refund = bets.reduce((sum, bet) => sum + Math.max(0, Number(bet.stake ?? 1)), 0);
    mechanic.saltBags = Math.min(POSTGAME_OARS_SALT_TARGET, Number(mechanic.saltBags || 0) + refund);
    battle.log.push(`鹽袋下注取消：${reason}，退回 ${refund} 包鹽袋。`);
    mechanic.lastResult = { bets: safeJsonClone(bets), won: false, voided: true, gained: 0, refunded: refund, stake: refund, saltAfter: mechanic.saltBags };
    mechanic.lockedPredictions = [];
    mechanic.lockedSaltBefore = 0;
    mechanic.predictionResolvedRound = Math.max(1, Number(battle.roundIndex || 1));
    const currentPlayer = isCoopBattle(battle) ? battleCommandPlayer(battle) : battlePlayer(null, battle);
    mechanic.predictionResolvedKey = postgameOarsActionKey(currentPlayer, battle);
    return true;
  }

  function purifyPostgameOars() {
    const battle = state.battleState;
    const mechanic = postgameBossMechanicFor(battle);
    if (!battle || mechanic?.key !== "postgame_oars" || battle.result || mechanic.purified || Number(mechanic.saltBags || 0) < POSTGAME_OARS_SALT_TARGET) return false;
    const player = isCoopBattle(battle) ? battleCommandPlayer(battle) : battlePlayer(null, battle);
    if (!player || (isCoopBattle(battle) ? warnBoardLanBattleLocked(player, battle) : warnBoardLanTurnLocked(player))) return false;
    const purificationDamage = Math.max(1, Number(battle.enemyCombatant?.currentHp || battle.enemyCombatant?.maxHp || 1));
    mechanic.saltBags = 0;
    mechanic.purified = true;
    mechanic.lockedPredictions = [];
    mechanic.lockedSaltBefore = 0;
    mechanic.purificationInterruptPending = false;
    battle.enemyCombatant.currentHp = 0;
    battle.playerPerformedAction = true;
    battle.roundResolved = true;
    battle.result = "win";
    battle.log.push(`${player.name} 將十五袋巨型鹽壓成「巨型鹽彈・影子解放」；歐斯的影子被一擊淨化。`);
    battle.visualEvent = attachBattleVisualEventSnapshots({
      id: `postgame-oars-purify-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      type: "postgame-oars-purify",
      side: "player",
      targetSide: "enemy",
      actorName: battleActiveCard(player, battle)?.name || player.name,
      targetName: battle.enemyCombatant?.name || "魔人歐斯",
      title: "巨型鹽彈・影子解放",
      moveType: "special",
      damage: purificationDamage,
      effectFx: { kind: "salt_purification", direction: "right", label: "影子解放", targetSide: "enemy" },
      duration: 3200,
    }, battle);
    ensureLineageExtractionOpportunity(battle);
    notifyBattleWindow();
    renderBattleInterface();
    scheduleBattleLanStatePush("oars-purified", 40);
    return true;
  }

  function postgameLucciSixPowerDef(value) {
    const token = String(value?.id || value?.name || value || "").trim();
    return POSTGAME_LUCCI_SIX_POWER_DEFS.find((entry) => entry.id === token || entry.name === token || entry.stat === token) || null;
  }

  function postgameBossMechanicActiveLucciPower(battle = state.battleState) {
    const mechanic = postgameBossMechanicFor(battle);
    if (mechanic?.key !== "postgame_rob_lucci_awakened") return null;
    if (Number(mechanic.activePowerRound || 0) !== Number(battle?.roundIndex || 0)) return null;
    return postgameLucciSixPowerDef(mechanic.activePowerId || mechanic.activePower || mechanic.activePowerStat);
  }

  function postgameBossMechanicPrepareLucciPowerForAction(battle = state.battleState) {
    const mechanic = postgameBossMechanicFor(battle);
    if (mechanic?.key !== "postgame_rob_lucci_awakened" || mechanic.rokuoganPending) return null;
    const roundIndex = Math.max(1, Number(battle?.roundIndex || 1));
    if (Number(mechanic.activePowerRound || 0) === roundIndex) return postgameBossMechanicActiveLucciPower(battle);
    const used = new Set((Array.isArray(mechanic.nodes) ? mechanic.nodes : []).filter((name) => POSTGAME_LUCCI_SIX_POWERS.includes(name)));
    const available = POSTGAME_LUCCI_SIX_POWER_DEFS.filter((entry) => !used.has(entry.name));
    if (!available.length) {
      mechanic.rokuoganPending = true;
      mechanic.activePower = "";
      mechanic.activePowerId = "";
      mechanic.activePowerStat = "";
      mechanic.activePowerRound = 0;
      return null;
    }
    const selected = available[Math.floor(Math.random() * available.length)] || available[0];
    mechanic.nodes.push(selected.name);
    mechanic.activePower = selected.name;
    mechanic.activePowerId = selected.id;
    mechanic.activePowerStat = selected.stat;
    mechanic.activePowerRound = roundIndex;
    mechanic.rokuoganPending = mechanic.nodes.length >= POSTGAME_LUCCI_SIX_POWER_DEFS.length;
    battle.openingPassiveVisualQueue = Array.isArray(battle.openingPassiveVisualQueue) ? battle.openingPassiveVisualQueue : [];
    battle.openingPassiveVisualPlayed = battle.openingPassiveVisualPlayed && typeof battle.openingPassiveVisualPlayed === "object"
      ? battle.openingPassiveVisualPlayed
      : {};
    const visualKey = `postgame-lucci-six-power:${battle.islandId || battle.postgameBossKey || "battle"}:${roundIndex}`;
    if (!battle.openingPassiveVisualPlayed[visualKey] && !battle.openingPassiveVisualQueue.some((event) => event.key === visualKey)) {
      battle.openingPassiveVisualQueue.push({
        id: `postgame-lucci-six-power-${roundIndex}-${Date.now()}-${Math.random().toString(36).slice(2)}`,
        key: visualKey,
        type: "postgame-lucci-six-power",
        side: "enemy",
        actorName: battle.enemyCombatant?.name || "覺醒羅布・路基",
        powerId: selected.id,
        powerName: selected.name,
        stat: selected.stat,
        statLabel: selected.statLabel,
        image: selected.image,
        effectText: `${selected.statLabel}提高 80%`,
        targetSide: "enemy",
        moveType: "buff",
        duration: 2500,
      });
    }
    battle.log.push(`路基行動前隨機使用六式「${selected.name}」；本次行動${selected.statLabel}提高 80%（${mechanic.nodes.length}/6）。`);
    if (mechanic.rokuoganPending) battle.log.push("六式已全部使用；路基下一次行動將使出必中覺醒・六王銃。");
    return selected;
  }

  function postgameBossMechanicCrewKey(card, index = 0) {
    return String(card?.id || card?.key || `crew-${Math.max(0, Number(index || 0))}`);
  }

  function postgameBossMechanicDirectMove(moveEntry) {
    return !!moveEntry && ["attack", "special"].includes(moveEntry.category || moveEntry.type) && Number(moveEntry.power || 0) > 0;
  }

  function postgameBossMechanicAddEnemyMove(battle, moveEntry) {
    if (!battle?.enemyCombatant || !moveEntry?.id) return null;
    const existing = (battle.enemyCombatant.moveSet || []).find((entry) => entry.id === moveEntry.id);
    if (existing) return existing;
    const created = createEnemyMoveSet({
      key: battle.enemyCombatant.key,
      attribute: battle.enemyCombatant.attribute,
      moves: [moveEntry],
    })[0];
    battle.enemyCombatant.moveSet.push(created);
    return created;
  }

  function postgameTesoroPhaseMoves(phase) {
    if (Number(phase || 1) === 2) {
      return [
        enemyMove("postgame_tesoro_golden_inferno", "黃金業火", "attack", 8, 286, "Golden Tesoro 的巨拳轟擊", {}, { attribute: "力", accuracy: 96 }),
        enemyMove("postgame_tesoro_golden_divine_fire", "黃金神火", "special", 7, 272, "巨人掌心凝聚黃金熱線", {}, { attribute: "技", accuracy: 96 }),
        enemyMove("postgame_tesoro_golden_press", "黃金帝壓", "attack", 8, 258, "巨體正面壓制；命中使金流淹沒一段", { enemyStagesOnHit: { def: -1 } }, { attribute: "力", accuracy: 98 }),
        enemyMove("postgame_tesoro_gold_wrath", "黃金神之怒", "special", 4, 338, "Golden Tesoro 的必中黃金終結技", {}, { attribute: "技", accuracy: 100 }),
      ];
    }
    return [];
  }

  function postgameTesoroApplyPhaseLoadout(battle, mechanic) {
    if (!battle?.enemyCombatant || mechanic?.key !== "postgame_gild_tesoro") return;
    const phase = Math.max(1, Math.min(2, Number(mechanic.phase || 1)));
    if (phase === 1) {
      mechanic.moveSetPhase = 1;
      return;
    }
    const defs = postgameTesoroPhaseMoves(phase);
    const desiredIds = new Set(defs.map((entry) => entry.id));
    const currentMoves = battle.enemyCombatant.moveSet || [];
    const hasDesiredLoadout = currentMoves.length === defs.length && currentMoves.every((entry) => desiredIds.has(entry.id));
    if (Number(mechanic.moveSetPhase || 0) === phase && hasDesiredLoadout) return;
    battle.enemyCombatant.moveSet = createEnemyMoveSet({
      key: battle.enemyCombatant.key,
      attribute: battle.enemyCombatant.attribute,
      moves: defs,
    });
    mechanic.moveSetPhase = phase;
  }

  function postgameTesoroRepairQueuedEnemyAction(battle, mechanic) {
    if (!battle?.enemyCombatant || mechanic?.key !== "postgame_gild_tesoro") return false;
    if (Number(mechanic.phase || 1) < 2 || battle.enemyPerformedAction || battle.enemyAction?.type !== "move") return false;
    const moveSet = Array.isArray(battle.enemyCombatant.moveSet) ? battle.enemyCombatant.moveSet : [];
    if (moveSet.some((entry) => entry.id === battle.enemyAction.moveId && Number(entry.currentPP ?? entry.pp ?? 0) > 0)) return false;
    const available = moveSet.filter((entry) => Number(entry.currentPP ?? entry.pp ?? 0) > 0);
    const fallback = available.find(postgameBossMechanicDirectMove);
    const replacement = fallback || available[0];
    if (!replacement) return false;
    battle.enemyAction = { type: "move", moveId: replacement.id };
    battle.enemyActionSummary = "";
    return true;
  }

  function postgameTesoroCrewControl(mechanic, card, index) {
    if (mechanic?.key !== "postgame_gild_tesoro") return 0;
    const crewKey = postgameBossMechanicCrewKey(card, index);
    return Math.max(0, Math.min(3, Number(mechanic.controlByCrew?.[crewKey] ?? mechanic.goldByCrew?.[crewKey] ?? 0)));
  }

  function postgameTesoroActiveControl(player, battle) {
    const mechanic = postgameBossMechanicFor(battle);
    if (mechanic?.key !== "postgame_gild_tesoro") return 0;
    return postgameTesoroCrewControl(mechanic, battleActiveCard(player, battle), battle.activeCrewIndex);
  }

  function applyPostgameBossMechanicPortrait(battle, mechanic) {
    if (!battle?.enemyCombatant || !mechanic?.key) return;
    if (mechanic.key === "postgame_gild_tesoro") {
      const standard = battleEnemyPortraitsFor(mechanic.key);
      if (Number(mechanic.phase || 1) === 2) {
        const root = "images/board/battle/enemies/postgame_gild_tesoro_golden";
        battle.enemyCombatant.battlePortraits = {
          ...standard,
          normal: `${root}/normal.webp`,
          idle: `${root}/normal.webp`,
          morale: `${root}/normal.webp`,
          angry: `${root}/hit_player.webp`,
          attack: `${root}/hit_player.webp`,
          hit: `${root}/hit.webp`,
          hurt: `${root}/hit.webp`,
          weak: `${root}/hit.webp`,
          dizzy: `${root}/hit.webp`,
          hitEnemySide: `${root}/hit.webp`,
          hitPlayerSide: `${root}/hit.webp`,
        };
      } else if (Number(mechanic.phase || 1) >= 3) {
        const finalNormal = standard.angry || standard.normal;
        battle.enemyCombatant.battlePortraits = {
          ...standard,
          normal: finalNormal,
          idle: finalNormal,
          morale: finalNormal,
        };
      }
      return;
    }
    if (mechanic.key === "postgame_douglas_bullet") {
      const standard = battleEnemyPortraitsFor(mechanic.key);
      battle.enemyCombatant.battlePortraits = {
        ...(battle.enemyCombatant.battlePortraits || {}),
        normal: standard.normal,
        idle: standard.normal,
        morale: standard.morale,
      };
      return;
    }
    let portrait = "";
    if (mechanic.key === "postgame_shiki" && mechanic.finalDuel) portrait = "images/board/battle/enemies/postgame_shiki/angry.webp";
    else if (mechanic.key === "postgame_saga" && mechanic.fused) portrait = "images/board/battle/enemies/postgame_saga/fused_normal.webp";
    else if (mechanic.key === "postgame_zephyr" && Number(mechanic.phase || 1) >= 2) portrait = "images/board/battle/enemies/postgame_zephyr/black_arm_normal.webp";
    else if (mechanic.key === "postgame_tot_musica") portrait = `images/board/battle/enemies/postgame_tot_musica/movement_${Math.max(1, Math.min(3, Number(mechanic.movement || 1)))}_normal.webp`;
    if (!portrait) return;
    battle.enemyCombatant.battlePortraits = { ...(battle.enemyCombatant.battlePortraits || {}), normal: portrait, idle: portrait, morale: portrait };
  }

  function postgameTotDefaultTeams(player) {
    const living = (player?.crew || [])
      .map((card, index) => ({ card, index }))
      .filter(({ card }) => card && Number(card.currentHp || 0) > 0)
      .map(({ index }) => index);
    const realCount = Math.max(1, Math.ceil(living.length / 2));
    return {
      realIndices: living.slice(0, realCount),
      songIndices: living.slice(realCount),
    };
  }

  function postgameTotUsesPlayerWorlds(battle = state.battleState, mechanic = postgameBossMechanicFor(battle)) {
    return Boolean(
      mechanic?.key === "postgame_tot_musica"
      && isCoopBattle(battle)
      && coopBattleParticipantIds(battle).length >= 2
      && mechanic.coopPlayerWorlds
    );
  }

  function postgameTotWorldPlayerIds(mechanic, world) {
    return Array.isArray(world === "real" ? mechanic?.realPlayerIds : mechanic?.songPlayerIds)
      ? (world === "real" ? mechanic.realPlayerIds : mechanic.songPlayerIds).map((id) => String(id))
      : [];
  }

  function postgameTotWorldPlayerCursorKey(world) {
    return world === "real" ? "realPlayerCursor" : "songPlayerCursor";
  }

  function postgameTotPlayerCanFight(player, battle) {
    if (!player) return false;
    const runtime = coopBattleRuntimeFor(player, battle, true);
    if (runtime?.escaped) return false;
    const living = livingCrewIndices(player);
    if (!living.length) {
      if (runtime) {
        runtime.defeated = true;
        runtime.needsReplacement = false;
      }
      return false;
    }
    if (runtime) {
      runtime.defeated = false;
      if (!living.includes(Number(runtime.activeCrewIndex))) runtime.activeCrewIndex = living[0];
      runtime.needsReplacement = false;
      runtime.replacementAfterAction = false;
    }
    return true;
  }

  function postgameTotActiveWorldPlayer(battle, mechanic, world, options = {}) {
    const ids = postgameTotWorldPlayerIds(mechanic, world);
    if (!ids.length) return null;
    const cursorKey = postgameTotWorldPlayerCursorKey(world);
    const start = Math.max(0, Math.min(ids.length - 1, Number(mechanic?.[cursorKey] || 0)));
    for (let offset = 0; offset < ids.length; offset += 1) {
      const index = (start + offset) % ids.length;
      const player = state.gameState.players.find((entry) => String(entry.id) === ids[index]);
      if (!postgameTotPlayerCanFight(player, battle)) continue;
      if (options.updateCursor !== false) mechanic[cursorKey] = index;
      return player;
    }
    return null;
  }

  function postgameTotNormalizePlayerWorlds(battle, mechanic) {
    if (!battle || mechanic?.key !== "postgame_tot_musica" || !isCoopBattle(battle)) return mechanic;
    const participantIds = coopBattleParticipantIds(battle);
    if (participantIds.length < 2) return mechanic;
    mechanic.coopPlayerWorlds = true;
    const validIds = new Set(participantIds);
    const assigned = new Set();
    mechanic.realPlayerIds = postgameTotWorldPlayerIds(mechanic, "real").filter((id) => validIds.has(id) && !assigned.has(id) && assigned.add(id));
    mechanic.songPlayerIds = postgameTotWorldPlayerIds(mechanic, "song").filter((id) => validIds.has(id) && !assigned.has(id) && assigned.add(id));
    participantIds.forEach((id) => {
      if (assigned.has(id)) return;
      const target = mechanic.realPlayerIds.length <= mechanic.songPlayerIds.length ? mechanic.realPlayerIds : mechanic.songPlayerIds;
      target.push(id);
      assigned.add(id);
    });
    if (!mechanic.realPlayerIds.length && mechanic.songPlayerIds.length > 1) mechanic.realPlayerIds.push(mechanic.songPlayerIds.shift());
    if (!mechanic.songPlayerIds.length && mechanic.realPlayerIds.length > 1) mechanic.songPlayerIds.push(mechanic.realPlayerIds.pop());
    mechanic.realPlayerCursor = Math.max(0, Math.min(Math.max(mechanic.realPlayerIds.length - 1, 0), Number(mechanic.realPlayerCursor || 0)));
    mechanic.songPlayerCursor = Math.max(0, Math.min(Math.max(mechanic.songPlayerIds.length - 1, 0), Number(mechanic.songPlayerCursor || 0)));
    const realPlayer = postgameTotActiveWorldPlayer(battle, mechanic, "real");
    const songPlayer = postgameTotActiveWorldPlayer(battle, mechanic, "song");
    mechanic.coopWorldActions = mechanic.coopWorldActions && typeof mechanic.coopWorldActions === "object"
      ? mechanic.coopWorldActions
      : { real: null, song: null };
    for (const [world, player] of [["real", realPlayer], ["song", songPlayer]]) {
      const selected = mechanic.coopWorldActions[world];
      if (!selected || String(selected.playerId || "") !== String(player?.id || "")) mechanic.coopWorldActions[world] = null;
    }
    mechanic.coopSelectionWorld = mechanic.coopWorldActions.real && !mechanic.coopWorldActions.song ? "song" : "real";
    mechanic.assigned = true;
    battle.needsReplacement = false;
    battle.replacementAfterAction = false;
    if (battle.result === "replacement") battle.result = "";
    delete battle.replacementReason;
    delete battle.pendingReplacementActiveCrewIndex;
    if (!battle.animating && !battle.result && !battle.roundResolved) {
      const selectionPlayer = mechanic.coopSelectionWorld === "song" ? songPlayer : realPlayer;
      if (selectionPlayer) battle.playerId = selectionPlayer.id;
    }
    return mechanic;
  }

  function postgameTotResolvePlayerWorldFrontlines(battle, mechanic, options = {}) {
    if (!postgameTotUsesPlayerWorlds(battle, mechanic)) return { realPlayer: null, songPlayer: null, lostWorld: "" };
    const shouldLog = options.log !== false;
    const worldPlayers = {};
    for (const world of ["real", "song"]) {
      const ids = postgameTotWorldPlayerIds(mechanic, world);
      const cursorKey = postgameTotWorldPlayerCursorKey(world);
      const cursor = Math.max(0, Math.min(Math.max(ids.length - 1, 0), Number(mechanic?.[cursorKey] || 0)));
      const currentPlayer = state.gameState.players.find((entry) => String(entry.id) === String(ids[cursor] || ""));
      if (currentPlayer) {
        withCoopBattleRuntime(currentPlayer, battle, () => {
          const runtime = coopBattleRuntimeFor(currentPlayer, battle, true);
          const currentIndex = Math.max(0, Number(runtime?.activeCrewIndex ?? currentPlayer.activeCrewIndex ?? 0));
          if (Number(currentPlayer.crew?.[currentIndex]?.currentHp || 0) > 0 || runtime?.escaped) return;
          const nextIndex = livingCrewIndices(currentPlayer)[0];
          if (Number.isInteger(nextIndex)) {
            const next = setTotMusicaActiveWorldCrew(currentPlayer, battle, mechanic, world, nextIndex);
            if (shouldLog) battle.log.push(`${world === "real" ? "現實世界" : "歌世界"}・${currentPlayer.name} 由 ${cardDisplayName(next)} 自動接替上場。`);
          } else {
            runtime.defeated = true;
            runtime.needsReplacement = false;
            runtime.replacementAfterAction = false;
            if (shouldLog) battle.log.push(`${currentPlayer.name} 已全員倒下，退出${world === "real" ? "現實世界" : "歌世界"}前線。`);
          }
        }, { save: true });
      }
      worldPlayers[world] = postgameTotActiveWorldPlayer(battle, mechanic, world);
    }
    const lostWorld = !worldPlayers.real ? "real" : !worldPlayers.song ? "song" : "";
    if (lostWorld) {
      battle.result = "lose";
      battle.needsReplacement = false;
      battle.replacementAfterAction = false;
      if (shouldLog) battle.log.push(`${lostWorld === "real" ? "現實世界" : "歌世界"}所有玩家皆已無法戰鬥，雙世界共鬥失敗。`);
      return { realPlayer: worldPlayers.real || null, songPlayer: worldPlayers.song || null, lostWorld };
    }
    battle.needsReplacement = false;
    if (battle.result === "replacement") battle.result = "";
    battle.replacementAfterAction = false;
    delete battle.replacementReason;
    delete battle.pendingReplacementActiveCrewIndex;
    if (options.resetSelection !== false) {
      mechanic.coopWorldActions = { real: null, song: null };
      mechanic.coopSelectionWorld = "real";
      battle.playerId = worldPlayers.real.id;
    }
    return { realPlayer: worldPlayers.real, songPlayer: worldPlayers.song, lostWorld: "" };
  }

  function postgameShikiCreateIslands(battle) {
    const bossMaxHp = Math.max(1, Number(battle?.enemyCombatant?.maxHp || 1));
    const islandMaxHp = Math.max(900, Math.round(bossMaxHp * 0.6));
    return POSTGAME_SHIKI_ISLAND_DEFS.map((definition) => ({
      ...definition,
      maxHp: islandMaxHp,
      currentHp: islandMaxHp,
      destroyed: false,
    }));
  }

  function postgameShikiActiveIsland(mechanic) {
    if (!mechanic || mechanic.finalDuel) return null;
    const living = postgameShikiLivingIslands(mechanic);
    return living.find((island) => island.id === mechanic.activeIslandId) || living[0] || null;
  }

  function postgameShikiLivingIslands(mechanic) {
    if (!mechanic || mechanic.finalDuel) return [];
    return (mechanic.islands || []).filter((island) => !island.destroyed && Number(island.currentHp || 0) > 0);
  }

  function postgameShikiNextLivingIsland(mechanic, afterIslandId = "") {
    if (!mechanic || mechanic.finalDuel) return null;
    const islands = Array.isArray(mechanic.islands) ? mechanic.islands : [];
    if (!islands.length) return null;
    const currentIndex = Math.max(-1, islands.findIndex((island) => island.id === afterIslandId));
    for (let offset = 1; offset <= islands.length; offset += 1) {
      const island = islands[(currentIndex + offset + islands.length) % islands.length];
      if (island && !island.destroyed && Number(island.currentHp || 0) > 0) return island;
    }
    return null;
  }

  function postgameShikiTargetId(islandId) {
    return `${POSTGAME_SHIKI_ISLAND_TARGET_PREFIX}${String(islandId || "")}`;
  }

  function postgameShikiIslandForTarget(mechanic, targetId) {
    if (!mechanic || mechanic.finalDuel) return null;
    const requested = String(targetId || "");
    if (requested === POSTGAME_SHIKI_ISLAND_TARGET_ID) return postgameShikiActiveIsland(mechanic);
    if (!requested.startsWith(POSTGAME_SHIKI_ISLAND_TARGET_PREFIX)) return null;
    const islandId = requested.slice(POSTGAME_SHIKI_ISLAND_TARGET_PREFIX.length);
    return postgameShikiLivingIslands(mechanic).find((island) => island.id === islandId) || null;
  }

  function postgameShikiSetEvent(mechanic, event) {
    mechanic.eventSerial = Math.max(0, Number(mechanic.eventSerial || 0)) + 1;
    mechanic.lastEvent = { ...event, serial: mechanic.eventSerial };
  }

  function postgameShikiRefreshFrontIsland(mechanic, battle, { initial = false } = {}) {
    if (!mechanic || mechanic.finalDuel) return null;
    const living = postgameShikiLivingIslands(mechanic);
    if (!living.length) return null;
    const next = living.find((island) => island.id === mechanic.activeIslandId) || living[0];
    mechanic.activeIslandId = next.id;
    mechanic.rotationCursor = Math.max(0, (mechanic.islands || []).findIndex((island) => island.id === next.id));
    mechanic.awaitingRotation = false;
    if (initial) {
      postgameShikiSetEvent(mechanic, { type: "deploy", islandId: next.id, islandName: next.name, image: next.image });
      battle?.log?.push?.("獸王島、岩獅島與空中艦隊同時現身，請選擇攻破順序。");
    }
    return next;
  }

  function postgameShikiEnterFinalDuel(battle, mechanic) {
    if (!battle?.enemyCombatant || !mechanic || mechanic.finalDuel) return false;
    mechanic.phase = 2;
    mechanic.finalDuel = true;
    mechanic.activeIslandId = "";
    mechanic.awaitingRotation = false;
    mechanic.exposedActions = 0;
    if (!mechanic.finalDuelEvasionApplied) {
      battle.enemyCombatant.intrinsicEvasionPenalty = Math.max(0, Number(battle.enemyCombatant.intrinsicEvasionPenalty || 0)) + 12;
      mechanic.finalDuelEvasionApplied = true;
    }
    battle.enemyCombatant.moveSet = createEnemyMoveSet({
      key: battle.enemyCombatant.key,
      attribute: "速",
      moves: [
        enemyMove("postgame_shiki_slash_wave", "斬波", "attack", 10, 250, "決戰劍氣；先制 +1", { priority: 1 }, { priority: 1, attribute: "速" }),
        enemyMove("postgame_shiki_lion_ground_scroll", "獅子威・地卷", "special", 7, 264, "浮空岩獅正面轟擊；命中後速度下降", { enemyStagesOnHit: { spd: -1 } }, { attribute: "技" }),
        enemyMove("postgame_shiki_lion_thousand_cutting_valley", "獅子・千切谷", "attack", 6, 292, "決戰連續劍氣兩段攻擊", { multiHit: 2 }, { attribute: "速" }),
        enemyMove("postgame_shiki_island_fall", "島嶼墜落", "special", 5, 332, "失去艦隊後砸落最後殘骸；重創前排並波及後排", { enemyStagesOnHit: { spd: -1 }, postgameBossMove: "shiki_island_fall" }, { attribute: "力", accuracy: 100 }),
      ],
    });
    postgameShikiSetEvent(mechanic, { type: "final", islandId: "", islandName: "金獅子決戰", image: "" });
    applyPostgameBossMechanicPortrait(battle, mechanic);
    battle.log.push("三座漂浮島全數墜落！史基失去島嶼掩護，進入金獅子決戰：雙攻與速度提升，閃避下降。");
    return true;
  }

  function initializePostgameBossMechanic(player, battle) {
    if (!player || !battle || (!battle.isPostgameBoss && battle.islandKind !== "postgame_boss")) return null;
    const key = String(battle.postgameBossKey || battle.enemyCombatant?.key || "");
    if (!POSTGAME_BOSS_MECHANIC_META[key]) return null;
    if (battle.postgameBossMechanic?.key === key) return normalizePostgameBossMechanic(player, battle);
    const mechanic = {
      version: 1,
      key,
      title: POSTGAME_BOSS_MECHANIC_META[key].title,
      initialized: true,
    };
    switch (key) {
      case "postgame_shiki":
        Object.assign(mechanic, {
          version: POSTGAME_SHIKI_ARCHIPELAGO_VERSION,
          archipelagoVersion: POSTGAME_SHIKI_ARCHIPELAGO_VERSION,
          phase: 1,
          islands: postgameShikiCreateIslands(battle),
          activeIslandId: "",
          rotationCursor: 0,
          exposedActions: 0,
          eventSerial: 0,
          lastEvent: null,
          finalDuel: false,
          finalDuelEvasionApplied: false,
          awaitingRotation: false,
        });
        postgameShikiRefreshFrontIsland(mechanic, battle, { initial: true });
        break;
      case "postgame_gild_tesoro":
        Object.assign(mechanic, {
          version: POSTGAME_TESORO_MECHANIC_VERSION,
          phase: 1,
          moveSetPhase: 1,
          controlByCrew: Object.fromEntries((player.crew || []).map((card, index) => [postgameBossMechanicCrewKey(card, index), 0])),
          goldByCrew: Object.fromEntries((player.crew || []).map((card, index) => [postgameBossMechanicCrewKey(card, index), 0])),
          lastMoveByCrew: {},
          exposedHits: 0,
          awakeningUsed: false,
          giantControl: 0,
          giantArmor: 0,
          ultimatePending: false,
          pendingPhase: 0,
          transitionSerial: 0,
          forcedSwitch: null,
          cancelQueuedPlayerAction: false,
          skipNextAction: false,
        });
        break;
      case "postgame_zephyr":
        Object.assign(mechanic, {
          version: POSTGAME_ZEPHYR_MECHANIC_VERSION,
          phase: 1,
          countdownTotal: POSTGAME_ZEPHYR_COUNTDOWN_START,
          countdown: POSTGAME_ZEPHYR_COUNTDOWN_START,
          countdownActive: true,
          disarmProgress: 0,
          disarmTarget: POSTGAME_ZEPHYR_DISARM_TARGET,
          dynaRockDisarmed: false,
          detonated: false,
          seaStoneSkipByCrew: {},
          lastMoveByCrew: {},
          lastDisarmRoll: 0,
          lastDisarmGain: 0,
        });
        break;
      case "postgame_tot_musica": {
        const teams = postgameTotDefaultTeams(player);
        Object.assign(mechanic, {
          assigned: isCpuPlayer(player),
          realIndices: teams.realIndices,
          songIndices: teams.songIndices,
          realActiveIndex: teams.realIndices[0] ?? battle.activeCrewIndex,
          songActiveIndex: teams.songIndices[0] ?? teams.realIndices[0] ?? battle.activeCrewIndex,
          movement: 1,
          lastSync: "pending",
           lastRealFirstDie: 0,
           lastSongFirstDie: 0,
           lastParityMatch: false,
           coopPlayerWorlds: false,
           realPlayerIds: [],
           songPlayerIds: [],
           realPlayerCursor: 0,
           songPlayerCursor: 0,
           coopSelectionWorld: "real",
           coopWorldActions: { real: null, song: null },
         });
        battle.activeCrewIndex = mechanic.realActiveIndex;
        player.activeCrewIndex = mechanic.realActiveIndex;
        break;
      }
      case "postgame_douglas_bullet": {
        mechanic.slots = Array.from({ length: 6 }, (_, index) => {
          const card = player.crew?.[index] || null;
          const item = normalizeBattleCarryItem(card?.battleCarryItem);
          const def = battleCarryItemDef(item);
          const effect = battleCarryItemEffect(item);
          const arsenalItems = [];
          return {
            number: index + 1,
            label: POSTGAME_BULLET_SLOT_LABELS[index],
            cardIndex: card ? index : -1,
            cardId: postgameBossMechanicCrewKey(card, index),
            cardName: card?.name || "空位",
            cardPortrait: card ? getBattlePortraitUrl(card, "idle") : "",
            itemId: item?.id || "",
            itemName: def?.name || "未裝備",
            itemImage: def?.image || (item ? battleCarryItemImage(item) : ""),
            itemSummary: item?.id === BULLET_ARSENAL_ITEM_ID
              ? "空武器庫外殼；內裝兵裝不給巴雷特效果，破孔後才由原持有人恢復使用"
              : (def?.summary || "沒有裝備攜帶物。"),
            effectKind: effect?.kind || "",
            arsenalItems,
            destroyed: false,
            triggered: {},
          };
        });
        const absorbedSlots = mechanic.slots.filter((slot) => slot.itemId);
        const absorbedNames = absorbedSlots.map((slot) => `${slot.number}號 ${slot.itemName}`);
        const hasEmptyArsenal = absorbedSlots.some((slot) => slot.itemId === BULLET_ARSENAL_ITEM_ID);
        battle.log.push(absorbedNames.length
          ? `巴雷特把隊伍的攜帶物吸入六孔裝甲：${absorbedNames.join("、")}。原持有人暫時失去效果。${hasEmptyArsenal ? "武器庫只吸收空外殼；兩件內裝兵裝留在原持有人身上封存，破壞該孔後才恢復生效。" : ""}`
          : "隊伍沒有裝備攜帶物，巴雷特的六個裝甲孔全部為空。"
        );
        postgameBossMechanicActiveBulletSlots(battle).forEach((slot) => {
          const effect = battleCarryItemEffect(slot.itemId);
          if (slot.itemId === "toxic_orb" || effect.kind === "self_status_on_battle_start" && effect.status === "poison") {
            applyBattleStatus("enemy", battle, "poison", Number(effect.turns || 3));
            battle.log.push(`${slot.itemName}的負面效果轉移到巴雷特身上，使他陷入中毒。`);
          }
          if (slot.itemId === "flame_orb" || effect.kind === "self_status_on_battle_start" && effect.status === "burn") {
            applyBattleStatus("enemy", battle, "burn", Number(effect.turns || 3));
            battle.log.push(`${slot.itemName}的負面效果轉移到巴雷特身上，使他陷入灼傷。`);
          }
        });
        const fusionVisualKey = `postgame-bullet-fusion:${battle.islandId || battle.postgameBossKey || "battle"}`;
        battle.openingPassiveVisualQueue = Array.isArray(battle.openingPassiveVisualQueue) ? battle.openingPassiveVisualQueue : [];
        battle.openingPassiveVisualPlayed = battle.openingPassiveVisualPlayed && typeof battle.openingPassiveVisualPlayed === "object"
          ? battle.openingPassiveVisualPlayed
          : {};
        if (!battle.openingPassiveVisualPlayed[fusionVisualKey] && !battle.openingPassiveVisualQueue.some((event) => event.key === fusionVisualKey)) {
          battle.openingPassiveVisualQueue.push({
            id: `postgame-bullet-fusion-${Date.now()}-${Math.random().toString(36).slice(2)}`,
            key: fusionVisualKey,
            type: "postgame-bullet-fusion",
            side: "enemy",
            actorName: battle.enemyCombatant?.name || "巴雷特",
            title: "合體武裝・六孔裝甲",
            effectText: absorbedNames.length
              ? `吸收 ${absorbedNames.length} 個裝甲孔位${hasEmptyArsenal ? "；武器庫只接管空外殼" : "並接管效果"}`
              : "六個裝甲孔位皆為空",
            targetSide: "enemy",
            moveType: "buff",
            iconUrl: POSTGAME_BOSS_MECHANIC_META.postgame_douglas_bullet.icon,
            slots: safeJsonClone(mechanic.slots),
            duration: absorbedNames.length ? 5600 : 2600,
          });
        }
        break;
      }
      case "postgame_saga":
        Object.assign(mechanic, { blood: 0, fused: false, bleedSources: {} });
        break;
      case "postgame_vinsmoke_judge":
        Object.assign(mechanic, { clones: 3, production: 0 });
        break;
      case "postgame_rob_lucci_awakened":
        Object.assign(mechanic, {
          nodes: [],
          rokuoganPending: false,
          activePower: "",
          activePowerId: "",
          activePowerStat: "",
          activePowerRound: 0,
        });
        postgameBossMechanicAddEnemyMove(battle, enemyMove(
          "postgame_lucci_ultimate_rokuogan",
          "覺醒・六王銃",
          "special",
          99,
          480,
          "六式全部使用後發動；必定命中、大幅無視防禦並震傷後排",
          { ignoreDefenseRatio: 0.5, postgameBossMove: "lucci_rokuogan", guaranteedHit: true },
          { attribute: "技", accuracy: 100 },
        ));
        break;
      case "postgame_king":
        Object.assign(mechanic, { flameOn: true, pendingFlameOn: null, lastFirstDice: 0 });
        break;
      case "postgame_charlotte_katakuri":
        Object.assign(mechanic, {
          version: POSTGAME_KATAKURI_MECHANIC_VERSION,
          forecastDie: 0,
          forecastRolling: false,
          forecastActionKey: "",
          choicePending: false,
          choiceMode: "",
          defenseRolling: false,
          defenseDie: 0,
          defenseReduction: 0,
          defenseActionKey: "",
          defenseAppliedActionKey: "",
          lastPlayerFirstDie: 0,
          lastOutcome: "",
        });
        break;
      case "postgame_patrick_redfield":
        Object.assign(mechanic, { lastDrainPercent: 0, lastDrainTotal: 0 });
        break;
      case "postgame_oars":
        Object.assign(mechanic, {
          saltBettingVersion: 3,
          saltBags: 3,
          saltTarget: POSTGAME_OARS_SALT_TARGET,
          lockedPredictions: [],
          lockedSaltBefore: 0,
          lastResult: null,
          predictionResolvedRound: 0,
          predictionResolvedKey: "",
          lastPeriodicSaltRound: 0,
          purificationInterruptPending: false,
          purified: false,
        });
        break;
      case "postgame_aramaki":
        Object.assign(mechanic, { groves: 1, revived: false, fireproof: false });
        break;
      default:
        break;
    }
    battle.postgameBossMechanic = mechanic;
    if (mechanic.key === "postgame_douglas_bullet") {
      postgameBossMechanicSealBulletArsenalCarriers(player, battle, mechanic);
      mechanic.bulletBaseMaxHp = Math.max(1, Number(battle.enemyCombatant?.maxHp || 1));
      postgameBossMechanicRefreshBulletMaxHp(player, battle, mechanic);
      postgameBossMechanicInitializeBulletRuntime(player, battle, mechanic);
    }
    battle.log.push(`${mechanic.title}：${POSTGAME_BOSS_MECHANIC_META[key].short}。`);
    return normalizePostgameBossMechanic(player, battle);
  }

  function normalizePostgameBossMechanic(player, battle) {
    const mechanic = battle?.postgameBossMechanic;
    if (!mechanic || !POSTGAME_BOSS_MECHANIC_META[mechanic.key]) return initializePostgameBossMechanic(player, battle);
    mechanic.version = Math.max(1, Number(mechanic.version || 1));
    mechanic.title = POSTGAME_BOSS_MECHANIC_META[mechanic.key].title;
    if (mechanic.key === "postgame_shiki") {
      const generated = postgameShikiCreateIslands(battle);
      const previousArchipelagoVersion = Math.max(0, Number(mechanic.archipelagoVersion || 0));
      const storedById = new Map((Array.isArray(mechanic.islands) ? mechanic.islands : []).map((island) => [String(island?.id || ""), island]));
      mechanic.islands = generated.map((fallback) => {
        const stored = storedById.get(fallback.id);
        const storedMaxHp = Math.max(1, Number(stored?.maxHp || fallback.maxHp));
        const storedCurrentHp = Math.max(0, Math.min(storedMaxHp, Number(stored?.currentHp ?? storedMaxHp)));
        const upgradingDurability = !!stored && previousArchipelagoVersion < POSTGAME_SHIKI_ARCHIPELAGO_VERSION;
        const maxHp = upgradingDurability ? fallback.maxHp : storedMaxHp;
        const currentHp = upgradingDurability
          ? Math.max(0, Math.min(maxHp, Math.round(maxHp * (storedCurrentHp / storedMaxHp))))
          : storedCurrentHp;
        return {
          ...fallback,
          maxHp,
          currentHp,
          destroyed: Boolean(stored?.destroyed) || currentHp <= 0,
        };
      });
      mechanic.archipelagoVersion = POSTGAME_SHIKI_ARCHIPELAGO_VERSION;
      mechanic.phase = Math.max(1, Math.min(2, Number(mechanic.phase || 1)));
      mechanic.finalDuel = Boolean(mechanic.finalDuel) || mechanic.phase >= 2 || mechanic.islands.every((island) => island.destroyed);
      mechanic.exposedActions = Math.max(0, Math.min(1, Number(mechanic.exposedActions || 0)));
      mechanic.eventSerial = Math.max(0, Number(mechanic.eventSerial || 0));
      mechanic.lastEvent = mechanic.lastEvent && typeof mechanic.lastEvent === "object" ? mechanic.lastEvent : null;
      mechanic.rotationCursor = Math.max(0, Math.min(mechanic.islands.length - 1, Number(mechanic.rotationCursor || 0)));
      mechanic.awaitingRotation = !!mechanic.awaitingRotation;
      if (mechanic.finalDuel) {
        mechanic.phase = 2;
        mechanic.activeIslandId = "";
        if (!mechanic.finalDuelEvasionApplied && battle.enemyCombatant) {
          battle.enemyCombatant.intrinsicEvasionPenalty = Math.max(0, Number(battle.enemyCombatant.intrinsicEvasionPenalty || 0)) + 12;
          mechanic.finalDuelEvasionApplied = true;
        }
      } else {
        if (battle.enemyCombatant?.moveSet) {
          battle.enemyCombatant.moveSet = battle.enemyCombatant.moveSet.filter((moveEntry) => moveEntry.id !== "postgame_shiki_island_fall");
        }
        postgameShikiRefreshFrontIsland(mechanic, battle);
      }
      delete mechanic.floatValue;
      delete mechanic.playerHitThisRound;
      delete mechanic.groundedSkipPending;
      delete mechanic.islandFallPending;
    }
    if (mechanic.key === "postgame_gild_tesoro") {
      const previousVersion = Math.max(0, Number(mechanic.version || 0));
      const legacyGold = mechanic.goldByCrew && typeof mechanic.goldByCrew === "object" ? mechanic.goldByCrew : {};
      mechanic.controlByCrew = mechanic.controlByCrew && typeof mechanic.controlByCrew === "object" ? mechanic.controlByCrew : {};
      mechanic.goldByCrew ||= {};
      mechanic.phase = Math.max(1, Math.min(2, Number(mechanic.phase || (mechanic.awakeningUsed ? 2 : 1))));
      (player?.crew || []).forEach((card, index) => {
        const crewKey = postgameBossMechanicCrewKey(card, index);
        const storedValue = Number(legacyGold[crewKey] ?? mechanic.controlByCrew[crewKey] ?? 0);
        const migratedGoldenLevel = previousVersion < POSTGAME_TESORO_MECHANIC_VERSION
          && mechanic.phase === 2
          && Number(index) === Number(battle.activeCrewIndex)
          ? Math.max(0, Math.min(3, Number(mechanic.giantControl || 0)))
          : 0;
        const floodLevel = mechanic.phase <= 2
          ? Math.max(0, Math.min(3, Math.max(storedValue, migratedGoldenLevel)))
          : 0;
        mechanic.controlByCrew[crewKey] = floodLevel;
        mechanic.goldByCrew[crewKey] = floodLevel;
      });
      mechanic.version = POSTGAME_TESORO_MECHANIC_VERSION;
      mechanic.moveSetPhase = Math.max(1, Math.min(2, Number(mechanic.moveSetPhase || mechanic.phase)));
      mechanic.lastMoveByCrew = mechanic.lastMoveByCrew && typeof mechanic.lastMoveByCrew === "object" ? mechanic.lastMoveByCrew : {};
      mechanic.exposedHits = 0;
      mechanic.awakeningUsed = mechanic.phase >= 2 || !!mechanic.awakeningUsed;
      mechanic.giantControl = 0;
      mechanic.giantArmor = 0;
      mechanic.ultimatePending = false;
      mechanic.pendingPhase = Math.max(0, Math.min(2, Number(mechanic.pendingPhase || 0)));
      if (mechanic.pendingPhase <= mechanic.phase) mechanic.pendingPhase = 0;
      mechanic.transitionSerial = Math.max(0, Number(mechanic.transitionSerial || 0));
      mechanic.cancelQueuedPlayerAction = !!mechanic.cancelQueuedPlayerAction;
      mechanic.skipNextAction = !!mechanic.skipNextAction;
      mechanic.forcedSwitch = mechanic.forcedSwitch?.pending
        ? {
          pending: true,
          fromIndex: Math.max(0, Number(mechanic.forcedSwitch.fromIndex ?? battle.activeCrewIndex ?? 0)),
          cardName: String(mechanic.forcedSwitch.cardName || ""),
        }
        : null;
      if (mechanic.forcedSwitch?.pending) {
        const fromIndex = mechanic.forcedSwitch.fromIndex;
        const forcedCard = player?.crew?.[fromIndex];
        if (!forcedCard || Number(forcedCard.currentHp || 0) <= 0) {
          mechanic.forcedSwitch = null;
          if (battle.replacementReason === "tesoro-gold") {
            battle.needsReplacement = true;
            battle.result = "replacement";
            battle.replacementAfterAction = true;
            battle.pendingReplacementActiveCrewIndex = fromIndex;
            delete battle.replacementReason;
          }
        }
      }
      if (mechanic.phase <= 2 && mechanic.forcedSwitch?.pending && !battle.result) {
        const fromIndex = mechanic.forcedSwitch.fromIndex;
        const candidates = livingCrewIndices(player).filter((crewIndex) => crewIndex !== fromIndex);
        if (candidates.length) {
          battle.needsReplacement = true;
          battle.result = "replacement";
          battle.replacementAfterAction = true;
          battle.replacementReason = "tesoro-gold";
          battle.pendingReplacementActiveCrewIndex = fromIndex;
        }
      }
      postgameTesoroApplyPhaseLoadout(battle, mechanic);
      postgameTesoroRepairQueuedEnemyAction(battle, mechanic);
    }
    if (mechanic.key === "postgame_tot_musica") {
      const validIndices = (player?.crew || []).map((_card, index) => index);
      mechanic.realIndices = (Array.isArray(mechanic.realIndices) ? mechanic.realIndices : []).filter((index) => validIndices.includes(Number(index))).map(Number);
      mechanic.songIndices = (Array.isArray(mechanic.songIndices) ? mechanic.songIndices : []).filter((index) => validIndices.includes(Number(index))).map(Number);
      if (!mechanic.realIndices.length || !mechanic.songIndices.length) Object.assign(mechanic, postgameTotDefaultTeams(player));
      mechanic.realActiveIndex = mechanic.realIndices.includes(Number(mechanic.realActiveIndex)) ? Number(mechanic.realActiveIndex) : mechanic.realIndices[0];
      mechanic.songActiveIndex = mechanic.songIndices.includes(Number(mechanic.songActiveIndex)) ? Number(mechanic.songActiveIndex) : mechanic.songIndices[0];
      mechanic.movement = Math.max(1, Math.min(3, Number(mechanic.movement || 1)));
      mechanic.lastRealFirstDie = Math.max(0, Math.min(6, Number(mechanic.lastRealFirstDie || 0)));
      mechanic.lastSongFirstDie = Math.max(0, Math.min(6, Number(mechanic.lastSongFirstDie || 0)));
      mechanic.lastParityMatch = !!mechanic.lastParityMatch;
      postgameTotNormalizePlayerWorlds(battle, mechanic);
      if (postgameTotUsesPlayerWorlds(battle, mechanic)) {
        const selectionPlayer = postgameTotActiveWorldPlayer(battle, mechanic, mechanic.coopSelectionWorld === "song" ? "song" : "real");
        const runtime = selectionPlayer ? coopBattleRuntimeFor(selectionPlayer, battle, true) : null;
        battle.activeCrewIndex = Math.max(0, Number(runtime?.activeCrewIndex ?? selectionPlayer?.activeCrewIndex ?? 0));
      } else {
        battle.activeCrewIndex = mechanic.realActiveIndex;
      }
    }
    if (mechanic.key === "postgame_king") {
      mechanic.flameOn = typeof mechanic.flameOn === "boolean" ? mechanic.flameOn : true;
      mechanic.pendingFlameOn = typeof mechanic.pendingFlameOn === "boolean" ? mechanic.pendingFlameOn : null;
      mechanic.lastFirstDice = Math.max(0, Math.min(6, Number(mechanic.lastFirstDice || 0)));
      delete mechanic.flameOffUntilPlayerAction;
    }
    if (mechanic.key === "postgame_charlotte_katakuri") {
      const previousVersion = Math.max(0, Number(mechanic.version || 0));
      mechanic.version = POSTGAME_KATAKURI_MECHANIC_VERSION;
      mechanic.forecastDie = Math.max(0, Math.min(6, Number(mechanic.forecastDie || 0)));
      mechanic.forecastRolling = !!mechanic.forecastRolling;
      mechanic.forecastActionKey = String(mechanic.forecastActionKey || "");
      mechanic.choicePending = !!mechanic.choicePending;
      mechanic.choiceMode = ["move", "defend"].includes(String(mechanic.choiceMode || "")) ? String(mechanic.choiceMode) : "";
      mechanic.defenseRolling = !!mechanic.defenseRolling;
      mechanic.defenseDie = Math.max(0, Math.min(6, Number(mechanic.defenseDie || 0)));
      mechanic.defenseReduction = Math.max(0, Math.min(0.9, Number(mechanic.defenseReduction || 0)));
      mechanic.defenseActionKey = String(mechanic.defenseActionKey || "");
      mechanic.defenseAppliedActionKey = String(mechanic.defenseAppliedActionKey || "");
      mechanic.lastPlayerFirstDie = Math.max(0, Math.min(6, Number(mechanic.lastPlayerFirstDie || 0)));
      mechanic.lastOutcome = ["predicted", "breakthrough", "defended"].includes(String(mechanic.lastOutcome || "")) ? String(mechanic.lastOutcome) : "";
      if (previousVersion < POSTGAME_KATAKURI_MECHANIC_VERSION) {
        const currentActor = isCoopBattle(battle) ? battleCommandPlayer(battle) : battlePlayer(null, battle) || player;
        const canResumeCurrentAction = !!currentActor
          && Number(battle?.roundIndex || 0) > 0
          && !battle?.playerAction
          && !battle?.roundResolved
          && !battle?.result;
        if (canResumeCurrentAction) {
          mechanic.forecastDie = randomInt(1, 6);
          mechanic.forecastActionKey = postgameKatakuriActionKey(currentActor, battle);
          mechanic.choicePending = true;
          mechanic.choiceMode = "";
          battle.awaitingRoundStartContinuation = true;
          battle.log ||= [];
          battle.log.push(`舊版未來視已轉換：卡塔庫栗的預知骰為 ${mechanic.forecastDie}，請選擇出招或防禦。`);
        }
      }
      delete mechanic.calm;
      delete mechanic.futureDisabledActions;
      delete mechanic.predictions;
      delete mechanic.lastMoveByCrew;
      delete mechanic.futureSightDodged;
    }
    if (mechanic.key === "postgame_douglas_bullet") {
      mechanic.slots = Array.isArray(mechanic.slots) ? mechanic.slots.slice(0, 6) : [];
      mechanic.slots.forEach((slot) => {
        slot.triggered = slot.triggered && typeof slot.triggered === "object" ? slot.triggered : {};
        slot.arsenalItems = slot.itemId === BULLET_ARSENAL_ITEM_ID
          ? []
          : (Array.isArray(slot.arsenalItems) ? slot.arsenalItems.slice(0, BULLET_ARSENAL_SLOT_LIMIT) : []);
        slot.arsenalItems.forEach((entry) => {
          entry.triggered = entry.triggered && typeof entry.triggered === "object" ? entry.triggered : {};
        });
      });
      postgameBossMechanicRefreshBulletMaxHp(player, battle, mechanic);
      postgameBossMechanicInitializeBulletRuntime(player, battle, mechanic);
    }
    if (mechanic.key === "postgame_zephyr") {
      const previousVersion = Math.max(0, Number(mechanic.version || 0));
      if (battle.enemyCombatant) battle.enemyCombatant.name = "澤法";
      mechanic.version = POSTGAME_ZEPHYR_MECHANIC_VERSION;
      mechanic.seaStoneSkipByCrew = mechanic.seaStoneSkipByCrew && typeof mechanic.seaStoneSkipByCrew === "object" ? mechanic.seaStoneSkipByCrew : {};
      mechanic.lastMoveByCrew = mechanic.lastMoveByCrew && typeof mechanic.lastMoveByCrew === "object" ? mechanic.lastMoveByCrew : {};
      mechanic.phase = Math.max(1, Math.min(2, Number(mechanic.phase || 1)));
      mechanic.countdownTotal = POSTGAME_ZEPHYR_COUNTDOWN_START;
      mechanic.countdown = Math.max(0, Math.min(POSTGAME_ZEPHYR_COUNTDOWN_START, Number(previousVersion < 2 ? POSTGAME_ZEPHYR_COUNTDOWN_START : mechanic.countdown ?? POSTGAME_ZEPHYR_COUNTDOWN_START)));
      mechanic.disarmTarget = POSTGAME_ZEPHYR_DISARM_TARGET;
      mechanic.disarmProgress = Math.max(0, Math.min(POSTGAME_ZEPHYR_DISARM_TARGET, Number(previousVersion < 2 ? 0 : mechanic.disarmProgress || 0)));
      mechanic.dynaRockDisarmed = previousVersion >= 2 && (Boolean(mechanic.dynaRockDisarmed) || mechanic.disarmProgress >= POSTGAME_ZEPHYR_DISARM_TARGET);
      mechanic.detonated = previousVersion >= 2 && Boolean(mechanic.detonated);
      if (previousVersion === 2 && mechanic.phase === 2 && mechanic.dynaRockDisarmed) {
        const explicitDisarm = (battle.log || []).some((entry) => /最後的炸藥岩解除成功/.test(String(entry || "")));
        if (!explicitDisarm) {
          const latestProgressLog = (battle.log || []).slice().reverse().map((entry) => String(entry || "").match(/解除進度\s+\d+\s*→\s*(\d+)\/3/)).find(Boolean);
          mechanic.disarmProgress = Math.max(0, Math.min(POSTGAME_ZEPHYR_DISARM_TARGET, Number(latestProgressLog?.[1] || 0)));
          mechanic.dynaRockDisarmed = false;
        }
      }
      mechanic.countdownActive = !mechanic.dynaRockDisarmed && !mechanic.detonated && mechanic.countdown > 0;
      mechanic.lastDisarmRoll = Math.max(0, Math.min(6, Number(mechanic.lastDisarmRoll || 0)));
      mechanic.lastDisarmGain = Math.max(0, Math.min(2, Number(mechanic.lastDisarmGain || 0)));
      delete mechanic.heat;
      delete mechanic.armor;
      delete mechanic.overheat;
      delete mechanic.overheatRound;
      if (mechanic.phase === 2) postgameZephyrApplyPhaseTwoLoadout(battle);
    }
    if (mechanic.key === "postgame_rob_lucci_awakened") {
      mechanic.nodes = (Array.isArray(mechanic.nodes) ? mechanic.nodes : []).filter((name) => POSTGAME_LUCCI_SIX_POWERS.includes(name)).slice(0, 6);
      const activePower = postgameLucciSixPowerDef(mechanic.activePowerId || mechanic.activePower || mechanic.activePowerStat);
      mechanic.activePower = activePower?.name || "";
      mechanic.activePowerId = activePower?.id || "";
      mechanic.activePowerStat = activePower?.stat || "";
      mechanic.activePowerRound = Math.max(0, Number(mechanic.activePowerRound || 0));
      mechanic.rokuoganPending = !!mechanic.rokuoganPending || mechanic.nodes.length >= POSTGAME_LUCCI_SIX_POWER_DEFS.length;
    }
    if (mechanic.key === "postgame_oars") {
      const legacyVersion = Math.max(0, Number(mechanic.saltBettingVersion || 0));
      const legacyPrediction = mechanic.lockedPrediction && typeof mechanic.lockedPrediction === "object"
        ? mechanic.lockedPrediction
        : null;
      mechanic.saltTarget = POSTGAME_OARS_SALT_TARGET;
      mechanic.saltBags = Math.max(0, Math.min(POSTGAME_OARS_SALT_TARGET, Number(mechanic.saltBags || 0)));
      if (legacyVersion < 2) mechanic.saltBags = Math.max(3, mechanic.saltBags);
      const normalizedLockedPredictions = (Array.isArray(mechanic.lockedPredictions)
        ? mechanic.lockedPredictions
        : legacyPrediction ? [{ ...safeJsonClone(legacyPrediction), stake: 0 }] : [])
        .filter((entry) => entry && typeof entry === "object" && entry.id)
        .map((entry) => ({ ...entry, stake: Math.max(0, Math.floor(Number(entry.stake ?? 1))) }));
      mechanic.lockedPredictions = [...normalizedLockedPredictions.reduce((merged, entry) => {
        const id = String(entry.id || "");
        const existing = merged.get(id);
        if (existing) existing.stake += entry.stake;
        else merged.set(id, entry);
        return merged;
      }, new Map()).values()];
      mechanic.lockedPrediction = null;
      mechanic.lockedSaltBefore = Math.max(0, Number(mechanic.lockedSaltBefore || 0));
      mechanic.lastResult = mechanic.lastResult && typeof mechanic.lastResult === "object" ? mechanic.lastResult : null;
      mechanic.predictionResolvedRound = Math.max(0, Number(mechanic.predictionResolvedRound || 0));
      mechanic.predictionResolvedKey = String(mechanic.predictionResolvedKey || "");
      mechanic.lastPeriodicSaltRound = Math.max(0, Number(mechanic.lastPeriodicSaltRound || (legacyVersion < 2 ? Math.floor(Number(battle.roundIndex || 0) / 3) * 3 : 0)));
      mechanic.saltBettingVersion = 3;
      mechanic.purificationInterruptPending = !!mechanic.purificationInterruptPending;
      mechanic.purified = !!mechanic.purified;
      if (battle.enemyCombatant) {
        battle.enemyCombatant.minimumHitChance = 25;
        battle.enemyCombatant.intrinsicEvasionPenalty = 16;
        if (legacyVersion < 2) {
          ["accuracy", "evasion", "spd"].forEach((stat) => {
            if (Number(battle.enemyCombatant.stages?.[stat] || 0) === -3) battle.enemyCombatant.stages[stat] = 0;
          });
        }
      }
    }
    applyPostgameBossMechanicPortrait(battle, mechanic);
    return mechanic;
  }

  function postgameBulletSlotForCrew(battle, card, index) {
    const mechanic = postgameBossMechanicFor(battle);
    if (mechanic?.key !== "postgame_douglas_bullet") return null;
    const cardId = postgameBossMechanicCrewKey(card, index);
    return (mechanic.slots || []).find((slot) => Number(slot.cardIndex) === Number(index) || (slot.cardId && slot.cardId === cardId)) || null;
  }

  function postgameBulletCarryIsAbsorbed(battle, card, index) {
    const slot = postgameBulletSlotForCrew(battle, card, index);
    return !!slot?.itemId && !slot.destroyed;
  }

  function postgameKatakuriCurrentPlayer(battle = state.battleState, fallbackPlayer = null) {
    return isCoopBattle(battle) ? battleCommandPlayer(battle) : battlePlayer(null, battle) || fallbackPlayer;
  }

  function postgameKatakuriActionKey(player, battle = state.battleState) {
    return `${Math.max(0, Number(battle?.roundIndex || 0))}:${String(player?.id || battle?.playerId || "player")}`;
  }

  function postgameKatakuriMoveChoiceActive(player, battle = state.battleState) {
    const mechanic = postgameBossMechanicFor(battle);
    return Boolean(
      mechanic?.key === "postgame_charlotte_katakuri"
      && mechanic.choiceMode === "move"
      && mechanic.forecastActionKey === postgameKatakuriActionKey(player, battle)
    );
  }

  function postgameKatakuriFutureSightCinematicDuration() {
    const params = new URLSearchParams(window.location.search);
    return params.has("katakuri_future_sight_qa") || params.has("postgame_mechanic_qa") ? 850 : 4800;
  }

  async function waitPostgameKatakuriForecastStage(battle, mechanic, actionKey) {
    while (
      state.battleState === battle
      && postgameBossMechanicFor(battle) === mechanic
      && mechanic.forecastActionKey === actionKey
      && !battle.result
    ) {
      if (!battlePrebattleIntroPending(battle) && battlePageReadyForOpeningVisuals()) return true;
      await wait(100);
    }
    return false;
  }

  async function playPostgameKatakuriFutureSightCinematic(battle, mechanic, actionKey) {
    const duration = postgameKatakuriFutureSightCinematicDuration();
    const event = attachBattleVisualEventSnapshots({
      id: `katakuri-future-sight-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      type: "postgame-katakuri-future-sight",
      side: "enemy",
      targetSide: "player",
      title: "預知未來",
      subtitle: "卡塔庫栗已經看見你接下來的行動。",
      videoUrl: "videos/board/postgame_bosses/katakuri/future_sight_red_eyes.mp4",
      videoStartTime: 0,
      duration,
    }, battle);
    battle.visualEvent = event;
    battle.log.push("卡塔庫栗發動見聞色霸氣，開始窺見接下來的未來。");
    notifyBattleWindow();
    scheduleBattleLanStatePush("battle-katakuri-future-sight", 0, { force: true });
    await waitBattleWindowVisual(event, duration);
    return Boolean(
      state.battleState === battle
      && postgameBossMechanicFor(battle) === mechanic
      && mechanic.forecastActionKey === actionKey
      && !battle.result
    );
  }

  async function beginPostgameKatakuriForecast(player, battle) {
    const mechanic = postgameBossMechanicFor(battle);
    if (!player || mechanic?.key !== "postgame_charlotte_katakuri" || battle.result) return false;
    const actionKey = postgameKatakuriActionKey(player, battle);
    if (mechanic.forecastActionKey === actionKey && (mechanic.forecastRolling || mechanic.choicePending || mechanic.choiceMode)) return true;
    mechanic.forecastDie = 0;
    mechanic.forecastRolling = true;
    mechanic.forecastActionKey = actionKey;
    mechanic.choicePending = false;
    mechanic.choiceMode = "";
    mechanic.defenseRolling = false;
    mechanic.defenseDie = 0;
    mechanic.defenseReduction = 0;
    mechanic.defenseActionKey = "";
    mechanic.defenseAppliedActionKey = "";
    mechanic.lastPlayerFirstDie = 0;
    mechanic.lastOutcome = "";
    renderBattleInterface();
    notifyBattleWindow();
    if (!await waitPostgameKatakuriForecastStage(battle, mechanic, actionKey)) return false;
    if (!await playPostgameKatakuriFutureSightCinematic(battle, mechanic, actionKey)) return false;
    const parityEntry = battleFirstDiceParityEntry("enemy", battle, player);
    const forecastRoll = rollBattleActionDice(
      "special",
      `${battle.enemyCombatant?.name || "卡塔庫栗"}・預知未來`,
      "未來視正在讀取這次行動……",
      battle,
      6,
      { side: "enemy", moveType: "buff", forcedFirstDiceParity: parityEntry?.parity || "" },
    );
    scheduleBattleLanStatePush("battle-katakuri-forecast-dice", 0, { force: true });
    const forecastDie = await forecastRoll;
    if (parityEntry) {
      const remaining = consumeBattleFirstDiceParityEffect("enemy", battle, player);
      battle.log.push(`${parityEntry.parity === "odd" ? "單數骰子" : "雙數骰子"}控制了卡塔庫栗這次預知骰，剩餘 ${remaining} 次。`);
    }
    const currentMechanic = postgameBossMechanicFor(battle);
    if (state.battleState !== battle || currentMechanic !== mechanic || mechanic.forecastActionKey !== actionKey || battle.result) return false;
    mechanic.forecastDie = Math.max(1, Math.min(6, Number(forecastDie || 1)));
    mechanic.forecastRolling = false;
    mechanic.choicePending = true;
    battle.log.push(`卡塔庫栗以「預知未來」擲出 ${mechanic.forecastDie}；${player.name} 可選擇出招突破，或放棄出招改為防禦。`);
    renderBattleInterface();
    notifyBattleWindow();
    scheduleOpeningPassiveVisualsIfReady(player, battle);
    scheduleBattleLanStatePush("battle-katakuri-forecast", 60, { force: true });
    if (isCpuPlayer(player)) scheduleCpuAutoStep(cpuTurnDelay(420, player, 160));
    return true;
  }

  async function resolvePostgameKatakuriDefense(player, battle, actionKey) {
    const mechanic = postgameBossMechanicFor(battle);
    if (!player || mechanic?.key !== "postgame_charlotte_katakuri" || mechanic.forecastActionKey !== actionKey || battle.result) return false;
    const parityEntry = battleFirstDiceParityEntry("player", battle, player);
    const defenseDie = await rollBattleActionDice(
      "move",
      `${battleActiveCard(player, battle)?.name || player.name}・防禦`,
      "防禦骰點數 ×15% 為本次直接攻擊減傷。",
      battle,
      6,
      { side: "player", moveType: "shield", forcedFirstDiceParity: parityEntry?.parity || "" },
    );
    if (parityEntry) {
      const remaining = consumeBattleFirstDiceParityEffect("player", battle, player);
      battle.log.push(`${parityEntry.parity === "odd" ? "單數骰子" : "雙數骰子"}控制了這次防禦骰，剩餘 ${remaining} 次。`);
    }
    const currentMechanic = postgameBossMechanicFor(battle);
    if (state.battleState !== battle || currentMechanic !== mechanic || mechanic.forecastActionKey !== actionKey || battle.result) return false;
    mechanic.defenseDie = Math.max(1, Math.min(6, Number(defenseDie || 1)));
    mechanic.defenseReduction = Math.max(0, Math.min(0.9, mechanic.defenseDie * POSTGAME_KATAKURI_DEFENSE_PER_DIE));
    mechanic.defenseActionKey = actionKey;
    mechanic.defenseAppliedActionKey = "";
    mechanic.defenseRolling = false;
    mechanic.lastOutcome = "defended";
    battle.playerDiceRoll = mechanic.defenseDie;
    battle.log.push(`${player.name} 放棄出招並擲出防禦骰 ${mechanic.defenseDie}；卡塔庫栗本次直接攻擊傷害減少 ${Math.round(mechanic.defenseReduction * 100)}%。`);
    const ready = !battle.awaitingRoundStartContinuation || continueBattleRoundStartAfterPrompt(player, battle);
    if (!ready) {
      renderBattleInterface();
      notifyBattleWindow();
      return true;
    }
    const action = {
      type: "katakuri-defense",
      actorCrewIndex: Math.max(0, Number(battle.activeCrewIndex ?? player.activeCrewIndex ?? 0)),
      defenseDie: mechanic.defenseDie,
      reduction: mechanic.defenseReduction,
      actionKey,
    };
    if (isCoopBattle(battle)) {
      queueCoopBattleAction(player, battle, action);
    } else {
      battle.playerAction = action;
      battle.enemyAction = chooseEnemyAction(battle);
      void resolvePlannedBattleActions(player, battle);
    }
    scheduleBattleLanStatePush("battle-katakuri-defense", 60, { force: true });
    return true;
  }

  function choosePostgameKatakuriAction(choice = "") {
    const battle = state.battleState;
    const player = postgameKatakuriCurrentPlayer(battle);
    const mechanic = postgameBossMechanicFor(battle);
    const normalizedChoice = choice === "defend" ? "defend" : choice === "move" ? "move" : "";
    if (!battle || !player || !normalizedChoice || mechanic?.key !== "postgame_charlotte_katakuri" || !mechanic.choicePending || mechanic.forecastRolling || mechanic.defenseRolling || battle.result) return false;
    if (isCoopBattle(battle) ? warnBoardLanBattleLocked(player, battle) : warnBoardLanTurnLocked(player)) return false;
    const actionKey = postgameKatakuriActionKey(player, battle);
    if (mechanic.forecastActionKey !== actionKey || mechanic.forecastDie < 1) return false;
    if (isCoopBattle(battle)) prepareCoopBattleCommandRuntime(player, battle);
    mechanic.choicePending = false;
    mechanic.choiceMode = normalizedChoice;
    if (normalizedChoice === "move") {
      const ready = !battle.awaitingRoundStartContinuation || continueBattleRoundStartAfterPrompt(player, battle);
      battle.log.push(`${player.name} 選擇正面出招並回到一般行動；仍可攻擊、換夥伴、使用道具或逃跑，只有實際使用招式時第一骰需達到 ${mechanic.forecastDie}。`);
      renderBattleInterface();
      notifyBattleWindow();
      scheduleBattleLanStatePush("battle-katakuri-choose-move", 60, { force: true });
      if (ready && isCpuPlayer(player)) scheduleCpuAutoStep(cpuTurnDelay(260, player, 120));
      return true;
    }
    mechanic.defenseRolling = true;
    renderBattleInterface();
    notifyBattleWindow();
    void resolvePostgameKatakuriDefense(player, battle, actionKey);
    return true;
  }

  function postgameBossMechanicPromptPending(battle = state.battleState) {
    const mechanic = postgameBossMechanicFor(battle);
    if (!mechanic) return false;
    if (mechanic.key === "postgame_tot_musica" && !mechanic.assigned) return true;
    if (mechanic.key === "postgame_gild_tesoro" && mechanic.forcedSwitch?.pending) return true;
    if (mechanic.key === "postgame_charlotte_katakuri" && (mechanic.forecastRolling || mechanic.choicePending || mechanic.defenseRolling)) return true;
    if (mechanic.key === "postgame_oars" && !mechanic.purified) {
      const currentPlayer = isCoopBattle(battle) ? battleCommandPlayer(battle) : battlePlayer(null, battle);
      if (Number(mechanic.saltBags || 0) >= POSTGAME_OARS_SALT_TARGET) return true;
      if (Number(mechanic.saltBags || 0) > 0 && !mechanic.lockedPredictions?.length && mechanic.predictionResolvedKey !== postgameOarsActionKey(currentPlayer, battle)) return true;
    }
    return false;
  }

  function postgameOarsPurificationInterruptPending(battle = state.battleState) {
    const mechanic = postgameBossMechanicFor(battle);
    return Boolean(
      mechanic?.key === "postgame_oars"
      && !mechanic.purified
      && mechanic.purificationInterruptPending
      && Number(mechanic.saltBags || 0) >= POSTGAME_OARS_SALT_TARGET
    );
  }

  function postgameBossMechanicTargets(player, battle) {
    const mechanic = postgameBossMechanicFor(battle);
    if (!mechanic) return [];
    const targets = [{ id: "boss", label: battle.enemyCombatant?.name || "Boss", description: "直接攻擊 Boss" }];
    if (mechanic.key === "postgame_shiki") {
      targets.unshift(...postgameShikiLivingIslands(mechanic).map((island) => ({
        id: postgameShikiTargetId(island.id),
        label: `${island.name} ${Math.max(0, Number(island.currentHp || 0))}/${Math.max(1, Number(island.maxHp || 1))}`,
        description: `${island.effect}；攻擊島嶼時有 ${Math.round(POSTGAME_SHIKI_ISLAND_PIERCE_RATIO * 100)}% 傷害貫穿史基；連擊破島後自動轉攻下一座`,
      })));
    }
    if (mechanic.key === "postgame_vinsmoke_judge" && mechanic.clones > 0) {
      targets.unshift({ id: "judge_clone", label: `複製兵 ×${mechanic.clones}`, description: "每段命中清除一名，不傷害伽治" });
    }
    if (mechanic.key === "postgame_aramaki" && mechanic.groves > 0) {
      targets.unshift({ id: "aramaki_grove", label: `森林根系 ×${mechanic.groves}`, description: "清除森林，阻止種子再生" });
    }
    return targets;
  }

  function postgameBossDefaultTarget(player, battle) {
    const mechanic = postgameBossMechanicFor(battle);
    if (!mechanic || !isCpuPlayer(player)) return "boss";
    if (mechanic.key === "postgame_shiki") {
      const living = postgameShikiLivingIslands(mechanic);
      const priority = ["lion", "beast", "fleet"].map((id) => living.find((island) => island.id === id)).find(Boolean) || living[0];
      if (priority) return postgameShikiTargetId(priority.id);
    }
    if (mechanic.key === "postgame_vinsmoke_judge" && mechanic.clones > 0) return "judge_clone";
    if (mechanic.key === "postgame_aramaki" && mechanic.groves >= 2) return "aramaki_grove";
    return "boss";
  }

  function postgameTotCoopWorldView(battle, mechanic, world) {
    const player = postgameTotActiveWorldPlayer(battle, mechanic, world);
    if (!player) return { playerId: "", playerName: "無可戰鬥玩家", activeIndex: -1, crew: [], battleItems: [], escapeThreshold: 0 };
    return withCoopBattleRuntime(player, battle, () => {
      const runtime = coopBattleRuntimeFor(player, battle, true);
      const activeIndex = livingActiveCrewIndex(player, runtime?.activeCrewIndex ?? player.activeCrewIndex ?? 0);
      battle.activeCrewIndex = activeIndex;
      player.activeCrewIndex = activeIndex;
      if (runtime) {
        runtime.activeCrewIndex = activeIndex;
        runtime.needsReplacement = false;
        runtime.replacementAfterAction = false;
      }
      battle.needsReplacement = false;
      if (battle.result === "replacement") battle.result = "";
      return {
        playerId: String(player.id),
        playerName: player.name || "共鬥玩家",
        activeIndex,
        crew: battleCrewEntries(player, battle).map(({ card, index }) => serializeBattleCrewCard(card, index, battle)),
        battleItems: getBattleItemOptions(player),
        escapeThreshold: getTeamEffects(player).escapeThreshold || 0,
      };
    }, { save: true });
  }

  function postgameBossMechanicView(player, battle) {
    const mechanic = normalizePostgameBossMechanic(player, battle);
    if (!mechanic) return null;
    const meta = POSTGAME_BOSS_MECHANIC_META[mechanic.key];
    const bossDef = postgameBossDef(mechanic.key);
    const view = {
      active: true,
      key: mechanic.key,
      title: meta.title,
      subtitle: meta.short,
      rule: meta.rule,
      counter: meta.counter,
      theme: meta.theme,
      panelImage: POSTGAME_BOSS_MECHANIC_PANEL_IMAGE,
      iconUrl: meta.icon,
      islandImage: bossDef?.islandImage || ISLAND_IMAGE_MAP.postgame_boss,
      targets: postgameBossMechanicTargets(player, battle),
      prompt: null,
      state: {},
    };
    switch (mechanic.key) {
      case "postgame_shiki":
        view.state = {
          phase: mechanic.phase,
          finalDuel: !!mechanic.finalDuel,
          activeIslandId: mechanic.activeIslandId || "",
          exposedActions: mechanic.exposedActions || 0,
          eventSerial: mechanic.eventSerial || 0,
          lastEvent: safeJsonClone(mechanic.lastEvent),
          islands: (mechanic.islands || []).map((island) => ({
            id: island.id,
            name: island.name,
            effect: island.effect,
            image: island.image,
            brokenImage: island.brokenImage,
            maxHp: island.maxHp,
            currentHp: island.currentHp,
            destroyed: !!island.destroyed,
            active: !island.destroyed,
          })),
        };
        break;
      case "postgame_gild_tesoro":
        view.state = {
          phase: Math.max(1, Math.min(2, Number(mechanic.phase || 1))),
          awakeningUsed: !!mechanic.awakeningUsed,
          exposedHits: Math.max(0, Number(mechanic.exposedHits || 0)),
          goldenDamageRetainedPercent: Number(mechanic.phase || 1) === 2 ? Math.round(POSTGAME_TESORO_GOLDEN_DAMAGE_RATIO * 100) : 100,
          transitionSerial: Math.max(0, Number(mechanic.transitionSerial || 0)),
          crew: (player.crew || []).map((card, index) => ({
            index,
            id: postgameBossMechanicCrewKey(card, index),
            name: cardDisplayName(card),
            portrait: getBattlePortraitUrl(card, "normal"),
            control: postgameTesoroCrewControl(mechanic, card, index),
            gold: Math.max(0, postgameTesoroCrewControl(mechanic, card, index)),
            currentHp: Number(card.currentHp || 0),
            maxHp: cardMaxHp(card),
            active: Number(index) === Number(battle.activeCrewIndex),
          })),
        };
        break;
      case "postgame_zephyr":
        view.state = {
          phase: mechanic.phase,
          countdownTotal: mechanic.countdownTotal,
          countdown: mechanic.countdown,
          countdownActive: !!mechanic.countdownActive,
          disarmProgress: mechanic.disarmProgress,
          disarmTarget: mechanic.disarmTarget,
          dynaRockDisarmed: !!mechanic.dynaRockDisarmed,
          detonated: !!mechanic.detonated,
          canDisarm: !battle.result && mechanic.countdownActive && !mechanic.dynaRockDisarmed && !mechanic.detonated && mechanic.countdown > 0,
          dynaStoneImage: POSTGAME_ZEPHYR_DYNA_STONE_IMAGE,
          lastDisarmRoll: mechanic.lastDisarmRoll,
          lastDisarmGain: mechanic.lastDisarmGain,
        };
        break;
      case "postgame_tot_musica":
        if (postgameTotUsesPlayerWorlds(battle, mechanic)) {
          const realWorld = postgameTotCoopWorldView(battle, mechanic, "real");
          const songWorld = postgameTotCoopWorldView(battle, mechanic, "song");
          view.state = {
            assigned: true,
            coopPlayerWorlds: true,
            movement: mechanic.movement,
            realPlayerIds: mechanic.realPlayerIds.slice(),
            songPlayerIds: mechanic.songPlayerIds.slice(),
            realPlayerId: realWorld.playerId,
            songPlayerId: songWorld.playerId,
            realPlayerName: realWorld.playerName,
            songPlayerName: songWorld.playerName,
            realIndices: realWorld.crew.map((card) => Number(card.index)),
            songIndices: songWorld.crew.map((card) => Number(card.index)),
            realActiveIndex: realWorld.activeIndex,
            songActiveIndex: songWorld.activeIndex,
            realCrew: realWorld.crew,
            songCrew: songWorld.crew,
            realBattleItems: realWorld.battleItems,
            songBattleItems: songWorld.battleItems,
            realEscapeThreshold: realWorld.escapeThreshold,
            songEscapeThreshold: songWorld.escapeThreshold,
            selectionWorld: mechanic.coopSelectionWorld === "song" ? "song" : "real",
            realActionSelected: !!mechanic.coopWorldActions?.real,
            songActionSelected: !!mechanic.coopWorldActions?.song,
            lastSync: mechanic.lastSync || "pending",
            lastRealFirstDie: mechanic.lastRealFirstDie || 0,
            lastSongFirstDie: mechanic.lastSongFirstDie || 0,
            lastParityMatch: !!mechanic.lastParityMatch,
            crew: [],
          };
        } else {
          view.state = {
            assigned: !!mechanic.assigned,
            coopPlayerWorlds: false,
            movement: mechanic.movement,
            realIndices: mechanic.realIndices.slice(),
            songIndices: mechanic.songIndices.slice(),
            realActiveIndex: mechanic.realActiveIndex,
            songActiveIndex: mechanic.songActiveIndex,
            lastSync: mechanic.lastSync || "pending",
            lastRealFirstDie: mechanic.lastRealFirstDie || 0,
            lastSongFirstDie: mechanic.lastSongFirstDie || 0,
            lastParityMatch: !!mechanic.lastParityMatch,
            crew: battleCrewEntries(player, battle).map(({ card, index }) => serializeBattleCrewCard(card, index, battle)),
          };
        }
        if (!mechanic.assigned) {
          view.prompt = {
            type: "tot_team_setup",
            title: "編排兩隊順位",
            message: "把船員排進左右兩隊；第一格是先發。",
          };
        }
        break;
      case "postgame_douglas_bullet":
        view.state = {
          slots: safeJsonClone((mechanic.slots || []).map((slot) => ({
            ...slot,
            runtimeStatus: postgameBossMechanicBulletSlotRuntimeStatus(slot, player, battle, mechanic),
          }))),
        };
        break;
      case "postgame_saga":
        view.state = { blood: mechanic.blood, max: 75, fused: !!mechanic.fused, threshold: mechanic.blood >= 75 ? 75 : mechanic.blood >= 50 ? 50 : mechanic.blood >= 25 ? 25 : 0 };
        break;
      case "postgame_vinsmoke_judge":
        view.state = { clones: mechanic.clones, maxClones: 3, production: mechanic.production, productionMax: 3 };
        break;
      case "postgame_rob_lucci_awakened":
        view.state = {
          powers: POSTGAME_LUCCI_SIX_POWER_DEFS.map((entry) => ({
            ...entry,
            used: mechanic.nodes.includes(entry.name),
            active: mechanic.nodes.includes(entry.name),
            current: mechanic.activePower === entry.name && Number(mechanic.activePowerRound || 0) === Number(battle.roundIndex || 0),
          })),
          activePower: mechanic.activePower || "",
          activePowerStat: mechanic.activePowerStat || "",
          activePowerEffect: postgameLucciSixPowerDef(mechanic.activePower)?.statLabel
            ? `${postgameLucciSixPowerDef(mechanic.activePower).statLabel}提高 80%`
            : "",
          usedCount: mechanic.nodes.length,
          remainingCount: Math.max(0, POSTGAME_LUCCI_SIX_POWER_DEFS.length - mechanic.nodes.length),
          rokuoganPending: !!mechanic.rokuoganPending,
        };
        break;
      case "postgame_king":
        view.state = { flameOn: !!mechanic.flameOn, vulnerable: !mechanic.flameOn };
        break;
      case "postgame_charlotte_katakuri": {
        const currentActor = postgameKatakuriCurrentPlayer(battle, player) || player;
        const actionKey = postgameKatakuriActionKey(currentActor, battle);
        const currentAction = mechanic.forecastActionKey === actionKey;
        view.state = {
          forecastDie: currentAction ? mechanic.forecastDie : 0,
          forecastRolling: currentAction && !!mechanic.forecastRolling,
          choicePending: currentAction && !!mechanic.choicePending,
          choiceMode: currentAction ? mechanic.choiceMode || "" : "",
          defenseRolling: currentAction && !!mechanic.defenseRolling,
          defenseDie: currentAction ? mechanic.defenseDie : 0,
          defenseReductionPercent: currentAction ? Math.round(Number(mechanic.defenseReduction || 0) * 100) : 0,
          lastPlayerFirstDie: mechanic.lastPlayerFirstDie || 0,
          lastOutcome: mechanic.lastOutcome || "",
        };
        if (!battle.result && currentAction && (mechanic.forecastRolling || mechanic.choicePending || mechanic.defenseRolling)) {
          view.prompt = {
            type: "katakuri_future_sight",
            title: mechanic.forecastRolling ? "預知未來" : mechanic.defenseRolling ? "防禦判定" : `預知骰：${mechanic.forecastDie}`,
            message: mechanic.forecastRolling
              ? "卡塔庫栗正在讀取這次行動……"
              : mechanic.defenseRolling
                ? "正在擲防禦骰；點數乘以 15% 就是本次直接攻擊減傷。"
                : `出招時第一骰低於 ${mechanic.forecastDie}，整招失效並照常消耗 PP；也可放棄出招改為防禦。`,
            forecastDie: mechanic.forecastDie,
            forecastRolling: !!mechanic.forecastRolling,
            defenseRolling: !!mechanic.defenseRolling,
            canChoose: !!mechanic.choicePending && !mechanic.forecastRolling && !mechanic.defenseRolling,
          };
        }
        break;
      }
      case "postgame_patrick_redfield":
        view.state = {
          lastDrainPercent: mechanic.lastDrainPercent || 0,
          lastDrainTotal: mechanic.lastDrainTotal || 0,
          crew: (player.crew || []).map((card, index) => ({ index, name: cardDisplayName(card), portrait: getBattlePortraitUrl(card, "idle"), currentHp: card.currentHp, maxHp: cardMaxHp(card) })),
        };
        break;
      case "postgame_oars": {
        const options = postgameOarsLotteryOptions(player, battle);
        view.state = {
          saltBags: mechanic.saltBags,
          saltTarget: POSTGAME_OARS_SALT_TARGET,
          lockedPredictions: safeJsonClone(mechanic.lockedPredictions || []),
          lastResult: mechanic.lastResult ? safeJsonClone(mechanic.lastResult) : null,
          nextPeriodicSaltIn: Math.max(1, 3 - (Math.max(1, Number(battle.roundIndex || 1)) % 3)),
          purified: !!mechanic.purified,
        };
        if (!battle.result && !mechanic.purified && Number(mechanic.saltBags || 0) >= POSTGAME_OARS_SALT_TARGET) {
          view.prompt = {
            type: "oars_purification",
            title: "巨型鹽彈已完成",
            message: "十五袋巨型鹽已集齊，可以立即解放歐斯體內的影子。",
          };
        } else if (!battle.result && !mechanic.purified && Number(mechanic.saltBags || 0) > 0 && !mechanic.lockedPredictions?.length && mechanic.predictionResolvedKey !== postgameOarsActionKey(player, battle)) {
          view.prompt = {
            type: "oars_lottery",
            title: "鹽袋下注",
            message: `持有 ${mechanic.saltBags} 包；每個選項可自由投入多包，也可以分押不同選項。`,
            availableSaltBags: mechanic.saltBags,
            maxStake: Number(mechanic.saltBags || 0),
            actionKey: postgameOarsActionKey(player, battle),
            options,
          };
        }
        break;
      }
      case "postgame_aramaki":
        view.state = { groves: mechanic.groves, maxGroves: 4, revived: !!mechanic.revived, fireproof: !!mechanic.fireproof };
        break;
      default:
        break;
    }
    return view;
  }

  function postgameBossMechanicActiveBulletSlots(battle) {
    const mechanic = postgameBossMechanicFor(battle);
    if (mechanic?.key !== "postgame_douglas_bullet") return [];
    return (mechanic.slots || []).filter((slot) => slot.itemId && !slot.destroyed).flatMap((slot) => {
      if (slot.itemId !== BULLET_ARSENAL_ITEM_ID) return [slot];
      return [];
    });
  }

  function postgameBossMechanicHasBulletItem(battle, itemId) {
    return postgameBossMechanicActiveBulletSlots(battle).some((slot) => slot.itemId === itemId);
  }

  function postgameBossMechanicBulletItemSlot(battle, itemId) {
    return postgameBossMechanicActiveBulletSlots(battle).find((slot) => slot.itemId === itemId) || null;
  }

  function postgameBossMechanicBulletEffectSlots(battle, effectKind) {
    return postgameBossMechanicActiveBulletSlots(battle).filter((slot) => battleCarryItemEffect(slot.itemId).kind === effectKind);
  }

  function postgameBossMechanicBulletSlotsById(battle, itemId) {
    return postgameBossMechanicActiveBulletSlots(battle).filter((slot) => slot.itemId === itemId);
  }

  function postgameBossMechanicBulletLivingEquippedCrewCount(player, mechanic, excludedCardIndex = -1) {
    return (mechanic?.slots || []).filter((slot) => {
      if (!slot?.itemId || Number(slot.cardIndex) === Number(excludedCardIndex)) return false;
      const owner = player?.crew?.[Math.max(0, Number(slot.cardIndex || 0))];
      return !!owner && Number(owner.currentHp || 0) > 0;
    }).length;
  }

  function postgameBossMechanicRefreshBulletMaxHp(player, battle, mechanic = postgameBossMechanicFor(battle)) {
    if (mechanic?.key !== "postgame_douglas_bullet" || !battle?.enemyCombatant) return;
    const activeBlackFlames = postgameBossMechanicActiveBulletSlots(battle).filter((slot) => battleCarryItemEffect(slot.itemId).kind === "postgame_lucci_black_flame");
    const multiplier = activeBlackFlames.reduce((value, slot) => value * Math.max(1, Number(battleCarryItemEffect(slot.itemId).maxHpMultiplier || 1.3)), 1);
    if (!Number(mechanic.bulletBaseMaxHp || 0)) {
      mechanic.bulletBaseMaxHp = Math.max(1, Math.round(Number(battle.enemyCombatant.maxHp || 1) / Math.max(1, multiplier)));
    }
    const desiredMaxHp = Math.max(1, Math.round(Number(mechanic.bulletBaseMaxHp || 1) * multiplier));
    const previousMaxHp = Math.max(1, Number(battle.enemyCombatant.maxHp || desiredMaxHp));
    if (previousMaxHp === desiredMaxHp) return;
    const hpRatio = Math.max(0, Number(battle.enemyCombatant.currentHp || 0)) / previousMaxHp;
    battle.enemyCombatant.maxHp = desiredMaxHp;
    battle.enemyCombatant.currentHp = Math.max(1, Math.min(desiredMaxHp, Math.round(desiredMaxHp * hpRatio)));
  }

  function postgameBossMechanicInitializeBulletRuntime(player, battle, mechanic = postgameBossMechanicFor(battle)) {
    if (mechanic?.key !== "postgame_douglas_bullet" || !battle?.enemyCombatant) return;
    postgameBossMechanicActiveBulletSlots(battle).forEach((slot) => {
      slot.triggered = slot.triggered && typeof slot.triggered === "object" ? slot.triggered : {};
      const effect = battleCarryItemEffect(slot.itemId);
      if (slot.itemId === "vegapunk_mini_shield" && !Number.isFinite(Number(slot.triggered.miniShieldRemaining))) {
        slot.triggered.miniShieldRemaining = Math.max(1, Math.round(Number(battle.enemyCombatant.maxHp || 1) * .12));
      }
      if (effect.kind === "postgame_tesoro_gold_rings") slot.triggered.goldStacks = Math.max(0, Math.min(Number(effect.requiredStacks || 3), Number(slot.triggered.goldStacks || 0)));
      if (effect.kind === "postgame_zephyr_battle_smasher") slot.triggered.heat = Math.max(0, Math.min(Number(effect.requiredHeat || 3), Number(slot.triggered.heat || 0)));
      if (effect.kind === "postgame_king_sword" && typeof slot.triggered.flameOn !== "boolean") slot.triggered.flameOn = true;
      if (effect.kind === "postgame_loki_ragnir") slot.triggered.clouds = Math.max(0, Math.min(Number(effect.freezeClouds || 3), Number(slot.triggered.clouds || 0)));
      if (effect.kind === "postgame_green_bull_life_seed") {
        slot.triggered.seeds = Math.max(0, Math.min(Number(effect.maxSeeds || 3), Number(slot.triggered.seeds || 0)));
        slot.triggered.greenBullReviveUsed = !!slot.triggered.greenBullReviveUsed;
      }
    });
  }

  function postgameBossMechanicScaleBulletArsenalCarrierHp(player, battle, slot, restore) {
    if (slot?.itemId !== BULLET_ARSENAL_ITEM_ID) return;
    const owner = player?.crew?.[Math.max(0, Number(slot.cardIndex || 0))];
    if (!owner) return;
    const suppressedMaxHp = cardBaseMaxHp(owner);
    const activeMaxHp = cardMaxHpIncludingCarry(owner);
    const fromMaxHp = restore ? suppressedMaxHp : activeMaxHp;
    const toMaxHp = restore ? activeMaxHp : suppressedMaxHp;
    const beforeHp = Math.max(0, Number(owner.currentHp || 0));
    owner.currentHp = beforeHp <= 0
      ? 0
      : Math.max(1, Math.min(toMaxHp, Math.round(beforeHp * toMaxHp / Math.max(1, fromMaxHp))));
  }

  function postgameBossMechanicSealBulletArsenalCarriers(player, battle, mechanic = postgameBossMechanicFor(battle)) {
    if (mechanic?.key !== "postgame_douglas_bullet") return;
    (mechanic.slots || [])
      .filter((slot) => slot.itemId === BULLET_ARSENAL_ITEM_ID && !slot.destroyed)
      .forEach((slot) => postgameBossMechanicScaleBulletArsenalCarrierHp(player, battle, slot, false));
  }

  function postgameBossMechanicRestoreBulletArsenalCarriers(player, battle, mechanic = postgameBossMechanicFor(battle)) {
    if (mechanic?.key !== "postgame_douglas_bullet") return;
    (mechanic.slots || [])
      .filter((slot) => slot.itemId === BULLET_ARSENAL_ITEM_ID && !slot.destroyed)
      .forEach((slot) => postgameBossMechanicScaleBulletArsenalCarrierHp(player, battle, slot, true));
  }

  function postgameBossMechanicBulletSlotRuntimeStatus(slot, player, battle, mechanic) {
    if (!slot?.itemId) return "";
    if (slot.itemId === BULLET_ARSENAL_ITEM_ID) {
      return "空武器庫・內裝兵裝封存中（破孔後生效）";
    }
    const effect = battleCarryItemEffect(slot.itemId);
    const used = slot.triggered || {};
    if (effect.kind === "postgame_judge_germa66_suit") return used.judgeFatalUsed ? "不屈：已發動（本場不可再用）" : "不屈：待命（本場尚未發動）";
    if (effect.kind === "force_advantage_attribute") {
      const defenderAttribute = battleActiveCard(player, battle)?.attribute || "無";
      const counterAttribute = attributeThatCounters(defenderAttribute);
      return counterAttribute ? `九尾幻化：${counterAttribute}屬性克制${defenderAttribute}` : "九尾幻化：等待有效屬性目標";
    }
    if (slot.itemId === "vegapunk_mini_shield") return `護盾 ${Math.max(0, Math.round(Number(used.miniShieldRemaining || 0)))} HP`;
    if (effect.kind === "postgame_tesoro_gold_rings") return `黃金 ${Number(used.goldStacks || 0)}/${Number(effect.requiredStacks || 3)}`;
    if (effect.kind === "postgame_zephyr_battle_smasher") return used.battleSmasherReady ? "過熱完成・下次爆發" : `熱量 ${Number(used.heat || 0)}/${Number(effect.requiredHeat || 3)}`;
    if (effect.kind === "postgame_king_sword") return used.flameOn === false ? "熄火・下次攻擊強化" : "背火・減傷中";
    if (effect.kind === "postgame_loki_ragnir") return `冰雲 ${Number(used.clouds || 0)}/${Number(effect.freezeClouds || 3)}`;
    if (effect.kind === "postgame_green_bull_life_seed") return used.greenBullReviveUsed ? "本場復活已發動" : `種子 ${Number(used.seeds || 0)}/${Number(effect.maxSeeds || 3)}`;
    if (effect.kind === "postgame_saga_seven_star_sword") {
      const hpRate = Number(battle?.enemyCombatant?.currentHp || 0) / Math.max(1, Number(battle?.enemyCombatant?.maxHp || 1));
      const steps = Math.max(0, Math.floor((1 - hpRate + 1e-9) / Math.max(.01, Number(effect.lostHpStep || .1))));
      return `目前增傷 +${Math.round(Math.min(Number(effect.maxDamageBonus || .8), steps * Number(effect.damageBonusPerStep || .04)) * 100)}%`;
    }
    return "";
  }

  function postgameBossMechanicReleaseBulletSlot(player, battle, slot) {
    if (!slot?.itemId || slot.destroyed) return false;
    const ownerIndex = Math.max(0, Number(slot.cardIndex || 0));
    const owner = player?.crew?.[ownerIndex];
    const releasedItems = slot.itemId === BULLET_ARSENAL_ITEM_ID
      ? (slot.arsenalItems || []).filter((entry) => entry.itemId)
      : [{ itemId: slot.itemId, slotIndex: -1, triggered: slot.triggered || {} }];
    releasedItems.forEach((released) => {
      const equipped = battleCarryEquippedEntriesForCard(owner).find((entry) => entry.item.id === released.itemId && Number(entry.slotIndex) === Number(released.slotIndex ?? -1));
      const runtime = owner && equipped
        ? battleCarryStateForEquippedItem(owner, ownerIndex, equipped.item, battle, true, equipped.slotIndex)
        : null;
      const used = released.triggered || {};
      if (!runtime) return;
      Object.entries(used).forEach(([key, value]) => {
        if (Object.prototype.hasOwnProperty.call(runtime, key)) runtime[key] = safeJsonClone(value);
      });
      if (Number(used.storedDamage || 0) > 0) runtime.storedDamage = Number(used.storedDamage || 0);
      if (used.firstGuard) runtime.cloudTriggered = true;
      if (Number.isFinite(Number(used.miniShieldRemaining))) {
        runtime.vegapunkShieldStarted = true;
        runtime.vegapunkShield = Math.max(0, Math.round(Number(used.miniShieldRemaining || 0)));
      } else if (released.itemId === "vegapunk_mini_shield") {
        runtime.vegapunkShieldStarted = true;
        runtime.vegapunkShield = Math.max(1, Math.round(cardMaxHp(owner) * .12));
      }
      if (used.fixedDamage) runtime.seastoneTriggered = true;
      if (used.fatal) {
        if (released.itemId === "going_merry_rescue") runtime.merryRescueTriggered = true;
        else runtime.lifePaperTriggered = true;
      }
      if (used.fatalRound) runtime.focusBandRound = Number(used.fatalRound || 0);
      if (used.healed) runtime.meatTriggered = true;
      if (used.blinded) runtime.flashTriggered = true;
      if (used.reflectRound) runtime.slashReflectedRound = Number(used.reflectRound || 0);
      if (used.desperate) runtime.pirateFlagTriggered = true;
      if (used.medicineTriggered) runtime.medicineTriggered = true;
      if (used.visionTriggered) runtime.visionTriggered = true;
      if (used.lampTriggered) runtime.lampTriggered = true;
      if (used.skyGogglesTriggered) runtime.skyGogglesTriggered = true;
      if (used.whiteHerbTriggered) runtime.whiteHerbTriggered = true;
      if (used.controlClearTriggered) runtime.controlClearTriggered = true;
      if (used.healShellTriggered) runtime.healShellTriggered = true;
      if (used.quickClawTriggered) {
        runtime.quickClawTriggered = true;
        runtime.quickClawRound = Number(used.quickClawRound || battle.roundIndex || 0);
      }
      if (used.permanentPointerMissed) {
        runtime.permanentPointerMissed = true;
        runtime.permanentPointerPrimed = !used.permanentPointerConsumed;
        runtime.permanentPointerConsumed = !!used.permanentPointerConsumed;
      }
    });
    slot.destroyed = true;
    if (slot.itemId === BULLET_ARSENAL_ITEM_ID) postgameBossMechanicScaleBulletArsenalCarrierHp(player, battle, slot, true);
    postgameBossMechanicRefreshBulletMaxHp(player, battle);
    const mechanic = postgameBossMechanicFor(battle);
    if (mechanic?.key === "postgame_douglas_bullet" && !postgameBossMechanicActiveBulletSlots(battle).some((activeSlot) => ["choice_lock_physical_damage", "choice_lock_special_damage", "choice_lock_speed_bonus"].includes(battleCarryItemEffect(activeSlot.itemId).kind))) {
      mechanic.bulletLockedSkillId = "";
    }
    return true;
  }

  function postgameBossMechanicEnemyStat(value, stat, player, battle) {
    const mechanic = postgameBossMechanicFor(battle);
    if (!mechanic) return value;
    let next = Number(value || 1);
    if (mechanic.key === "postgame_shiki" && mechanic.finalDuel) {
      if (stat === "atk" || stat === "satk" || stat === "spd") next *= 1.25;
    }
    if (mechanic.key === "postgame_douglas_bullet") {
      for (const slot of postgameBossMechanicActiveBulletSlots(battle)) {
        const effect = battleCarryItemEffect(slot.itemId);
        if (stat === "spd" && slot.itemId === "wind_dial") next *= 1.15;
        if (stat === "spd" && slot.itemId === "iron_cloud") next *= 0.95;
        if (stat === "spd" && effect.kind === "temporary_speed_multiplier") next *= Number(effect.multiplier || 1.15);
        if (stat === "spd" && effect.kind === "choice_lock_speed_bonus") next *= 1 + Number(effect.speedBonus || .25);
        if (stat === "spd" && effect.kind === "speed_down_damage_reduction") next *= Number(effect.speedMultiplier || 0.75);
        if (stat === "sdef" && effect.kind === "sdef_bonus_block_support_skills") next *= Number(effect.sdefMultiplier || 1.4);
        if (stat === "spd" && effect.kind === "postgame_shiki_oto_kogarashi") next *= Number(effect.speedMultiplier || 1.2);
        if (stat === "atk" && effect.kind === "postgame_shiki_oto_kogarashi") next *= Number(effect.atkMultiplier || 1.2);
        if (stat === "atk" && effect.kind === "zoro_enma") next *= Number(effect.atkMultiplier || 1.15);
        if (stat === "satk" && effect.kind === "postgame_katakuri_mogura") next *= Number(effect.satkMultiplier || 1.3);
        if (stat === "satk" && effect.kind === "postgame_loki_ragnir") next *= Number(effect.satkMultiplier || 1.2);
        if (stat === "spd" && effect.kind === "postgame_lucci_black_flame") next *= Number(effect.speedMultiplier || 1.3);
        if (stat === "atk" && effect.kind === "postgame_rocks_eclipse") next *= Number(effect.atkMultiplier || 1.2);
        if (stat === "satk" && effect.kind === "postgame_rocks_eclipse") next *= Number(effect.satkMultiplier || 1.2);
        if (stat === "spd" && effect.kind === "postgame_king_sword" && slot.triggered?.flameOn === false) next *= Number(effect.unlitSpeedMultiplier || 1.25);
      }
    }
    if (mechanic.key === "postgame_zephyr" && mechanic.phase === 2) {
      if (stat === "def" || stat === "sdef") next *= 0.78;
      if (stat === "atk" || stat === "spd") next *= 1.18;
    }
    if (mechanic.key === "postgame_gild_tesoro") {
      if (Number(mechanic.phase || 1) === 2 && (stat === "atk" || stat === "satk")) next *= 1.12;
      if (Number(mechanic.phase || 1) >= 3 && ["atk", "satk", "spd"].includes(stat)) next *= 1.22;
    }
    if (mechanic.key === "postgame_king" && !mechanic.flameOn) {
      if (stat === "spd") next *= 1.35;
      if (stat === "atk" || stat === "satk") next *= 1.18;
    }
    if (mechanic.key === "postgame_rob_lucci_awakened") {
      const activePower = postgameBossMechanicActiveLucciPower(battle);
      if (activePower?.stat === stat && activePower.stat !== "evasion") next *= POSTGAME_LUCCI_POWER_MULTIPLIER;
    }
    return Math.max(1, Math.round(next));
  }

  function postgameBossMechanicEnemyHitChanceBonus(moveEntry, battle) {
    const mechanic = postgameBossMechanicFor(battle);
    if (mechanic?.key !== "postgame_douglas_bullet") return 0;
    let bonus = 0;
    const player = battlePlayer(null, battle);
    const target = battleActiveCard(player, battle);
    postgameBossMechanicActiveBulletSlots(battle).forEach((slot) => {
      if (slot.itemId === "sniper_king_goggles") bonus += 8;
      if (slot.itemId === "log_pose") bonus += target?.isDevilFruitUser ? 8 : 4;
      if (slot.itemId === "justice_cloak" && target?.isDevilFruitUser) bonus += 8;
      if (slot.itemId === "eternal_pose" && slot.triggered?.permanentPointerPrimed) bonus += 16;
      const effect = battleCarryItemEffect(slot.itemId);
      if (effect.kind === "force_advantage_attribute" && Number(target?.currentStages?.evasion || battle.playerStages?.evasion || 0) > 0) bonus += 8;
    });
    return bonus;
  }

  function postgameBossMechanicScaleHitDamages(hitDamages, multiplier) {
    const source = Array.isArray(hitDamages) ? hitDamages : [];
    const ratio = Math.max(0, Number(multiplier || 0));
    if (!source.length) return source;
    return source.map((damage) => Math.max(0, Math.round(Number(damage || 0) * ratio)));
  }

  function postgameBossMechanicApplyJudgeCloneGuard(hitDamages, mechanic, battle, targetId, visualMeta = null) {
    const adjusted = Array.isArray(hitDamages)
      ? hitDamages.map((damage) => Math.max(0, Math.round(Number(damage || 0))))
      : [];
    const before = Math.max(0, Math.min(3, Math.floor(Number(mechanic?.clones || 0))));
    const blockedHits = adjusted.map(() => false);
    let remaining = before;
    adjusted.forEach((damage, index) => {
      if (damage <= 0 || remaining <= 0) return;
      blockedHits[index] = true;
      adjusted[index] = 0;
      remaining -= 1;
    });
    if (mechanic) mechanic.clones = remaining;
    if (visualMeta && typeof visualMeta === "object") {
      visualMeta.judgeCloneBlocks = blockedHits;
      visualMeta.judgeCloneCountBefore = before;
      visualMeta.judgeCloneCountAfter = remaining;
      visualMeta.judgeCloneTargetId = String(targetId || "boss");
    }
    const destroyed = before - remaining;
    if (destroyed > 0) {
      battle.log.push(destroyed > 1
        ? `Germa 複製兵逐段衝出，替伽治擋下 ${destroyed} 段攻擊；剩餘複製兵 ${remaining}。`
        : `一名 Germa 複製兵衝出替伽治擋下這一擊；剩餘複製兵 ${remaining}。`);
    }
    return String(targetId || "boss") === "judge_clone" ? adjusted.map(() => 0) : adjusted;
  }

  function postgameBossMechanicDestroyGroves(mechanic, count, battle, fireMove = false) {
    const removed = Math.min(Math.max(0, Number(mechanic.groves || 0)), Math.max(0, Number(count || 0)));
    mechanic.groves = Math.max(0, Number(mechanic.groves || 0) - removed);
    if (removed > 0) battle.log.push(`${fireMove ? "火焰燒毀" : "攻擊破壞"} ${removed} 片森林根系；剩餘 ${mechanic.groves}/4。`);
    else battle.log.push("攻擊落在枯萎地面，沒有森林根系可破壞。");
  }

  function postgameBossMechanicBulletIncomingMultiplier(mechanic, battle, playerMove, player) {
    let multiplier = 1;
    const active = postgameBossMechanicActiveBulletSlots(battle);
    const shieldActive = Number(mechanic.bulletOverflowShield || 0) > 0
      || active.some((slot) => slot.itemId === "vegapunk_mini_shield" && Number(slot.triggered?.miniShieldRemaining || 0) > 0)
      || Number(battle.enemyCombatant?.roundEffects?.shieldRatio || 0) > 0;
    const oneShot = (slot, key, ratio) => {
      if (!slot || slot.triggered?.[key]) return false;
      slot.triggered ||= {};
      slot.triggered[key] = true;
      multiplier *= ratio;
      battle.log.push(`巴雷特吸收的${slot.itemName}發動。`);
      return true;
    };
    active.forEach((slot) => {
      const effect = battleCarryItemEffect(slot.itemId);
      slot.triggered ||= {};
      if (slot.itemId === "cloud_dial") oneShot(slot, "firstGuard", .75);
      if (slot.itemId === "justice_cloak") multiplier *= .92;
      if (slot.itemId === "iron_cloud") multiplier *= .9;
      if (slot.itemId === "water_dial" && isFireBattleMove(playerMove)) multiplier *= .8;
      if (effect.kind === "reduce_first_hit_damage") oneShot(slot, "firstGuard", 1 - Math.max(0, Math.min(.9, Number(effect.reduction || .25))));
      if (effect.kind === "speed_down_damage_reduction") multiplier *= 1 - Math.max(0, Math.min(.9, Number(effect.reduction || .12)));
      if (effect.kind === "devil_fruit_suppressor" && battleActiveCard(player, battle)?.isDevilFruitUser) {
        multiplier *= 1 - Math.max(0, Math.min(.9, Number(effect.damageReduction || .2)));
      }
      if (effect.kind === "postgame_shiki_oto_kogarashi") oneShot(slot, "shikiFirstGuard", 1 - Math.max(0, Math.min(.9, Number(effect.firstDirectDamageReduction || .4))));
      if (effect.kind === "postgame_king_sword" && slot.triggered.flameOn !== false) multiplier *= 1 - Math.max(0, Math.min(.9, Number(effect.flameDamageReduction || .25)));
      if (slot.itemId === "opal_cloud" && shieldActive) multiplier *= .9;
    });
    return multiplier;
  }

  function postgameBossMechanicConsumeBulletShields(hitDamages, mechanic, battle) {
    const adjusted = Array.isArray(hitDamages) ? hitDamages.map((value) => Math.max(0, Math.round(Number(value || 0)))) : [];
    const consumePool = (available, update, label) => {
      let remaining = Math.max(0, Math.round(Number(available || 0)));
      const before = remaining;
      if (!remaining) return;
      for (let index = 0; index < adjusted.length && remaining > 0; index += 1) {
        const absorbed = Math.min(adjusted[index], remaining);
        adjusted[index] -= absorbed;
        remaining -= absorbed;
      }
      update(remaining);
      const absorbed = before - remaining;
      if (absorbed > 0) battle.log.push(`${label}吸收了 ${absorbed} 點傷害。`);
    };
    consumePool(mechanic.bulletOverflowShield, (value) => { mechanic.bulletOverflowShield = value; }, "傘劍溢出護盾");
    postgameBossMechanicActiveBulletSlots(battle)
      .filter((slot) => slot.itemId === "vegapunk_mini_shield")
      .forEach((slot) => consumePool(slot.triggered?.miniShieldRemaining, (value) => {
        slot.triggered ||= {};
        slot.triggered.miniShieldRemaining = value;
      }, `${slot.itemName}`));
    return adjusted;
  }

  function postgameBossMechanicBulletComboProgression(hitDamages, battle) {
    const scores = postgameBossMechanicBulletEffectSlots(battle, "postgame_tot_musica_demon_score");
    if (!scores.length || !Array.isArray(hitDamages) || hitDamages.length <= 1) return hitDamages;
    return hitDamages.map((damage, index) => {
      let next = Math.max(0, Number(damage || 0));
      scores.forEach((slot) => {
        const effect = battleCarryItemEffect(slot.itemId);
        const bonus = Math.max(0, Number(effect.firstHitBonus || .01)) * (2 ** index);
        next *= 1 + bonus;
      });
      return Math.max(0, Math.round(next));
    });
  }

  function postgameBossMechanicBulletIgnoreDefenseRatio(battle, moveEntry) {
    const mechanic = postgameBossMechanicFor(battle);
    if (mechanic?.key !== "postgame_douglas_bullet" || !postgameBossMechanicDirectMove(moveEntry)) return 0;
    let remainingDefense = 1;
    postgameBossMechanicBulletEffectSlots(battle, "postgame_zephyr_battle_smasher").forEach((slot) => {
      if (!slot.triggered?.battleSmasherReady) return;
      remainingDefense *= 1 - Math.max(0, Math.min(.85, Number(battleCarryItemEffect(slot.itemId).ignoreDefenseRatio || .2)));
    });
    return Math.max(0, Math.min(.85, 1 - remainingDefense));
  }

  function markBattleCriticalVisual(visualMeta, source = "", hitIndex = null) {
    if (!visualMeta || typeof visualMeta !== "object") return;
    visualMeta.critical = true;
    const parsedHitIndex = Number(hitIndex);
    if (Number.isInteger(parsedHitIndex) && parsedHitIndex >= 0) {
      visualMeta.criticalHitIndexes ||= [];
      if (!visualMeta.criticalHitIndexes.includes(parsedHitIndex)) visualMeta.criticalHitIndexes.push(parsedHitIndex);
      visualMeta.criticalHitIndexes.sort((left, right) => left - right);
      visualMeta.criticalCount = visualMeta.criticalHitIndexes.length;
    } else {
      visualMeta.criticalCount = Math.max(0, Number(visualMeta.criticalCount || 0)) + 1;
    }
    if (source) {
      visualMeta.criticalSources ||= [];
      if (!visualMeta.criticalSources.includes(source)) visualMeta.criticalSources.push(source);
    }
  }

  function markBattleFatalGuardVisual(visualMeta, itemName = "") {
    if (!visualMeta || typeof visualMeta !== "object") return;
    visualMeta.fatalGuard = true;
    visualMeta.fatalGuardLabel = "不屈";
    visualMeta.fatalGuardItemName = String(itemName || "傑爾馬66戰鬥服");
  }

  function postgameBossMechanicTriggerBulletJudgeFatalGuard(player, battle, mechanic, visualMeta = null) {
    if (mechanic?.key !== "postgame_douglas_bullet") return null;
    const judgeSlot = postgameBossMechanicBulletEffectSlots(battle, "postgame_judge_germa66_suit")
      .find((slot) => !slot.triggered?.judgeFatalUsed);
    if (!judgeSlot) return null;
    judgeSlot.triggered ||= {};
    judgeSlot.triggered.judgeFatalUsed = true;
    const effect = battleCarryItemEffect(judgeSlot.itemId);
    applyStageSet(battle.enemyCombatant.stages, effect.selfStages || { def: 1, spd: 1 }, 0, battle.enemyCombatant.stageTurns, 99);
    markBattleFatalGuardVisual(visualMeta, judgeSlot.itemName);
    battle.log.push(`巴雷特吸收的${judgeSlot.itemName}發動「不屈」，完全抵銷這次致命傷，防禦與速度提升。`);
    return judgeSlot;
  }

  function postgameBossMechanicBulletOutgoingMultiplier(mechanic, battle, moveEntry, diceFace, player, visualMeta = null) {
    const active = postgameBossMechanicActiveBulletSlots(battle);
    let multiplier = 1;
    active.forEach((slot) => {
      const effect = battleCarryItemEffect(slot.itemId);
      slot.triggered ||= {};
      if (slot.itemId === "flame_dial" && isFireBattleMove(moveEntry)) multiplier *= 1.1;
      if (slot.itemId === "water_dial" && isWaterBattleMove(moveEntry)) multiplier *= 1.1;
      if (slot.itemId === "ammo_pouch" && isShootingBattleMove(moveEntry)) multiplier *= 1.08;
      if (effect.kind === "choice_lock_physical_damage" && boardMoveIsPhysicalDamage(moveEntry)) multiplier *= 1 + Number(effect.damageBonus || .25);
      if (effect.kind === "choice_lock_special_damage" && boardMoveIsSpecialDamage(moveEntry)) multiplier *= 1 + Number(effect.damageBonus || .25);
      if (effect.kind === "move_late_damage_bonus") multiplier *= 1 + Number(effect.damageBonus || .15);
      if (effect.kind === "damage_bonus_with_self_damage") multiplier *= 1 + Number(effect.damageBonus || .3);
      if (effect.kind === "same_skill_damage_stack") {
        if (slot.triggered.lastSkillId === moveEntry.id) slot.triggered.stackCount = Math.min(4, Number(slot.triggered.stackCount || 0) + 1);
        else slot.triggered.stackCount = 0;
        slot.triggered.lastSkillId = moveEntry.id;
        multiplier *= 1 + Math.min(Number(effect.maxBonus || .4), Number(slot.triggered.stackCount || 0) * Number(effect.stackBonus || .1));
      }
      if (effect.kind === "skill_tag_damage_bonus_and_status_chance") {
        const matched = effect.skillTag === "fire" ? isFireBattleMove(moveEntry) : effect.skillTag === "thunder" ? /雷|電|閃|thunder|lightning/i.test(moveSearchText(moveEntry)) : false;
        if (matched) multiplier *= 1 + Number(effect.damageBonus || .15);
      }
      if (effect.kind === "sound_skill_bonus_and_satk_once" && isSoundBattleMove(moveEntry)) multiplier *= 1 + Number(effect.damageBonus || .2);
      if (effect.kind === "devil_fruit_suppressor" && battleActiveCard(player, battle)?.isDevilFruitUser) multiplier *= 1 + Number(effect.damageBonus || .2);
      if (effect.kind === "skip_charge_once" && !slot.triggered.powerHerbUsed && postgameBossMechanicDirectMove(moveEntry)) multiplier *= 1 + Number(effect.fallbackDamageBonus || .15);
      if (effect.kind === "postgame_saga_seven_star_sword") {
        const hpRate = Number(battle.enemyCombatant.currentHp || 0) / Math.max(1, Number(battle.enemyCombatant.maxHp || 1));
        const steps = Math.max(0, Math.floor((1 - hpRate + 1e-9) / Math.max(.01, Number(effect.lostHpStep || .1))));
        multiplier *= 1 + Math.min(Number(effect.maxDamageBonus || .8), steps * Number(effect.damageBonusPerStep || .04));
      }
      if (effect.kind === "postgame_zephyr_battle_smasher" && slot.triggered.battleSmasherReady) multiplier *= 1 + Number(effect.damageBonus || .4);
      if (effect.kind === "postgame_king_sword" && slot.triggered.flameOn === false) multiplier *= 1 + Number(effect.nextDirectDamageBonus || .25);
      if (effect.kind === "postgame_loki_ragnir" && Number(diceFace || 0) >= Number(effect.highDiceMinimum || 5)) {
        multiplier *= 1 + Math.max(0, Number(slot.triggered.clouds || 0)) * Number(effect.damageBonusPerCloud || .15);
      }
    });
    return multiplier;
  }

  function applyPostgameBossDamageRules(hitDamages, side, moveEntry, diceFace, player, battle, action = {}, visualMeta = null) {
    const mechanic = postgameBossMechanicFor(battle);
    if (!mechanic) return hitDamages;
    let adjusted = Array.isArray(hitDamages) ? hitDamages.slice() : [];
    if (side === "player") {
      const targetId = String(action?.targetId || "boss");
      if (mechanic.key === "postgame_zephyr" && targetId === "boss" && postgameBossMechanicDirectMove(moveEntry)) {
        if (Number(mechanic.phase || 1) === 1) {
          const hpFloor = Math.max(1, Math.round(Number(battle.enemyCombatant?.maxHp || 1) * POSTGAME_ZEPHYR_PHASE_TWO_HP_RATIO));
          const allowedDamage = Math.max(0, Number(battle.enemyCombatant?.currentHp || 0) - hpFloor);
          const requestedDamage = battleDamageHitTotal(adjusted);
          if (requestedDamage > allowedDamage) {
            adjusted = adjustBattleHitDamagesToTotal(adjusted, allowedDamage);
            battle.log.push("Battle Smasher 擋住致命衝擊；澤法將在半血時卸下重臂，進入黑腕決戰。");
          }
        } else {
          const activeCard = battleActiveCard(player, battle);
          const crewKey = postgameBossMechanicCrewKey(activeCard, battle.activeCrewIndex);
          if (mechanic.lastMoveByCrew?.[crewKey] === moveEntry.id) {
            adjusted = postgameBossMechanicScaleHitDamages(adjusted, POSTGAME_ZEPHYR_REPEAT_DAMAGE_RATIO);
            battle.log.push(`教官的看破：澤法看穿 ${moveEntry.name}，重複招式傷害只保留 ${Math.round(POSTGAME_ZEPHYR_REPEAT_DAMAGE_RATIO * 100)}%。`);
          }
        }
      }
      if (mechanic.key === "postgame_shiki") {
        const targetedIsland = postgameShikiIslandForTarget(mechanic, targetId);
        if (targetedIsland) {
          let islandDamage = 0;
          const islandHitDamages = [];
          const islandHitTargetIds = [];
          const islandHitTargetNames = [];
          const islandHitDestroyed = [];
          const islandBreaks = [];
          const islandVisualIslands = (mechanic.islands || []).map((island) => ({
            id: island.id,
            name: island.name,
            effect: island.effect,
            image: island.image,
            brokenImage: island.brokenImage,
            maxHp: island.maxHp,
            currentHp: island.currentHp,
            destroyed: !!island.destroyed,
          }));
          let currentIsland = targetedIsland;
          const bossDamages = adjusted.map((damage) => {
            const rawDamage = Math.max(0, Number(damage || 0));
            if (currentIsland?.destroyed || Number(currentIsland?.currentHp || 0) <= 0) {
              currentIsland = postgameShikiNextLivingIsland(mechanic, currentIsland?.id || targetedIsland.id);
            }
            if (rawDamage <= 0) {
              islandHitDamages.push(0);
              islandHitTargetIds.push(currentIsland?.id || "");
              islandHitTargetNames.push(currentIsland?.name || "");
              islandHitDestroyed.push(false);
              return 0;
            }
            if (!currentIsland) {
              islandHitDamages.push(0);
              islandHitTargetIds.push("");
              islandHitTargetNames.push("");
              islandHitDestroyed.push(false);
              return rawDamage;
            }
            const hitIsland = currentIsland;
            const appliedToIsland = Math.min(rawDamage, Number(hitIsland.currentHp || 0));
            hitIsland.currentHp = Math.max(0, Number(hitIsland.currentHp || 0) - appliedToIsland);
            islandDamage += appliedToIsland;
            islandHitDamages.push(appliedToIsland);
            islandHitTargetIds.push(hitIsland.id);
            islandHitTargetNames.push(hitIsland.name);
            const overflow = Math.max(0, rawDamage - appliedToIsland);
            const destroyedByHit = Number(hitIsland.currentHp || 0) <= 0 && !hitIsland.destroyed;
            islandHitDestroyed.push(destroyedByHit);
            if (destroyedByHit) {
              hitIsland.currentHp = 0;
              hitIsland.destroyed = true;
              islandBreaks.push({
                islandId: hitIsland.id,
                islandName: hitIsland.name,
                brokenImage: hitIsland.brokenImage,
                hitIndex: islandHitDamages.length - 1,
              });
              mechanic.rotationCursor = Math.max(0, (mechanic.islands || []).findIndex((island) => island.id === hitIsland.id));
              currentIsland = postgameShikiNextLivingIsland(mechanic, hitIsland.id);
              mechanic.activeIslandId = currentIsland?.id || "";
              mechanic.awaitingRotation = false;
            }
            return Math.max(0, Math.round(appliedToIsland * POSTGAME_SHIKI_ISLAND_PIERCE_RATIO) + overflow);
          });
          const bossDamage = battleDamageHitTotal(bossDamages);
          if (islandDamage > 0) {
            const attackedNames = [...new Set(islandHitTargetNames.filter(Boolean))];
            battle.log.push(`${attackedNames.join("、") || targetedIsland.name}合計承受 ${islandDamage} 點傷害，${bossDamage} 點貫穿史基。`);
            if (visualMeta) {
              visualMeta.shikiIslandId = targetedIsland.id;
              visualMeta.shikiIslandName = targetedIsland.name;
              visualMeta.shikiIslandDamage = islandDamage;
              visualMeta.shikiIslandHitDamages = islandHitDamages.slice();
              visualMeta.shikiIslandHitTargetIds = islandHitTargetIds.slice();
              visualMeta.shikiIslandHitTargetNames = islandHitTargetNames.slice();
              visualMeta.shikiIslandHitDestroyed = islandHitDestroyed.slice();
              visualMeta.shikiIslandBreaks = safeJsonClone(islandBreaks);
              visualMeta.shikiIslandVisualIslands = safeJsonClone(islandVisualIslands);
            }
          }
          if (islandBreaks.length) {
            mechanic.exposedActions = 1;
            const lastBreak = islandBreaks[islandBreaks.length - 1];
            postgameShikiSetEvent(mechanic, {
              type: "break",
              islandId: lastBreak.islandId,
              islandName: lastBreak.islandName,
              image: lastBreak.brokenImage,
            });
            if (visualMeta) visualMeta.shikiIslandDestroyed = true;
            islandBreaks.forEach((entry, index) => {
              const nextTarget = islandHitTargetNames.slice(entry.hitIndex + 1).find(Boolean);
              battle.log.push(`${entry.islandName}崩解墜落！${nextTarget ? `連擊剩餘段數自動轉攻${nextTarget}。` : "下一次直接攻擊史基的傷害 +50%。"}`);
            });
            if ((mechanic.islands || []).every((island) => island.destroyed)) postgameShikiEnterFinalDuel(battle, mechanic);
          }
          return bossDamages;
        }
        if (targetId === "boss") {
          if (Number(mechanic.exposedActions || 0) > 0 && adjusted.some((damage) => Number(damage || 0) > 0)) {
            adjusted = postgameBossMechanicScaleHitDamages(adjusted, 1.5);
            mechanic.exposedActions = Math.max(0, Number(mechanic.exposedActions || 0) - 1);
            battle.log.push("漂浮島崩解形成破綻：這次直接攻擊史基的傷害 +50%。");
          }
          const livingIslands = postgameShikiLivingIslands(mechanic);
          if (livingIslands.length) {
            const lionAlive = livingIslands.some((island) => island.id === "lion");
            const shieldRatio = lionAlive ? POSTGAME_SHIKI_LION_DIRECT_DAMAGE_RATIO : POSTGAME_SHIKI_DIRECT_DAMAGE_RATIO;
            adjusted = postgameBossMechanicScaleHitDamages(adjusted, shieldRatio);
            battle.log.push(`${lionAlive ? "岩獅島的壁壘" : "漂浮群島"}正在護航，直接攻擊史基只保留 ${Math.round(shieldRatio * 100)}% 傷害。`);
          }
        }
      }
      if (mechanic.key === "postgame_vinsmoke_judge") {
        adjusted = postgameBossMechanicApplyJudgeCloneGuard(adjusted, mechanic, battle, targetId, visualMeta);
      }
      if (mechanic.key === "postgame_gild_tesoro" && targetId === "boss") {
        if (Number(mechanic.phase || 1) === 2) {
          adjusted = postgameBossMechanicScaleHitDamages(adjusted, POSTGAME_TESORO_GOLDEN_DAMAGE_RATIO);
          battle.log.push(`Golden Tesoro 的巨體防禦生效，這次傷害保留 ${Math.round(POSTGAME_TESORO_GOLDEN_DAMAGE_RATIO * 100)}%。`);
        }
      }
      if (mechanic.key === "postgame_aramaki" && targetId === "aramaki_grove") {
        const fireMove = isFireBattleMove(moveEntry);
        const amount = fireMove && !mechanic.fireproof ? 2 : Number(diceFace || 0) >= 5 ? 2 : 1;
        postgameBossMechanicDestroyGroves(mechanic, amount, battle, fireMove && !mechanic.fireproof);
        return adjusted.map(() => 0);
      }
      if (mechanic.key === "postgame_king" && mechanic.flameOn) {
        adjusted = postgameBossMechanicScaleHitDamages(adjusted, 0.1);
        if (visualMeta && typeof visualMeta === "object") {
          visualMeta.kingFlameGuarded = true;
          visualMeta.kingFlameGuardLabel = "火焰防護";
        }
        battle.log.push("露娜利亞背火點燃，KING 幾乎完全擋下這次傷害。");
      }
      if (mechanic.key === "postgame_douglas_bullet") {
        mechanic.bulletHpBeforeHit = Number(battle.enemyCombatant.currentHp || 0);
        mechanic.bulletFullHpBeforeHit = Number(battle.enemyCombatant.currentHp || 0) >= Number(battle.enemyCombatant.maxHp || 1);
        adjusted = postgameBossMechanicScaleHitDamages(adjusted, postgameBossMechanicBulletIncomingMultiplier(mechanic, battle, moveEntry, player));
        adjusted = postgameBossMechanicConsumeBulletShields(adjusted, mechanic, battle);
        const incomingDamage = battleDamageHitTotal(adjusted);
        if (incomingDamage > 0 && incomingDamage >= Number(battle.enemyCombatant.currentHp || 0)
          && postgameBossMechanicTriggerBulletJudgeFatalGuard(player, battle, mechanic, visualMeta)) {
          adjusted = adjusted.map(() => 0);
        }
      }
    } else {
      if (mechanic.key === "postgame_shiki" && postgameShikiLivingIslands(mechanic).some((island) => island.id === "beast")) {
        adjusted = postgameBossMechanicScaleHitDamages(adjusted, 1.15);
        battle.log.push("獸王島發動猛獸追獵，史基的直接傷害 +15%。");
      }
      if (mechanic.key === "postgame_saga") {
        const multiplier = mechanic.blood >= 75 ? 1.5 : mechanic.blood >= 50 ? 1.3 : mechanic.blood >= 25 ? 1.15 : 1;
        adjusted = postgameBossMechanicScaleHitDamages(adjusted, multiplier);
      }
      if (mechanic.key === "postgame_king" && !mechanic.flameOn) adjusted = postgameBossMechanicScaleHitDamages(adjusted, 1.2);
      if (mechanic.key === "postgame_charlotte_katakuri") {
        const currentActor = postgameKatakuriCurrentPlayer(battle, player) || player;
        const actionKey = postgameKatakuriActionKey(currentActor, battle);
        const reduction = mechanic.defenseActionKey === actionKey
          ? Math.max(0, Math.min(0.9, Number(mechanic.defenseReduction || 0)))
          : 0;
        if (reduction > 0 && adjusted.some((damage) => Number(damage || 0) > 0)) {
          adjusted = postgameBossMechanicScaleHitDamages(adjusted, 1 - reduction);
          if (visualMeta && typeof visualMeta === "object") {
            visualMeta.katakuriDefenseActive = true;
            visualMeta.katakuriDefensePercent = Math.round(reduction * 100);
          }
          if (mechanic.defenseAppliedActionKey !== actionKey) {
            mechanic.defenseAppliedActionKey = actionKey;
            battle.log.push(`防禦骰 ${mechanic.defenseDie} 生效：卡塔庫栗本次直接攻擊傷害減少 ${Math.round(reduction * 100)}%。`);
          }
        }
      }
      if (mechanic.key === "postgame_douglas_bullet") {
        adjusted = postgameBossMechanicScaleHitDamages(adjusted, postgameBossMechanicBulletOutgoingMultiplier(mechanic, battle, moveEntry, diceFace, player, visualMeta));
        adjusted = postgameBossMechanicBulletComboProgression(adjusted, battle);
        const kyubiSlots = postgameBossMechanicBulletEffectSlots(battle, "force_advantage_attribute");
        const defenderAttribute = battleActiveCard(player, battle)?.attribute || "無";
        const counterAttribute = attributeThatCounters(defenderAttribute);
        if (kyubiSlots.length && counterAttribute && adjusted.some((damage) => Number(damage || 0) > 0)) {
          kyubiSlots.forEach((slot) => {
            slot.triggered ||= {};
            slot.triggered.kyubiMaskRound = Number(battle.roundIndex || 0);
            slot.triggered.kyubiMaskTargetAttribute = defenderAttribute;
            slot.triggered.kyubiMaskAttackAttribute = counterAttribute;
          });
          if (visualMeta && typeof visualMeta === "object") {
            visualMeta.kyubiMaskActive = true;
            visualMeta.kyubiMaskLabel = `九尾幻化・${counterAttribute}剋${defenderAttribute}`;
          }
          battle.log.push(`巴雷特吸收的戴彭九尾幻面發動「九尾幻化」：攻擊轉為${counterAttribute}屬性，克制${defenderAttribute}，屬性傷害倍率 x2。`);
        }
      }
    }
    return adjusted;
  }

  function postgameTesoroQueuePhase(mechanic, battle, phase) {
    if (mechanic?.key !== "postgame_gild_tesoro") return false;
    const nextPhase = 2;
    if (Number(mechanic.phase || 1) >= nextPhase || Number(mechanic.pendingPhase || 0) >= nextPhase) return false;
    mechanic.pendingPhase = nextPhase;
    return true;
  }

  function postgameTesoroSetControl(player, battle, card, index, delta) {
    const mechanic = postgameBossMechanicFor(battle);
    if (mechanic?.key !== "postgame_gild_tesoro" || !card || Number(mechanic.phase || 1) >= 3) return 0;
    const key = postgameBossMechanicCrewKey(card, index);
    const before = Math.max(0, Math.min(3, Number(mechanic.goldByCrew?.[key] ?? mechanic.controlByCrew?.[key] ?? 0)));
    if (Number(card.currentHp || 0) <= 0) return before;
    const after = Math.max(0, Math.min(3, before + Math.max(0, Number(delta || 0))));
    mechanic.controlByCrew ||= {};
    mechanic.goldByCrew ||= {};
    mechanic.controlByCrew[key] = after;
    mechanic.goldByCrew[key] = after;
    if (after !== before) {
      battle.log.push(`${cardDisplayName(card)} 的金流淹沒 ${before}/3 → ${after}/3。`);
    }

    if (after >= 3) {
      if (Number(index) === Number(battle.activeCrewIndex) && !mechanic.forcedSwitch?.pending) {
        const candidates = livingCrewIndices(player).filter((crewIndex) => crewIndex !== Number(index));
        if (candidates.length) {
          mechanic.forcedSwitch = {
            pending: true,
            fromIndex: Number(index),
            cardName: cardDisplayName(card),
          };
          mechanic.cancelQueuedPlayerAction = false;
          battle.needsReplacement = true;
          battle.result = "replacement";
          battle.replacementAfterAction = true;
          battle.replacementReason = "tesoro-gold";
          battle.pendingReplacementActiveCrewIndex = Number(index);
          battle.log.push(`${cardDisplayName(card)} 被三段金流完全淹沒；本回合立刻選擇替補，原本尚未執行的指令取消。`);
        } else {
          mechanic.controlByCrew[key] = 0;
          mechanic.goldByCrew[key] = 0;
          mechanic.skipNextAction = true;
          battle.log.push(`${cardDisplayName(card)} 沒有可替補夥伴；本輪指令取消，金流退去後下一次行動仍被封住。`);
        }
      }
    }
    return after;
  }

  function postgameBossMechanicGainSagaBlood(player, battle, amount, sourceLabel = "直接傷害") {
    const mechanic = postgameBossMechanicFor(battle);
    if (mechanic?.key !== "postgame_saga" || amount <= 0) return;
    const before = Number(mechanic.blood || 0);
    mechanic.blood = Math.max(0, Math.min(75, before + Math.max(1, Math.round(amount))));
    if (mechanic.blood !== before) battle.log.push(`七星劍由${sourceLabel}吸收鮮血，血祭值 ${before} → ${mechanic.blood}。`);
    if (mechanic.blood >= 75 && !mechanic.fused) {
      mechanic.fused = true;
      battle.log.push("七星劍血祭值到達 75，正式融入薩卡身體；完全融合形態出現。");
      const beforePortrait = battle.enemyCombatant?.battlePortraits?.normal
        || battle.enemyCombatant?.battlePortraits?.idle
        || "images/board/battle/enemies/postgame_saga/normal.webp";
      const phasePortrait = "images/board/battle/enemies/postgame_saga/fused_normal.webp";
      const fusionVisualKey = `postgame-saga-fusion:${battle.islandId || battle.postgameBossKey || "battle"}`;
      battle.openingPassiveVisualQueue = Array.isArray(battle.openingPassiveVisualQueue) ? battle.openingPassiveVisualQueue : [];
      battle.openingPassiveVisualPlayed = battle.openingPassiveVisualPlayed && typeof battle.openingPassiveVisualPlayed === "object"
        ? battle.openingPassiveVisualPlayed
        : {};
      if (!battle.openingPassiveVisualPlayed[fusionVisualKey] && !battle.openingPassiveVisualQueue.some((event) => event.key === fusionVisualKey)) {
        battle.openingPassiveVisualQueue.push({
          id: `postgame-saga-fusion-${Date.now()}-${Math.random().toString(36).slice(2)}`,
          key: fusionVisualKey,
          type: "postgame-saga-fusion",
          side: "enemy",
          actorName: battle.enemyCombatant?.name || "薩卡",
          title: "血祭值 75／75",
          stageText: "七星劍吸滿鮮血",
          fusionText: "七星劍融入薩卡身體",
          resultText: "完全融合・最終形態",
          effectText: "直接攻擊傷害 +50%",
          targetSide: "enemy",
          moveType: "buff",
          beforePortrait,
          finalPortrait: phasePortrait,
          swordImage: "images/board/items/postgame_boss_relics/saga_seven_star_sword.webp",
          duration: 6200,
        });
      }
      battle.enemyCombatant.battlePortraits = {
        ...(battle.enemyCombatant.battlePortraits || {}),
        normal: phasePortrait,
        idle: phasePortrait,
        morale: phasePortrait,
      };
    }
  }

  function postgameBossMechanicAfterDirectHit(side, moveEntry, diceFace, actualDamage, player, battle, action = {}) {
    const mechanic = postgameBossMechanicFor(battle);
    if (!mechanic) return;
    if (side === "player") {
      if (mechanic.key === "postgame_gild_tesoro" && actualDamage > 0) {
        const hpRate = Number(battle.enemyCombatant?.currentHp || 0) / Math.max(1, Number(battle.enemyCombatant?.maxHp || 1));
        if (Number(mechanic.phase || 1) === 1 && hpRate <= 0.5) postgameTesoroQueuePhase(mechanic, battle, 2);
      }
      if (mechanic.key === "postgame_zephyr" && Number(mechanic.phase || 1) === 1) {
        const hpRate = Number(battle.enemyCombatant?.currentHp || 0) / Math.max(1, Number(battle.enemyCombatant?.maxHp || 1));
        if (hpRate <= POSTGAME_ZEPHYR_PHASE_TWO_HP_RATIO) postgameBossMechanicActivateZephyrPhaseTwo(battle, "half-hp");
      }
      if (mechanic.key === "postgame_douglas_bullet" && postgameBossMechanicDirectMove(moveEntry)) {
        const struckSlot = (mechanic.slots || [])[Math.max(0, Math.min(5, Number(diceFace || 1) - 1))];
        if (actualDamage > 0) {
        for (const impactSlot of postgameBossMechanicBulletSlotsById(battle, "impact_dial")) {
          impactSlot.triggered ||= {};
          impactSlot.triggered.storedDamage = Math.max(Number(impactSlot.triggered.storedDamage || 0), Math.round(actualDamage * 0.5));
          battle.log.push(`衝擊貝記錄了 ${impactSlot.triggered.storedDamage} 點反擊能量。`);
        }
        for (const rejectSlot of postgameBossMechanicBulletSlotsById(battle, "reject_dial")) {
          rejectSlot.triggered ||= {};
          rejectSlot.triggered.storedDamage = Math.max(Number(rejectSlot.triggered.storedDamage || 0), Math.round(actualDamage * 0.7));
          battle.log.push(`排擊貝記錄了 ${rejectSlot.triggered.storedDamage} 點高風險反擊能量。`);
        }
        for (const slashSlot of postgameBossMechanicBulletSlotsById(battle, "slash_dial")) {
          if (Number(slashSlot.triggered?.reflectRound || 0) === Number(battle.roundIndex || 0)) continue;
          slashSlot.triggered ||= {};
          slashSlot.triggered.reflectRound = Number(battle.roundIndex || 0);
          const card = battleActiveCard(player, battle);
          const reflected = Math.min(Math.max(0, Number(card.currentHp || 0) - 1), Math.max(1, Math.round(actualDamage * 0.12)));
          card.currentHp = Math.max(0, Number(card.currentHp || 0) - reflected);
          battle.log.push(`斬擊貝反彈 ${reflected} 點傷害給 ${cardDisplayName(card)}。`);
        }
        const flashSlot = postgameBossMechanicBulletSlotsById(battle, "flash_dial").find((slot) => !slot.triggered?.blinded);
        if (flashSlot) {
          flashSlot.triggered ||= {};
          flashSlot.triggered.blinded = true;
          applyStageSet(battle.playerStages, { accuracy: -1 }, 0, battle.playerStageTurns, 3);
          battle.log.push("閃光貝在首次受擊時爆閃，我方命中下降。");
        }
        const hpRate = Number(battle.enemyCombatant.currentHp || 0) / Math.max(1, Number(battle.enemyCombatant.maxHp || 1));
        const meatSlot = postgameBossMechanicBulletSlotsById(battle, "water_meat").find((slot) => !slot.triggered?.healed);
        if (meatSlot && hpRate < 0.5 && !meatSlot.triggered?.healed) {
          meatSlot.triggered ||= {};
          meatSlot.triggered.healed = true;
          const before = Number(battle.enemyCombatant.currentHp || 0);
          battle.enemyCombatant.currentHp = Math.min(battle.enemyCombatant.maxHp, before + Math.round(battle.enemyCombatant.maxHp * 0.25));
          battle.log.push(`水水肉緊急回復 ${battle.enemyCombatant.currentHp - before} HP。`);
        }
        const flagSlot = postgameBossMechanicBulletSlotsById(battle, "pirate_flag_charm").find((slot) => !slot.triggered?.desperate);
        if (flagSlot && hpRate < 0.3 && !flagSlot.triggered?.desperate) {
          flagSlot.triggered ||= {};
          flagSlot.triggered.desperate = true;
          applyStageSet(battle.enemyCombatant.stages, { atk: 1, accuracy: 1 }, 0, battle.enemyCombatant.stageTurns, 99);
          battle.log.push("海賊旗護符在逆境中發動，巴雷特的攻擊與命中提升。");
        }
        for (const genericSlot of postgameBossMechanicActiveBulletSlots(battle)) {
          const effect = battleCarryItemEffect(genericSlot.itemId);
          genericSlot.triggered ||= {};
          if (effect.kind === "store_damage_counter" && Number(genericSlot.triggered.storedDamage || 0) <= 0) {
            genericSlot.triggered.storedDamage = Math.max(1, Math.round(actualDamage * Number(effect.storeRate || .3)));
            battle.log.push(`${genericSlot.itemName}儲存了 ${genericSlot.triggered.storedDamage} 點反擊能量。`);
          }
          if (effect.kind === "reflect_damage_on_melee_hit" && !isShootingBattleMove(moveEntry) && Number(genericSlot.triggered.reflectRound || 0) !== Number(battle.roundIndex || 0)) {
            genericSlot.triggered.reflectRound = Number(battle.roundIndex || 0);
            const card = battleActiveCard(player, battle);
            const reflected = Math.min(Math.max(0, Number(card.currentHp || 0) - 1), Math.max(1, Math.round(cardMaxHp(card) * Number(effect.attackerMaxHpPercent || .08))));
            card.currentHp = Math.max(1, Number(card.currentHp || 0) - reflected);
            battle.log.push(`${genericSlot.itemName}刺傷攻擊者，反彈 ${reflected} 點傷害。`);
          }
          if (effect.kind === "record_first_single_target_skill_then_counter" && !genericSlot.triggered.visionShellTriggered) {
            genericSlot.triggered.visionShellTriggered = true;
            const card = battleActiveCard(player, battle);
            const counter = Math.min(Math.max(0, Number(card.currentHp || 0) - 1), Math.max(1, Math.round(actualDamage * Number(effect.counterPowerRate || .5))));
            card.currentHp = Math.max(1, Number(card.currentHp || 0) - counter);
            battle.log.push(`${genericSlot.itemName}記錄攻擊並反擊 ${counter} 點傷害。`);
          }
          if (effect.kind === "force_attacker_switch_once" && !genericSlot.triggered.redCardTriggered) {
            genericSlot.triggered.redCardTriggered = true;
            applyStageSet(battle.playerStages, { spd: -1, accuracy: -1 }, 0, battle.playerStageTurns, 2);
            battle.log.push(`${genericSlot.itemName}干擾攻擊者，使我方速度與命中下降。`);
          }
          if (effect.kind === "boost_when_hit_by_weakness" && !genericSlot.triggered.weaknessPolicyTriggered) {
            const attackAttribute = moveEntry.attribute || battleActiveCard(player, battle)?.attribute;
            if (attributeModifier(attackAttribute, battle.enemyCombatant.attribute, 1) > 1) {
              genericSlot.triggered.weaknessPolicyTriggered = true;
              applyStageSet(battle.enemyCombatant.stages, effect.statStages || { atk: 2, satk: 2 }, 0, battle.enemyCombatant.stageTurns, 3);
              battle.log.push(`${genericSlot.itemName}因弱點受擊啟動，巴雷特的攻擊能力大幅提升。`);
            }
          }
        }
        postgameBossMechanicBulletEffectSlots(battle, "postgame_king_sword").forEach((slot) => {
          slot.triggered ||= {};
          if (slot.triggered.flameOn === false) return;
          slot.triggered.flameOn = false;
          battle.log.push(`${slot.itemName}背火熄滅；巴雷特的速度與下一次直接攻擊獲得強化。`);
        });
        }
        if (struckSlot?.itemId && !struckSlot.destroyed) {
          postgameBossMechanicReleaseBulletSlot(player, battle, struckSlot);
          battle.log.push(`骰出 ${diceFace}，巴雷特的「${struckSlot.label}」裝甲破壞；${struckSlot.itemName}在本次命中效果結算後回到${struckSlot.cardName}。`);
        } else {
          battle.log.push(`骰出 ${diceFace}，對應「${struckSlot?.label || "未知"}」孔位為空或已破壞，沒有其他裝甲受到影響。`);
        }
      }
    } else {
      const activeCard = battleActiveCard(player, battle);
      if (mechanic.key === "postgame_saga" && actualDamage > 0) {
        postgameBossMechanicGainSagaBlood(player, battle, (actualDamage / Math.max(1, cardMaxHp(activeCard))) * 100, "直接傷害");
        if (Number(battleStatusBag("player", battle)?.bleed || 0) > 0) mechanic.bleedSources[postgameBossMechanicCrewKey(activeCard, battle.activeCrewIndex)] = true;
      }
      if (mechanic.key === "postgame_patrick_redfield" && actualDamage > 0) {
        const percent = Math.max(1, Math.min(6, Number(diceFace || 1)));
        let total = 0;
        (player.crew || []).forEach((card) => {
          if (!card || Number(card.currentHp || 0) <= 0) return;
          const loss = Math.min(Math.max(0, Number(card.currentHp || 0) - 1), Math.max(1, Math.round(cardMaxHp(card) * percent / 100)));
          card.currentHp = Math.max(1, Number(card.currentHp || 0) - loss);
          total += loss;
        });
        const before = Number(battle.enemyCombatant.currentHp || 0);
        battle.enemyCombatant.currentHp = Math.min(Number(battle.enemyCombatant.maxHp || 1), before + total);
        mechanic.lastDrainPercent = percent;
        mechanic.lastDrainTotal = total;
        battle.log.push(`全隊生命掠奪 ${percent}%：所有存活船員合計失去 ${total} HP，雷德菲爾德回復 ${battle.enemyCombatant.currentHp - before} HP。`);
      }
      if (mechanic.key === "postgame_zephyr" && moveEntry.id === "postgame_zephyr_seastone_bullet" && actualDamage > 0 && activeCard?.isDevilFruitUser) {
        mechanic.seaStoneSkipByCrew[postgameBossMechanicCrewKey(activeCard, battle.activeCrewIndex)] = 1;
        battle.log.push(`${cardDisplayName(activeCard)} 被海樓石機械手抓住，下一次行動完全不能進行。`);
      }
      if (mechanic.key === "postgame_aramaki" && moveEntry.id === "postgame_aramaki_nutrient_drain" && actualDamage > 0) {
        mechanic.groves = Math.min(4, Number(mechanic.groves || 0) + 1);
        battle.log.push(`養分吸收令森林擴張；根系 ${mechanic.groves}/4。`);
      }
      if (mechanic.key === "postgame_douglas_bullet" && actualDamage > 0) {
        const activeCard = battleActiveCard(player, battle);
        for (const itemId of ["impact_dial", "reject_dial"]) {
          for (const slot of postgameBossMechanicBulletSlotsById(battle, itemId)) {
            const stored = Math.max(0, Number(slot?.triggered?.storedDamage || 0));
            if (!stored) continue;
            activeCard.currentHp = Math.max(0, Number(activeCard.currentHp || 0) - stored);
            slot.triggered.storedDamage = 0;
            battle.log.push(`${slot.itemName}釋放儲存衝擊，追加 ${stored} 點傷害。`);
            if (itemId === "reject_dial") {
              const recoil = Math.max(1, Math.round(battle.enemyCombatant.maxHp * 0.15));
              battle.enemyCombatant.currentHp = Math.max(1, Number(battle.enemyCombatant.currentHp || 0) - recoil);
              battle.log.push(`排擊貝反噬巴雷特 ${recoil} HP。`);
            }
          }
        }
        for (const seaStoneSlot of postgameBossMechanicBulletSlotsById(battle, "seastone_bullet")) {
          if (!activeCard?.isDevilFruitUser || seaStoneSlot.triggered?.fixedDamage) continue;
          seaStoneSlot.triggered ||= {};
          seaStoneSlot.triggered.fixedDamage = true;
          const fixed = Math.max(1, Math.round(cardMaxHp(activeCard) * 0.06));
          activeCard.currentHp = Math.max(0, Number(activeCard.currentHp || 0) - fixed);
          applyStageSet(battle.playerStages, { spd: -1 }, 0, battle.playerStageTurns, 3);
          battle.log.push(`海樓石子彈追加 ${fixed} 點固定傷害，並使能力者速度下降。`);
        }
        const flameDialTriggered = postgameBossMechanicBulletSlotsById(battle, "flame_dial")
          .some(() => Math.random() < 0.35);
        if (flameDialTriggered) {
          applyBattleStatus("player", battle, "burn", 2);
          battle.log.push("炎貝追加灼傷效果。");
        }
        for (const genericSlot of postgameBossMechanicActiveBulletSlots(battle)) {
          const effect = battleCarryItemEffect(genericSlot.itemId);
          genericSlot.triggered ||= {};
          if (effect.kind === "store_damage_counter" && Number(genericSlot.triggered.storedDamage || 0) > 0) {
            const stored = Math.max(1, Math.round(Number(genericSlot.triggered.storedDamage || 0)));
            activeCard.currentHp = Math.max(0, Number(activeCard.currentHp || 0) - stored);
            genericSlot.triggered.storedDamage = 0;
            battle.log.push(`${genericSlot.itemName}釋放儲存衝擊，追加 ${stored} 點傷害。`);
            if (Number(effect.selfDamageMaxHpPercentAfterRelease || 0) > 0) {
              const recoil = Math.max(1, Math.round(battle.enemyCombatant.maxHp * Number(effect.selfDamageMaxHpPercentAfterRelease || .15)));
              battle.enemyCombatant.currentHp = Math.max(1, Number(battle.enemyCombatant.currentHp || 0) - recoil);
              battle.log.push(`${genericSlot.itemName}反噬巴雷特 ${recoil} HP。`);
            }
          }
          if (effect.kind === "heal_by_direct_damage_dealt") {
            const before = Number(battle.enemyCombatant.currentHp || 0);
            battle.enemyCombatant.currentHp = Math.min(battle.enemyCombatant.maxHp, before + Math.max(1, Math.round(actualDamage * Number(effect.percent || .15))));
            battle.log.push(`${genericSlot.itemName}依傷害回復 ${battle.enemyCombatant.currentHp - before} HP。`);
          }
          if (effect.kind === "damage_bonus_with_self_damage") {
            const recoil = Math.max(1, Math.round(battle.enemyCombatant.maxHp * Number(effect.selfDamageMaxHpPercent || .08)));
            battle.enemyCombatant.currentHp = Math.max(1, Number(battle.enemyCombatant.currentHp || 0) - recoil);
            battle.log.push(`${genericSlot.itemName}燃燒生命，反噬巴雷特 ${recoil} HP。`);
          }
          if (effect.kind === "flinch_on_damage" && Math.random() < Number(effect.chance || .1)) {
            applyBattleStatus("player", battle, "bind", 1);
            battle.log.push(`${genericSlot.itemName}令我方畏縮，下一次行動受阻。`);
          }
          if (effect.kind === "skill_tag_damage_bonus_and_status_chance" && effect.statusChance?.status) {
            const matched = effect.skillTag === "fire" ? isFireBattleMove(moveEntry) : effect.skillTag === "thunder" ? /雷|電|閃|thunder|lightning/i.test(moveSearchText(moveEntry)) : false;
            if (matched && Math.random() < Number(effect.statusChance.chance || .1)) applyBattleStatus("player", battle, effect.statusChance.status, 2);
          }
          if (effect.kind === "sound_skill_bonus_and_satk_once" && isSoundBattleMove(moveEntry) && !genericSlot.triggered.toneShellTriggered) {
            genericSlot.triggered.toneShellTriggered = true;
            applyStageSet(battle.enemyCombatant.stages, { satk: Number(effect.satkStage || 1) }, 0, battle.enemyCombatant.stageTurns, 3);
            battle.log.push(`${genericSlot.itemName}強化音波，巴雷特的戰術提升。`);
          }
        }
        for (const relicSlot of postgameBossMechanicActiveBulletSlots(battle)) {
          const effect = battleCarryItemEffect(relicSlot.itemId);
          relicSlot.triggered ||= {};
          if (effect.kind === "postgame_tesoro_gold_rings" && !relicSlot.triggered.goldRingsTriggered) {
            relicSlot.triggered.goldStacks = Math.min(Number(effect.requiredStacks || 3), Number(relicSlot.triggered.goldStacks || 0) + 1);
            battle.log.push(`${relicSlot.itemName}累積黃金 ${relicSlot.triggered.goldStacks}/${Number(effect.requiredStacks || 3)}。`);
            if (relicSlot.triggered.goldStacks >= Number(effect.requiredStacks || 3)) {
              relicSlot.triggered.goldRingsTriggered = true;
              applyBattleStatus("player", battle, "bind", Number(effect.bindTurns || 1));
              applyStageSet(battle.playerStages, effect.enemyStages || { def: -1, sdef: -1 }, 0, battle.playerStageTurns, 99);
              battle.log.push(`${relicSlot.itemName}完成三層黃金，束縛我方並令防禦與特防下降持續整場。`);
            }
          }
          if (effect.kind === "postgame_zephyr_battle_smasher") {
            if (relicSlot.triggered.battleSmasherReady) {
              relicSlot.triggered.battleSmasherReady = false;
              relicSlot.triggered.heat = 0;
              const recoil = Math.max(1, Math.round(Number(battle.enemyCombatant.maxHp || 1) * Number(effect.recoilMaxHp || .3)));
              battle.enemyCombatant.currentHp = Math.max(1, Number(battle.enemyCombatant.currentHp || 0) - recoil);
              battle.log.push(`${relicSlot.itemName}釋放過熱爆發並反噬巴雷特 ${recoil} HP。`);
            } else {
              relicSlot.triggered.heat = Math.min(Number(effect.requiredHeat || 3), Number(relicSlot.triggered.heat || 0) + 1);
              if (relicSlot.triggered.heat >= Number(effect.requiredHeat || 3)) relicSlot.triggered.battleSmasherReady = true;
              battle.log.push(`${relicSlot.itemName}熱量 ${relicSlot.triggered.heat}/${Number(effect.requiredHeat || 3)}${relicSlot.triggered.battleSmasherReady ? "，下次直接攻擊爆發" : ""}。`);
            }
          }
          if (effect.kind === "postgame_redfield_umbrella_sword") {
            const recovery = Math.max(1, Math.round(actualDamage * Number(effect.drainRatio || .2)));
            const before = Number(battle.enemyCombatant.currentHp || 0);
            const missing = Math.max(0, Number(battle.enemyCombatant.maxHp || 1) - before);
            const healed = Math.min(missing, recovery);
            battle.enemyCombatant.currentHp = Math.min(Number(battle.enemyCombatant.maxHp || 1), before + healed);
            const overflow = recovery - healed;
            if (overflow > 0) {
              const swordCount = postgameBossMechanicBulletEffectSlots(battle, "postgame_redfield_umbrella_sword").length;
              const shieldCap = Math.max(1, Math.round(Number(battle.enemyCombatant.maxHp || 1) * Number(effect.maxOverflowShieldRatio || .15) * swordCount));
              mechanic.bulletOverflowShield = Math.min(shieldCap, Number(mechanic.bulletOverflowShield || 0) + overflow);
            }
            battle.log.push(`${relicSlot.itemName}吸收傷害：回復 ${healed} HP${overflow > 0 ? `，溢出護盾目前 ${Math.round(mechanic.bulletOverflowShield || 0)} HP` : ""}。`);
          }
          if (effect.kind === "postgame_loki_ragnir") {
            const cloudsBefore = Math.max(0, Number(relicSlot.triggered.clouds || 0));
            const cloudsAfter = Math.min(Number(effect.freezeClouds || 3), cloudsBefore + 1);
            if (cloudsAfter >= Number(effect.freezeClouds || 3)) {
              applyBattleStatus("player", battle, "freeze", Number(effect.freezeTurns || 1));
              relicSlot.triggered.clouds = effect.clearCloudsAfterFreeze === false ? cloudsAfter : 0;
              battle.log.push(`${relicSlot.itemName}生成第三朵冰雲並立即凍結我方一回合，冰雲歸零。`);
            } else {
              relicSlot.triggered.clouds = cloudsAfter;
            }
          }
          if (effect.kind === "yonko_counter_griffon") {
            applyStageSet(battle.playerStages, { def: Number(effect.defenseStage || -1) }, 0, battle.playerStageTurns, 3);
            battle.log.push(`${relicSlot.itemName}撕開我方防禦。`);
          }
          if (effect.kind === "yonko_counter_fearless") {
            const fixed = Math.max(1, Math.round(cardMaxHp(activeCard) * Number(effect.maxHpDamagePerHit || .05)));
            const dealt = Math.min(Math.max(0, Number(activeCard.currentHp || 0)), fixed);
            activeCard.currentHp = Math.max(0, Number(activeCard.currentHp || 0) - dealt);
            battle.log.push(`${relicSlot.itemName}追加 ${dealt} 點固定傷害。`);
          }
        }
      }
    }
  }

  function postgameZephyrApplyPhaseTwoLoadout(battle) {
    if (!battle?.enemyCombatant) return false;
    const hasBlackArmLoadout = (battle.enemyCombatant.moveSet || []).some((moveEntry) => moveEntry.id === "postgame_zephyr_black_arm_fist");
    if (!hasBlackArmLoadout) {
      battle.enemyCombatant.moveSet = createEnemyMoveSet({
        key: battle.enemyCombatant.key,
        attribute: "力",
        moves: [
          enemyMove("postgame_zephyr_black_arm_fist", "黑腕・武裝重拳", "attack", 12, 276, "卸下機械臂後的武裝色重拳", { ignoreDefenseRatio: 0.16 }, { attribute: "力" }),
          enemyMove("postgame_zephyr_soru_assault", "六式・剃突擊", "attack", 10, 244, "高速近身；先制 +1", { priority: 1 }, { priority: 1, attribute: "速" }),
          enemyMove("postgame_zephyr_armament_barrage", "黑腕連打", "attack", 8, 138, "連續武裝色拳擊", { multiHit: 2 }, { attribute: "力" }),
          enemyMove("postgame_zephyr_final_resolve", "最後的教官", "buff", 6, 0, "攻擊、速度與意志提升", { selfStages: { atk: 1, spd: 1, sdef: 1 } }, { attribute: "力" }),
        ],
      });
    }
    const phasePortrait = "images/board/battle/enemies/postgame_zephyr/black_arm_normal.webp";
    battle.enemyCombatant.battlePortraits = { ...(battle.enemyCombatant.battlePortraits || {}), normal: phasePortrait, idle: phasePortrait, morale: phasePortrait };
    return true;
  }

  function waitPostgameZephyrExplosionStory(event) {
    if (!event?.id || !battleWindowIsActive()) return Promise.resolve("no-battle-window");
    const duration = Math.max(4000, Number(event.duration || POSTGAME_ZEPHYR_EXPLOSION_STORY_DURATION));
    return new Promise((resolve) => {
      const finish = (reason = "complete") => {
        const waiter = postgameZephyrExplosionStoryWaiters.get(event.id);
        if (!waiter) return;
        window.clearTimeout(waiter.timeout);
        postgameZephyrExplosionStoryWaiters.delete(event.id);
        resolve(reason);
      };
      const timeout = window.setTimeout(() => finish("timeout"), duration + 700);
      postgameZephyrExplosionStoryWaiters.set(event.id, { finish, timeout });
    });
  }

  function postgameZephyrApplyDetonationWipeout(player, battle, eventId = "") {
    if (!player || !battle || battle.result === "lose") return false;
    if (eventId && battle.visualEvent?.id === eventId) battle.visualEvent = null;
    battle.knockedOutCrew = Array.isArray(battle.knockedOutCrew) ? battle.knockedOutCrew : [];
    (player.crew || []).forEach((card) => {
      if (!card) return;
      card.currentHp = 0;
      if (card.id && !battle.knockedOutCrew.includes(card.id)) battle.knockedOutCrew.push(card.id);
    });
    battle.playerAction = null;
    battle.enemyAction = null;
    battle.playerPerformedAction = true;
    battle.enemyPerformedAction = true;
    battle.needsReplacement = false;
    battle.pendingEscapeRoll = null;
    battle.result = "lose";
    battle.roundResolved = true;
    battle.waitingResume = false;
    battle.animating = false;
    recalcPlayerDerivedStats(player);
    battle.log.push(`終結點爆炸吞沒戰場，${player.name} 的隊伍全員瀕死，依一般戰敗規則結算。`);
    return true;
  }

  function battleZephyrExplosionStoryDone(eventId = "") {
    const battle = state.battleState;
    const event = battle?.visualEvent;
    if (event?.type !== "postgame-zephyr-explosion-story") return false;
    if (eventId && event.id !== eventId) return false;
    const player = battlePlayer(null, battle);
    if (!player || (isCoopBattle(battle) ? warnBoardLanBattleLocked(player, battle) : warnBoardLanTurnLocked(player))) return false;
    const waiter = postgameZephyrExplosionStoryWaiters.get(event.id);
    if (waiter) {
      waiter.finish("viewer-complete");
      return true;
    }
    if (!postgameZephyrApplyDetonationWipeout(player, battle, event.id)) return false;
    notifyBattleWindow();
    renderBattleInterface();
    return true;
  }

  async function postgameZephyrResolveDetonationDefeat(player, battle) {
    const mechanic = postgameBossMechanicFor(battle);
    if (mechanic?.key !== "postgame_zephyr" || !mechanic.detonated) return false;
    const event = attachBattleVisualEventSnapshots({
      id: `postgame-zephyr-explosion-story-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      type: "postgame-zephyr-explosion-story",
      side: "enemy",
      targetSide: "player",
      moveName: "最後的炸藥岩・終結點毀滅",
      sceneCount: 5,
      duration: POSTGAME_ZEPHYR_EXPLOSION_STORY_DURATION,
    }, battle);
    battle.roundResolved = true;
    battle.waitingResume = false;
    battle.visualEvent = event;
    battle.log.push("最後的炸藥岩引爆——終結點毀滅的連鎖災難開始。");
    renderBattleInterface();
    notifyBattleWindow();
    await waitPostgameZephyrExplosionStory(event);
    postgameZephyrApplyDetonationWipeout(player, battle, event.id);
    notifyBattleWindow();
    return true;
  }

  function postgameZephyrResolveDisarmRoll(player, battle, diceFace) {
    const mechanic = postgameBossMechanicFor(battle);
    if (mechanic?.key !== "postgame_zephyr" || !mechanic.countdownActive || mechanic.dynaRockDisarmed || mechanic.detonated) return null;
    const gain = Number(diceFace || 0) >= 5 ? 2 : 1;
    const before = Math.max(0, Number(mechanic.disarmProgress || 0));
    mechanic.disarmProgress = Math.min(POSTGAME_ZEPHYR_DISARM_TARGET, before + gain);
    mechanic.lastDisarmRoll = Math.max(1, Math.min(6, Number(diceFace || 1)));
    mechanic.lastDisarmGain = gain;
    battle.playerActionSummary = `阻止引爆 ${mechanic.disarmProgress}/${POSTGAME_ZEPHYR_DISARM_TARGET}`;
    battle.log.push(`${cardDisplayName(battleActiveCard(player, battle))} 放棄攻擊處理炸藥岩，骰出 ${diceFace}，解除進度 ${before} → ${mechanic.disarmProgress}/${POSTGAME_ZEPHYR_DISARM_TARGET}。`);
    if (mechanic.disarmProgress >= POSTGAME_ZEPHYR_DISARM_TARGET) {
      mechanic.dynaRockDisarmed = true;
      mechanic.countdownActive = false;
      postgameBossMechanicActivateZephyrPhaseTwo(battle, "disarm");
    }
    return {
      diceFace: mechanic.lastDisarmRoll,
      gain,
      before,
      progress: mechanic.disarmProgress,
      completed: mechanic.dynaRockDisarmed,
    };
  }

  function postgameBossMechanicActivateZephyrPhaseTwo(battle, reason = "half-hp") {
    const mechanic = postgameBossMechanicFor(battle);
    if (mechanic?.key !== "postgame_zephyr") return false;
    const alreadyPhaseTwo = Number(mechanic.phase || 1) === 2;
    if (reason === "disarm") {
      mechanic.countdownActive = false;
      mechanic.dynaRockDisarmed = true;
      mechanic.disarmProgress = POSTGAME_ZEPHYR_DISARM_TARGET;
    }
    if (alreadyPhaseTwo) {
      if (reason === "disarm") battle.log.push("最後的炸藥岩解除成功；引爆倒數停止，黑腕決戰繼續。");
      return reason === "disarm";
    }
    mechanic.phase = 2;
    postgameZephyrApplyPhaseTwoLoadout(battle);
    if (!battle.enemyPerformedAction && battle.enemyAction?.type === "move") {
      battle.enemyAction = chooseEnemyAction(battle);
      battle.enemyActionSummary = "";
    }
    battle.log.push(reason === "disarm"
      ? "最後的炸藥岩解除成功；澤法見爆破計畫遭到阻止，卸下 Battle Smasher，以黑腕進行最後決鬥。"
      : "澤法生命降到一半，Battle Smasher 在正面衝擊下爆裂脫落；黑腕拳頭決戰開始，但最後的炸藥岩仍在倒數。");
    return true;
  }

  function postgameBossMechanicAfterMove(side, moveEntry, diceFace, hit, actualDamage, player, battle, firstDiceFace = diceFace) {
    const mechanic = postgameBossMechanicFor(battle);
    if (!mechanic || !moveEntry) return;
    if (side === "enemy") {
      if (mechanic.key === "postgame_shiki") {
        const fleetVolley = hit && actualDamage > 0 && postgameShikiLivingIslands(mechanic).some((island) => island.id === "fleet");
        const finalIslandFall = mechanic.finalDuel && moveEntry.id === "postgame_shiki_island_fall";
        if (fleetVolley || finalIslandFall) {
          const benchLoss = [];
          (player.crew || []).forEach((card, index) => {
            if (!card || index === battle.activeCrewIndex || Number(card.currentHp || 0) <= 0) return;
            const loss = Math.min(Math.max(0, Number(card.currentHp || 0) - 1), Math.max(1, Math.round(cardMaxHp(card) * 0.03)));
            card.currentHp = Math.max(1, Number(card.currentHp || 0) - loss);
            if (loss > 0) benchLoss.push(`${cardDisplayName(card)} -${loss}`);
          });
          if (benchLoss.length) battle.log.push(`${fleetVolley ? "空中艦隊齊射" : "島嶼墜落"}波及後排：${benchLoss.join("、")}。`);
        }
      }
      if (mechanic.key === "postgame_gild_tesoro") {
        const phase = Math.max(1, Number(mechanic.phase || 1));
        const goldenHit = hit
          && phase <= 2
          && !["buff", "heal"].includes(String(moveEntry.type || moveEntry.category || "").toLowerCase());
        if (goldenHit) postgameTesoroSetControl(player, battle, battleActiveCard(player, battle), battle.activeCrewIndex, 1);
      }
      if (mechanic.key === "postgame_vinsmoke_judge") {
        mechanic.production = Math.min(3, Number(mechanic.production || 0) + 1);
        if (mechanic.production >= 3) {
          mechanic.production = 0;
          if (mechanic.clones < 3) {
            mechanic.clones += 1;
            battle.log.push(`Germa 培養艙完成一名複製兵；人牆恢復到 ${mechanic.clones}/3。`);
          } else {
            battle.log.push("Germa 培養艙完成生產，但前線複製兵已滿。");
          }
        }
      }
      if (mechanic.key === "postgame_rob_lucci_awakened") {
        if (moveEntry.id === "postgame_lucci_ultimate_rokuogan") {
          mechanic.nodes = [];
          mechanic.rokuoganPending = false;
          mechanic.activePower = "";
          mechanic.activePowerId = "";
          mechanic.activePowerStat = "";
          mechanic.activePowerRound = 0;
          const splashes = [];
          (player.crew || []).forEach((card, index) => {
            if (!card || index === battle.activeCrewIndex || Number(card.currentHp || 0) <= 0) return;
            const loss = Math.min(Math.max(0, Number(card.currentHp || 0) - 1), Math.max(1, Math.round(cardMaxHp(card) * 0.03)));
            card.currentHp = Math.max(1, Number(card.currentHp || 0) - loss);
            if (loss > 0) splashes.push(`${cardDisplayName(card)} -${loss}`);
          });
          if (splashes.length) battle.log.push(`六王銃震波波及後排：${splashes.join("、")}。`);
        }
      }
      if (mechanic.key === "postgame_king") {
        const firstDie = Math.max(1, Math.min(6, Number(firstDiceFace || diceFace || 1)));
        mechanic.lastFirstDice = firstDie;
        mechanic.pendingFlameOn = firstDie % 2 === 1;
      }
      if (mechanic.key === "postgame_aramaki") {
        mechanic.fireproof = moveEntry.id === "postgame_aramaki_fireproof_forest";
        if (moveEntry.id === "postgame_aramaki_great_tree") mechanic.groves = Math.min(4, Number(mechanic.groves || 0) + 2);
        else if (moveEntry.id === "postgame_aramaki_forbidden_hate_forest" && hit) mechanic.groves = Math.min(4, Number(mechanic.groves || 0) + 1);
        if (["postgame_aramaki_great_tree", "postgame_aramaki_forbidden_hate_forest"].includes(moveEntry.id)) battle.log.push(`森林根系擴張到 ${mechanic.groves}/4。`);
      }
      if (mechanic.key === "postgame_douglas_bullet") {
        const directMove = postgameBossMechanicDirectMove(moveEntry);
        if (directMove && postgameBossMechanicActiveBulletSlots(battle).some((slot) => ["choice_lock_physical_damage", "choice_lock_special_damage", "choice_lock_speed_bonus"].includes(battleCarryItemEffect(slot.itemId).kind))) {
          mechanic.bulletLockedSkillId ||= moveEntry.id;
        }
        if (directMove) {
          postgameBossMechanicBulletEffectSlots(battle, "skip_charge_once").forEach((slot) => {
            slot.triggered ||= {};
            if (!slot.triggered.powerHerbUsed) slot.triggered.powerHerbUsed = true;
          });
          postgameBossMechanicBulletEffectSlots(battle, "postgame_king_sword").forEach((slot) => {
            slot.triggered ||= {};
            if (slot.triggered.flameOn === false) {
              slot.triggered.flameOn = true;
              battle.log.push(`${slot.itemName}在攻擊後重新點燃背火。`);
            }
          });
          if (!hit) {
            postgameBossMechanicBulletEffectSlots(battle, "postgame_zephyr_battle_smasher").forEach((slot) => {
              if (!slot.triggered?.battleSmasherReady) return;
              const effect = battleCarryItemEffect(slot.itemId);
              slot.triggered.battleSmasherReady = false;
              slot.triggered.heat = 0;
              const before = Math.max(1, Number(battle.enemyCombatant.currentHp || 1));
              const recoil = Math.max(1, Math.round(Number(battle.enemyCombatant.maxHp || 1) * Number(effect.recoilMaxHp || .3)));
              battle.enemyCombatant.currentHp = Math.max(1, before - recoil);
              battle.log.push(`${slot.itemName}落空仍消耗過熱爆發，反噬巴雷特 ${Math.max(0, before - battle.enemyCombatant.currentHp)} HP。`);
            });
          }
        }
        if (moveEntry.category === "shield" && postgameBossMechanicHasBulletItem(battle, "opal_cloud")) {
          battle.enemyCombatant.roundEffects ||= emptyRoundEffects();
          battle.enemyCombatant.roundEffects.shieldRatio = Math.min(0.8, Number(battle.enemyCombatant.roundEffects.shieldRatio || 0) + 0.1);
          battle.log.push("蛋白石雲讓巴雷特的防護再提升 10%。");
        }
        if (moveEntry.category === "heal" && postgameBossMechanicHasBulletItem(battle, "medical_bag")) {
          const extraHeal = Math.max(1, Math.round(Number(battle.enemyCombatant.maxHp || 1) * 0.045));
          const before = Number(battle.enemyCombatant.currentHp || 0);
          battle.enemyCombatant.currentHp = Math.min(Number(battle.enemyCombatant.maxHp || 1), before + extraHeal);
          const healed = Number(battle.enemyCombatant.currentHp || 0) - before;
          if (healed > 0) battle.log.push(`醫療包強化回復，巴雷特額外恢復 ${healed} 點生命。`);
        }
        for (const eternalSlot of postgameBossMechanicBulletSlotsById(battle, "eternal_pose")) {
          eternalSlot.triggered ||= {};
          if (eternalSlot.triggered.permanentPointerPrimed) {
            eternalSlot.triggered.permanentPointerPrimed = false;
            eternalSlot.triggered.permanentPointerConsumed = true;
          } else if (!hit && !eternalSlot.triggered.permanentPointerMissed) {
            eternalSlot.triggered.permanentPointerMissed = true;
            eternalSlot.triggered.permanentPointerPrimed = true;
          }
        }
        if (!hit) {
          const blunderSlot = postgameBossMechanicBulletEffectSlots(battle, "boost_speed_when_miss").find((slot) => !slot.triggered?.blunderPolicyTriggered);
          if (blunderSlot && !blunderSlot.triggered?.blunderPolicyTriggered) {
            blunderSlot.triggered ||= {};
            blunderSlot.triggered.blunderPolicyTriggered = true;
            const effect = battleCarryItemEffect(blunderSlot.itemId);
            applyStageSet(battle.enemyCombatant.stages, { spd: Number(effect.speedStage || 2) }, 0, battle.enemyCombatant.stageTurns, 3);
            battle.log.push(`${blunderSlot.itemName}在失手後啟動，巴雷特的速度大幅提升。`);
          }
        }
        mechanic.bulletMissedLastAttack = !hit;
      }
    } else {
      if (mechanic.key === "postgame_zephyr" && postgameBossMechanicDirectMove(moveEntry)) {
        const activeCard = battleActiveCard(player, battle);
        const crewKey = postgameBossMechanicCrewKey(activeCard, battle.activeCrewIndex);
        mechanic.lastMoveByCrew[crewKey] = moveEntry.id;
      }
      if (mechanic.key === "postgame_aramaki" && isFireBattleMove(moveEntry) && hit && String(actionTargetFromBattle(battle) || "boss") === "boss" && mechanic.groves > 0) {
        postgameBossMechanicDestroyGroves(mechanic, mechanic.fireproof ? 0 : 1, battle, !mechanic.fireproof);
      }
      if (mechanic.key === "postgame_douglas_bullet") {
        if (!postgameBossMechanicDirectMove(moveEntry)) {
          const card = battleActiveCard(player, battle);
          const crewKey = postgameBossMechanicCrewKey(card, battle.activeCrewIndex);
          mechanic.bulletLastPlayerActionWasDirect ||= {};
          mechanic.bulletLastPlayerDirectMoves ||= {};
          mechanic.bulletLastPlayerActionWasDirect[crewKey] = false;
          mechanic.bulletLastPlayerDirectMoves[crewKey] = "";
        }
        for (const medicineSlot of postgameBossMechanicBulletSlotsById(battle, "medicine_pack")) {
          if (medicineSlot.triggered?.medicineTriggered) continue;
          const enemyStatuses = battleStatusBag("enemy", battle);
          const statusKey = Object.keys(enemyStatuses || {}).find((key) => Number(enemyStatuses[key] || 0) > 0);
          if (statusKey) {
            enemyStatuses[statusKey] = 0;
            medicineSlot.triggered ||= {};
            medicineSlot.triggered.medicineTriggered = true;
            battle.log.push(`醫藥包清除了巴雷特的「${BATTLE_STATUS_INFO[statusKey]?.label || statusKey}」。`);
          }
        }
        for (const visionSlot of postgameBossMechanicBulletSlotsById(battle, "vision_dial")) {
          if (visionSlot.triggered?.visionTriggered) continue;
          const boosted = ["atk", "def", "satk", "sdef", "spd", "accuracy", "evasion"]
            .find((stat) => Number(battle.playerStages?.[stat] || 0) > 0);
          if (boosted) {
            applyStageSet(battle.enemyCombatant.stages, { [boosted]: 1 }, 0, battle.enemyCombatant.stageTurns, 3);
            visionSlot.triggered ||= {};
            visionSlot.triggered.visionTriggered = true;
            battle.log.push(`視貝複製了玩家的能力提升，巴雷特的${BATTLE_STAGE_LABELS[boosted] || boosted}上升。`);
          }
        }
        const lampSlot = postgameBossMechanicBulletSlotsById(battle, "lamp_dial").find((slot) => !slot.triggered?.lampTriggered);
        if (lampSlot && Number(battle.enemyCombatant.stages?.accuracy || 0) < 0) {
          battle.enemyCombatant.stages.accuracy = 0;
          lampSlot.triggered ||= {};
          lampSlot.triggered.lampTriggered = true;
          battle.log.push("燈貝照亮戰場，巴雷特的命中下降被清除。");
        }
        const gogglesSlot = postgameBossMechanicBulletSlotsById(battle, "sky_island_goggles").find((slot) => !slot.triggered?.skyGogglesTriggered);
        if (gogglesSlot) {
          const restored = ["accuracy", "evasion", "spd"].filter((stat) => Number(battle.enemyCombatant.stages?.[stat] || 0) < 0);
          if (restored.length) {
            restored.forEach((stat) => { battle.enemyCombatant.stages[stat] = 0; });
            gogglesSlot.triggered ||= {};
            gogglesSlot.triggered.skyGogglesTriggered = true;
            battle.log.push("空島護目鏡校正視野，巴雷特的命中、閃避與速度下降被清除。");
          }
        }
        const whiteHerbSlot = postgameBossMechanicBulletEffectSlots(battle, "clear_stat_down_once").find((slot) => !slot.triggered?.whiteHerbTriggered);
        if (whiteHerbSlot && !whiteHerbSlot.triggered?.whiteHerbTriggered) {
          const lowered = Object.keys(battle.enemyCombatant.stages || {}).filter((stat) => Number(battle.enemyCombatant.stages[stat] || 0) < 0);
          if (lowered.length) {
            whiteHerbSlot.triggered ||= {};
            whiteHerbSlot.triggered.whiteHerbTriggered = true;
            lowered.forEach((stat) => { battle.enemyCombatant.stages[stat] = 0; });
            battle.log.push(`${whiteHerbSlot.itemName}清除了巴雷特的能力下降。`);
          }
        }
        for (const clearSlot of postgameBossMechanicBulletEffectSlots(battle, "clear_control_status_once")) {
          if (clearSlot.triggered?.controlClearTriggered) continue;
          const effect = battleCarryItemEffect(clearSlot.itemId);
          const enemyStatuses = battleStatusBag("enemy", battle);
          const statusKey = (effect.statuses || ["paralyze", "freeze", "bind"]).find((key) => Number(enemyStatuses[key] || 0) > 0);
          if (!statusKey) continue;
          clearSlot.triggered ||= {};
          clearSlot.triggered.controlClearTriggered = true;
          enemyStatuses[statusKey] = 0;
          battle.log.push(`${clearSlot.itemName}清除了巴雷特的「${BATTLE_STATUS_INFO[statusKey]?.label || statusKey}」。`);
        }
        const healShellSlot = postgameBossMechanicBulletEffectSlots(battle, "auto_heal_when_low_hp").find((slot) => !slot.triggered?.healShellTriggered);
        if (healShellSlot) {
          const hpRate = Number(battle.enemyCombatant.currentHp || 0) / Math.max(1, Number(battle.enemyCombatant.maxHp || 1));
          const effect = battleCarryItemEffect(healShellSlot.itemId);
          if (hpRate < Number(effect.threshold || .4)) {
            healShellSlot.triggered ||= {};
            healShellSlot.triggered.healShellTriggered = true;
            const before = Number(battle.enemyCombatant.currentHp || 0);
            battle.enemyCombatant.currentHp = Math.min(battle.enemyCombatant.maxHp, before + Math.round(battle.enemyCombatant.maxHp * Number(effect.healPercent || .35)));
            battle.log.push(`${healShellSlot.itemName}自動回復 ${battle.enemyCombatant.currentHp - before} HP。`);
          }
        }
      }
    }
    const hpRate = Number(battle.enemyCombatant.currentHp || 0) / Math.max(1, Number(battle.enemyCombatant.maxHp || 1));
    if (mechanic.key === "postgame_gild_tesoro" && Number(mechanic.phase || 1) === 1 && hpRate <= 0.5) {
      postgameTesoroQueuePhase(mechanic, battle, 2);
    }
    if (mechanic.key === "postgame_tot_musica") {
      const movement = hpRate > 0.66 ? 1 : hpRate > 0.33 ? 2 : 3;
      if (movement !== mechanic.movement) {
        mechanic.movement = movement;
        const phasePortrait = `images/board/battle/enemies/postgame_tot_musica/movement_${movement}_normal.webp`;
        battle.enemyCombatant.battlePortraits = { ...(battle.enemyCombatant.battlePortraits || {}), normal: phasePortrait, idle: phasePortrait, morale: phasePortrait };
        battle.log.push(`Tot Musica 切換到第 ${movement} 樂章。`);
      }
    }
  }

  async function resolvePostgameTesoroPhaseTransition(player, battle) {
    const mechanic = postgameBossMechanicFor(battle);
    const phase = Math.max(0, Math.min(2, Number(mechanic?.pendingPhase || 0)));
    if (mechanic?.key !== "postgame_gild_tesoro" || phase <= Number(mechanic.phase || 1)) return false;
    mechanic.pendingPhase = 0;
    mechanic.phase = phase;
    mechanic.transitionSerial = Math.max(0, Number(mechanic.transitionSerial || 0)) + 1;
    mechanic.cancelQueuedPlayerAction = false;
    mechanic.awakeningUsed = true;
    mechanic.giantControl = 0;
    mechanic.giantArmor = 0;
    mechanic.ultimatePending = false;
    battle.log.push(`泰佐洛生命低於一半，將整座城市的黃金聚成巨人「Golden Tesoro」！每名船員的金流繼續累積；巨體防禦使受到的傷害只保留 ${Math.round(POSTGAME_TESORO_GOLDEN_DAMAGE_RATIO * 100)}%。`);
    postgameTesoroApplyPhaseLoadout(battle, mechanic);
    if (!battle.enemyPerformedAction && battle.enemyAction?.type === "move") {
      postgameTesoroRepairQueuedEnemyAction(battle, mechanic);
      battle.enemyAction = chooseEnemyAction(battle);
      battle.enemyActionSummary = "";
    }
    applyPostgameBossMechanicPortrait(battle, mechanic);
    const phaseTitle = "Golden Tesoro 降臨";
    battle.visualEvent = attachBattleVisualEventSnapshots({
      id: `postgame-tesoro-phase-${phase}-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      type: "status",
      side: "enemy",
      targetSide: "enemy",
      moveName: phaseTitle,
      moveType: "buff",
      effectFx: { targetSide: "enemy", kind: "buff", direction: "up", label: phaseTitle },
      duration: 2200,
    }, battle);
    renderBattleInterface();
    notifyBattleWindow();
    await waitBattleWindowVisual(battle.visualEvent, 2200);
    return true;
  }

  function actionTargetFromBattle(battle) {
    return battle?.playerAction?.targetId || "boss";
  }

  function postgameBossMechanicPreventEnemyKnockout(player, battle) {
    const mechanic = postgameBossMechanicFor(battle);
    if (!mechanic || Number(battle.enemyCombatant?.currentHp || 0) > 0) return false;
    if (mechanic.key === "postgame_zephyr" && Number(mechanic.phase || 1) === 1) {
      battle.enemyCombatant.currentHp = Math.max(1, Math.round(Number(battle.enemyCombatant.maxHp || 1) * POSTGAME_ZEPHYR_PHASE_TWO_HP_RATIO));
      postgameBossMechanicActivateZephyrPhaseTwo(battle, "half-hp");
      return true;
    }
    if (mechanic.key === "postgame_gild_tesoro") {
      const pendingPhase = Number(mechanic.pendingPhase || 0);
      if (pendingPhase === 2) {
        battle.enemyCombatant.currentHp = Math.max(1, Math.round(Number(battle.enemyCombatant.maxHp || 1) * 0.5));
        battle.log.push("泰佐洛以城市黃金承受致命傷，保留半條生命並準備化為 Golden Tesoro。");
        return true;
      }
    }
    if (mechanic.key === "postgame_aramaki" && !mechanic.revived && mechanic.groves > 0) {
      const groves = Math.max(1, Math.min(4, Number(mechanic.groves || 0)));
      mechanic.revived = true;
      mechanic.groves = 0;
      battle.enemyCombatant.currentHp = Math.max(1, Math.round(Number(battle.enemyCombatant.maxHp || 1) * groves * 0.1));
      battle.log.push(`荒牧從殘存種子重新發芽，消耗 ${groves} 片森林並回復 ${groves * 10}% 最大 HP。`);
      return true;
    }
    if (mechanic.key === "postgame_douglas_bullet") {
      const judgeSlot = postgameBossMechanicTriggerBulletJudgeFatalGuard(player, battle, mechanic);
      if (judgeSlot) {
        battle.enemyCombatant.currentHp = Math.max(1, Math.min(Number(battle.enemyCombatant.maxHp || 1), Number(mechanic.bulletHpBeforeHit || 1)));
        return true;
      }
      const lifeSlot = postgameBossMechanicActiveBulletSlots(battle).find((slot) => {
        if (slot.triggered?.fatal) return false;
        const effect = battleCarryItemEffect(slot.itemId);
        if (slot.itemId === "going_merry_rescue" || effect.kind === "fatal_rescue_heal_once") return true;
        if (slot.itemId === "life_paper" || slot.itemId === "focus_sash" || effect.kind === "survive_fatal_once_if_full_hp") return !!mechanic.bulletFullHpBeforeHit;
        if (slot.itemId === "focus_band" || effect.kind === "survive_fatal_chance") {
          if (Number(slot.triggered?.fatalRound || 0) === Number(battle.roundIndex || 0)) return false;
          return Math.random() < Number(effect.chance || .2);
        }
        return false;
      });
      if (lifeSlot) {
        lifeSlot.triggered ||= {};
        const effect = battleCarryItemEffect(lifeSlot.itemId);
        const repeatsByRound = lifeSlot.itemId === "focus_band" || effect.kind === "survive_fatal_chance";
        if (!repeatsByRound) lifeSlot.triggered.fatal = true;
        lifeSlot.triggered.fatalRound = Number(battle.roundIndex || 0);
        battle.enemyCombatant.currentHp = lifeSlot.itemId === "going_merry_rescue" || effect.kind === "fatal_rescue_heal_once"
          ? Math.max(1, Math.round(battle.enemyCombatant.maxHp * Number(effect.healPercent || .5)))
          : 1;
        battle.log.push(`巴雷特吸收的${lifeSlot.itemName}阻止致命傷。`);
        return true;
      }
      const seedSlot = postgameBossMechanicBulletEffectSlots(battle, "postgame_green_bull_life_seed")
        .find((slot) => !slot.triggered?.greenBullReviveUsed && Number(slot.triggered?.seeds || 0) > 0);
      if (seedSlot) {
        seedSlot.triggered ||= {};
        const effect = battleCarryItemEffect(seedSlot.itemId);
        const seeds = Math.max(1, Math.min(Number(effect.maxSeeds || 3), Number(seedSlot.triggered.seeds || 0)));
        seedSlot.triggered.seeds = 0;
        seedSlot.triggered.greenBullReviveUsed = true;
        battle.enemyCombatant.currentHp = Math.max(1, Math.round(Number(battle.enemyCombatant.maxHp || 1) * seeds * Number(effect.revivePerSeed || .12)));
        battle.log.push(`${seedSlot.itemName}消耗 ${seeds} 顆種子，令巴雷特以 ${Math.round(seeds * Number(effect.revivePerSeed || .12) * 100)}% 最大 HP 再生；本場不可再次復活。`);
        return true;
      }
    }
    return false;
  }

  function queuePostgameAramakiRevival(battle) {
    const mechanic = postgameBossMechanicFor(battle);
    if (
      mechanic?.key !== "postgame_aramaki"
      || mechanic.revived
      || mechanic.revivePending
      || Number(mechanic.groves || 0) <= 0
      || Number(battle?.enemyCombatant?.currentHp || 0) > 0
    ) return false;
    const groves = Math.max(1, Math.min(4, Number(mechanic.groves || 0)));
    mechanic.revivePending = {
      groves,
      healAmount: Math.max(1, Math.round(Number(battle.enemyCombatant.maxHp || 1) * groves * 0.1)),
    };
    return true;
  }

  async function resolvePostgameAramakiRevival(player, battle) {
    const mechanic = postgameBossMechanicFor(battle);
    const pending = mechanic?.key === "postgame_aramaki" ? mechanic.revivePending : null;
    if (!pending || mechanic.revived || Number(battle?.enemyCombatant?.currentHp || 0) > 0) return false;
    const enemyName = battle.enemyCombatant?.name || "綠牛／荒牧";
    battle.visualEvent = attachBattleVisualEventSnapshots({
      id: `postgame-aramaki-down-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      type: "postgame-aramaki-down",
      side: "enemy",
      targetSide: "enemy",
      targetName: enemyName,
      title: `${enemyName}倒下`,
      duration: 1100,
    }, battle);
    notifyBattleWindow();
    await waitBattleWindowVisual(battle.visualEvent, 1100);
    if (Number(battle.enemyCombatant?.currentHp || 0) > 0 || mechanic.revived) {
      mechanic.revivePending = null;
      return false;
    }
    const groves = Math.max(1, Math.min(4, Number(pending.groves || 0)));
    const healAmount = Math.max(1, Math.min(
      Number(battle.enemyCombatant.maxHp || 1),
      Number(pending.healAmount || Math.round(Number(battle.enemyCombatant.maxHp || 1) * groves * 0.1)),
    ));
    mechanic.revived = true;
    mechanic.groves = 0;
    mechanic.revivePending = null;
    battle.enemyCombatant.currentHp = healAmount;
    battle.log.push(`荒牧被擊倒後才從殘存種子重新發芽，消耗 ${groves} 片森林並回復 ${groves * 10}% 最大 HP。`);
    battle.visualEvent = attachBattleVisualEventSnapshots({
      id: `postgame-aramaki-revive-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      type: "postgame-aramaki-revive",
      side: "enemy",
      targetSide: "enemy",
      targetName: enemyName,
      moveName: "種子再生・重新發芽",
      moveType: "heal",
      amount: healAmount,
      effectFx: { kind: "heal", direction: "up", label: "重新發芽", targetSide: "enemy" },
      duration: 1700,
    }, battle);
    renderBattleInterface();
    notifyBattleWindow();
    await waitBattleWindowVisual(battle.visualEvent, 1700);
    return true;
  }

  async function postgameBossMechanicRoundEnd(player, battle) {
    const mechanic = postgameBossMechanicFor(battle);
    if (!mechanic) return;
    if (mechanic.key === "postgame_zephyr" && mechanic.countdownActive && !mechanic.dynaRockDisarmed && !mechanic.detonated) {
      mechanic.countdown = Math.max(0, Number(mechanic.countdown || 0) - 1);
      if (mechanic.countdown > 0) {
        battle.log.push(`最後終結點引爆倒數：剩餘 ${mechanic.countdown} 次澤法行動。`);
      } else {
        mechanic.countdownActive = false;
        mechanic.detonated = true;
        await postgameZephyrResolveDetonationDefeat(player, battle);
      }
    }
    if (mechanic.key === "postgame_shiki" && !mechanic.finalDuel) postgameShikiRefreshFrontIsland(mechanic, battle);
    if (mechanic.key === "postgame_douglas_bullet") {
      for (const slot of postgameBossMechanicBulletSlotsById(battle, "sanji_bento")) {
        const before = Number(battle.enemyCombatant.currentHp || 0);
        battle.enemyCombatant.currentHp = Math.min(Number(battle.enemyCombatant.maxHp || 1), before + Math.max(1, Math.round(battle.enemyCombatant.maxHp * .05)));
        if (battle.enemyCombatant.currentHp > before) battle.log.push(`巴雷特吸收的${slot.itemName}回復 ${battle.enemyCombatant.currentHp - before} HP。`);
      }
      for (const slot of postgameBossMechanicBulletEffectSlots(battle, "heal_each_turn")) {
        const effect = battleCarryItemEffect(slot.itemId);
        const amount = Math.max(1, Math.round(battle.enemyCombatant.maxHp * Number(effect.percent || .05)));
        const before = Number(battle.enemyCombatant.currentHp || 0);
        battle.enemyCombatant.currentHp = Math.min(battle.enemyCombatant.maxHp, before + amount);
        if (battle.enemyCombatant.currentHp > before) battle.log.push(`${slot.itemName}令巴雷特回復 ${battle.enemyCombatant.currentHp - before} HP。`);
      }
      const seedHpRate = Number(battle.enemyCombatant.currentHp || 0) / Math.max(1, Number(battle.enemyCombatant.maxHp || 1));
      for (const slot of postgameBossMechanicBulletEffectSlots(battle, "postgame_green_bull_life_seed")) {
        const effect = battleCarryItemEffect(slot.itemId);
        if (seedHpRate >= Number(effect.hpThreshold || .7)) continue;
        slot.triggered ||= {};
        if (!slot.triggered.greenBullReviveUsed) slot.triggered.seeds = Math.min(Number(effect.maxSeeds || 3), Number(slot.triggered.seeds || 0) + 1);
        const before = Number(battle.enemyCombatant.currentHp || 0);
        battle.enemyCombatant.currentHp = Math.min(battle.enemyCombatant.maxHp, before + Math.max(1, Math.round(battle.enemyCombatant.maxHp * Number(effect.healPerTurn || .03))));
        battle.log.push(`${slot.itemName}${slot.triggered.greenBullReviveUsed ? "本場復活已使用" : `累積種子 ${slot.triggered.seeds}/${Number(effect.maxSeeds || 3)}`}，並回復 ${battle.enemyCombatant.currentHp - before} HP。`);
      }
    }
  }

  function postgameBossMechanicRoundStart(player, battle) {
    const mechanic = normalizePostgameBossMechanic(player, battle);
    if (!mechanic) return false;
    if (mechanic.key === "postgame_tot_musica" && !mechanic.assigned) return true;
    if (mechanic.key === "postgame_gild_tesoro" && mechanic.forcedSwitch?.pending) return true;
    if (mechanic.key === "postgame_king" && typeof mechanic.pendingFlameOn === "boolean") {
      mechanic.flameOn = mechanic.pendingFlameOn;
      mechanic.pendingFlameOn = null;
      battle.log.push(mechanic.flameOn ? "新回合開始，KING 背後火焰熊熊燃起。" : "新回合開始，KING 背後火焰已經熄滅。");
    }
    if (mechanic.key === "postgame_oars") {
      const roundIndex = Math.max(1, Number(battle.roundIndex || 1));
      if (roundIndex % 3 === 0 && Number(mechanic.lastPeriodicSaltRound || 0) < roundIndex) {
        const before = Math.max(0, Number(mechanic.saltBags || 0));
        mechanic.saltBags = Math.min(POSTGAME_OARS_SALT_TARGET, before + 1);
        mechanic.lastPeriodicSaltRound = roundIndex;
        if (mechanic.saltBags > before) battle.log.push(`第 ${roundIndex} 回合補給：獲得 1 包鹽袋，目前 ${mechanic.saltBags}/${POSTGAME_OARS_SALT_TARGET}。`);
        if (before < POSTGAME_OARS_SALT_TARGET && mechanic.saltBags >= POSTGAME_OARS_SALT_TARGET) mechanic.purificationInterruptPending = true;
      }
    }
    if (mechanic.key === "postgame_rob_lucci_awakened") {
      postgameBossMechanicPrepareLucciPowerForAction(battle);
    }
    if (mechanic.key === "postgame_charlotte_katakuri") {
      void beginPostgameKatakuriForecast(player, battle);
      return true;
    }
    return false;
  }

  function postgameBossMechanicActionBlocked(side, player, battle) {
    const mechanic = postgameBossMechanicFor(battle);
    if (!mechanic) return false;
    if (side === "player") {
      if (mechanic.key === "postgame_gild_tesoro" && mechanic.skipNextAction) {
        mechanic.skipNextAction = false;
        battle.log.push(`${battleActiveCard(player, battle)?.name || player.name} 的黃金化剛解除，本次行動被跳過。`);
        return true;
      }
      if (mechanic.key === "postgame_zephyr") {
        const card = battleActiveCard(player, battle);
        const key = postgameBossMechanicCrewKey(card, battle.activeCrewIndex);
        if (Number(mechanic.seaStoneSkipByCrew?.[key] || 0) > 0) {
          mechanic.seaStoneSkipByCrew[key] = 0;
          battle.log.push(`${cardDisplayName(card)} 受到海樓石壓制，跳過本次行動後機械手立即放開。`);
          return true;
        }
      }
    }
    return false;
  }

  function resolvePostgameBossForcedSwitch(nextIndex) {
    const battle = state.battleState;
    const player = isCoopBattle(battle) ? battleCommandPlayer(battle) : battlePlayer(null, battle);
    const mechanic = postgameBossMechanicFor(battle);
    if (!battle || !player || mechanic?.key !== "postgame_gild_tesoro" || !mechanic.forcedSwitch?.pending) return false;
    if (warnBoardLanBattleLocked(player, battle)) return false;
    const card = player.crew?.[Number(nextIndex)];
    if (!card || Number(nextIndex) === Number(battle.activeCrewIndex) || Number(card.currentHp || 0) <= 0) return false;
    const fromIndex = Number(mechanic.forcedSwitch.fromIndex ?? battle.activeCrewIndex);
    battle.needsReplacement = true;
    battle.result = "replacement";
    battle.replacementAfterAction = true;
    battle.replacementReason = "tesoro-gold";
    battle.pendingReplacementActiveCrewIndex = fromIndex;
    return chooseBattleReplacement(Number(nextIndex));
  }

  function confirmTotMusicaTeams(realIndices = [], songIndices = null) {
    const battle = state.battleState;
    const player = isCoopBattle(battle) ? battleCommandPlayer(battle) : battlePlayer(null, battle);
    const mechanic = postgameBossMechanicFor(battle);
    if (!battle || !player || mechanic?.key !== "postgame_tot_musica" || mechanic.assigned) return false;
    if (postgameTotUsesPlayerWorlds(battle, mechanic)) return false;
    if (warnBoardLanBattleLocked(player, battle)) return false;
    const living = livingCrewIndices(player);
    const real = Array.from(new Set((Array.isArray(realIndices) ? realIndices : []).map(Number))).filter((index) => living.includes(index));
    const explicitSong = Array.isArray(songIndices)
      ? Array.from(new Set(songIndices.map(Number))).filter((index) => living.includes(index) && !real.includes(index))
      : null;
    const song = explicitSong || living.filter((index) => !real.includes(index));
    const assigned = [...real, ...song];
    const coversLivingCrew = assigned.length === living.length && living.every((index) => assigned.includes(index));
    if (!real.length || !song.length || !coversLivingCrew || Math.abs(real.length - song.length) > 1) {
      battle.log.push("分隊無效：每名存活船員都要排入左右其中一隊，且人數差不能超過 1。");
      notifyBattleWindow();
      return false;
    }
    mechanic.realIndices = real;
    mechanic.songIndices = song;
    mechanic.realActiveIndex = real[0];
    mechanic.songActiveIndex = song[0];
    mechanic.assigned = true;
    battle.activeCrewIndex = real[0];
    player.activeCrewIndex = real[0];
    battle.log.push(`分隊完成：左隊 ${real.map((index) => cardDisplayName(player.crew[index])).join("、")}；右隊 ${song.map((index) => cardDisplayName(player.crew[index])).join("、")}。`);
    if (battle.awaitingRoundStartContinuation) continueBattleRoundStartAfterPrompt(player, battle);
    else if (!battle.roundIndex || battle.roundResolved || battle.waitingResume) startBattleRound(player, battle);
    notifyBattleWindow();
    renderBattleInterface();
    return true;
  }

  function normalizeTotMusicaWorldAction(action = {}) {
    if (action?.type === "switch") return { type: "switch", nextIndex: Number(action.nextIndex) };
    if (action?.type === "item") {
      const parsedTargetIndex = Number(action.targetIndex);
      return {
        type: "item",
        itemId: String(action.itemId || ""),
        targetIndex: Number.isInteger(parsedTargetIndex) ? parsedTargetIndex : null,
        targetPlayerId: String(action.targetPlayerId || ""),
        targetSide: action.targetSide === "enemy" ? "enemy" : action.targetSide === "player" ? "player" : "",
      };
    }
    if (action?.type === "escape") return { type: "escape" };
    return { type: "move", moveId: String(action?.moveId || "") };
  }

  function queueTotMusicaAction(realAction, songAction) {
    const battle = state.battleState;
    const player = isCoopBattle(battle) ? battleCommandPlayer(battle) : battlePlayer(null, battle);
    const mechanic = postgameBossMechanicFor(battle);
    if (!battle || !player || mechanic?.key !== "postgame_tot_musica" || !mechanic.assigned) return false;
    if (postgameTotUsesPlayerWorlds(battle, mechanic)) return false;
    if (battle.animating || battle.roundResolved || battle.result || battle.needsReplacement || warnBoardLanBattleLocked(player, battle)) return false;
    const validate = (world, rawAction) => {
      const action = normalizeTotMusicaWorldAction(rawAction);
      const indices = world === "real" ? mechanic.realIndices : mechanic.songIndices;
      const activeIndex = Number(world === "real" ? mechanic.realActiveIndex : mechanic.songActiveIndex);
      if (action.type === "switch") {
        return indices.includes(action.nextIndex) && action.nextIndex !== activeIndex && Number(player.crew?.[action.nextIndex]?.currentHp || 0) > 0;
      }
      if (action.type === "item") {
        const option = getBattleItemOptions(player).find((entry) => entry.id === action.itemId && Number(entry.count || 0) > 0);
        if (!option) return false;
        if (option.targetMode === "battle_side") return action.targetSide === "player" || action.targetSide === "enemy";
        if (action.targetIndex == null) return !["living_ally", "downed_ally"].includes(option.targetMode);
        return indices.includes(Number(action.targetIndex)) && battleCrewIndexIsEligible(player, battle, Number(action.targetIndex));
      }
      if (action.type === "escape") {
        return !battle.isJudicialRaid && !battle.isMarineford && !battle.noEscape && !battle.isNoEscape && Number(getTeamEffects(player).escapeThreshold || 0) > 0;
      }
      const card = player.crew?.[activeIndex];
      return !!getUnlockedMoves(card).find((entry) => entry.id === action.moveId && Number(entry.currentPP ?? entry.pp ?? 0) > 0);
    };
    const normalizedReal = normalizeTotMusicaWorldAction(realAction);
    const normalizedSong = normalizeTotMusicaWorldAction(songAction);
    if (!validate("real", normalizedReal) || !validate("song", normalizedSong)) {
      battle.log.push("雙世界行動無效：請為現實世界與歌世界各選一個可用行動。");
      notifyBattleWindow();
      return false;
    }
    const selectedItemCounts = [normalizedReal, normalizedSong].reduce((counts, action) => {
      if (action.type === "item") counts[action.itemId] = Number(counts[action.itemId] || 0) + 1;
      return counts;
    }, {});
    if (Object.entries(selectedItemCounts).some(([itemId, count]) => Number(getBattleItemOptions(player).find((entry) => entry.id === itemId)?.count || 0) < count)) {
      battle.log.push("雙世界行動無效：同一道具的持有數量不足以讓兩隊同時使用。");
      notifyBattleWindow();
      return false;
    }
    battle.playerAction = { type: "tot-dual", realAction: normalizedReal, songAction: normalizedSong };
    battle.enemyAction = chooseEnemyAction(battle);
    void resolvePlannedBattleActions(player, battle);
    return true;
  }

  function queueTotMusicaWorldAction(world, rawAction) {
    const battle = state.battleState;
    const mechanic = postgameBossMechanicFor(battle);
    if (!battle || mechanic?.key !== "postgame_tot_musica") return false;
    postgameTotNormalizePlayerWorlds(battle, mechanic);
    if (!postgameTotUsesPlayerWorlds(battle, mechanic) || battle.animating || battle.roundResolved || battle.result || battle.needsReplacement) return false;
    const normalizedWorld = world === "song" ? "song" : "real";
    if (normalizedWorld !== mechanic.coopSelectionWorld) return false;
    const player = postgameTotActiveWorldPlayer(battle, mechanic, normalizedWorld);
    if (!player || warnBoardLanBattleLocked(player, battle)) return false;
    const runtime = coopBattleRuntimeFor(player, battle, true);
    const activeIndex = livingActiveCrewIndex(player, runtime?.activeCrewIndex ?? player.activeCrewIndex ?? 0);
    const action = normalizeTotMusicaWorldAction(rawAction);
    const valid = (() => {
      if (action.type === "switch") return action.nextIndex !== activeIndex && Number(player.crew?.[action.nextIndex]?.currentHp || 0) > 0;
      if (action.type === "item") {
        const option = getBattleItemOptions(player).find((entry) => entry.id === action.itemId);
        if (!option || Number(option.count || 0) <= 0) return false;
        if (option.targetMode === "battle_side") return action.targetSide === "player" || action.targetSide === "enemy";
        return action.targetIndex == null || Number.isInteger(Number(action.targetIndex));
      }
      if (action.type === "escape") return !battle.noEscape && !battle.isNoEscape && Number(getTeamEffects(player).escapeThreshold || 0) > 0;
      return !!getUnlockedMoves(player.crew?.[activeIndex]).find((entry) => entry.id === action.moveId && Number(entry.currentPP ?? entry.pp ?? 0) > 0);
    })();
    if (!valid) {
      battle.log.push(`${normalizedWorld === "real" ? "現實世界" : "歌世界"}行動無效，請重新選擇。`);
      notifyBattleWindow();
      return false;
    }
    mechanic.coopWorldActions[normalizedWorld] = { playerId: String(player.id), action };
    const otherWorld = normalizedWorld === "real" ? "song" : "real";
    const otherPlayer = postgameTotActiveWorldPlayer(battle, mechanic, otherWorld);
    battle.log.push(`${normalizedWorld === "real" ? "現實世界" : "歌世界"}・${player.name} 已完成行動選擇。`);
    if (!mechanic.coopWorldActions[otherWorld]) {
      mechanic.coopSelectionWorld = otherWorld;
      if (!otherPlayer) {
        battle.result = "lose";
        battle.log.push(`${otherWorld === "real" ? "現實世界" : "歌世界"}已無可戰鬥玩家，雙世界共鬥失敗。`);
      } else {
        battle.playerId = otherPlayer.id;
        const otherRuntime = coopBattleRuntimeFor(otherPlayer, battle, true);
        battle.activeCrewIndex = livingActiveCrewIndex(otherPlayer, otherRuntime?.activeCrewIndex ?? otherPlayer.activeCrewIndex ?? 0);
        battle.playerAction = null;
        battle.enemyAction = null;
        battle.log.push(`雙世界選擇交棒：輪到${otherWorld === "real" ? "現實世界" : "歌世界"}的 ${otherPlayer.name}。`);
      }
      renderBattleInterface();
      notifyBattleWindow();
      scheduleBoardLanStatePush("tot-musica-world-action", 40, { force: true });
      return true;
    }
    const realPlayer = postgameTotActiveWorldPlayer(battle, mechanic, "real");
    const songPlayer = postgameTotActiveWorldPlayer(battle, mechanic, "song");
    if (!realPlayer || !songPlayer) {
      battle.result = "lose";
      renderBattleInterface();
      notifyBattleWindow();
      return true;
    }
    prepareCoopBattleCommandRuntime(realPlayer, battle);
    battle.playerId = realPlayer.id;
    battle.playerAction = {
      type: "tot-dual",
      realAction: safeJsonClone(mechanic.coopWorldActions.real.action),
      songAction: safeJsonClone(mechanic.coopWorldActions.song.action),
      realPlayerId: String(realPlayer.id),
      songPlayerId: String(songPlayer.id),
    };
    battle.enemyAction = chooseEnemyAction(battle);
    scheduleBoardLanStatePush("tot-musica-world-pair-ready", 40, { force: true });
    void resolvePlannedBattleActions(realPlayer, battle);
    return true;
  }

  function setTotMusicaActiveWorldCrew(player, battle, mechanic, world, index) {
    syncActivePlayerStatusBag(player, battle);
    const nextIndex = Number(index);
    if (postgameTotUsesPlayerWorlds(battle, mechanic)) {
      const runtime = coopBattleRuntimeFor(player, battle, true);
      if (runtime) runtime.activeCrewIndex = nextIndex;
    } else if (world === "real") mechanic.realActiveIndex = nextIndex;
    else mechanic.songActiveIndex = nextIndex;
    battle.activeCrewIndex = nextIndex;
    player.activeCrewIndex = nextIndex;
    syncActivePlayerStatusBag(player, battle);
    markBattleCrewParticipation(player, battle, nextIndex);
    return player.crew?.[nextIndex] || null;
  }

  function totMusicaFirstDiceParityMatches(realFirstDie, songFirstDie) {
    const real = Math.floor(Number(realFirstDie || 0));
    const song = Math.floor(Number(songFirstDie || 0));
    return real >= 1 && song >= 1 && real % 2 === song % 2;
  }

  function totMusicaDualAttackSynergy(player, realResult, songResult) {
    const resultAttribute = (result) => {
      const card = player?.crew?.[Number(result?.cardIndex)] || {};
      return String(result?.move?.attribute || result?.attribute || card.attribute || "").trim();
    };
    const resultMoveClass = (result) => {
      const category = String(result?.move?.category || "").trim();
      return category === "special" || category === "attack" ? category : "";
    };
    const realAttribute = resultAttribute(realResult);
    const songAttribute = resultAttribute(songResult);
    const realMoveClass = resultMoveClass(realResult);
    const songMoveClass = resultMoveClass(songResult);
    const sameAttribute = !!realAttribute && !!songAttribute && realAttribute === songAttribute;
    const sameFirstDie = Number(realResult?.firstDiceFace || 0) > 0
      && Number(realResult?.firstDiceFace || 0) === Number(songResult?.firstDiceFace || 0);
    const sameMoveClass = !!realMoveClass && realMoveClass === songMoveClass;
    const bonusRate = (sameAttribute ? 0.5 : 0) + (sameFirstDie ? 0.5 : 0) + (sameMoveClass ? 0.2 : 0);
    return {
      realAttribute,
      songAttribute,
      realMoveClass,
      songMoveClass,
      sameAttribute,
      sameFirstDie,
      sameMoveClass,
      bonusRate,
      bonusMultiplier: 1 + bonusRate,
    };
  }

  function totMusicaDualDamageRate(bothAttackRolls, parityMatched, synergy = {}) {
    if (!bothAttackRolls) return 0;
    const baseRate = parityMatched ? 1 : 0.05;
    return baseRate * Math.max(1, Number(synergy.bonusMultiplier || 1));
  }

  function totMusicaDiceParityLabel(value) {
    const die = Math.floor(Number(value || 0));
    if (die < 1) return "未擲骰";
    return die % 2 ? "單數" : "雙數";
  }

  async function resolveTotMusicaWorldAction(player, battle, mechanic, world, rawAction) {
    const label = world === "real" ? "現實世界" : "歌世界";
    const playerWorlds = postgameTotUsesPlayerWorlds(battle, mechanic);
    const indices = playerWorlds
      ? (player?.crew || []).map((_card, index) => index)
      : world === "real" ? mechanic.realIndices : mechanic.songIndices;
    const runtime = playerWorlds ? coopBattleRuntimeFor(player, battle, true) : null;
    const activeIndex = Number(runtime?.activeCrewIndex ?? (world === "real" ? mechanic.realActiveIndex : mechanic.songActiveIndex));
    const action = normalizeTotMusicaWorldAction(rawAction);
    if (action.type === "switch") {
      if (!indices.includes(action.nextIndex) || Number(player.crew?.[action.nextIndex]?.currentHp || 0) <= 0) return { world, label, direct: false, hit: false, damage: 0, diceFace: 0, firstDiceFace: 0, diceRolls: [], move: null, cardIndex: activeIndex };
      const fromName = cardDisplayName(player.crew?.[activeIndex]);
      const card = setTotMusicaActiveWorldCrew(player, battle, mechanic, world, action.nextIndex);
      battle.log.push(`${label}免費調度：${fromName} → ${cardDisplayName(card)}；本世界本輪不會命中魔王。`);
      return { world, label, playerId: String(player.id || ""), attribute: card?.attribute || "無", direct: false, hit: false, damage: 0, diceFace: 0, firstDiceFace: 0, diceRolls: [], move: null, switched: true, cardIndex: action.nextIndex };
    }
    if (action.type === "item") {
      const card = setTotMusicaActiveWorldCrew(player, battle, mechanic, world, activeIndex);
      const itemDef = gameItemDef(action.itemId);
      const beforeLogLength = battle.log.length;
      applyBattleItemAction("player", {
        ...action,
        targetPlayerId: action.targetPlayerId || String(player.id || ""),
      }, player, battle);
      const applied = battle.log.length > beforeLogLength;
      battle.log.push(`${label}由 ${cardDisplayName(card)} 使用${itemDef?.name || "戰鬥道具"}；本世界本輪不會形成同步攻擊。`);
      return {
        world, label, playerId: String(player.id || ""), attribute: card?.attribute || "無", direct: false, hit: applied, affected: applied, damage: 0, diceFace: 0, firstDiceFace: 0, diceRolls: [], move: null,
        itemUsed: true, actionName: itemDef?.name || "戰鬥道具", cardIndex: activeIndex,
      };
    }
    if (action.type === "escape") {
      const card = setTotMusicaActiveWorldCrew(player, battle, mechanic, world, activeIndex);
      const teamEffects = getTeamEffects(player);
      const threshold = Math.max(0, Number(teamEffects.escapeThreshold || 0));
      const bonus = Math.max(0, Math.round(Number(teamEffects.shipEscapeRollBonus || 0)));
      const baseRoll = threshold > 0
        ? await rollBattleActionDice("move", `${label}・${cardDisplayName(card)} 嘗試逃跑`, `需要骰出 ${threshold}+ 才能脫離戰鬥。`, battle, 6, { side: "player", moveType: "escape", suppressVisual: true })
        : 0;
      battle.pendingEscapeRollBase = baseRoll;
      battle.pendingEscapeRollBonus = bonus;
      battle.pendingEscapeRoll = baseRoll + bonus;
      applyEscapeAction("player", player, battle);
      const escaped = battle.result === "escape";
      return {
        world, label, playerId: String(player.id || ""), attribute: card?.attribute || "無", direct: false, hit: escaped, affected: escaped, damage: 0, diceFace: baseRoll + bonus, firstDiceFace: baseRoll,
        diceRolls: baseRoll > 0 ? [baseRoll] : [], move: null, escaped, actionName: escaped ? "逃跑成功" : "逃跑失敗", cardIndex: activeIndex,
      };
    }
    const card = setTotMusicaActiveWorldCrew(player, battle, mechanic, world, activeIndex);
    const move = getUnlockedMoves(card).find((entry) => entry.id === action.moveId);
    if (!card || !move || Number(move.currentPP ?? move.pp ?? 0) <= 0) return { world, label, direct: false, hit: false, damage: 0, diceFace: 0, firstDiceFace: 0, diceRolls: [], move: null, cardIndex: activeIndex };
    if (await isBattleActionBlockedByStatus("player", player, battle)) {
      battle.log.push(`${label}的 ${cardDisplayName(card)} 行動受阻，同步攻擊無法成立。`);
      return { world, label, direct: false, hit: false, damage: 0, diceFace: 0, firstDiceFace: 0, diceRolls: [], move, cardIndex: activeIndex };
    }
    move.currentPP = Math.max(0, Number(move.currentPP ?? move.pp ?? 0) - 1);
    let firstDiceFace = 0;
    let diceRolls = [];
    const diceFace = await rollBattleActionDiceWithPassives(
      battleDiceThemeForMove(move),
      `${label}・${cardDisplayName(card)} 使用 ${move.name}`,
      "第一顆骰只要同為單數或雙數，就能發動同步攻擊。",
      battle,
      6,
      {
        side: "player",
        moveType: move.category || "attack",
        castSfx: battleCastSfxForMove(move),
        suppressVisual: true,
        onFirstDie: (value) => { firstDiceFace = Number(value || 0); },
        onDiceResolved: (rolls) => { diceRolls = (Array.isArray(rolls) ? rolls : []).map((value) => Number(value || 0)).filter((value) => value > 0); },
      },
    );
    const direct = postgameBossMechanicDirectMove(move);
    if (!direct) {
      const healingDone = applyMoveEffects(move, "player", diceFace, player, battle, "status", 0);
      battle.log.push(`${label}使用 ${move.name}，效果正常發動，但不是同步所需的直接攻擊${healingDone > 0 ? `（回復 ${healingDone} HP）` : ""}。`);
      return { world, label, playerId: String(player.id || ""), attribute: card?.attribute || "無", direct: false, hit: true, damage: 0, diceFace, firstDiceFace, diceRolls, move, cardIndex: activeIndex };
    }
    const bonus = bonusDamageFromMove(move, diceFace, player, battle, "player");
    const criticalVisual = { critical: false, criticalCount: 0 };
    let hitDamages;
    if (isComboBattleMove(move)) {
      let maxHits = comboMoveMaxHits(move, diceFace);
      maxHits = battleCarryAdjustedMultiHit("player", move, diceFace, maxHits, player, battle);
      hitDamages = computeComboHitDamages("player", move, diceFace, maxHits, bonus, player, battle, criticalVisual);
    } else {
      hitDamages = splitBattleDamageIntoHits(computeMoveDamage("player", move, diceFace, player, battle, criticalVisual), 1, bonus);
    }
    let total = battleDamageHitTotal(hitDamages);
    total = applyOffensiveBattleCarryAfterHit("player", total, player, battle);
    hitDamages = adjustBattleHitDamagesToTotal(hitDamages, total);
    return {
      world, label, playerId: String(player.id || ""), attribute: card?.attribute || "無", direct: true, hit: true, damage: battleDamageHitTotal(hitDamages), hitDamages, diceFace, firstDiceFace, diceRolls, move,
      cardIndex: activeIndex,
      critical: !!criticalVisual.critical,
      criticalCount: Math.max(0, Number(criticalVisual.criticalCount || 0)),
      criticalHitIndexes: Array.isArray(criticalVisual.criticalHitIndexes) ? criticalVisual.criticalHitIndexes.slice() : [],
    };
  }

  async function executeTotMusicaDualAction(player, battle, action) {
    const mechanic = postgameBossMechanicFor(battle);
    if (mechanic?.key !== "postgame_tot_musica") return;
    const playerWorlds = postgameTotUsesPlayerWorlds(battle, mechanic);
    const realPlayer = playerWorlds ? postgameTotActiveWorldPlayer(battle, mechanic, "real") : player;
    const songPlayer = playerWorlds ? postgameTotActiveWorldPlayer(battle, mechanic, "song") : player;
    if (!realPlayer || !songPlayer) {
      battle.result = "lose";
      battle.log.push("其中一個世界已無可戰鬥玩家，雙世界同步戰失敗。");
      return;
    }
    const beforeSnapshot = getBattleVisualSnapshot(realPlayer, battle);
    const resolveWorld = async (world, worldPlayer, worldAction) => {
      if (!playerWorlds) return resolveTotMusicaWorldAction(worldPlayer, battle, mechanic, world, worldAction);
      return withCoopBattleRuntimeAsync(worldPlayer, battle, () => resolveTotMusicaWorldAction(worldPlayer, battle, mechanic, world, worldAction), { save: true });
    };
    const realResult = await resolveWorld("real", realPlayer, action.realAction);
    const songResult = await resolveWorld("song", songPlayer, action.songAction);
    for (const [worldPlayer, result] of [[realPlayer, realResult], [songPlayer, songResult]]) {
      if (!playerWorlds || !result?.escaped) continue;
      const runtime = coopBattleRuntimeFor(worldPlayer, battle, true);
      runtime.escaped = true;
      runtime.needsReplacement = false;
      battle.log.push(`${worldPlayer.name} 成功撤離所屬世界，將由同世界隊友接替。`);
    }
    const bothAttackRolls = realResult.direct && songResult.direct
      && Number(realResult.firstDiceFace || 0) > 0
      && Number(songResult.firstDiceFace || 0) > 0;
    const parityMatched = totMusicaFirstDiceParityMatches(realResult.firstDiceFace, songResult.firstDiceFace);
    const synchronized = bothAttackRolls && parityMatched;
    const partialStrike = bothAttackRolls && !parityMatched;
    const synergy = totMusicaDualAttackSynergy(realPlayer, realResult, songResult);
    const baseDamageRate = synchronized ? 1 : partialStrike ? 0.05 : 0;
    const finalDamageRate = totMusicaDualDamageRate(bothAttackRolls, parityMatched, synergy);
    mechanic.lastRealFirstDie = Number(realResult.firstDiceFace || 0);
    mechanic.lastSongFirstDie = Number(songResult.firstDiceFace || 0);
    mechanic.lastParityMatch = parityMatched;
    let totalDamage = 0;
    let scaledWorldDamages = [0, 0];
    if (bothAttackRolls) {
      const rawWorldDamages = [Math.max(0, Number(realResult.damage || 0)), Math.max(0, Number(songResult.damage || 0))];
      const rawTotalDamage = battleDamageHitTotal(rawWorldDamages);
      const calculatedDamage = rawTotalDamage > 0 ? Math.max(1, Math.round(rawTotalDamage * finalDamageRate)) : 0;
      const beforeHp = Number(battle.enemyCombatant.currentHp || 0);
      battle.enemyCombatant.currentHp = Math.max(0, beforeHp - calculatedDamage);
      totalDamage = Math.max(0, beforeHp - battle.enemyCombatant.currentHp);
      scaledWorldDamages = scaleBattleHitDamagesToTotal(rawWorldDamages, totalDamage);
      [[realResult, realPlayer], [songResult, songPlayer]].forEach(([result, worldPlayer], index) => {
        const applyResultEffect = () => {
          setTotMusicaActiveWorldCrew(worldPlayer, battle, mechanic, result.world, result.cardIndex);
          applyMoveEffects(result.move, "player", result.diceFace, worldPlayer, battle, "attack", scaledWorldDamages[index] || 0);
        };
        if (playerWorlds) withCoopBattleRuntime(worldPlayer, battle, applyResultEffect, { save: true });
        else applyResultEffect();
      });
      const bonusParts = [
        synergy.sameAttribute ? "同屬性 +50%" : "",
        synergy.sameFirstDie ? "第一骰同點 +50%" : "",
        synergy.sameMoveClass ? `${synergy.realMoveClass === "special" ? "同為特攻" : "同為普通攻擊"} +20%` : "",
      ].filter(Boolean);
      if (synchronized) {
        mechanic.lastSync = "success";
        battle.log.push(`雙世界奇偶同步成功！現實世界第一顆骰 ${realResult.firstDiceFace}（${totMusicaDiceParityLabel(realResult.firstDiceFace)}）、歌世界第一顆骰 ${songResult.firstDiceFace}（${totMusicaDiceParityLabel(songResult.firstDiceFace)}），${bonusParts.length ? `${bonusParts.join("、")}，` : ""}最終倍率 ×${synergy.bonusMultiplier.toFixed(2)}，共造成 ${totalDamage} 點傷害。`);
      } else {
        mechanic.lastSync = "parity_mismatch";
        battle.log.push(`雙世界第一顆骰 ${realResult.firstDiceFace}（${totMusicaDiceParityLabel(realResult.firstDiceFace)}）與 ${songResult.firstDiceFace}（${totMusicaDiceParityLabel(songResult.firstDiceFace)}）奇偶不同，兩道攻擊分流直擊並保留 5% 基礎傷害；${bonusParts.length ? `${bonusParts.join("、")}，` : ""}最終傷害率 ${(finalDamageRate * 100).toFixed(0)}%，共造成 ${totalDamage} 點傷害。`);
      }
    } else {
      mechanic.lastSync = "no_attack_roll";
      battle.log.push("雙世界同步失敗：至少一邊沒有使用直接攻擊並擲出判定骰，Tot Musica 的次元屏障抵銷全部傷害。");
    }
    [[realResult, realPlayer], [songResult, songPlayer]].forEach(([result, worldPlayer], index) => {
      if (!result?.direct || !result.move) return;
      const settleCarry = () => {
        setTotMusicaActiveWorldCrew(worldPlayer, battle, mechanic, result.world, result.cardIndex);
        const actualWorldDamage = Math.max(0, Number(scaledWorldDamages[index] || 0));
        applyPlayerCarryAfterDirectAction("player", result.move, !!result.hit, actualWorldDamage, result.diceFace, worldPlayer, battle);
      };
      if (playerWorlds) withCoopBattleRuntime(worldPlayer, battle, settleCarry, { save: true });
      else settleCarry();
    });
    if (!playerWorlds) setTotMusicaActiveWorldCrew(player, battle, mechanic, "real", mechanic.realActiveIndex);
    const representativeMove = songResult.move || realResult.move;
    postgameBossMechanicAfterMove("player", representativeMove, Math.max(realResult.diceFace || 0, songResult.diceFace || 0), bothAttackRolls, totalDamage, realPlayer, battle);
    battle.playerDiceRoll = Math.max(realResult.diceFace || 0, songResult.diceFace || 0);
    battle.playerPerformedAction = true;
    const worldVisual = (result, fallbackIndex, worldPlayer) => {
      const parsedIndex = Number(result?.cardIndex);
      const cardIndex = Number.isInteger(parsedIndex) && parsedIndex >= 0 ? parsedIndex : Math.max(0, Number(fallbackIndex || 0));
      const card = worldPlayer.crew?.[cardIndex] || {};
      const portraits = sanjiRaidSuitBattleViewPortraits(card, worldPlayer, battle, cardIndex) || cardPortraitsForDisplay(card) || card.battlePortraits || {};
      return {
        world: result?.world || "",
        worldLabel: result?.label || "",
        cardIndex,
        actorName: cardDisplayName(card) || result?.label || "夥伴",
        battlePortraits: safeJsonClone(portraits),
        playerId: String(worldPlayer.id || ""),
        playerName: worldPlayer.name || "共鬥玩家",
        cosmeticFrameId: activeCrewCosmeticFrameId(worldPlayer, card) || defaultCharacterCosmeticFrameId(card),
        moveName: result?.move?.name || result?.actionName || (result?.switched ? "免費調度" : "行動未成立"),
        moveType: result?.move?.category || "",
        moveAttribute: String(result?.move?.attribute || card.attribute || "無"),
        direct: !!result?.direct,
        hit: !!result?.hit,
        switched: !!result?.switched,
        itemUsed: !!result?.itemUsed,
        firstDiceFace: Number(result?.firstDiceFace || 0),
        diceRolls: (Array.isArray(result?.diceRolls) ? result.diceRolls : []).map((value) => Number(value || 0)).filter((value) => value > 0).slice(0, 3),
        diceTotal: Number(result?.diceFace || 0),
        parityLabel: totMusicaDiceParityLabel(result?.firstDiceFace),
        damage: Math.max(0, Number(result?.damage || 0)),
        critical: !!result?.critical,
        criticalCount: Math.max(0, Number(result?.criticalCount || 0)),
        criticalHitIndexes: Array.isArray(result?.criticalHitIndexes) ? result.criticalHitIndexes.slice() : [],
        currentHp: Math.max(0, Number(card.currentHp || 0)),
        maxHp: Math.max(1, Number(cardMaxHp(card) || 1)),
      };
    };
    const realFallbackIndex = playerWorlds ? coopBattleRuntimeFor(realPlayer, battle, true)?.activeCrewIndex : mechanic.realActiveIndex;
    const songFallbackIndex = playerWorlds ? coopBattleRuntimeFor(songPlayer, battle, true)?.activeCrewIndex : mechanic.songActiveIndex;
    const realVisual = worldVisual(realResult, realFallbackIndex, realPlayer);
    const songVisual = worldVisual(songResult, songFallbackIndex, songPlayer);
    const synergyLabels = [
      synergy.sameAttribute ? "同屬性 +50%" : "",
      synergy.sameFirstDie ? "第一骰同點 +50%" : "",
      synergy.sameMoveClass ? `${synergy.realMoveClass === "special" ? "同為特攻" : "同為普通攻擊"} +20%` : "",
    ].filter(Boolean);
    const bonusText = synergyLabels.length ? `・${synergyLabels.join("・")}` : "";
    const resultText = synchronized
      ? `同為${realVisual.parityLabel}・同步 ×${synergy.bonusMultiplier.toFixed(2)}${bonusText}`
      : bothAttackRolls
        ? `${realVisual.parityLabel}／${songVisual.parityLabel}・分流 ${(finalDamageRate * 100).toFixed(0)}%${bonusText}`
        : "至少一邊沒有直接攻擊骰";
    const displayedDiceCount = Math.max(1, realVisual.diceRolls.length, songVisual.diceRolls.length);
    const visualDuration = (bothAttackRolls ? 13800 : 7600) + Math.max(0, displayedDiceCount - 1) * 2600;
    const holdBossForEnemy = bothAttackRolls && battle.firstActor === "player" && battle.secondActor === "enemy";
    battle.visualEvent = attachBattleVisualEventSnapshots({
      id: `tot-sync-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      type: "tot-musica-dual-sync",
      side: "player",
      targetSide: "enemy",
      actorName: `${realVisual.actorName} ＋ ${songVisual.actorName}`,
      targetName: battle.enemyCombatant.name,
      moveName: synchronized ? "雙世界奇偶同步攻擊" : bothAttackRolls ? "雙世界分流直擊" : "次元屏障・同步失敗",
      moveType: "special",
      damage: totalDamage,
      hitDamages: bothAttackRolls ? scaledWorldDamages : [],
      critical: !!(realVisual.critical || songVisual.critical),
      criticalCount: Math.max(0, Number(realVisual.criticalCount || 0)) + Math.max(0, Number(songVisual.criticalCount || 0)),
      criticalHitIndexes: [realVisual.critical ? 0 : -1, songVisual.critical ? 1 : -1].filter((index) => index >= 0),
      diceFace: battle.playerDiceRoll,
      miss: !bothAttackRolls,
      synchronized,
      partialStrike,
      bothAttackRolls,
      bothDirectHits: bothAttackRolls,
      holdBossForEnemy,
      parityMatched,
      baseDamageRate,
      finalDamageRate,
      synergy: safeJsonClone({ ...synergy, labels: synergyLabels }),
      resultText,
      realWorld: realVisual,
      songWorld: songVisual,
      startSnapshot: safeJsonClone(beforeSnapshot),
      duration: visualDuration,
    }, battle);
    notifyBattleWindow();
    await waitBattleWindowVisual(battle.visualEvent, visualDuration);
    if (battle.enemyCombatant.currentHp <= 0) {
      battle.result = "win";
      battle.log.push("雙世界同時擊破 Tot Musica，戰鬥勝利。");
    } else {
      postgameTotPrepareCounterattackAfterPlayerAction(player, battle, mechanic);
    }
    renderBattleInterface();
  }

  function totMusicaWorldCombatantVisual(player, battle, mechanic, world, cardIndex, extras = {}) {
    const card = player.crew?.[Number(cardIndex)] || {};
    const portraits = sanjiRaidSuitBattleViewPortraits(card, player, battle, Number(cardIndex)) || cardPortraitsForDisplay(card) || card.battlePortraits || {};
    return {
      world,
      worldLabel: world === "real" ? "現實世界" : "歌世界",
      cardIndex: Number(cardIndex),
      actorName: cardDisplayName(card) || (world === "real" ? "現實世界夥伴" : "歌世界夥伴"),
      battlePortraits: safeJsonClone(portraits),
      cosmeticFrameId: activeCrewCosmeticFrameId(player, card) || defaultCharacterCosmeticFrameId(card),
      currentHp: Math.max(0, Number(card.currentHp || 0)),
      maxHp: Math.max(1, Number(cardMaxHp(card) || 1)),
      ...extras,
    };
  }

  function totMusicaLivingWorldIndex(player, mechanic, world, battle = state.battleState) {
    const playerWorlds = postgameTotUsesPlayerWorlds(battle, mechanic);
    const indices = playerWorlds
      ? (player?.crew || []).map((_card, index) => index)
      : world === "real" ? mechanic.realIndices : mechanic.songIndices;
    const runtime = playerWorlds ? coopBattleRuntimeFor(player, battle, true) : null;
    const activeIndex = Number(runtime?.activeCrewIndex ?? (world === "real" ? mechanic.realActiveIndex : mechanic.songActiveIndex));
    if (indices.includes(activeIndex) && Number(player.crew?.[activeIndex]?.currentHp || 0) > 0) return activeIndex;
    return indices.find((index) => Number(player.crew?.[index]?.currentHp || 0) > 0) ?? -1;
  }

  function postgameTotResolveSoloWorldFrontlines(player, battle, mechanic, options = {}) {
    if (!player || mechanic?.key !== "postgame_tot_musica" || postgameTotUsesPlayerWorlds(battle, mechanic)) {
      return { realSurvivor: -1, songSurvivor: -1, lostWorld: "" };
    }
    const shouldLog = options.log !== false;
    for (const world of ["real", "song"]) {
      const currentIndex = Number(world === "real" ? mechanic.realActiveIndex : mechanic.songActiveIndex);
      if (Number(player.crew?.[currentIndex]?.currentHp || 0) > 0) continue;
      const nextIndex = totMusicaLivingWorldIndex(player, mechanic, world, battle);
      if (nextIndex < 0) continue;
      const next = setTotMusicaActiveWorldCrew(player, battle, mechanic, world, nextIndex);
      if (shouldLog) battle.log.push(`${world === "real" ? "現實世界" : "歌世界"}由 ${cardDisplayName(next)} 自動接替上場。`);
    }
    const realSurvivor = totMusicaLivingWorldIndex(player, mechanic, "real", battle);
    const songSurvivor = totMusicaLivingWorldIndex(player, mechanic, "song", battle);
    const lostWorld = realSurvivor < 0 ? "real" : songSurvivor < 0 ? "song" : "";
    if (lostWorld) {
      battle.result = "lose";
      battle.needsReplacement = false;
      battle.replacementAfterAction = false;
      if (shouldLog) battle.log.push(`${lostWorld === "real" ? "現實世界" : "歌世界"}已無可戰鬥船員，雙世界同步戰失敗。`);
      return { realSurvivor, songSurvivor, lostWorld };
    }
    setTotMusicaActiveWorldCrew(player, battle, mechanic, "real", realSurvivor);
    // Tot Musica 由各世界自己的順位自動接替，不得被通用／共鬥的單角色 replacement 攔截反擊。
    battle.needsReplacement = false;
    if (battle.result === "replacement") battle.result = "";
    battle.replacementAfterAction = false;
    delete battle.replacementReason;
    delete battle.pendingReplacementActiveCrewIndex;
    if (isCoopBattle(battle)) saveCoopBattleRuntime(player, battle);
    return { realSurvivor, songSurvivor, lostWorld: "" };
  }

  function postgameTotPrepareCounterattackAfterPlayerAction(player, battle, mechanic) {
    if (mechanic?.key !== "postgame_tot_musica" || Number(battle?.enemyCombatant?.currentHp || 0) <= 0) return false;
    if (battle.result && battle.result !== "replacement") return false;
    if (postgameTotUsesPlayerWorlds(battle, mechanic)) {
      const frontline = postgameTotResolvePlayerWorldFrontlines(battle, mechanic, { resetSelection: false });
      if (frontline.lostWorld) return false;
    } else {
      const frontline = postgameTotResolveSoloWorldFrontlines(player, battle, mechanic);
      if (frontline.lostWorld) return false;
    }
    if (battle.result) return false;
    const queuedMove = getMoveByAction("enemy", battle.enemyAction, player, battle);
    if (!queuedMove || Number(queuedMove.currentPP ?? queuedMove.pp ?? 0) <= 0) {
      battle.enemyAction = chooseEnemyAction(battle);
    }
    return !!battle.enemyAction;
  }

  function postgameTotEnemyBlockedReason(battle) {
    const bag = battleStatusBag("enemy", battle);
    if (Number(bag.freeze || 0) > 0) return "冰凍";
    if (Number(bag.bind || 0) > 0) return "束縛";
    if (Number(bag.paralyze || 0) > 0) return "麻痺";
    return "異常狀態";
  }

  async function executeTotMusicaEnemyAction(player, battle, action) {
    const mechanic = postgameBossMechanicFor(battle);
    if (mechanic?.key !== "postgame_tot_musica" || !mechanic.assigned) return;
    const moveEntry = getMoveByAction("enemy", action, player, battle);
    if (!moveEntry || Number(moveEntry.currentPP ?? moveEntry.pp ?? 0) <= 0) return;
    if (await isBattleActionBlockedByStatus("enemy", player, battle)) {
      battle.enemyPerformedAction = true;
      const mechanic = postgameBossMechanicFor(battle);
      const playerWorlds = postgameTotUsesPlayerWorlds(battle, mechanic);
      const blockedReason = postgameTotEnemyBlockedReason(battle);
      const worldVisual = (world) => {
        const worldPlayer = playerWorlds ? postgameTotActiveWorldPlayer(battle, mechanic, world) : player;
        const activeIndex = worldPlayer ? totMusicaLivingWorldIndex(worldPlayer, mechanic, world, battle) : -1;
        return activeIndex >= 0
          ? totMusicaWorldCombatantVisual(worldPlayer, battle, mechanic, world, activeIndex, {
            playerId: String(worldPlayer.id || ""),
            playerName: worldPlayer.name || "共鬥玩家",
            startHp: Math.max(0, Number(worldPlayer.crew?.[activeIndex]?.currentHp || 0)),
            hit: false,
            affected: false,
            damage: 0,
          })
          : { world, worldLabel: world === "real" ? "現實世界" : "歌世界", cardIndex: -1, actorName: "無可戰鬥船員", currentHp: 0, maxHp: 1, hit: false, affected: false, damage: 0 };
      };
      const continueFromPlayerHigh = battle.firstActor === "player" && battle.secondActor === "enemy" && battle.playerPerformedAction;
      const duration = continueFromPlayerHigh ? 3400 : 5200;
      battle.visualEvent = attachBattleVisualEventSnapshots({
        id: `tot-enemy-blocked-${Date.now()}-${Math.random().toString(36).slice(2)}`,
        type: "tot-musica-enemy-dual-strike",
        side: "enemy",
        targetSide: "player",
        actorName: battle.enemyCombatant.name,
        moveName: moveEntry.name,
        moveType: moveEntry.category || moveEntry.type || "attack",
        blocked: true,
        blockedReason,
        dealsDamage: false,
        continueFromPlayerHigh,
        enemy: {
          name: battle.enemyCombatant.name,
          battlePortraits: safeJsonClone(battle.enemyCombatant?.battlePortraits || {}),
          cosmeticFrameId: battle.enemyCombatant.cosmeticFrameId || "postgameTotMusica",
          currentHp: Math.max(0, Number(battle.enemyCombatant.currentHp || 0)),
          maxHp: Math.max(1, Number(battle.enemyCombatant.maxHp || 1)),
        },
        realWorld: worldVisual("real"),
        songWorld: worldVisual("song"),
        duration,
      }, battle);
      battle.log.push(`${battle.enemyCombatant.name} 因${blockedReason}無法行動，雙世界暫時逃過攻擊。`);
      notifyBattleWindow();
      await waitBattleWindowVisual(battle.visualEvent, duration);
      renderBattleInterface();
      return;
    }
    moveEntry.currentPP = Math.max(0, Number(moveEntry.currentPP ?? moveEntry.pp ?? 0) - 1);
    let diceRolls = [];
    const diceFace = await rollBattleActionDiceWithPassives(
      battleDiceThemeForMove(moveEntry),
      `${battle.enemyCombatant.name} 使用 ${moveEntry.name}`,
      "魔王的攻擊會由上往下同時籠罩兩個世界…",
      battle,
      6,
      {
        side: "enemy",
        moveType: isComboBattleMove(moveEntry) ? "combo" : (moveEntry.category || moveEntry.type || "attack"),
        castSfx: battleCastSfxForMove(moveEntry),
        suppressVisual: true,
        onDiceResolved: (rolls) => { diceRolls = (Array.isArray(rolls) ? rolls : []).map((value) => Number(value || 0)).filter((value) => value > 0); },
      },
    );
    battle.enemyDiceRoll = diceFace;
    const beforeEnemyHp = Number(battle.enemyCombatant.currentHp || 0);
    const worldResults = [];
    let totalDamage = 0;
    let anyHit = false;
    const dealsDamage = battleMoveDealsDamage(moveEntry);
    const playerWorlds = postgameTotUsesPlayerWorlds(battle, mechanic);

    if (!dealsDamage && ["heal", "buff"].includes(moveEntry.category)) {
      applyMoveEffects(moveEntry, "enemy", diceFace, player, battle, moveEntry.category, 0);
    }

    for (const world of ["real", "song"]) {
      const worldPlayer = playerWorlds ? postgameTotActiveWorldPlayer(battle, mechanic, world) : player;
      const resolveTarget = async () => {
        const activeIndex = worldPlayer ? totMusicaLivingWorldIndex(worldPlayer, mechanic, world, battle) : -1;
        if (activeIndex < 0) return { world, worldLabel: world === "real" ? "現實世界" : "歌世界", cardIndex: -1, actorName: "無可戰鬥船員", currentHp: 0, maxHp: 1, hit: false, damage: 0, knockedOut: true };
        const card = setTotMusicaActiveWorldCrew(worldPlayer, battle, mechanic, world, activeIndex);
        const beforeHp = Math.max(0, Number(card.currentHp || 0));
        preparePlayerMoguraForEnemyMove(moveEntry, worldPlayer, battle);
        const hitCheck = dealsDamage ? battleMoveHits("enemy", moveEntry, worldPlayer, battle) : { hit: true, chance: 100 };
        let actualDamage = 0;
        let hitDamages = [];
        const criticalVisual = { critical: false, criticalCount: 0 };
        if (dealsDamage && hitCheck.hit) {
          const bonus = bonusDamageFromMove(moveEntry, diceFace, worldPlayer, battle, "enemy");
          if (isComboBattleMove(moveEntry)) {
            let maxHits = comboMoveMaxHits(moveEntry, diceFace);
            maxHits = battleCarryAdjustedMultiHit("enemy", moveEntry, diceFace, maxHits, worldPlayer, battle);
            hitDamages = computeComboHitDamages("enemy", moveEntry, diceFace, maxHits, bonus, worldPlayer, battle, criticalVisual);
          } else {
            hitDamages = splitBattleDamageIntoHits(computeMoveDamage("enemy", moveEntry, diceFace, worldPlayer, battle, criticalVisual), 1, bonus);
          }
          let targetDamage = battleDamageHitTotal(hitDamages);
          targetDamage = applyDefensiveBattleCarryBeforeDamage("player", targetDamage, worldPlayer, battle, criticalVisual);
          targetDamage = applyShipFirstBattleDamageReduction(targetDamage, worldPlayer, battle);
          targetDamage = applyYonkoEnemyTotalDamageBeforeApply(targetDamage, "enemy", moveEntry, worldPlayer, battle);
          hitDamages = scaleBattleHitDamagesToTotal(hitDamages, targetDamage);
          hitDamages = applyPostgameBossDamageRules(hitDamages, "enemy", moveEntry, diceFace, worldPlayer, battle, action, criticalVisual);
          targetDamage = battleDamageHitTotal(hitDamages);
          card.currentHp = Math.max(0, beforeHp - targetDamage);
          actualDamage = Math.max(0, beforeHp - Number(card.currentHp || 0));
          totalDamage += actualDamage;
          anyHit = true;
          postgameBossMechanicAfterDirectHit("enemy", moveEntry, diceFace, actualDamage, worldPlayer, battle, action);
          storeBattleCarryDamageAfterHit("player", actualDamage, worldPlayer, battle);
          applyCharacterPassiveAfterDamageTaken(worldPlayer, battle, card, actualDamage, moveEntry);
          if (card.currentHp <= 0 && !tryPlayerBattleCarryRevive(worldPlayer, battle, card)) tryCharacterPassiveRevive(worldPlayer, battle, card);
          applyMoveEffects(moveEntry, "enemy", diceFace, worldPlayer, battle, "attack", actualDamage);
        } else if (dealsDamage) {
          applyMoveEffects(moveEntry, "enemy", diceFace, worldPlayer, battle, "miss", 0);
        } else if (!["heal", "buff"].includes(moveEntry.category)) {
          applyMoveEffects(moveEntry, "enemy", diceFace, worldPlayer, battle, "status", 0);
          anyHit = true;
        }
        recordJudicialRaidContribution(battle, worldPlayer, { damageTaken: actualDamage });
        return totMusicaWorldCombatantVisual(worldPlayer, battle, mechanic, world, activeIndex, {
          playerId: String(worldPlayer.id || ""),
          playerName: worldPlayer.name || "共鬥玩家",
          startHp: beforeHp,
           hit: dealsDamage && !!hitCheck.hit,
           raidSuitStealth: !!hitCheck.raidSuitStealth,
           fatalGuard: !!criticalVisual.fatalGuard,
           fatalGuardLabel: String(criticalVisual.fatalGuardLabel || ""),
           fatalGuardItemName: String(criticalVisual.fatalGuardItemName || ""),
           affected: !dealsDamage || !!hitCheck.hit,
          damage: actualDamage,
          hitDamages,
          critical: !!criticalVisual.critical,
          criticalCount: Math.max(0, Number(criticalVisual.criticalCount || 0)),
          criticalHitIndexes: Array.isArray(criticalVisual.criticalHitIndexes) ? criticalVisual.criticalHitIndexes.slice() : [],
          knockedOut: Number(card.currentHp || 0) <= 0,
        });
      };
      const result = playerWorlds && worldPlayer
        ? await withCoopBattleRuntimeAsync(worldPlayer, battle, resolveTarget, { save: true })
        : await resolveTarget();
      worldResults.push(result);
    }

    postgameBossMechanicAfterMove("enemy", moveEntry, diceFace, anyHit, totalDamage, player, battle);
    battle.enemyPerformedAction = true;
    const actorRound = battle.enemyCombatant.roundEffects;
    if (actorRound) actorRound.nextHitBoost = 0;
    const bossPortraits = battle.enemyCombatant?.battlePortraits || {};
    const continueFromPlayerHigh = battle.firstActor === "player"
      && battle.secondActor === "enemy"
      && battle.playerPerformedAction
      && ["success", "parity_mismatch"].includes(String(mechanic.lastSync || ""));
    const duration = (continueFromPlayerHigh ? 11100 : 14000) + Math.max(0, diceRolls.length - 1) * 2600;
    battle.visualEvent = attachBattleVisualEventSnapshots({
      id: `tot-enemy-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      type: "tot-musica-enemy-dual-strike",
      side: "enemy",
      targetSide: "player",
      actorName: battle.enemyCombatant.name,
      moveName: moveEntry.name,
      moveType: moveEntry.category || moveEntry.type || "attack",
      dealsDamage,
      continueFromPlayerHigh,
      diceFace,
      diceRolls,
      damage: totalDamage,
      critical: worldResults.some((entry) => entry.critical),
      criticalCount: worldResults.reduce((sum, entry) => sum + Math.max(0, Number(entry.criticalCount || 0)), 0),
      criticalHitIndexes: worldResults.map((entry, index) => entry.critical ? index : -1).filter((index) => index >= 0),
      miss: dealsDamage && !worldResults.some((entry) => entry.hit),
      enemy: {
        name: battle.enemyCombatant.name,
        battlePortraits: safeJsonClone(bossPortraits),
        cosmeticFrameId: battle.enemyCombatant.cosmeticFrameId || "postgameTotMusica",
        currentHp: Math.max(0, Number(battle.enemyCombatant.currentHp || 0)),
        maxHp: Math.max(1, Number(battle.enemyCombatant.maxHp || 1)),
      },
      realWorld: worldResults.find((entry) => entry.world === "real") || {},
      songWorld: worldResults.find((entry) => entry.world === "song") || {},
      duration,
    }, battle);
    battle.log.push(dealsDamage
      ? `${battle.enemyCombatant.name} 使用 ${moveEntry.name}，骰出 ${diceFace}，由上往下同時攻擊兩個世界，共造成 ${totalDamage} 點傷害。`
      : `${battle.enemyCombatant.name} 使用 ${moveEntry.name}，骰出 ${diceFace}，效果同時作用於兩個世界；這是控制招式，不造成直接傷害。`);
    notifyBattleWindow();
    await waitBattleWindowVisual(battle.visualEvent, duration);

    if (playerWorlds) {
      postgameTotResolvePlayerWorldFrontlines(battle, mechanic);
    } else {
      postgameTotResolveSoloWorldFrontlines(player, battle, mechanic);
    }
    if (Number(battle.enemyCombatant.currentHp || 0) > beforeEnemyHp) {
      battle.enemyCombatant.currentHp = Math.min(Number(battle.enemyCombatant.maxHp || beforeEnemyHp), Number(battle.enemyCombatant.currentHp || 0));
    }
    renderBattleInterface();
  }

