  function normalizeShipSkinId(value) {
    const raw = typeof value === "object" && value
      ? value.id || value.shipId || value.shipSkinId || value.image || ""
      : value;
    const match = String(raw || "").match(/ship[_-]?0?([1-6])/i);
    return match ? `ship_${String(Number(match[1])).padStart(2, "0")}` : "";
  }

  function shipSkinById(value) {
    const id = normalizeShipSkinId(value);
    return SHIP_SKINS.find((skin) => skin.id === id) || null;
  }

  function shipSkinForPlayer(player, index = 0) {
    return shipSkinById(player?.shipSkin)
      || shipSkinById(player?.shipId)
      || shipSkinById(player?.shipSkinId)
      || shipSkinById(player?.ship)
      || SHIP_SKINS[index % SHIP_SKINS.length];
  }

  function isPlayerInBattleOnMap(player) {
    if (!player) return false;
    if (state.battleState && String(state.battleState.playerId || "") === String(player.id || "")) return true;
    if (state.battleState?.coop?.enabled) {
      const participantIds = Array.isArray(state.battleState.coop.participantIds) ? state.battleState.coop.participantIds : [];
      if (participantIds.some((id) => String(id) === String(player.id))) return true;
    }
    if (player.pendingBattle?.islandId) {
      const pendingIslandState = getIslandState(player.pendingBattle.islandId);
      if (pendingIslandState?.isDefeated) return false;
      const pendingKey = battleEnemyIdentityKey(player.pendingBattle);
      const currentKey = String(pendingIslandState?.enemyProfile?.key || pendingIslandState?.enemyProfile?.id || pendingIslandState?.enemyProfile?.name || "").trim();
      if (pendingKey && currentKey && pendingKey !== currentKey) return false;
    }
    return !!player.pendingBattle;
  }

  function shipBattleStatusIconHtml(player) {
    if (!isPlayerInBattleOnMap(player)) return "";
    const frames = SHIP_BATTLE_STATUS_ICON_FRAMES.map((src, frameIndex) => (
      `<img class="ship-battle-status-frame frame-${frameIndex + 1}" src="${src}" alt="" loading="eager" decoding="async" draggable="false">`
    )).join("");
    return `<div class="ship-battle-status" title="戰鬥中" aria-label="戰鬥中">${frames}</div>`;
  }

  function shipMoveLearnBadgeHtml(player) {
    if (!shouldShowMoveLearnBadgeFor(player)) return "";
    const count = pendingMoveLearnCountForPlayer(player);
    if (count <= 0) return "";
    const label = `有 ${count} 個新技能可以學習`;
    return `<div class="ship-move-learn-badge" title="${escapeModalText(label)}" aria-label="${escapeModalText(label)}">新技${count > 1 ? `<b>${count}</b>` : ""}</div>`;
  }

  function waterSevenShipIdForPlayer(player = currentPlayer()) {
    const players = state.gameState?.players || [];
    const playerIndex = Math.max(0, players.findIndex((entry) => String(entry?.id) === String(player?.id)));
    return shipSkinForPlayer(player, playerIndex)?.id || "ship_01";
  }

  function normalizeShipUpgradeLevels(levels = {}) {
    const source = levels && typeof levels === "object" && !Array.isArray(levels) ? levels : {};
    return Object.fromEntries(WATER_SEVEN_UPGRADE_PARTS.map((part) => {
      const value = Number(source[part]);
      return [part, Number.isFinite(value) ? Math.max(0, Math.min(3, Math.round(value))) : 0];
    }));
  }

  function normalizePlayerShipState(player) {
    if (!player) {
      return {
        upgradeLevels: normalizeShipUpgradeLevels(),
        slotsUnlocked: 0,
        equippedGear: [null, null, null, null],
      };
    }
    const inventory = ensurePlayerInventoryState(player);
    player.shipUpgradeLevels = normalizeShipUpgradeLevels(player.shipUpgradeLevels);
    const slotValue = Number(player.shipSlotsUnlocked);
    player.shipSlotsUnlocked = Number.isFinite(slotValue)
      ? Math.max(0, Math.min(WATER_SEVEN_SLOT_COUNT, Math.round(slotValue)))
      : 0;
    const sourceGear = Array.isArray(player.shipEquippedGear) ? player.shipEquippedGear : [];
    const usedGear = new Set();
    player.shipEquippedGear = Array.from({ length: WATER_SEVEN_SLOT_COUNT }, (_, index) => {
      if (index >= player.shipSlotsUnlocked) return null;
      const itemId = String(sourceGear[index] || "").trim();
      if (!itemId || usedGear.has(itemId)) return null;
      const item = gameItemDef(itemId);
      const owned = Math.max(0, Math.round(Number(inventory.items?.[itemId] || 0)));
      const isShipEquipment = item && normalizeGameItemCategory(item.category) === "ship" && item.effect?.kind === "ship_equipment";
      if (!isShipEquipment || owned <= 0) return null;
      usedGear.add(itemId);
      return itemId;
    });
    return {
      upgradeLevels: player.shipUpgradeLevels,
      slotsUnlocked: player.shipSlotsUnlocked,
      equippedGear: player.shipEquippedGear,
    };
  }

  function playerShipUpgradeLevel(player, partId) {
    return normalizePlayerShipState(player).upgradeLevels[partId] || 0;
  }

  function waterSevenPartLabel(partId) {
    return {
      sail: "桅杆",
      rudder: "船尾",
      watchtower: "偵查台",
      kitchen: "廚房",
      training: "甲板",
    }[partId] || "船隻部位";
  }

  function shipUpgradeIconPath(partId) {
    const key = WATER_SEVEN_UPGRADE_PARTS.includes(partId) ? partId : "sail";
    return `${SHIP_UPGRADE_ICON_BASE}/${key}.webp`;
  }

  function waterSevenCostSummary(cost = {}) {
    const parts = [];
    const berries = Math.max(0, Math.round(Number(cost.berries || 0)));
    if (berries > 0) parts.push(`${formatCoin(berries)} 貝里`);
    WATER_SEVEN_MATERIAL_ITEMS.forEach(({ key, id }) => {
      const amount = Math.max(0, Math.round(Number(cost[key] || 0)));
      if (amount <= 0) return;
      parts.push(`${gameItemDef(id)?.name || key} x${amount}`);
    });
    return parts.join("、") || "無費用";
  }

  function waterSevenCanSpendCost(player, cost = {}) {
    if (!player) return false;
    const inventory = ensurePlayerInventoryState(player);
    if (Math.max(0, Math.round(Number(player.coins || 0))) < Math.max(0, Math.round(Number(cost.berries || 0)))) return false;
    return WATER_SEVEN_MATERIAL_ITEMS.every(({ key, id }) => {
      const required = Math.max(0, Math.round(Number(cost[key] || 0)));
      return required <= 0 || Math.max(0, Math.round(Number(inventory.items?.[id] || 0))) >= required;
    });
  }

  function waterSevenSpendCost(player, cost = {}) {
    if (!waterSevenCanSpendCost(player, cost)) return false;
    player.coins = Math.max(0, Math.round(Number(player.coins || 0)) - Math.max(0, Math.round(Number(cost.berries || 0))));
    WATER_SEVEN_MATERIAL_ITEMS.forEach(({ key, id }) => {
      const required = Math.max(0, Math.round(Number(cost[key] || 0)));
      if (required > 0) removeInventoryItem(player, id, required);
    });
    return true;
  }

  function waterSevenShipGearCatalog(player) {
    const inventory = ensurePlayerInventoryState(player);
    return Object.values(GAME_ITEMS)
      .filter((item) => normalizeGameItemCategory(item?.category) === "ship" && item?.effect?.kind === "ship_equipment")
      .filter((item) => itemUnlockedByBounty(player, item) || Math.max(0, Math.round(Number(inventory.items?.[item.id] || 0))) > 0)
      .sort((a, b) => {
        const rankOrder = { C: 0, B: 1, A: 2, S: 3 };
        return (rankOrder[itemRarityLabel(a.rarity)] || 0) - (rankOrder[itemRarityLabel(b.rarity)] || 0)
          || String(a.name || "").localeCompare(String(b.name || ""), "zh-Hant");
      });
  }

  function waterSevenFormalItemView(item, count = 0) {
    const category = normalizeGameItemCategory(item?.category);
    const rarity = itemRarityLabel(item?.rarity);
    return {
      id: item?.id || "",
      name: item?.name || "未知道具",
      rank: rarity,
      rarity,
      category,
      kind: WATER_SEVEN_SHIP_GEAR_TYPE_BY_ID[item?.id] || item?.shipType || item?.subType || (item?.effect?.kind === "ship_material" ? "船材" : "船隻裝備"),
      effect: item?.description || item?.uiSummary || "",
      desc: item?.balanceNote || item?.uiSummary || item?.description || "",
      image: item?.image || (item?.id ? `images/board/items/${item.id}.webp` : ""),
      imageKey: item?.imageKey || "",
      count: Math.max(0, Math.round(Number(count || 0))),
    };
  }

  function getWaterSevenView(player = currentPlayer()) {
    if (!player) return null;
    const players = state.gameState?.players || [];
    const playerIndex = Math.max(0, players.findIndex((entry) => String(entry?.id) === String(player.id)));
    const shipSkin = shipSkinForPlayer(player, playerIndex);
    const inventory = ensurePlayerInventoryState(player);
    const shipState = normalizePlayerShipState(player);
    const upgradeLevels = shipState.upgradeLevels;
    const slotsUnlocked = shipState.slotsUnlocked;
    const materials = {};
    const materialItems = WATER_SEVEN_MATERIAL_ITEMS
      .map(({ key, id }) => {
        const item = gameItemDef(id);
        const count = Math.max(0, Math.round(Number(inventory.items?.[id] || 0)));
        materials[key] = count;
        return item ? { key, ...waterSevenFormalItemView(item, count) } : null;
      })
      .filter(Boolean);
    const shipEquipment = waterSevenShipGearCatalog(player)
      .map((item) => waterSevenFormalItemView(item, inventory.items?.[item.id] || 0));
    return {
      playerId: player.id,
      playerName: player.name,
      berries: Math.max(0, Math.round(Number(player.coins || 0))),
      shipId: shipSkin?.id || "ship_01",
      shipName: shipSkin?.name || "玩家船隻",
      slotsUnlocked,
      upgradeLevels,
      upgradeCosts: Object.fromEntries(WATER_SEVEN_UPGRADE_PARTS.map((part) => [
        part,
        (WATER_SEVEN_UPGRADE_COSTS[part] || []).map((cost) => ({ ...cost })),
      ])),
      slotCosts: WATER_SEVEN_SLOT_COSTS.map((cost) => ({ ...cost })),
      equippedShipGear: shipState.equippedGear.slice(0, WATER_SEVEN_SLOT_COUNT),
      materials,
      materialItems,
      shipEquipment,
      updatedAt: Date.now(),
    };
  }
