  function postgameLegacyRecruitPoolUnlocked(game = state.gameState) {
    if (!game) return false;
    return Boolean(
      game.finalEndingCleared
      || (game.finalEndingRecords && Object.keys(game.finalEndingRecords).length)
      || game.postgameWorld?.unlocked
    );
  }

  function cardAvailableInNormalRecruitPool(card, game = state.gameState) {
    const id = String(card?.id || card || "").trim();
    if (!id) return false;
    if (POSTGAME_LEGACY_RECRUIT_CARD_IDS.has(id)) {
      return postgameLegacyRecruitPoolUnlocked(game);
    }
    return !STORY_RECRUIT_CARD_IDS.has(id);
  }

  function syncAvailableCardsWithCatalog(game) {
    if (!game) return 0;
    const available = Array.isArray(game.availableCards) ? game.availableCards : [];
    const normalized = [];
    const seenIds = new Set();
    available.forEach((card) => {
      const id = String(card?.id || "").trim();
      if (!id || seenIds.has(id)) return;
      const catalogCard = CHARACTER_CARDS.find((entry) => entry.id === id);
      normalized.push(cloneCard(catalogCard || card));
      seenIds.add(id);
    });
    const ownedIds = new Set();
    (game.players || []).forEach((player) => {
      (player?.crew || []).forEach((card) => {
        const id = String(card?.id || "").trim();
        if (id) ownedIds.add(id);
      });
    });
    let added = 0;
    CHARACTER_CARDS.forEach((catalogCard) => {
      const id = String(catalogCard?.id || "").trim();
      if (!id || seenIds.has(id) || ownedIds.has(id)) return;
      if (!cardAvailableInNormalRecruitPool(catalogCard, game)) return;
      normalized.push(cloneCard(catalogCard));
      seenIds.add(id);
      added += 1;
    });
    game.availableCards = normalized;
    return added;
  }

  function normalizeLoadedGameState(options = {}) {
    const game = state.gameState;
    if (!game || !game.boardData) return false;
    game.players = Array.isArray(game.players) ? game.players : [];
    ensureGameSettings(game);
    game.currentPlayerIndex = Math.max(0, Math.min(game.players.length - 1, Number(game.currentPlayerIndex) || 0));
    game.round = Math.max(1, Number(game.round || 1));
    game.seaEncounterRefreshCycle = Math.max(0, Number(game.seaEncounterRefreshCycle || 0));
    game.seaEncounterLastRefreshRound = Math.max(1, Number(game.seaEncounterLastRefreshRound || game.round || 1));
    game.finalIslandCandidate = Boolean(game.finalIslandCandidate);
    game.finalEndingRecords = game.finalEndingRecords && typeof game.finalEndingRecords === "object" ? game.finalEndingRecords : {};
    game.finalEndingCleared = Boolean(game.finalEndingCleared || Object.keys(game.finalEndingRecords).length);
    game.finalEndingLast = game.finalEndingLast && typeof game.finalEndingLast === "object" ? game.finalEndingLast : null;
    game.finalIslandUnlocked = Boolean(game.finalIslandUnlocked || game.finalEndingCleared);
    ensureFinalIslandLayout(game);
    normalizePostgameWorldState(game);
    ensurePostgameWorldLayout(game);
    if (Array.isArray(game.boardData.seaTiles)) {
      game.boardData.seaTiles.forEach((tile) => {
        tile.zone = tile.zone || "mid";
        if (!SEA_EVENT_TYPE_INFO[tile.primaryTypeId]) {
          const pool = seaCardTypePoolForRoute(tile.routeId, tile.zone);
          const rand = createRng(`${game.seed}-sea-load-${tile.id}`);
          tile.primaryTypeId = pickWeighted(pool, rand);
        } else if (tile.primaryTypeId === "encounter" && !allowsSeaEncounterOnTile(tile)) {
          const pool = seaCardTypePoolForRoute(tile.routeId, tile.zone);
          const rand = createRng(`${game.seed}-sea-load-no-encounter-${tile.id}`);
          tile.primaryTypeId = pickWeighted(pool, rand);
        }
      });
    }
    normalizeTemporaryEnemyIslandServices(game);
    ensureWaterSevenIslandPosition(game);
    ensureMissionIslandsOnBoard(game);
    ensureWaterSevenIslandPosition(game);
    rebalanceIslandEnemyStatesByPosition(game);
    ensureYonkoEnemyStates(game);
    game.log = Array.isArray(game.log) ? game.log : [];
    game.availableCards = Array.isArray(game.availableCards) ? game.availableCards.map((card) => cloneCard(card)) : [];
    game.draftOrder = Array.isArray(game.draftOrder) ? game.draftOrder : [];
    game.draftSequence = Array.isArray(game.draftSequence) ? game.draftSequence : [];
    game.draftPickIndex = Math.max(0, Number(game.draftPickIndex || 0));
    game.draftPickNotice = typeof game.draftPickNotice === "string" ? game.draftPickNotice : "";
    game.pendingMoveLearnQueue = Array.isArray(game.pendingMoveLearnQueue) ? game.pendingMoveLearnQueue : [];
    game.claimedBranchRoutes = game.claimedBranchRoutes && typeof game.claimedBranchRoutes === "object" ? game.claimedBranchRoutes : {};
    game.yonkoStatus = game.yonkoStatus && typeof game.yonkoStatus === "object" ? game.yonkoStatus : {};
    game.finalGateDefeatedBy = game.finalGateDefeatedBy && typeof game.finalGateDefeatedBy === "object" ? game.finalGateDefeatedBy : {};
    const loadedYonkoIds = (game.boardData?.islands || []).filter((island) => island.kind === "yonko").map((island) => island.id);
    loadedYonkoIds.forEach((id) => {
      const islandState = game.boardData?.islandStates?.[id];
      if (islandState?.isYonkoDefeated) {
        game.yonkoStatus[id] = true;
      } else if (typeof game.yonkoStatus[id] !== "boolean") {
        game.yonkoStatus[id] = false;
      }
    });
    game.marinefordLostWhitebeardIds = Array.isArray(game.marinefordLostWhitebeardIds) ? game.marinefordLostWhitebeardIds : [];
    game.marinefordJoinedWhitebeardIds = Array.isArray(game.marinefordJoinedWhitebeardIds) ? game.marinefordJoinedWhitebeardIds : [];
    game.movementAnimating = false;
    game.diceRolling = false;
    game.resolutionLock = false;
    game.battleExitLock = false;
    game.routePrompt = null;
    game.tradePrompt = null;
    game.coopBattlePrompt = null;
    game.activeTrade = null;
    game.activeSpar = null;
    game.islandDecision = null;
    game.pendingMove = null;
    ensureJudicialRaidState();
    game.players.forEach((player, index) => {
      player.id ||= `p${index + 1}`;
      player.name ||= `玩家 ${index + 1}`;
      const lobbyPlayer = (state.lobby?.players || []).find((entry) => Number(entry?.userId) === Number(player.userId || player.id));
      player.clientId ||= String(lobbyPlayer?.clientId || player.userId || player.id || `board-player-${index + 1}`);
      player.isCPU = forceCpuPlayersFromQuery() || !!(player.isCPU || lobbyPlayer?.isCPU || lobbyPlayer?.isCpu || lobbyPlayer?.cpu || String(player.clientId || "").startsWith("board-cpu-"));
      player.isProxyCPU = lobbyPlayer?.isProxyCPU === true || player.isProxyCPU === true;
      player.proxyOwnerUserId = player.isProxyCPU ? Number(lobbyPlayer?.proxyOwnerUserId || player.proxyOwnerUserId || player.userId || 0) : 0;
      player.isMe = Number(player.userId) === Number(profile.userId);
      player.shipSkin = shipSkinForPlayer(player, index);
      player.crew = Array.isArray(player.crew) ? player.crew : [];
      ensurePlayerResearchLabState(player);
      player.recruitRolls = Array.isArray(player.recruitRolls) ? player.recruitRolls : [];
      player.items = Array.isArray(player.items) ? player.items : [];
      player.smallSupplies = Math.max(0, Number(player.smallSupplies || 0));
      player.fixedStepTokens = Math.max(0, Number(player.fixedStepTokens || 0));
      player.routeInsight = Math.max(0, Number(player.routeInsight || 0));
      player.guardCharm = Math.max(0, Number(player.guardCharm || 0));
      player.battleFood = Math.max(0, Number(player.battleFood || 0));
      normalizePendingCoopBattleResults(player);
      player.forcedReturnRoute = normalizeForcedReturnRoute(player.forcedReturnRoute);
      normalizePlayerMissionState(player);
      ensurePlayerBattleCarryState(player);
      normalizePlayerYorkDecoderState(player);
      normalizePlayerPostgameBossVoyageState(player);
      normalizePendingPostgameBossVoyage(player);
      syncEarnedCosmeticFramesFromInventory(player);
      normalizePlayerYonkoRewardState(player);
      normalizePlayerShipState(player);
      normalizeImpelDownState(player);
      normalizeMarinefordHold(player);
      player.finalGateDefeated = Boolean(player.finalGateDefeated);
      player.finalGateAftermathSeen = Boolean(player.finalGateAftermathSeen);
      player.finalGateElbaphCleared = Boolean(player.finalGateElbaphCleared);
      player.finalGateElbaphStep = String(player.finalGateElbaphStep || "");
      player.finalGateElbaphKillinghamDefeated = Boolean(player.finalGateElbaphKillinghamDefeated);
      player.finalGateElbaphSommersDefeated = Boolean(player.finalGateElbaphSommersDefeated);
      player.finalGateChopperHealed = Boolean(player.finalGateChopperHealed);
      player.finalGateBlackTurnCleared = Boolean(player.finalGateBlackTurnCleared);
      player.finalGateBlackTurnCrewId = String(player.finalGateBlackTurnCrewId || "");
      player.finalGateBlackTurnCrewName = String(player.finalGateBlackTurnCrewName || "");
      player.finalGateAttempts = Math.max(0, Number(player.finalGateAttempts || 0));
      player.finalGateRetreat = player.finalGateRetreat && typeof player.finalGateRetreat === "object" ? player.finalGateRetreat : null;
      player.finalEndingSeen = Array.isArray(player.finalEndingSeen) ? [...new Set(player.finalEndingSeen.map((id) => String(id || "").trim()).filter(Boolean))] : [];
      player.finalEndingChoice = String(player.finalEndingChoice || "");
      player.finalEndingCleared = Boolean(player.finalEndingCleared);
      normalizePlayerMainMissionState(player);
      player.discoveredIslands = Array.isArray(player.discoveredIslands) ? player.discoveredIslands : [START_ISLAND_ID];
      player.defeatedEnemies = Array.isArray(player.defeatedEnemies) ? player.defeatedEnemies : [];
      player.location ||= { kind: "island", islandId: START_ISLAND_ID };
      player.crew.forEach((card) => {
        if (card) syncCrewCardProgress(card);
      });
      player.researchLab.collection.forEach((card) => {
        if (card) syncCrewCardProgress(card);
      });
      if (player.crew.length) recalcPlayerDerivedStats(player);
      repairMissedRecruitSyncedMoveChoices(player, { silent: true });
      repairMissedLateMoveChoices(player, { silent: true });
    });
    normalizeMapMarkers(game);
    const syncedRecruitCards = syncAvailableCardsWithCatalog(game);
    if (syncedRecruitCards > 0) {
      game.log.push(`已同步 ${syncedRecruitCards} 名新酒館候選人。`);
    }
    refreshPrisonerCrewBlockedEnemyIslands(game);
    if (state.battleState?.isSparBattle && options.source !== "lan") {
      state.battleState = null;
    }
    if (state.battleState) {
      state.battleState.animating = false;
      normalizeBattleEntryTransition(state.battleState);
      if (options.source !== "lan") {
        state.battleState.visualEvent = null;
        state.battleState.lastVisualEvent = null;
      }
      state.battleState.transitionLocked = false;
    }
    return true;
  }

  async function saveManualGame(options = {}) {
    if (!state.gameState) return;
    const saveOptions = options && typeof options === "object" && typeof options.preventDefault !== "function"
      ? options
      : {};
    const silent = Boolean(saveOptions.silent);
    const successLog = saveOptions.successLog === false
      ? ""
      : (typeof saveOptions.successLog === "string" ? saveOptions.successLog : "已手動存檔。");
    const payload = createManualSavePayload({ excludeSpar: true });
    let localSaved = false;
    let serverSaved = false;
    let campaignSaved = false;
    let campaignSaveRequired = shouldWriteBoardCampaignProgress(payload);
    let campaignError = null;
    let lastError = null;
    try {
      writeLocalManualSavePayload(payload);
      localSaved = true;
    } catch (error) {
      lastError = error;
      console.warn("Local manual save failed.", error);
    }
    try {
      await writeServerManualSavePayload(payload, { updateGlobal: !silent });
      serverSaved = true;
    } catch (error) {
      lastError = error;
      console.warn("Server manual save failed.", error);
    }
    if (campaignSaveRequired) {
      try {
        const campaignResult = await writeBoardCampaignProgress(payload);
        campaignSaved = campaignResult?.ok === true;
      } catch (error) {
        campaignError = error;
        lastError = error;
        console.warn("Shared campaign save failed.", error);
      }
    }
    if (localSaved || serverSaved) {
      if (successLog) addLog(successLog);
      if (silent) return { localSaved, serverSaved, campaignSaved, payload };
      renderAll();
      const saveTarget = localSaved && serverSaved
        ? "本機瀏覽器，並同步備份到伺服器"
        : localSaved
          ? "本機瀏覽器（伺服器備份暫時失敗）"
          : "伺服器備份（本機瀏覽器暫時無法寫入）";
      openSaveLoadUi({
        title: "存檔完成",
        subtitle: campaignSaveRequired && !campaignSaved ? "個人紀錄已保存，共有航海同步失敗" : "航海進度已記錄",
        bodyHtml: `
          <div class="save-load-message ${campaignSaveRequired && !campaignSaved ? "is-warning" : ""}">
            <strong>存檔位置：${escapeModalText(saveTarget)}</strong>
            <p>目前進度已存到${escapeModalText(saveTarget)}。${campaignSaveRequired
              ? (campaignSaved
                ? "你的最新位置、船員與培養紀錄也已寫入共有航海紀錄；之後在集合等待室會載入這一版。"
                : `共有航海紀錄尚未同步：${escapeModalText(campaignError?.message || "請確認伺服器連線後再存一次")}`)
              : "手動存檔會同步更新跨房號雲端紀錄；之後從任何房號按「讀檔」都能讀回。"}</p>
          </div>
        `,
        actions: [{ id: "saveOkBtn", label: "知道了" }],
      });
      document.getElementById("saveOkBtn")?.addEventListener("click", closeModal);
      return { localSaved, serverSaved, campaignSaved, payload };
    }
    {
      console.error("Manual save failed.", lastError);
      if (silent) return false;
      openSaveLoadUi({
        title: "存檔失敗",
        subtitle: "航海紀錄未能寫入",
        bodyHtml: `
          <div class="save-load-message is-error">
            <strong>本機與伺服器皆未寫入成功</strong>
            <p>平板瀏覽器與伺服器備份都沒有寫入成功。可能是網站資料被瀏覽器封鎖，或伺服器尚未重啟。</p>
          </div>
        `,
        actions: [{ id: "saveFailOkBtn", label: "知道了" }],
      });
      document.getElementById("saveFailOkBtn")?.addEventListener("click", closeModal);
    }
  }

  function scheduleManualLoadLanSync(options = {}) {
    if (options.source === "lan" || !boardLan.enabled) return;
    boardLan.lastSentKey = "";
    scheduleBoardLanStatePush("load-save", 100, { force: true });
  }

  async function openLoadGameModal() {
    manualLoadModalActive = true;
    resumeSetupAfterManualLoadClose = String(state.gameState?.phase || "").startsWith("setup");
    const loadModalSessionId = ++manualLoadModalSessionId;
    openSaveLoadUi({
      title: "讀取存檔",
      subtitle: "正在搜尋航海紀錄",
      bodyHtml: `
        <div class="save-load-message">
          <span class="save-load-spinner" aria-hidden="true"></span>
          <strong>正在檢查本機與伺服器備份</strong>
          <p>正在檢查可讀取的存檔，請稍候。</p>
        </div>
      `,
    });
    const localPayload = readManualSavePayload();
    let serverPayload = null;
    let serverError = null;
    try {
      serverPayload = await readServerManualSavePayload();
    } catch (error) {
      serverError = error;
      console.warn("Unable to read server manual save.", error);
    }
    if (!manualLoadModalActive || loadModalSessionId !== manualLoadModalSessionId) return;
    if (!localPayload && !serverPayload) {
      openSaveLoadUi({
        title: "沒有可讀取的存檔",
        subtitle: "找不到航海紀錄",
        bodyHtml: `
          <div class="save-load-message is-warning">
            <strong>目前沒有可恢復的進度</strong>
            <p>${serverError ? "本機瀏覽器沒有存檔，伺服器備份也暫時讀不到。" : "先按右上角「存檔」保存目前進度，之後就能在這裡讀回來。"}</p>
          </div>
        `,
        actions: [{ id: "noSaveOkBtn", label: "知道了" }],
      });
      document.getElementById("noSaveOkBtn")?.addEventListener("click", closeManualLoadModal);
      return;
    }
    if (localPayload && serverPayload && !isSameManualSavePayload(localPayload, serverPayload)) {
      openSaveLoadUi({
        title: "選擇讀取進度",
        subtitle: "本機與伺服器紀錄不同",
        bodyHtml: `
          <p class="save-load-record-note">本機存檔與伺服器存檔是不同進度，請選擇要讀取哪一份。讀取只會改目前遊戲畫面，不會刪掉另一份。</p>
          <div class="save-load-record-grid is-double has-note">
            ${renderManualSaveSummaryCard(localPayload, "本機瀏覽器")}
            ${renderManualSaveSummaryCard(serverPayload, "伺服器備份")}
          </div>
        `,
        actions: [
          { id: "loadLocalSaveBtn", label: "讀本機瀏覽器" },
          { id: "loadServerSaveBtn", label: "讀伺服器備份" },
          { id: "deleteSaveBtn", label: "刪除全部存檔", tone: "danger" },
          { id: "cancelLoadSaveBtn", label: "取消", tone: "secondary" },
        ],
      });
      document.getElementById("loadLocalSaveBtn")?.addEventListener("click", () => loadManualGame(localPayload));
      document.getElementById("loadServerSaveBtn")?.addEventListener("click", () => loadManualGame(serverPayload, { rebindServerSavePlayer: true }));
      document.getElementById("deleteSaveBtn")?.addEventListener("click", confirmDeleteManualSave);
      document.getElementById("cancelLoadSaveBtn")?.addEventListener("click", closeManualLoadModal);
      return;
    }
    const payload = serverPayload || localPayload;
    const sourceLabel = localPayload && serverPayload ? "本機瀏覽器 / 伺服器備份" : serverPayload ? "伺服器備份" : "本機瀏覽器";
    openSaveLoadUi({
      title: "讀取存檔",
      subtitle: "讀取後會覆蓋目前這一局",
      bodyHtml: `
        <div class="save-load-record-grid is-single">
          ${renderManualSaveSummaryCard(payload, sourceLabel)}
        </div>
      `,
      actions: [
        { id: "confirmLoadSaveBtn", label: "讀取存檔" },
        { id: "deleteSaveBtn", label: "刪除全部存檔", tone: "danger" },
        { id: "cancelLoadSaveBtn", label: "取消", tone: "secondary" },
      ],
    });
    document.getElementById("confirmLoadSaveBtn")?.addEventListener("click", () => loadManualGame(payload, { rebindServerSavePlayer: payload === serverPayload }));
    document.getElementById("deleteSaveBtn")?.addEventListener("click", confirmDeleteManualSave);
    document.getElementById("cancelLoadSaveBtn")?.addEventListener("click", closeManualLoadModal);
  }

  function battleRefreshRecoveryBattleKey(battle = state.battleState) {
    if (!battle) return "";
    return [
      battle.isSparBattle ? "spar" : "battle",
      battle.sparId || battle.id || "",
      battle.playerId || "",
      battle.islandId || "",
      battle.islandKind || "",
      battle.postgameBossKey || "",
      battle.enemyCombatant?.key || battle.enemyCombatant?.name || "",
      Math.max(0, Number(battle.roundIndex || 0)),
    ].map((value) => String(value ?? "")).join("|");
  }

  function battleRefreshRecoveryActionSignature(battle = state.battleState) {
    if (!battle) return "";
    if (battle.isSparBattle) {
      return JSON.stringify((battle.participantOrder || []).map((id) => {
        const participant = sparBattleParticipant(battle, id);
        return [String(id), participant?.action || null];
      }));
    }
    return JSON.stringify({
      playerAction: battle.playerAction || null,
      enemyAction: battle.enemyAction || null,
      coopPlayerId: isCoopBattle(battle) ? String(battle.playerId || "") : "",
    });
  }

  function battleRefreshRecoveryHasQueuedResolution(battle = state.battleState) {
    if (!battle || battle.result || battle.roundResolved || battle.needsReplacement) return false;
    if (battle.isSparBattle) {
      const ids = Array.isArray(battle.participantOrder) ? battle.participantOrder : [];
      return ids.length >= 2 && ids.every((id) => !!sparBattleParticipant(battle, id)?.action);
    }
    return !!battle.playerAction && !!battle.enemyAction;
  }

  function readBattleRefreshRecoveryCheckpoint() {
    try {
      const raw = sessionStorage.getItem(BATTLE_REFRESH_RECOVERY_STORAGE_KEY);
      const checkpoint = raw ? JSON.parse(raw) : null;
      return checkpoint && typeof checkpoint === "object" ? checkpoint : null;
    } catch (_error) {
      return null;
    }
  }

  function clearBattleRefreshRecoveryCheckpoint(battle = null) {
    try {
      if (battle) {
        const checkpoint = readBattleRefreshRecoveryCheckpoint();
        if (checkpoint?.battleKey && checkpoint.battleKey !== battleRefreshRecoveryBattleKey(battle)) return false;
      }
      sessionStorage.removeItem(BATTLE_REFRESH_RECOVERY_STORAGE_KEY);
      return true;
    } catch (_error) {
      return false;
    }
  }

  function battleRefreshRecoveryParticipantIds(battle) {
    if (!battle || battle.isSparBattle) return [];
    const participants = isCoopBattle(battle) ? coopBattleParticipants(battle) : [battlePlayer(null, battle)];
    return [...new Set(participants.map((player) => String(player?.id || "")).filter(Boolean))];
  }

  function persistBattleRefreshRecoveryCheckpoint(battle = state.battleState) {
    if (!battleRefreshRecoveryHasQueuedResolution(battle)) return false;
    const battleKey = battleRefreshRecoveryBattleKey(battle);
    const actionSignature = battleRefreshRecoveryActionSignature(battle);
    const previous = readBattleRefreshRecoveryCheckpoint();
    if (previous?.battleKey === battleKey && previous?.actionSignature === actionSignature) return true;
    const battleSnapshot = safeJsonClone(battle);
    delete battleSnapshot.__coopQueueRuntime;
    delete battleSnapshot.__coopSingleActionHandoff;
    delete battleSnapshot.__sparRuntimePlayer;
    battleSnapshot.animating = false;
    const participantIds = battleRefreshRecoveryParticipantIds(battle);
    const playerSnapshots = (state.gameState?.players || [])
      .filter((player) => participantIds.includes(String(player?.id || "")))
      .map((player) => safeJsonClone(player));
    const checkpoint = {
      version: 1,
      createdAt: Date.now(),
      roomCode: String(state.lobby?.roomCode || boardLan.roomCode || query.get("room") || ""),
      battleKey,
      actionSignature,
      battleState: battleSnapshot,
      playerSnapshots,
      judicialRaid: battle.isJudicialRaid ? safeJsonClone(state.gameState?.judicialRaid || null) : null,
    };
    try {
      sessionStorage.setItem(BATTLE_REFRESH_RECOVERY_STORAGE_KEY, JSON.stringify(checkpoint));
      return true;
    } catch (error) {
      console.warn("[battle refresh] unable to save recovery checkpoint", error);
      return false;
    }
  }

  function restoreBattleRefreshRecoveryCheckpoint() {
    const liveBattle = state.battleState;
    const checkpoint = readBattleRefreshRecoveryCheckpoint();
    if (!checkpoint) return null;
    if (Date.now() - Number(checkpoint.createdAt || 0) > BATTLE_REFRESH_RECOVERY_TTL_MS) {
      clearBattleRefreshRecoveryCheckpoint();
      return null;
    }
    if (!battleRefreshRecoveryHasQueuedResolution(liveBattle)) {
      clearBattleRefreshRecoveryCheckpoint();
      return null;
    }
    if (
      checkpoint.battleKey !== battleRefreshRecoveryBattleKey(liveBattle)
      || checkpoint.actionSignature !== battleRefreshRecoveryActionSignature(liveBattle)
      || !checkpoint.battleState
    ) {
      clearBattleRefreshRecoveryCheckpoint();
      return null;
    }
    const playerSnapshots = Array.isArray(checkpoint.playerSnapshots) ? checkpoint.playerSnapshots : [];
    playerSnapshots.forEach((snapshot) => {
      const index = (state.gameState?.players || []).findIndex((player) => String(player?.id || "") === String(snapshot?.id || ""));
      if (index >= 0) state.gameState.players[index] = safeJsonClone(snapshot);
    });
    if (checkpoint.judicialRaid && state.gameState) {
      state.gameState.judicialRaid = safeJsonClone(checkpoint.judicialRaid);
    }
    state.battleState = safeJsonClone(checkpoint.battleState);
    delete state.battleState.__coopQueueRuntime;
    delete state.battleState.__coopSingleActionHandoff;
    delete state.battleState.__sparRuntimePlayer;
    state.battleState.animating = false;
    state.battleState.transitionLocked = false;
    state.gameState.resolutionLock = true;
    syncGamePlayerIdentitiesFromLobby();
    syncBattleReplacementActiveCrewIndex();
    return {
      restored: true,
      battleKey: checkpoint.battleKey,
      createdAt: Number(checkpoint.createdAt || 0),
    };
  }

  let battleRefreshRecoveryTimer = 0;

  function scheduleInterruptedBattleResolutionRecovery(delay = 180) {
    if (battleRefreshRecoveryTimer) window.clearTimeout(battleRefreshRecoveryTimer);
    battleRefreshRecoveryTimer = window.setTimeout(async () => {
      battleRefreshRecoveryTimer = 0;
      const battle = state.battleState;
      if (!battleRefreshRecoveryHasQueuedResolution(battle)) return;
      if (boardLan.applying) {
        scheduleInterruptedBattleResolutionRecovery(180);
        return;
      }
      if (battle.isSparBattle) {
        if (!canBoardLanControlCurrentPlayer(currentPlayer())) return;
        battle.log.push("頁面刷新後已接回本輪尚未完成的切磋結算。");
        renderBattleInterface();
        notifyBattleWindow();
        await resolveSparBattleRound(battle);
        return;
      }
      const player = battlePlayer(null, battle);
      if (!player || !canBoardLanControlBattlePlayer(player, battle)) return;
      battle.log.push("頁面刷新後已接回本輪尚未完成的戰鬥結算。");
      renderBattleInterface();
      notifyBattleWindow();
      if (isCoopBattle(battle)) await resolveCoopSingleBattleAction(player, battle);
      else await resolvePlannedBattleActions(player, battle);
    }, Math.max(0, Number(delay || 0)));
  }

  function captureLiveFlowStateForLoad(game = null, options = {}) {
    if (options?.source !== "lan" && !options?.preserveLiveFlow) return null;
    const source = game && typeof game === "object" ? game : {};
    const initialLanRestore = options?.source === "lan" && options?.initialLanRestore === true;
    return {
      // A refreshed page no longer owns the timers that created these visual locks.
      // Keep the real pending flow below, but let the new page resume it instead of
      // waiting forever for an animation callback that belonged to the old page.
      movementAnimating: initialLanRestore ? false : Boolean(source.movementAnimating),
      diceRolling: initialLanRestore ? false : Boolean(source.diceRolling),
      resolutionLock: initialLanRestore ? false : Boolean(source.resolutionLock),
      battleExitLock: initialLanRestore ? false : Boolean(source.battleExitLock),
      routePrompt: source.routePrompt ? safeJsonClone(source.routePrompt) : null,
      tradePrompt: source.tradePrompt ? safeJsonClone(source.tradePrompt) : null,
      activeTrade: source.activeTrade ? safeJsonClone(source.activeTrade) : null,
      activeSpar: source.activeSpar ? safeJsonClone(source.activeSpar) : null,
      coopBattlePrompt: source.coopBattlePrompt ? safeJsonClone(source.coopBattlePrompt) : null,
      islandDecision: source.islandDecision ? safeJsonClone(source.islandDecision) : null,
      pendingMove: source.pendingMove ? safeJsonClone(source.pendingMove) : null,
    };
  }

  function restoreLiveFlowStateAfterLoad(liveFlow = null) {
    if (!liveFlow || !state.gameState) return;
    state.gameState.movementAnimating = Boolean(liveFlow.movementAnimating);
    state.gameState.diceRolling = Boolean(liveFlow.diceRolling);
    state.gameState.resolutionLock = Boolean(liveFlow.resolutionLock);
    state.gameState.battleExitLock = Boolean(liveFlow.battleExitLock);
    state.gameState.routePrompt = liveFlow.routePrompt ? safeJsonClone(liveFlow.routePrompt) : null;
    state.gameState.tradePrompt = liveFlow.tradePrompt ? safeJsonClone(liveFlow.tradePrompt) : null;
    state.gameState.activeTrade = liveFlow.activeTrade ? safeJsonClone(liveFlow.activeTrade) : null;
    state.gameState.activeSpar = liveFlow.activeSpar ? safeJsonClone(liveFlow.activeSpar) : null;
    state.gameState.coopBattlePrompt = liveFlow.coopBattlePrompt ? safeJsonClone(liveFlow.coopBattlePrompt) : null;
    state.gameState.islandDecision = liveFlow.islandDecision ? safeJsonClone(liveFlow.islandDecision) : null;
    state.gameState.pendingMove = liveFlow.pendingMove ? safeJsonClone(liveFlow.pendingMove) : null;
  }

  function replaceLoadedPlayerIdentityRefs(root, oldPlayerIds, oldClientIds, nextUserId, nextClientId) {
    if (!root || typeof root !== "object") return;
    Object.entries(root).forEach(([key, value]) => {
      if (value && typeof value === "object") {
        replaceLoadedPlayerIdentityRefs(value, oldPlayerIds, oldClientIds, nextUserId, nextClientId);
        return;
      }
      if (/clientId$/i.test(key) && oldClientIds.has(String(value || ""))) {
        root[key] = nextClientId;
        return;
      }
      if (typeof value === "string" && oldPlayerIds.has(value)) {
        root[key] = String(nextUserId);
        return;
      }
      if (typeof value === "number" && oldPlayerIds.has(String(value))) {
        root[key] = Number(nextUserId);
      }
    });
  }

  function rebindServerSavePlayerToLocalProfile(game, options = {}) {
    if (!options.rebindServerSavePlayer || options.source === "lan" || !boardLan.enabled || !game?.players?.length) return;
    const humanPlayers = game.players.filter((player) => !isCpuPlayer(player));
    if (!humanPlayers.length || humanPlayers.some((player) => boardPlayerMatchesLocalUser(player))) return;
    const current = game.players[Number(game.currentPlayerIndex || 0)];
    const player = current && !isCpuPlayer(current) ? current : humanPlayers[0];
    const nextUserId = Number(profile.userId) || Number(player.userId || player.id) || 1;
    const nextClientId = String(profile.clientId || nextUserId || player.clientId || "").trim() || String(nextUserId);
    const oldPlayerIds = new Set([player.id, player.userId].map((value) => String(value || "").trim()).filter(Boolean));
    const oldClientIds = new Set([player.clientId].map((value) => String(value || "").trim()).filter(Boolean));
    replaceLoadedPlayerIdentityRefs(game, oldPlayerIds, oldClientIds, nextUserId, nextClientId);
    player.id = String(nextUserId);
    player.userId = nextUserId;
    player.clientId = nextClientId;
    player.isHost = true;
    player.isMe = true;
    player.isCPU = false;
    player.isCpu = false;
    player.cpu = false;
    if (state.lobby?.roomCode) {
      state.lobby.hostUserId = nextUserId;
      state.lobby.hostName = player.name || profile.name || state.lobby.hostName;
    }
  }

  function loadManualGame(payload = readManualSavePayload(), options = {}) {
    if (!payload?.gameState?.boardData) {
      if (options.silent) return false;
      openLoadGameModal();
      return;
    }
    const preserveOpeningStory = options.source === "lan"
      && openingStoryActive
      && String(payload.gameState.seed || "") === String(openingStorySeed || "")
      && payload.gameState.phase === "setup-order";
    const liveFlow = captureLiveFlowStateForLoad(payload.gameState, options);
    state.gameState = safeJsonClone(payload.gameState);
    if (payload.campaignContext?.campaignId) {
      state.campaignContext = safeJsonClone(payload.campaignContext);
    } else if (state.lobby?.campaignId) {
      state.campaignContext = {
        campaignId: String(state.lobby.campaignId || ""),
        mode: String(state.lobby.campaignMode || ""),
      };
    }
    rebindServerSavePlayerToLocalProfile(state.gameState, options);
    state.battleState = payload.battleState ? safeJsonClone(payload.battleState) : null;
    state.boardUiEvent = null;
    if (!normalizeLoadedGameState(options)) {
      if (options.silent) return false;
      openSaveLoadUi({
        title: "讀檔失敗",
        subtitle: "航海紀錄無法恢復",
        bodyHtml: `
          <div class="save-load-message is-error">
            <strong>存檔資料不完整</strong>
            <p>這份存檔資料不完整，無法安全恢復。</p>
          </div>
        `,
        actions: [{ id: "loadFailOkBtn", label: "知道了" }],
      });
      document.getElementById("loadFailOkBtn")?.addEventListener("click", closeManualLoadModal);
      return;
    }
    restoreLiveFlowStateAfterLoad(liveFlow);
    syncBattleReplacementActiveCrewIndex();
    syncGamePlayerIdentitiesFromLobby();
    const shouldRecoverInterruptedBattle = options.source !== "lan" || options.initialLanRestore === true;
    const battleRefreshRecovery = state.battleState && shouldRecoverInterruptedBattle
      ? restoreBattleRefreshRecoveryCheckpoint()
      : null;
    if (!preserveOpeningStory) {
      cancelOpeningStorySession();
      clearManualLoadModalSession();
      closeModal();
    }
    state.autoCenterEnabled = true;
    if (!state.battleState) closeBattlePageOverlay();
    if (!options.silent) {
      state.gameState.log.push(`已讀取 ${formatSaveTime(payload.savedAt)} 的存檔。`);
    }
    renderAll();
    autoCenterOnCurrentPlayer();
    scheduleActiveTradeModalForLocalPlayer();
    scheduleActiveSparUiForLocalPlayer();
    scheduleCoopBattlePromptModalForLocalPlayer();
    schedulePendingPostgameBossVoyageForCurrentPlayer();
    scheduleTurnStartIslandServiceChoiceForCurrentPlayer();
    scheduleManualLoadLanSync(options);
    if (state.battleState) {
      if (!activeSyncedBattleEntryTransition(state.battleState)) {
        state.gameState.skipNextBattleMapShake = true;
      }
      state.gameState.resolutionLock = true;
      renderBattleInterface();
      if (battleRefreshRecovery || (shouldRecoverInterruptedBattle && battleRefreshRecoveryHasQueuedResolution(state.battleState))) {
        scheduleInterruptedBattleResolutionRecovery();
      }
      return true;
    }
    if (String(state.gameState.phase || "").startsWith("setup")) {
      if (!preserveOpeningStory) {
        openSetupStep({
          skipOpeningStory: options.source !== "lan" || options.lanReason === "load-save",
        });
      }
      return true;
    }
    scheduleAutoResumeBattleForCurrentPlayer();
    scheduleAutoResumePendingMoveForCurrentPlayer();
    schedulePendingMoveLearn(600);
    return true;
  }

  async function loadServerManualGame(roomCode = manualSaveRoomCode()) {
    const normalizedRoomCode = sanitizeRoomCode(roomCode) || manualSaveRoomCode();
    const response = await fetch(`/api/board-save/${encodeURIComponent(normalizedRoomCode)}`, {
      method: "GET",
      cache: "no-store",
    });
    if (!response.ok) throw new Error(`server save read failed: ${response.status}`);
    const data = await response.json();
    const payload = data?.payload;
    if (!isValidManualSavePayload(payload)) throw new Error("invalid server save payload");
    loadManualGame(payload, { rebindServerSavePlayer: true });
    return summarizeManualSave(payload);
  }

  function boardLanProfilePayload() {
    return {
      userId: profile.userId,
      clientId: profile.clientId,
      name: profile.name,
      avatar: profile.avatar,
      title: profile.title,
      secret: profile.secret || "",
    };
  }

  function boardLanContentKey(payload) {
    if (!payload?.gameState) return "";
    try {
      return JSON.stringify({
        gameState: payload.gameState,
        battleState: payload.battleState || null,
        boardUiEvent: payload.boardUiEvent || null,
      });
    } catch {
      return `${payload.savedAt || ""}:${Date.now()}`;
    }
  }

  function canPushBoardLanState(reason = "state") {
    if (!boardLan.enabled) return true;
    if (!state.gameState) return false;
    const normalizedReason = String(reason || "state");
    if (normalizedReason.startsWith("settings-")) return localPlayerIsLobbyHost();
    if (normalizedReason.startsWith("trade-")) {
      const trade = normalizeActiveTrade(state.gameState.activeTrade);
      if (trade) {
        return activeTradePlayers(trade).some((player) => canBoardLanControlPlayerIdentity(player));
      }
      const prompt = state.gameState.tradePrompt;
      if (prompt) {
        const allowedIds = new Set([prompt.playerId, ...(prompt.partnerIds || [])].map((id) => String(id)));
        return (state.gameState.players || []).some((player) => allowedIds.has(String(player.id)) && canBoardLanControlPlayerIdentity(player));
      }
    }
    if (normalizedReason.startsWith("spar-")) {
      const spar = state.gameState.activeSpar;
      const participantIds = Array.isArray(spar?.participantIds) ? spar.participantIds.map(String) : [];
      if (state.battleState?.isSparBattle) {
        (state.battleState.participantOrder || []).forEach((id) => participantIds.push(String(id)));
      }
      const allowedIds = new Set(participantIds);
      if (!allowedIds.size) return canBoardLanControlCurrentPlayer(currentPlayer());
      return (state.gameState.players || []).some((player) => allowedIds.has(String(player.id)) && canBoardLanControlPlayerIdentity(player));
    }
    if ((normalizedReason === "battle" || normalizedReason.startsWith("battle-")) && state.battleState) {
      if (state.battleState.isSparBattle) {
        const allowedIds = new Set((state.battleState.participantOrder || []).map(String));
        return (state.gameState.players || []).some((player) => allowedIds.has(String(player.id)) && canBoardLanControlPlayerIdentity(player));
      }
      const owner = battlePlayer(null, state.battleState);
      return canBoardLanControlPlayerIdentity(owner);
    }
    return canBoardLanControlCurrentPlayer(currentPlayer());
  }

  function pushBoardLanStateUnchecked(reason = "state") {
    if (!boardLan.enabled || !boardLan.connected || boardLan.applying || !state.gameState) return;
    if (boardLan.awaitingInitialState) return;
    const payload = createManualSavePayload();
    if (!isValidManualSavePayload(payload)) return;
    const key = boardLanContentKey(payload);
    if (key && key === boardLan.lastSentKey) return;
    boardLan.lastSentKey = key;
    const outboundVersion = Math.max(0, Number(boardLan.version || 0)) + 1;
    boardLan.socket.emit("BOARD_GAME_STATE", {
      roomCode: boardLan.roomCode || state.lobby?.roomCode || "",
      payload,
      version: outboundVersion,
      sourceClientId: boardLan.clientId,
      reason,
    }, (result = {}) => {
      boardLan.lastAck = result;
      boardLan.lastError = result.ok ? "" : String(result.error || "sync_failed");
      if (!result.ok) {
        boardLan.lastSentKey = "";
      }
      if (result.ok && Number(result.version) > boardLan.version) {
        boardLan.version = Number(result.version);
      }
    });
  }

  function pushBoardLanState(reason = "state") {
    if (!canPushBoardLanState(reason)) return;
    pushBoardLanStateUnchecked(reason);
  }

  function scheduleBoardLanStatePush(reason = "state", delay = 160, options = {}) {
    if (!boardLan.enabled || boardLan.applying || !state.gameState) return;
    if (boardLan.awaitingInitialState) return;
    if (!options.force && !canPushBoardLanState(reason)) return;
    clearTimeout(boardLan.pushTimer);
    boardLan.pushTimer = setTimeout(() => {
      boardLan.pushTimer = 0;
      if (options.force) pushBoardLanStateUnchecked(reason);
      else pushBoardLanState(reason);
    }, delay);
  }

  function clearBoardLanInitialStateRetry() {
    window.clearTimeout(boardLan.initialStateRetryTimer);
    boardLan.initialStateRetryTimer = 0;
  }

  function resetBoardLanInitialRestoreTracking() {
    clearBoardLanInitialStateRetry();
    boardLan.initialStateRequestAttempts = 0;
    boardLan.initialStateWaitStartedAt = 0;
  }

  function showBoardLanInitialStateWait(options = {}) {
    if (!boardLan.awaitingInitialState) return;
    const waitStartedAt = Math.max(0, Number(boardLan.initialStateWaitStartedAt || 0));
    const force = options.force === true || campaignInitialLoadRequested;
    if (!force && (!waitStartedAt || Date.now() - waitStartedAt < 2400)) return;
    if (refs.modal?.classList.contains("board-lan-initial-wait-modal")) return;
    const title = campaignInitialLoadRequested ? "正在讀取個人航海紀錄" : "正在連接航海房";
    const description = campaignInitialLoadRequested
      ? "正在載入你在這份共有航海紀錄中的最新個人進度，完成後會直接回到地圖。"
      : "正在向房主取得同一局遊戲資料，完成後會自動進入，不需要重新整理。";
    openModal(`
      <div style="display:grid;gap:14px;place-items:center;text-align:center;padding:clamp(24px,5vw,56px);">
        <div style="font-size:clamp(26px,3vw,44px);font-weight:900;color:#f6d58a;">${title}</div>
        <p style="max-width:680px;margin:0;color:#d9e8ef;font-size:clamp(16px,1.7vw,23px);line-height:1.65;">
          ${description}
        </p>
      </div>
    `, "board-lan-initial-wait-modal force-choice no-backdrop-close");
  }

  function showBoardCampaignInitialLoadFailure(error = "") {
    boardLan.awaitingInitialState = false;
    boardLan.initialStateCanSeed = false;
    boardLan.lastError = String(error || "campaign_load_failed");
    resetBoardLanInitialRestoreTracking();
    openModal(`
      <div style="display:grid;gap:16px;place-items:center;text-align:center;padding:clamp(24px,5vw,56px);">
        <div style="font-size:clamp(25px,3vw,42px);font-weight:900;color:#f6d58a;">個人航海紀錄載入失敗</div>
        <p style="max-width:680px;margin:0;color:#d9e8ef;font-size:clamp(16px,1.7vw,22px);line-height:1.65;">
          為了保護你原本的進度，本頁不會建立新的航海紀錄。請回到開始頁重新選擇。
        </p>
        <a href="board_start.html" style="display:inline-flex;align-items:center;justify-content:center;min-width:210px;padding:12px 22px;border:1px solid #f6d58a;border-radius:12px;background:linear-gradient(180deg,#c89435,#7d4a16);color:#fff;text-decoration:none;font-weight:900;box-shadow:0 10px 24px rgba(0,0,0,.28);">
          返回開始頁
        </a>
      </div>
    `, "board-lan-initial-wait-modal force-choice no-backdrop-close");
  }

  function seedBoardLanInitialState(reason = "join") {
    if (campaignInitialLoadRequested) return false;
    if (!boardLan.awaitingInitialState || !boardLan.connected || !boardLan.initialStateCanSeed || !localPlayerIsLobbyHost()) return false;
    boardLan.awaitingInitialState = false;
    boardLan.initialStateCanSeed = false;
    resetBoardLanInitialRestoreTracking();
    if (refs.modal?.classList.contains("board-lan-initial-wait-modal")) closeModal();
    openSetupStep();
    window.setTimeout(() => pushBoardLanStateUnchecked(reason), 120);
    return true;
  }

  function scheduleBoardLanInitialStateRetry(delay = 700) {
    clearBoardLanInitialStateRetry();
    if (!boardLan.awaitingInitialState) return;
    if (Number(boardLan.initialStateRequestAttempts || 0) >= 4) {
      if (campaignInitialLoadRequested) showBoardCampaignInitialLoadFailure("campaign_state_timeout");
      return;
    }
    boardLan.initialStateRetryTimer = window.setTimeout(() => {
      boardLan.initialStateRetryTimer = 0;
      if (!boardLan.awaitingInitialState) return;
      if (seedBoardLanInitialState("join")) return;
      if (Number(boardLan.initialStateRequestAttempts || 0) >= 4) return;
      boardLan.initialStateRequestAttempts = Number(boardLan.initialStateRequestAttempts || 0) + 1;
      showBoardLanInitialStateWait();
      if (boardLan.connected && boardLan.socket) {
        boardLan.socket.emit("BOARD_STATE_REQUEST", {
          roomCode: boardLan.roomCode || state.lobby?.roomCode || "",
          requesterClientId: boardLan.clientId,
        });
      }
      if (boardLan.initialStateRequestAttempts < 4) {
        scheduleBoardLanInitialStateRetry(Math.min(4800, 600 * (2 ** boardLan.initialStateRequestAttempts)));
      } else if (campaignInitialLoadRequested) {
        boardLan.initialStateRetryTimer = window.setTimeout(() => {
          boardLan.initialStateRetryTimer = 0;
          if (boardLan.awaitingInitialState) showBoardCampaignInitialLoadFailure("campaign_state_timeout");
        }, 1800);
      }
    }, Math.max(120, Number(delay) || 700));
  }

  function isBoardLanTradeTerminalPayload(message = {}) {
    const reason = String(message.reason || "");
    if (reason !== "trade-complete" && reason !== "trade-close") return false;
    const localGame = state.gameState;
    const incomingGame = message.payload?.gameState;
    if (!localGame || !incomingGame) return false;
    const localTrade = normalizeActiveTrade(localGame.activeTrade);
    const localPrompt = localGame.tradePrompt;
    if (!localTrade && !localPrompt) return false;
    if (incomingGame.activeTrade || incomingGame.tradePrompt) return false;
    if (Number(localGame.currentPlayerIndex || 0) !== Number(incomingGame.currentPlayerIndex || 0)) return false;
    if (String(localGame.phase || "") !== String(incomingGame.phase || "")) return false;
    if (localTrade) {
      const playerIds = activeTradePlayers(localTrade).map((player) => String(player.id));
      const incomingIds = new Set((incomingGame.players || []).map((player) => String(player.id)));
      return playerIds.length >= 2 && playerIds.every((id) => incomingIds.has(id));
    }
    if (localPrompt) {
      return String(localPrompt.playerId || "") === String(incomingGame.pendingMove?.playerId || localPrompt.playerId || "");
    }
    return false;
  }

  function resumeTradeTerminalFlowFromLan(reason = "") {
    if (reason !== "trade-complete" && reason !== "trade-close") return;
    if (!state.gameState) return;
    closeModal();
    renderAll();
    const pending = state.gameState.pendingMove;
    if (!pending || state.gameState.tradePrompt || state.gameState.activeTrade || state.gameState.resolutionLock) return;
    const pendingPlayer = tradePlayerById(pending.playerId);
    if (!pendingPlayer || !canBoardLanControlCurrentPlayer(pendingPlayer)) return;
    window.setTimeout(() => {
      if (!state.gameState?.pendingMove || state.gameState.tradePrompt || state.gameState.activeTrade || state.gameState.resolutionLock) return;
      const latestPendingPlayer = tradePlayerById(state.gameState.pendingMove.playerId);
      if (!latestPendingPlayer || !canBoardLanControlCurrentPlayer(latestPendingPlayer)) return;
      continueMove();
    }, 140);
  }

  function shouldPreApplyBoardUiEvent(event = {}) {
    return !!event?.id && event.type === "turn-banner" && !handledBoardUiEventIds.has(event.id);
  }

  function applyBoardLanPayload(message = {}) {
    if (!boardLan.enabled || !message.payload) return;
    if (message.sourceClientId === boardLan.clientId && !boardLan.awaitingInitialState) return;
    const version = Number(message.version || 0);
    const allowTradeTerminal = isBoardLanTradeTerminalPayload(message);
    const reason = String(message.reason || "");
    const initialRestorePending = boardLan.awaitingInitialState;
    const incomingHasBattle = !!message.payload?.battleState;
    const localBattleKey = state.battleState ? boardLanContentKey({ gameState: state.gameState, battleState: state.battleState }) : "";
    const incomingBattleKey = incomingHasBattle ? boardLanContentKey(message.payload) : "";
    const allowBattleCatchup = incomingHasBattle && reason.startsWith("battle-") && (!state.battleState || incomingBattleKey !== localBattleKey);
    if (version && version < boardLan.version && !allowTradeTerminal && !allowBattleCatchup) return;
    // turn-banner 會先播放交棒演出，再用同一份版本延後套用；這次內部續跑不能被重複版本保護擋掉。
    if (version && version === boardLan.version && !message.__skipPreApplyUiEvent && !boardLan.awaitingInitialState && !allowTradeTerminal && !allowBattleCatchup) return;
    const preApplyEvent = message.payload?.boardUiEvent || null;
    if (!initialRestorePending && !message.__skipPreApplyUiEvent && shouldPreApplyBoardUiEvent(preApplyEvent)) {
      boardLan.version = Math.max(boardLan.version, version);
      const delay = Math.max(0, Number(handleBoardUiEvent(preApplyEvent) || preApplyEvent.transitionDelay || TURN_HANDOFF_TRANSITION_DELAY_MS));
      window.clearTimeout(boardLan.deferredApplyTimer);
      boardLan.deferredApplyTimer = window.setTimeout(() => {
        boardLan.deferredApplyTimer = 0;
        applyBoardLanPayload({ ...message, __skipPreApplyUiEvent: true });
      }, delay);
      return;
    }
    boardLan.version = Math.max(boardLan.version, version);
    boardLan.applying = true;
    let applied = false;
    const wasAwaitingInitialState = boardLan.awaitingInitialState;
    if (wasAwaitingInitialState) boardLan.awaitingInitialState = false;
    try {
      applied = loadManualGame(message.payload, {
        silent: true,
        source: "lan",
        lanReason: reason,
        initialLanRestore: wasAwaitingInitialState,
      });
      if (applied) {
        boardLan.awaitingInitialState = false;
        boardLan.initialStateCanSeed = false;
        resetBoardLanInitialRestoreTracking();
        boardLan.lastSentKey = boardLanContentKey(message.payload);
        boardLan.lastError = "";
        const incomingUiEvent = message.payload.boardUiEvent || null;
        if (wasAwaitingInitialState && incomingUiEvent?.type === "turn-banner") {
          if (incomingUiEvent.id) handledBoardUiEventIds.add(incomingUiEvent.id);
        } else {
          handleBoardUiEvent(incomingUiEvent);
        }
        restorePinnedSpectatorModalIfNeeded(incomingUiEvent);
      }
    } finally {
      if (!applied && wasAwaitingInitialState) {
        boardLan.awaitingInitialState = true;
        showBoardLanInitialStateWait();
        scheduleBoardLanInitialStateRetry(420);
      }
      setTimeout(() => {
        boardLan.applying = false;
        if (applied && wasAwaitingInitialState && shouldRunCpuAutoStep()) {
          scheduleCpuAutoStep(180);
        }
        if (applied && message.reason === "trade-confirm") {
          executeConfirmedActiveTradeIfCurrentTurnOwner({ silent: true, fromLan: true });
        }
        if (applied && (message.reason === "trade-complete" || message.reason === "trade-close")) {
          resumeTradeTerminalFlowFromLan(message.reason);
        }
      }, 80);
    }
  }

  function setupBoardLanSocket() {
    if (!boardLan.enabled || !window.io || boardLan.socket) return false;
    boardLan.socket = window.io({ transports: ["websocket", "polling"] });
    boardLan.socket.on("connect", () => {
      boardLan.connected = true;
      boardLan.awaitingInitialState = true;
      boardLan.initialStateCanSeed = false;
      boardLan.initialStateRequestAttempts = 0;
      boardLan.initialStateWaitStartedAt = Date.now();
      if (campaignInitialLoadRequested) showBoardLanInitialStateWait({ force: true });
      boardLan.socket.emit("BOARD_JOIN_GAME", {
        roomCode: boardLan.roomCode || state.lobby?.roomCode || "",
        profile: boardLanProfilePayload(),
      }, (result = {}) => {
        if (!result.ok) {
          boardLan.awaitingInitialState = false;
          boardLan.initialStateCanSeed = false;
          resetBoardLanInitialRestoreTracking();
          console.warn("[board LAN] join failed", result);
          if (campaignInitialLoadRequested) showBoardCampaignInitialLoadFailure(result.error || "campaign_join_failed");
          else openSetupStep();
          return;
        }
        const hasRemoteState = Boolean(result.hasState);
        boardLan.initialStateCanSeed = !hasRemoteState && result.canSeedState === true;
        if (hasRemoteState) {
          boardLan.version = Math.max(boardLan.version, Number(result.version || 0));
        }
        if (result.lobby?.roomCode) {
          state.lobby = result.lobby;
          if (result.lobby.campaignId) {
            state.campaignContext = {
              ...(state.campaignContext || {}),
              campaignId: String(result.lobby.campaignId),
              mode: String(result.lobby.campaignMode || state.campaignContext?.mode || ""),
            };
          }
          shared.saveLobby(state.lobby);
          const changedPlayers = syncSetupPlayersFromLobby();
          const changedIdentities = syncGamePlayerIdentitiesFromLobby();
          if (!campaignInitialLoadRequested || !boardLan.awaitingInitialState) {
            renderHeader();
            if (changedPlayers || changedIdentities) renderAll();
          }
        }
        if (!boardLan.awaitingInitialState) return;
        if (!hasRemoteState && result.canSeedState === true && seedBoardLanInitialState("join")) return;
        showBoardLanInitialStateWait();
        scheduleBoardLanInitialStateRetry(hasRemoteState ? 360 : 520);
      });
    });
    boardLan.socket.on("disconnect", () => {
      boardLan.connected = false;
      boardLan.initialStateCanSeed = false;
      resetBoardLanInitialRestoreTracking();
    });
    boardLan.socket.on("BOARD_LOBBY", (message = {}) => {
      if (!message.lobby?.roomCode) return;
      state.lobby = message.lobby;
      if (message.lobby.campaignId) {
        state.campaignContext = {
          ...(state.campaignContext || {}),
          campaignId: String(message.lobby.campaignId),
          mode: String(message.lobby.campaignMode || state.campaignContext?.mode || ""),
        };
      }
      shared.saveLobby(state.lobby);
      const changedPlayers = syncSetupPlayersFromLobby();
      const changedIdentities = syncGamePlayerIdentitiesFromLobby();
      if (!campaignInitialLoadRequested || !boardLan.awaitingInitialState) {
        renderHeader();
        if (changedPlayers || changedIdentities) {
          renderAll();
          scheduleBoardLanStatePush("lobby-players", 180);
        }
      }
      if (boardLan.awaitingInitialState && !seedBoardLanInitialState("join")) {
        showBoardLanInitialStateWait();
        scheduleBoardLanInitialStateRetry(320);
      }
    });
    boardLan.socket.on("BOARD_GAME_STATE", applyBoardLanPayload);
    boardLan.socket.on("BOARD_STATE_REQUEST", () => {
      if (boardLan.awaitingInitialState) {
        if (!seedBoardLanInitialState("join")) scheduleBoardLanInitialStateRetry(220);
        return;
      }
      setTimeout(() => pushBoardLanState("request"), 120);
    });
    return true;
  }

  function confirmDeleteManualSave() {
    openSaveLoadUi({
      title: "確認刪除存檔",
      subtitle: "此操作無法復原",
      bodyHtml: `
        <div class="save-load-message is-error">
          <strong>本機與伺服器紀錄都會被清除</strong>
          <p>將刪除目前瀏覽器的手動存檔，以及伺服器上的跨房號備份。刪除後無法復原，確定要繼續嗎？</p>
        </div>
      `,
      actions: [
        { id: "confirmDeleteSaveBtn", label: "確認刪除", tone: "danger" },
        { id: "cancelDeleteSaveBtn", label: "取消", tone: "secondary" },
      ],
    });
    document.getElementById("confirmDeleteSaveBtn")?.addEventListener("click", deleteManualSave);
    document.getElementById("cancelDeleteSaveBtn")?.addEventListener("click", closeManualLoadModal);
  }

  async function deleteManualSave() {
    manualSaveStorageKeys().forEach((key) => localStorage.removeItem(key));
    let serverDeleted = false;
    try {
      await deleteServerManualSavePayload();
      serverDeleted = true;
    } catch (error) {
      console.warn("Unable to delete server manual save.", error);
    }
    openSaveLoadUi({
      title: "存檔已刪除",
      subtitle: serverDeleted ? "本機與伺服器紀錄已清除" : "伺服器備份未能同步清除",
      bodyHtml: `
        <div class="save-load-message ${serverDeleted ? "" : "is-warning"}">
          <strong>${serverDeleted ? "航海紀錄已清除" : "本機紀錄已清除"}</strong>
          <p>目前瀏覽器裡的手動存檔已清除。${serverDeleted ? "伺服器備份也已同步清除。" : "伺服器備份暫時無法清除。"}</p>
        </div>
      `,
      actions: [{ id: "deleteSaveOkBtn", label: "知道了" }],
    });
    document.getElementById("deleteSaveOkBtn")?.addEventListener("click", closeManualLoadModal);
  }

  function createFreshGameSeed() {
    const randomBuffer = new Uint32Array(2);
    if (window.crypto?.getRandomValues) {
      window.crypto.getRandomValues(randomBuffer);
    } else {
      randomBuffer[0] = Math.floor(Math.random() * 0xffffffff);
      randomBuffer[1] = Math.floor(Math.random() * 0xffffffff);
    }
    return `${state.lobby.roomCode || "local"}-${Date.now()}-${randomBuffer[0].toString(36)}-${randomBuffer[1].toString(36)}`;
  }

  function boardCpuSlotNumber(player, fallbackOrdinal = 1) {
    const userId = Number(player?.userId ?? player?.id);
    if (Number.isInteger(userId) && userId <= -1001) return Math.max(1, Math.abs(userId + 1000));
    const clientMatch = String(player?.clientId || "").match(/-(\d+)$/);
    if (clientMatch) return Math.max(1, Number(clientMatch[1]) || 1);
    return Math.max(1, Number(fallbackOrdinal) || 1);
  }

  function boardCpuDisplayName(player, fallbackOrdinal = 1) {
    if (player?.isProxyCPU) return String(player.name || "代理 CPU");
    return `CPU${boardCpuSlotNumber(player, fallbackOrdinal)}`;
  }

  function createGamePlayersFromLobby(seedValue = Date.now()) {
    const lobbyPlayers = (state.lobby.players || []).slice(0, 4);
    const normalizedPlayers = lobbyPlayers.length
      ? lobbyPlayers
      : buildFallbackLobbyPlayers();
    const shipPool = shuffleArray(SHIP_SKINS, createRng(`${seedValue}-ships`));
    const forceCpuPlayers = forceCpuPlayersFromQuery();
    let cpuOrdinal = 0;
    return normalizedPlayers.map((player, index) => {
      const isCPU = forceCpuPlayers || !!(player.isCPU || player.isCpu || player.cpu || String(player.clientId || "").startsWith("board-cpu-"));
      if (isCPU) cpuOrdinal += 1;
      return ({
      id: String(player.userId),
      userId: Number(player.userId),
      clientId: String(player.clientId || player.userId || `board-player-${index + 1}`),
      name: isCPU ? boardCpuDisplayName(player, cpuOrdinal) : player.name,
      avatar: player.avatar,
      title: player.title,
      shipSkin: shipPool[index % shipPool.length],
      isHost: !!player.isHost,
      isMe: Number(player.userId) === Number(profile.userId),
      isCPU,
      isProxyCPU: player.isProxyCPU === true,
      proxyOwnerUserId: Number(player.proxyOwnerUserId || 0),
      hp: 120,
      maxHp: 120,
      coins: 3000,
      bounty: 0,
      power: 0,
      crew: [],
      researchLab: {
        schemaVersion: RESEARCH_LAB_SCHEMA_VERSION,
        nextInstanceSequence: 1,
        nextFactorSequence: 1,
        researchPoints: 0,
        researchLevel: 1,
        starterExtractorGranted: false,
        codexFactorCardIds: [],
        codexCultivatedCardIds: [],
        collection: [],
        completeFactors: [],
      },
      activeCrewIndex: 0,
      items: [],
      inventory: { items: {}, equipped: {} },
      yorkDecoderTier: 0,
      unlockedPostgameBossClueItemIds: [],
      pendingPostgameBossVoyage: null,
      ownedCosmeticFrameIds: [],
      activeCosmeticFrameId: "",
      activeMission: null,
      activeMissions: [],
      mainMission: null,
      missionBoardChoices: null,
      completedMissionIds: [],
      impelDown: { active: false },
      marinefordHold: { active: false },
      activeMapBuffs: [],
      nextDiceModifier: 0,
      recruitBonus: 0,
      routeInsight: 0,
      guardCharm: 0,
      battleFood: 0,
      smallSupplies: 0,
      skipNextTurn: false,
      roadPoneglyphs: [],
      defeatedYonkoGlyphs: [],
      yonkoCounterRewards: [],
      finalGateDefeated: false,
      finalGateAftermathSeen: false,
      finalGateElbaphCleared: false,
      finalGateElbaphStep: "",
      finalGateElbaphKillinghamDefeated: false,
      finalGateElbaphSommersDefeated: false,
      finalGateChopperHealed: false,
      finalGateBlackTurnCleared: false,
      finalGateBlackTurnCrewId: "",
      finalGateBlackTurnCrewName: "",
      finalGateAttempts: 0,
      finalGateRetreat: null,
      finalEndingSeen: [],
      finalEndingChoice: "",
      finalEndingCleared: false,
      defeatedEnemies: [],
        fixedStepTokens: 0,
        smallPointer: 0,
        rerollTickets: 0,
        presetStep: null,
      pendingBattle: null,
      pendingCoopBattleResults: [],
      claimedBranchId: null,
      recruitRolls: [],
      routeChoice: null,
      forcedReturnRoute: null,
      discoveredIslands: [START_ISLAND_ID],
      location: { kind: "island", islandId: START_ISLAND_ID, entryDirection: null },
      });
    });
  }

  function syncSetupPlayersFromLobby() {
    const game = state.gameState;
    const lobbyPlayers = Array.isArray(state.lobby?.players) ? state.lobby.players.slice(0, 4) : [];
    if (!game || game.phase !== "setup-order" || lobbyPlayers.length <= 0) return false;
    const currentIds = (game.players || []).map((player) => String(player.userId || player.id)).join("|");
    const lobbyIds = lobbyPlayers.map((player) => String(player.userId)).join("|");
    if (currentIds === lobbyIds) return false;
    game.players = createGamePlayersFromLobby(game.seed);
    game.currentPlayerIndex = Math.min(game.currentPlayerIndex || 0, Math.max(0, game.players.length - 1));
    game.draftOrder = [];
    game.draftSequence = [];
    game.draftPickIndex = 0;
    game.draftPickNotice = "";
    game.players.forEach((player) => {
      player.recruitRolls = [];
    });
    addLog("連線房間玩家名單已同步，開局排序已重置。");
    return true;
  }

  function syncGamePlayerIdentitiesFromLobby() {
    const game = state.gameState;
    const lobbyPlayers = Array.isArray(state.lobby?.players) ? state.lobby.players.slice(0, 4) : [];
    if (!game?.players?.length || !lobbyPlayers.length) return false;
    let changed = false;
    let cpuOrdinal = 0;
    game.players.forEach((player) => {
      const lobbyPlayer = lobbyPlayers.find((entry) => Number(entry?.userId) === Number(player.userId || player.id));
      if (lobbyPlayer?.clientId && String(player.clientId || "") !== String(lobbyPlayer.clientId)) {
        player.clientId = String(lobbyPlayer.clientId);
        changed = true;
      }
      const isMe = boardPlayerMatchesLocalUser(player);
      if (player.isMe !== isMe) {
        player.isMe = isMe;
        changed = true;
      }
      const isCPU = forceCpuPlayersFromQuery() || !!(lobbyPlayer?.isCPU || lobbyPlayer?.isCpu || lobbyPlayer?.cpu || String(lobbyPlayer?.clientId || player.clientId || "").startsWith("board-cpu-"));
      const isProxyCPU = lobbyPlayer?.isProxyCPU === true;
      if (isCPU) cpuOrdinal += 1;
      if (player.isCPU !== isCPU) {
        player.isCPU = isCPU;
        changed = true;
      }
      if (player.isProxyCPU !== isProxyCPU) {
        player.isProxyCPU = isProxyCPU;
        changed = true;
      }
      const proxyOwnerUserId = isProxyCPU ? Number(lobbyPlayer?.proxyOwnerUserId || player.userId || 0) : 0;
      if (Number(player.proxyOwnerUserId || 0) !== proxyOwnerUserId) {
        player.proxyOwnerUserId = proxyOwnerUserId;
        changed = true;
      }
      if (isCPU) {
        const cpuName = boardCpuDisplayName(lobbyPlayer || player, cpuOrdinal);
        if (player.name !== cpuName) {
          player.name = cpuName;
          changed = true;
        }
      }
    });
    return changed;
  }

  function buildIslandDistanceMap(routes, originId = START_ISLAND_ID) {
    const adjacency = {};
    routes.forEach((routeItem) => {
      if (routeItem.meta?.requiresFinalUnlocked) return;
      adjacency[routeItem.from] ||= [];
      adjacency[routeItem.to] ||= [];
      adjacency[routeItem.from].push(routeItem.to);
      adjacency[routeItem.to].push(routeItem.from);
    });
    const startId = originId || START_ISLAND_ID;
    const distanceMap = new Map([[startId, 0]]);
    const queue = [startId];
    while (queue.length) {
      const islandId = queue.shift();
      const nextDistance = (distanceMap.get(islandId) || 0) + 1;
      (adjacency[islandId] || []).forEach((nextIslandId) => {
        if (distanceMap.has(nextIslandId)) return;
        distanceMap.set(nextIslandId, nextDistance);
        queue.push(nextIslandId);
      });
    }
    return distanceMap;
  }

  function buildIslandDistanceMapFromStart(routes) {
    return buildIslandDistanceMap(routes, START_ISLAND_ID);
  }

  function buildIslandDistanceMapFromReverseMountain(routes) {
    return buildIslandDistanceMap(routes, INVERSION_MOUNTAIN_ID);
  }

  function playerIslandDistanceSeeds(player) {
    const location = player?.location || {};
    if (location.kind === "island" && location.islandId) {
      return [{ islandId: location.islandId, offset: 0 }];
    }
    if (location.kind === "route" && location.routeId) {
      const routeItem = getRouteById(location.routeId);
      if (routeItem) {
        const tileCount = Math.max(1, routeItem.tiles?.length || 1);
        const tileIndex = Math.max(0, Math.min(tileCount - 1, Math.round(Number(location.tileIndex || 0))));
        return [
          { islandId: routeItem.from, offset: tileIndex + 1 },
          { islandId: routeItem.to, offset: tileCount - tileIndex },
        ];
      }
    }
    return [{ islandId: START_ISLAND_ID, offset: 0 }];
  }

  function findNearestHospitalIsland(player) {
    const boardData = state.gameState?.boardData || {};
    const islands = boardData.islands || [];
    const routes = boardData.routesBetweenIslands || MAP_TEMPLATE.routesBetweenIslands;
    const hospitals = islands.filter((island) => isMedicalServiceIslandKind(getEffectiveIslandKind(island, getIslandState(island.id))));
    if (!hospitals.length) return null;
    const seeds = playerIslandDistanceSeeds(player);
    const scored = hospitals.map((hospital) => {
      const best = seeds.reduce((nearest, seed) => {
        const distanceMap = buildIslandDistanceMap(routes, seed.islandId);
        const distance = distanceMap.get(hospital.id);
        if (distance == null) return nearest;
        return Math.min(nearest, Number(seed.offset || 0) + distance);
      }, Number.POSITIVE_INFINITY);
      return { hospital, distance: best };
    });
    const reachable = scored.filter((entry) => Number.isFinite(entry.distance));
    const pool = reachable.length ? reachable : scored.map((entry) => ({ ...entry, distance: 0 }));
    pool.sort((a, b) => a.distance - b.distance || String(a.hospital.name || "").localeCompare(String(b.hospital.name || ""), "zh-Hant"));
    return pool[0]?.hospital || null;
  }

  function tierForEnemyDistance(islandId, distanceMap, maxDistance) {
    const distance = distanceMap.get(islandId) ?? maxDistance;
    const ratio = maxDistance > 0 ? distance / maxDistance : 0;
    if (ratio <= 0.38) return "T5";
    if (ratio <= 0.58) return "T4";
    if (ratio <= 0.75) return "T3";
    if (ratio <= 0.9) return "T2";
    return "T1";
  }

  function enemyLevelBand(tier) {
    return ENEMY_TIER_LEVEL_BANDS[legacyTier(tier)] || ENEMY_TIER_LEVEL_BANDS.T5;
  }

  function enemyLevelForProgress(tier, progress = 0.5) {
    const band = enemyLevelBand(tier);
    const ratio = Math.max(0, Math.min(1, Number(progress) || 0));
    return Math.max(band.min, Math.min(band.max, Math.round(band.min + (band.max - band.min) * ratio)));
  }

  function enemyMovePowerCap(tier, level = 1) {
    const normalizedTier = legacyTier(tier);
    const normalizedLevel = Math.max(1, Math.min(CHARACTER_MAX_LEVEL, Math.round(Number(level || 1))));
    if (normalizedTier === "T1") return Math.round(118 + normalizedLevel * 0.75);
    if (normalizedTier === "T2") return Math.round(112 + normalizedLevel * 0.9);
    if (normalizedTier === "T3") return Math.round(96 + normalizedLevel * 1);
    return Infinity;
  }

  function capEnemyMovePowers(enemy = {}) {
    const cap = enemyMovePowerCap(enemy.tier, enemy.level);
    if (!Number.isFinite(cap)) return enemy;
    ["moves", "moveSet"].forEach((key) => {
      if (!Array.isArray(enemy[key])) return;
      enemy[key] = enemy[key].map((moveEntry) => {
        const category = moveEntry?.category || moveEntry?.type || "";
        const power = Number(moveEntry?.power || 0);
        if (!["attack", "special"].includes(category) || power <= cap) return moveEntry;
        return {
          ...moveEntry,
          originalPower: Number(moveEntry.originalPower || power),
          power: cap,
        };
      });
    });
    return enemy;
  }

  function enemyTierForLevel(level, fallbackTier = "T5") {
    const normalizedLevel = Math.max(1, Math.min(CHARACTER_MAX_LEVEL, Math.round(Number(level || 1))));
    const entry = Object.entries(ENEMY_TIER_LEVEL_BANDS)
      .find(([, band]) => normalizedLevel >= band.min && normalizedLevel <= band.max);
    return entry?.[0] || legacyTier(fallbackTier);
  }

  function levelGrowthProgress(level) {
    const normalized = Math.max(1, Math.min(CHARACTER_MAX_LEVEL, Number(level || 1)));
    const ratio = (normalized - 1) / Math.max(1, CHARACTER_MAX_LEVEL - 1);
    return Math.max(0, Math.min(1, 1 - Math.pow(1 - ratio, CARD_LEVEL_GROWTH_CURVE_POWER)));
  }

  function enemyLevelForDistance(islandId, distanceMap, maxDistance, tier) {
    const distance = distanceMap.get(islandId) ?? maxDistance;
    const ratio = maxDistance > 0 ? distance / maxDistance : 0;
    return enemyLevelForProgress(tier, ratio);
  }

  function withEnemyLevel(profile, level) {
    const next = {
      ...profile,
      level: Math.max(1, Math.min(CHARACTER_MAX_LEVEL, Math.round(Number(level) || enemyLevelForProgress(profile?.tier)))),
    };
    delete next._balanceVersion;
    return balanceEnemyProfile(next);
  }

  function enemyPoolTierForKey(enemyKey) {
    const key = String(enemyKey || "");
    if (!key) return "";
    return ENEMY_TIER_ORDER.find((tier) => (ENEMY_POOLS[tier] || []).some((profile) => profile.key === key))
      || legacyTier(regionalEnemyProfileForKey(key)?.tier || "");
  }

  function positionBalancedEnemyProfileForIsland(islandId, rand, usedEnemyKeys, distanceMap, maxDistance, existingProfile = null) {
    const usedKeys = usedEnemyKeys || new Set();
    const preferredTier = tierForEnemyDistance(islandId, distanceMap, maxDistance);
    const regionIds = regionalSpawnIdsForIslandId(islandId);
    const sourceProfile = existingProfile
      && legacyTier(existingProfile.tier) === preferredTier
      && !enemyBlockedByPrisonerCrew(existingProfile.key)
      && regionalEnemyProfileAllowed(existingProfile, regionIds)
      && !usedKeys.has(String(existingProfile.key || ""))
      ? existingProfile
      : pickUniqueEnemyProfile(preferredTier, rand, usedKeys, regionIds);
    const sourceTier = enemyPoolTierForKey(sourceProfile?.key) || legacyTier(sourceProfile?.tier || preferredTier);
    const level = enemyLevelForDistance(islandId, distanceMap, maxDistance, sourceTier);
    const profile = regionalizeEnemySpawnProfile(withEnemyLevel({ ...sourceProfile, tier: sourceTier }, level), regionIds);
    profile._positionBalanceVersion = ISLAND_ENEMY_POSITION_BALANCE_VERSION;
    profile._spawnRegionPresetVersion = regionalEnemySpawnConfig()?.version || "";
    profile._spawnPostgameUnlocked = regionalEnemySpawnPostgameUnlocked();
    return profile;
  }

  function enemyIslandDistanceContext(game = state.gameState) {
    const boardData = game?.boardData || {};
    const islands = Array.isArray(boardData.islands) ? boardData.islands : [];
    const routes = boardData.routesBetweenIslands || MAP_TEMPLATE.routesBetweenIslands;
    const distanceMap = buildIslandDistanceMapFromReverseMountain(routes);
    const maxEnemyDistance = Math.max(
      1,
      ...islands
        .filter((island) => island.id !== START_ISLAND_ID && island.id !== INVERSION_MOUNTAIN_ID && island.kind !== "yonko" && island.kind !== "yonko-slot" && island.kind !== "final")
        .map((island) => distanceMap.get(island.id) ?? 1)
    );
    return { distanceMap, maxEnemyDistance };
  }

  function usedEnemyKeysForIslandRefresh(skipIslandId, previousKey = "") {
    const used = prisonerCrewEnemyKeys();
    if (previousKey) used.add(String(previousKey));
    activeEnemyReservationKeys({ skipLocationKey: enemyReservationLocationKeyForIslandId(skipIslandId) }).forEach((key) => used.add(key));
    const boardData = state.gameState?.boardData;
    if (!boardData?.islandStates || !Array.isArray(boardData.islands)) return used;
    boardData.islands.forEach((island) => {
      if (island.id === skipIslandId || island.kind !== "enemy") return;
      const islandState = boardData.islandStates[island.id];
      const key = islandState?.enemyProfile?.key;
      if (key) used.add(String(key));
    });
    return used;
  }

  function refreshEnemyIslandProfile(island, islandState) {
    if (!island || !islandState || island.kind !== "enemy") return null;
    const previousKey = islandState.enemyProfile?.key || "";
    islandState.enemyRefreshCycle = Math.max(0, Number(islandState.enemyRefreshCycle || 0)) + 1;
    const { distanceMap, maxEnemyDistance } = enemyIslandDistanceContext();
    const rand = createRng(`${state.gameState.seed}-enemy-island-refresh-${island.id}-${islandState.enemyRefreshCycle}-${state.gameState.round || 1}`);
    const profile = positionBalancedEnemyProfileForIsland(
      island.id,
      rand,
      usedEnemyKeysForIslandRefresh(island.id, previousKey),
      distanceMap,
      maxEnemyDistance,
      null
    );
    island.enemyTier = profile.tier;
    islandState.enemyTier = profile.tier;
    islandState.enemyProfile = profile;
    islandState.maxHp = profile.maxHp;
    islandState.currentHp = profile.maxHp;
    islandState.currentKind = "enemy";
    islandState.isDefeated = false;
    islandState.temporaryServiceKind = "";
    islandState.temporaryServiceStartedRound = 0;
    islandState.temporaryServiceExpiresAtRound = 0;
    islandState.lastDefeatedEnemyKey = previousKey;
    islandState.shopStock = [];
    islandState.shopStockUnlockStage = "";
    return profile;
  }

  function refreshEnemyIslandProfileIfReservedElsewhere(island, islandState) {
    if (!island || !islandState || island.kind !== "enemy" || islandState.isDefeated || !islandState.enemyProfile) return null;
    const enemyKey = String(islandState.enemyProfile.key || "").trim();
    if (!enemyKey) return null;
    const locationKey = enemyReservationLocationKeyForIsland(island);
    const reservedElsewhere = activeEnemyReservationKeys({ skipLocationKey: locationKey });
    if (!reservedElsewhere.has(enemyKey)) return null;
    const previousName = islandState.enemyProfile.name || "原敵人";
    const profile = refreshEnemyIslandProfile(island, islandState);
    if (profile && profile.key !== enemyKey) {
      addLog(`${island.name} 原本的 ${previousName} 已在別處交戰，改由 ${profile.name} 佔據此島。`);
    }
    return profile;
  }

  function applyYonkoEnemyProfileToState(island, islandState) {
    if (!island || !islandState || island.kind !== "yonko") return null;
    const profile = yonkoBossProfileForIsland(island);
    if (!profile) return null;
    const wasDefeated = Boolean(islandState.isYonkoDefeated || islandState.isDefeated);
    const previousMaxHp = Math.max(1, Number(islandState.maxHp || islandState.enemyProfile?.maxHp || profile.maxHp || 1));
    const previousCurrentHp = Number(islandState.currentHp || previousMaxHp);
    const currentRatio = wasDefeated ? 0 : Math.max(0, Math.min(1, previousCurrentHp / previousMaxHp));
    island.enemyTier = profile.tier;
    islandState.currentKind = "yonko";
    islandState.enemyTier = profile.tier;
    islandState.enemyProfile = profile;
    islandState.maxHp = profile.maxHp;
    islandState.currentHp = wasDefeated ? 0 : Math.max(1, Math.round(profile.maxHp * currentRatio));
    islandState.glyphId ||= island.glyphId || profile.key || "";
    islandState.isDefeated = wasDefeated;
    islandState.isYonkoDefeated = wasDefeated;
    return profile;
  }

  function ensureYonkoEnemyStates(game = state.gameState) {
    const islands = Array.isArray(game?.boardData?.islands) ? game.boardData.islands : [];
    const islandStates = game?.boardData?.islandStates || {};
    let updated = 0;
    islands.forEach((island) => {
      if (island.kind !== "yonko") return;
      const islandState = islandStates[island.id];
      if (!islandState) return;
      const needsProfile = !islandState.enemyProfile || !YONKO_BOSS_PROFILES[islandState.enemyProfile.key];
      const needsHp = Number(islandState.maxHp || 0) <= 0 || (!islandState.isYonkoDefeated && Number(islandState.currentHp || 0) <= 0);
      if (!needsProfile && !needsHp) return;
      if (applyYonkoEnemyProfileToState(island, islandState)) updated += 1;
    });
    return updated;
  }

  function refreshPrisonerCrewBlockedEnemyIslands(game = state.gameState) {
    if (!game?.boardData || state.battleState) return 0;
    const blockedKeys = prisonerCrewEnemyKeys(game);
    if (!blockedKeys.size) return 0;
    const islands = Array.isArray(game.boardData.islands) ? game.boardData.islands : [];
    const islandStates = game.boardData.islandStates || {};
    let refreshed = 0;
    islands.forEach((island) => {
      const islandState = islandStates[island.id];
      const enemyKey = islandState?.enemyProfile?.key;
      if (island.kind !== "enemy" || islandState?.isDefeated || !blockedKeys.has(String(enemyKey || ""))) return;
      if (refreshEnemyIslandProfile(island, islandState)) refreshed += 1;
    });
    return refreshed;
  }

  function activateTemporaryEnemyIslandService(island, islandState, player) {
    if (!island || !islandState || island.kind !== "enemy") return "";
    const rand = createRng(`${state.gameState.seed}-enemy-service-${island.id}-${state.gameState.round || 1}-${state.gameState.log.length}`);
    const serviceKind = TEMPORARY_ENEMY_ISLAND_SERVICE_KINDS[Math.floor(rand() * TEMPORARY_ENEMY_ISLAND_SERVICE_KINDS.length)] || "shop";
    islandState.currentKind = serviceKind;
    islandState.isDefeated = true;
    islandState.currentHp = 0;
    islandState.temporaryServiceKind = serviceKind;
    islandState.temporaryServiceStartedRound = Math.max(1, Number(state.gameState.round || 1));
    islandState.temporaryServiceExpiresAtRound = islandState.temporaryServiceStartedRound + TEMPORARY_ENEMY_ISLAND_SERVICE_ROUNDS;
    islandState.lastDefeatedEnemyKey = islandState.enemyProfile?.key || "";
    if (serviceKind === "shop") {
      islandState.shopStock = createShopStock(createRng(`${state.gameState.seed}-liberated-shop-${island.id}-${state.gameState.round || 1}`), player);
      islandState.shopStockUnlockStage = bountyUnlockStage(player);
    } else {
      islandState.shopStock = [];
      islandState.shopStockUnlockStage = "";
    }
    return serviceKind;
  }

  function playerCrewHighestLevel(player) {
    const levels = (player?.crew || []).map((card) => Number(card?.level || 1)).filter((level) => Number.isFinite(level));
    return Math.max(1, ...levels);
  }

  function regionalEncounterMinimumLevel(player) {
    return Math.max(1, Math.min(CHARACTER_MAX_LEVEL, playerCrewHighestLevel(player) - 5));
  }

  function raiseEnemyProfileToPlayerLevelFloor(profile, player) {
    if (!profile) return profile;
    const currentLevel = Math.max(1, Number(profile.level || enemyLevelForProgress(profile.tier)));
    const targetLevel = regionalEncounterMinimumLevel(player);
    if (currentLevel >= targetLevel) return profile;
    const raised = withEnemyLevel({ ...profile }, targetLevel);
    raised._levelFloorAdjustedFrom = Math.round(currentLevel);
    raised._levelFloorTarget = targetLevel;
    return raised;
  }

  function raiseEnemyIslandToPlayerLevelFloor(island, islandState, player) {
    if (island?.kind !== "enemy" || !islandState?.enemyProfile) return null;
    const previousProfile = islandState.enemyProfile;
    const raisedProfile = raiseEnemyProfileToPlayerLevelFloor(previousProfile, player);
    if (raisedProfile === previousProfile) return null;
    const previousMaxHp = Math.max(1, Number(islandState.maxHp || previousProfile.maxHp || 1));
    const currentRatio = Math.max(0, Math.min(1, Number(islandState.currentHp ?? previousMaxHp) / previousMaxHp));
    islandState.enemyProfile = raisedProfile;
    islandState.enemyTier = raisedProfile.tier;
    islandState.maxHp = raisedProfile.maxHp;
    islandState.currentHp = Math.max(1, Math.round(raisedProfile.maxHp * currentRatio));
    island.enemyTier = raisedProfile.tier;
    return {
      fromLevel: raisedProfile._levelFloorAdjustedFrom,
      toLevel: raisedProfile._levelFloorTarget,
      enemyName: raisedProfile.name || "敵人",
    };
  }

  function seaEncounterTierCapForPlayer(player) {
    const highestLevel = playerCrewHighestLevel(player);
    if (highestLevel < 20) return "T5";
    if (highestLevel < 40) return "T4";
    if (highestLevel < 60) return "T3";
    if (highestLevel < 80) return "T2";
    return "T1";
  }

  function filterSeaEncounterTiersByPlayer(tierPool, player) {
    const maxTierIndex = ENEMY_TIER_ORDER.indexOf(seaEncounterTierCapForPlayer(player));
    return (tierPool || []).filter((entry) => {
      const tierIndex = ENEMY_TIER_ORDER.indexOf(entry.id);
      return tierIndex >= 0 && tierIndex <= maxTierIndex;
    });
  }

  function pickUniqueEnemyProfile(preferredTier, rand, usedEnemyKeys, regionIds = []) {
    const usedKeys = usedEnemyKeys || new Set();
    const blockedKeys = prisonerCrewEnemyKeys();
    const activeReservedKeys = activeEnemyReservationKeys();
    const preferredIndex = ENEMY_TIER_ORDER.indexOf(preferredTier);
    const orderedTiers = ENEMY_TIER_ORDER
      .map((tier, index) => ({ tier, distance: preferredIndex >= 0 ? Math.abs(index - preferredIndex) : 99 }))
      .sort((a, b) => a.distance - b.distance || ENEMY_TIER_ORDER.indexOf(a.tier) - ENEMY_TIER_ORDER.indexOf(b.tier))
      .map((entry) => entry.tier);
    const normalizedRegionIds = uniqueRegionalSpawnIds(regionIds);
    const regionalProfiles = regionalEnemyProfilesForRegionIds(normalizedRegionIds);
    if (normalizedRegionIds.length && regionalProfiles.length) {
      const pickFromRegionalPool = (excludeUsed) => {
        for (const tier of orderedTiers) {
          const pool = regionalProfiles.filter((profile) => (enemyPoolTierForKey(profile.key) || legacyTier(profile.tier)) === tier);
          const candidates = pool.filter((profile) => !blockedKeys.has(profile.key)
            && !activeReservedKeys.has(profile.key)
            && (!excludeUsed || !usedKeys.has(profile.key)));
          if (!candidates.length) continue;
          return candidates[Math.floor(rand() * candidates.length)];
        }
        return null;
      };
      const regionalFallback = pickFromRegionalPool(true)
        || pickFromRegionalPool(false)
        || regionalProfiles[Math.floor(rand() * regionalProfiles.length)];
      if (regionalFallback) {
        usedKeys.add(regionalFallback.key);
        return regionalizeEnemySpawnProfile(cloneEnemy(regionalFallback), normalizedRegionIds);
      }
    }
    for (const tier of orderedTiers) {
      const pool = ENEMY_POOLS[tier] || [];
      const unused = pool.filter((profile) => !RESERVED_STORY_ENEMY_KEYS.has(profile.key) && !blockedKeys.has(profile.key) && !usedKeys.has(profile.key) && !activeReservedKeys.has(profile.key));
      if (!unused.length) continue;
      const picked = unused[Math.floor(rand() * unused.length)];
      usedKeys.add(picked.key);
      return cloneEnemy(picked);
    }
    const preferredPool = ENEMY_POOLS[preferredTier] || [];
    const allPools = ENEMY_TIER_ORDER.flatMap((tier) => ENEMY_POOLS[tier] || []);
    const candidatePool = preferredPool.length ? preferredPool : allPools;
    const fallbackPool = candidatePool.filter((profile) => !RESERVED_STORY_ENEMY_KEYS.has(profile.key) && !blockedKeys.has(profile.key) && !usedKeys.has(profile.key) && !activeReservedKeys.has(profile.key));
    const fallbackWithoutUsed = candidatePool.filter((profile) => !RESERVED_STORY_ENEMY_KEYS.has(profile.key) && !blockedKeys.has(profile.key) && !activeReservedKeys.has(profile.key));
    const fallbackCandidates = fallbackPool.length ? fallbackPool : (fallbackWithoutUsed.length ? fallbackWithoutUsed : candidatePool);
    const fallback = fallbackCandidates[Math.floor(rand() * fallbackCandidates.length)] || allPools[0];
    usedKeys.add(fallback.key);
    return cloneEnemy(fallback);
  }

  function pickSeaEncounterEnemy(tile, player) {
    const refreshCycle = Math.max(0, Number(state.gameState?.seaEncounterRefreshCycle || 0));
    const rand = createRng(`${state.gameState.seed}-sea-encounter-${refreshCycle}-${tile?.id || "sea"}-${player?.id || "player"}`);
    const progress = getSeaTileDistanceProgress(tile);
    const tierPoolByProgress = progress <= 0.22
      ? [
        { id: "T5", weight: 100 },
      ]
      : progress <= 0.42
        ? [
          { id: "T5", weight: 78 },
          { id: "T4", weight: 22 },
        ]
        : progress <= 0.62
          ? [
            { id: "T5", weight: 32 },
            { id: "T4", weight: 34 },
            { id: "T3", weight: 26 },
            { id: "T2", weight: 8 },
          ]
          : progress <= 0.82
            ? [
              { id: "T4", weight: 18 },
              { id: "T3", weight: 38 },
              { id: "T2", weight: 36 },
              { id: "T1", weight: 8 },
            ]
            : [
              { id: "T3", weight: 18 },
              { id: "T2", weight: 52 },
              { id: "T1", weight: 30 },
            ];
    const tier = pickWeighted(tierPoolByProgress, rand);
    const blockedKeys = new Set(prisonerCrewEnemyKeys());
    const activeReservedKeys = activeEnemyReservationKeys({ skipLocationKey: enemyReservationLocationKeyForSea(tile, player) });
    activeReservedKeys.forEach((key) => blockedKeys.add(key));
    const regionIds = regionalSpawnIdsForSeaTile(tile);
    const selectedProfile = pickUniqueEnemyProfile(tier, rand, blockedKeys, regionIds);
    const selectedTier = enemyPoolTierForKey(selectedProfile?.key) || legacyTier(selectedProfile?.tier || tier);
    const levelCap = playerCrewHighestLevel(player) + 6;
    const distanceLevel = enemyLevelForProgress(selectedTier, progress);
    const band = enemyLevelBand(selectedTier);
    const distanceBoundedLevel = Math.max(band.min, Math.min(band.max, levelCap, distanceLevel));
    const encounterLevel = Math.max(distanceBoundedLevel, regionalEncounterMinimumLevel(player));
    const leveledProfile = withEnemyLevel({ ...selectedProfile, tier: selectedTier }, encounterLevel);
    return cloneSeaEncounterEnemy(regionalizeEnemySpawnProfile(leveledProfile, regionIds));
  }

  function getSeaTileDistanceProgress(tile) {
    const boardData = state.gameState?.boardData;
    const routes = boardData?.routesBetweenIslands || MAP_TEMPLATE.routesBetweenIslands;
    const routeItem = routes.find((entry) => entry.id === tile?.routeId);
    if (!routeItem) {
      if (tile?.zone === "danger") return 0.78;
      if (tile?.zone === "safe") return 0.18;
      return 0.5;
    }
    const distanceMap = buildIslandDistanceMapFromStart(routes);
    const maxDistance = Math.max(
      1,
      ...(boardData?.islands || MAP_TEMPLATE.islandSlots)
        .filter((island) => island.id !== START_ISLAND_ID && island.id !== INVERSION_MOUNTAIN_ID && island.kind !== "yonko" && island.kind !== "yonko-slot" && island.kind !== "final")
        .map((island) => distanceMap.get(island.id) ?? 1)
    );
    const fromDistance = distanceMap.get(routeItem.from) ?? maxDistance;
    const toDistance = distanceMap.get(routeItem.to) ?? maxDistance;
    const tileCount = Math.max(1, routeItem.tiles?.length || 5);
    const stepProgress = Math.max(0, Math.min(1, (Number(tile?.index || 0) + 1) / (tileCount + 1)));
    const nearDistance = Math.min(fromDistance, toDistance);
    const farDistance = Math.max(fromDistance, toDistance);
    const estimatedDistance = nearDistance + (farDistance - nearDistance) * stepProgress;
    return Math.max(0, Math.min(1, estimatedDistance / maxDistance));
  }

  function rerollSeaTilePrimaryTypes() {
    const game = state.gameState;
    const tiles = game?.boardData?.seaTiles;
    if (!Array.isArray(tiles) || !tiles.length) return 0;
    const cycle = Math.max(0, Number(game.seaEncounterRefreshCycle || 0));
    tiles.forEach((tile) => {
      const pool = seaCardTypePoolForRoute(tile.routeId, tile.zone || "mid");
      const rand = createRng(`${game.seed}-sea-refresh-${cycle}-${tile.id}`);
      tile.primaryTypeId = pickWeighted(pool, rand);
    });
    return tiles.filter((tile) => tile.primaryTypeId === "encounter").length;
  }

  function maybeRefreshSeaEncounterTiles() {
    const game = state.gameState;
    const tiles = game?.boardData?.seaTiles;
    if (!Array.isArray(tiles) || !tiles.length) return false;
    const round = Math.max(1, Number(game.round || 1));
    const lastRefreshRound = Math.max(1, Number(game.seaEncounterLastRefreshRound || 1));
    if (round - lastRefreshRound < SEA_ENCOUNTER_REFRESH_ROUNDS) return false;
    game.seaEncounterRefreshCycle = Math.max(0, Number(game.seaEncounterRefreshCycle || 0)) + 1;
    game.seaEncounterLastRefreshRound = round;
    const encounterCount = rerollSeaTilePrimaryTypes();
    addLog(`海域敵影重新流動，遭遇格已換位（目前 ${encounterCount} 格）。`);
    return true;
  }

  function randomizeBoardFromSeed(seedValue) {
    const rand = createRng(seedValue);
    const finalIslandLayout = null;
    const shopPool = shuffleArray(MAP_TEMPLATE.shopIslandPool.slice(), rand);
    const hospitalPool = shuffleArray(MAP_TEMPLATE.hospitalIslandPool.slice(), rand);
    const tavernPool = shuffleArray(MAP_TEMPLATE.tavernIslandPool.slice(), rand);
    const missionPool = shuffleArray((MAP_TEMPLATE.missionIslandPool || []).slice(), rand);
    const enemyIslandPool = shuffleArray(MAP_TEMPLATE.enemyIslandPool.slice(), rand);
    const drawIslandPick = (pool, source) => {
      if (!pool.length) pool.push(...shuffleArray(source.slice(), rand));
      return pool.pop() || source[0] || {};
    };
    const variableSlots = MAP_TEMPLATE.islandSlots.filter((slot) => slot.kind === "variable" || slot.kind === "grid-slot");
    const variableRoleMap = assignVariableIslandRoles(variableSlots, rand);
    const yonkoBySlot = Object.fromEntries(
      (MAP_TEMPLATE.yonkoCornerSlots || []).map((index, slotIndex) => [`island-${index}`, MAP_TEMPLATE.yonkoCornerPool[slotIndex]])
    );
    const distanceMap = buildIslandDistanceMapFromReverseMountain(MAP_TEMPLATE.routesBetweenIslands);
    const maxEnemyDistance = Math.max(
      1,
      ...MAP_TEMPLATE.islandSlots
        .filter((slot) => slot.id !== START_ISLAND_ID && slot.id !== INVERSION_MOUNTAIN_ID && slot.kind !== "yonko-slot" && slot.kind !== "final")
        .map((slot) => distanceMap.get(slot.id) ?? 1)
    );

    const islands = MAP_TEMPLATE.islandSlots.map((slot) => {
      if (slot.kind === "start" || slot.kind === "final") {
        return {
          id: slot.id,
          kind: slot.kind,
          col: slot.col,
          row: slot.row,
          name: slot.fixedName,
          brief: slot.brief,
          hint: slot.kind === "final" ? "集滿 4 份歷史本文拓本後才會現身" : slot.hint,
          enemyTier: slot.tier || "",
          glyphId: slot.glyphId || "",
          finalAnchorIslandId: "",
          finalRouteId: "",
        };
      }
      if (slot.kind === "yonko-slot") {
        const yonko = yonkoBySlot[slot.id];
        return {
          id: slot.id,
          kind: "yonko",
          col: slot.col,
          row: slot.row,
          name: yonko ? `${yonko.title}據點` : "四皇據點",
          brief: "四皇據點",
          hint: yonko ? `${yonko.title} 駐守於此` : "四皇駐守於此",
          enemyTier: "T1",
          glyphId: yonko?.glyphId || "",
        };
      }
      if (slot.kind === "grid-slot") {
        const role = normalizeIslandRole(variableRoleMap[slot.id] || "enemy");
        if (role === "enemy") {
          const pick = drawIslandPick(enemyIslandPool, MAP_TEMPLATE.enemyIslandPool);
          return { id: slot.id, kind: "enemy", col: slot.col, row: slot.row, name: pick.name, brief: pick.brief, hint: pick.hint, enemyTier: "", glyphId: "" };
        }
        if (role === "shop") {
          const pick = drawIslandPick(shopPool, MAP_TEMPLATE.shopIslandPool);
          return { id: slot.id, kind: "shop", col: slot.col, row: slot.row, name: pick.name, brief: pick.brief, hint: pick.hint, enemyTier: "", glyphId: "" };
        }
        if (role === "hospital") {
          const pick = drawIslandPick(hospitalPool, MAP_TEMPLATE.hospitalIslandPool);
          return { id: slot.id, kind: "hospital", col: slot.col, row: slot.row, name: pick.name, brief: pick.brief, hint: pick.hint, enemyTier: "", glyphId: "" };
        }
        if (role === "tavern") {
          const pick = drawIslandPick(tavernPool, MAP_TEMPLATE.tavernIslandPool);
          return { id: slot.id, kind: "tavern", col: slot.col, row: slot.row, name: pick.name, brief: pick.brief, hint: pick.hint, enemyTier: "", glyphId: "" };
        }
        if (role === "mission") {
          const pick = drawIslandPick(missionPool, MAP_TEMPLATE.missionIslandPool);
          return { id: slot.id, kind: "mission", col: slot.col, row: slot.row, name: pick.name, brief: pick.brief, hint: pick.hint, enemyTier: "", glyphId: "" };
        }
        const pick = drawIslandPick(enemyIslandPool, MAP_TEMPLATE.enemyIslandPool);
        return { id: slot.id, kind: "enemy", col: slot.col, row: slot.row, name: pick.name, brief: pick.brief, hint: pick.hint, enemyTier: "", glyphId: "" };
      }
      if (slot.fixedName && slot.kind !== "yonko") {
        return {
          id: slot.id,
          kind: slot.kind,
          col: slot.col,
          row: slot.row,
          name: slot.fixedName,
          brief: slot.brief,
          hint: slot.hint,
          enemyTier: slot.tier || "",
          glyphId: slot.glyphId || "",
        };
      }
      if (slot.kind === "shop") {
        const pick = drawIslandPick(shopPool, MAP_TEMPLATE.shopIslandPool);
        return { id: slot.id, kind: "shop", col: slot.col, row: slot.row, name: pick.name, brief: pick.brief, hint: pick.hint, enemyTier: "", glyphId: "" };
      }
      if (slot.kind === "island") {
        const pick = drawIslandPick(shopPool, MAP_TEMPLATE.shopIslandPool);
        return { id: slot.id, kind: "shop", col: slot.col, row: slot.row, name: pick.name, brief: pick.brief, hint: pick.hint, enemyTier: "", glyphId: "" };
      }
      if (slot.kind === "variable") {
        const role = normalizeIslandRole(variableRoleMap[slot.id] || "enemy");
        if (role === "enemy") {
          const pick = drawIslandPick(enemyIslandPool, MAP_TEMPLATE.enemyIslandPool);
          return { id: slot.id, kind: "enemy", col: slot.col, row: slot.row, name: pick.name, brief: pick.brief, hint: pick.hint, enemyTier: "", glyphId: "" };
        }
        if (role === "shop") {
          const pick = drawIslandPick(shopPool, MAP_TEMPLATE.shopIslandPool);
          return { id: slot.id, kind: "shop", col: slot.col, row: slot.row, name: pick.name, brief: pick.brief, hint: pick.hint, enemyTier: "", glyphId: "" };
        }
        if (role === "hospital") {
          const pick = drawIslandPick(hospitalPool, MAP_TEMPLATE.hospitalIslandPool);
          return { id: slot.id, kind: "hospital", col: slot.col, row: slot.row, name: pick.name, brief: pick.brief, hint: pick.hint, enemyTier: "", glyphId: "" };
        }
        if (role === "tavern") {
          const pick = drawIslandPick(tavernPool, MAP_TEMPLATE.tavernIslandPool);
          return { id: slot.id, kind: "tavern", col: slot.col, row: slot.row, name: pick.name, brief: pick.brief, hint: pick.hint, enemyTier: "", glyphId: "" };
        }
        if (role === "mission") {
          const pick = drawIslandPick(missionPool, MAP_TEMPLATE.missionIslandPool);
          return { id: slot.id, kind: "mission", col: slot.col, row: slot.row, name: pick.name, brief: pick.brief, hint: pick.hint, enemyTier: "", glyphId: "" };
        }
        const pick = drawIslandPick(shopPool, MAP_TEMPLATE.shopIslandPool);
        return { id: slot.id, kind: "shop", col: slot.col, row: slot.row, name: pick.name, brief: pick.brief, hint: pick.hint, enemyTier: "", glyphId: "" };
      }
      return {
        id: slot.id,
        kind: slot.kind,
        col: slot.col,
        row: slot.row,
        name: slot.kind === "yonko" ? `四皇據點・${slot.id.split("-").pop()}` : "未知敵島",
        brief: slot.kind === "yonko" ? "四皇據點" : "敵人島",
        hint: "",
        enemyTier: slot.tier || "",
        glyphId: slot.glyphId || "",
      };
    });

    islands.forEach((island) => {
      if (island.id === START_ISLAND_ID) {
        island.pxX = ACTIVE_MAP_LAYOUT.markers.loguetown.x;
        island.pxY = ACTIVE_MAP_LAYOUT.markers.loguetown.y;
        return;
      }
      if (island.id === INVERSION_MOUNTAIN_ID) {
        island.pxX = ACTIVE_MAP_LAYOUT.markers.reverse.x;
        island.pxY = ACTIVE_MAP_LAYOUT.markers.reverse.y;
        return;
      }
      const gridIndex = Number(String(island.id).replace("island-", ""));
      if (ACTIVE_MAP_LAYOUT.islands[gridIndex]) {
        island.pxX = ACTIVE_MAP_LAYOUT.islands[gridIndex].x;
        island.pxY = ACTIVE_MAP_LAYOUT.islands[gridIndex].y;
      }
    });
    const islandStates = {};
    const usedEnemyKeys = new Set();
    islands.forEach((island) => {
      const stateItem = {
        islandId: island.id,
        currentKind: island.kind,
        isDefeated: false,
        maxHp: 0,
        currentHp: 0,
        enemyTier: island.enemyTier || "",
        enemyProfile: null,
        glyphId: island.glyphId || "",
        isYonkoDefeated: false,
        copiedByPlayers: [],
        shopStock: island.kind === "shop" ? createShopStock(rand) : [],
        shopStockUnlockStage: island.kind === "shop" ? "C" : "",
        temporaryServiceKind: "",
        temporaryServiceStartedRound: 0,
        temporaryServiceExpiresAtRound: 0,
        enemyRefreshCycle: 0,
        lastDefeatedEnemyKey: "",
      };
      if (island.kind === "enemy") {
        const profile = positionBalancedEnemyProfileForIsland(island.id, rand, usedEnemyKeys, distanceMap, maxEnemyDistance);
        island.enemyTier = profile.tier;
        stateItem.enemyTier = profile.tier;
        stateItem.enemyProfile = profile;
        stateItem.maxHp = profile.maxHp;
        stateItem.currentHp = profile.maxHp;
      } else if (island.kind === "yonko") {
        applyYonkoEnemyProfileToState(island, stateItem);
      }
      islandStates[island.id] = stateItem;
    });

    const runtimeRoutesBetweenIslands = buildRuntimeRoutesBetweenIslands(MAP_TEMPLATE.routesBetweenIslands, islands, finalIslandLayout);
    rebuildIslandDirectionalLinks(islands, runtimeRoutesBetweenIslands);

    const islandLookup = Object.fromEntries(islands.map((island) => [island.id, island]));
    const routedBetweenIslands = runtimeRoutesBetweenIslands.map((routeItem) => ({
      ...routeItem,
      tiles: buildDisplayRouteTiles(routeItem, islandLookup),
    }));

    const seaTiles = [];
    routedBetweenIslands.forEach((routeItem) => {
      seaTiles.push(...buildRouteSeaTiles(routeItem, rand));
    });

    return {
      mapTemplate: MAP_TEMPLATE.mapTemplate,
      inversionMountainRoutes: MAP_TEMPLATE.inversionMountainRoutes.map((item) => ({ ...item })),
      islands,
      routesBetweenIslands: routedBetweenIslands,
      seaTiles,
      islandStates,
      finalIslandLayout: null,
    };
  }

  function buildDisplayRouteTiles(routeItem, islandLookup) {
    const from = islandLookup[routeItem.from];
    const to = islandLookup[routeItem.to];
    const steps = Math.max(routeItem.tiles?.length || 0, 5);
    const fromPos = nodeToPx(from);
    const toPos = nodeToPx(to);
    const dx = toPos.x - fromPos.x;
    const dy = toPos.y - fromPos.y;
    const distance = Math.hypot(dx, dy) || 1;
    const unitX = dx / distance;
    const unitY = dy / distance;
    return Array.from({ length: steps }, (_, index) => {
      const customTile = getCustomSeaTile(routeItem, index + 1, steps);
      const ratio = (index + 1) / (steps + 1);
      const base = routeItem.tiles?.[index] || routeItem.tiles?.[routeItem.tiles.length - 1] || { col: 0, row: 0 };
      const rawX = customTile ? customTile.x : Math.round(fromPos.x + dx * ratio);
      const rawY = customTile ? customTile.y : Math.round(fromPos.y + dy * ratio);
      const endpointNudge = seaTileEndpointNudge(index, steps);
      return {
        ...base,
        pxX: Math.round(rawX + unitX * endpointNudge),
        pxY: Math.round(rawY + unitY * endpointNudge),
      };
    });
  }

  function seaTileEndpointNudge(index, steps) {
    if (index === 0) return 28;
    if (index === 1) return 14;
    if (index === steps - 2) return -14;
    if (index === steps - 1) return -28;
    return 0;
  }

  function getCustomSeaTile(routeRef, step, totalSteps = 5) {
    if (!ACTIVE_MAP_LAYOUT.seaTiles) return null;
    const routeKeys = getCustomRouteLookupKeys(routeRef);
    const matches = Object.entries(ACTIVE_MAP_LAYOUT.seaTiles)
      .filter(([id, tile]) => {
        const tileRouteId = String(tile.routeId || "");
        return routeKeys.includes(tileRouteId) || routeKeys.some((routeId) => id.startsWith(`${routeId}-sea-`));
      })
      .map(([, tile]) => tile)
      .sort((a, b) => Number(a.step || 0) - Number(b.step || 0));
    if (!matches.length) return null;
    const direct = matches.find((tile) => Number(tile.step) === step);
    if (direct && matches.length === totalSteps) return direct;
    const targetRatio = step / (totalSteps + 1);
    let best = matches[0];
    let bestDistance = Infinity;
    matches.forEach((tile, index) => {
      const tileRatio = (index + 1) / (matches.length + 1);
      const distance = Math.abs(tileRatio - targetRatio);
      if (distance < bestDistance) {
        best = tile;
        bestDistance = distance;
      }
    });
    return best;
  }

  function getCustomRouteLookupKeys(routeRef) {
    if (!routeRef) return [];
    if (typeof routeRef === "string") return [routeRef];
    const keys = new Set();
    if (routeRef.id) keys.add(String(routeRef.id));
    const from = routeEndpointLayoutName(routeRef.from);
    const to = routeEndpointLayoutName(routeRef.to);
    if (from && to) {
      keys.add(`route-${from}-${to}`);
      keys.add(`route-${to}-${from}`);
    }
    return [...keys];
  }

  function routeEndpointLayoutName(endpoint) {
    if (!endpoint) return null;
    if (endpoint === START_ISLAND_ID) return "loguetown";
    if (endpoint === INVERSION_MOUNTAIN_ID) return "reverse";
    if (endpoint === "final-island") return "final";
    const islandMatch = String(endpoint).match(/^island-(\d+)$/);
    if (islandMatch) return islandMatch[1];
    return String(endpoint);
  }

  function assignVariableIslandRoles(slots, rand) {
    const out = {};
    const usage = { shop: 0, hospital: 0, tavern: 0, mission: 0, enemy: 0 };
    const total = slots.length;
    const caps = {
      shop: Math.max(8, Math.floor(total * 0.2)),
      hospital: Math.max(6, Math.floor(total * 0.14)),
      tavern: Math.max(6, Math.floor(total * 0.14)),
      mission: Math.max(4, Math.floor(total * 0.1)),
      enemy: Math.max(16, Math.floor(total * 0.44)),
    };
    const ordered = shuffleArray(slots.slice(), rand);

    ordered.forEach((slot) => {
      const weights = roleWeightsForSlot(slot);
      const candidates = slot.allowKinds
        .map((kind) => ({ kind, weight: weights[kind] || 0 }))
        .filter((entry) => entry.weight > 0 && usage[entry.kind] < (caps[entry.kind] ?? 99));
      const pool = candidates.length ? candidates : slot.allowKinds.map((kind) => ({ kind, weight: 1 }));
      const role = pickWeightedRole(pool, rand);
      out[slot.id] = role;
      usage[role] = (usage[role] || 0) + 1;
    });

    const dangerSlots = ordered.filter((slot) => slot.roleBand === "danger");
    while (usage.enemy < Math.max(10, Math.floor(total * 0.2))) {
      const fallback = dangerSlots.find((slot) => out[slot.id] !== "enemy" && slot.allowKinds.includes("enemy"));
      if (!fallback) break;
      usage[out[fallback.id]] -= 1;
      out[fallback.id] = "enemy";
      usage.enemy += 1;
    }

    return out;
  }

  function roleWeightsForSlot(slot) {
    if (slot.roleBand === "safe") return { shop: 28, hospital: 20, tavern: 20, mission: 14, enemy: 18 };
    if (slot.roleBand === "mid") return { shop: 16, hospital: 14, tavern: 16, mission: 14, enemy: 40 };
    return { shop: 9, hospital: 8, tavern: 10, mission: 9, enemy: 64 };
  }

  function normalizeIslandRole(role) {
    return ["shop", "hospital", "tavern", "mission", "enemy"].includes(role) ? role : "enemy";
  }

  function pickWeightedRole(pool, rand) {
    const total = pool.reduce((sum, entry) => sum + entry.weight, 0);
    let cursor = rand() * total;
    for (const entry of pool) {
      cursor -= entry.weight;
      if (cursor <= 0) return entry.kind;
    }
    return pool[pool.length - 1].kind;
  }

  function createSeedFromRoom(roomCode) {
    return roomCode.split("").reduce((sum, ch) => sum + ch.charCodeAt(0), 97);
  }

  function createRng(seedValue) {
    let seed = 0;
    if (typeof seedValue === "string") {
      seed = 2166136261;
      for (let index = 0; index < seedValue.length; index += 1) {
        seed ^= seedValue.charCodeAt(index);
        seed = Math.imul(seed, 16777619);
      }
    } else {
      seed = Number(seedValue) || 0;
    }
    seed >>>= 0;
    return function rand() {
      seed = (seed * 1664525 + 1013904223) >>> 0;
      return seed / 4294967296;
    };
  }

  function shuffleArray(list, rand) {
    const out = list.slice();
    for (let i = out.length - 1; i > 0; i -= 1) {
      const j = Math.floor(rand() * (i + 1));
      [out[i], out[j]] = [out[j], out[i]];
    }
    return out;
  }

  function randomSubset(list, count, rand) {
    return shuffleArray(list, rand).slice(0, Math.min(count, list.length)).map((item) => ({ ...item }));
  }

  function pickWeighted(pool, rand) {
    const total = pool.reduce((sum, entry) => sum + entry.weight, 0);
    let cursor = rand() * total;
    for (const entry of pool) {
      cursor -= entry.weight;
      if (cursor <= 0) return entry.id;
    }
    return pool[pool.length - 1].id;
  }

  function currentPlayer() {
    return state.gameState.players[state.gameState.currentPlayerIndex] || null;
  }

  function localBoardPlayer() {
    if (!state.gameState?.players?.length) return currentPlayer();
    if (!boardLan.enabled) return currentPlayer();
    return state.gameState.players.find((player) => canBoardLanControlPlayerIdentity(player))
      || state.gameState.players.find((player) => player.isMe)
      || currentPlayer();
  }

  function boardPlayerMatchesLocalUser(player = null) {
    const localUserId = Number(profile.userId);
    const playerUserId = Number(player?.userId || player?.id);
    return Number.isFinite(localUserId) && Number.isFinite(playerUserId) && localUserId === playerUserId;
  }

  function forceCpuPlayersFromQuery() {
    const value = String(query.get("cpu4") || query.get("cpuPlayers") || query.get("allCpu") || "").trim().toLowerCase();
    return ["1", "4", "all", "true", "yes"].includes(value);
  }

  function isCpuPlayer(player = null) {
    return !!player && (
      player.isCPU === true
      || player.isCpu === true
      || player.cpu === true
      || String(player.clientId || "").startsWith("board-cpu-")
    );
  }

  function cpuTurnDelay(ms, player = null, min = 90) {
    const base = Number(ms || 0);
    if (!isCpuPlayer(player)) return base;
    return Math.max(Number(min || 0), Math.round(base / currentCpuTurnSpeed()));
  }

  function localPlayerIsLobbyHost() {
    if (!boardLan.enabled) return true;
    const hostUserId = Number(state.lobby?.hostUserId);
    const localUserId = Number(profile.userId);
    if (Number.isFinite(hostUserId) && hostUserId > 0 && Number.isFinite(localUserId) && localUserId > 0) {
      return hostUserId === localUserId;
    }
    return (state.lobby?.players || []).some((player) => player?.isMe && player?.isHost);
  }

  function canLocalDriveCpuPlayer(player = null) {
    if (!isCpuPlayer(player)) return false;
    return !boardLan.enabled || localPlayerIsLobbyHost();
  }

  function mapViewerPlayer() {
    return localBoardPlayer() || currentPlayer();
  }

  function canBoardLanControlPlayerIdentity(player = null) {
    if (!boardLan.enabled || !player) return true;
    if (canLocalDriveCpuPlayer(player)) return true;
    const localClientId = String(boardLan.clientId || profile.clientId || "").trim();
    const playerClientId = String(player.clientId || "").trim();
    const fallbackClientId = String(player.userId || player.id || "").trim();
    const playerClientIdIsSynthetic = playerClientId === fallbackClientId || playerClientId.startsWith("board-player-");
    if (boardPlayerMatchesLocalUser(player)) return true;
    if (localClientId && playerClientId && localClientId === playerClientId) return true;
    if (localClientId && playerClientId && !playerClientIdIsSynthetic) return false;
    return boardPlayerMatchesLocalUser(player);
  }

  function canBoardLanControlCurrentPlayer(player = currentPlayer()) {
    if (!boardLan.enabled || !player) return true;
    const activePlayer = currentPlayer();
    if (!activePlayer || String(activePlayer.id || activePlayer.userId || "") !== String(player.id || player.userId || "")) {
      return false;
    }
    return canBoardLanControlPlayerIdentity(player);
  }

  function warnBoardLanTurnLocked(player = currentPlayer()) {
    if (!boardLan.enabled || canBoardLanControlCurrentPlayer(player)) return false;
    const activePlayer = currentPlayer();
    shared.showToast(`現在是 ${activePlayer?.name || "其他玩家"} 的回合，請等自己的回合再操作。`);
    return true;
  }

  function bgmCharacterTag(card) {
    const id = String(card?.id || "").toLowerCase();
    return ["luffy", "zoro", "nami", "sanji", "chopper", "robin", "usopp"].includes(id) ? id : "";
  }

  function bgmIslandEnvironmentTags(island, islandState) {
    const tags = [];
    const kind = getEffectiveIslandKind(island || {}, islandState || {});
    const text = `${island?.name || ""} ${island?.brief || ""} ${island?.hint || ""}`.toLowerCase();
    if (kind === "shop") tags.push("village", "food");
    if (isMedicalServiceIslandKind(kind)) tags.push("healing", kind === "research_lab" ? "laboratory" : "village");
    if (kind === "tavern") tags.push("food", "village");
    if (island?.kind === "yonko") tags.push("boss", "danger");
    if (island?.kind === "enemy") tags.push("danger");
    if (text.includes("冬") || text.includes("雪") || text.includes("cold")) tags.push("cold");
    if (text.includes("熱") || text.includes("火") || text.includes("沙") || text.includes("hot")) tags.push("hot");
    if (text.includes("港") || text.includes("harbor")) tags.push("harbor");
    return [...new Set(tags)];
  }

  function bgmDangerLevelForBattle(battle) {
    if (!battle) return 1;
    if (battle.isJudicialRaid || battle.islandKind === "yonko" || battle.enemyTier === "T1") return 5;
    if (battle.enemyTier === "T2") return 4;
    if (battle.enemyTier === "T3" || battle.isSeaEncounter) return 3;
    return 2;
  }

  function bgmBattleContext(battle = state.battleState) {
    if (!battle) return null;
    if (!battle.bgmScopeId) {
      battle.bgmScopeId = `battle-${battle.playerId || "player"}-${battle.islandId || battle.seaTileId || "field"}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
    }
    const player = state.gameState.players.find((entry) => entry.id === battle.playerId) || currentPlayer();
    const activeCard = player?.crew?.[battle.activeCrewIndex] || activeCrew(player);
    const island = battle.isSeaEncounter ? null : getIslandById(battle.islandId);
    const islandState = island ? getIslandState(island.id) : null;
    const playerHpRate = activeCard?.maxHp ? activeCard.currentHp / activeCard.maxHp : 1;
    const enemyHpRate = battle.enemyCombatant?.maxHp ? battle.enemyCombatant.currentHp / battle.enemyCombatant.maxHp : 1;
    const isBoss = battle.isJudicialRaid || battle.islandKind === "yonko" || battle.enemyTier === "T1";
    const isClimax = isBoss ? (playerHpRate < 0.35 || enemyHpRate < 0.45) : (playerHpRate < 0.25 || enemyHpRate < 0.3);
    const battlePhase = battle.result === "win" ? "" : (isClimax ? "climax" : ((battle.playerPerformedAction || battle.enemyPerformedAction) ? "loop" : "intro"));
    if (battle.result === "win") {
      return {
        phase: "victory",
        musicScope: `victory-${battle.bgmScopeId}`,
        sceneType: "battle_result",
        locationType: battle.isSeaEncounter ? "sea" : "island",
        islandType: battle.islandKind || "",
        character: bgmCharacterTag(activeCard),
        enemyType: [battle.enemyTier, battle.enemyCombatant?.role, battle.enemyCombatant?.key, battle.enemyCombatant?.isDevilFruitUser ? "devil_fruit" : ""],
        isBoss,
        playerHpRate,
        enemyHpRate,
        dangerLevel: bgmDangerLevelForBattle(battle),
        environment: battle.isSeaEncounter ? ["ocean"] : bgmIslandEnvironmentTags(island, islandState),
        eventTags: ["victory", "success", "clear"],
        storyMood: "happy",
      };
    }
    return {
      phase: `battle_${battlePhase}`,
      musicScope: battle.bgmScopeId,
      sceneType: "battle",
      locationType: battle.isSeaEncounter ? "sea" : "island",
      islandType: battle.islandKind || "",
      character: bgmCharacterTag(activeCard),
      enemyType: [battle.enemyTier, battle.enemyCombatant?.role, battle.enemyCombatant?.key, battle.enemyCombatant?.isDevilFruitUser ? "devil_fruit" : ""],
      isBoss,
      isForcedBattle: !battle.isSeaEncounter && (battle.islandKind === "enemy" || battle.islandKind === "postgame_boss" || battle.islandKind === "postgame_egghead" || battle.islandKind === "yonko" || battle.isJudicialRaid),
      isDuel: true,
      battlePhase,
      playerHpRate,
      enemyHpRate,
      dangerLevel: bgmDangerLevelForBattle(battle),
      environment: battle.isSeaEncounter ? ["ocean"] : bgmIslandEnvironmentTags(island, islandState),
      eventTags: [battle.isSeaEncounter ? "sea_creature" : "", isBoss ? "boss" : "", enemyHpRate < 0.35 ? "counterattack" : ""],
      storyMood: battlePhase === "climax" ? "intense" : "tense",
      isCounterattack: enemyHpRate < 0.35 && playerHpRate > 0,
      minBgmHoldMs: 60000,
    };
  }

  function bgmMapContext() {
    const player = currentPlayer();
    if (!player) return { phase: "menu", sceneType: "setup", eventTags: ["journey_start"], storyMood: "hopeful" };
    if (String(state.gameState.phase || "").startsWith("setup")) {
      return { phase: "menu", sceneType: "setup", character: bgmCharacterTag(activeCrew(player)), eventTags: ["journey_start", "pirate_king"], storyMood: "hopeful" };
    }
    if (player.location?.kind === "route") {
      return {
        phase: "map",
        sceneType: "sailing",
        locationType: "sea",
        character: bgmCharacterTag(activeCrew(player)),
        environment: ["ocean"],
        eventTags: ["sailing", "journey", "grand_line"],
        dangerLevel: 1,
        storyMood: "adventurous",
      };
    }
    const island = player.location?.islandId ? getIslandById(player.location.islandId) : null;
    const islandState = island ? getIslandState(island.id) : null;
    return {
      phase: "map",
      sceneType: "island_map",
      locationType: "island",
      islandType: getEffectiveIslandKind(island || {}, islandState || {}),
      character: bgmCharacterTag(activeCrew(player)),
      environment: bgmIslandEnvironmentTags(island, islandState),
      eventTags: ["landing", "island"],
      dangerLevel: ["postgame_boss", "postgame_egghead"].includes(island?.kind) ? 5 : island?.kind === "enemy" || island?.kind === "yonko" ? 3 : 1,
      storyMood: "adventurous",
    };
  }

  function playBgmForContext(context, options = {}) {
    if (!context) return null;
    if (luffyGearFifthVideoBgmPaused) return window.BgmManager?.status?.().currentChoice || null;
    return window.BgmManager?.chooseAndPlay?.(context, options) || null;
  }

  function refreshBgmForState(options = {}) {
    if (state.battleState) return playBgmForContext(bgmBattleContext(state.battleState), options);
    return playBgmForContext(bgmMapContext(), options);
  }

  function activeCrew(player) {
    return player?.crew?.[player.activeCrewIndex] || null;
  }

  function activeCrewCarryEffect(player) {
    return battleCarryItemEffect(battleCarryItemsForCard(activeCrew(player))[0]);
  }

  function activeCrewHasCarryEffect(player, kinds = []) {
    const expected = Array.isArray(kinds) ? kinds : [kinds];
    return battleCarryItemsForCard(activeCrew(player)).some((item) => expected.includes(battleCarryItemEffect(item)?.kind || ""));
  }

  function validateBattleCarryEquip(card, item) {
    const normalized = normalizeBattleCarryItem(item);
    const def = battleCarryItemDef(normalized);
    if (!card) return { ok: false, reason: "找不到角色。" };
    if (!def) return { ok: false, reason: "這不是可裝備的戰鬥攜帶物。" };
    const effect = battleCarryItemEffect(normalized);
    if ((def.id === "seastone_bullet" || effect.forbidDevilFruitUser) && isDevilFruitCharacter(card)) {
      return { ok: false, reason: `能力者無法攜帶${def.name}。` };
    }
    return { ok: true, reason: "" };
  }

  function isLockedBattleCarryItem(item) {
    const normalized = normalizeBattleCarryItem(item);
    if (!normalized?.bound) return false;
    if (YONKO_COUNTER_ITEM_IDS.has(normalized.id)) return false;
    return true;
  }

  function returnBattleCarryItemToBackpack(player, item) {
    const normalized = normalizeBattleCarryItem(item);
    if (!player || !normalized || isLockedBattleCarryItem(normalized)) return false;
    if (normalized.id === BULLET_ARSENAL_ITEM_ID) {
      battleCarryArsenalItems(normalized).forEach((inner) => addBattleCarryItemToBackpack(player, { ...inner, bound: false }));
      return !!addBattleCarryItemToBackpack(player, createBattleCarryItem(BULLET_ARSENAL_ITEM_ID));
    }
    return !!addBattleCarryItemToBackpack(player, { ...normalized, bound: false });
  }

  function returnBattleCarryFromRemovedCard(player, card) {
    const item = normalizeBattleCarryItem(card?.battleCarryItem);
    if (!item) return "";
    if (returnBattleCarryItemToBackpack(player, item)) {
      card.battleCarryItem = null;
      return battleCarryItemName(item);
    }
    return "";
  }

  function equipBattleCarryItemFromInventory(player, cardIndex, inventoryIndex) {
    ensurePlayerBattleCarryState(player);
    const card = player?.crew?.[cardIndex];
    const item = normalizeBattleCarryItem(player?.items?.[inventoryIndex]);
    const def = battleCarryItemDef(item);
    const validation = validateBattleCarryEquip(card, item);
    if (!validation.ok) return validation;
    if (isLockedBattleCarryItem(card.battleCarryItem)) {
      return { ok: false, reason: `${battleCarryItemName(card.battleCarryItem)} 無法卸下，因此不能更換。` };
    }
    const previousMaxHp = cardMaxHp(card);
    const previousHp = Math.max(0, Number(card.currentHp ?? previousMaxHp));
    player.items.splice(inventoryIndex, 1);
    removeInventoryItem(player, item.id, 1);
    const previous = normalizeBattleCarryItem(card.battleCarryItem);
    if (previous) returnBattleCarryItemToBackpack(player, previous);
    card.battleCarryItem = item;
    const nextMaxHp = cardMaxHp(card);
    card.currentHp = previousHp <= 0 ? 0 : Math.max(1, Math.min(nextMaxHp, Math.round(previousHp * nextMaxHp / previousMaxHp)));
    addLog(`${card.name} 裝備了 ${battleCarryItemName(item)}。`);
    recordMissionEvent(player, { type: "equip_held", itemId: item.id, itemName: battleCarryItemName(item), category: "held" });
    const carryRank = itemRarityLabel(gameItemDef(item.id)?.rarity || def.rarity);
    if (["A", "S"].includes(carryRank)) {
      recordMainMissionEvent(player, { type: "equip_high_held", itemId: item.id, rank: carryRank });
    }
    return { ok: true, reason: "" };
  }

  function unequipBattleCarryItem(player, cardIndex) {
    ensurePlayerBattleCarryState(player);
    const card = player?.crew?.[cardIndex];
    const item = normalizeBattleCarryItem(card?.battleCarryItem);
    if (!card || !item) return { ok: false, reason: "角色目前沒有攜帶物。" };
    if (isLockedBattleCarryItem(item)) return { ok: false, reason: `${battleCarryItemName(item)} 無法卸下。` };
    const previousMaxHp = cardMaxHp(card);
    const previousHp = Math.max(0, Number(card.currentHp ?? previousMaxHp));
    returnBattleCarryItemToBackpack(player, item);
    card.battleCarryItem = null;
    const nextMaxHp = cardMaxHp(card);
    card.currentHp = previousHp <= 0 ? 0 : Math.max(1, Math.min(nextMaxHp, Math.round(previousHp * nextMaxHp / previousMaxHp)));
    addLog(`${card.name} 卸下了 ${battleCarryItemName(item)}，物品已回到背包。`);
    return { ok: true, reason: "" };
  }

  function validateBattleCarryArsenalInsert(card, item, slotIndex = -1) {
    const normalized = normalizeBattleCarryItem(item);
    if (normalized?.id === BULLET_ARSENAL_ITEM_ID) return { ok: false, reason: "武器庫不能裝入另一個武器庫。" };
    const validation = validateBattleCarryEquip(card, normalized);
    if (!validation.ok) return validation;
    const arsenal = normalizeBattleCarryItem(card?.battleCarryItem);
    const resolvedSlot = Number(slotIndex);
    const duplicateIndex = battleCarryArsenalSlots(arsenal)
      .findIndex((entry, index) => entry?.id === normalized.id && index !== resolvedSlot);
    if (duplicateIndex >= 0) {
      return { ok: false, reason: `同一種兵裝不能重複裝入；${battleCarryItemName(normalized)}已在第 ${duplicateIndex + 1} 槽。` };
    }
    return validation;
  }

  function equipBattleCarryItemIntoArsenal(player, cardIndex, slotIndex, inventoryIndex) {
    ensurePlayerBattleCarryState(player);
    const card = player?.crew?.[cardIndex];
    const arsenal = normalizeBattleCarryItem(card?.battleCarryItem);
    const item = normalizeBattleCarryItem(player?.items?.[inventoryIndex]);
    const resolvedSlot = Math.max(0, Math.min(BULLET_ARSENAL_SLOT_LIMIT - 1, Number(slotIndex || 0)));
    if (!card || arsenal?.id !== BULLET_ARSENAL_ITEM_ID) return { ok: false, reason: "角色目前沒有裝備巴雷特的武器庫。" };
    const validation = validateBattleCarryArsenalInsert(card, item, resolvedSlot);
    if (!validation.ok) return validation;
    const previousMaxHp = cardMaxHp(card);
    const previousHp = Math.max(0, Number(card.currentHp ?? previousMaxHp));
    player.items.splice(inventoryIndex, 1);
    removeInventoryItem(player, item.id, 1);
    const slots = Array.from({ length: BULLET_ARSENAL_SLOT_LIMIT }, (_, index) => arsenal.arsenalItems?.[index] || null);
    const previous = slots[resolvedSlot];
    if (previous) addBattleCarryItemToBackpack(player, { ...previous, bound: false });
    slots[resolvedSlot] = item;
    arsenal.arsenalItems = slots;
    card.battleCarryItem = arsenal;
    const nextMaxHp = cardMaxHp(card);
    card.currentHp = previousHp <= 0 ? 0 : Math.max(1, Math.min(nextMaxHp, Math.round(previousHp * nextMaxHp / previousMaxHp)));
    addLog(`${card.name}把${battleCarryItemName(item)}裝入巴雷特的武器庫第 ${resolvedSlot + 1} 槽。`);
    recordMissionEvent(player, { type: "equip_held", itemId: item.id, itemName: battleCarryItemName(item), category: "held" });
    return { ok: true, reason: "" };
  }

  function unequipBattleCarryItemFromArsenal(player, cardIndex, slotIndex) {
    ensurePlayerBattleCarryState(player);
    const card = player?.crew?.[cardIndex];
    const arsenal = normalizeBattleCarryItem(card?.battleCarryItem);
    const resolvedSlot = Math.max(0, Math.min(BULLET_ARSENAL_SLOT_LIMIT - 1, Number(slotIndex || 0)));
    if (!card || arsenal?.id !== BULLET_ARSENAL_ITEM_ID) return { ok: false, reason: "角色目前沒有裝備巴雷特的武器庫。" };
    const slots = Array.from({ length: BULLET_ARSENAL_SLOT_LIMIT }, (_, index) => arsenal.arsenalItems?.[index] || null);
    const item = slots[resolvedSlot];
    if (!item) return { ok: false, reason: "這個兵裝槽目前是空的。" };
    const previousMaxHp = cardMaxHp(card);
    const previousHp = Math.max(0, Number(card.currentHp ?? previousMaxHp));
    addBattleCarryItemToBackpack(player, { ...item, bound: false });
    slots[resolvedSlot] = null;
    arsenal.arsenalItems = slots;
    card.battleCarryItem = arsenal;
    const nextMaxHp = cardMaxHp(card);
    card.currentHp = previousHp <= 0 ? 0 : Math.max(1, Math.min(nextMaxHp, Math.round(previousHp * nextMaxHp / previousMaxHp)));
    addLog(`${card.name}把${battleCarryItemName(item)}從巴雷特的武器庫卸回背包。`);
    return { ok: true, reason: "" };
  }

  function openBulletArsenalLoadoutModal(player, cardIndex, selectedSlotIndex = 0, options = {}) {
    ensurePlayerBattleCarryState(player);
    const card = player?.crew?.[cardIndex];
    const arsenal = normalizeBattleCarryItem(card?.battleCarryItem);
    if (!card || arsenal?.id !== BULLET_ARSENAL_ITEM_ID) {
      openEquipBattleCarryModal(player, cardIndex, options);
      return;
    }
    const selectedSlot = Math.max(0, Math.min(BULLET_ARSENAL_SLOT_LIMIT - 1, Number(selectedSlotIndex || 0)));
    const loadout = Array.from({ length: BULLET_ARSENAL_SLOT_LIMIT }, (_, index) => arsenal.arsenalItems?.[index] || null);
    const selectedItem = loadout[selectedSlot];
    const entries = battleCarryInventoryEntries(player).filter(({ item }) => item.id !== BULLET_ARSENAL_ITEM_ID);
    const def = battleCarryItemDef(arsenal);
    openModal(`
      <section class="carry-item-ui bullet-arsenal-ui" aria-label="${escapeModalText(cardDisplayName(card))} 的巴雷特武器庫">
        <img class="carry-item-panel-frame" src="images/board/carry_item_ui/carry_item_panel_frame.webp" alt="" aria-hidden="true">
        <header class="carry-item-heading"><h3>${escapeModalText(cardDisplayName(card))}・巴雷特的武器庫</h3><p>選擇兩件不同兵裝同時生效</p></header>
        <div class="carry-current-icon-stage">${itemIconMarkup({ name: def.name, category: "held", image: def.image }, "carry-current-icon", { badge: "武" })}</div>
        <div class="carry-current-name">兵裝槽 ${selectedSlot + 1}</div>
        <div class="carry-current-copy">
          <div class="bullet-arsenal-slot-tabs">
            ${loadout.map((item, index) => `<button type="button" class="bullet-arsenal-slot-tab${index === selectedSlot ? " is-active" : ""}" data-arsenal-slot="${index}"><span>${index + 1}</span>${escapeModalText(item ? battleCarryItemName(item) : "空槽")}</button>`).join("")}
          </div>
          <strong>${escapeModalText(selectedItem ? battleCarryItemName(selectedItem) : "尚未裝入兵裝")}</strong><br>${escapeModalText(selectedItem ? battleCarryItemSummary(selectedItem) : "從右側背包選擇一件攜帶物；不能放入另一個武器庫，也不能和另一槽重複。")}
        </div>
        <div class="carry-current-action"><button type="button" class="modal-btn secondary" id="unequipArsenalSlotBtn" ${selectedItem ? "" : "disabled"}>${selectedItem ? "卸下此槽兵裝" : "此槽目前為空"}</button></div>
        <div class="carry-inventory-heading"><strong>可裝入的攜帶物</strong><span>共 ${entries.length} 個</span></div>
        <div class="carry-item-list">
          ${entries.length ? entries.map(({ item, index }) => {
            const itemDef = battleCarryItemDef(item);
            const validation = validateBattleCarryArsenalInsert(card, item, selectedSlot);
            return `<article class="carry-item-row${validation.ok ? "" : " is-disabled"}">
              ${itemIconMarkup({ name: itemDef.name, category: "held", image: itemDef.image }, "carry-item-row-icon", { badge: itemDef.name.slice(0, 1) })}
              <div class="carry-item-row-copy"><div><strong>${escapeModalText(itemDef.name)}</strong><span>${escapeModalText(itemDef.rarity)}・${escapeModalText(itemDef.category)}</span></div><p>${escapeModalText(itemDef.summary)}${validation.ok ? "" : `（不能裝入：${escapeModalText(validation.reason)}）`}</p></div>
              <button type="button" class="modal-btn ${validation.ok ? "primary" : "secondary"}" data-arsenal-inventory-index="${index}" ${validation.ok ? "" : "disabled"}>${selectedItem ? "更換" : "裝入"}</button>
            </article>`;
          }).join("") : `<div class="carry-item-empty-note">背包中沒有可裝入的角色攜帶物。</div>`}
        </div>
        <footer class="carry-item-footer"><button type="button" class="modal-btn secondary" id="backArsenalLoadoutBtn">返回攜帶物整備</button></footer>
      </section>
    `, "carry-item-nautical-modal");
    refs.modal.querySelectorAll("[data-arsenal-slot]").forEach((button) => button.addEventListener("click", () => openBulletArsenalLoadoutModal(player, cardIndex, Number(button.dataset.arsenalSlot), options)));
    refs.modal.querySelectorAll("[data-arsenal-inventory-index]").forEach((button) => button.addEventListener("click", () => {
      const result = equipBattleCarryItemIntoArsenal(player, cardIndex, selectedSlot, Number(button.dataset.arsenalInventoryIndex));
      if (!result.ok) addLog(result.reason);
      renderAll();
      openBulletArsenalLoadoutModal(player, cardIndex, selectedSlot, options);
    }));
    document.getElementById("unequipArsenalSlotBtn")?.addEventListener("click", () => {
      const result = unequipBattleCarryItemFromArsenal(player, cardIndex, selectedSlot);
      if (!result.ok) addLog(result.reason);
      renderAll();
      openBulletArsenalLoadoutModal(player, cardIndex, selectedSlot, options);
    });
    document.getElementById("backArsenalLoadoutBtn")?.addEventListener("click", () => openEquipBattleCarryModal(player, cardIndex, options));
  }

  function openEquipBattleCarryModal(player, cardIndex, options = {}) {
    ensurePlayerBattleCarryState(player);
    const card = player?.crew?.[cardIndex];
    if (!card) return;
    const returnTo = typeof options === "string" ? options : String(options?.returnTo || "");
    const returnFromEquipCarryModal = () => {
      if (returnTo === "detail" || returnTo === "detailCrewManage") {
        openCharacterDetail(player, cardIndex, { returnTo: returnTo === "detailCrewManage" ? "crewManage" : "" });
        return;
      }
      if (returnTo === "crewManage") {
        openCrewManagementModal(player, cardIndex);
        return;
      }
      closeModal();
    };
    const entries = battleCarryInventoryEntries(player);
    const currentItem = normalizeBattleCarryItem(card.battleCarryItem);
    const currentDef = battleCarryItemDef(currentItem);
    const currentLocked = Boolean(currentItem && isLockedBattleCarryItem(currentItem));
    const returnLabel = returnTo === "detail" || returnTo === "detailCrewManage"
      ? "返回船員詳情"
      : (returnTo === "crewManage" ? "返回船員名冊" : "關閉");
    openModal(`
      <section class="carry-item-ui" aria-label="${escapeModalText(cardDisplayName(card))} 的攜帶物整備">
        <img class="carry-item-panel-frame" src="images/board/carry_item_ui/carry_item_panel_frame.webp" alt="" aria-hidden="true">
        <header class="carry-item-heading">
          <h3>${escapeModalText(cardDisplayName(card))}・攜帶物整備</h3>
          <p>每名角色最多攜帶 1 個</p>
        </header>
        <div class="carry-current-icon-stage${currentItem ? "" : " is-empty"}">
          ${currentItem
            ? itemIconMarkup({ name: currentDef?.name || battleCarryItemName(currentItem), category: "held", image: currentDef?.image || battleCarryItemImage(currentDef) }, "carry-current-icon", { badge: battleCarryItemName(currentItem).slice(0, 1) })
            : `<span class="carry-current-empty">尚未裝備</span>`}
        </div>
        <div class="carry-current-name">${escapeModalText(currentDef?.name || "目前沒有攜帶物")}</div>
        <div class="carry-current-copy">
          ${currentDef
            ? `<strong>${escapeModalText(currentDef.rarity)}・${escapeModalText(currentDef.category)}</strong><br>${escapeModalText(currentDef.summary)}${currentLocked ? `<br><em>此攜帶物目前無法卸下或更換。</em>` : ""}`
            : "從右側選擇背包中的角色攜帶物。裝備後會移到角色身上；更換時，原攜帶物會自動回到背包。"}
        </div>
        <div class="carry-current-action${currentItem?.id === BULLET_ARSENAL_ITEM_ID ? " is-arsenal" : ""}">
          ${currentItem?.id === BULLET_ARSENAL_ITEM_ID ? `<button type="button" class="modal-btn primary" id="manageBulletArsenalBtn">整備兩件兵裝</button>` : ""}
          <button type="button" class="modal-btn secondary" id="unequipCarryFromEquipModalBtn" ${!currentItem || currentLocked ? "disabled" : ""}>${currentLocked ? "此攜帶物無法卸下" : (currentItem ? "卸下攜帶物" : "目前沒有攜帶物")}</button>
        </div>
        <div class="carry-inventory-heading">
          <strong>背包中的攜帶物</strong>
          <span>共 ${entries.length} 個</span>
        </div>
        <div class="carry-item-list">
        ${entries.length ? entries.map(({ item, index }) => {
          const def = battleCarryItemDef(item);
          const validation = validateBattleCarryEquip(card, item);
          return `
            <article class="carry-item-row${validation.ok ? "" : " is-disabled"}">
              ${itemIconMarkup({ name: def.name, category: "held", image: def.image || battleCarryItemImage(def) }, "carry-item-row-icon", { badge: def.name.slice(0, 1) })}
              <div class="carry-item-row-copy">
                <div><strong>${escapeModalText(def.name)}</strong><span>${escapeModalText(def.rarity)}・${escapeModalText(def.category)}</span></div>
                <p>${escapeModalText(def.summary)}${validation.ok ? "" : `（不能裝備：${escapeModalText(validation.reason)}）`}</p>
              </div>
              <button type="button" class="modal-btn ${validation.ok ? "primary" : "secondary"}" data-equip-carry-index="${index}" ${validation.ok ? "" : "disabled"}>${currentItem ? "更換" : "裝備"}</button>
            </article>
          `;
          }).join("") : `<div class="carry-item-empty-note">背包中沒有可裝備的角色攜帶物。</div>`}
        </div>
        <footer class="carry-item-footer"><button type="button" class="modal-btn secondary" id="backEquipCarryBtn">${returnLabel}</button></footer>
      </section>
    `, "carry-item-nautical-modal");
    refs.modal.querySelectorAll("[data-equip-carry-index]").forEach((button) => {
      button.addEventListener("click", () => {
        const result = equipBattleCarryItemFromInventory(player, cardIndex, Number(button.dataset.equipCarryIndex));
        if (!result.ok) {
          addLog(result.reason);
          openEquipBattleCarryModal(player, cardIndex, options);
          return;
        }
        renderAll();
        if (normalizeBattleCarryItem(card.battleCarryItem)?.id === BULLET_ARSENAL_ITEM_ID) openBulletArsenalLoadoutModal(player, cardIndex, 0, options);
        else openEquipBattleCarryModal(player, cardIndex, options);
      });
    });
    document.getElementById("unequipCarryFromEquipModalBtn")?.addEventListener("click", () => {
      const result = unequipBattleCarryItem(player, cardIndex);
      if (!result.ok) addLog(result.reason);
      renderAll();
      openEquipBattleCarryModal(player, cardIndex, options);
    });
    document.getElementById("manageBulletArsenalBtn")?.addEventListener("click", () => openBulletArsenalLoadoutModal(player, cardIndex, 0, options));
    document.getElementById("backEquipCarryBtn")?.addEventListener("click", returnFromEquipCarryModal);
  }

  function cosmeticFramePreviewLayersMarkup(frameId = "") {
    if (!frameId) return "";
    if (frameId === "nikaFrame") {
      return [
        { id: "sunGlow", asset: "images/board/battle/nika_frame/nika_sun_glow.webp", x: 50, y: 51, w: 150, h: 122, opacity: 0.74, z: 7, blend: "screen" },
        { id: "cloudLeft", asset: "images/board/battle/nika_frame/nika_cloud_left.webp", x: 7.5, y: 28, w: 52, h: 128, opacity: 1, z: 5, blend: "normal" },
        { id: "cloudRight", asset: "images/board/battle/nika_frame/nika_cloud_right.webp", x: 90, y: 56, w: 52, h: 128, opacity: 1, z: 5, blend: "normal" },
        { id: "frame", asset: "images/board/battle/nika_frame/nika_card_frame.webp", x: 50, y: 48.5, w: 116, h: 116, opacity: 1, z: 10, blend: "normal" },
      ].map((layer) => `
        <img class="cosmetic-frame-preview-layer is-nika-${layer.id}"
          src="${layer.asset}" alt="" aria-hidden="true" loading="lazy" decoding="async"
          style="left:${layer.x}%;top:${layer.y}%;width:${layer.w}%;height:${layer.h}%;opacity:${layer.opacity};z-index:${layer.z};mix-blend-mode:${layer.blend};">
      `).join("");
    }
    const layers = COSMETIC_FRAME_PREVIEW_CONFIGS[frameId]?.layers || {};
    return Object.entries(layers).map(([layerId, layer]) => {
      if (!layer?.asset) return "";
      const rotate = Number(layer.rotate || 0);
      const flipX = layer.flipX ? -1 : 1;
      const flipY = layer.flipY ? -1 : 1;
      const strength = Number(layer.strength || 1);
      return `
        <img class="cosmetic-frame-preview-layer"
          data-preview-layer="${escapeModalText(layerId)}" src="${escapeModalText(layer.asset)}"
          alt="" aria-hidden="true" loading="lazy" decoding="async"
          style="left:${Number(layer.x ?? 50)}%;top:${Number(layer.y ?? 50)}%;width:${Number(layer.w ?? 100)}%;height:${Number(layer.h ?? 100)}%;opacity:${Number(layer.opacity ?? 1)};z-index:${Number(layer.z ?? 5)};mix-blend-mode:${escapeModalText(layer.blend || "normal")};--cosmetic-preview-rotate:${rotate}deg;--cosmetic-preview-flip-x:${flipX};--cosmetic-preview-flip-y:${flipY};--cosmetic-preview-strength:${strength};">
      `;
    }).join("");
  }

  function openCrewCosmeticFrameModal(player, cardIndex, options = {}) {
    const card = player?.crew?.[cardIndex];
    if (!card) return;
    const modalOptions = typeof options === "string" ? { returnTo: options } : (options || {});
    const returnTo = String(modalOptions.returnTo || "");
    const currentFrameId = activeCrewCosmeticFrameId(player, card);
    const currentFrameDef = cosmeticFrameDef(currentFrameId);
    const frameDefs = availableCosmeticFrameDefsForCard(player, card);
    const availableFrameIds = new Set(["", ...frameDefs.map((def) => def.id)]);
    const requestedPreviewId = Object.prototype.hasOwnProperty.call(modalOptions, "previewFrameId")
      ? normalizeCosmeticFrameId(modalOptions.previewFrameId)
      : currentFrameId;
    const previewFrameId = availableFrameIds.has(requestedPreviewId) ? requestedPreviewId : currentFrameId;
    const previewFrameDef = cosmeticFrameDef(previewFrameId);
    const portraits = cardPortraitsForDisplay(card);
    const frameChoices = [{ id: "", label: "無框", unlockText: "保留角色原本的戰鬥卡樣式" }, ...frameDefs];
    const hasPendingChange = previewFrameId !== currentFrameId;
    const returnFromFrameModal = () => {
      if (returnTo === "crewManage") {
        openCrewManagementModal(player, cardIndex);
        return;
      }
      openCharacterDetail(player, cardIndex, { returnTo: returnTo === "detailCrewManage" ? "crewManage" : "" });
    };
    openModal(`
      <section class="cosmetic-frame-ui" aria-label="${escapeModalText(cardDisplayName(card))} 的外觀框選擇">
        <img class="cosmetic-frame-panel-art" src="images/board/cosmetic_frame_ui/cosmetic_frame_panel_frame.webp" alt="" aria-hidden="true">
        <header class="cosmetic-frame-heading"><h3>選擇外觀框</h3></header>
        <div class="cosmetic-frame-preview-area">
          <div class="cosmetic-frame-card-preview${previewFrameId ? " has-frame" : ""}">
            ${cosmeticFramePreviewLayersMarkup(previewFrameId)}
            <div class="cosmetic-frame-preview-portrait">
              <img src="${escapeModalText(portraits.normal)}" alt="${escapeModalText(cardDisplayName(card))}" loading="lazy"
                data-fallback-src="${escapeModalText(portraits.idle || portraits.normal)}"
                onerror="if(this.dataset.fallbackSrc){this.src=this.dataset.fallbackSrc;this.dataset.fallbackSrc='';}else{this.remove();}">
            </div>
          </div>
        </div>
        <div class="cosmetic-frame-preview-name">
          <strong>${escapeModalText(cardDisplayName(card))}</strong>
          <span>${escapeModalText(previewFrameDef?.label || "無框")}</span>
        </div>
        <div class="cosmetic-frame-preview-status">
          <span>目前裝備：${escapeModalText(currentFrameDef?.label || "無框")}</span>
          <small>${escapeModalText(previewFrameDef?.unlockText || "不套用外觀框")}</small>
        </div>
        <div class="cosmetic-frame-choice-list" role="listbox" aria-label="可用外觀框">
          ${frameChoices.map((def) => {
            const isSelected = def.id === previewFrameId;
            const isCurrent = def.id === currentFrameId;
            return `
              <button type="button" class="cosmetic-frame-choice${isSelected ? " is-selected" : ""}${isCurrent ? " is-current" : ""}"
                data-preview-cosmetic-frame="${escapeModalText(def.id)}" role="option" aria-selected="${isSelected}">
                <span class="cosmetic-frame-choice-copy">
                  <strong>${escapeModalText(def.label)}</strong>
                  <small>${escapeModalText(def.unlockText || "外觀框")}</small>
                </span>
                ${isCurrent ? `<em>使用中</em>` : (isSelected ? `<em>預覽中</em>` : "")}
              </button>
            `;
          }).join("")}
        </div>
        <footer class="cosmetic-frame-footer">
          <button type="button" class="modal-btn primary" id="confirmCrewCosmeticFrameBtn" ${hasPendingChange ? "" : "disabled"}>${hasPendingChange ? (previewFrameId ? "裝備此框" : "改成無框") : "目前使用中"}</button>
          <button type="button" class="modal-btn secondary" id="backCrewCosmeticFrameBtn">返回詳情</button>
        </footer>
      </section>
    `, "cosmetic-frame-nautical-modal");
    refs.modal.querySelectorAll("[data-preview-cosmetic-frame]").forEach((button) => {
      button.addEventListener("click", () => {
        openCrewCosmeticFrameModal(player, cardIndex, { returnTo, previewFrameId: button.dataset.previewCosmeticFrame || "" });
      });
    });
    const cosmeticChoiceList = refs.modal.querySelector(".cosmetic-frame-choice-list");
    const selectedCosmeticChoice = cosmeticChoiceList?.querySelector(".cosmetic-frame-choice.is-selected");
    if (cosmeticChoiceList && selectedCosmeticChoice) {
      cosmeticChoiceList.scrollTop = Math.max(0, selectedCosmeticChoice.offsetTop);
    }
    document.getElementById("confirmCrewCosmeticFrameBtn")?.addEventListener("click", () => {
      if (!hasPendingChange) return;
      const result = equipCrewCosmeticFrame(player, cardIndex, previewFrameId);
      if (!result.ok) {
        addLog(result.reason);
        openCrewCosmeticFrameModal(player, cardIndex, { returnTo, previewFrameId: currentFrameId });
        return;
      }
      renderAll();
      openCharacterDetail(player, cardIndex, { returnTo: returnTo === "detailCrewManage" ? "crewManage" : "" });
      scheduleBoardLanStatePush("crew-cosmetic-frame", 80, { force: true });
    });
    document.getElementById("backCrewCosmeticFrameBtn")?.addEventListener("click", returnFromFrameModal);
  }

  function grantBattleCarryItemsForTesting(playerIndex = state.gameState.currentPlayerIndex) {
    const player = state.gameState.players[Math.max(0, Math.min(state.gameState.players.length - 1, Number(playerIndex) || 0))] || currentPlayer();
    if (!player) return [];
    ensurePlayerBattleCarryState(player);
    const granted = BATTLE_CARRY_ITEM_ORDER
      .map((id) => addBattleCarryItemToBackpack(player, id))
      .filter(Boolean);
    const names = granted.map((item) => battleCarryItemName(item));
    addLog(`${player.name} 取得測試用戰鬥攜帶物：${names.join("、")}。`);
    renderAll();
    return names;
  }

  function grantBattleCarryItemForTesting(itemId = "justice_cloak", playerIndex = state.gameState.currentPlayerIndex) {
    const player = state.gameState.players[Math.max(0, Math.min(state.gameState.players.length - 1, Number(playerIndex) || 0))] || currentPlayer();
    if (!player) return "";
    ensurePlayerBattleCarryState(player);
    const item = addBattleCarryItemToBackpack(player, itemId);
    if (!item) return "";
    const name = battleCarryItemName(item);
    addLog(`${player.name} 取得測試用戰鬥攜帶物：${name}。`);
    renderAll();
    return name;
  }

  function grantGameItemsForTesting(itemIds = Object.keys(GAME_ITEMS), quantity = 1, playerIndex = state.gameState.currentPlayerIndex) {
    const player = state.gameState.players[Math.max(0, Math.min(state.gameState.players.length - 1, Number(playerIndex) || 0))] || currentPlayer();
    if (!player) return [];
    ensurePlayerInventoryState(player);
    const ids = Array.isArray(itemIds) ? itemIds : [itemIds];
    const granted = [];
    ids.forEach((itemId) => {
      const def = gameItemDef(itemId);
      if (!def) return;
      const count = Math.max(1, Math.round(Number(quantity || 1)));
      if (normalizeGameItemCategory(def.category) === "held") {
        for (let index = 0; index < count; index += 1) addBattleCarryItemToBackpack(player, def.id);
      } else {
        addInventoryItem(player, def.id, count);
        if (def.id === "heal_2") player.smallSupplies = Math.max(0, Number(player.smallSupplies || 0)) + count;
        if (def.id === "battle_food") player.battleFood = Math.max(0, Number(player.battleFood || 0)) + count;
        if (def.id === "guard_charm") player.guardCharm = Math.max(0, Number(player.guardCharm || 0)) + count;
        if (def.id === "pointer") player.routeInsight = Math.max(0, Number(player.routeInsight || 0)) + count;
        if (def.id === "fixed_step") player.fixedStepTokens = Math.max(0, Number(player.fixedStepTokens || 0)) + count;
      }
      granted.push(def.name);
    });
    addLog(`${player.name} 取得測試道具：${granted.join("、")}。`);
    renderAll();
    return granted;
  }

  function isCrewCardAlive(card) {
    return !!card && Number(card.currentHp || 0) > 0;
  }

  function ensureActiveCrewAlive(player) {
    if (!player?.crew?.length) return false;
    if (isCrewCardAlive(activeCrew(player))) return true;
    const nextIndex = player.crew.findIndex((card) => isCrewCardAlive(card));
    if (nextIndex < 0) return false;
    player.activeCrewIndex = nextIndex;
    return true;
  }

  function totalCurrentPP(card) {
    return (card?.moveSet || []).reduce((sum, entry) => sum + (entry.currentPP ?? entry.pp ?? 0), 0);
  }

  function totalMaxPP(card) {
    return (card?.moveSet || []).reduce((sum, entry) => sum + (entry.pp ?? 0), 0);
  }

  function adjustCrewPP(player, amount) {
    const lead = activeCrew(player);
    if (!lead || !amount) return 0;
    if (amount > 0) {
      let remain = amount;
      for (const entry of lead.moveSet || []) {
        const current = entry.currentPP ?? entry.pp ?? 0;
        const cap = entry.pp ?? current;
        if (current >= cap) continue;
        const delta = Math.min(remain, cap - current);
        entry.currentPP = current + delta;
        remain -= delta;
        if (remain <= 0) break;
      }
      return amount - remain;
    }
    let remain = Math.abs(amount);
    const ordered = [...(lead.moveSet || [])].sort((a, b) => (b.currentPP ?? 0) - (a.currentPP ?? 0));
    for (const entry of ordered) {
      const current = entry.currentPP ?? entry.pp ?? 0;
      if (current <= 0) continue;
      const delta = Math.min(remain, current);
      entry.currentPP = current - delta;
      remain -= delta;
      if (remain <= 0) break;
    }
    return -(Math.abs(amount) - remain);
  }

  function getIslandById(id) {
    return state.gameState.boardData.islands.find((item) => item.id === id) || null;
  }

  function getIslandState(id) {
    return state.gameState.boardData.islandStates[id] || null;
  }

  function isServiceIslandKind(kind) {
    return TEMPORARY_ENEMY_ISLAND_SERVICE_KINDS.includes(kind) || kind === "mission" || kind === "research_lab" || kind === "arena";
  }

  function isMedicalServiceIslandKind(kind) {
    return kind === "hospital" || kind === "research_lab";
  }

  function serviceIslandLabel(kind) {
    return {
      shop: "商店島",
      hospital: "醫院島",
      research_lab: "研究所島",
      tavern: "酒館島",
      arena: "競技場島",
      mission: "任務島",
    }[kind] || "服務島";
  }

  function temporaryEnemyIslandTurnsLeft(islandState) {
    if (!islandState?.temporaryServiceExpiresAtRound) return 0;
    const round = Math.max(1, Number(state.gameState?.round || 1));
    return Math.max(0, Math.ceil(Number(islandState.temporaryServiceExpiresAtRound || round) - round));
  }

  function isTemporaryEnemyIslandService(island, islandState = getIslandState(island?.id)) {
    return island?.kind === "enemy"
      && islandState?.isDefeated
      && TEMPORARY_ENEMY_ISLAND_SERVICE_KINDS.includes(islandState?.currentKind)
      && Number(islandState?.temporaryServiceExpiresAtRound || 0) > 0;
  }

  function getEffectiveIslandKind(island, islandState = getIslandState(island?.id)) {
    if (!island) return "";
    if (state.gameState?.postgameWorld?.researchLabsActive && island.kind === "hospital") return "research_lab";
    if (state.gameState?.postgameWorld?.researchLabsActive && island.kind === "tavern") return "arena";
    return islandState?.currentKind || island.kind;
  }

  function normalizeTemporaryEnemyIslandServices(game = state.gameState) {
    const islands = game?.boardData?.islands;
    const islandStates = game?.boardData?.islandStates;
    if (!Array.isArray(islands) || !islandStates) return;
    const round = Math.max(1, Number(game.round || 1));
    islands.forEach((island) => {
      const islandState = islandStates[island.id];
      if (!islandState) return;
      islandState.temporaryServiceKind ||= "";
      islandState.temporaryServiceStartedRound = Math.max(0, Number(islandState.temporaryServiceStartedRound || 0));
      islandState.temporaryServiceExpiresAtRound = Math.max(0, Number(islandState.temporaryServiceExpiresAtRound || 0));
      islandState.enemyRefreshCycle = Math.max(0, Number(islandState.enemyRefreshCycle || 0));
      islandState.lastDefeatedEnemyKey ||= "";
      if (island.kind !== "enemy") return;
      if (!islandState.isDefeated || !TEMPORARY_ENEMY_ISLAND_SERVICE_KINDS.includes(islandState.currentKind)) return;
      if (!islandState.temporaryServiceExpiresAtRound) {
        islandState.temporaryServiceKind = islandState.currentKind;
        islandState.temporaryServiceStartedRound = round;
        islandState.temporaryServiceExpiresAtRound = round + TEMPORARY_ENEMY_ISLAND_SERVICE_ROUNDS;
      }
    });
  }

  function ensureWaterSevenIslandPosition(game = state.gameState) {
    const islands = game?.boardData?.islands;
    const islandStates = game?.boardData?.islandStates;
    if (!Array.isArray(islands) || !islandStates) return;
    const island = islands.find((entry) => entry.id === WATER_SEVEN_ISLAND_ID);
    if (!island) return;
    island.kind = "shop";
    island.name = "水之七島";
    island.brief = "船隻改造島";
    island.hint = "司法島往顛倒山方向一格，可購買船隻道具與船材";
    island.enemyTier = "";
    island.glyphId = "";
    const islandState = islandStates[WATER_SEVEN_ISLAND_ID] || { islandId: WATER_SEVEN_ISLAND_ID };
    islandState.currentKind = "shop";
    islandState.isDefeated = false;
    islandState.enemyProfile = null;
    islandState.enemyTier = "";
    islandState.currentHp = 0;
    islandState.maxHp = 0;
    islandState.temporaryServiceKind = "";
    islandState.temporaryServiceStartedRound = 0;
    islandState.temporaryServiceExpiresAtRound = 0;
    islandState.shopStock = Array.isArray(islandState.shopStock) && islandState.shopStock.length
      ? islandState.shopStock
      : createShopStock(createRng(`${game.seed || "load"}-water-seven-shop-stock`));
    islandState.shopStockUnlockStage ||= "C";
    islandStates[WATER_SEVEN_ISLAND_ID] = islandState;
  }

  function ensureMissionIslandsOnBoard(game = state.gameState) {
    const islands = game?.boardData?.islands;
    const islandStates = game?.boardData?.islandStates;
    if (!Array.isArray(islands) || !islandStates) return;
    if (islands.some((island) => island.kind === "mission" || islandStates[island.id]?.currentKind === "mission")) return;
    const sourcePool = MAP_TEMPLATE.missionIslandPool?.length ? MAP_TEMPLATE.missionIslandPool : [
      { name: "世界經濟新聞任務牆", brief: "任務島", hint: "可接委託賺取貝里、EXP 與懸賞" },
    ];
    const candidates = islands
      .filter((island) => ["shop", "tavern", "hospital"].includes(island.kind))
      .filter((island) => island.id !== START_ISLAND_ID && island.id !== INVERSION_MOUNTAIN_ID && island.id !== WATER_SEVEN_ISLAND_ID);
    const targetCount = Math.min(4, Math.max(1, candidates.length));
    const rand = createRng(`${game.seed || "load"}-mission-island-migration`);
    shuffleArray(candidates, rand).slice(0, targetCount).forEach((island, index) => {
      const pick = sourcePool[index % sourcePool.length] || sourcePool[0];
      island.kind = "mission";
      island.name = pick.name;
      island.brief = pick.brief;
      island.hint = pick.hint;
      island.enemyTier = "";
      island.glyphId = "";
      const islandState = islandStates[island.id] || {};
      islandState.currentKind = "";
      islandState.isDefeated = false;
      islandState.enemyProfile = null;
      islandState.enemyTier = "";
      islandState.currentHp = 0;
      islandState.maxHp = 0;
      islandStates[island.id] = islandState;
    });
  }

  function getIslandImageUrl(island, islandState = getIslandState(island?.id)) {
    if (!island) return "";
    if (island.id === "final-island" || island.kind === "final") return ISLAND_IMAGE_MAP.final;
    if (island.id === WATER_SEVEN_ISLAND_ID) return ISLAND_IMAGE_MAP.water_seven;
    const islandKind = getEffectiveIslandKind(island, islandState);
    if (islandKind === "yonko") {
      return ISLAND_IMAGE_MAP[island.glyphId] || "";
    }
    return ISLAND_IMAGE_MAP[islandKind] || "";
  }

  function getNearestIslandFromRoute(location) {
    if (!location || location.kind !== "route") return null;
    return location.toIslandId || location.fromIslandId || null;
  }

  function getScoutStartIslandIds(player) {
    if (!player?.location) return [];
    if (player.location.kind === "island") return [player.location.islandId].filter(Boolean);
    if (player.location.kind === "route") {
      return [player.location.fromIslandId, player.location.toIslandId].filter(Boolean);
    }
    return [];
  }

  function getPlayerScoutRange(player) {
    return getTeamEffects(player).scoutRange || 0;
  }

  function isIslandDiscoveredByPlayer(player, islandId) {
    return Array.isArray(player?.discoveredIslands) && player.discoveredIslands.includes(islandId);
  }

  function markIslandDiscovered(player, islandId) {
    if (!player || !islandId) return false;
    if (!Array.isArray(player.discoveredIslands)) player.discoveredIslands = [];
    if (player.discoveredIslands.includes(islandId)) return false;
    player.discoveredIslands.push(islandId);
    return true;
  }

  function isIslandAlwaysVisible(island) {
    if (isPostgameEggheadIsland(island)) return Boolean(state.gameState?.postgameWorld?.eggheadUnlocked);
    if (isPostgameBossIsland(island)) return Boolean(state.gameState?.postgameWorld?.unlocked);
    if (island?.kind === "final") return Boolean(state.gameState?.finalIslandUnlocked);
    if (island?.kind === "elbaph" || island?.finalGateAnchor) return Boolean(state.gameState?.finalIslandUnlocked);
    return ["start", "reverse-mountain", "yonko", "judicial", "impel_down", "marineford"].includes(island?.kind)
      || island?.id === START_ISLAND_ID
      || island?.id === INVERSION_MOUNTAIN_ID
      || island?.id === WATER_SEVEN_ISLAND_ID;
  }

  function getConnectedRoutesForScout(islandId) {
    return state.gameState.boardData.routesBetweenIslands.filter((routeItem) => {
      const attached = routeItem.from === islandId || routeItem.to === islandId;
      if (!attached) return false;
      if (routeItem.meta.requiresFinalUnlocked && !state.gameState.finalIslandUnlocked) return false;
      return true;
    });
  }

  function getScoutVisibleIslandIds(player) {
    const range = getPlayerScoutRange(player);
    if (range <= 0 || !player) return new Set();
    const visible = new Set();

    if (player.location?.kind === "route") {
      getScoutStartIslandIds(player).forEach((islandId) => {
        const island = getIslandById(islandId);
        if (!island) return;
        if (island.kind === "final" && !state.gameState.finalIslandUnlocked) return;
        visible.add(islandId);
      });
      return visible;
    }

    if (player.location?.kind === "island") {
      getConnectedRoutesForScout(player.location.islandId).forEach((routeItem) => {
        const nextIslandId = routeItem.from === player.location.islandId ? routeItem.to : routeItem.from;
        if (!nextIslandId || visible.has(nextIslandId)) return;
        const nextIsland = getIslandById(nextIslandId);
        if (!nextIsland) return;
        if (nextIsland.kind === "final" && !state.gameState.finalIslandUnlocked) return;
        visible.add(nextIslandId);
      });
    }

    return visible;
  }

  function isIslandWithinScoutRange(player, islandId) {
    return getScoutVisibleIslandIds(player).has(islandId);
  }

  function getScoutEncounterTileIds(player) {
    const canScoutEncounters = (getTeamEffects(player).seaEncounterScoutRange || 0) > 0;
    const visible = new Set();
    if (!player || !canScoutEncounters) return visible;

    const addEncounterTilesOnRoute = (routeItem) => {
      (routeItem?.tiles || []).forEach((tileItem, index) => {
        const tile = getTileByLocation(routeItem.id, index);
        if (tile?.primaryTypeId === "encounter") visible.add(tile.id);
      });
    };

    if (player.location?.kind === "island") {
      getConnectedRoutesForScout(player.location.islandId).forEach((routeItem) => {
        addEncounterTilesOnRoute(routeItem);
      });
      return visible;
    }

    if (player.location?.kind === "route") {
      const routeItem = getRouteById(player.location.routeId);
      if (!routeItem) return visible;
      addEncounterTilesOnRoute(routeItem);
    }

    return visible;
  }

  function isIslandVisibleToPlayer(player, island) {
    if (!player || !island) return false;
    if (isIslandAlwaysVisible(island)) return true;
    if (isIslandDiscoveredByPlayer(player, island.id)) return true;
    if (isIslandWithinScoutRange(player, island.id)) return true;
    return false;
  }

  function effectiveIslandDisplayName(island, kind = getEffectiveIslandKind(island, getIslandState(island?.id))) {
    const baseName = String(island?.name || "未知島嶼");
    if (kind !== "arena") return baseName;
    if (/酒館|酒吧|酒場/.test(baseName)) return baseName.replace(/酒館|酒吧|酒場/g, "競技場");
    return `${baseName}競技場`;
  }

  function getVisibleIslandView(player, island) {
    const islandState = getIslandState(island?.id);
    if (isPostgameEggheadIsland(island)) {
      return {
        ...island,
        displayName: island.name,
        displayKind: "postgame_egghead",
        displayBrief: "約克的移動研究據點・洛克斯終戰",
        displayHint: "擊敗後必須先離島，再重新登島才能再次挑戰。",
        imageUrl: ISLAND_IMAGE_MAP.postgame_egghead,
        imageFallback: ISLAND_IMAGE_MAP.research_lab,
        bossRevealed: true,
        hidden: false,
      };
    }
    if (isPostgameBossIsland(island)) {
      const assignment = postgameBossAssignment(island);
      const discovered = isIslandDiscoveredByPlayer(player, island.id);
      return {
        ...island,
        displayName: island.name,
        displayKind: "postgame_boss",
        displayBrief: discovered && assignment?.boss
          ? `駐守 Boss：${assignment.boss.name}`
          : "無風帶消失後顯現的未知孤島",
        displayHint: discovered && assignment?.boss
          ? `${assignment.boss.name} 的專屬島嶼已永久記錄在你的海圖。`
          : "第一次登島後才會揭露 Boss 身分與專屬島貌。",
        imageUrl: discovered && assignment?.boss?.islandImage
          ? assignment.boss.islandImage
          : ISLAND_IMAGE_MAP.postgame_boss,
        imageFallback: ISLAND_IMAGE_MAP.postgame_boss,
        bossRevealed: discovered,
        hidden: false,
      };
    }
    const visible = isIslandVisibleToPlayer(player, island);
    if (!visible) {
      return {
        ...island,
        displayName: "未知島嶼",
        displayKind: "unknown",
        displayBrief: "???",
        displayHint: "需要偵查型夥伴或親自抵達後才會揭露",
        imageUrl: ISLAND_IMAGE_MAP.unknown,
        hidden: true,
      };
    }
    const effectiveKind = getEffectiveIslandKind(island, islandState);
    return {
      ...island,
      displayName: effectiveIslandDisplayName(island, effectiveKind),
      displayKind: effectiveKind,
      displayBrief: island.brief,
      displayHint: island.hint,
      imageUrl: getIslandImageUrl(island, islandState),
      hidden: false,
    };
  }

  function canRevealEnemyIslandInfo(player = currentPlayer(), island = null) {
    if (!island || island.kind !== "enemy") return true;
    if (!getTeamEffects(player).enemyInfoEnemyIsland) return false;
    const isCurrentIsland = player?.location?.kind === "island"
      && String(player.location.islandId || "") === String(island.id || "");
    return isCurrentIsland || isIslandWithinScoutRange(player, island.id);
  }

  function enemyIslandShadowText() {
    return "島上有敵影活動";
  }

  function getSeaCardBackImage(typeId) {
    return SEA_CARD_BACK_IMAGE_MAP[typeId] || SEA_CARD_BACK_IMAGE_MAP.unknown;
  }

  function isReverseMountainEntranceIsland(islandId) {
    const numericId = Number(String(islandId || "").replace("island-", ""));
    return MAP_TEMPLATE.reverseMountainEntrances.includes(numericId);
  }

  function buildIslandVisual(island, islandState, _label, title, _meta, imageSrc = null, fallbackSrc = "") {
    const finalImageSrc = imageSrc || getIslandImageUrl(island, islandState);
    if (!finalImageSrc) {
      return `<div class="island-generic-mark" aria-label="${escapeModalText(title)}"><img src="${ISLAND_IMAGE_MAP.unknown}" alt=""></div>`;
    }
    const islandKind = finalImageSrc === ISLAND_IMAGE_MAP.unknown ? "unknown" : getEffectiveIslandKind(island, islandState);
    return `
      <div class="island-visual image-mode kind-${islandKind}">
        <div class="island-visual-art kind-${islandKind}">
          <div class="island-visual-glow"></div>
          <img
            class="island-visual-img"
            src="${finalImageSrc}"
            alt="${title}"
            loading="eager"
            decoding="async"
            draggable="false"
            ${fallbackSrc ? `data-fallback-src="${escapeModalText(fallbackSrc)}"` : ""}
            onerror="if(this.dataset.fallbackSrc && this.src.indexOf(this.dataset.fallbackSrc) === -1){this.src=this.dataset.fallbackSrc;this.dataset.fallbackSrc='';}else{this.closest('.island-visual-art').classList.add('is-fallback');this.remove();}"
          >
          <div class="island-visual-fallback">${title}</div>
        </div>
      </div>
    `;
  }

  function buildElbaphIslandVisual(title, meta, imageSrc = "") {
    return `
      <div class="elbaph-island-visual${imageSrc ? " has-image" : ""}" aria-label="${escapeModalText(title)}">
        ${imageSrc ? `
          <div class="elbaph-island-art">
            <img src="${escapeModalText(imageSrc)}" alt="${escapeModalText(title)}" loading="eager" decoding="async" draggable="false" onerror="this.closest('.elbaph-island-visual')?.classList.remove('has-image'); this.closest('.elbaph-island-art')?.remove();">
          </div>
        ` : `
          <div class="elbaph-island-emblem"><img src="images/board/attribute_icons/neutral.webp" alt=""></div>
          <strong>${escapeModalText(title)}</strong>
          <small>${escapeModalText(meta || "通往最終之島前的巨人國")}</small>
        `}
      </div>
    `;
  }

  function getRouteById(id) {
    return state.gameState.boardData.routesBetweenIslands.find((item) => item.id === id) || null;
  }

  function getTileByLocation(routeId, index) {
    return state.gameState.boardData.seaTiles.find((tile) => tile.routeId === routeId && tile.index === index) || null;
  }

  function oppositeDirection(direction) {
    const table = {
      north: "south",
      south: "north",
      east: "west",
      west: "east",
      special: "special",
    };
    return table[direction] || direction;
  }

  function directionLabel(direction) {
    const table = {
      north: "北",
      south: "南",
      east: "東",
      west: "西",
      special: "主航線",
    };
    return table[direction] || direction;
  }

  function coordToPx(col, row) {
    return {
      x: BOARD_OFFSET_X + col * TILE_SIZE,
      y: BOARD_OFFSET_Y + row * TILE_SIZE,
    };
  }

  function nodeToPx(nodeOrCol, row) {
    if (typeof nodeOrCol === "object" && nodeOrCol) {
      if (Number.isFinite(nodeOrCol.pxX) && Number.isFinite(nodeOrCol.pxY)) {
        return { x: nodeOrCol.pxX, y: nodeOrCol.pxY };
      }
      if (Number.isFinite(nodeOrCol.col) && Number.isFinite(nodeOrCol.row)) {
        return coordToPx(nodeOrCol.col, nodeOrCol.row);
      }
    }
    return coordToPx(nodeOrCol, row);
  }

  function connections() {
    const out = [];
    state.gameState.boardData.routesBetweenIslands.forEach((routeItem) => {
      if (shouldHideRouteOnMap(routeItem)) return;
      const from = getIslandById(routeItem.from);
      const to = getIslandById(routeItem.to);
      const points = [nodeToPx(from), ...routeItem.tiles.map((tileItem) => nodeToPx(tileItem)), nodeToPx(to)];
      for (let i = 0; i < points.length - 1; i += 1) {
        out.push({
          a: points[i],
          b: points[i + 1],
          routeId: routeItem.id,
          routeSegmentIndex: i,
          postgameRoute: Boolean(routeItem.meta?.postgameRoute),
          postgameOrder: Math.max(0, Number(routeItem.meta?.postgameOrder || 0)),
        });
      }
    });
    return out;
  }

  function renderReverseMountainBackdrop() {
    return;
  }

  function playerPositionPx(player) {
    if (player.location.kind === "island") {
      const island = getIslandById(player.location.islandId);
      return nodeToPx(island);
    }
    const tile = getTileByLocation(player.location.routeId, player.location.tileIndex);
    return nodeToPx(tile);
  }

  function playerShipIndex(player) {
    const index = state.gameState.players.findIndex((entry) => entry.id === player?.id);
    return index >= 0 ? index : 0;
  }

  function shipTokenOffset(index) {
    const offsets = [
      { x: -22, y: -22 },
      { x: 22, y: -22 },
      { x: -22, y: 22 },
      { x: 22, y: 22 },
    ];
    return offsets[Math.max(0, index) % offsets.length];
  }

  function playerShipTokenPositionPx(player, basePosition = playerPositionPx(player)) {
    const offset = shipTokenOffset(playerShipIndex(player));
    return {
      x: basePosition.x + offset.x,
      y: basePosition.y + offset.y,
    };
  }

  function mapMovementStepDelay(player) {
    // Fast-forward only compresses the visual wait; pendingMove still resolves one step at a time.
    return cpuTurnDelay(MAP_MOVEMENT_STEP_MS, player, MAP_MOVEMENT_FAST_STEP_MS);
  }

  function traversalFromIsland(routeItem, islandId) {
    if (routeItem.from === islandId) {
      return {
        routeId: routeItem.id,
        fromIslandId: routeItem.from,
        toIslandId: routeItem.to,
        tiles: routeItem.tiles.map((tileItem, idx) => ({ ...tileItem, index: idx })),
        exitDirection: routeItem.directions?.from || "east",
        entryDirectionAtDestination: routeItem.directions?.to || "west",
      };
    }
    return {
      routeId: routeItem.id,
      fromIslandId: routeItem.to,
      toIslandId: routeItem.from,
      tiles: routeItem.tiles.map((tileItem, idx) => ({ ...tileItem, index: idx })).reverse(),
      exitDirection: routeItem.directions?.to || "west",
      entryDirectionAtDestination: routeItem.directions?.from || "east",
    };
  }

  function routeDirectionFromIsland(routeItem, islandId) {
    if (!routeItem) return "";
    if (routeItem.from === islandId) return routeItem.directions?.from || "east";
    if (routeItem.to === islandId) return routeItem.directions?.to || "west";
    return "";
  }

  function normalizeForcedReturnRoute(value) {
    if (!value || typeof value !== "object") return null;
    const islandId = String(value.islandId || "");
    if (!islandId) return null;
    return {
      islandId,
      routeId: value.routeId ? String(value.routeId) : "",
      direction: value.direction ? String(value.direction) : "",
      reason: value.reason ? String(value.reason) : "escape",
    };
  }

  function forcedReturnRoutesForPlayer(player, islandId, routes) {
    const forced = normalizeForcedReturnRoute(player?.forcedReturnRoute);
    if (!forced || forced.islandId !== islandId) return [];
    return (routes || []).filter((routeItem) => {
      if (forced.routeId && routeItem.id === forced.routeId) return true;
      return forced.direction && routeDirectionFromIsland(routeItem, islandId) === forced.direction;
    });
  }

  function isForcedReturnRouteForPlayer(player, islandId, routeItem) {
    return forcedReturnRoutesForPlayer(player, islandId, [routeItem]).length > 0;
  }

  function clearForcedReturnRoute(player) {
    if (player) player.forcedReturnRoute = null;
  }

  function markForcedReturnRoute(player, island, reason = "escape") {
    if (!player || player.location?.kind !== "island") return false;
    const islandId = island?.id || player.location.islandId;
    const direction = player.location.entryDirection || "";
    if (!islandId || !direction) {
      clearForcedReturnRoute(player);
      return false;
    }
    const routeItem = state.gameState.boardData.routesBetweenIslands.find((item) => {
      const attached = item.from === islandId || item.to === islandId;
      return attached && routeDirectionFromIsland(item, islandId) === direction;
    });
    if (!routeItem) {
      clearForcedReturnRoute(player);
      return false;
    }
    player.forcedReturnRoute = { islandId, routeId: routeItem.id, direction, reason };
    return true;
  }

  function getAvailableRoutes(islandId, player = currentPlayer()) {
    const hardAvailableRoutes = state.gameState.boardData.routesBetweenIslands.filter((routeItem) => {
      const attached = routeItem.from === islandId || routeItem.to === islandId;
      if (!attached) return false;
      if (routeItem.meta.requiresFinalUnlocked && !state.gameState.finalIslandUnlocked) return false;
      if (isFinalGateRetreatActive(player, islandId) && isFinalRouteItem(routeItem)) return false;
      if (islandId === INVERSION_MOUNTAIN_ID && routeItem.from === START_ISLAND_ID) return false;
      if (isReverseMountainEntranceIsland(islandId) && (routeItem.from === INVERSION_MOUNTAIN_ID || routeItem.to === INVERSION_MOUNTAIN_ID)) {
        return false;
      }
      if (routeItem.meta.uniqueBranch) {
        const claimedBy = state.gameState.claimedBranchRoutes?.[routeItem.meta.branchId];
        if (islandId === INVERSION_MOUNTAIN_ID && player?.claimedBranchId) {
          return routeItem.meta.branchId === player.claimedBranchId;
        }
        if (claimedBy && claimedBy !== player?.id) return false;
      }
      return true;
    });
    const forcedReturnRoutes = forcedReturnRoutesForPlayer(player, islandId, hardAvailableRoutes);
    if (forcedReturnRoutes.length) {
      return forcedReturnRoutes;
    }
    const entryDirection = player?.location?.kind === "island" && player.location.islandId === islandId
      ? player.location.entryDirection
      : null;
    const currentIsland = getIslandById(islandId);
    const postgameBossIslandsUnlocked = Boolean(state.gameState?.postgameWorld?.unlocked);
    const keepsArrivalRouteOpen = isPostgameBossIsland(currentIsland)
      || (postgameBossIslandsUnlocked && currentIsland?.kind === "yonko");
    if (entryDirection && islandId !== INVERSION_MOUNTAIN_ID && !keepsArrivalRouteOpen) {
      const forwardRoutes = hardAvailableRoutes.filter((routeItem) => {
        const routeDirection = routeDirectionFromIsland(routeItem, islandId);
        return routeDirection !== entryDirection;
      });
      if (forwardRoutes.length) {
        return forwardRoutes;
      }
    }
    return hardAvailableRoutes;
  }

  function cloneCard(card) {
    const catalogCard = characterCatalogCardById(card.id);
    const clonedEvolution = { ...card };
    syncCardEvolutionState(clonedEvolution);
    const expGrowthGroup = expGrowthGroupForCard(card);
    const savedLevel = Math.max(1, Math.min(CHARACTER_MAX_LEVEL, Math.floor(Number(card.level || 1))));
    const savedProgress = Math.max(0, Math.floor(Number(card.exp ?? card.currentExp ?? 0)));
    let totalExp = Number(card.totalExp);
    if (!Number.isFinite(totalExp)) totalExp = expForLevel(savedLevel, expGrowthGroup) + savedProgress;
    totalExp = Math.max(0, Math.min(expForLevel(CHARACTER_MAX_LEVEL, expGrowthGroup), Math.floor(totalExp)));
    const level = cardLevelFromTotalExp(totalExp, expGrowthGroup);
    const currentExp = level >= CHARACTER_MAX_LEVEL ? 0 : Math.max(0, totalExp - expForLevel(level, expGrowthGroup));
    const baseStatsLevel1 = { ...(card.baseStatsLevel1 || catalogCard?.baseStats || card.baseStats || {}) };
    const currentMoveById = new Map((card.moveSet || []).map((entry) => [entry.id, entry]));
    const sourceMoveSet = effectiveCardMoveSet(clonedEvolution, catalogCard);
    const moveSet = applyLineageEndgameBossMovePowers(sourceMoveSet.map((entry) => {
      const savedMove = currentMoveById.get(entry.id);
      const nextMove = { ...JSON.parse(JSON.stringify(entry)) };
      nextMove.currentPP = Number.isFinite(Number(savedMove?.currentPP))
        ? Math.max(0, Math.min(nextMove.pp, Number(savedMove.currentPP)))
        : nextMove.pp;
      return nextMove;
    }), card);
    const eligibleMoveIds = moveSet
      .filter((entry) => effectiveMoveUnlockLevel(entry) <= level)
      .map((entry) => entry.id);
    const existingMoveIds = Array.isArray(card.unlockedMoveIds)
      ? card.unlockedMoveIds.filter((id) => eligibleMoveIds.includes(id))
      : [];
    const activeMoveIds = buildActiveMoveIdsForCard(clonedEvolution, eligibleMoveIds, existingMoveIds);
    const leveledStats = cardStatsForLevel({ ...card, formId: clonedEvolution.formId, baseStatsLevel1, growthRate: card.growthRate }, level);
    const currentHp = Number.isFinite(Number(card.currentHp))
      ? Math.max(0, Math.min(leveledStats.hp, Number(card.currentHp)))
      : leveledStats.hp;
    return {
      ...JSON.parse(JSON.stringify(card)),
      level,
      expGrowthGroup,
      totalExp,
      exp: currentExp,
      currentExp,
      nextLevelExp: expToNextLevel(level, expGrowthGroup),
      formId: clonedEvolution.formId,
      unlockedEvolutionFormIds: clonedEvolution.unlockedEvolutionFormIds,
      evolutionStage: clonedEvolution.evolutionStage,
      currentFormName: clonedEvolution.currentFormName,
      baseStatsLevel1,
      baseStats: leveledStats,
      hp: leveledStats.hp,
      atk: leveledStats.atk,
      def: leveledStats.def,
      satk: leveledStats.satk,
      sdef: leveledStats.sdef,
      spd: leveledStats.spd,
      currentHp,
      currentStages: {
        atk: 0, def: 0, satk: 0, sdef: 0, spd: 0, accuracy: 0, evasion: 0,
      },
      moveSet,
      unlockedMoveIds: activeMoveIds,
      battleCarryItem: normalizeBattleCarryItem(card.battleCarryItem),
    };
  }

  function cloneFreshDraftRecruit(card) {
    const recruit = cloneCard(card);
    syncCrewCardProgress(recruit);
    recruit.currentHp = Math.max(1, Number(recruit.baseStats?.hp || recruit.hp || 1));
    return recruit;
  }

  function normalizeExpGrowthGroup(group) {
    const value = String(group || "").trim();
    if (["fastest", "fast", "medium_fast", "medium", "medium_slow", "slow", "slowest"].includes(value)) return value;
    return DEFAULT_EXP_GROWTH_GROUP;
  }

  function expGrowthGroupForCard(card) {
    if (typeof card === "string") return normalizeExpGrowthGroup(card);
    const catalogCard = typeof CHARACTER_CARDS !== "undefined"
      ? characterCatalogCardById(card?.id)
      : null;
    return normalizeExpGrowthGroup(
      card?.expGrowthGroup
      || catalogCard?.expGrowthGroup
      || CARD_EXP_GROWTH_BY_TIER[legacyTier(card?.tier || catalogCard?.tier)]
      || DEFAULT_EXP_GROWTH_GROUP,
    );
  }

  function expForLevel(level, growthGroup = DEFAULT_EXP_GROWTH_GROUP) {
    const lv = Math.max(1, Math.min(100, Math.floor(Number(level || 1))));
    if (lv <= 1) return 0;
    const group = normalizeExpGrowthGroup(growthGroup);
    const cube = Math.pow(lv, 3);
    const fourth = Math.pow(lv, 4);
    let value = 0;
    if (group === "fastest") {
      if (lv <= 50) value = -0.02 * fourth + 2 * cube;
      else if (lv <= 68) value = -0.01 * fourth + 1.5 * cube;
      else if (lv <= 98) value = 0.002 * cube * Math.floor((1911 - 10 * lv) / 3);
      else value = -0.01 * fourth + 1.6 * cube;
    } else if (group === "fast") {
      value = 0.8 * cube;
    } else if (group === "medium_fast" || group === "medium") {
      value = cube;
    } else if (group === "medium_slow") {
      value = 1.2 * cube - 15 * Math.pow(lv, 2) + 100 * lv - 140;
    } else if (group === "slow") {
      value = 1.25 * cube;
    } else if (group === "slowest") {
      if (lv <= 15) value = 0.02 * cube * Math.floor((lv + 73) / 3);
      else if (lv <= 36) value = 0.02 * fourth + 0.28 * cube;
      else value = 0.02 * cube * Math.floor((lv + 64) / 2);
    }
    return Math.max(0, Math.floor(value));
  }

  function expToNextLevel(level, cardOrGroup = DEFAULT_EXP_GROWTH_GROUP) {
    const value = Math.max(1, Math.min(CHARACTER_MAX_LEVEL, Math.floor(Number(level || 1))));
    if (value >= CHARACTER_MAX_LEVEL) return 0;
    const group = expGrowthGroupForCard(cardOrGroup);
    return Math.max(1, expForLevel(value + 1, group) - expForLevel(value, group));
  }

  function boostedMissionExp(mission) {
    const base = Math.max(0, Number(mission?.exp || 0));
    return base > 0 ? Math.max(1, Math.round(base * MISSION_EXP_REWARD_MULTIPLIER)) : 0;
  }

  function crewAverageLevelForExp(player) {
    const cards = (player?.crew || []).filter(Boolean);
    if (!cards.length) return 1;
    return cards.reduce((sum, card) => sum + Number(card.level || 1), 0) / cards.length;
  }

  function earlyGrowthExpMultiplier(averageLevel) {
    const level = Number(averageLevel || 1);
    if (level < 20) return 2.75;
    if (level < 35) return 2.45;
    if (level < 50) return 2.05;
    if (level < 65) return 1.2;
    return 1;
  }

  function applyLowLevelExpCatchup(expAmount, card, averageLevel) {
    let next = Math.max(1, Math.round(Number(expAmount || 0)));
    next = Math.max(1, Math.round(next * earlyGrowthExpMultiplier(averageLevel)));
    const gap = Math.max(0, Number(averageLevel || 1) - Number(card?.level || 1));
    if (gap >= LOW_LEVEL_EXP_CATCHUP_MAJOR_GAP) {
      next = Math.max(1, Math.round(next * (1 + LOW_LEVEL_EXP_CATCHUP_MAJOR_BONUS)));
    } else if (gap >= LOW_LEVEL_EXP_CATCHUP_MINOR_GAP) {
      next = Math.max(1, Math.round(next * (1 + LOW_LEVEL_EXP_CATCHUP_MINOR_BONUS)));
    }
    return next;
  }

  function cardLevelFromTotalExp(totalExp, growthGroup = DEFAULT_EXP_GROWTH_GROUP) {
    const group = normalizeExpGrowthGroup(growthGroup);
    const exp = Math.max(0, Math.floor(Number(totalExp || 0)));
    let level = 1;
    while (level < CHARACTER_MAX_LEVEL && exp >= expForLevel(level + 1, group)) level += 1;
    return level;
  }

  function syncCardExperienceFields(card) {
    if (!card) return { level: 1, totalExp: 0, currentExp: 0, nextLevelExp: 0, growthGroup: DEFAULT_EXP_GROWTH_GROUP };
    const growthGroup = expGrowthGroupForCard(card);
    const savedLevel = Math.max(1, Math.min(CHARACTER_MAX_LEVEL, Math.floor(Number(card.level || 1))));
    const savedProgress = Math.max(0, Math.floor(Number(card.exp ?? card.currentExp ?? 0)));
    const maxTotalExp = expForLevel(CHARACTER_MAX_LEVEL, growthGroup);
    let totalExp = Number(card.totalExp);
    if (!Number.isFinite(totalExp)) totalExp = expForLevel(savedLevel, growthGroup) + savedProgress;
    totalExp = Math.max(0, Math.min(maxTotalExp, Math.floor(totalExp)));
    const level = cardLevelFromTotalExp(totalExp, growthGroup);
    const levelFloorExp = expForLevel(level, growthGroup);
    const nextLevelExp = expToNextLevel(level, growthGroup);
    const currentExp = level >= CHARACTER_MAX_LEVEL ? 0 : Math.max(0, totalExp - levelFloorExp);
    card.expGrowthGroup = growthGroup;
    card.level = level;
    card.totalExp = totalExp;
    card.exp = currentExp;
    card.currentExp = currentExp;
    card.nextLevelExp = nextLevelExp;
    return { level, totalExp, currentExp, nextLevelExp, growthGroup };
  }

  function effectiveMoveUnlockLevel(moveEntry) {
    const value = Number(moveEntry?.unlockLevel || 1);
    if (!Number.isFinite(value)) return 1;
    return Math.max(1, Math.min(CHARACTER_MAX_LEVEL, Math.floor(value)));
  }

  function activeEvolutionForm(card) {
    const formId = String(card?.formId || card?.evolutionFormId || "base");
    const form = EVOLUTION_FORMS[formId];
    return form && form.characterId === card?.id ? form : null;
  }

  function evolutionFormsForCard(card) {
    return (EVOLUTION_FORMS_BY_CHARACTER[card?.id] || []).slice();
  }

  function syncCardEvolutionState(card) {
    if (!card) return null;
    const savedFormId = String(card.formId || card.evolutionFormId || "base");
    const savedForm = EVOLUTION_FORMS[savedFormId];
    card.formId = savedForm && savedForm.characterId === card.id ? savedForm.id : "base";
    const savedUnlocked = Array.isArray(card.unlockedEvolutionFormIds)
      ? card.unlockedEvolutionFormIds
      : Array.isArray(card.unlockedForms)
        ? card.unlockedForms
        : [];
    const unlocked = savedUnlocked.filter((formId) => EVOLUTION_FORMS[formId]?.characterId === card.id);
    if (card.formId !== "base" && !unlocked.includes(card.formId)) unlocked.push(card.formId);
    card.unlockedEvolutionFormIds = Array.from(new Set(unlocked));
    const activeForm = activeEvolutionForm(card);
    card.evolutionStage = activeForm ? Number(activeForm.stage || 1) : 0;
    card.currentFormName = activeForm?.name || "";
    return activeForm;
  }

  function cardDisplayName(card) {
    const form = activeEvolutionForm(card);
    return form?.displayName || card?.name || "未知角色";
  }

  function cardDraftTraitText(card) {
    if (!card) return "";
    const form = activeEvolutionForm(card);
    const attribute = String(form?.attribute || card.attribute || "").trim();
    const roleType = String(form?.roleType || card.roleType || card.roleLabel || card.role || "").trim();
    return [attribute, roleType].filter(Boolean).join("・");
  }

  function cardPortraitsForDisplay(card) {
    const sourcePortraits = activeEvolutionForm(card)?.battlePortraits
      || card?.battlePortraits
      || battleCharacterPortraitsFor(card?.id || "unknown");
    const portraits = sourcePortraits && typeof sourcePortraits === "object" ? sourcePortraits : {};
    return {
      ...portraits,
      idle: portraits?.idle || PLACEHOLDER_BATTLE_PORTRAIT,
      fallback: portraits?.fallback || PLACEHOLDER_BATTLE_PORTRAIT,
      placeholder: portraits?.placeholder || PLACEHOLDER_BATTLE_PORTRAIT,
    };
  }

  const SANJI_RAID_SUIT_ITEM_ID = "judge_germa66_battle_suit";
  const SANJI_RAID_SUIT_FORM_ID = "sanji_evolution_2";
  const ENMA_ITEM_ID = "enma";
  const ZORO_NEW_WORLD_FORM_ID = "zoro_evolution_2";
  const ZORO_ZOROJURO_FORM_ID = "zoro_zorojuro";
  const ENMA_TRIAL_CINEMATIC_KIND = "enma_trial";
  const ENMA_TRIAL_CINEMATIC_ROOT = "images/board/battle/cinematics/enma_trial_v1";
  const ENMA_TRIAL_CINEMATIC_FRAMES = Object.freeze([
    Object.freeze({
      src: `${ENMA_TRIAL_CINEMATIC_ROOT}/frame_01.webp`,
      state: "ready",
      speaker: "新世界索隆",
      text: "來測試這把新刀如何。",
      durationMs: 3000,
    }),
    Object.freeze({
      src: `${ENMA_TRIAL_CINEMATIC_ROOT}/frame_02.webp`,
      state: "drain-start",
      speaker: "新世界索隆",
      text: "……！這把刀在吸走我的霸氣。",
      durationMs: 3000,
    }),
    Object.freeze({
      src: `${ENMA_TRIAL_CINEMATIC_ROOT}/frame_03.webp`,
      state: "drained",
      speaker: "新世界索隆",
      text: "可惡……！",
      durationMs: 2400,
    }),
    Object.freeze({
      src: `${ENMA_TRIAL_CINEMATIC_ROOT}/frame_04.webp`,
      state: "reclaim",
      speaker: "新世界索隆",
      text: "給我還回來！",
      durationMs: 2400,
    }),
    Object.freeze({
      src: `${ENMA_TRIAL_CINEMATIC_ROOT}/frame_05.webp`,
      state: "mastered",
      speaker: "新世界索隆",
      text: "閻魔嗎……等我習慣它，就能變得更強吧。",
      durationMs: 3800,
    }),
    Object.freeze({
      src: `${ENMA_TRIAL_CINEMATIC_ROOT}/frame_06.webp`,
      state: "vow",
      speaker: "新世界索隆",
      text: "你也想測試我嗎？我會贏下這場戰鬥，證明給你看的。",
      durationMs: 4200,
    }),
  ]);
  const SANJI_RAID_SUIT_PORTRAIT_ROOT = "images/board/battle/portraits/evolutions/sanji_stealth_black";
  const SANJI_RAID_SUIT_PORTRAITS = Object.freeze({
    normal: `${SANJI_RAID_SUIT_PORTRAIT_ROOT}/normal.webp`,
    stealth: `${SANJI_RAID_SUIT_PORTRAIT_ROOT}/stealth.webp`,
    angry: `${SANJI_RAID_SUIT_PORTRAIT_ROOT}/angry.webp`,
    hit: `${SANJI_RAID_SUIT_PORTRAIT_ROOT}/hit.webp`,
    hitPlayerSide: `${SANJI_RAID_SUIT_PORTRAIT_ROOT}/hit.webp`,
    hitEnemySide: `${SANJI_RAID_SUIT_PORTRAIT_ROOT}/hit_enemy.webp`,
    morale: `${SANJI_RAID_SUIT_PORTRAIT_ROOT}/morale.webp`,
    weak: `${SANJI_RAID_SUIT_PORTRAIT_ROOT}/weak.webp`,
    dizzy: `${SANJI_RAID_SUIT_PORTRAIT_ROOT}/dizzy.webp`,
    attack: `${SANJI_RAID_SUIT_PORTRAIT_ROOT}/angry.webp`,
    hurt: `${SANJI_RAID_SUIT_PORTRAIT_ROOT}/hit.webp`,
    idle: `${SANJI_RAID_SUIT_PORTRAIT_ROOT}/normal.webp`,
    fallback: PLACEHOLDER_BATTLE_PORTRAIT,
    placeholder: PLACEHOLDER_BATTLE_PORTRAIT,
  });
  const SANJI_RAID_SUIT_PASSIVE = Object.freeze({
    name: "隱形黑・光學迷彩",
    text: "防禦+30%、意志+25%、速度+35%；不額外提高攻擊與戰術。速度高於敵人時傷害+15%（招式另有同條件增傷時取較高者），進場與隱形技能會啟動光學迷彩，使下一次敵方直接攻擊必定落空。",
    statMultiplier: { def: 1.3, sdef: 1.25, spd: 1.35 },
    damageDealt: [{ ifFaster: true, bonus: 0.15, stackMode: "max-faster-bonus" }],
  });
  const SANJI_RAID_SUIT_MOVE_OVERRIDES = Object.freeze({
    sanji_sky_walk: {
      name: "隱形・消失",
      category: "buff",
      type: "buff",
      power: 0,
      effectText: "啟動光學迷彩；自身速度+2、閃避+2，下回合先手",
      effects: { selfStages: { spd: 2, evasion: 2 }, guaranteedFirstNextTurn: true, sanjiRaidSuitStealth: true },
    },
    sanji_bien_cuit_grill_shot: {
      name: "隱形黑・流星蕎麥麵",
      category: "attack",
      type: "attack",
      power: 150,
      priority: 2,
      effectText: "先制+2；速度高於敵人時傷害+25%，骰到5以上灼傷",
      effects: { strongerIfFaster: 0.25, statusOnHighDice: { burn: 2 } },
    },
    sanji_poele_a_frire_spectrum: {
      name: "隱形黑・急襲連踢",
      category: "attack",
      type: "attack",
      power: 64,
      effectText: "骰子點數決定連擊段數；命中後敵方防禦、速度-1",
      effects: { multiHit: 1, comboAtkRatio: 0.085, enemyStagesOnHit: { def: -1, spd: -1 } },
    },
    sanji_hell_memories: {
      name: "戰鬥服・地獄回憶",
      category: "special",
      type: "special",
      power: 180,
      effectText: "無視15%防禦；對強敵傷害+25%，骰到5以上灼傷",
      effects: { ignoreDefenseRatio: 0.15, bossDamageBonus: 0.25, statusOnHighDice: { burn: 2 } },
    },
    sanji_blue_walk: {
      name: "隱形黑・空中加速",
      category: "buff",
      type: "buff",
      power: 0,
      effectText: "重新啟動光學迷彩；速度+3、攻擊+1，解除速度下降",
      effects: { selfStages: { spd: 3, atk: 1 }, cleanseSelfStatDown: ["spd"], sanjiRaidSuitStealth: true },
    },
    sanji_mouton_shot_nw: {
      name: "隱形黑・魔神風腳",
      category: "special",
      type: "special",
      power: 196,
      priority: 2,
      effectText: "先制+2；速度高於敵人時傷害+30%，骰到5以上貫穿護盾",
      effects: { strongerIfFaster: 0.3, pierceShieldOnHighDice: true },
    },
  });

  function sanjiRaidSuitCrewKey(card, index = 0) {
    return `${String(card?.instanceId || card?.id || "sanji")}:${Math.max(0, Number(index || 0))}`;
  }

  function sanjiRaidSuitBattleOwner(card, battle = state.battleState) {
    if (!card || !battle) return { player: null, index: -1 };
    const player = battlePlayer(null, battle);
    const index = (player?.crew || []).findIndex((entry) => entry === card);
    return { player, index };
  }

  function sanjiRaidSuitPlayerState(player, battle = state.battleState, create = false) {
    if (!player || !battle) return null;
    const playerId = String(player.id || battle.playerId || "player");
    if (!battle.sanjiRaidSuitState && create) battle.sanjiRaidSuitState = { version: 1, players: {} };
    const root = battle.sanjiRaidSuitState;
    if (!root) return null;
    root.version = Math.max(1, Number(root.version || 1));
    root.players = root.players && typeof root.players === "object" ? root.players : {};
    if (!root.players[playerId] && create) root.players[playerId] = { forms: {} };
    const entry = root.players[playerId] || null;
    if (entry) entry.forms = entry.forms && typeof entry.forms === "object" ? entry.forms : {};
    return entry;
  }

  function sanjiRaidSuitEligible(card, battle = state.battleState, index = -1) {
    if (!card || card.id !== "sanji" || activeEvolutionForm(card)?.id !== SANJI_RAID_SUIT_FORM_ID) return false;
    if (!cardHasBattleCarryItem(card, SANJI_RAID_SUIT_ITEM_ID)) return false;
    if (battle && index >= 0 && postgameBulletCarryIsAbsorbed(battle, card, index)) return false;
    return true;
  }

  function sanjiRaidSuitFormState(card, player = null, battle = state.battleState, index = -1, create = false) {
    if (!card || !battle) return null;
    const owner = player || sanjiRaidSuitBattleOwner(card, battle).player;
    const crewIndex = index >= 0 ? Number(index) : sanjiRaidSuitBattleOwner(card, battle).index;
    if (!owner || crewIndex < 0) return null;
    const playerState = sanjiRaidSuitPlayerState(owner, battle, create);
    if (!playerState) return null;
    const key = sanjiRaidSuitCrewKey(card, crewIndex);
    if (!playerState.forms[key] && create) playerState.forms[key] = { transformed: false, stealthReady: false };
    return playerState.forms[key] || null;
  }

  function sanjiRaidSuitTransformed(card, player = null, battle = state.battleState, index = -1) {
    return !!sanjiRaidSuitFormState(card, player, battle, index, false)?.transformed;
  }

  function sanjiRaidSuitDisplayName(card, player = null, battle = state.battleState, index = -1) {
    return sanjiRaidSuitTransformed(card, player, battle, index) ? "新世界香吉士・隱形黑" : cardDisplayName(card);
  }

  function sanjiRaidSuitPortraits(card, player = null, battle = state.battleState, index = -1) {
    if (!sanjiRaidSuitTransformed(card, player, battle, index)) {
      return activeEvolutionForm(card)?.battlePortraits || card?.battlePortraits || null;
    }
    return SANJI_RAID_SUIT_PORTRAITS;
  }

  function sanjiRaidSuitTransformEventKey(card, player = null, index = -1) {
    return `sanji-raid-suit:${String(player?.id || "player")}:${sanjiRaidSuitCrewKey(card, index)}`;
  }

  function sanjiRaidSuitTransformationDisplayPending(card, player = null, battle = state.battleState, index = -1) {
    if (!card || !battle || !sanjiRaidSuitTransformed(card, player, battle, index)) return false;
    const eventKey = sanjiRaidSuitTransformEventKey(card, player, index);
    const isMatchingTransform = (event) => event?.type === "sanji-raid-suit-transform" && event?.key === eventKey;
    if (isMatchingTransform(battle.visualEvent)) return true;
    return Array.isArray(battle.openingPassiveVisualQueue) && battle.openingPassiveVisualQueue.some(isMatchingTransform);
  }

  function sanjiRaidSuitDisplayedTransformed(card, player = null, battle = state.battleState, index = -1) {
    return sanjiRaidSuitTransformed(card, player, battle, index)
      && !sanjiRaidSuitTransformationDisplayPending(card, player, battle, index);
  }

  function sanjiRaidSuitBattleViewName(card, player = null, battle = state.battleState, index = -1) {
    return sanjiRaidSuitDisplayedTransformed(card, player, battle, index) ? "新世界香吉士・隱形黑" : cardDisplayName(card);
  }

  function sanjiRaidSuitBattleViewPortraits(card, player = null, battle = state.battleState, index = -1) {
    if (!sanjiRaidSuitDisplayedTransformed(card, player, battle, index)) {
      return activeEvolutionForm(card)?.battlePortraits || card?.battlePortraits || null;
    }
    return sanjiRaidSuitPortraits(card, player, battle, index);
  }

  function sanjiRaidSuitMoveEntry(card, sourceMove, player = null, battle = state.battleState, index = -1) {
    const override = SANJI_RAID_SUIT_MOVE_OVERRIDES[sourceMove?.id];
    if (!override || !sanjiRaidSuitTransformed(card, player, battle, index)) return sourceMove;
    const projected = {
      ...sourceMove,
      ...override,
      effects: safeJsonClone(override.effects || {}),
      pp: Number(sourceMove.pp || 0),
    };
    Object.defineProperty(projected, "currentPP", {
      enumerable: true,
      configurable: true,
      get: () => Number(sourceMove.currentPP ?? sourceMove.pp ?? 0),
      set: (value) => {
        sourceMove.currentPP = Math.max(0, Math.min(Number(sourceMove.pp || 0), Number(value || 0)));
      },
    });
    return projected;
  }

  function createSanjiRaidSuitTransformEvent(player, battle, card, index, options = {}) {
    const basePortraits = activeEvolutionForm(card)?.battlePortraits || card?.battlePortraits || {};
    return {
      id: `sanji-raid-suit-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      key: sanjiRaidSuitTransformEventKey(card, player, index),
      type: "sanji-raid-suit-transform",
      side: "player",
      playerId: String(player?.id || "player"),
      crewKey: sanjiRaidSuitCrewKey(card, index),
      crewIndex: Number(index),
      actorName: "新世界香吉士",
      finalName: "隱形黑・Stealth Black",
      title: "戰鬥服變身",
      effectText: "光學迷彩啟動・戰鬥能力全面提升",
      targetSide: "player",
      moveType: "buff",
      itemImage: battleCarryItemImage(SANJI_RAID_SUIT_ITEM_ID),
      beforePortrait: basePortraits.normal || basePortraits.idle || PLACEHOLDER_BATTLE_PORTRAIT,
      finalPortrait: SANJI_RAID_SUIT_PORTRAITS.normal,
      fromName: options.fromName || "",
      toName: "新世界香吉士・隱形黑",
      reason: options.reason || "transform",
      duration: Math.max(4200, Number(options.duration || 5000)),
    };
  }

  function ensureSanjiRaidSuitTransformation(player, battle = state.battleState, index = -1, options = {}) {
    const crewIndex = index >= 0 ? Number(index) : Number(battle?.activeCrewIndex ?? player?.activeCrewIndex ?? 0);
    const card = player?.crew?.[crewIndex];
    if (!sanjiRaidSuitEligible(card, battle, crewIndex)) return null;
    const formState = sanjiRaidSuitFormState(card, player, battle, crewIndex, true);
    if (!formState || formState.transformed) return null;
    formState.transformed = true;
    formState.stealthReady = true;
    const event = createSanjiRaidSuitTransformEvent(player, battle, card, crewIndex, options);
    battle.log ||= [];
    battle.log.push("新世界香吉士開啟傑爾馬66戰鬥服，變身為隱形黑；光學迷彩已啟動。");
    if (options.queueOpening) {
      battle.openingPassiveVisualQueue = Array.isArray(battle.openingPassiveVisualQueue) ? battle.openingPassiveVisualQueue : [];
      battle.openingPassiveVisualQueue.unshift(event);
    }
    return event;
  }

  function applyEvolutionStatModifiers(stats, form) {
    if (!form) return stats;
    const multipliers = form.statMultiplier || form.statModifiers || {};
    const flat = form.statBonus || {};
    return Object.fromEntries(["hp", "atk", "def", "satk", "sdef", "spd"].map((stat) => {
      const baseValue = Number(stats?.[stat] || 1);
      const multiplier = Number(multipliers[stat] || 1);
      const bonus = Number(flat[stat] || 0);
      return [stat, Math.max(1, Math.round(baseValue * multiplier + bonus))];
    }));
  }

  function normalizeCardTraining(card) {
    if (!card) return {};
    const raw = card.training && typeof card.training === "object" && !Array.isArray(card.training) ? card.training : {};
    const next = {};
    TRAINING_STATS.forEach((stat) => {
      const value = Math.max(0, Math.min(TRAINING_MAX_PER_STAT, Math.floor(Number(raw[stat] || 0))));
      next[stat] = value;
    });
    card.training = next;
    card.passiveMemoryLevel = Math.max(0, Math.min(3, Math.floor(Number(card.passiveMemoryLevel || 0))));
    delete card.hiddenPassiveUnlocked;
    return next;
  }

  function cardTrainingBonus(card) {
    const training = normalizeCardTraining(card);
    const bonus = {};
    TRAINING_STATS.forEach((stat) => {
      bonus[stat] = Math.max(0, Math.round(Number(training[stat] || 0) * Number(TRAINING_STAT_BONUS[stat] || 1)));
    });
    const memoryBonus = cardMemoryStatBonus(card);
    TRAINING_STATS.forEach((stat) => {
      bonus[stat] = Number(bonus[stat] || 0) + Number(memoryBonus[stat] || 0);
    });
    return bonus;
  }

  function emptyStatBonusMap() {
    return Object.fromEntries(TRAINING_STATS.map((stat) => [stat, 0]));
  }

  function trainingOnlyStatBonus(card) {
    const training = normalizeCardTraining(card);
    const bonus = emptyStatBonusMap();
    TRAINING_STATS.forEach((stat) => {
      bonus[stat] = Math.max(0, Math.round(Number(training[stat] || 0) * Number(TRAINING_STAT_BONUS[stat] || 1)));
    });
    return bonus;
  }

  function cardMemoryStatBonus(card) {
    const bonus = emptyStatBonusMap();
    const passiveLevel = Math.max(0, Math.floor(Number(card?.passiveMemoryLevel || 0)));
    if (passiveLevel > 0) {
      const role = card?.roleType || "";
      if (role === "戰鬥型") {
        bonus.atk = (bonus.atk || 0) + passiveLevel * 2;
        bonus.hp = (bonus.hp || 0) + passiveLevel * 3;
      } else if (role === "偵查型") {
        bonus.satk = (bonus.satk || 0) + passiveLevel * 2;
        bonus.spd = (bonus.spd || 0) + passiveLevel;
      } else if (role === "移動型") {
        bonus.spd = (bonus.spd || 0) + passiveLevel * 2;
        bonus.atk = (bonus.atk || 0) + passiveLevel;
      } else if (role === "輔助型") {
        bonus.sdef = (bonus.sdef || 0) + passiveLevel * 2;
        bonus.def = (bonus.def || 0) + passiveLevel;
      } else if (isDedicatedLineageCultivationCard(card)) {
        const attribute = String(card?.attribute || "");
        if (attribute === "力") {
          bonus.atk = (bonus.atk || 0) + passiveLevel * 2;
          bonus.hp = (bonus.hp || 0) + passiveLevel * 3;
        } else if (attribute === "技") {
          bonus.satk = (bonus.satk || 0) + passiveLevel * 2;
          bonus.spd = (bonus.spd || 0) + passiveLevel;
        } else if (attribute === "速") {
          bonus.spd = (bonus.spd || 0) + passiveLevel * 2;
          bonus.atk = (bonus.atk || 0) + passiveLevel;
        }
      }
    }
    return bonus;
  }

  function cardProgressBonusBreakdown(card) {
    const training = trainingOnlyStatBonus(card);
    const memory = cardMemoryStatBonus(card);
    const total = emptyStatBonusMap();
    TRAINING_STATS.forEach((stat) => {
      total[stat] = Number(training[stat] || 0) + Number(memory[stat] || 0);
    });
    return { training, memory, total };
  }

  function statBreakdownText(card, stat, currentValue) {
    const breakdown = cardProgressBonusBreakdown(card);
    const total = Number(breakdown.total[stat] || 0);
    const value = Math.max(1, Math.round(Number(currentValue || 1)));
    if (total <= 0) return String(value);
    const parts = [
      Number(breakdown.training[stat] || 0) > 0 ? `修行+${breakdown.training[stat]}` : "",
      Number(breakdown.memory[stat] || 0) > 0 ? `記憶+${breakdown.memory[stat]}` : "",
    ].filter(Boolean);
    const original = Math.max(1, value - total);
    return `${value}（原本${original} +${total}：${parts.join("、")}）`;
  }

  function applyTrainingStatModifiers(stats, card) {
    const bonus = cardTrainingBonus(card);
    return Object.fromEntries(TRAINING_STATS.map((stat) => [
      stat,
      Math.max(1, Math.round(Number(stats?.[stat] || 1) + Number(bonus[stat] || 0))),
    ]));
  }

  function trainingSummary(card) {
    const training = normalizeCardTraining(card);
    const parts = TRAINING_STATS
      .filter((stat) => Number(training[stat] || 0) > 0)
      .map((stat) => `${TRAINING_STAT_LABELS[stat]}+${training[stat]}`);
    const extras = [];
    if (Number(card?.passiveMemoryLevel || 0) > 0) extras.push(`記憶+${card.passiveMemoryLevel}`);
    return [...parts, ...extras].join("、") || "尚未修行";
  }

  function trainingStatBonusText(stat, points = 1) {
    const label = TRAINING_STAT_LABELS[stat] || stat;
    const perPoint = Number(TRAINING_STAT_BONUS[stat] || 1);
    const total = Math.max(0, Math.floor(Number(points || 0))) * perPoint;
    return `${label}修行 +${points} 點，實際${label} +${total}`;
  }

  function trainingRulesText() {
    return `修行不會改角色原始基礎值；會存在角色身上，計算目前能力時額外加成。每項修行最高 ${TRAINING_MAX_PER_STAT} 點。換算：生命每點 HP +${TRAINING_STAT_BONUS.hp}，攻擊/防禦/特攻/特防每點 +${TRAINING_STAT_BONUS.atk}，速度每點 +${TRAINING_STAT_BONUS.spd}。`;
  }

  function trainingItemDetailText(itemDef) {
    const effect = itemDef?.effect || {};
    const points = trainingItemPoints(itemDef);
    if (["training_material", "training_material_small"].includes(effect.kind)) {
      return `${trainingStatBonusText(effect.trainingType, points)}。`;
    }
    if (effect.kind === "training_tier_material") {
      return `給目前最低的修行項目分配 ${points} 點；若最低項滿了，會往下一個未滿項目補。`;
    }
    return "";
  }

  function keyItemDetailText(itemDef) {
    const effect = itemDef?.effect || {};
    const trainingText = trainingItemDetailText(itemDef);
    if (trainingText) return ` 效果：${trainingText} ${trainingRulesText()}`;
    if (effect.kind === "skill_training_material") {
      return ` 效果：選 1 名船員補學已達等級、但目前沒有放進上場技能的招式；若已滿 4 招，會跳出替換選擇。${effect.level === "ultimate" ? "奧義修行卷會優先找高等或奧義招式。" : ""}`;
    }
    if (effect.kind === "switch_unlocked_passive") {
      return " 效果：戰鬥記憶 +1，最高 3；依角色定位給少量能力加成。戰鬥型偏攻擊與 HP，偵查型偏戰術與速度，移動型偏速度，輔助型偏意志與防禦。";
    }
    if (effect.kind === "reset_training_build") {
      return ` 效果：重置該船員全部修行與戰鬥記憶，返還約 ${Math.round(Number(effect.refundRate || 0.6) * 100)}% 修行點為修行細沙。`;
    }
    if (effect.kind === "crew_evolution_material") return " 效果：草帽團角色 Lv.20 後進化用，進化時會消耗。";
    if (effect.kind === "new_world_evolution_material") return " 效果：新世界篇章進化用的重要報紙；進化時會消耗。";
    if (effect.kind === "prime_era_evolution_material") return " 來源：S級任務「舊時代殘響」。效果：舊時代強者返老或全盛期進化用；進化時會消耗。";
    if (effect.kind === "story_unlock_material") return " 效果：劇情與最終航線線索，不會在戰鬥中使用。";
    if (effect.kind === "story_clear_proof") return " 效果：劇情通關證明，不會在戰鬥中使用。";
    return "";
  }

  function trainingDetailRows(card) {
    const training = normalizeCardTraining(card);
    const breakdown = cardProgressBonusBreakdown(card);
    return TRAINING_STATS.map((stat) => {
      const points = Number(training[stat] || 0);
      const parts = [
        `修行+${Number(breakdown.training[stat] || 0)}`,
        Number(breakdown.memory[stat] || 0) > 0 ? `記憶+${breakdown.memory[stat]}` : "",
      ].filter(Boolean);
      const label = String(TRAINING_STAT_LABELS[stat] || stat);
      const ratio = Math.max(0, Math.min(100, Math.round((points / Math.max(1, TRAINING_MAX_PER_STAT)) * 100)));
      return `
        <article class="training-stat-row" data-training-stat="${escapeModalText(stat)}">
          <img class="training-stat-row-frame" src="images/board/training_ui/training_stat_row_frame.webp" alt="" aria-hidden="true">
          <span class="training-stat-badge" title="${escapeModalText(label)}"><img src="${TRAINING_STAT_ICON_BASE}/${escapeModalText(stat)}.webp" alt="${escapeModalText(label)}"></span>
          <div class="training-stat-copy">
            <div class="training-stat-head"><strong>${escapeModalText(label)}</strong><span>${points}/${TRAINING_MAX_PER_STAT} 點</span></div>
            <small>${escapeModalText(parts.join("、") || "尚未修行")}</small>
            <span class="training-stat-progress" aria-hidden="true"><i style="width:${ratio}%"></i></span>
          </div>
          <div class="training-stat-total"><small>實際加成</small><strong>+${Number(breakdown.total[stat] || 0)}</strong></div>
        </article>
      `;
    }).join("");
  }

  function trainingRadarChartMarkup(card, mode = "total") {
    const training = normalizeCardTraining(card);
    const normalizedMode = mode === "training" ? "training" : "total";
    const isTrainingMode = normalizedMode === "training";
    const centerX = 90;
    const centerY = 43;
    const radius = 34;
    const labelRadius = 40;
    const pointAt = (index, scale = 1) => {
      const angle = (-Math.PI / 2) + (index * Math.PI / 3);
      return {
        x: centerX + (Math.cos(angle) * radius * scale),
        y: centerY + (Math.sin(angle) * radius * scale),
      };
    };
    const polygonPoints = (scale) => TRAINING_STATS
      .map((stat, index) => {
        const point = pointAt(index, typeof scale === "function" ? scale(stat) : scale);
        return `${point.x.toFixed(1)},${point.y.toFixed(1)}`;
      })
      .join(" ");
    const values = TRAINING_STATS.map((stat) => isTrainingMode
      ? Math.max(0, Math.min(TRAINING_MAX_PER_STAT, Number(training[stat] || 0)))
      : Math.max(1, Math.round(Number(card?.baseStats?.[stat] || 1))));
    const totalScaleMax = Math.max(1, ...values);
    const ratioForStat = (stat) => {
      const index = TRAINING_STATS.indexOf(stat);
      const value = Number(values[index] || 0);
      const maximum = isTrainingMode ? Math.max(1, TRAINING_MAX_PER_STAT) : totalScaleMax;
      return Math.max(0.04, Math.min(1, value / maximum));
    };
    const modeLabel = isTrainingMode ? "修行數據" : "總數據";
    const nextModeLabel = isTrainingMode ? "總數據" : "修行數據";
    const ariaLabel = `${modeLabel}：${TRAINING_STATS.map((stat, index) => `${TRAINING_STAT_LABELS[stat]} ${values[index]}${isTrainingMode ? " 點" : ""}`).join("、")}。點擊切換為${nextModeLabel}。`;
    const dataPoints = polygonPoints(ratioForStat);
    return `
      <button type="button" class="training-radar-toggle" data-training-radar-toggle data-radar-mode="${normalizedMode}" aria-label="${escapeModalText(ariaLabel)}" aria-pressed="${isTrainingMode ? "true" : "false"}" title="點擊切換為${nextModeLabel}">
      <svg class="training-radar-chart" viewBox="0 0 180 90" aria-hidden="true">
        <g class="training-radar-grid" aria-hidden="true">
          <polygon points="${polygonPoints(1)}"></polygon>
          <polygon points="${polygonPoints(2 / 3)}"></polygon>
          <polygon points="${polygonPoints(1 / 3)}"></polygon>
          ${TRAINING_STATS.map((stat, index) => {
            const point = pointAt(index, 1);
            return `<line x1="${centerX}" y1="${centerY}" x2="${point.x.toFixed(1)}" y2="${point.y.toFixed(1)}"></line>`;
          }).join("")}
        </g>
        <polygon class="training-radar-value" points="${dataPoints}"></polygon>
        <g class="training-radar-points" aria-hidden="true">
          ${TRAINING_STATS.map((stat, index) => {
            const point = pointAt(index, ratioForStat(stat));
            return `<circle cx="${point.x.toFixed(1)}" cy="${point.y.toFixed(1)}" r="1.8"></circle>`;
          }).join("")}
        </g>
        <g class="training-radar-labels">
          ${TRAINING_STATS.map((stat, index) => {
            const angle = (-Math.PI / 2) + (index * Math.PI / 3);
            const x = centerX + (Math.cos(angle) * labelRadius);
            const y = centerY + (Math.sin(angle) * labelRadius);
            const anchor = Math.cos(angle) > 0.2 ? "start" : (Math.cos(angle) < -0.2 ? "end" : "middle");
            return `<text x="${x.toFixed(1)}" y="${y.toFixed(1)}" text-anchor="${anchor}">${escapeModalText(TRAINING_STAT_LABELS[stat])}<tspan> ${values[index]}</tspan></text>`;
          }).join("")}
        </g>
        <text class="training-radar-mode-label" x="${centerX}" y="${centerY + 2}" text-anchor="middle">${modeLabel}</text>
      </svg>
      </button>
    `;
  }

  function effectiveCardMoveSet(card, catalogCard = characterCatalogCardById(card?.id)) {
    const activeForm = activeEvolutionForm(card);
    const moveMap = new Map();
    const addMoves = (moves = []) => {
      (moves || []).forEach((entry) => {
        if (entry?.id && !moveMap.has(entry.id)) moveMap.set(entry.id, safeJsonClone(entry));
      });
    };
    addMoves(catalogCard?.moveSet || card?.moveSet || []);
    if (activeForm) {
      const activeStage = Number(activeForm.stage || card?.evolutionStage || 0);
      evolutionFormsForCard(card)
        .filter((form) => Number(form.stage || 0) > 0 && Number(form.stage || 0) <= activeStage)
        .forEach((form) => {
          addMoves(form.moveSet || []);
          addMoves(form.addMoves || []);
        });
    } else {
      (activeForm?.addMoves || []).forEach((entry) => {
        if (entry?.id) moveMap.set(entry.id, safeJsonClone(entry));
      });
    }
    return Array.from(moveMap.values());
  }

  function formPreferredMoveIds(form, eligibleMoveIds = []) {
    if (!form) return [];
    const eligibleSet = new Set(eligibleMoveIds);
    const preferred = Array.isArray(form.defaultMoveIds) && form.defaultMoveIds.length
      ? form.defaultMoveIds
      : Array.isArray(form.moveSet) && form.moveSet.length
        ? form.moveSet.map((entry) => entry.id)
        : (form.addMoves || []).map((entry) => entry.id);
    return preferred.filter((id) => id && (!eligibleSet.size || eligibleSet.has(id)));
  }

  function buildActiveMoveIdsForCard(card, eligibleMoveIds = [], existingMoveIds = []) {
    const activeForm = activeEvolutionForm(card);
    const formHasMoveSet = Array.isArray(activeForm?.moveSet) && activeForm.moveSet.length;
    const preferredIds = formPreferredMoveIds(activeForm, eligibleMoveIds);
    const existingValidIds = (existingMoveIds || []).filter((id) => eligibleMoveIds.includes(id));
    const seedIds = formHasMoveSet
      ? (existingValidIds.length ? existingValidIds : preferredIds)
      : [...preferredIds, ...(existingValidIds.length ? existingValidIds : eligibleMoveIds)];
    const activeIds = [];
    [...seedIds, ...preferredIds, ...eligibleMoveIds].forEach((id) => {
      if (!id || activeIds.includes(id) || !eligibleMoveIds.includes(id)) return;
      activeIds.push(id);
    });
    return activeIds.slice(0, MAX_ACTIVE_MOVES);
  }

  function firstEvolutionMoveChoiceId(form, eligibleMoveIds = [], existingMoveIds = []) {
    if (!form) return "";
    const eligibleSet = new Set(eligibleMoveIds);
    const existingSet = new Set(existingMoveIds);
    const orderedIds = [];
    const addId = (id) => {
      if (!id || orderedIds.includes(id)) return;
      orderedIds.push(id);
    };
    formPreferredMoveIds(form, eligibleMoveIds).forEach(addId);
    (form.moveSet || []).forEach((entry) => addId(entry.id));
    (form.addMoves || []).forEach((entry) => addId(entry.id));
    return orderedIds.find((id) => eligibleSet.has(id) && !existingSet.has(id)) || "";
  }

  function evolutionMaterialCosts(form) {
    return Array.isArray(form?.materialCost) ? form.materialCost.filter((cost) => cost?.itemId && Number(cost.quantity || 0) > 0) : [];
  }

  function evolutionMaterialText(form) {
    const costs = evolutionMaterialCosts(form);
    if (!costs.length) return "無材料";
    return costs.map((cost) => `${gameItemDef(cost.itemId)?.name || cost.itemId} x${Math.max(1, Math.round(Number(cost.quantity || 1)))}`).join("、");
  }

  function evolutionConsumesMaterials(form) {
    const costs = evolutionMaterialCosts(form);
    if (costs.some((cost) => cost.itemId === "new_world_newspaper_3d2y")) return true;
    return form?.consumeMaterials !== false;
  }

  function nextEvolutionFormForCard(card) {
    const currentStage = Number(activeEvolutionForm(card)?.stage || card?.evolutionStage || 0);
    return evolutionFormsForCard(card).find((form) => Number(form.stage || 1) > currentStage && !form.specialAwakening) || null;
  }

  function evolutionRequirementStatus(player, card, form) {
    if (!card || !form) return { ok: false, reasons: ["尚無可進化形態"] };
    const reasons = [];
    const level = Number(card.level || 1);
    const requiredLevel = Math.max(1, Math.floor(Number(form.requiredLevel || 1)));
    if (level < requiredLevel) reasons.push(`需要 Lv.${requiredLevel}`);
    evolutionMaterialCosts(form).forEach((cost) => {
      const need = Math.max(1, Math.round(Number(cost.quantity || 1)));
      const count = inventoryItemCount(player, cost.itemId);
      if (count < need) reasons.push(`需要 ${gameItemDef(cost.itemId)?.name || cost.itemId} x${need}`);
    });
    return { ok: reasons.length === 0, reasons };
  }

  function evolutionStatusText(player, card) {
    const activeForm = activeEvolutionForm(card);
    const nextForm = nextEvolutionFormForCard(card);
    const forms = evolutionFormsForCard(card);
    if (!forms.length) return "尚無進化";
    if (activeForm?.id === ZORO_NEW_WORLD_FORM_ID) return "特殊進化：攜帶閻魔實際參戰並贏得一場非切磋戰鬥，可永久進化為索隆十郎。";
    if (activeForm && !nextForm) return "已達目前可進化最終階。";
    if (!nextForm) return "尚無進化";
    const status = evolutionRequirementStatus(player, card, nextForm);
    const materialText = evolutionMaterialText(nextForm);
    const action = evolutionConsumesMaterials(nextForm) ? "消耗" : "使用";
    return status.ok
      ? `下一階已可進化，${action} ${materialText}。`
      : `下一階條件：${status.reasons.join("、")}。材料：${materialText}。`;
  }

  function evolutionStageSummaryText(card) {
    const forms = evolutionFormsForCard(card);
    if (!forms.length) return "進化階段：無進化";
    const totalStages = forms.reduce((max, form) => Math.max(max, Math.max(1, Math.floor(Number(form.stage || 1)))), 0);
    const activeForm = activeEvolutionForm(card);
    const activeFormStage = Number(activeForm?.stage || card?.evolutionStage || 0);
    const activeStage = Math.max(0, Math.min(totalStages, Math.floor(activeFormStage)));
    const currentText = activeStage <= 0 ? "未進化" : activeStage >= totalStages ? "已達最終階" : `第 ${activeStage} 階`;
    return `進化階段：${activeStage} / ${totalStages} 階（${currentText}）`;
  }

  function evolutionEffectForCosts(costs) {
    const list = Array.isArray(costs) ? costs : [];
    const direct = list.find((cost) => EVOLUTION_MATERIAL_EFFECTS[cost?.itemId]);
    if (direct) return EVOLUTION_MATERIAL_EFFECTS[direct.itemId];
    return null;
  }

  function hideEvolutionHud() {
    window.clearTimeout(evolutionHudTimer);
    window.clearTimeout(evolutionHudStoryLineTimer);
    window.clearTimeout(evolutionHudLineTimer);
    evolutionHudTimer = null;
    evolutionHudStoryLineTimer = null;
    evolutionHudLineTimer = null;
    if (evolutionHudDismissHandler && refs.evolutionHud) {
      refs.evolutionHud.removeEventListener("click", evolutionHudDismissHandler);
    }
    evolutionHudDismissHandler = null;
    if (!refs.evolutionHud) return;
    refs.evolutionHud.classList.remove("show", "flag", "paper", "prime", "enma", "awaiting");
    refs.evolutionHud.setAttribute("aria-hidden", "true");
  }

  function setEvolutionHudPortrait(img, src, alt, fallbackSrc = "") {
    if (!img) return;
    img.src = src || "";
    img.alt = alt || "";
    img.dataset.fallbackSrc = fallbackSrc && fallbackSrc !== src ? fallbackSrc : "";
    img.hidden = !src;
  }

  function itemRevealIsPending() {
    return Boolean(
      itemRevealActive
      || itemRevealQueue.length
      || itemRevealTimer
      || refs.itemRevealHud?.classList.contains("show")
    );
  }

  function notifyItemRevealIdle() {
    if (itemRevealIsPending()) return;
    const callbacks = itemRevealIdleCallbacks.splice(0);
    callbacks.forEach((callback) => {
      try {
        callback();
      } catch (error) {
        console.error("item reveal idle callback failed", error);
      }
    });
  }

  function waitForItemRevealIdle(callback) {
    if (typeof callback !== "function") return;
    if (!itemRevealIsPending()) {
      window.setTimeout(callback, 0);
      return;
    }
    itemRevealIdleCallbacks.push(callback);
    if (!itemRevealActive && itemRevealQueue.length) window.setTimeout(playNextItemReveal, 0);
  }

  function deferEndTurnUntilItemRevealIdle(options = {}) {
    itemRevealDeferredEndTurnOptions = { ...options, itemRevealWaitComplete: true };
    if (itemRevealDeferredEndTurnWaiting) return;
    itemRevealDeferredEndTurnWaiting = true;
    waitForItemRevealIdle(() => {
      const deferredOptions = itemRevealDeferredEndTurnOptions || { itemRevealWaitComplete: true };
      itemRevealDeferredEndTurnOptions = null;
      itemRevealDeferredEndTurnWaiting = false;
      endTurn(deferredOptions);
    });
  }

  function hideItemRevealHud() {
    window.clearTimeout(itemRevealTimer);
    itemRevealTimer = null;
    if (itemRevealDismissHandler && refs.itemRevealHud) {
      refs.itemRevealHud.removeEventListener("click", itemRevealDismissHandler);
    }
    itemRevealDismissHandler = null;
    itemRevealActive = false;
    if (!refs.itemRevealHud) return;
    refs.itemRevealHud.classList.remove("show", "awaiting");
    refs.itemRevealHud.setAttribute("aria-hidden", "true");
    notifyItemRevealIdle();
  }

  function playNextItemReveal() {
    if (itemRevealActive) return;
    if (!refs.itemRevealHud) {
      itemRevealQueue.length = 0;
      notifyItemRevealIdle();
      return;
    }
    if (!itemRevealQueue.length) {
      notifyItemRevealIdle();
      return;
    }
    const entry = itemRevealQueue.shift();
    const itemDef = gameItemDef(entry?.itemId);
    if (!itemDef) {
      window.setTimeout(playNextItemReveal, 0);
      notifyItemRevealIdle();
      return;
    }
    itemRevealActive = true;
    const image = itemImageForDisplay(itemDef);
    const clueBossDef = itemDef.effect?.kind === "postgame_york_clue"
      ? postgameBossDef(itemDef.effect.bossKey)
      : null;
    const clueReveal = document.getElementById("postgameClueReveal");
    const clueRevealFrame = document.getElementById("postgameClueRevealFrame");
    const clueRevealIsland = document.getElementById("postgameClueRevealIsland");
    const clueRevealRank = document.getElementById("postgameClueRevealRank");
    const clueRevealRankMirror = document.getElementById("postgameClueRevealRankMirror");
    refs.itemRevealHud.className = `item-reveal-hud show ${normalizeGameItemCategory(itemDef.category)}${clueBossDef ? " postgame-clue" : ""}`;
    refs.itemRevealHud.setAttribute("aria-hidden", "false");
    if (refs.itemRevealTitle) refs.itemRevealTitle.textContent = itemDef.revealTitle || "重要道具";
    if (refs.itemRevealName) refs.itemRevealName.textContent = `${itemDef.name}${Number(entry.quantity || 1) > 1 ? ` ×${entry.quantity}` : ""}`;
    if (refs.itemRevealLine) refs.itemRevealLine.textContent = itemDef.revealLine || itemDef.uiSummary || itemDef.description || "新的重要道具已加入背包。";
    if (refs.itemRevealImage) {
      refs.itemRevealImage.src = image;
      refs.itemRevealImage.alt = itemDef.name;
      refs.itemRevealImage.hidden = Boolean(clueBossDef) || !image;
    }
    if (clueReveal) {
      clueReveal.hidden = !clueBossDef;
      if (clueBossDef) {
        if (clueRevealFrame) clueRevealFrame.src = image || "images/board/postgame_clue_ui/york_clue_playing_card_frame_v2.webp";
        if (clueRevealIsland) {
          clueRevealIsland.src = clueBossDef.islandImage || ISLAND_IMAGE_MAP.postgame_boss;
          clueRevealIsland.alt = clueBossDef.name;
        }
        if (clueRevealRank) {
          const clueLabel = postgameClueCardLabel(itemDef.effect.clueNumber || clueBossDef.clueNumber);
          clueRevealRank.textContent = clueLabel;
          clueRevealRank.classList.toggle("double", clueLabel.length > 1);
          if (clueRevealRankMirror) {
            clueRevealRankMirror.textContent = clueLabel;
            clueRevealRankMirror.classList.toggle("double", clueLabel.length > 1);
          }
        }
      }
    }
    itemRevealTimer = window.setTimeout(() => {
      if (!refs.itemRevealHud) return;
      refs.itemRevealHud.classList.add("awaiting");
      itemRevealDismissHandler = (event) => {
        if (event.target?.closest?.("button,a,input,select,textarea")) return;
        hideItemRevealHud();
        window.setTimeout(playNextItemReveal, 120);
      };
      refs.itemRevealHud.addEventListener("click", itemRevealDismissHandler);
    }, 1800);
  }

  function queueImportantItemReveal(itemOrId, quantity = 1) {
    const itemDef = gameItemDef(itemOrId);
    if (!itemDef?.important) return;
    itemRevealQueue.push({ itemId: itemDef.id, quantity: Math.max(1, Math.round(Number(quantity || 1))) });
    window.setTimeout(playNextItemReveal, 0);
  }

  function playEvolutionMaterialEffect({ card, form, costs, materialText, materialAction, beforePortraits, afterPortraits, beforeName, afterName }) {
    const config = evolutionEffectForCosts(costs);
    if (!config || !refs.evolutionHud || !refs.evolutionHudMaterial) return Promise.resolve();
    hideEvolutionHud();
    void refs.evolutionHud.offsetWidth;
    refs.evolutionHud.className = `evolution-hud show ${config.type}`;
    refs.evolutionHud.setAttribute("aria-hidden", "false");
    const basePortraits = beforePortraits || card?.battlePortraits || {};
    const evolvedPortraits = afterPortraits || cardPortraitsForDisplay(card) || {};
    const baseSrc = basePortraits.normal || basePortraits.morale || basePortraits.idle || "";
    const evolvedSrc = evolvedPortraits.normal || evolvedPortraits.morale || evolvedPortraits.idle || "";
    setEvolutionHudPortrait(refs.evolutionHudCharacterBefore, baseSrc, beforeName || card?.name || "進化前", basePortraits.idle || "");
    setEvolutionHudPortrait(refs.evolutionHudCharacterAfter, evolvedSrc, afterName || form?.displayName || form?.name || cardDisplayName(card), evolvedPortraits.idle || "");
    refs.evolutionHudMaterial.hidden = !config.image;
    refs.evolutionHudMaterial.src = config.image || "";
    refs.evolutionHudMaterial.alt = config.kicker;
    const startName = beforeName || card?.name || cardDisplayName(card);
    const finalName = afterName || form?.displayName || form?.name || cardDisplayName(card);
    if (refs.evolutionHudSub) refs.evolutionHudSub.textContent = "沉睡的力量，正在回應這片大海。";
    return new Promise((resolve) => {
      let finished = false;
      const finish = () => {
        if (finished) return;
        finished = true;
        hideEvolutionHud();
        resolve();
      };
      evolutionHudStoryLineTimer = window.setTimeout(() => {
        if (refs.evolutionHudSub) refs.evolutionHudSub.textContent = config.firstLine;
      }, 3200);
      evolutionHudLineTimer = window.setTimeout(() => {
        if (refs.evolutionHudSub) refs.evolutionHudSub.textContent = `${startName} 進化成 ${finalName} 了。`;
      }, 6600);
      evolutionHudTimer = window.setTimeout(() => {
        if (!refs.evolutionHud) {
          finish();
          return;
        }
        refs.evolutionHud.classList.add("awaiting");
        evolutionHudDismissHandler = (event) => {
          if (event.target?.closest?.("button,a,input,select,textarea")) return;
          finish();
        };
        refs.evolutionHud.addEventListener("click", evolutionHudDismissHandler);
      }, EVOLUTION_HUD_DURATION_MS);
    });
  }

  async function evolveCrewCard(player, index) {
    const card = player?.crew?.[index];
    if (!player || !card) return;
    syncCrewCardProgress(card);
    const form = nextEvolutionFormForCard(card);
    if (!form) {
      addLog(`${card.name} 目前沒有可進化形態。`);
      openCharacterDetail(player, index);
      return;
    }
    const status = evolutionRequirementStatus(player, card, form);
    if (!status.ok) {
      addLog(`${card.name} 還不能進化：${status.reasons.join("、")}。`);
      openCharacterDetail(player, index);
      return;
    }
    const costs = evolutionMaterialCosts(form);
    const materialText = evolutionMaterialText(form);
    const materialAction = evolutionConsumesMaterials(form) ? "消耗" : "使用";
    const beforeName = cardDisplayName(card);
    const beforePortraits = { ...(cardPortraitsForDisplay(card) || {}) };
    if (evolutionConsumesMaterials(form)) {
      const removed = costs.every((cost) => removeFormalItemFromPlayer(player, cost.itemId, cost.quantity));
      if (!removed) {
        addLog(`${card.name} 進化材料不足。`);
        openCharacterDetail(player, index);
        return;
      }
    }
    const previousStats = { ...(card.baseStats || {}) };
    const previousUnlockedMoveIds = Array.isArray(card.unlockedMoveIds)
      ? card.unlockedMoveIds.slice(0, MAX_ACTIVE_MOVES)
      : [];
    card.formId = form.id;
    card.unlockedEvolutionFormIds = Array.from(new Set([...(card.unlockedEvolutionFormIds || []), form.id]));
    syncCardMoveSetFromCatalog(card);
    const eligibleMoveIds = (card.moveSet || [])
      .filter((moveEntry) => effectiveMoveUnlockLevel(moveEntry) <= Number(card.level || 1))
      .map((moveEntry) => moveEntry.id);
    const isDirectMoveEvolution = form.id === LUFFY_GEAR_FIFTH_FORM_ID;
    const previousActiveMoveIds = previousUnlockedMoveIds.filter((id) => eligibleMoveIds.includes(id));
    card.unlockedMoveIds = isDirectMoveEvolution
      ? buildActiveMoveIdsForCard(card, eligibleMoveIds, formPreferredMoveIds(form, eligibleMoveIds))
      : buildActiveMoveIdsForCard(card, eligibleMoveIds, previousActiveMoveIds);
    applyCardLevelStats(card, previousStats);
    syncUnlockedMoveIds(card);
    recalcPlayerDerivedStats(player);
    addLog(`${card.name} ${materialAction} ${materialText}，進化為 ${form.name}。`);
    recordMainMissionEvent(player, { type: "evolved_crew", cardId: card.id, formId: form.id });
    const evolutionMoveId = isDirectMoveEvolution ? "" : firstEvolutionMoveChoiceId(form, eligibleMoveIds, card.unlockedMoveIds || []);
    const evolutionMove = card.moveSet.find((entry) => entry.id === evolutionMoveId);
    if (evolutionMove) {
      addLog(`${form.name} 的新招 ${evolutionMove.name} 可以學習，請在船上的新技能提示選擇要替換哪一招。`);
      queueMoveLearnChoice(player, card, evolutionMove.id);
    }
    const afterName = form.displayName || form.name || cardDisplayName(card);
    const afterPortraits = { ...(cardPortraitsForDisplay(card) || {}) };
    renderAll();
    if (refs.modalBack?.classList.contains("open")) closeModal();
    await playEvolutionMaterialEffect({ card, form, costs, materialText, materialAction, beforePortraits, afterPortraits, beforeName, afterName });
    openCharacterDetail(player, index);
  }

  function strictBattleParticipationForPlayer(player, battle) {
    const runtime = isCoopBattle(battle) ? coopBattleRuntimeFor(player, battle, false) : null;
    const entries = [
      ...(Array.isArray(runtime?.participatedCrewIndices) ? runtime.participatedCrewIndices : []),
      ...(String(player?.id || "") === String(battle?.playerId || "") && Array.isArray(battle?.participatedCrewIndices)
        ? battle.participatedCrewIndices
        : []),
    ];
    return new Set(entries
      .map((entry) => Number(entry))
      .filter((entry) => Number.isInteger(entry) && entry >= 0 && entry < Number(player?.crew?.length || 0)));
  }

  function grantZorojuroVictoryEvolution(player, battle) {
    if (!player || !battle || battle.result !== "win" || battle.isSparBattle) return [];
    const form = EVOLUTION_FORMS[ZORO_ZOROJURO_FORM_ID];
    if (!form) return [];
    const participated = strictBattleParticipationForPlayer(player, battle);
    const evolved = [];
    participated.forEach((index) => {
      const card = player.crew?.[index];
      if (!card || card.id !== "zoro") return;
      syncCrewCardProgress(card);
      if (activeEvolutionForm(card)?.id !== ZORO_NEW_WORLD_FORM_ID) return;
      if (!cardHasBattleCarryItem(card, ENMA_ITEM_ID)) return;
      const beforeName = cardDisplayName(card);
      const beforePortraits = { ...(cardPortraitsForDisplay(card) || {}) };
      const previousStats = { ...(card.baseStats || {}) };
      card.formId = form.id;
      card.unlockedEvolutionFormIds = Array.from(new Set([...(card.unlockedEvolutionFormIds || []), form.id]));
      syncCardMoveSetFromCatalog(card);
      const eligibleMoveIds = (card.moveSet || [])
        .filter((moveEntry) => effectiveMoveUnlockLevel(moveEntry) <= Number(card.level || 1))
        .map((moveEntry) => moveEntry.id);
      card.unlockedMoveIds = buildActiveMoveIdsForCard(card, eligibleMoveIds, formPreferredMoveIds(form, eligibleMoveIds));
      applyCardLevelStats(card, previousStats);
      syncUnlockedMoveIds(card);
      const finalEligibleMoveIds = (card.moveSet || [])
        .filter((moveEntry) => effectiveMoveUnlockLevel(moveEntry) <= Number(card.level || 1))
        .map((moveEntry) => moveEntry.id);
      card.unlockedMoveIds = formPreferredMoveIds(form, finalEligibleMoveIds).slice(0, MAX_ACTIVE_MOVES);
      const afterName = form.displayName || form.name;
      const afterPortraits = { ...(cardPortraitsForDisplay(card) || {}) };
      addLog(`${player.name} 的 ${beforeName} 攜帶閻魔實際參戰並取得勝利，成功駕馭霸氣，特殊進化為 ${afterName}。`);
      recordMainMissionEvent(player, { type: "evolved_crew", cardId: card.id, formId: form.id, source: "enma_victory" });
      evolved.push({ player, card, index, form, beforeName, afterName, beforePortraits, afterPortraits });
    });
    if (evolved.length) recalcPlayerDerivedStats(player);
    return evolved;
  }

  async function resolveZorojuroVictoryEvolutions(player, battle, options = {}) {
    if (!battle || battle.result !== "win" || battle.isSparBattle) return [];
    const participants = isCoopBattle(battle) ? coopBattleParticipants(battle) : [player];
    const evolved = participants.flatMap((entry) => grantZorojuroVictoryEvolution(entry, battle));
    if (!evolved.length) return [];
    renderAll();
    scheduleBoardLanStatePush("zorojuro-enma-victory", 60, { force: true });
    if (options.showEffect === false) return evolved;
    const visible = evolved.filter((entry) => !isCpuPlayer(entry.player) && canBoardLanControlCurrentPlayer(entry.player));
    for (const entry of visible) {
      await playEvolutionMaterialEffect({
        card: entry.card,
        form: entry.form,
        costs: entry.form.materialCost,
        materialText: "閻魔 x1",
        materialAction: "駕馭",
        beforePortraits: entry.beforePortraits,
        afterPortraits: entry.afterPortraits,
        beforeName: entry.beforeName,
        afterName: entry.afterName,
      });
    }
    return evolved;
  }

  function leveledCardStat(baseValue, growthValue, stat, level) {
    const growthProgress = levelGrowthProgress(level);
    const growthUnits = Number(CARD_LEVEL_GROWTH_UNITS[stat] || 10);
    return Math.max(1, Math.round(Number(baseValue || 1) + Number(growthValue || 0) * growthUnits * growthProgress));
  }

  function cardStatsForLevel(card, level = Number(card?.level || 1)) {
    const base = card?.baseStatsLevel1 || card?.baseStats || {};
    const growth = card?.growthRate || {};
    const stats = {
      hp: leveledCardStat(base.hp, growth.hp, "hp", level),
      atk: leveledCardStat(base.atk, growth.atk, "atk", level),
      def: leveledCardStat(base.def, growth.def, "def", level),
      satk: leveledCardStat(base.satk, growth.satk, "satk", level),
      sdef: leveledCardStat(base.sdef, growth.sdef, "sdef", level),
      spd: leveledCardStat(base.spd, growth.spd, "spd", level),
    };
    return applyTrainingStatModifiers(
      applyLineageTendencyStatModifiers(
        applyLineageEndgameBossStatModifiers(
          applyLineageGrowthStageStatModifiers(applyEvolutionStatModifiers(stats, activeEvolutionForm(card)), card),
          card
        ),
        card
      ),
      card
    );
  }

  function applyCardLevelStats(card, previousStats = card?.baseStats) {
    if (!card) return {};
    const catalogCard = characterCatalogCardById(card.id);
    syncCardEvolutionState(card);
    if (!card.baseStatsLevel1) card.baseStatsLevel1 = { ...(catalogCard?.baseStats || card.baseStats || {}) };
    const oldStats = { ...(previousStats || card.baseStats || {}) };
    const oldCurrentHp = Number(card.currentHp ?? oldStats.hp ?? 1);
    const newStats = cardStatsForLevel(card, card.level);
    const hpGain = Math.max(0, (newStats.hp || 0) - (oldStats.hp || 0));
    card.baseStats = newStats;
    card.hp = newStats.hp;
    card.atk = newStats.atk;
    card.def = newStats.def;
    card.satk = newStats.satk;
    card.sdef = newStats.sdef;
    card.spd = newStats.spd;
    card.currentHp = oldCurrentHp <= 0 ? 0 : Math.min(newStats.hp, Math.max(1, oldCurrentHp + hpGain));
    return {
      hp: newStats.hp - (oldStats.hp || 0),
      atk: newStats.atk - (oldStats.atk || 0),
      def: newStats.def - (oldStats.def || 0),
      satk: newStats.satk - (oldStats.satk || 0),
      sdef: newStats.sdef - (oldStats.sdef || 0),
      spd: newStats.spd - (oldStats.spd || 0),
    };
  }

  function cloneEnemy(enemy) {
    return balanceEnemyProfile(JSON.parse(JSON.stringify(enemy)));
  }

  function bountyGain(value) {
    const amount = Math.round(Number(value || 0));
    return amount > 0 ? Math.max(BOUNTY_MIN_GAIN, amount) : 0;
  }

  function addBounty(player, value) {
    const amount = bountyGain(value);
    if (player && amount > 0) player.bounty += amount;
    return amount;
  }

  function createEmptyJudicialRaidState() {
    return {
      active: false,
      cleared: false,
      failed: false,
      clearCount: 0,
      lastClearedAtRound: 0,
      islandId: JUDICIAL_ISLAND_ID,
      phaseIndex: 0,
      enemyKey: "",
      enemyCurrentHp: 0,
      enemyMaxHp: 0,
      enemyStages: emptyStages(),
      enemyStageTurns: emptyStageTurns(),
      enemyStatuses: emptyStatusEffects(),
      startedBy: "",
      currentActorPlayerId: "",
      turnQueue: [],
      pendingJoinPlayerIds: [],
      participants: {},
      phaseClearedKeys: [],
      phaseRewardClaimedKeys: [],
      rewardClaimedBy: [],
      log: [],
    };
  }

  function ensureJudicialRaidState() {
    if (!state.gameState) return createEmptyJudicialRaidState();
    const defaults = createEmptyJudicialRaidState();
    const raid = state.gameState.judicialRaid || {};
    state.gameState.judicialRaid = {
      ...defaults,
      ...raid,
      clearCount: Math.max(raid.cleared ? 1 : 0, Math.round(Number(raid.clearCount || 0))),
      lastClearedAtRound: Math.max(0, Math.round(Number(raid.lastClearedAtRound || 0))),
      islandId: raid.islandId || JUDICIAL_ISLAND_ID,
      participants: raid.participants && typeof raid.participants === "object" ? raid.participants : {},
      turnQueue: Array.isArray(raid.turnQueue) ? raid.turnQueue : [],
      pendingJoinPlayerIds: Array.isArray(raid.pendingJoinPlayerIds) ? raid.pendingJoinPlayerIds : [],
      phaseClearedKeys: Array.isArray(raid.phaseClearedKeys) ? raid.phaseClearedKeys : [],
      phaseRewardClaimedKeys: Array.isArray(raid.phaseRewardClaimedKeys) ? raid.phaseRewardClaimedKeys : [],
      rewardClaimedBy: Array.isArray(raid.rewardClaimedBy) ? raid.rewardClaimedBy : [],
      log: Array.isArray(raid.log) ? raid.log : [],
      enemyStages: raid.enemyStages || emptyStages(),
      enemyStageTurns: raid.enemyStageTurns || emptyStageTurns(),
      enemyStatuses: raid.enemyStatuses || emptyStatusEffects(),
    };
    return state.gameState.judicialRaid;
  }

  function raidHpMultiplier(count) {
    if (count <= 1) return 1;
    if (count === 2) return 1.6;
    if (count === 3) return 2.2;
    return 2.8;
  }

  function getJudicialRaidEnemyProfile(phaseIndex = 0) {
    const key = JUDICIAL_RAID_PHASES[Math.max(0, Math.min(JUDICIAL_RAID_PHASES.length - 1, Number(phaseIndex) || 0))];
    const profile = ENIES_LOBBY_ENEMY_PROFILES.find((enemy) => enemy.key === key)
      || ENIES_LOBBY_ENEMY_PROFILES.find((enemy) => enemy.key === "spandam");
    if (!profile) {
      console.warn("Judicial raid enemy profile missing; using fallback enemy.");
      return ENIES_LOBBY_ENEMY_PROFILES[0];
    }
    return profile;
  }

  function createJudicialRaidPhaseEnemy(phaseIndex) {
    const enemy = cloneEnemy(getJudicialRaidEnemyProfile(phaseIndex));
    enemy.hp = enemy.maxHp;
    enemy.damageMultiplier = 1;
    enemy.recommendedPower = enemyRecommendedPowerFromStats(enemy.baseStats || enemy);
    return enemy;
  }

  function activeJudicialRaidParticipants(raid = ensureJudicialRaidState()) {
    return Object.values(raid.participants || {}).filter((entry) => entry?.active && !entry.defeated);
  }

  function judicialRaidParticipantCount(raid = ensureJudicialRaidState()) {
    return Math.max(1, activeJudicialRaidParticipants(raid).length);
  }

  function scaleJudicialRaidEnemyHp(baseEnemy, participantCount) {
    return Math.max(1, Math.round((baseEnemy?.maxHp || 1) * raidHpMultiplier(participantCount)));
  }

  function rebuildJudicialRaidTurnQueue(raid = ensureJudicialRaidState()) {
    raid.turnQueue = activeJudicialRaidParticipants(raid).map((entry) => entry.playerId);
    return raid.turnQueue;
  }

  function addJudicialRaidLog(text) {
    let raid = ensureJudicialRaidState();
    raid.log.push(text);
    if (raid.log.length > 80) raid.log = raid.log.slice(-80);
    addLog(text);
  }

  function ensureJudicialRaidParticipant(player, raid = ensureJudicialRaidState()) {
    if (!player?.id) return null;
    if (!raid.participants[player.id]) {
      raid.participants[player.id] = {
        playerId: player.id,
        joinedAtPhase: raid.phaseIndex || 0,
        joinedAtRound: 0,
        active: true,
        defeated: false,
        damageDone: 0,
        damageTaken: 0,
        healingDone: 0,
        turnsActed: 0,
        lastJoinedAt: Date.now(),
      };
    } else {
      raid.participants[player.id].active = true;
      raid.participants[player.id].lastJoinedAt = Date.now();
    }
    rebuildJudicialRaidTurnQueue(raid);
    return raid.participants[player.id];
  }

  function initializeJudicialRaidPhase(raid, phaseIndex) {
    const baseEnemy = createJudicialRaidPhaseEnemy(phaseIndex);
    const count = judicialRaidParticipantCount(raid);
    raid.phaseIndex = phaseIndex;
    raid.enemyKey = baseEnemy.key || JUDICIAL_RAID_PHASES[phaseIndex] || "spandam";
    raid.enemyMaxHp = scaleJudicialRaidEnemyHp(baseEnemy, count);
    raid.enemyCurrentHp = raid.enemyMaxHp;
    raid.enemyStages = emptyStages();
    raid.enemyStageTurns = emptyStageTurns();
    raid.enemyStatuses = emptyStatusEffects();
    raid.currentActorPlayerId = "";
    return baseEnemy;
  }

  function recordJudicialRaidContribution(battle, player, patch = {}) {
    if (!battle || !player?.id) return;
    const addPatch = (participant) => {
      if (!participant) return;
      participant.damageDone = Math.max(0, Number(participant.damageDone || 0)) + Math.max(0, Number(patch.damageDone || 0));
      participant.damageTaken = Math.max(0, Number(participant.damageTaken || 0)) + Math.max(0, Number(patch.damageTaken || 0));
      participant.healingDone = Math.max(0, Number(participant.healingDone || 0)) + Math.max(0, Number(patch.healingDone || 0));
      participant.turnsActed = Math.max(0, Number(participant.turnsActed || 0)) + Math.max(0, Number(patch.turnsActed || 0));
      participant.itemsUsed = Math.max(0, Number(participant.itemsUsed || 0)) + Math.max(0, Number(patch.itemsUsed || 0));
      participant.rescuesDone = Math.max(0, Number(participant.rescuesDone || 0)) + Math.max(0, Number(patch.rescuesDone || 0));
    };
    if (isCoopBattle(battle)) {
      battle.coop ||= {};
      battle.coop.contributions = battle.coop.contributions && typeof battle.coop.contributions === "object"
        ? battle.coop.contributions
        : {};
      const id = String(player.id);
      battle.coop.contributions[id] ||= {
        playerId: player.id,
        damageDone: 0,
        damageTaken: 0,
        healingDone: 0,
        turnsActed: 0,
        itemsUsed: 0,
        rescuesDone: 0,
      };
      addPatch(battle.coop.contributions[id]);
    }
    if (!battle.isJudicialRaid) return;
    const raid = ensureJudicialRaidState();
    const participant = ensureJudicialRaidParticipant(player, raid);
    if (!participant) return;
    addPatch(participant);
    raid.enemyCurrentHp = Math.max(0, Math.min(raid.enemyMaxHp || battle.enemyCombatant.maxHp || 1, battle.enemyCombatant.currentHp ?? raid.enemyCurrentHp));
    raid.enemyStages = battle.enemyCombatant.stages || raid.enemyStages || emptyStages();
    raid.enemyStageTurns = battle.enemyCombatant.stageTurns || raid.enemyStageTurns || emptyStageTurns();
    raid.enemyStatuses = battle.enemyCombatant.statuses || raid.enemyStatuses || emptyStatusEffects();
  }

  function cloneSeaEncounterEnemy(enemy) {
    const out = cloneEnemy(enemy);
    out.hp = out.maxHp;
    out.damageMultiplier = 1;
    return out;
  }

  function enemyGrowthRateForTier(tier) {
    return { ...(ENEMY_TIER_GROWTH[legacyTier(tier)] || ENEMY_TIER_GROWTH.T5) };
  }

  function enemyBaseStatsFromSeed(stats = {}) {
    const atkSeed = Number(stats.atk || 1);
    const defSeed = Number(stats.def || Math.max(1, Math.round(atkSeed * 0.72)));
    const satkSeed = Number(stats.satk || Math.round(atkSeed * 0.92));
    const sdefSeed = Number(stats.sdef || Math.round(defSeed * 0.92));
    const spdSeed = Number(stats.spd || 1);
    return {
      hp: Math.max(30, Math.round(Number(stats.maxHp || stats.hp || 1))),
      atk: Math.max(8, Math.round(24 + atkSeed * ENEMY_STAT_SEED_SCALE.atk)),
      def: Math.max(8, Math.round(24 + defSeed * ENEMY_STAT_SEED_SCALE.def)),
      satk: Math.max(8, Math.round(24 + satkSeed * ENEMY_STAT_SEED_SCALE.satk)),
      sdef: Math.max(8, Math.round(24 + sdefSeed * ENEMY_STAT_SEED_SCALE.sdef)),
      spd: Math.max(8, Math.round(34 + spdSeed * ENEMY_STAT_SEED_SCALE.spd)),
    };
  }

  function enemyRecommendedPowerFromStats(stats = {}) {
    const atk = Math.max(Number(stats.atk || stats.satk || 1), Number(stats.satk || stats.atk || 1));
    const def = Math.max(Number(stats.def || stats.sdef || 1), Number(stats.sdef || stats.def || 1));
    const spd = Number(stats.spd || 1);
    const hp = Number(stats.hp || stats.maxHp || 1);
    return Math.max(1, Math.round((atk + def + spd * 0.5 + hp * 0.035) / 16));
  }

  function battleExpRewardForEnemy(tier, level, multiplier = 1.5) {
    const normalizedTier = legacyTier(tier);
    const baseExp = ENEMY_BASE_EXP_BY_TIER[normalizedTier] || ENEMY_BASE_EXP_BY_TIER.T5;
    const enemyLevel = Math.max(1, Math.min(CHARACTER_MAX_LEVEL, Math.round(Number(level || enemyLevelForProgress(normalizedTier)))));
    return Math.max(1, Math.floor((baseExp * enemyLevel * Number(multiplier || 1) * BATTLE_EXP_REWARD_MULTIPLIER) / 7));
  }

  function enemyProfileStatPersonality(enemy = {}) {
    const source = enemy.originalStats || enemy;
    const atk = Math.max(1, Number(source.atk || 1));
    const def = Math.max(1, Number(source.def || Math.round(atk * 0.72)));
    const satk = Math.max(1, Number(source.satk || Math.round(atk * 0.92)));
    const sdef = Math.max(1, Number(source.sdef || Math.round(def * 0.92)));
    const spd = Math.max(1, Number(source.spd || 1));
    const avgOffense = (atk + satk) / 2;
    const avgDefense = (def + sdef) / 2;
    return {
      atk: Math.max(0.88, Math.min(1.18, atk / Math.max(1, avgOffense))),
      satk: Math.max(0.88, Math.min(1.18, satk / Math.max(1, avgOffense))),
      def: Math.max(0.88, Math.min(1.18, def / Math.max(1, avgDefense))),
      sdef: Math.max(0.88, Math.min(1.18, sdef / Math.max(1, avgDefense))),
      spd: Math.max(0.82, Math.min(1.24, spd / Math.max(1, avgOffense * 0.72))),
    };
  }

  function enemyLevelStatEnvelope(enemy = {}, tier = "T5", level = 1) {
    const normalizedTier = legacyTier(tier);
    const rule = ENEMY_LEVEL_STAT_ENVELOPE[normalizedTier] || ENEMY_LEVEL_STAT_ENVELOPE.T5;
    const normalizedLevel = Math.max(1, Math.min(CHARACTER_MAX_LEVEL, Math.round(Number(level || 1))));
    const personality = enemyProfileStatPersonality(enemy);
    const hpFloor = Math.round(rule.hpBase + rule.hpPerLevel * normalizedLevel);
    const offenseFloor = rule.offenseBase + rule.offensePerLevel * normalizedLevel;
    const defenseFloor = rule.defenseBase + rule.defensePerLevel * normalizedLevel;
    const speedFloor = rule.speedBase + rule.speedPerLevel * normalizedLevel;
    const cap = Number(rule.cap || 1.5);
    const hpCap = Number(rule.hpCap || cap);
    return {
      floor: {
        hp: hpFloor,
        atk: Math.round(offenseFloor * personality.atk),
        satk: Math.round(offenseFloor * personality.satk),
        def: Math.round(defenseFloor * personality.def),
        sdef: Math.round(defenseFloor * personality.sdef),
        spd: Math.round(speedFloor * personality.spd),
      },
      cap: {
        hp: Math.round(hpFloor * hpCap),
        atk: Math.round(offenseFloor * personality.atk * cap),
        satk: Math.round(offenseFloor * personality.satk * cap),
        def: Math.round(defenseFloor * personality.def * cap),
        sdef: Math.round(defenseFloor * personality.sdef * cap),
        spd: Math.round(speedFloor * personality.spd * Math.min(cap, 1.38)),
      },
    };
  }

  function enforceEnemyLevelStatEnvelope(enemy = {}, tier = "T5", level = 1, stats = {}) {
    const envelope = enemyLevelStatEnvelope(enemy, tier, level);
    const clamp = (stat) => Math.max(envelope.floor[stat], Math.min(envelope.cap[stat], Math.round(Number(stats[stat] || 1))));
    return {
      hp: clamp("hp"),
      atk: clamp("atk"),
      def: clamp("def"),
      satk: clamp("satk"),
      sdef: clamp("sdef"),
      spd: clamp("spd"),
    };
  }

  function scaleBalancedEnemyStats(enemy = {}, multipliers = {}) {
    const scaledStats = {
      hp: Math.max(1, Math.round(Number(enemy.maxHp || enemy.hp || 1) * Number(multipliers.hp || 1))),
      atk: Math.max(1, Math.round(Number(enemy.atk || 1) * Number(multipliers.atk || 1))),
      def: Math.max(1, Math.round(Number(enemy.def || 1) * Number(multipliers.def || 1))),
      satk: Math.max(1, Math.round(Number(enemy.satk || enemy.atk || 1) * Number(multipliers.satk || multipliers.atk || 1))),
      sdef: Math.max(1, Math.round(Number(enemy.sdef || enemy.def || 1) * Number(multipliers.sdef || multipliers.def || 1))),
      spd: Math.max(1, Math.round(Number(enemy.spd || 1) * Number(multipliers.spd || 1))),
    };
    enemy.maxHp = scaledStats.hp;
    enemy.hp = scaledStats.hp;
    enemy.atk = scaledStats.atk;
    enemy.def = scaledStats.def;
    enemy.satk = scaledStats.satk;
    enemy.sdef = scaledStats.sdef;
    enemy.spd = scaledStats.spd;
    enemy.baseStats = scaledStats;
    enemy.recommendedPower = enemyRecommendedPowerFromStats(scaledStats);
    return enemy;
  }

  function balanceEnemyProfile(enemy) {
    if (!enemy || enemy._balanceVersion === ENEMY_BALANCE_VERSION) return enemy;
    if (enemy.fixedBattleStats) {
      enemy.originalStats ||= {
        maxHp: Math.max(1, Number(enemy.maxHp || enemy.hp || 1)),
        atk: Math.max(1, Number(enemy.atk || 1)),
        def: Math.max(1, Number(enemy.def || 1)),
        satk: Math.max(1, Number(enemy.satk || enemy.atk || 1)),
        sdef: Math.max(1, Number(enemy.sdef || enemy.def || 1)),
        spd: Math.max(1, Number(enemy.spd || 1)),
        recommendedPower: Math.max(1, Number(enemy.recommendedPower || 1)),
      };
      enemy.baseStats = {
        hp: enemy.originalStats.maxHp,
        atk: enemy.originalStats.atk,
        def: enemy.originalStats.def,
        satk: enemy.originalStats.satk,
        sdef: enemy.originalStats.sdef,
        spd: enemy.originalStats.spd,
      };
      enemy.damageMultiplier = 1;
      enemy._balanceVersion = ENEMY_BALANCE_VERSION;
      return enemy;
    }
    const declaredTier = legacyTier(enemy.tier);
    const band = enemyLevelBand(declaredTier);
    const explicitLevel = Number(enemy.level);
    const hasExplicitLevel = Number.isFinite(explicitLevel) && explicitLevel > 0;
    const level = Number.isFinite(explicitLevel) && explicitLevel > 0
      ? Math.max(1, Math.min(CHARACTER_MAX_LEVEL, Math.round(explicitLevel)))
      : Math.max(band.min, Math.min(band.max, Math.round(Number(enemy.level) || enemyLevelForProgress(declaredTier))));
    const normalizedTier = hasExplicitLevel ? enemyTierForLevel(level, declaredTier) : declaredTier;
    const originalStats = enemy.originalStats || {
      maxHp: Number(enemy.maxHp || 1),
      atk: Number(enemy.atk || 1),
      def: Number(enemy.def || Math.max(1, Math.round((enemy.atk || 1) * 0.72))),
      satk: Number(enemy.satk || Math.round((enemy.atk || 1) * 0.92)),
      sdef: Number(enemy.sdef || Math.round((enemy.def || Math.max(1, Math.round((enemy.atk || 1) * 0.72))) * 0.92)),
      spd: Number(enemy.spd || 1),
      recommendedPower: Number(enemy.recommendedPower || 1),
    };
    const baseStatsLevel1 = enemy.baseStatsLevel1 || enemyBaseStatsFromSeed(originalStats);
    const growthRate = enemy.growthRate || enemyGrowthRateForTier(normalizedTier);
    const leveledStats = enforceEnemyLevelStatEnvelope(enemy, normalizedTier, level, cardStatsForLevel({ baseStatsLevel1, growthRate }, level));
    enemy.originalStats = enemy.originalStats || originalStats;
    enemy.baseStatsLevel1 = baseStatsLevel1;
    enemy.growthRate = growthRate;
    enemy.baseStats = leveledStats;
    enemy.tier = normalizedTier;
    enemy.level = level;
    enemy.maxHp = leveledStats.hp;
    enemy.hp = leveledStats.hp;
    enemy.atk = leveledStats.atk;
    enemy.def = leveledStats.def;
    enemy.satk = leveledStats.satk;
    enemy.sdef = leveledStats.sdef;
    enemy.spd = leveledStats.spd;
    enemy.recommendedPower = enemyRecommendedPowerFromStats(leveledStats);
    enemy.damageMultiplier = 1;
    enemy.rank = tierLabel(normalizedTier);
    capEnemyMovePowers(enemy);
    enemy._balanceVersion = ENEMY_BALANCE_VERSION;
    return enemy;
  }

  function ensureBalancedEnemyState(islandState) {
    if (!islandState?.enemyProfile || islandState.enemyProfile._balanceVersion === ENEMY_BALANCE_VERSION) return;
    const previousMaxHp = Math.max(1, Number(islandState.maxHp || islandState.enemyProfile.maxHp || 1));
    const currentRatio = islandState.isDefeated ? 0 : Math.max(0, Number(islandState.currentHp || previousMaxHp)) / previousMaxHp;
    islandState.enemyProfile = balanceEnemyProfile(JSON.parse(JSON.stringify(islandState.enemyProfile)));
    islandState.enemyTier = islandState.enemyProfile.tier;
    islandState.maxHp = islandState.enemyProfile.maxHp;
    islandState.currentHp = islandState.isDefeated ? 0 : Math.max(1, Math.round(islandState.maxHp * Math.min(1, currentRatio)));
  }

  function rebalanceIslandEnemyStatesByPosition(game = state.gameState) {
    const boardData = game?.boardData;
    const islands = boardData?.islands;
    const islandStates = boardData?.islandStates;
    const routes = boardData?.routesBetweenIslands || MAP_TEMPLATE.routesBetweenIslands;
    if (!Array.isArray(islands) || !islandStates || state.battleState) return;
    const distanceMap = buildIslandDistanceMapFromReverseMountain(routes);
    const maxEnemyDistance = Math.max(
      1,
      ...islands
        .filter((island) => island.id !== START_ISLAND_ID && island.id !== INVERSION_MOUNTAIN_ID && island.kind !== "yonko" && island.kind !== "yonko-slot" && island.kind !== "final")
        .map((island) => distanceMap.get(island.id) ?? 1)
    );
    const blockedEnemyKeys = prisonerCrewEnemyKeys(game);
    const usedEnemyKeys = new Set(blockedEnemyKeys);
    islands.forEach((island) => {
      const islandState = islandStates[island.id];
      if (island.kind !== "enemy" || !islandState?.enemyProfile || islandState.isDefeated) return;
      const expectedTier = tierForEnemyDistance(island.id, distanceMap, maxEnemyDistance);
      const regionIds = regionalSpawnIdsForIslandId(island.id);
      const enemy = islandState.enemyProfile;
      const existingSourceTier = enemyPoolTierForKey(enemy.key) || legacyTier(enemy.tier || expectedTier);
      const expectedLevel = enemyLevelForDistance(island.id, distanceMap, maxEnemyDistance, existingSourceTier);
      const enemyBlocked = blockedEnemyKeys.has(String(enemy.key || ""));
      const enemyUnavailable = !regionalEnemyProfileAllowed(enemy, regionIds, game);
      const postgameModeMatches = enemy._spawnPostgameUnlocked === regionalEnemySpawnPostgameUnlocked(game);
      const persistedLevelFloor = Math.max(0, Number(enemy._levelFloorTarget || 0));
      const levelFloorBalanced = persistedLevelFloor > expectedLevel
        && Math.round(Number(enemy.level || 0)) === Math.round(persistedLevelFloor);
      const alreadyBalanced = enemy._positionBalanceVersion === ISLAND_ENEMY_POSITION_BALANCE_VERSION
        && enemy._balanceVersion === ENEMY_BALANCE_VERSION
        && enemy._spawnRegionPresetVersion === (regionalEnemySpawnConfig()?.version || "")
        && postgameModeMatches
        && ((legacyTier(enemy.tier) === existingSourceTier && Math.round(Number(enemy.level || 0)) === expectedLevel) || levelFloorBalanced)
        && !enemyBlocked
        && !enemyUnavailable;
      if (alreadyBalanced) {
        if (enemy.key) usedEnemyKeys.add(String(enemy.key));
        return;
      }
      const previousMaxHp = Math.max(1, Number(islandState.maxHp || enemy.maxHp || 1));
      const currentRatio = islandState.isDefeated ? 0 : Math.max(0, Number(islandState.currentHp || previousMaxHp)) / previousMaxHp;
      const rand = createRng(`${game.seed}-island-position-${island.id}-${ISLAND_ENEMY_POSITION_BALANCE_VERSION}`);
      const profile = positionBalancedEnemyProfileForIsland(
        island.id,
        rand,
        usedEnemyKeys,
        distanceMap,
        maxEnemyDistance,
        !enemyBlocked
          && !enemyUnavailable
          && postgameModeMatches
          && enemy._positionBalanceVersion === ISLAND_ENEMY_POSITION_BALANCE_VERSION
          && legacyTier(enemy.tier) === existingSourceTier
          ? enemy
          : null
      );
      island.enemyTier = profile.tier;
      islandState.enemyTier = profile.tier;
      islandState.enemyProfile = profile;
      islandState.maxHp = profile.maxHp;
      islandState.currentHp = Math.max(1, Math.round(profile.maxHp * Math.min(1, currentRatio || 1)));
    });
  }

  function addLog(text) {
    state.gameState.log.push(text);
    renderLog();
  }

  function showMissionCompleteToast(mission) {
    const toast = refs.missionCompleteToast || document.getElementById("missionCompleteToast");
    if (!toast || !mission) return;
    const title = toast.querySelector("[data-mission-toast-title]");
    const sub = toast.querySelector("[data-mission-toast-sub]");
    if (title) title.textContent = `任務完成：${mission.title || "未知任務"}`;
    if (sub) sub.textContent = "可以從船內任務或任務島領取獎勵。";
    toast.classList.remove("show");
    void toast.offsetWidth;
    toast.classList.add("show");
    window.clearTimeout(missionCompleteToastTimer);
    missionCompleteToastTimer = window.setTimeout(() => {
      toast.classList.remove("show");
    }, 3200);
  }

  function teamMoveAverage(player) {
    if (!player?.crew?.length) return 0;
    return player.crew.reduce((sum, card) => sum + card.move, 0) / player.crew.length;
  }

  function getUnlockedMoves(card) {
    if (!card) return [];
    if (!Array.isArray(card.unlockedMoveIds) || card.unlockedMoveIds.length === 0) {
      syncUnlockedMoveIds(card);
    }
    const level = Number(card.level || 1);
    const activeIds = new Set((card.unlockedMoveIds || []).slice(0, MAX_ACTIVE_MOVES));
    const battle = state.battleState;
    const { player, index } = sanjiRaidSuitBattleOwner(card, battle);
    return (card.moveSet || [])
      .filter((moveEntry) => activeIds.has(moveEntry.id) && effectiveMoveUnlockLevel(moveEntry) <= level)
      .map((moveEntry) => sanjiRaidSuitMoveEntry(card, moveEntry, player, battle, index));
  }

  function playerShipEquipmentDefs(player) {
    const shipState = normalizePlayerShipState(player);
    return shipState.equippedGear
      .filter(Boolean)
      .map((itemId) => gameItemDef(itemId))
      .filter((item) => item && normalizeGameItemCategory(item.category) === "ship" && item.effect?.kind === "ship_equipment");
  }

  function battleCrewIndexIsEligible(player, battle, index) {
    const crewIndex = Number(index);
    if (!Number.isInteger(crewIndex) || crewIndex < 0 || !player?.crew?.[crewIndex]) return false;
    const isArenaBattle = !!battle && (battle.isArenaBattle || battle.islandKind === "arena");
    if (!isArenaBattle || String(battle.playerId || "") !== String(player?.id || "")) return true;
    if (!Array.isArray(battle.arenaCrewIndices)) return true;
    return battle.arenaCrewIndices.some((entry) => Number(entry) === crewIndex);
  }

  function battleCrewEntries(player, battle) {
    return (player?.crew || [])
      .map((card, index) => ({ card, index }))
      .filter(({ index }) => battleCrewIndexIsEligible(player, battle, index));
  }

  function getTeamEffects(player) {
    const roleCounts = { "戰鬥型": 0, "偵查型": 0, "移動型": 0, "輔助型": 0 };
    const battle = state.battleState;
    battleCrewEntries(player, battle).forEach(({ card }) => {
      const roleType = card?.roleType;
      if (roleCounts[roleType] != null) roleCounts[roleType] += 1;
    });
    const battleCount = roleCounts["戰鬥型"] || 0;
    let scoutCount = roleCounts["偵查型"] || 0;
    const shipState = normalizePlayerShipState(player);
    if (shipState.upgradeLevels.watchtower >= 1 && scoutCount > 0) {
      scoutCount = Math.min(3, scoutCount + 1);
    }
    const diceMaxBonus = Math.min(3, roleCounts["移動型"] || 0);
    const supportCount = roleCounts["輔助型"] || 0;
    const effects = {
      disadvantagedFloor: 0.5,
      battleCount,
      scoutCount,
      scoutRange: scoutCount >= 1 ? 1 : 0,
      diceMaxBonus,
      supportCount,
      battleAttackMultiplier: 1.1,
      battleExtraDiceThreshold: battleCount >= 3 ? 4 : battleCount >= 2 ? 5 : battleCount >= 1 ? 6 : 0,
      movementCap: Math.min(9, 6 + diceMaxBonus),
      movementSpeedBonus: Math.min(0.3, diceMaxBonus * 0.1),
      escapeThreshold: diceMaxBonus > 0 ? Math.max(2, 7 - diceMaxBonus) : 0,
      supportDamageReduction: Math.min(0.3, supportCount * 0.1),
      turnHealRate: Math.min(0.15, supportCount * 0.05),
      moveBonus: 0,
      negativeBerryLossReduction: 0,
      eventGainBonus: 0,
      shopDiscount: 0,
      firstBattleReduction: 0,
      enemyIslandDamageBonus: 0,
      firstNormalFourBonus: 0,
      skillMpReduction: 0,
      firstStrikeBonus: 0,
      yonkoDamageBonus: 0,
      allAtkBonus: 0,
      enemyInfoBonus: scoutCount,
      seaEncounterScoutRange: scoutCount >= 2 ? 1 : 0,
      seaChoiceReveal: scoutCount >= 3,
      stormSoftening: 0,
      healItemBonus: 0,
      activeSkillPowerBonus: 0,
      antiShieldBonus: 0,
      lowHpRecover: 0,
      escapeSpeedBonus: 0,
      shipMovementBonuses: [],
      seaChoiceTypeReveal: 0,
      seaChoiceBattleRisk: false,
      seaHpDamageReduction: 0,
      firstBattleDamageReduction: 0,
      battleStartShield: 0,
      bossBattleStartShield: 0,
      battleWinLowestHeal: 0,
      battleWinTeamHeal: 0,
      battleWinLowHpExtraHeal: 0,
      battleWinLowHpThreshold: 0.3,
      battleWinReviveOneHp: false,
      shipEscapeMoveBonus: 0,
      shipSpeedBoostTurns: 0,
      shipOpeningFirstStrikeDamageBonus: 0,
      shipSwitchDamageReduction: 0,
      shipEscapeRollBonus: 0,
      battleWinRestoreRandomPP: 0,
      battleWinTeamHealWhenAverageLow: 0,
      battleWinTeamHealAverageThreshold: 0.5,
      battleExpBonus: 0,
      lowLevelExpBonus: 0,
      missionExpBonus: 0,
      enemyInfoSeaEncounter: false,
      enemyInfoEnemyIsland: false,
    };
    const shipItems = playerShipEquipmentDefs(player);
    let shipEscapeBonus = 0;
    shipItems.forEach((item) => {
      const effect = item.effect || {};
      if (["low_roll_fix", "tailwind_step", "cola_burst"].includes(effect.trigger)) {
        effects.shipMovementBonuses.push({
          itemId: item.id,
          itemName: item.name,
          trigger: effect.trigger,
          triggerRoll: Number(effect.triggerRoll || 0),
          moveBonus: Math.max(0, Math.round(Number(effect.moveBonus || 0))),
          cooldownTurns: Math.max(0, Math.round(Number(effect.cooldownTurns || 0))),
        });
      }
      shipEscapeBonus += Math.max(0, Math.round(Number(effect.escapeThresholdBonus || 0)));
      effects.shipEscapeMoveBonus = Math.max(effects.shipEscapeMoveBonus, Math.max(0, Math.round(Number(effect.escapeMoveBonus || 0))));
      effects.seaChoiceTypeReveal = Math.max(effects.seaChoiceTypeReveal, Math.max(0, Math.round(Number(effect.seaChoiceTypeReveal || 0))));
      effects.seaChoiceBattleRisk = effects.seaChoiceBattleRisk || Boolean(effect.seaChoiceBattleRisk);
      effects.seaHpDamageReduction = Math.max(effects.seaHpDamageReduction, Math.max(0, Number(effect.seaHpDamageReduction || 0)));
      effects.firstBattleDamageReduction = Math.max(effects.firstBattleDamageReduction, Math.max(0, Number(effect.firstBattleDamageReduction || 0)));
      effects.battleStartShield = Math.max(effects.battleStartShield, Math.max(0, Number(effect.battleStartShield || 0)));
      effects.bossBattleStartShield = Math.max(effects.bossBattleStartShield, Math.max(0, Number(effect.bossBattleStartShield || 0)));
      effects.battleWinLowestHeal = Math.max(effects.battleWinLowestHeal, Math.max(0, Number(effect.battleWinLowestHeal || 0)));
      effects.battleWinTeamHeal = Math.max(effects.battleWinTeamHeal, Math.max(0, Number(effect.battleWinTeamHeal || 0)));
      effects.battleWinLowHpExtraHeal = Math.max(effects.battleWinLowHpExtraHeal, Math.max(0, Number(effect.battleWinLowHpExtraHeal || 0)));
      if (Number(effect.lowHpThreshold || 0) > 0) effects.battleWinLowHpThreshold = Math.max(0.01, Number(effect.lowHpThreshold || 0.3));
      effects.battleWinReviveOneHp = effects.battleWinReviveOneHp || Boolean(effect.battleWinReviveOneHp);
    });
    if (shipEscapeBonus > 0) {
      const baseEscapeThreshold = Number(effects.escapeThreshold || 0) > 0 ? effects.escapeThreshold : 7;
      effects.escapeThreshold = Math.max(2, baseEscapeThreshold - shipEscapeBonus);
    }
    const upgrades = shipState.upgradeLevels;
    if (upgrades.sail >= 1) effects.shipSpeedBoostTurns = upgrades.sail >= 2 ? 2 : 1;
    if (upgrades.sail >= 3) effects.shipOpeningFirstStrikeDamageBonus = 0.06;
    if (upgrades.rudder >= 1) effects.firstBattleDamageReduction = Math.max(effects.firstBattleDamageReduction, 0.08);
    if (upgrades.rudder >= 2) effects.shipSwitchDamageReduction = Math.max(effects.shipSwitchDamageReduction, 0.1);
    if (upgrades.rudder >= 3) effects.shipEscapeRollBonus = Math.max(effects.shipEscapeRollBonus, 1);
    if (upgrades.watchtower >= 2) effects.enemyInfoSeaEncounter = true;
    if (upgrades.watchtower >= 3) effects.enemyInfoEnemyIsland = true;
    if (upgrades.kitchen >= 1) effects.battleWinLowestHeal += 0.05;
    if (upgrades.kitchen >= 2) effects.battleWinRestoreRandomPP = Math.max(effects.battleWinRestoreRandomPP, 1);
    if (upgrades.kitchen >= 3) {
      effects.battleWinTeamHealWhenAverageLow = Math.max(effects.battleWinTeamHealWhenAverageLow, 0.05);
      effects.battleWinTeamHealAverageThreshold = 0.5;
    }
    if (upgrades.training >= 1) effects.battleExpBonus = Math.max(effects.battleExpBonus, 0.06);
    if (upgrades.training >= 2) effects.lowLevelExpBonus = Math.max(effects.lowLevelExpBonus, 0.08);
    if (upgrades.training >= 3) effects.missionExpBonus = Math.max(effects.missionExpBonus, 0.1);
    return effects;
  }

