  function spectatorMissionCard(mission = {}, selectedId = "") {
    const isSelected = selectedId === mission.id;
    const isActive = Boolean(mission.active);
    const isComplete = Boolean(mission.active?.completed);
    const isShared = Boolean(mission.shared);
    const isSharedComplete = Boolean(mission.shared?.completed);
    return `
      <button type="button" class="mission-card${isSelected ? " selected" : ""}${isShared ? " shared-accepted" : ""}" aria-disabled="true">
        <img class="grade-mark grade-${String(mission.grade || "E").toLowerCase()}" src="${missionJournalGradeImage(mission)}" alt="${escapeModalText(mission.grade || "E")}級">
        <h3>${escapeModalText(mission.title || "未知任務")}</h3>
        <div class="mission-tags">
          <span class="type-icon" aria-hidden="true"></span>
          <span class="tag">${escapeModalText(mission.tierLabel || `${mission.grade || "E"}級`)}</span>
          <span class="tag">${escapeModalText(mission.type || "委託")}</span>
          ${mission.special ? `<span class="tag special-tag">${escapeModalText(mission.special)}</span>` : ""}
        </div>
        <div class="condition">${escapeModalText(mission.condition || "")}</div>
        <div class="reward">
          <span>${formatCoin(mission.coins || 0)} B</span>
          <span>EXP ${formatCoin(mission.exp || 0)}</span>
          <span>賞金 ${escapeModalText(mission.bountyText || "0")}</span>
          <span class="item-summary">物品 ${escapeModalText(mission.itemSummary || "無")}</span>
        </div>
        ${isActive ? `<span class="mission-stamp stamp-pop">${isComplete ? "CLEAR" : "ACCEPTED"}</span>` : ""}
        ${isShared ? `<span class="mission-stamp shared-stamp">${isSharedComplete ? "CO-OP CLEAR" : "CO-OP"}</span>` : ""}
      </button>
    `;
  }

