  function openSpectatorBoardModal(event = {}) {
    const detail = event.detail || {};
    if (detail.kind === "sea-choice") {
      pinSpectatorModalEvent(event);
      spectatorSeaChoiceModal(detail);
    } else {
      clearPinnedSpectatorModalEvent();
      if (detail.kind === "sea-result") spectatorSeaEventResultModal(detail);
      else if (detail.kind === "chest-result") spectatorCardResultModal(detail);
      else if (detail.kind === "shop") spectatorShopModal(detail);
      else if (detail.kind === "hospital") spectatorHospitalModal(detail);
      else if (detail.kind === "research-lab") spectatorResearchLabModal(detail);
      else if (detail.kind === "arena") spectatorArenaModal(detail);
      else if (detail.kind === "judicial-raid") spectatorJudicialRaidModal(detail);
      else if (detail.kind === "tavern") spectatorTavernModal(detail);
      else if (detail.kind === "tavern-result") spectatorTavernResultModal(detail);
      else if (detail.kind === "battle-rewards") spectatorBattleRewardsModal(detail);
      else if (detail.kind === "mission-board") spectatorMissionBoardModal(detail);
      else showBoardUiHud(event.title || "行動同步", event.subtitle || "觀看操作方行動。", { theme: "event", symbol: "看" });
    }
  }

  function emitTurnHandoffEvent(player, data = {}) {
    if (!player) return null;
    const duration = data.duration || (isCpuPlayer(player)
      ? cpuTurnDelay(TURN_HANDOFF_BANNER_DURATION_MS, player, 1900)
      : TURN_HANDOFF_BANNER_DURATION_MS);
    const transitionDelay = data.transitionDelay || (isCpuPlayer(player)
      ? cpuTurnDelay(TURN_HANDOFF_TRANSITION_DELAY_MS, player, 1450)
      : TURN_HANDOFF_TRANSITION_DELAY_MS);
    return emitBoardUiEvent("turn-banner", {
      player,
      title: "",
      subtitle: data.subtitle || (data.context === "battle" ? "準備接手戰鬥。" : "準備擲骰前進。"),
      context: data.context || "map",
      color: turnTransitionColorForPlayer(player),
      avatar: player.avatar || 1,
      userId: player.userId || player.id || "",
      clientId: player.clientId || "",
      duration,
      transitionDelay,
      waitUntilEnd: !!data.waitUntilEnd,
    }, { immediate: true });
  }

  function runAfterTurnHandoffBanner(player, callback, options = {}) {
    if (!player) {
      callback?.();
      return 0;
    }
    setTurnHandoffVisualLock(true);
    const event = emitTurnHandoffEvent(player, options);
    const delay = Math.max(0, Number(handleBoardUiEvent(event) || event?.transitionDelay || TURN_HANDOFF_TRANSITION_DELAY_MS));
    window.setTimeout(() => {
      try {
        callback?.();
      } finally {
        setTurnHandoffVisualLock(false);
      }
    }, delay);
    return delay;
  }

  function handleBoardUiEvent(event = {}) {
    if (!event?.id || handledBoardUiEventIds.has(event.id)) return 0;
    handledBoardUiEventIds.add(event.id);
    if (handledBoardUiEventIds.size > 120) {
      Array.from(handledBoardUiEventIds).slice(0, 40).forEach((id) => handledBoardUiEventIds.delete(id));
    }
    const playerName = event.playerName || "玩家";
    if (event.type === "turn-banner") {
      return showTurnTransitionBanner(event);
    }
    if (event.type === "postgame-world-unlock") {
      return playPostgameWorldUnlockCinematic(event);
    }
    if (event.type === "postgame-egghead-reveal") {
      return playPostgameEggheadRevealCinematic(event);
    }
    if (event.type === "final-boss-voyage") {
      return playFinalBossVoyageCinematic(event);
    }
    if (event.type === "spectator-modal") {
      if (event.detail?.kind === "sea-choice") {
        const player = currentPlayer();
        const ownsChoice = player
          && String(event.playerId || event.userId || "") === String(player.id || player.userId || "")
          && canBoardLanControlCurrentPlayer(player);
        const tile = ownsChoice && player.location?.kind === "route"
          ? getTileByLocation(player.location.routeId, player.location.tileIndex)
          : null;
        if (tile) {
          clearPinnedSpectatorModalEvent();
          openSeaEventChoice(player, tile, { recovered: true, choices: event.detail.choices });
          return 0;
        }
      }
      openSpectatorBoardModal(event);
      return 0;
    }
    if (event.type === "draft-wheel") {
      showSynchronizedDraftWheel(event);
      return 0;
    }
    if (event.type === "dice") {
      const maxFace = Math.max(1, Math.round(Number(event.maxFace || 6)));
      void animateDice(
        event.theme || "move",
        event.title || `${playerName} 擲骰`,
        event.subtitle || "骰面正在翻滾…",
        maxFace,
        {
          settle: event.result,
          settleDelay: event.settleDelay,
          faceLabels: event.faceLabels,
        }
      );
      return 0;
    }
    if (event.type === "sea-encounter") {
      void playSeaEncounterSplash(event.enemyName || "敵人");
      showBoardUiHud(event.title || "敵影襲來", event.subtitle || `${event.enemyName || "敵人"} 襲來！`, { theme: "battle", symbol: "!" });
      return 0;
    }
    showBoardUiHud(
      event.title || "行動同步",
      event.subtitle || `${playerName} 正在行動。`,
      { theme: event.theme || "event", symbol: event.symbol || "", duration: event.duration || 1700 }
    );
    return 0;
  }

  function battleWindowIsActive() {
    return !!state.battleState && !!state.battleWindow && !state.battleWindow.closed;
  }

  function battleDiceBonusText(category, settle) {
    if (category === "combo") {
      return `連擊倍率 x${comboDiceMultiplier(settle).toFixed(2)}`;
    }
    if (category === "attack" || category === "special") {
      return `傷害加成 x${attackDiceMultiplier(settle).toFixed(2)}`;
    }
    if (category === "heal") {
      return `回復加成 x${healDiceMultiplier(settle).toFixed(2)}`;
    }
    const delta = statusDiceDelta(settle);
    if (delta > 0) return `狀態加成 +${delta}`;
    if (delta < 0) return `狀態加成 ${delta}`;
    return "標準效果";
  }

  function enemyExtraDiceThreshold(enemyOrTier) {
    const tier = legacyTier(typeof enemyOrTier === "string" ? enemyOrTier : (enemyOrTier?.tier || ""));
    if (tier === "T1") return 4;
    if (tier === "T2") return 5;
    if (tier === "T3") return 6;
    return 0;
  }

  function extraBattleDiceRule(side, player, battle) {
    if (side === "player") {
      const threshold = Number(getTeamEffects(player).battleExtraDiceThreshold || 0);
      return threshold ? {
        threshold,
        title: "戰鬥型被動：追加戰鬥骰",
        banner: "戰鬥型被動發動",
        logLabel: "戰鬥型被動",
      } : null;
    }
    const enemyTier = legacyTier(battle?.enemyCombatant?.tier || battle?.enemyTier || "");
    const threshold = enemyExtraDiceThreshold(enemyTier);
    return threshold ? {
      threshold,
      title: `${tierLabel(enemyTier)}級敵人壓迫：追加戰鬥骰`,
      banner: `${tierLabel(enemyTier)}級敵人壓迫`,
      logLabel: `${tierLabel(enemyTier)}級敵人壓迫`,
    } : null;
  }

  function rocksEclipseThirdDiceThreshold(side, player, battle, firstExtraDiceThreshold) {
    if (!player || !battle || !firstExtraDiceThreshold) return 0;
    if (side === "enemy") {
      const eclipseSlot = postgameBossMechanicBulletEffectSlots(battle, "postgame_rocks_eclipse")[0];
      if (!eclipseSlot) return 0;
      const effect = battleCarryItemEffect(eclipseSlot.itemId);
      const thresholdMap = effect.thirdDieThresholdByFirstThreshold || {};
      return Math.max(0, Number(thresholdMap[firstExtraDiceThreshold] || 0));
    }
    if (side !== "player") return 0;
    const activeCard = battleActiveCard(player, battle);
    const activeIndex = Math.max(0, Number(battle.activeCrewIndex || 0));
    if (!activeCard || postgameBulletCarryIsAbsorbed(battle, activeCard, activeIndex)) return 0;
    const effect = battleCarryItemsForCard(activeCard).map(battleCarryItemEffect).find((entry) => entry.kind === "postgame_rocks_eclipse" && entry.enableThirdBattleDie);
    if (!effect) return 0;
    const thresholdMap = effect.thirdDieThresholdByFirstThreshold || {};
    return Math.max(0, Number(thresholdMap[firstExtraDiceThreshold] || 0));
  }

  function maximumBattleActionDiceTotal(side, player, battle) {
    const rule = extraBattleDiceRule(side, player, battle);
    if (!rule?.threshold) return 6;
    return rocksEclipseThirdDiceThreshold(side, player, battle, rule.threshold) ? 18 : 12;
  }

  function battleDiceSideLabel(side) {
    return "";
  }

  function battleDiceActorName(title, battle, options = {}) {
    if (options.actorName) return String(options.actorName);
    const side = options.side === "enemy" ? "enemy" : options.side === "player" ? "player" : "";
    const player = battlePlayer(null, battle);
    if (side === "player") return battleActiveCard(player, battle)?.name || player?.name || "";
    if (side === "enemy") return battle?.enemyCombatant?.name || "敵人";
    const match = String(title || "").match(/^(.+?)(?:\s+使用|\s+嘗試| 的|：)/);
    return match?.[1] || "";
  }

  function battleVisualEventTargetSide(event = {}) {
    const explicit = String(event.targetSide || "").trim();
    if (explicit === "player" || explicit === "enemy") return explicit;
    const actorSide = event.side === "enemy" ? "enemy" : event.side === "player" ? "player" : "";
    if (!actorSide) return "";
    const moveType = String(event.moveType || event.type || "").toLowerCase();
    if (event.type === "heal" || ["heal", "buff", "shield", "support"].includes(moveType)) return actorSide;
    if (event.type === "attack" || ["attack", "special", "combo", "debuff", "control", "status"].includes(moveType)) {
      return actorSide === "player" ? "enemy" : "player";
    }
    return actorSide;
  }

  function attachBattleVisualEventSnapshots(event = {}, battle = state.battleState) {
    const player = battlePlayer(null, battle);
    if (!player || !battle) return event;
    const snapshot = getBattleVisualSnapshot(player, battle);
    if (!snapshot) return event;
    const actorSide = event.side === "enemy" ? "enemy" : event.side === "player" ? "player" : "";
    const targetSide = battleVisualEventTargetSide(event);
    event.finalSnapshot = safeJsonClone(snapshot);
    if (actorSide) event.actorCombatant = battleVisualSnapshotSide(snapshot, actorSide);
    if (targetSide) {
      event.targetSide = targetSide;
      event.targetCombatant = battleVisualSnapshotSide(snapshot, targetSide);
    }
    return event;
  }

  function emitBattleKnockoutEvent(side, battle, targetName) {
    const event = {
      id: `knockout-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      type: "knockout",
      side,
      targetName,
      duration: 4250,
    };
    battle.visualEvent = event;
    notifyBattleWindow();
    return event;
  }

  async function rollBattleActionDice(theme, title, subtitle, battle, maxFace = 6, options = {}) {
    const rollMaxFace = Math.max(1, Math.round(Number(maxFace || 6)));
    const forcedParity = normalizeBattleFirstDiceParity(options.forcedFirstDiceParity);
    const allowedFaces = forcedParity
      ? Array.from({ length: rollMaxFace }, (_value, index) => index + 1).filter((face) => (forcedParity === "odd" ? face % 2 === 1 : face % 2 === 0))
      : [];
    const settle = allowedFaces.length
      ? allowedFaces[randomInt(0, allowedFaces.length - 1)]
      : randomInt(1, rollMaxFace);
    const parityLabel = forcedParity === "odd" ? "單數骰子" : forcedParity === "even" ? "雙數骰子" : "";
    const displaySubtitle = parityLabel ? `${subtitle || "決定招式最終效果…"}｜${parityLabel}生效` : subtitle;
    if (options.suppressVisual) {
      battle.log.push(`${title}：${parityLabel ? `${parityLabel}生效，` : ""}擲出加成骰 ${settle}。`);
      return settle;
    }
    if (state.battleState && refs.modalBack?.classList.contains("open") && document.getElementById("battleCinematic")) {
      return playBattleDiceAnimation({ title, subtitle: displaySubtitle, maxFace: rollMaxFace, theme, settle });
    }
    if (!battleWindowIsActive()) {
      return animateDice(theme, title, displaySubtitle, rollMaxFace, { settle });
    }
    const duration = Math.max(1200, Number(options.duration || 1650));
    const actorName = battleDiceActorName(title, battle, options);
    const sideLabel = battleDiceSideLabel(options.side || "");
    battle.visualEvent = attachBattleVisualEventSnapshots({
      id: `dice-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      type: "dice",
      theme,
      title,
      subtitle: displaySubtitle,
      maxFace: rollMaxFace,
      settle,
      side: options.side || "",
      sideLabel,
      actorName,
      moveType: options.moveType || theme,
      isExtraDice: !!options.isExtraDice,
      extraDiceOrdinal: Number(options.extraDiceOrdinal || 0),
      firstDie: options.firstDie || 0,
      secondDie: options.secondDie || 0,
      triggerThreshold: options.triggerThreshold || 0,
      extraDiceReason: options.extraDiceReason || "",
      forcedFirstDiceParity: forcedParity,
      parityConstraintLabel: parityLabel,
      castSfx: options.isExtraDice ? "" : (options.castSfx || ""),
      bonusText: battleDiceBonusText(options.moveType || theme, settle),
      duration,
    }, battle);
    battle.log.push(`${title}：${parityLabel ? `${parityLabel}生效，` : ""}擲出加成骰 ${settle}。`);
    notifyBattleWindow();
    await wait(duration + 620);
    return settle;
  }

  async function rollBattleActionDiceWithPassives(theme, title, subtitle, battle, maxFace = 6, options = {}) {
    const side = options.side === "enemy" ? "enemy" : "player";
    const actorRound = side === "player" ? battle.playerRoundEffects : battle.enemyCombatant?.roundEffects;
    const adjustedMaxFace = Math.max(1, Number(maxFace || 6) - Math.max(0, Number(actorRound?.diceCapDown || 0)));
    const player = battlePlayer(null, battle);
    const parityEntry = battleFirstDiceParityEntry(side, battle, player);
    const first = await rollBattleActionDice(theme, title, subtitle, battle, adjustedMaxFace, {
      ...options,
      forcedFirstDiceParity: parityEntry?.parity || "",
    });
    if (parityEntry) {
      const remaining = consumeBattleFirstDiceParityEffect(side, battle, player);
      battle.log.push(`${parityEntry.parity === "odd" ? "單數骰子" : "雙數骰子"}完成一次第一骰控制，剩餘 ${remaining} 次。`);
    }
    if (typeof options.onFirstDie === "function") options.onFirstDie(first);
    const rule = extraBattleDiceRule(side, player, battle);
    if (!rule?.threshold || first < rule.threshold) {
      if (typeof options.onDiceResolved === "function") options.onDiceResolved([first], first);
      return first;
    }
    const actorName = battleDiceActorName(title, battle, options);
    const second = await rollBattleActionDice(theme, rule.title, `第一顆骰出 ${first}，達到 ${rule.threshold}+，觸發第二顆骰，兩顆相加計算倍率。`, battle, 6, {
      ...options,
      actorName,
      isExtraDice: true,
      extraDiceOrdinal: 2,
      forcedFirstDiceParity: "",
      firstDie: first,
      triggerThreshold: rule.threshold,
      extraDiceReason: rule.logLabel,
    });
    const thirdThreshold = rocksEclipseThirdDiceThreshold(side, player, battle, rule.threshold);
    let third = 0;
    if (thirdThreshold && second >= thirdThreshold) {
      third = await rollBattleActionDice(theme, "名刀『日蝕』：第三顆戰鬥骰", `第二顆骰出 ${second}，達到 ${thirdThreshold}+，觸發第三顆骰，三顆相加計算倍率。`, battle, 6, {
        ...options,
        actorName,
        isExtraDice: true,
        extraDiceOrdinal: 3,
        forcedFirstDiceParity: "",
        firstDie: first,
        secondDie: second,
        triggerThreshold: thirdThreshold,
        extraDiceReason: "名刀『日蝕』",
      });
    }
    const total = first + second + third;
    if (typeof options.onDiceResolved === "function") {
      options.onDiceResolved(third ? [first, second, third] : [first, second], total);
    }
    battle.log.push(third
      ? `${actorName ? `${actorName}的` : ""}${rule.logLabel}先以第一顆 ${first} 達到 ${rule.threshold}+；名刀『日蝕』再以第二顆 ${second} 達到 ${thirdThreshold}+，追加第三顆 ${third}，合計 ${total}。`
      : `${actorName ? `${actorName}的` : ""}${rule.logLabel}觸發：第一顆 ${first} 達到 ${rule.threshold}+，追加骰 ${second}，合計 ${total}。`);
    if (!options.suppressVisual) {
      battle.visualEvent = attachBattleVisualEventSnapshots({
        id: `extra-dice-total-${Date.now()}-${Math.random().toString(36).slice(2)}`,
        type: "bonus",
        theme,
        title: rule.banner,
        subtitle: third
          ? `第一顆 ${first} + 第二顆 ${second} + 第三顆 ${third}`
          : `第一顆 ${first} + 第二顆 ${second}`,
        maxFace,
        settle: total,
        firstDie: first,
        secondDie: second,
        thirdDie: third,
        side: options.side || "",
        sideLabel: battleDiceSideLabel(options.side || ""),
        actorName,
        extraDiceReason: third ? "名刀『日蝕』" : rule.logLabel,
        triggerThreshold: third ? thirdThreshold : rule.threshold,
        moveType: options.moveType || theme,
        bonusText: `總點數 ${total}，${battleDiceBonusText(options.moveType || theme, total)}`,
        duration: 1800,
      }, battle);
      notifyBattleWindow();
      await wait(1800);
    }
    return total;
  }

