  let reverseMountainStoryActive = false;

  function openingStorySessionSeeds() {
    try {
      const value = JSON.parse(sessionStorage.getItem(OPENING_STORY_SESSION_KEY) || "[]");
      return Array.isArray(value) ? value.map((entry) => String(entry || "")).filter(Boolean) : [];
    } catch (_) {
      return [];
    }
  }

  function openingStorySeenThisSession(seed) {
    return openingStorySessionSeeds().includes(String(seed || ""));
  }

  function markOpeningStorySeenThisSession(seed) {
    const key = String(seed || "");
    if (!key) return;
    const seeds = openingStorySessionSeeds().filter((entry) => entry !== key);
    seeds.push(key);
    try {
      sessionStorage.setItem(OPENING_STORY_SESSION_KEY, JSON.stringify(seeds.slice(-16)));
    } catch (_) {}
  }

  function isFreshOpeningSetupState(game = state.gameState) {
    if (!game || game.phase !== "setup-order") return false;
    if ((game.draftOrder || []).length || (game.draftSequence || []).length || Number(game.draftPickIndex || 0) > 0) return false;
    return (game.players || []).every((player) => !(player.crew || []).length && !(player.recruitRolls || []).length);
  }

  function shouldPlayOpeningStory(options = {}) {
    if (options.force) return true;
    if (options.skipOpeningStory || query.get("skipOpeningStory") === "1") return false;
    if (!isFreshOpeningSetupState()) return false;
    if (boardLan.enabled && boardLan.awaitingInitialState) return false;
    return !openingStorySeenThisSession(state.gameState?.seed);
  }

  function cancelOpeningStorySession() {
    openingStoryActive = false;
    openingStorySeed = "";
  }

  function startOpeningStory(options = {}) {
    if (!shouldPlayOpeningStory(options)) return false;
    const seed = String(state.gameState?.seed || "");
    openingStoryActive = true;
    openingStorySeed = seed;
    markOpeningStorySeenThisSession(seed);
    preloadFinalEndingAssets(OPENING_STORY_DEFINITION);
    playBgmForContext({ phase: "story", sceneType: "opening", eventTags: ["roger", "great_pirate_age", "journey_start"], storyMood: "epic" });
    startFinalEndingCinematicSession(currentPlayer(), OPENING_STORY_DEFINITION, () => {
      const sameSetup = String(state.gameState?.seed || "") === seed && String(state.gameState?.phase || "").startsWith("setup");
      cancelOpeningStorySession();
      closeModal();
      if (sameSetup) openSetupStep({ skipOpeningStory: true });
    });
    return true;
  }

