  function normalizeFinalEndingState(player) {
    state.gameState.finalEndingRecords = state.gameState.finalEndingRecords && typeof state.gameState.finalEndingRecords === "object" ? state.gameState.finalEndingRecords : {};
    if (!player) return;
    player.finalEndingSeen = Array.isArray(player.finalEndingSeen)
      ? [...new Set(player.finalEndingSeen.map((id) => String(id || "").trim()).filter(Boolean))]
      : [];
    player.finalEndingChoice = String(player.finalEndingChoice || "");
    player.finalEndingCleared = Boolean(player.finalEndingCleared);
  }

  function playerClearedFinalGate(player) {
    if (!player) return false;
    if (player.finalGateDefeated) return true;
    if (state.gameState.finalGateDefeatedBy?.[player.id]) {
      player.finalGateDefeated = true;
      return true;
    }
    return false;
  }

  function crewHasNicoRobin(player) {
    return (player?.crew || []).some((card) => {
      const text = `${card?.id || ""} ${card?.name || ""} ${card?.baseName || ""}`.toLowerCase();
      return text.includes("robin") || text.includes("羅賓") || text.includes("妮可");
    });
  }

  function finalEndingLivingCrewCount(player) {
    return (player?.crew || []).filter((card) => Number(card?.currentHp ?? cardMaxHp(card)) > 0).length;
  }

  function playerDefeatedAllYonkoGlyphs(player) {
    const defeated = new Set(Array.isArray(player?.defeatedYonkoGlyphs) ? player.defeatedYonkoGlyphs : []);
    return Object.keys(ROAD_PONEGLYPH_BY_GLYPH).every((glyphId) => defeated.has(glyphId));
  }

  function finalEndingEligibility(player, endingId) {
    const ending = FINAL_ENDING_DEFS[endingId];
    if (!ending) return { ok: false, reason: "未知結局。" };
    syncPlayerRoadPoneglyphsFromInventory(player);
    if (!state.gameState.finalIslandUnlocked) return { ok: false, reason: "最終之島尚未啟動。" };
    if (!playerHasAllRoadPoneglyphs(player)) return { ok: false, reason: "需要四份歷史本文拓本。" };
    if (!playerClearedFinalGate(player)) return { ok: false, reason: "需要先在最終之島連接點擊退伊姆。" };
    if (endingId === "treasure_banquet") return { ok: true, reason: "" };
    if (endingId === "true_history") {
      const watchtowerLevel = playerShipUpgradeLevel(player, "watchtower");
      if (crewHasNicoRobin(player) || watchtowerLevel >= 3) return { ok: true, reason: "" };
      return { ok: false, reason: ending.lockedText };
    }
    if (endingId === "dawn_alliance") {
      if (playerDefeatedAllYonkoGlyphs(player) && finalEndingLivingCrewCount(player) >= 6) return { ok: true, reason: "" };
      return { ok: false, reason: ending.lockedText };
    }
    return { ok: false, reason: ending.lockedText };
  }

  function finalEndingChoiceMarkup(player) {
    normalizeFinalEndingState(player);
    const crewCount = finalEndingLivingCrewCount(player);
    const glyphCount = playerRoadPoneglyphCount(player);
    const defeatedYonkoCount = new Set(Array.isArray(player.defeatedYonkoGlyphs) ? player.defeatedYonkoGlyphs : []).size;
    const choices = FINAL_ENDING_ORDER.map((endingId) => {
      const ending = FINAL_ENDING_DEFS[endingId];
      const eligibility = finalEndingEligibility(player, endingId);
      const seen = player.finalEndingSeen.includes(endingId);
      const classes = ["final-ending-choice-card", `tone-${ending.tone}`, eligibility.ok ? "available" : "locked", seen ? "seen" : ""].filter(Boolean).join(" ");
      return `
        <button type="button" class="${classes}" data-final-ending-choice="${escapeModalText(endingId)}" ${eligibility.ok ? "" : "disabled"}>
          <span class="final-ending-choice-badge">${escapeModalText(ending.badge)}${seen ? "・已看過" : ""}</span>
          <strong>${escapeModalText(ending.title)}</strong>
          <span>${escapeModalText(ending.summary)}</span>
          <small>${eligibility.ok ? escapeModalText(ending.condition) : escapeModalText(eligibility.reason)}</small>
        </button>
      `;
    }).join("");
    return `
      <div class="final-ending-screen final-ending-route-select">
        <div class="final-ending-map-glow" aria-hidden="true"></div>
        <div class="final-ending-choice-shell">
          <p class="final-ending-kicker">最終之島・拉夫德魯</p>
          <h2>選擇這趟航海留下的結局</h2>
          <p class="final-ending-lead">你們已經穿過四皇的航路、擊退伊姆的阻擋。結局只會在抵達最終之島後出現，每條路線會用不同角度收束這局冒險。</p>
          <div class="final-ending-status-row">
            <span>拓本 ${glyphCount}/4</span>
            <span>四皇 ${defeatedYonkoCount}/4</span>
            <span>可戰鬥夥伴 ${crewCount}/6</span>
            <span>伊姆 ${playerClearedFinalGate(player) ? "已擊退" : "未擊退"}</span>
          </div>
          <div class="final-ending-choice-grid">
            ${choices}
          </div>
        </div>
      </div>
    `;
  }

  function openFinalIslandEndingChoice(player) {
    startFinalIslandAutoEnding(player);
  }

  function playerCompletedFinalIslandEnding(player) {
    if (!player) return false;
    normalizeFinalEndingState(player);
    const record = state.gameState.finalEndingRecords?.[player.id] || null;
    if (record && !player.finalEndingCleared) player.finalEndingCleared = true;
    return Boolean(player.finalEndingCleared || record);
  }

  function finalIslandRevisitRecord(player) {
    const record = state.gameState.finalEndingRecords?.[player?.id]
      || (String(state.gameState.finalEndingLast?.playerId || "") === String(player?.id || "") ? state.gameState.finalEndingLast : null)
      || null;
    const endingId = String(record?.endingId || player?.finalEndingChoice || "treasure_banquet");
    const ending = FINAL_ENDING_DEFS[endingId] || FINAL_ENDING_DEFS.treasure_banquet;
    return {
      endingId,
      endingTitle: String(record?.title || ending?.title || "最終結局"),
      round: Math.max(0, Number(record?.round || 0)),
    };
  }

  function applyFinalIslandDawnBanquet(player, island) {
    const service = HOSPITAL_SERVICES.find((entry) => entry.id === "full_crew_restore") || HOSPITAL_SERVICES[0];
    const neededRecovery = (player?.crew || []).some((card) => (
      Number(card?.currentHp || 0) < Number(card?.baseStats?.hp || 0)
      || (card?.moveSet || []).some((move) => Number(move?.currentPP || 0) < Number(move?.pp || 0))
      || Object.values(card?.currentStages || {}).some((value) => Number(value || 0) !== 0)
    ));
    const serviceSummary = service?.apply?.(player) || "全隊 HP / PP 已完全恢復";
    (player?.crew || []).forEach((card) => {
      card.currentHp = Number(card?.baseStats?.hp || card?.currentHp || 0);
    });
    const summary = neededRecovery ? serviceSummary : "全隊已處於最佳狀態";
    addLog(`${player.name} 在 ${island?.name || "最終之島"} 舉辦黎明宴會：${summary}。`);
    if (neededRecovery) {
      recordMissionEvent(player, { type: "island_service", islandKind: "final", service: "dawn_banquet" });
    }
    emitBoardActionNotice("service", "黎明宴會", `${player.name} 在拉夫德魯完成全隊整備`, {
      player,
      theme: "final",
      symbol: "宴",
    }, { immediate: true });
    scheduleBoardLanStatePush("final-island-dawn-banquet", 80, { force: true });
    return summary;
  }

  function finalIslandBossVoyageUnlockedCount(player) {
    return postgameBossVoyageEntries(player).filter((entry) => entry.unlocked).length;
  }

  function finalIslandBossVoyageCpuScore(player, entry) {
    if (!entry?.unlocked || !entry.assignment || !entry.profile) return -Infinity;
    let score = entry.ownsRelic ? 0 : 10000;
    const living = (player.crew || []).filter((card) => Number(card?.currentHp || 0) > 0);
    living.forEach((card) => {
      if (ATTRIBUTE_ADVANTAGE[card.attribute] === entry.profile.attribute) score += 150;
      if (ATTRIBUTE_ADVANTAGE[entry.profile.attribute] === card.attribute) score -= 90;
      score += Math.max(Number(card.atk || card.baseStats?.atk || 0), Number(card.satk || card.baseStats?.satk || 0)) * 0.05;
    });
    score -= Number(entry.profile.recommendedPower || 0) * 0.3;
    score -= entry.bossDef.clueNumber * 0.001;
    return score;
  }

  function selectFinalIslandBossVoyageForCpu(player) {
    return postgameBossVoyageEntries(player)
      .filter((entry) => entry.unlocked && entry.assignment && entry.island)
      .sort((a, b) => finalIslandBossVoyageCpuScore(player, b) - finalIslandBossVoyageCpuScore(player, a))[0] || null;
  }

  function finalIslandBossVoyageDetailMarkup(player, entry) {
    if (!entry) {
      return `
        <section class="final-boss-compass-detail is-empty">
          <div class="final-boss-compass-empty-mark"><img src="images/board/attribute_icons/neutral.webp" alt="" aria-hidden="true"></div>
          <h3>尚未取得可轉送的座標</h3>
          <p>擊敗無風帶孤島 Boss 或從其他玩家交易取得線索牌後，大熊就能依照永久記錄的座標進行轉送。</p>
        </section>
      `;
    }
    const bossDef = entry.bossDef;
    const profile = entry.profile || {};
    const relic = entry.relicDef || {};
    const portrait = getBattlePortraitUrl(profile, "normal") || battleEnemyPortraitsFor(bossDef.key).normal;
    const relicEffect = relic.uiSummary || relic.description || relic.summary || battleCarryItemSummary(entry.relicItemId);
    return `
      <section class="final-boss-compass-detail">
        <div class="final-boss-compass-visual">
          <img class="final-boss-compass-island" src="${escapeModalText(bossDef.islandImage)}" alt="${escapeModalText(entry.island?.name || bossDef.name)}" onerror="this.src='${escapeModalText(ISLAND_IMAGE_MAP.postgame_boss)}';">
          <img class="final-boss-compass-boss" src="${escapeModalText(portrait)}" alt="${escapeModalText(bossDef.name)}" onerror="this.hidden=true;">
          <span class="final-boss-compass-rank">${escapeModalText(postgameClueCardLabel(bossDef.clueNumber))}</span>
        </div>
        <div class="final-boss-compass-copy">
          <span class="final-boss-compass-kicker">肉球目的地 ${String(bossDef.clueNumber).padStart(2, "0")}</span>
          <h3>${escapeModalText(bossDef.name)}</h3>
          <p>${escapeModalText(profile.role || "終局 Boss")}・${escapeModalText(profile.attribute || "未知")}屬性</p>
          <div class="final-boss-compass-facts">
            <span><b>目的地</b>${escapeModalText(entry.island?.name || "無風帶孤島")}</span>
            <span><b>目前線索</b>${entry.currentClueCount} 張${entry.currentClueCount <= 0 ? "（已交易，座標仍保留）" : ""}</span>
            <span><b>專屬掉落</b>${escapeModalText(relic.name || "未登錄")}${entry.ownsRelic ? "・已持有" : "・尚未持有"}</span>
          </div>
          <div class="final-boss-compass-relic">
            ${entry.relicItemId ? itemIconMarkup(relic, "final-boss-compass-relic-icon") : ""}
            <span><strong>${escapeModalText(relic.name || "專屬攜帶物")}</strong><small>${escapeModalText(relicEffect || "效果未登錄。")}</small></span>
          </div>
          <p class="final-boss-compass-rule">確認後只登記目的地並消耗本回合，不會立刻播放動畫；下次輪到你時，大熊才從拉夫德魯把整艘船拍進肉球氣泡，完整飛往目標 Boss 島。</p>
        </div>
      </section>
    `;
  }

  function openFinalIslandBossVoyageCompass(player, island, selectedBossKey = "") {
    if (!player || !island || warnBoardLanTurnLocked(player)) return false;
    if (normalizePendingPostgameBossVoyage(player)) return false;
    const entries = postgameBossVoyageEntries(player);
    const unlockedEntries = entries.filter((entry) => entry.unlocked && entry.assignment && entry.island);
    const selected = unlockedEntries.find((entry) => entry.bossDef.key === selectedBossKey) || unlockedEntries[0] || null;
    const selectedIndex = selected ? entries.findIndex((entry) => entry.bossDef.key === selected.bossDef.key) : 0;
    const cards = entries.map((entry, index) => {
      const bossDef = entry.bossDef;
      const clueDef = gameItemDef(bossDef.clueItemId) || { id: bossDef.clueItemId, name: `約克的線索 ${bossDef.clueNumber}`, kind: "postgame-clue", effect: { kind: "postgame_york_clue", bossKey: bossDef.key, clueNumber: bossDef.clueNumber } };
      const selectedClass = selected?.bossDef.key === bossDef.key ? " is-selected" : "";
      const lockedClass = entry.unlocked ? "" : " is-locked";
      let coverOffset = index - selectedIndex;
      if (coverOffset > entries.length / 2) coverOffset -= entries.length;
      if (coverOffset < entries.length / -2) coverOffset += entries.length;
      const coverDistance = Math.abs(coverOffset);
      const coverScale = coverDistance === 0 ? 1.12 : Math.max(0.54, 0.9 - (coverDistance * 0.105));
      const coverOpacity = coverDistance > 4 ? 0 : Math.max(0.34, 1 - (coverDistance * 0.13));
      const coverAngle = coverOffset === 0 ? 0 : (coverOffset < 0 ? 58 : -58);
      const coverHiddenClass = coverDistance > 4 ? " is-cover-hidden" : "";
      return `
        <button type="button" class="final-boss-compass-card${selectedClass}${lockedClass}${coverHiddenClass}" style="--cover-offset:${coverOffset};--cover-scale:${coverScale};--cover-opacity:${coverOpacity};--cover-angle:${coverAngle}deg;--cover-order:${20 - coverDistance}" data-final-boss-voyage-key="${escapeModalText(bossDef.key)}" ${entry.unlocked && entry.assignment ? "" : "disabled"} aria-pressed="${selectedClass ? "true" : "false"}" aria-label="${escapeModalText(entry.unlocked ? bossDef.name : `未解鎖線索牌 ${postgameClueCardLabel(bossDef.clueNumber)}`)}">
          ${itemIconMarkup(clueDef, "final-boss-compass-card-art", { portraitImage: bossDef.islandImage })}
          <span>${escapeModalText(entry.unlocked ? bossDef.name : "未解鎖")}</span>
        </button>
      `;
    }).join("");
    openModal(`
      <section class="final-boss-compass-screen" aria-labelledby="finalBossCompassTitle">
        <div class="final-boss-compass-bg" aria-hidden="true"></div>
        <header class="final-boss-compass-heading">
          <span>LAUGH TALE・PAW-PAW TRANSFER</span>
          <h2 id="finalBossCompassTitle">大熊的肉球航路</h2>
          <p>左右循環選擇永久記錄的約克線索牌，再把目的地交給大熊；線索已交易出去也不會失去座標。</p>
        </header>
        <div class="final-boss-compass-layout">
          <div class="final-boss-compass-stage" id="finalBossCoverFlowStage" tabindex="0" aria-label="十三張 Boss 線索牌左右循環選擇">
            <div class="final-boss-coverflow-floor" aria-hidden="true"></div>
            <div class="final-boss-compass-card-ring">${cards}</div>
            <button type="button" class="final-boss-coverflow-arrow previous" id="finalBossCoverFlowPrevious" aria-label="上一張線索牌">‹</button>
            <button type="button" class="final-boss-coverflow-arrow next" id="finalBossCoverFlowNext" aria-label="下一張線索牌">›</button>
            <div class="final-boss-compass-core-copy"><strong>${selected ? `${String(selectedIndex + 1).padStart(2, "0")} / 13` : `0 / 13`}</strong><span>左右選擇・循環</span></div>
          </div>
          ${finalIslandBossVoyageDetailMarkup(player, selected)}
        </div>
        <footer class="final-boss-compass-actions">
          <button type="button" class="modal-btn secondary" id="finalBossCompassBackBtn">返回黎明紀錄殿</button>
          <button type="button" class="modal-btn primary" id="finalBossCompassConfirmBtn" ${selected ? "" : "disabled"}>把目的地交給大熊</button>
        </footer>
      </section>
    `, "final-boss-compass-fullscreen-modal force-choice no-backdrop-close");
    refs.modal.querySelectorAll("[data-final-boss-voyage-key]").forEach((button) => {
      button.addEventListener("click", () => openFinalIslandBossVoyageCompass(player, island, button.dataset.finalBossVoyageKey));
    });
    const moveCoverFlow = (direction) => {
      if (unlockedEntries.length <= 0) return;
      const currentIndex = Math.max(0, unlockedEntries.findIndex((entry) => entry.bossDef.key === selected?.bossDef.key));
      const nextIndex = (currentIndex + direction + unlockedEntries.length) % unlockedEntries.length;
      openFinalIslandBossVoyageCompass(player, island, unlockedEntries[nextIndex].bossDef.key);
    };
    document.getElementById("finalBossCoverFlowPrevious")?.addEventListener("click", () => moveCoverFlow(-1));
    document.getElementById("finalBossCoverFlowNext")?.addEventListener("click", () => moveCoverFlow(1));
    const coverFlowStage = document.getElementById("finalBossCoverFlowStage");
    coverFlowStage?.addEventListener("keydown", (event) => {
      if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
      event.preventDefault();
      moveCoverFlow(event.key === "ArrowLeft" ? -1 : 1);
    });
    coverFlowStage?.addEventListener("wheel", (event) => {
      if (Math.abs(event.deltaX) < 8 && Math.abs(event.deltaY) < 8) return;
      event.preventDefault();
      moveCoverFlow((Math.abs(event.deltaX) > Math.abs(event.deltaY) ? event.deltaX : event.deltaY) < 0 ? -1 : 1);
    }, { passive: false, once: true });
    let coverFlowTouchX = null;
    coverFlowStage?.addEventListener("touchstart", (event) => {
      coverFlowTouchX = Number(event.touches?.[0]?.clientX);
    }, { passive: true });
    coverFlowStage?.addEventListener("touchend", (event) => {
      const endX = Number(event.changedTouches?.[0]?.clientX);
      if (!Number.isFinite(coverFlowTouchX) || !Number.isFinite(endX) || Math.abs(endX - coverFlowTouchX) < 28) return;
      moveCoverFlow(endX > coverFlowTouchX ? -1 : 1);
      coverFlowTouchX = null;
    }, { passive: true });
    document.getElementById("finalBossCompassBackBtn")?.addEventListener("click", () => openFinalIslandRevisitModal(player, island));
    document.getElementById("finalBossCompassConfirmBtn")?.addEventListener("click", () => {
      if (selected) void startFinalIslandBossVoyage(player, island, selected);
    });
    if (!selectedBossKey) {
      emitSpectatorModalEvent("final-boss-voyage-compass", player, {
        title: "大熊的肉球航路",
        subtitle: `${player.name} 正在請大熊確認 Boss 島座標。`,
      });
    }
    return true;
  }

  function clearFinalBossVoyageCinematic() {
    if (finalBossVoyageCinematicTimer) window.clearTimeout(finalBossVoyageCinematicTimer);
    finalBossVoyageCinematicTimer = null;
    document.getElementById("finalBossVoyageCinematic")?.remove();
  }

  function clearFinalBossVoyageMapAnimation() {
    if (typeof finalBossVoyageMapAnimationCleanup === "function") {
      finalBossVoyageMapAnimationCleanup();
    }
    finalBossVoyageMapAnimationCleanup = null;
  }

  function kumaPawCurveControl(start, end) {
    const dx = end.x - start.x;
    const dy = end.y - start.y;
    const distance = Math.hypot(dx, dy) || 1;
    const arc = Math.min(760, Math.max(220, distance * 0.2));
    return {
      x: (start.x + end.x) * 0.5 + (dy / distance) * arc,
      y: (start.y + end.y) * 0.5 - (dx / distance) * arc,
    };
  }

  function setKumaPawMapTokenPose(token, point, angle) {
    if (!token || !point) return;
    const safeAngle = Number.isFinite(Number(angle)) ? Number(angle) : 0;
    token.style.left = `${point.x}px`;
    token.style.top = `${point.y}px`;
    token.style.transform = `translate(-50%,-50%) rotate(${safeAngle}deg)`;
    token.style.setProperty("--kuma-paw-map-ship-upright", `${-safeAngle}deg`);
  }

  function playKumaPawMapVoyageAnimation(event = {}) {
    clearFinalBossVoyageMapAnimation();
    const board = refs.boardGameMap;
    const detail = event.detail && typeof event.detail === "object" ? event.detail : {};
    const phase = "arrival";
    const playerId = String(event.playerId || detail.playerId || "");
    const player = state.gameState?.players?.find((entry) => String(entry.id || "") === playerId) || null;
    const finalIsland = getIslandById("final-island");
    const destinationIsland = getIslandById(String(detail.islandId || ""));
    if (!board || !finalIsland || !destinationIsland || !playerId) return 0;

    const finalPosition = playerShipTokenPositionPx(player || { id: playerId }, nodeToPx(finalIsland));
    const destinationPosition = playerShipTokenPositionPx(player || { id: playerId }, nodeToPx(destinationIsland));
    const start = finalPosition;
    const end = destinationPosition;
    const control = kumaPawCurveControl(start, end);
    const boardSize = boardPixelSize();
    const path = `M ${start.x} ${start.y} Q ${control.x} ${control.y} ${end.x} ${end.y}`;
    const shipImage = escapeModalText(detail.shipImage || "images/board/ships/ship_01.webp");
    const layer = document.createElement("div");
    layer.className = `kuma-paw-map-layer phase-${phase}`;
    layer.dataset.eventId = String(event.id || "");
    layer.innerHTML = `
      <svg class="kuma-paw-map-flight-svg" viewBox="0 0 ${boardSize.width} ${boardSize.height}" aria-hidden="true">
        <path class="kuma-paw-map-contrail aura" pathLength="1" d="${path}"></path>
        <path class="kuma-paw-map-contrail core" pathLength="1" d="${path}"></path>
      </svg>
      <img class="kuma-paw-map-burst landing" src="images/board/final_island/kuma_paw_transfer/paw_landing_impact.webp" alt="" style="left:${end.x}px;top:${end.y}px" aria-hidden="true">
      <img class="kuma-paw-map-landing-ship" src="${shipImage}" alt="" style="left:${end.x}px;top:${end.y}px" aria-hidden="true">
      <div class="kuma-paw-map-token" aria-label="${escapeModalText(detail.playerName || event.playerName || "玩家")} 的船正在肉球氣泡內飛行">
        <img class="kuma-paw-map-bubble" src="images/board/final_island/kuma_paw_transfer/paw_flight_bubble.webp" alt="">
        <img class="kuma-paw-map-ship" src="${shipImage}" alt="">
      </div>
    `;
    board.appendChild(layer);
    state.kumaPawAnimation = { playerId, eventId: String(event.id || ""), phase };
    const escapedPlayerId = window.CSS?.escape ? CSS.escape(playerId) : playerId.replace(/"/g, '\\"');
    const sourceShip = board.querySelector(`.ship-token[data-player-id="${escapedPlayerId}"]`);
    sourceShip?.classList.add("kuma-paw-hidden-source");
    const token = layer.querySelector(".kuma-paw-map-token");
    const reduceMotion = window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;
    const requestedDuration = Math.max(520, Number(detail.mapDuration || event.duration || 2600));
    const duration = reduceMotion ? Math.min(620, requestedDuration) : requestedDuration;
    const followScale = Math.max(0.7, Math.min(1.02, state.panZoom.scale || 0.84));
    const initialTangent = quadraticPathTangent(start, control, end, 0);
    setKumaPawMapTokenPose(token, start, Math.atan2(initialTangent.y, initialTangent.x) * 180 / Math.PI);
    panToBoardPoint(start.x, Math.max(0, start.y), { immediate: false, scale: followScale });

    let animationFrame = 0;
    let settleTimer = 0;
    let startTime = 0;
    let cleaned = false;
    const cleanup = () => {
      if (cleaned) return;
      cleaned = true;
      if (animationFrame) window.cancelAnimationFrame(animationFrame);
      if (settleTimer) window.clearTimeout(settleTimer);
      layer.remove();
      if (state.kumaPawAnimation?.eventId === String(event.id || "")) state.kumaPawAnimation = null;
      if (!player?.pendingPostgameBossVoyage) sourceShip?.classList.remove("kuma-paw-hidden-source");
      finalBossVoyageMapAnimationCleanup = null;
    };
    finalBossVoyageMapAnimationCleanup = cleanup;
    const ease = (value) => value < 0.5
      ? 4 * value * value * value
      : 1 - Math.pow(-2 * value + 2, 3) / 2;
    const tick = (timestamp) => {
      if (!startTime) startTime = timestamp;
      const raw = Math.min(1, (timestamp - startTime) / duration);
      const t = ease(raw);
      const point = quadraticPathPoint(start, control, end, t);
      const tangent = quadraticPathTangent(start, control, end, t);
      const angle = Math.atan2(tangent.y, tangent.x) * 180 / Math.PI;
      setKumaPawMapTokenPose(token, point, angle);
      panToBoardPoint(point.x, Math.max(0, point.y), { immediate: true, scale: followScale });
      if (raw < 1) {
        animationFrame = window.requestAnimationFrame(tick);
        return;
      }
      layer.classList.add("arrived");
      settleTimer = window.setTimeout(cleanup, reduceMotion ? 90 : 1380);
    };
    requestAnimationFrame(() => {
      layer.classList.add("moving");
      animationFrame = window.requestAnimationFrame(tick);
    });
    return duration;
  }

  function playFinalBossVoyageCinematic(event = {}) {
    clearFinalBossVoyageCinematic();
    const detail = event.detail && typeof event.detail === "object" ? event.detail : {};
    const phase = detail.phase === "arrival" ? "arrival" : "departure";
    const duration = Math.max(900, Number(event.duration || 2400));
    if (phase !== "arrival") return 0;
    finalBossVoyageCinematicTimer = window.setTimeout(() => {
      finalBossVoyageCinematicTimer = null;
      playKumaPawMapVoyageAnimation(event);
    }, 80);
    return duration;
  }

  function finalBossVoyageEvent(player, entry, phase, duration) {
    const shipSkin = shipSkinForPlayer(player, Math.max(0, state.gameState.players.indexOf(player)));
    const cinematicDuration = 0;
    const mapDuration = Math.max(1200, duration - 1500);
    const event = emitBoardUiEvent("final-boss-voyage", {
      player,
      title: phase === "arrival" ? "肉球氣泡・轉送" : "肉球果實・轉送",
      subtitle: phase === "arrival" ? `${player.name} 從拉夫德魯飛往 ${entry.bossDef.name} 的據點。` : `大熊把 ${player.name} 的船拍向 ${entry.bossDef.name}；下次個人回合抵達。`,
      theme: "final",
      symbol: "掌",
      duration,
      detail: {
        phase,
        playerId: player.id,
        playerName: player.name,
        bossKey: entry.bossDef.key,
        bossName: entry.bossDef.name,
        clueItemId: entry.bossDef.clueItemId,
        clueNumber: entry.bossDef.clueNumber,
        islandId: entry.assignment?.islandId || "",
        islandName: entry.island?.name || "無風帶孤島",
        islandImage: entry.bossDef.islandImage,
        shipImage: shipSkin?.image || "images/board/ships/ship_01.webp",
        cinematicDuration,
        mapDuration,
      },
    }, { immediate: true, clearDelay: duration + 800 });
    handleBoardUiEvent(event);
    return event;
  }

  async function startFinalIslandBossVoyage(player, island, entry) {
    if (!player || !island || !entry?.unlocked || !entry.assignment || warnBoardLanTurnLocked(player)) return false;
    if (player.location?.kind !== "island" || player.location.islandId !== island.id || island.kind !== "final") return false;
    if (normalizePendingPostgameBossVoyage(player)) return false;
    player.pendingPostgameBossVoyage = {
      bossKey: entry.bossDef.key,
      clueItemId: entry.bossDef.clueItemId,
      islandId: entry.assignment.islandId,
      phase: "awaiting_turn",
      departedAtRound: Math.max(1, Number(state.gameState.round || 1)),
      selectedAt: Date.now(),
    };
    state.gameState.resolutionLock = true;
    state.gameState.turnStep = `肉球轉送：${entry.bossDef.name}`;
    closeModal();
    addLog(`${player.name} 在拉夫德魯把 ${postgameClueCardLabel(entry.bossDef.clueNumber)} 的永久座標交給大熊，登記前往 ${entry.bossDef.name} 的島嶼；本回合用於決定目的地，下次個人回合才開始轉送。`);
    state.gameState.resolutionLock = false;
    renderAll();
    scheduleBoardLanStatePush("final-boss-voyage-destination-selected", 0, { force: true });
    endTurn({
      reason: "final-boss-voyage-turn-spent",
      context: "map",
      subtitle: `已登記 ${entry.bossDef.name}；下次輪到時才從拉夫德魯開始肉球轉送。`,
    });
    return true;
  }

  async function processPendingPostgameBossVoyageForCurrentPlayer() {
    const player = currentPlayer();
    if (!player || !canBoardLanControlCurrentPlayer(player)) return false;
    const playerId = String(player.id || "");
    if (!playerId || finalBossVoyageProcessingPlayerIds.has(playerId)) return false;
    const pending = normalizePendingPostgameBossVoyage(player);
    if (!pending || state.battleState || state.gameState.pendingMove || state.gameState.movementAnimating || state.gameState.diceRolling) return false;
    const entry = postgameBossVoyageEntries(player).find((item) => item.bossDef.key === pending.bossKey);
    if (!entry?.unlocked || !entry.assignment || !entry.island) {
      player.pendingPostgameBossVoyage = null;
      return false;
    }
    finalBossVoyageProcessingPlayerIds.add(playerId);
    try {
      const currentRound = Math.max(1, Number(state.gameState.round || 1));
      if (pending.phase === "departing" || (pending.phase === "awaiting_turn" && currentRound <= pending.departedAtRound)) {
        // 舊存檔可能仍停在 departing；只轉成等待，不補播選擇目的地時的動畫。
        pending.phase = "awaiting_turn";
        state.gameState.resolutionLock = false;
        state.gameState.turnStep = `肉球轉送：${entry.bossDef.name}`;
        closeModal();
        renderAll();
        scheduleBoardLanStatePush("final-boss-voyage-recover-awaiting-turn", 0, { force: true });
        endTurn({ reason: "final-boss-voyage-recover-departure", context: "map", subtitle: `已登記 ${entry.bossDef.name}；下次輪到時才從拉夫德魯開始肉球轉送。` });
        return true;
      }
      const duration = isCpuPlayer(player) ? cpuTurnDelay(8000, player, 3400) : 8000;
      pending.phase = "arriving";
      pending.islandId = entry.assignment.islandId;
      state.gameState.resolutionLock = true;
      state.gameState.turnStep = `肉球氣泡飛往 ${entry.bossDef.name} 的據點`;
      state.gameState.pendingMove = null;
      player.location = { kind: "island", islandId: entry.assignment.islandId, entryDirection: null };
      player.routeChoice = null;
      closeModal();
      finalBossVoyageEvent(player, entry, "arrival", duration);
      renderAll();
      scheduleBoardLanStatePush("final-boss-voyage-arrival", 80, { force: true });
      await wait(duration);
      const latest = normalizePendingPostgameBossVoyage(player);
      if (!latest || latest.bossKey !== entry.bossDef.key || String(currentPlayer()?.id || "") !== playerId) return false;
      player.pendingPostgameBossVoyage = null;
      clearFinalBossVoyageMapAnimation();
      state.gameState.resolutionLock = false;
      renderAll();
      handleIslandArrival(player, entry.island);
      resolveLanding(player);
      scheduleBoardLanStatePush("final-boss-voyage-landing", 80, { force: true });
      return true;
    } finally {
      finalBossVoyageProcessingPlayerIds.delete(playerId);
    }
  }

  function schedulePendingPostgameBossVoyageForCurrentPlayer() {
    [0, 220, 620].forEach((delay) => {
      window.setTimeout(() => {
        const player = currentPlayer();
        if (!player || pendingCoopBattleResultForPlayer(player) || !player.pendingPostgameBossVoyage) return;
        void processPendingPostgameBossVoyageForCurrentPlayer();
      }, delay);
    });
  }

  function openFinalIslandRevisitModal(player, island) {
    if (!player || !island || warnBoardLanTurnLocked(player)) return false;
    const record = finalIslandRevisitRecord(player);
    const clues = postgameClueCollectionSummary(player);
    const voyageUnlocked = finalIslandBossVoyageUnlockedCount(player);
    const world = normalizePostgameWorldState();
    const decoderTier = normalizePlayerYorkDecoderState(player);
    if (isCpuPlayer(player)) {
      const target = selectFinalIslandBossVoyageForCpu(player);
      if (target) void startFinalIslandBossVoyage(player, island, target);
      else {
        applyFinalIslandDawnBanquet(player, island);
        finishIslandServiceTurn();
      }
      return true;
    }
    playBgmForContext({
      phase: "town",
      sceneType: "final_island_revisit",
      locationType: "island",
      islandType: "final",
      environment: ["laugh_tale", "banquet", "history"],
      eventTags: ["final", "postgame", "revisit", "healing"],
      storyMood: "healing",
    });
    openModal(renderEncounterNauticalPanel({
      title: "拉夫德魯・黎明紀錄殿",
      eyebrow: "最終劇情已完成・再次登島",
      portraitSrc: "images/board/story/speakers/kuma_memory_smile.webp",
      portraitFallback: ISLAND_IMAGE_MAP.final,
      portraitName: "巴索羅繆・大熊",
      portraitMeta: "在最終之島等待的肉球轉送者",
      contextTitle: record.endingTitle,
      contextSubtitle: "結局已記錄，不會自動重播劇情",
      stats: [
        ["通關紀錄", record.round > 0 ? `第 ${record.round} 回合` : "已完成"],
        ["Boss 線索", `${clues.unique}/${POSTGAME_BOSS_DEFS.length} 種`],
        ["永久指針", `${voyageUnlocked}/${POSTGAME_BOSS_DEFS.length} 座`],
        ["解碼器", decoderTier > 0 ? `第 ${decoderTier} 階` : "尚未取得"],
        ["蛋頭島", world.eggheadUnlocked ? "已定位" : "尚未定位"],
        ["島嶼功能", "肉球轉送／黎明宴會"],
      ],
      messageTitle: "通關後的最終之島",
      messageLines: [
        "石壁保留你的結局與全破後世界進度；再次登島不會重新啟動首次劇情。大熊已抵達紀錄殿外，安靜地守在船旁。",
        "把曾經持有的 Boss 線索座標交給大熊，他會以肉球果實轉送整艘船；線索交易出去後，已記錄的座標仍永久保留。",
        "選好目的地只會登記座標並消耗本回合，不會立刻播放動畫；下次輪到你時，大熊才從拉夫德魯把船完整拍飛到目標 Boss 島。",
        "舉辦黎明宴會可讓船上所有夥伴的 HP、PP 與能力階段完全恢復，而且不消耗回合；整備後仍可請大熊轉送。",
      ],
      detailLabel: "黎明宴會",
      detailText: "免費完成全隊整備且不消耗回合；不重複發放結局、任務或世界解鎖獎勵。",
      actions: [
        { id: "finalIslandBossVoyageBtn", label: `請大熊轉送（${voyageUnlocked}/13）` },
        { id: "finalIslandDawnBanquetBtn", label: "黎明宴會・不耗回合" },
        { id: "leaveFinalIslandArchiveBtn", label: "離開紀錄殿", secondary: true },
      ],
    }), "encounter-nautical-modal no-backdrop-close");
    document.getElementById("finalIslandBossVoyageBtn")?.addEventListener("click", () => openFinalIslandBossVoyageCompass(player, island));
    document.getElementById("finalIslandDawnBanquetBtn")?.addEventListener("click", () => {
      applyFinalIslandDawnBanquet(player, island);
      openFinalIslandRevisitModal(player, island);
    });
    document.getElementById("leaveFinalIslandArchiveBtn")?.addEventListener("click", () => {
      addLog(`${player.name} 查看拉夫德魯的黎明紀錄後重新出航。`);
      finishIslandServiceTurn();
    });
    emitSpectatorModalEvent("final-island-revisit", player, {
      title: "拉夫德魯・黎明紀錄殿",
      subtitle: `${player.name} 正在查看通關後的最終之島。`,
    });
    return true;
  }

  function selectFinalEndingForPlayer(player) {
    normalizeFinalEndingState(player);
    return FINAL_ENDING_AUTO_PRIORITY.find((endingId) => finalEndingEligibility(player, endingId).ok) || "treasure_banquet";
  }

  function finalEndingChapterDuration(ending, chapter) {
    return Math.max(12000, Number(chapter?.duration || ending?.sceneDuration || FINAL_ENDING_SCENE_DURATION_MS));
  }

  function finalEndingTotalDuration(ending) {
    return (ending?.chapters || []).reduce((sum, chapter) => sum + finalEndingChapterDuration(ending, chapter), 0);
  }

  function finalEndingDurationLabel(ending) {
    const minutes = Math.max(1, Math.round(finalEndingTotalDuration(ending) / 60000));
    return `約 ${minutes} 分鐘`;
  }

  function finalEndingTextLines(text) {
    const raw = String(text || "").trim();
    if (!raw) return [];
    const lines = [];
    const endMarks = "。！？!?";
    const closers = "」』）)";
    let current = "";
    for (let i = 0; i < raw.length; i += 1) {
      const char = raw[i];
      const prev = raw[i - 1] || "";
      const next = raw[i + 1] || "";
      current += char;
      if (closers.includes(char) && endMarks.includes(prev)) {
        if (current.trim()) lines.push(current.trim());
        current = "";
      } else if (endMarks.includes(char) && !closers.includes(next)) {
        if (current.trim()) lines.push(current.trim());
        current = "";
      }
    }
    if (current.trim()) lines.push(current.trim());
    return lines.length ? lines : [raw];
  }

  function finalEndingDialogueLineMarkup(text) {
    return finalEndingTextLines(text).map((line, index) => (
      `<span class="final-ending-line" style="--line-index:${index}">${escapeModalText(line)}</span>`
    )).join("");
  }

  function finalEndingChapterBeats(chapter) {
    if (Array.isArray(chapter?.beats) && chapter.beats.length) {
      return chapter.beats
        .map((beat) => ({
          speaker: String(beat?.speaker || chapter.speaker || "旁白"),
          text: String(beat?.text || "").trim(),
          pose: String(beat?.pose || "").trim(),
          speakerImage: String(beat?.speakerImage || "").trim(),
          effect: String(beat?.effect || "").trim(),
          titleCard: String(beat?.titleCard || "").trim(),
        }))
        .filter((beat) => beat.text);
    }
    return finalEndingTextLines(chapter?.text || "").map((text) => ({
      speaker: String(chapter?.speaker || "旁白"),
      text,
      pose: "",
      speakerImage: "",
    }));
  }

  function finalEndingBeatProgressMarkup(beats, beatIndex) {
    return beats.map((_, index) => `<span class="${index === beatIndex ? "active" : ""}"></span>`).join("");
  }

  function finalEndingSpeakerDisplayName(speaker) {
    const clean = String(speaker || "").trim();
    return FINAL_ENDING_NARRATION_SPEAKERS.has(clean) ? "" : clean;
  }

  function finalEndingSpeakerPortraitPath(beatOrSpeaker) {
    const clean = String(typeof beatOrSpeaker === "object" ? beatOrSpeaker?.speaker : beatOrSpeaker || "").trim();
    if (FINAL_ENDING_NARRATION_SPEAKERS.has(clean)) return "";
    if (typeof beatOrSpeaker === "object" && beatOrSpeaker?.speakerImage) return beatOrSpeaker.speakerImage;
    const poses = FINAL_ENDING_SPEAKER_PORTRAITS[clean];
    if (!poses) return "";
    if (typeof poses === "string") return poses;
    const pose = String(typeof beatOrSpeaker === "object" ? beatOrSpeaker?.pose || "" : "").trim();
    return poses[pose] || poses.default || "";
  }

  function finalEndingSpeakerPortraitLayerClass(beatOrSpeaker) {
    const clean = String(typeof beatOrSpeaker === "object" ? beatOrSpeaker?.speaker : beatOrSpeaker || "").trim();
    return ["普羅米修斯", "宙斯", "拿破崙"].includes(clean) ? " front-layer" : "";
  }

  function finalEndingSpeakerPortraitStyle(beatOrSpeaker) {
    const clean = String(typeof beatOrSpeaker === "object" ? beatOrSpeaker?.speaker : beatOrSpeaker || "").trim();
    const pose = String(typeof beatOrSpeaker === "object" ? beatOrSpeaker?.pose || "" : "").trim();
    if (clean === "耶穌布") return ` style="--final-ending-speaker-scale:1.3;"`;
    if ((clean === "騙人布" || clean === "烏索普") && pose === "conflicted") {
      return ` style="--final-ending-speaker-scale:.7;--final-ending-speaker-y:-24%;"`;
    }
    return "";
  }

  function finalEndingDialogueClassName(beat) {
    return `final-ending-dialogue ${finalEndingSpeakerPortraitPath(beat) ? "has-portrait" : "is-narration"}`;
  }

  function normalizeStoryPlaybackSettings(settings = {}) {
    const speed = STORY_PLAYBACK_SPEEDS.includes(Number(settings.speed))
      ? Number(settings.speed)
      : STORY_PLAYBACK_DEFAULT_SPEED;
    return {
      auto: !!settings.auto,
      speed,
    };
  }

  function loadStoryPlaybackSettings() {
    try {
      return normalizeStoryPlaybackSettings(JSON.parse(localStorage.getItem(STORY_PLAYBACK_STORAGE_KEY) || "{}"));
    } catch (_) {
      return normalizeStoryPlaybackSettings();
    }
  }

  function saveStoryPlaybackSettings(settings = {}) {
    const normalized = normalizeStoryPlaybackSettings(settings);
    try {
      localStorage.setItem(STORY_PLAYBACK_STORAGE_KEY, JSON.stringify(normalized));
    } catch (_) {}
    return normalized;
  }

  let storyPlaybackSettings = loadStoryPlaybackSettings();

  function storyPlaybackSpeedOptionsMarkup(currentSpeed) {
    return STORY_PLAYBACK_SPEEDS.map((speed) => (
      `<option value="${speed}" ${Number(currentSpeed) === speed ? "selected" : ""}>${speed}x</option>`
    )).join("");
  }

  function finalEndingPlaybackControlsMarkup() {
    const settings = normalizeStoryPlaybackSettings(storyPlaybackSettings);
    return `
      <div class="final-ending-playback-controls" aria-label="劇情播放控制">
        <button type="button" class="final-ending-control-btn ${settings.auto ? "active" : ""}" id="finalEndingAutoBtn" aria-pressed="${settings.auto ? "true" : "false"}">${settings.auto ? "自動中" : "自動"}</button>
        <label class="final-ending-speed-control" for="finalEndingSpeedSelect">
          <span>速度</span>
          <select id="finalEndingSpeedSelect">${storyPlaybackSpeedOptionsMarkup(settings.speed)}</select>
        </label>
        <button type="button" class="final-ending-control-btn danger" id="finalEndingSkipBtn">跳過</button>
      </div>
    `;
  }

  function finalEndingDialogueContentMarkup(ending, chapterIndex, beats, beatIndex) {
    const safeBeatIndex = Math.max(0, Math.min(beats.length - 1, Number(beatIndex) || 0));
    const chapter = ending.chapters[chapterIndex] || ending.chapters[0];
    const beat = beats[safeBeatIndex] || { speaker: chapter?.speaker || "旁白", text: chapter?.text || "" };
    const lastBeat = safeBeatIndex >= beats.length - 1;
    const last = chapterIndex >= ending.chapters.length - 1 && lastBeat;
    const speakerName = finalEndingSpeakerDisplayName(beat.speaker);
    const speakerPortrait = finalEndingSpeakerPortraitPath(beat);
    const speakerMarkup = speakerName ? `<div class="final-ending-speaker">${escapeModalText(speakerName)}</div>` : "";
    const portraitLayerClass = finalEndingSpeakerPortraitLayerClass(beat);
    const portraitStyle = finalEndingSpeakerPortraitStyle(beat);
    const portraitMarkup = speakerPortrait ? `
      <div class="final-ending-speaker-portrait${portraitLayerClass}"${portraitStyle} aria-hidden="true">
        <img src="${escapeModalText(speakerPortrait)}" alt="" loading="eager" decoding="async" draggable="false">
      </div>
    ` : "";
    return `
      ${portraitMarkup}
      <div class="final-ending-dialogue-body">
        <div class="final-ending-speaker-row ${speakerName ? "" : "narration"}">
          ${speakerMarkup}
          <div class="final-ending-beat-progress" aria-hidden="true">${finalEndingBeatProgressMarkup(beats, safeBeatIndex)}</div>
        </div>
        <p class="final-ending-lines"><span class="final-ending-line current">${escapeModalText(beat.text)}</span></p>
        <div class="final-ending-progress" aria-hidden="true">${finalEndingProgressMarkup(ending, chapterIndex)}</div>
        <div class="final-ending-actions">
          <button type="button" class="final-ending-btn ghost" id="finalEndingPrevBtn" ${chapterIndex <= 0 && safeBeatIndex <= 0 ? "disabled" : ""}>返回</button>
          <button type="button" class="final-ending-btn primary" id="finalEndingNextBtn">${last ? escapeModalText(ending.finishLabel || "完成結局") : (lastBeat ? "下一幕" : "繼續")}</button>
        </div>
      </div>
    `;
  }

  let finalEndingPreloadKey = "";

  function preloadFinalEndingAssets(ending) {
    if (!ending || typeof Image === "undefined") return;
    const paths = new Set();
    ending.chapters.forEach((chapter) => {
      [chapter.bg, chapter.foreground, chapter.accent].forEach((path) => {
        if (path) paths.add(path);
      });
      finalEndingChapterBeats(chapter).forEach((beat) => {
        const portrait = finalEndingSpeakerPortraitPath(beat);
        if (portrait) paths.add(portrait);
      });
    });
    ["images/board/final_island/road_poneglyph_stone_north.webp", "images/board/final_island/road_poneglyph_stone_east.webp", "images/board/final_island/road_poneglyph_stone_south.webp", "images/board/final_island/road_poneglyph_stone_west.webp"].forEach((path) => paths.add(path));
    const key = Array.from(paths).sort().join("|");
    if (key === finalEndingPreloadKey) return;
    finalEndingPreloadKey = key;
    paths.forEach((path) => {
      const image = new Image();
      image.decoding = "async";
      image.src = path;
    });
  }

  let finalEndingAutoTimer = null;
  let finalEndingAdvanceTimer = null;

  function clearFinalEndingAdvanceTimer() {
    if (!finalEndingAdvanceTimer) return;
    window.clearTimeout(finalEndingAdvanceTimer);
    finalEndingAdvanceTimer = null;
  }

  function finalEndingAutoDelayForBeat(beat = {}) {
    const speed = Math.max(0.5, Number(storyPlaybackSettings.speed || STORY_PLAYBACK_DEFAULT_SPEED));
    const textLength = String(beat.text || "").replace(/\s+/g, "").length;
    const rawDelay = STORY_AUTO_BASE_DELAY_MS + Math.min(2600, textLength * STORY_AUTO_TEXT_DELAY_MS);
    return Math.max(520, Math.round(rawDelay / speed));
  }

  function startFinalIslandAutoEnding(player) {
    if (!player) return;
    normalizeFinalEndingState(player);
    state.gameState.resolutionLock = true;
    state.gameState.turnStep = "最終之島結局";
    const endingId = selectFinalEndingForPlayer(player);
    const ending = FINAL_ENDING_DEFS[endingId];
    addLog(`${player.name} 抵達最終之島，符合「${ending?.title || "最終結局"}」條件。`);
    preloadFinalEndingAssets(ending);
    startFinalIslandEnding(player, endingId, 0);
  }

  function finalEndingProgressMarkup(ending, chapterIndex) {
    return ending.chapters.map((_, index) => `<span class="${index === chapterIndex ? "active" : ""}"></span>`).join("");
  }

  function finalEndingCssImage(path) {
    const clean = String(path || "").replace(/["\\\n\r;]/g, "");
    return clean ? `url(${clean})` : "none";
  }

  function finalEndingCinematicStyle(chapter, duration) {
    const foregroundInset = String(chapter.foregroundInset || "8% 12% 30%").replace(/[;"\\]/g, "");
    const accentInset = String(chapter.accentInset || "6% 8% 24%").replace(/[;"\\]/g, "");
    const foregroundOpacity = Number.isFinite(Number(chapter.foregroundOpacity)) ? Number(chapter.foregroundOpacity) : 0;
    const accentOpacity = Number.isFinite(Number(chapter.accentOpacity)) ? Number(chapter.accentOpacity) : 0;
    return [
      `--scene-duration:${duration}ms`,
      `--ending-bg:${finalEndingCssImage(chapter.bg)}`,
      `--ending-foreground:${finalEndingCssImage(chapter.foreground)}`,
      `--ending-foreground-opacity:${foregroundOpacity}`,
      `--ending-foreground-inset:${foregroundInset}`,
      `--ending-accent:${finalEndingCssImage(chapter.accent)}`,
      `--ending-accent-opacity:${accentOpacity}`,
      `--ending-accent-inset:${accentInset}`,
    ].join(";");
  }

  function finalEndingCinematicMarkup(player, ending, chapterIndex, beatIndex = 0) {
    const chapter = ending.chapters[chapterIndex] || ending.chapters[0];
    const beats = finalEndingChapterBeats(chapter);
    const safeBeatIndex = Math.max(0, Math.min(beats.length - 1, Number(beatIndex) || 0));
    const beat = beats[safeBeatIndex] || { speaker: chapter.speaker || "旁白", text: chapter.text || "" };
    const showRobin = false;
    const scene = String(chapter.scene || "arrival").replace(/[^\w-]/g, "");
    const duration = finalEndingChapterDuration(ending, chapter);
    const sceneStyle = finalEndingCinematicStyle(chapter, duration);
    return `
      <div class="final-ending-screen final-ending-cinematic ending-${escapeModalText(ending.tone)} scene-${escapeModalText(scene)}" style="${sceneStyle}">
        ${finalEndingPlaybackControlsMarkup()}
        ${ending.id === "opening_great_pirate_age" ? `
          <div class="opening-story-flash" aria-hidden="true"></div>
          <div class="opening-story-title-card" aria-live="polite"></div>
        ` : ""}
        <div class="final-ending-letterbox" aria-hidden="true"></div>
        <div class="final-ending-sky-layer" aria-hidden="true"></div>
        <div class="final-ending-sea-light" aria-hidden="true"></div>
        <div class="final-ending-island-art" aria-hidden="true"></div>
        <div class="final-ending-stage" aria-hidden="true">
          <div class="final-ending-world-map"></div>
          <div class="final-ending-history-wall"></div>
          <div class="final-ending-treasure-table"></div>
          <div class="final-ending-redline-rift"></div>
          <div class="final-ending-allblue"></div>
          <div class="final-ending-party-lights"></div>
          <div class="final-ending-crew-ring"></div>
        </div>
        ${ending.showPoneglyphs === false ? "" : `
          <div class="final-ending-poneglyph-row" aria-hidden="true">
            <img src="images/board/final_island/road_poneglyph_stone_north.webp" alt="">
            <img src="images/board/final_island/road_poneglyph_stone_east.webp" alt="">
            <img src="images/board/final_island/road_poneglyph_stone_south.webp" alt="">
            <img src="images/board/final_island/road_poneglyph_stone_west.webp" alt="">
          </div>
        `}
        ${showRobin ? `
          <img class="final-ending-robin" src="images/board/final_island/robin_reading_cutout.webp" alt="妮可·羅賓" loading="eager" decoding="async" draggable="false">
        ` : ""}
        <section class="${finalEndingDialogueClassName(beat)}" aria-live="polite">
          ${finalEndingDialogueContentMarkup(ending, chapterIndex, beats, safeBeatIndex)}
        </section>
      </div>
    `;
  }

  function startFinalEndingCinematicSession(player, ending, onComplete, chapterIndex = 0, beatIndex = 0) {
    if (!ending || !Array.isArray(ending.chapters) || !ending.chapters.length) {
      addLog("目前無法播放這段劇情。");
      if (typeof onComplete === "function") onComplete();
      return;
    }
    preloadFinalEndingAssets(ending);
    let currentChapterIndex = Math.max(0, Math.min(ending.chapters.length - 1, Number(chapterIndex) || 0));
    let currentChapter = ending.chapters[currentChapterIndex] || ending.chapters[0];
    let currentBeats = finalEndingChapterBeats(currentChapter);
    let currentBeatIndex = Math.max(0, Math.min(currentBeats.length - 1, Number(beatIndex) || 0));
    if (finalEndingAutoTimer) {
      window.clearTimeout(finalEndingAutoTimer);
      finalEndingAutoTimer = null;
    }
    openModal(finalEndingCinematicMarkup(player, ending, currentChapterIndex, currentBeatIndex), "final-ending-fullscreen-modal no-backdrop-close force-choice");
    let canAdvance = false;
    let sessionCompleted = false;
    const screen = document.querySelector(".final-ending-screen");
    const dialogue = document.querySelector(".final-ending-dialogue");
    const renderOpeningStoryBeatExtras = (beat = {}) => {
      if (!screen || ending.id !== "opening_great_pirate_age") return;
      delete screen.dataset.openingEffect;
      void screen.offsetWidth;
      const effect = String(beat.effect || "").replace(/[^\w-]/g, "");
      if (effect) screen.dataset.openingEffect = effect;
      const titleCard = screen.querySelector(".opening-story-title-card");
      if (!titleCard) return;
      titleCard.classList.remove("is-visible");
      titleCard.textContent = String(beat.titleCard || "");
      if (beat.titleCard) {
        void titleCard.offsetWidth;
        titleCard.classList.add("is-visible");
      }
    };
    const completeSession = () => {
      if (sessionCompleted) return;
      sessionCompleted = true;
      if (finalEndingAutoTimer) {
        window.clearTimeout(finalEndingAutoTimer);
        finalEndingAutoTimer = null;
      }
      clearFinalEndingAdvanceTimer();
      if (typeof onComplete === "function") onComplete();
    };
    const updatePlaybackControls = () => {
      const autoButton = document.getElementById("finalEndingAutoBtn");
      const speedSelect = document.getElementById("finalEndingSpeedSelect");
      if (autoButton) {
        autoButton.classList.toggle("active", !!storyPlaybackSettings.auto);
        autoButton.setAttribute("aria-pressed", storyPlaybackSettings.auto ? "true" : "false");
        autoButton.textContent = storyPlaybackSettings.auto ? "自動中" : "自動";
      }
      if (speedSelect && Number(speedSelect.value) !== Number(storyPlaybackSettings.speed)) {
        speedSelect.value = String(storyPlaybackSettings.speed);
      }
    };
    const scheduleAutoAdvance = () => {
      clearFinalEndingAdvanceTimer();
      if (!storyPlaybackSettings.auto || !canAdvance) return;
      const beat = currentBeats[currentBeatIndex] || {};
      finalEndingAdvanceTimer = window.setTimeout(() => {
        finalEndingAdvanceTimer = null;
        goNext({ auto: true });
      }, finalEndingAutoDelayForBeat(beat));
    };
    const armAdvanceLock = () => {
      if (finalEndingAutoTimer) {
        window.clearTimeout(finalEndingAutoTimer);
        finalEndingAutoTimer = null;
      }
      clearFinalEndingAdvanceTimer();
      canAdvance = false;
      const nextButton = document.getElementById("finalEndingNextBtn");
      if (nextButton) nextButton.disabled = true;
      dialogue?.classList.add("waiting");
      const lockMs = Math.max(180, Math.round(FINAL_ENDING_ADVANCE_LOCK_MS / Math.max(0.5, Number(storyPlaybackSettings.speed || 1))));
      finalEndingAutoTimer = window.setTimeout(() => {
        canAdvance = true;
        const currentNextButton = document.getElementById("finalEndingNextBtn");
        if (currentNextButton) currentNextButton.disabled = false;
        dialogue?.classList.remove("waiting");
        finalEndingAutoTimer = null;
        scheduleAutoAdvance();
      }, lockMs);
    };
    const releaseAdvanceLock = () => {
      if (finalEndingAutoTimer) {
        window.clearTimeout(finalEndingAutoTimer);
        finalEndingAutoTimer = null;
      }
      canAdvance = true;
      const currentNextButton = document.getElementById("finalEndingNextBtn");
      if (currentNextButton) currentNextButton.disabled = false;
      dialogue?.classList.remove("waiting");
      scheduleAutoAdvance();
    };
    const renderCurrentBeat = () => {
      const currentBeat = currentBeats[currentBeatIndex] || currentBeats[0] || { speaker: "旁白", text: "" };
      if (!dialogue) return;
      renderOpeningStoryBeatExtras(currentBeat);
      dialogue.className = `${finalEndingDialogueClassName(currentBeat)} waiting`;
      dialogue.innerHTML = finalEndingDialogueContentMarkup(ending, currentChapterIndex, currentBeats, currentBeatIndex);
      armAdvanceLock();
    };
    const renderCurrentScene = () => {
      currentChapter = ending.chapters[currentChapterIndex] || ending.chapters[0];
      currentBeats = finalEndingChapterBeats(currentChapter);
      currentBeatIndex = Math.max(0, Math.min(currentBeats.length - 1, currentBeatIndex));
      if (screen) {
        const scene = String(currentChapter.scene || "arrival").replace(/[^\w-]/g, "");
        const duration = finalEndingChapterDuration(ending, currentChapter);
        screen.className = `final-ending-screen final-ending-cinematic ending-${escapeModalText(ending.tone)} scene-${escapeModalText(scene)} scene-switching`;
        screen.setAttribute("style", finalEndingCinematicStyle(currentChapter, duration));
        window.setTimeout(() => screen.classList.remove("scene-switching"), 520);
      }
      renderCurrentBeat();
    };
    renderOpeningStoryBeatExtras(currentBeats[currentBeatIndex] || currentBeats[0] || {});
    armAdvanceLock();
    const goPrev = () => {
      if (currentBeatIndex > 0) {
        currentBeatIndex -= 1;
        renderCurrentBeat();
        return;
      }
      if (currentChapterIndex > 0) {
        currentChapterIndex -= 1;
        currentChapter = ending.chapters[currentChapterIndex] || ending.chapters[0];
        currentBeats = finalEndingChapterBeats(currentChapter);
        currentBeatIndex = Math.max(0, currentBeats.length - 1);
        renderCurrentScene();
      }
    };
    const goNext = (_options = {}) => {
      clearFinalEndingAdvanceTimer();
      if (!canAdvance) {
        releaseAdvanceLock();
        return;
      }
      if (currentBeatIndex < currentBeats.length - 1) {
        currentBeatIndex += 1;
        renderCurrentBeat();
        return;
      }
      if (currentChapterIndex >= ending.chapters.length - 1) {
        completeSession();
      } else {
        currentChapterIndex += 1;
        currentBeatIndex = 0;
        renderCurrentScene();
      }
    };
    updatePlaybackControls();
    document.querySelector(".final-ending-playback-controls")?.addEventListener("click", (event) => {
      event.stopPropagation();
    });
    document.getElementById("finalEndingAutoBtn")?.addEventListener("click", (event) => {
      event.stopPropagation();
      storyPlaybackSettings = saveStoryPlaybackSettings({
        ...storyPlaybackSettings,
        auto: !storyPlaybackSettings.auto,
      });
      updatePlaybackControls();
      if (storyPlaybackSettings.auto) {
        if (canAdvance) scheduleAutoAdvance();
      } else {
        clearFinalEndingAdvanceTimer();
      }
    });
    document.getElementById("finalEndingSpeedSelect")?.addEventListener("change", (event) => {
      event.stopPropagation();
      storyPlaybackSettings = saveStoryPlaybackSettings({
        ...storyPlaybackSettings,
        speed: Number(event.target.value || STORY_PLAYBACK_DEFAULT_SPEED),
      });
      updatePlaybackControls();
      if (storyPlaybackSettings.auto && canAdvance) scheduleAutoAdvance();
    });
    document.getElementById("finalEndingSkipBtn")?.addEventListener("click", (event) => {
      event.stopPropagation();
      completeSession();
    });
    dialogue?.addEventListener("click", (event) => {
      event.stopPropagation();
      const prevButton = event.target?.closest?.("#finalEndingPrevBtn");
      if (prevButton) {
        goPrev();
        return;
      }
      const nextButton = event.target?.closest?.("#finalEndingNextBtn");
      if (nextButton) {
        goNext();
        return;
      }
      goNext();
    });
    screen?.addEventListener("click", () => {
      goNext();
    });
  }

  function startFinalIslandEnding(player, endingId, chapterIndex = 0, beatIndex = 0) {
    const ending = FINAL_ENDING_DEFS[endingId];
    const eligibility = finalEndingEligibility(player, endingId);
    if (!ending || !eligibility.ok) {
      addLog(eligibility.reason || "目前無法播放這個結局。");
      state.gameState.resolutionLock = false;
      renderAll();
      endTurn();
      return;
    }
    startFinalEndingCinematicSession(player, ending, () => finishFinalIslandEnding(player, endingId), chapterIndex, beatIndex);
  }

  function startFinalGateAftermath(player, onComplete) {
    if (!player) {
      if (typeof onComplete === "function") onComplete();
      return;
    }
    player.finalGateAftermathSeen = true;
    state.gameState.resolutionLock = true;
    state.gameState.turnStep = "伊姆戰後劇情";
    preloadFinalEndingAssets(FINAL_IMU_AFTERSTORY_ENDING);
    startFinalEndingCinematicSession(player, FINAL_IMU_AFTERSTORY_ENDING, () => {
      state.gameState.resolutionLock = false;
      if (typeof onComplete === "function") {
        onComplete();
      } else {
        closeModal();
        renderAll();
      }
    });
  }

  function finishFinalIslandEnding(player, endingId) {
    const ending = FINAL_ENDING_DEFS[endingId];
    if (!player || !ending) return;
    const postgameWasUnlocked = Boolean(state.gameState.postgameWorld?.unlocked);
    if (finalEndingAutoTimer) {
      window.clearTimeout(finalEndingAutoTimer);
      finalEndingAutoTimer = null;
    }
    clearFinalEndingAdvanceTimer();
    normalizeFinalEndingState(player);
    if (!player.finalEndingSeen.includes(endingId)) player.finalEndingSeen.push(endingId);
    player.finalEndingChoice = endingId;
    player.finalEndingCleared = true;
    state.gameState.finalEndingCleared = true;
    state.gameState.finalEndingLast = {
      playerId: player.id,
      playerName: player.name,
      endingId,
      title: ending.title,
      round: Math.max(1, Number(state.gameState.round || 1)),
      completedAt: Date.now(),
    };
    state.gameState.finalEndingRecords[player.id] = state.gameState.finalEndingLast;
    addLog(`${player.name} 在最終之島完成「${ending.title}」。`);
    recordMissionEvent(player, { type: "final_ending", endingId, title: ending.title });
    const unlockedNow = unlockPostgameWorldAfterEnding(player, { ...ending, id: endingId }) && !postgameWasUnlocked;
    if (unlockedNow) {
      syncAvailableCardsWithCatalog(state.gameState);
      addLog("完成最終之島後，艾斯、柯拉松、光月御田與羅傑已開放於酒館招募名單。");
    }
    if (unlockedNow && state.gameState.postgameWorld) {
      state.gameState.postgameWorld.researchLabsActive = true;
      state.gameState.postgameWorld.researchStoryPlayed = true;
    }
    closeModal();
    state.gameState.resolutionLock = unlockedNow;
    renderAll();
    if (unlockedNow) {
      const event = emitBoardUiEvent("postgame-world-unlock", {
        player,
        title: "無風帶消失",
        subtitle: "十三座孤島與新航線已出現在世界地圖。",
        theme: "final",
        symbol: "界",
        duration: POSTGAME_WORLD_CINEMATIC_DURATION_MS,
        detail: {
          playerName: player.name,
          endingId,
          endingTitle: ending.title,
          islandCount: 13,
          completeTurnAfterStory: true,
        },
      }, {
        immediate: true,
        clearDelay: POSTGAME_WORLD_CINEMATIC_DURATION_MS + 3200,
      });
      handleBoardUiEvent(event);
      return;
    }
    state.gameState.resolutionLock = false;
    endTurn();
  }

  function resolveLanding(player) {
    if (resolveCrewWipeoutIfNeeded(player, "全隊瀕死")) return;
    if (player.location.kind === "route") {
      resolveSeaTile(player, getTileByLocation(player.location.routeId, player.location.tileIndex));
      return;
    }
    const island = getIslandById(player.location.islandId);
    if (island.id === INVERSION_MOUNTAIN_ID || island.kind === "reverse-mountain") {
      openReverseMountainChoice(player, 0);
      return;
    }
    if (tryTriggerFinalGateAtIsland(player, island.id, "landing")) return;
    const islandState = getIslandState(island.id);
    const islandKind = getEffectiveIslandKind(island, islandState);
    if ((island.kind === "elbaph" || island.finalGateAnchor || islandKind === "elbaph") && player.finalGateDefeated) {
      recordMissionEvent(player, { type: "visit_island_kind", islandKind: "elbaph", islandId: island.id });
      addLog(`${player.name} 回到艾爾巴夫，洛基在王子試煉場等待再戰。`);
      if (isCpuPlayer(player)) {
        startElbaphLokiTrialBattle(player);
        return;
      }
      openElbaphLokiTrialModal(player, island);
      return;
    }
    if (isPostgameEggheadIsland(island)) {
      recordMissionEvent(player, { type: "visit_island_kind", islandKind: "postgame_egghead", islandId: island.id });
      addLog(`${player.name} 抵達移動蛋頭島，約克部署的洛克斯終戰已啟動。`);
      if (maybeOpenIslandCoopPrompt(player)) return;
      if (isCpuPlayer(player)) {
        addLog(`${player.name} 向洛克斯・D・吉貝克發起挑戰。`);
        startBattle(player, island, islandState);
        return;
      }
      openPostgameRocksModal(player, island, islandState);
      return;
    }
    if (isPostgameBossIsland(island)) {
      const assignment = postgameBossAssignment(island);
      const bossName = assignment?.boss?.name || "未知 Boss";
      recordMissionEvent(player, { type: "visit_island_kind", islandKind: "postgame_boss", islandId: island.id });
      addLog(`${player.name} 在 ${island.name} 發現 ${bossName} 的據點。`);
      if (maybeOpenIslandCoopPrompt(player)) return;
      if (isCpuPlayer(player)) {
        addLog(`${player.name} 向 ${bossName} 發起挑戰。`);
        startBattle(player, island, islandState);
        return;
      }
      openPostgameBossModal(player, island, islandState);
      return;
    }
    if (maybeOpenIslandCoopPrompt(player)) return;
    recordMissionEvent(player, { type: "visit_island_kind", islandKind, islandId: island.id });
    if (island.kind === "judicial" || islandKind === "judicial") {
      openJudicialRaidModal(player, island, islandState);
      return;
    }
    if (island.kind === "impel_down" || islandKind === "impel_down") {
      openImpelDownModal(player, island, islandState);
      return;
    }
    if (island.kind === "marineford" || islandKind === "marineford") {
      openMarinefordModal(player, island, islandState);
      return;
    }
    if (island.id === WATER_SEVEN_ISLAND_ID) {
      openWaterSevenWindow(player);
      return;
    }
      if ((island.kind === "enemy" && islandState.enemyProfile && !islandState.isDefeated) || (island.kind === "yonko" && islandState.enemyProfile)) {
        openEnemyIslandModal(player, island, islandState);
      return;
    }
    if (islandKind === "shop") {
      openShopModal(player, island, islandState);
      return;
    }
    if (islandKind === "hospital") {
      openHospitalModal(player, island);
      return;
    }
    if (islandKind === "research_lab") {
      openResearchLabModal(player, island);
      return;
    }
    if (islandKind === "tavern") {
      openTavernModal(player, island);
      return;
    }
    if (islandKind === "arena") {
      openArenaModal(player, island);
      return;
    }
    if (islandKind === "mission") {
      openMissionBoardModal(player, island, islandState, "", "", { newVisit: true });
      return;
    }
      if (island.kind === "final") {
      if (!state.gameState.finalIslandUnlocked) {
        addLog(`${player.name} 看到尚未真正開啟的最終之島。`);
        endTurn();
        return;
      }
      syncPlayerRoadPoneglyphsFromInventory(player);
      if (!playerHasAllRoadPoneglyphs(player)) {
        openModal(`
          <h3 class="modal-title">最終之島封印</h3>
          <div class="modal-sub">尚未集滿 4 份歷史本文拓本，無法進入最終之島。</div>
          <div class="tier-strip"><span class="tier-chip">目前拓本 ${playerRoadPoneglyphCount(player)}/4</span></div>
          <div class="modal-row"><button type="button" class="modal-btn secondary" id="finalGateCloseBtn">知道了</button></div>
        `, "no-backdrop-close");
        document.getElementById("finalGateCloseBtn")?.addEventListener("click", () => { closeModal(); endTurn(); });
        return;
      }
      if (!playerClearedFinalGate(player)) {
        addLog(`${player.name} 尚未擊退伊姆，通往最終之島的航路仍被阻擋。`);
        endTurn();
        return;
      }
      if (playerCompletedFinalIslandEnding(player)) {
        addLog(`${player.name} 重返最終之島，黎明紀錄殿已開放。`);
        openFinalIslandRevisitModal(player, island);
        return;
      }
      addLog(`${player.name} 登上最終之島，結局分歧開始。`);
      openFinalIslandEndingChoice(player);
      return;
    }
      if (islandKind === "event-island") {
        openEventIslandModal(player, island);
        return;
      }
      addLog(`${player.name} 停靠 ${island.name}。`);
      endTurn();
    }

  function resolveSeaTile(player, tile) {
    if (!tile) {
      endTurn();
      return;
    }
    const seaEncounterAllowed = allowsSeaEncounterOnTile(tile);
    if (tile.primaryTypeId === "encounter" && !seaEncounterAllowed) {
      const rand = createRng(`${state.gameState?.seed || "sea"}-pre-first-row-safe-${tile.id || ""}-${state.gameState?.round || 1}`);
      tile.primaryTypeId = pickWeighted(seaCardTypePoolForRoute(tile.routeId, tile.zone || "safe"), rand);
    }
    if (tile.primaryTypeId === "encounter") {
      const avoidBuff = (player.activeMapBuffs || []).find((buff) => ["avoid_random_encounter", "prevent_forced_random_encounter"].includes(buff?.kind));
      if (avoidBuff) {
        addLog(`${player.name} 的${gameItemDef(avoidBuff.itemId)?.name || "航海道具"}生效，避開了這次隨機遭遇。`);
        endTurn();
        return;
      }
      const leaderCarry = battleCarryItemsForCard(activeCrew(player)).find((item) => item.id === "cleanse_tag" || battleCarryItemEffect(item).kind === "leader_reduce_random_encounter");
      const leaderCarryEffect = battleCarryItemEffect(leaderCarry);
      const cleanseChance = leaderCarryEffect.strength === "low" ? 0.35 : Number(leaderCarryEffect.chance || 0.35);
      if ((leaderCarry?.id === "cleanse_tag" || leaderCarryEffect.kind === "leader_reduce_random_encounter") && Math.random() < cleanseChance) {
        addLog(`${activeCrew(player)?.name || player.name} 的避敵航海符生效，隊伍避開了不必要的遭遇。`);
        endTurn();
        return;
      }
      addLog(`${player.name} 航行到遭遇海格，遭遇敵人。`);
      startSeaEncounterBattle(player, tile);
      return;
    }
    const encounterBuff = (player.activeMapBuffs || []).find((buff) => [
      "increase_encounter_with_reward",
      "increase_battle_event_with_exp",
      "increase_danger_event_and_drop",
    ].includes(buff?.kind) && mapBuffAppliesToSeaZone(buff, tile?.zone || ""));
    const encounterChance = Math.max(
      Number(encounterBuff?.data?.encounterBonus || 0),
      Number(encounterBuff?.data?.battleEventBonus || 0),
      Number(encounterBuff?.data?.dangerEventBonus || 0),
    );
    if (seaEncounterAllowed && encounterChance > 0 && Math.random() < encounterChance) {
      addLog(`${player.name} 的${gameItemDef(encounterBuff.itemId)?.name || "航海道具"}吸引了敵影，觸發海格遭遇。`);
      startSeaEncounterBattle(player, tile);
      return;
    }
    openSeaEventChoice(player, tile);
  }

  function getSeaEventChoicePool(zone, player = null) {
    const pool = SEA_CARD_TYPE_POOLS[zone || "mid"] || SEA_CARD_TYPE_POOLS.mid;
    const choices = pool.filter((entry) => entry.id !== "encounter");
    const eventBuff = (player?.activeMapBuffs || []).find((buff) => ["increase_event_pool", "increase_rare_event"].includes(buff?.kind));
    if (eventBuff) {
      const preferredType = eventBuff.kind === "increase_rare_event"
        ? "treasure"
        : ({
            medicine: "medicine",
            treasure: "treasure",
            weather: "weather",
            money: "money",
            heal_supply: "medicine",
            ocean: "weather",
            mineral_material: "treasure",
          }[eventBuff.data?.pool] || "");
      const bonus = Math.max(0, Number(eventBuff.data?.bonus || eventBuff.data?.rareEventBonus || 0.2));
      if (preferredType) {
        const boosted = choices.map((entry) => ({
          ...entry,
          weight: entry.id === preferredType ? Math.max(1, Math.round(entry.weight * (1 + bonus))) : entry.weight,
        }));
        return boosted.length ? boosted : choices;
      }
    }
    return choices.length ? choices : pool;
  }

  function buildSeaEventChoices(tile, player) {
    const rand = createRng(`${state.gameState.seed}-${tile.id}-${player.id}-${state.gameState.log.length}`);
    const pool = getSeaEventChoicePool(tile.zone, player);
    return Array.from({ length: 2 }, (_, index) => {
      const slotId = `${tile.id}-choice-${index}`;
      const typeId = index === 0 && tile.primaryTypeId && tile.primaryTypeId !== "encounter" ? tile.primaryTypeId : pickWeighted(pool, rand);
      return {
        slotId,
        typeId,
        effectDef: drawSeaCardEffect(typeId, tile, player, slotId),
      };
    });
  }

  function openSeaEventChoice(player, tile, options = {}) {
    if (warnBoardLanTurnLocked(player)) return;
    const dangerLevel = tile?.zone === "danger" ? 4 : tile?.zone === "mid" ? 3 : 2;
    playBgmForContext({
      phase: tile?.zone === "danger" ? "danger" : "event",
      sceneType: "sea_event",
      locationType: "sea",
      character: bgmCharacterTag(activeCrew(player)),
      dangerLevel,
      environment: ["ocean"],
      eventTags: ["ocean", "sailing", tile?.zone || "", tile?.primaryTypeId || ""],
      storyMood: dangerLevel >= 4 ? "tense" : "adventurous",
    });
    const recoveredChoices = Array.isArray(options.choices) ? options.choices.slice(0, 2) : [];
    const choices = recoveredChoices.length === 2
      ? recoveredChoices.map((choice, index) => {
          const slotId = String(choice.slotId || `${tile.id}-choice-${index}`);
          const typeId = String(choice.typeId || "money");
          return { slotId, typeId, effectDef: drawSeaCardEffect(typeId, tile, player, slotId) };
        })
      : buildSeaEventChoices(tile, player);
    const teamEffects = getTeamEffects(player);
    const revealChoices = teamEffects.seaChoiceReveal;
    const revealTypeLimit = Math.max(0, Math.round(Number(teamEffects.seaChoiceTypeReveal || 0)));
    const revealBattleRisk = Boolean(teamEffects.seaChoiceBattleRisk);
    state.gameState.resolutionLock = true;
    const entriesHtml = choices.map(({ slotId, typeId, effectDef }, index) => {
      const info = SEA_EVENT_TYPE_INFO[typeId] || { type: "未知海域", teaser: "前方有未知變化。" };
      const detailLines = [];
      if (!revealChoices && index < revealTypeLimit && effectDef) {
        detailLines.push(`望遠鏡線索：${effectDef.title}`);
      }
      if (!revealChoices && revealBattleRisk) {
        detailLines.push(`偵查台：${typeId === "encounter" ? "可能戰鬥" : "不會戰鬥"}`);
      }
      if (revealChoices && effectDef) {
        detailLines.push(`翻開效果：${effectDef.title}｜${effectDef.desc}`);
      }
      return seaEventChoiceEntryMarkup({
        slotId,
        typeId,
        label: info.type,
        teaser: info.teaser,
        cardBack: getSeaCardBackImage(typeId),
        detailLines,
      }, index, { interactive: true });
    }).join("");
    openModal(seaEventChoiceUiMarkup({
      title: "海域抉擇",
      subtitle: `${player.name} 來到海格，${revealChoices ? "偵查型夥伴已看穿卡背下的詳細效果。" : "從兩張類型卡背中選一張再揭曉真正效果。"}`,
      entriesHtml,
      actions: choices.map(({ slotId, typeId }) => ({
        label: "選這張",
        choiceId: slotId,
        typeId,
      })),
    }), "sea-event-choice-modal force-choice no-backdrop-close");
    refs.modal.querySelectorAll("[data-sea-choice]").forEach((button) => {
      button.addEventListener("click", () => {
        const choice = choices.find((entry) => String(entry.slotId) === String(button.dataset.seaChoice));
        triggerSeaEvent(player, tile, button.dataset.seaType, button.dataset.seaChoice, choice?.effectDef || null);
      });
    });
    if (!options.recovered) {
      emitSpectatorModalEvent("sea-choice", player, {
        playerName: player.name,
        title: "海域抉擇",
        subtitle: `${player.name} 正在從兩張海域卡中選擇。`,
        choices: choices.map(({ slotId, typeId }) => {
          const info = SEA_EVENT_TYPE_INFO[typeId] || { type: "未知海域", teaser: "前方有未知變化。" };
          return {
            slotId,
            typeId,
            label: info.type,
            typeLabel: info.type,
            teaser: info.teaser,
            cardBack: getSeaCardBackImage(typeId),
          };
        }),
      }, { clearDelay: 60000 });
    }
  }

  function seaTreasureChestProfile(profileId = "standard") {
    return SEA_TREASURE_CHEST_WEIGHT_PROFILES[profileId] || SEA_TREASURE_CHEST_WEIGHT_PROFILES.standard;
  }

  function seaTreasureChestProfilePool(profileId = "standard") {
    const profile = seaTreasureChestProfile(profileId);
    return SEA_TREASURE_CHEST_TYPES.map((entry) => ({
      ...entry,
      weight: Math.max(0, Math.round(Number(profile.weights?.[entry.id] ?? entry.weight ?? 1))),
    })).filter((entry) => entry.weight > 0);
  }

  function seaTreasureChestProfileOddsText(profileId = "standard") {
    const pool = seaTreasureChestProfilePool(profileId);
    const total = pool.reduce((sum, entry) => sum + Number(entry.weight || 0), 0) || 1;
    return pool
      .map((entry) => `${entry.label.replace("寶箱", "")}${Math.round((Number(entry.weight || 0) / total) * 100)}%`)
      .join(" / ");
  }

  function drawWeightedTreasureChestTypes(rand, count = 4, profileId = "standard") {
    const pool = seaTreasureChestProfilePool(profileId);
    if (!pool.length) return [];
    return Array.from({ length: Math.max(0, Math.round(Number(count || 0))) }, () => {
      const id = pickWeighted(pool, rand);
      const type = pool.find((entry) => entry.id === id) || pool[0];
      return { ...type };
    });
  }

  function buildSeaTreasureChestChoices(player, tile, slotId = "", profileId = "standard") {
    const rand = createRng(`${state.gameState.seed}-${tile?.id || "sea"}-${player?.id || "player"}-${slotId || "treasure"}-${profileId}-chests-${state.gameState.log.length}`);
    const revealOrder = drawWeightedTreasureChestTypes(rand, 4, profileId);
    const derangements = [
      [1, 0, 3, 2],
      [1, 2, 3, 0],
      [1, 3, 0, 2],
      [2, 0, 3, 1],
      [2, 3, 0, 1],
      [2, 3, 1, 0],
      [3, 0, 1, 2],
      [3, 2, 0, 1],
      [3, 2, 1, 0],
    ];
    const finalPositions = derangements[Math.floor(rand() * derangements.length)] || derangements[0];
    return revealOrder.map((type, index) => ({
      slotId: `${slotId || tile?.id || "sea"}-treasure-chest-${index}`,
      typeId: type.id,
      index,
      revealIndex: index,
      finalIndex: finalPositions[index] ?? index,
    }));
  }

  function seaTreasureChestType(typeId) {
    return SEA_TREASURE_CHEST_TYPES.find((entry) => entry.id === typeId) || SEA_TREASURE_CHEST_TYPES[0];
  }

  function applySeaWoodChestTrap(player, tile, rand = Math.random) {
    const roll = rand();
    if (roll < 0.34) {
      const penalty = seaEventCoinAmount(650, tile);
      const result = applyBerryPenaltyOrCapture(player, penalty, "木寶箱陷阱");
      return {
        ...result,
        title: "木寶箱陷阱",
        summary: `陷阱觸發，${result.summary || `損失 ${formatCoin(penalty)} 貝里`}`,
        desc: "木箱底部藏著假鎖與煙霧彈，打開後觸發罰金陷阱。",
      };
    }
    if (roll < 0.67) {
      const loss = applyShipReducedSeaHpLoss(player, seaEventHpLossAmount(player, 0.14, 18));
      return {
        title: "木寶箱陷阱",
        summary: `陷阱觸發，受到 ${loss} 傷害`,
        desc: "木箱彈出暗器，造成船員與船身傷害。",
      };
    }
    const drained = Math.abs(adjustCrewPP(player, -4));
    if (drained > 0) {
      return {
        title: "木寶箱陷阱",
        summary: `陷阱觸發，失去 ${drained} PP`,
        desc: "木箱裡的煙霧讓前排船員短暫失神，招式次數被消耗。",
      };
    }
    const loss = applyShipReducedSeaHpLoss(player, seaEventHpLossAmount(player, 0.08, 10));
    return {
      title: "木寶箱陷阱",
      summary: `陷阱觸發，受到 ${loss} 傷害`,
      desc: "木箱機關沒有可消耗的 PP，改造成輕微傷害。",
    };
  }

  function rollPostgameChestExtractor(player, chestTypeId, rand = Math.random) {
    if (!state.gameState?.postgameWorld?.researchLabsActive || !["gold", "gem"].includes(chestTypeId)) return null;
    const chance = chestTypeId === "gem" ? 0.28 : 0.18;
    if (rand() >= chance) return null;
    const pool = chestTypeId === "gem"
      ? [
        { id: "lineage_extractor_precision", weight: 35 },
        { id: "lineage_extractor_resonance_power", weight: 16 },
        { id: "lineage_extractor_resonance_skill", weight: 16 },
        { id: "lineage_extractor_resonance_speed", weight: 16 },
        { id: "lineage_extractor_ability", weight: 17 },
      ]
      : [
        { id: "lineage_extractor_precision", weight: 55 },
        { id: "lineage_extractor_resonance_power", weight: 15 },
        { id: "lineage_extractor_resonance_skill", weight: 15 },
        { id: "lineage_extractor_resonance_speed", weight: 15 },
      ];
    const available = pool.filter((entry) => formalItemGrantCapacity(player, entry.id) > 0);
    return available.length ? pickWeighted(available, rand) : null;
  }

  function applySeaTreasureChestReward(player, tile, chestType, rand = Math.random) {
    const parts = [];
    const grantCoins = (base) => {
      const coins = seaEventCoinAmount(base, tile);
      player.coins += coins;
      parts.push(`${formatCoin(coins)} 貝里`);
      return coins;
    };
    const grantItem = (itemId, quantity = 1) => {
      const item = grantFormalItemToPlayer(player, itemId, quantity, { reveal: itemRarityLabel(gameItemDef(itemId)?.rarity) === "S" });
      if (item) parts.push(`${item.name}${quantity > 1 ? ` x${quantity}` : ""}`);
      return item;
    };
    const grantPoolItem = (poolName) => {
      const item = grantRandomEventPoolItem(player, poolName, rand);
      if (item) parts.push(item.name);
      return item;
    };

    if (chestType.id === "wood") {
      return applySeaWoodChestTrap(player, tile, rand);
    } else if (chestType.id === "copper") {
      grantCoins(850);
      grantPoolItem("advanced_supply_pool") || grantPoolItem("basic_supply_pool");
    } else if (chestType.id === "silver") {
      grantCoins(1350);
      grantPoolItem("treasure_pool") || grantPoolItem("advanced_supply_pool");
      if (rand() < 0.45) grantItem("ship_plank", 1);
    } else if (chestType.id === "gold") {
      grantCoins(2200);
      grantPoolItem("treasure_pool") || grantPoolItem("elite_supply_pool");
      grantItem(rand() < 0.55 ? "ship_toolbox" : "ship_plank", 1);
    } else {
      grantCoins(3400);
      grantPoolItem("rare_pool") || grantPoolItem("elite_supply_pool") || grantPoolItem("treasure_pool");
      grantItem("ship_coating_resin", 1);
    }
    const extractorId = rollPostgameChestExtractor(player, chestType.id, rand);
    if (extractorId) grantItem(extractorId, 1);

    return {
      summary: parts.length ? `獲得 ${parts.join("、")}` : "獲得寶箱獎勵",
      desc: chestType.desc || "寶箱已打開。",
    };
  }

  function openSeaTreasureChestDraft(player, tile, effectDef, typeId, slotId = "") {
    if (warnBoardLanTurnLocked(player)) return;
    const profileId = effectDef?.chestProfile || (typeId === "chest" ? "standard" : "standard");
    const profile = seaTreasureChestProfile(profileId);
    const choices = buildSeaTreasureChestChoices(player, tile, slotId, profileId);
    state.gameState.resolutionLock = true;
    openModal(`
      <div class="sea-chest-stage-shell">
        <img class="sea-chest-stage-frame" src="images/board/sea_chest_ui/sea_chest_shuffle_panel_frame.webp" alt="" aria-hidden="true">
        <div class="sea-chest-stage-head">
          <h3 class="sea-chest-stage-title">${escapeModalText(effectDef.title || "漂流寶箱群")}</h3>
          <div class="sea-chest-stage-meta">${escapeModalText(profile.label || "標準比例")}候選權重：${escapeModalText(seaTreasureChestProfileOddsText(profileId))}</div>
        </div>
        <div class="sea-chest-stage-note" data-sea-chest-stage-note>先確認 4 個候選寶箱；木箱是陷阱。按下確認洗牌後才會翻面洗牌。</div>
        <div class="sea-chest-draft-grid is-reveal" data-sea-chest-grid>
          ${choices.map((choice) => {
            const chestType = seaTreasureChestType(choice.typeId);
            const finalOrder = Math.max(0, Math.round(Number(choice.finalIndex ?? choice.index ?? 0)));
            return `
            <button
              type="button"
              class="sea-treasure-chest-card is-revealed"
              data-sea-treasure-chest="${escapeModalText(choice.slotId)}"
              data-final-order="${finalOrder}"
              style="--shuffle-delay:${Math.min(360, Math.max(0, finalOrder) * 90)}ms"
              aria-label="選擇第 ${finalOrder + 1} 個寶箱"
              disabled
            >
              <span class="sea-chest-card-art sea-chest-flip">
                <span class="sea-chest-flip-inner">
                  <span class="sea-chest-card-face sea-chest-front-face">
                    <img src="${escapeModalText(chestType.image || "")}" alt="${escapeModalText(chestType.label)}" loading="lazy" onerror="this.closest('.sea-chest-card-face').classList.add('is-fallback'); this.remove();">
                    <span class="sea-chest-card-fallback">${escapeModalText(chestType.label)}</span>
                  </span>
                  <span class="sea-chest-card-face sea-chest-back-face">
                    <img src="${SEA_TREASURE_CHEST_BACK_IMAGE}" alt="神秘寶箱" loading="lazy" onerror="this.closest('.sea-chest-card-face').classList.add('is-fallback'); this.remove();">
                    <span class="sea-chest-card-fallback"><img src="images/board/judicial_raid_ui/reward_icons/unknown.webp" alt="神秘寶箱"></span>
                  </span>
                </span>
              </span>
              <span class="sea-chest-card-label" data-chest-label>${escapeModalText(chestType.id === "wood" ? "木寶箱：陷阱" : chestType.label)}</span>
            </button>
          `;
          }).join("")}
        </div>
        <div class="modal-row sea-chest-shuffle-row">
          <button type="button" class="modal-btn primary" id="startSeaChestShuffleBtn">確認洗牌</button>
        </div>
      </div>
    `, "force-choice sea-chest-stage-modal no-backdrop-close");
    document.getElementById("startSeaChestShuffleBtn")?.addEventListener("click", (event) => {
      startSeaTreasureChestShuffle(event.currentTarget);
    });
    refs.modal.querySelectorAll("[data-sea-treasure-chest]").forEach((button) => {
      button.addEventListener("click", () => resolveSeaTreasureChestChoice(player, tile, effectDef, typeId, choices, button.dataset.seaTreasureChest));
    });
  }

  function startSeaTreasureChestShuffle(startButton = null) {
    const grid = refs.modal?.querySelector?.("[data-sea-chest-grid]");
    if (!grid) return;
    if (grid.dataset.shuffleStarted === "true") return;
    grid.dataset.shuffleStarted = "true";
    const note = refs.modal.querySelector("[data-sea-chest-stage-note]");
    const buttons = Array.from(grid.querySelectorAll("[data-sea-treasure-chest]"));
    const reduceMotion = window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;
    const setNote = (text) => { if (note?.isConnected) note.textContent = text; };
    const stillOpen = () => grid.isConnected && refs.modalBack?.classList.contains("open");
    if (startButton) {
      startButton.disabled = true;
      startButton.textContent = "洗牌中";
    }
    setNote("確認洗牌，寶箱開始翻面。");
    window.setTimeout(() => {
      if (!stillOpen()) return;
      grid.classList.remove("is-reveal");
      grid.classList.add("is-face-down");
      buttons.forEach((button) => {
        button.classList.add("is-face-down");
        const label = button.querySelector("[data-chest-label]");
        if (label) label.textContent = "翻成背面";
      });
      setNote("寶箱翻成背面，準備洗牌。");
    }, 180);
    window.setTimeout(() => {
      if (!stillOpen()) return;
      grid.classList.add("is-shuffling");
      const finalOrders = buttons.map((button) => Math.max(0, Math.round(Number(button.dataset.finalOrder || 0))));
      const shufflePasses = [
        [2, 0, 3, 1],
        [1, 3, 0, 2],
        [3, 2, 1, 0],
        finalOrders,
      ];
      const runShufflePass = (orders, passIndex) => {
        if (!stillOpen()) return;
        const beforeRects = new Map(buttons.map((button) => [button, button.getBoundingClientRect()]));
        buttons.forEach((button, index) => {
          button.getAnimations?.().forEach((animation) => animation.cancel());
          button.style.order = String(orders[index] ?? index);
        });
        const gridRect = grid.getBoundingClientRect();
        buttons.forEach((button, index) => {
          const before = beforeRects.get(button);
          const after = button.getBoundingClientRect();
          const offsetX = Number(before?.left || after.left) - after.left;
          const offsetY = Number(before?.top || after.top) - after.top;
          const direction = ((index + passIndex) % 2) === 0 ? 1 : -1;
          const sweep = Math.max(after.width * .58, gridRect.width * .105);
          button.animate([
            { transform: `translate(${offsetX}px,${offsetY}px) rotate(0deg) scale(1)`, zIndex: "2" },
            { transform: `translate(${offsetX * .72 + direction * sweep}px,${offsetY - Math.max(18, after.height * .17)}px) rotate(${direction * 7}deg) scale(1.08)`, zIndex: "7", offset: .28 },
            { transform: `translate(${offsetX * .34 - direction * sweep * .72}px,${offsetY + Math.max(12, after.height * .1)}px) rotate(${-direction * 5}deg) scale(.97)`, zIndex: "6", offset: .62 },
            { transform: "translate(0,0) rotate(0deg) scale(1)", zIndex: "2" },
          ], {
            duration: reduceMotion ? 1 : 680,
            delay: reduceMotion ? 0 : index * 50,
            easing: "cubic-bezier(.18,.78,.2,1)",
            fill: "both",
          });
        });
        setNote(`寶箱洗牌中，第 ${passIndex + 1} 輪交叉換位。`);
      };
      shufflePasses.forEach((orders, passIndex) => {
        window.setTimeout(() => runShufflePass(orders, passIndex), reduceMotion ? 0 : passIndex * 860);
      });
    }, reduceMotion ? 260 : 980);
    window.setTimeout(() => {
      if (!stillOpen()) return;
      grid.classList.remove("is-shuffling");
      grid.classList.add("is-ready");
      if (startButton?.isConnected) startButton.remove();
      buttons.forEach((button) => {
        const finalOrder = Math.max(0, Math.round(Number(button.dataset.finalOrder || 0)));
        button.getAnimations?.().forEach((animation) => animation.cancel());
        button.style.order = String(finalOrder);
        button.disabled = false;
        button.classList.add("is-ready");
        const label = button.querySelector("[data-chest-label]");
        if (label) label.textContent = `寶箱 ${finalOrder + 1}`;
      });
      setNote("選一個寶箱打開。木寶箱是陷阱。");
    }, reduceMotion ? 520 : 4550);
  }

  function resolveSeaTreasureChestChoice(player, tile, effectDef, typeId, choices, choiceSlotId) {
    if (warnBoardLanTurnLocked(player)) return;
    const choice = (choices || []).find((entry) => String(entry.slotId) === String(choiceSlotId)) || choices?.[0];
    if (!choice) return;
    refs.modal.querySelectorAll("[data-sea-treasure-chest]").forEach((button) => {
      button.disabled = true;
      button.classList.toggle("is-picked", String(button.dataset.seaTreasureChest) === String(choiceSlotId));
    });
    const chestType = seaTreasureChestType(choice.typeId);
    const rand = createRng(`${state.gameState.seed}-${tile?.id || "sea"}-${player?.id || "player"}-${choice.slotId}-reward-${state.gameState.log.length}`);
    const reward = applySeaTreasureChestReward(player, tile, chestType, rand);
    const rewardTitle = reward.title || `${chestType.label}開啟`;
    emitSpectatorModalEvent("chest-result", player, {
      playerName: player.name,
      title: rewardTitle,
      desc: reward.desc || chestType.desc,
      subtitle: `${player.name} 從漂流寶箱中抽中了${chestType.label}。`,
      summary: reward.summary || "獎勵已取得",
      chips: reward.title ? ["寶藏海格", "陷阱", chestType.label] : ["寶藏海格", chestType.label],
    });
    state.gameState.resolutionLock = true;
    openModal(`
      <div class="sea-chest-stage-shell is-result">
        <img class="sea-chest-stage-frame" src="images/board/item_reveal_ui/important_item_reveal_panel_frame.webp" alt="" aria-hidden="true">
        <div class="sea-chest-stage-head">
          <h3 class="sea-chest-stage-title">${escapeModalText(rewardTitle)}</h3>
          <div class="sea-chest-stage-meta">${escapeModalText(reward.desc || chestType.desc || "寶箱已打開。")}</div>
          <div class="tier-strip">
            <span class="tier-chip">${escapeModalText(chestType.label)}</span>
            <span class="tier-chip">${escapeModalText(reward.summary || "獎勵已取得")}</span>
          </div>
        </div>
        <div class="sea-chest-result-card">
          <div class="sea-chest-card-art reveal">
            <img src="${escapeModalText(chestType.image || "")}" alt="${escapeModalText(chestType.label)}" loading="lazy" onerror="this.closest('.sea-chest-card-art').classList.add('is-fallback'); this.remove();">
            <span class="sea-chest-card-fallback">${escapeModalText(chestType.label)}</span>
          </div>
        </div>
        <div class="modal-row sea-chest-shuffle-row">
          <button type="button" class="modal-btn primary" id="confirmSeaTreasureChestBtn">確認</button>
        </div>
      </div>
    `, "force-choice sea-chest-stage-modal no-backdrop-close");
    document.getElementById("confirmSeaTreasureChestBtn")?.addEventListener("click", () => {
      closeModal();
      addLog(`${player.name} 打開${chestType.label}：${reward.summary || "獎勵已取得"}。`);
      recordMissionEvent(player, { type: "chest_open", zone: tile?.zone || "", chestType: chestType.id, seaType: typeId });
      state.gameState.resolutionLock = false;
      applyPostResolution(player, reward);
    });
  }

  function triggerSeaEvent(player, tile, typeId, slotId = "", preselectedEffectDef = null) {
    if (warnBoardLanTurnLocked(player)) return;
    const effectDef = preselectedEffectDef || drawSeaCardEffect(typeId, tile, player, slotId);
    const result = effectDef.apply ? (effectDef.apply(player, state.gameState, tile) || {}) : {};
    if (result.openTreasureChestDraft) {
      emitSpectatorModalEvent("sea-result", player, {
        playerName: player.name,
        title: effectDef.title,
        desc: effectDef.desc,
        subtitle: `${player.name} 翻開了一張${SEA_EVENT_TYPE_INFO[typeId]?.type || "海域"}卡。`,
        typeId,
        cardBack: getSeaCardBackImage(typeId),
        summary: "正在從 4 個寶箱中選擇",
        chips: [SEA_EVENT_TYPE_INFO[typeId]?.type || "未知", "寶箱抽選"],
      });
      recordMissionEvent(player, { type: "sea_event", seaType: typeId, zone: tile?.zone || "" });
      openSeaTreasureChestDraft(player, tile, effectDef, typeId, slotId);
      return;
    }
    emitSpectatorModalEvent("sea-result", player, {
      playerName: player.name,
      title: effectDef.title,
      desc: effectDef.desc,
      subtitle: `${player.name} 翻開了一張${SEA_EVENT_TYPE_INFO[typeId]?.type || "海域"}卡。`,
      typeId,
      cardBack: getSeaCardBackImage(typeId),
      summary: result.summary || "效果已套用",
      chips: [SEA_EVENT_TYPE_INFO[typeId]?.type || "未知"],
    });
    recordMissionEvent(player, { type: "sea_event", seaType: typeId, zone: tile?.zone || "" });
    if (result.startSeaEncounter) {
      closeModal();
      addLog(`${player.name} 選擇「${SEA_EVENT_TYPE_INFO[typeId]?.type || "遭遇"}」事件卡，觸發「${effectDef.title}」。`);
      state.gameState.resolutionLock = false;
      startSeaEncounterBattle(player, tile, effectDef);
      return;
    }
    state.gameState.resolutionLock = true;
    openModal(seaEventResultUiMarkup({
      title: effectDef.title,
      subtitle: `${player.name} 翻開了一張${SEA_EVENT_TYPE_INFO[typeId]?.type || "海域"}卡。`,
      typeId,
      cardBack: getSeaCardBackImage(typeId),
      desc: effectDef.desc,
      summary: result.summary || "效果已套用",
      chips: result.placeholder ? ["placeholder"] : [],
      action: { id: "confirmSeaEventBtn", label: "確認" },
    }), "sea-event-result-modal force-choice no-backdrop-close");
    document.getElementById("confirmSeaEventBtn")?.addEventListener("click", () => {
      closeModal();
      addLog(`${player.name} 選擇「${SEA_EVENT_TYPE_INFO[typeId]?.type || "未知"}」事件卡，觸發「${effectDef.title}」：${result.summary || "效果已生效"}`);
      state.gameState.resolutionLock = false;
      applyPostResolution(player, result);
    });
  }

  function drawSeaCardEffect(typeId, tile, player, slotId = "") {
    if (typeId === "chest") {
      return {
        title: "寶箱海域",
        desc: "海上漂來四個外型一樣的寶箱，洗牌後只能選一個。",
        chestProfile: "standard",
        apply() { return { summary: "從 4 個寶箱中抽 1 個", openTreasureChestDraft: true }; },
      };
    }
    const rand = createRng(`${state.gameState.seed}-${tile.id}-${player.id}-${slotId || typeId}-${state.gameState.log.length}`);
    const pool = SEA_CARD_EFFECTS[typeId] || SEA_CARD_EFFECTS.money;
    return pool[Math.floor(rand() * pool.length)];
  }

  function triggerChestEvent(player, tile) {
    if (warnBoardLanTurnLocked(player)) return;
    const effectDef = {
      title: "寶箱海域",
      desc: "海上漂來四個外型一樣的寶箱，洗牌後只能選一個。",
      chestProfile: "standard",
    };
    emitSpectatorModalEvent("sea-result", player, {
      playerName: player.name,
      title: effectDef.title,
      desc: effectDef.desc,
      subtitle: `${player.name} 正在選擇漂流寶箱。`,
      typeId: "treasure",
      cardBack: getSeaCardBackImage("treasure"),
      summary: "正在從 4 個寶箱中選擇",
      chips: ["寶箱海域", "寶箱抽選"],
    });
    openSeaTreasureChestDraft(player, tile, effectDef, "treasure", tile?.id || "chest");
  }

  function applyPostResolution(player, result) {
    if (warnBoardLanTurnLocked(player)) return;
    renderAll();
    if (result.captured) {
      endTurn();
      return;
    }
    if (result.startSeaEncounter) {
      const tile = state.gameState.boardData.seaTiles.find((entry) => entry.id === result.tileId) || null;
      startSeaEncounterBattle(player, tile);
      return;
    }
    if (result.teleportToNearestShop) {
      teleportPlayerToNearestShop(player);
      addLog(`${player.name} 被暴風雨吹向最近的商店島。`);
      renderAll();
      endTurn();
      return;
    }
    if (result.randomTeleportOnRoute) {
      teleportPlayerWithinRoute(player, result.tileId);
      addLog(`${player.name} 被亂風吹到同航線的另一處海域。`);
      renderAll();
      endTurn();
      return;
    }
    if (result.continueMove) {
      state.gameState.pendingMove = { playerId: player.id, stepsRemaining: result.continueMove };
      state.gameState.turnStep = `事件效果：再前進 ${result.continueMove} 格`;
      renderAll();
      continueMove();
      return;
    }
    if (result.reverseMove) {
      movePlayerBackward(player, result.reverseMove);
      renderAll();
      endTurn();
      return;
    }
    endTurn();
  }

  function teleportPlayerWithinRoute(player, tileId) {
    const source = state.gameState.boardData.seaTiles.find((tile) => tile.id === tileId);
    if (!source) return;
    const sameRoute = state.gameState.boardData.seaTiles.filter((tile) => tile.routeId === source.routeId && tile.id !== source.id);
    if (!sameRoute.length) return;
    const pick = sameRoute[randomInt(0, sameRoute.length - 1)];
    player.location = {
      kind: "route",
      routeId: pick.routeId,
      tileIndex: pick.index,
      fromIslandId: getRouteById(pick.routeId).from,
      toIslandId: getRouteById(pick.routeId).to,
    };
  }

  function movePlayerBackward(player, steps) {
    if (player.location.kind !== "route") return;
    const routeItem = getRouteById(player.location.routeId);
    const travel = traversalFromIsland(routeItem, player.location.fromIslandId);
    const currentIndex = travel.tiles.findIndex((tileItem) => tileItem.index === player.location.tileIndex);
    const nextIndex = Math.max(0, currentIndex - steps);
    const nextTile = travel.tiles[nextIndex];
    if (!nextTile) return;
    player.location.tileIndex = nextTile.index;
    addLog(`${player.name} 被海流帶回海格 ${nextTile.col}, ${nextTile.row}。`);
  }

  function teleportPlayerToNearestShop(player) {
    const currentPos = playerPositionPx(player);
    const shops = state.gameState.boardData.islands.filter((island) => getEffectiveIslandKind(island) === "shop");
    const target = shops.reduce((best, island) => {
      const pos = nodeToPx(island);
      const dist = Math.hypot(pos.x - currentPos.x, pos.y - currentPos.y);
      if (!best || dist < best.dist) return { island, dist };
      return best;
    }, null);
    if (target) {
      player.location = { kind: "island", islandId: target.island.id };
      clearForcedReturnRoute(player);
    }
  }

  function shopItemIcon(item) {
    if (item?.id === "heal_2") return "補";
    if (item?.id === "battle_food") return "食";
    if (item?.id === "armor") return "護";
    if (item?.id === "pointer") return "針";
    if (item?.id === "fixed_step") return "券";
    return "道";
  }

  function shopItemPocketName(item) {
    const def = gameItemDef(item?.id);
    return ITEM_CATEGORY_LABELS[normalizeGameItemCategory(def?.category || item?.category)] || "道具";
  }

  function normalizeShopStock(stock) {
    return (Array.isArray(stock) ? stock : [])
      .map((entry) => SHOP_ITEM_BY_ID[typeof entry === "string" ? entry : entry?.id])
      .filter(Boolean);
  }

  function availableShopItemsForPlayer(player) {
    return SHOP_ITEMS;
  }

  function normalizeShopStockForPlayer(stock, player) {
    return normalizeShopStock(stock);
  }

  function createShopStock(rand = Math.random, player = null) {
    const pool = availableShopItemsForPlayer(player);
    return pool.map((item) => ({ id: item.id }));
  }

  function readShopStock(islandState, player = null) {
    const unlockStage = "ALL";
    const stock = normalizeShopStockForPlayer(islandState?.shopStock, player);
    if (stock.length >= SHOP_ITEMS.length && islandState?.shopStockUnlockStage === unlockStage) return stock;
    const generated = createShopStock(createRng(`${Date.now()}-${unlockStage}`), player);
    if (islandState) {
      islandState.shopStock = generated;
      islandState.shopStockUnlockStage = unlockStage;
    }
    return normalizeShopStock(generated);
  }

  function shopItemUnlockText() {
    return "";
  }

  function grantShopItemToBackpack(player, item, quantity, effects) {
    const count = Math.max(1, Number(quantity) || 1);
    const itemDef = gameItemDef(item?.id);
    if (itemDef) {
      if (normalizeGameItemCategory(itemDef.category) === "held") {
        let added = 0;
        for (let index = 0; index < count; index += 1) {
          if (addBattleCarryItemToBackpack(player, itemDef.id)) added += 1;
        }
        if (added > 0) recordMissionEvent(player, { type: "obtain_item", itemId: itemDef.id, itemName: itemDef.name, category: "held", amount: added }, added);
        return `${itemDef.name} +${added}`;
      }
      addInventoryItem(player, itemDef.id, count);
      if (itemDef.id === "heal_2") player.smallSupplies = Math.max(0, Number(player.smallSupplies || 0)) + count;
      if (itemDef.id === "battle_food") player.battleFood = Math.max(0, Number(player.battleFood || 0)) + count;
      if (itemDef.id === "guard_charm") player.guardCharm = Math.max(0, Number(player.guardCharm || 0)) + count;
      if (itemDef.id === "pointer") player.routeInsight = Math.max(0, Number(player.routeInsight || 0)) + count;
      if (itemDef.id === "fixed_step") player.fixedStepTokens = Math.max(0, Number(player.fixedStepTokens || 0)) + count;
      recordMissionEvent(player, { type: "obtain_item", itemId: itemDef.id, itemName: itemDef.name, category: normalizeGameItemCategory(itemDef.category), amount: count }, count);
      if (itemDef.important) queueImportantItemReveal(itemDef, count);
      return `${itemDef.name} +${count}`;
    }
    if (item.id === "heal_2") {
      player.smallSupplies = Math.max(0, Number(player.smallSupplies || 0)) + count;
      return `小補給 +${count}`;
    }
    if (item.id === "battle_food") {
      player.battleFood = Math.max(0, Number(player.battleFood || 0)) + count;
      return `戰鬥糧食 +${count}`;
    }
    if (item.id === "armor") {
      player.guardCharm = Math.max(0, Number(player.guardCharm || 0)) + count;
      return `防具 / 守護護符 +${count}`;
    }
    if (item.id === "pointer") {
      player.routeInsight = Math.max(0, Number(player.routeInsight || 0)) + count;
      return `航海指針 +${count}`;
    }
    if (item.id === "fixed_step") {
      player.fixedStepTokens = Math.max(0, Number(player.fixedStepTokens || 0)) + count;
      return `指定步數券 +${count}`;
    }
    const summary = item.apply?.(player, effects);
    return summary || `${item.name} +${count}`;
  }

  function currentShopListScrollTop() {
    return Math.max(0, Math.round(Number(refs.modal?.querySelector(".shop-list")?.scrollTop || 0)));
  }

  function shopSpectatorDetail(player, island, islandState, selectedItemId = "", notice = "", extra = {}) {
    const effects = getTeamEffects(player);
    const stock = readShopStock(islandState, player).map((item) => {
      const finalCost = Math.max(1, Math.round(item.cost * (1 - effects.shopDiscount)));
      return {
        id: item.id,
        name: item.name,
        cost: item.cost,
        finalCost,
        type: item.type,
        category: item.category,
        rarity: item.rarity,
        image: item.image || "",
        desc: item.desc || "",
        lockedText: shopItemUnlockText(player, item),
        icon: shopItemIcon(item),
        pocketName: shopItemPocketName(item),
      };
    });
    const selectedItem = stock.find((entry) => entry.id === selectedItemId) || stock[0] || null;
    return {
      playerName: player?.name || "玩家",
      islandName: island?.name || "商店",
      coins: Number(player?.coins || 0),
      selectedItemId: selectedItem?.id || "",
      notice: notice || "",
      stock,
      ...extra,
    };
  }

  function performShopPurchase(player, island, islandState, item, quantity, returnScrollTop = 0) {
    const effects = getTeamEffects(player);
    const count = Math.max(1, Number(quantity) || 1);
    const finalCost = Math.max(1, Math.round(item.cost * (1 - effects.shopDiscount)));
    const totalCost = finalCost * count;
    if (player.coins < totalCost) {
      openShopModal(player, island, islandState, item.id, "貝里不足，無法購買。", returnScrollTop);
      return false;
    }
    player.coins -= totalCost;
    const summary = grantShopItemToBackpack(player, item, count, effects);
    addLog(`${player.name} 在 ${island.name} 購買了 ${item.name} ×${count}：${summary}（花費 ${totalCost}）`);
    emitBoardActionNotice("purchase", "購買道具", `${player.name} 在 ${island.name} 購買 ${item.name} ×${count}`, {
      player,
      itemId: item.id,
      itemName: item.name,
      quantity: count,
      theme: "treasure",
      symbol: "買",
    }, { immediate: true });
    recordMissionEvent(player, { type: "shop_buy", itemId: item.id, itemName: item.name, amount: count }, count);
    recordMissionEvent(player, { type: "island_service", islandKind: "shop" });
    recalcPlayerDerivedStats(player);
    renderAll();
    openShopModal(player, island, islandState, item.id, `已購買：${summary}`, returnScrollTop, {
      purchase: {
        itemId: item.id,
        itemName: item.name,
        count,
        totalCost,
        summary,
      },
    });
    return true;
  }

  function openShopQuantityModal(player, island, islandState, itemId, returnScrollTop = 0) {
    if (warnBoardLanTurnLocked(player)) return;
    const item = SHOP_ITEM_BY_ID[itemId];
    if (!item) return openShopModal(player, island, islandState, "", "", returnScrollTop);
    const effects = getTeamEffects(player);
    const finalCost = Math.max(1, Math.round(item.cost * (1 - effects.shopDiscount)));
    const maxQuantity = Math.max(0, Math.min(99, Math.floor(player.coins / finalCost)));
    if (maxQuantity <= 0) {
      openShopModal(player, island, islandState, item.id, "貝里不足，無法購買。", returnScrollTop);
      return;
    }
    emitSpectatorModalEvent("shop", player, shopSpectatorDetail(player, island, islandState, item.id, "正在選擇購買數量。", {
      quantityChoice: {
        itemId: item.id,
        itemName: item.name,
        finalCost,
        maxQuantity,
      },
    }));
    openModal(`
      <div class="shop-quantity-box">
        <h3 class="shop-quantity-title">購買數量</h3>
        <div class="shop-quantity-art">
          ${itemIconMarkup(item, "shop-quantity-thumb", { badge: shopItemIcon(item) })}
        </div>
        <div class="shop-quantity-item">
          <span>${escapeModalText(item.name)}</span>
          <strong>${formatCoin(finalCost)} ฿ / 個</strong>
        </div>
        <div class="shop-quantity-control">
          <button type="button" class="modal-btn secondary" id="shopQtyMinus">-</button>
          <strong id="shopQtyValue">1</strong>
          <button type="button" class="modal-btn secondary" id="shopQtyPlus">+</button>
        </div>
        <div class="shop-quantity-total">
          <span>最多 ${maxQuantity} 個</span>
          <strong id="shopQtyTotal">${formatCoin(finalCost)} 貝里</strong>
        </div>
      </div>
      <div class="modal-row">
        <button type="button" class="modal-btn primary" id="shopQtyConfirm">確定購買</button>
        <button type="button" class="modal-btn secondary" id="shopQtyCancel">取消</button>
      </div>
    `, "shop-modal shop-quantity-modal no-backdrop-close");
    let quantity = 1;
    const qtyValue = document.getElementById("shopQtyValue");
    const qtyTotal = document.getElementById("shopQtyTotal");
    const updateQuantity = () => {
      qtyValue.textContent = String(quantity);
      qtyTotal.textContent = `${formatCoin(finalCost * quantity)} 貝里`;
    };
    document.getElementById("shopQtyMinus")?.addEventListener("click", () => {
      quantity = quantity <= 1 ? maxQuantity : Math.max(1, quantity - 1);
      updateQuantity();
    });
    document.getElementById("shopQtyPlus")?.addEventListener("click", () => {
      quantity = Math.min(maxQuantity, quantity + 1);
      updateQuantity();
    });
    document.getElementById("shopQtyConfirm")?.addEventListener("click", () => {
      performShopPurchase(player, island, islandState, item, quantity, returnScrollTop);
    });
    document.getElementById("shopQtyCancel")?.addEventListener("click", () => {
      openShopModal(player, island, islandState, item.id, "", returnScrollTop);
    });
  }

  function openShopModal(player, island, islandState, selectedItemId = "", notice = "", listScrollTop = 0, spectatorExtra = {}) {
    if (warnBoardLanTurnLocked(player)) return;
    playBgmForContext({
      phase: "shop",
      sceneType: "shop",
      locationType: "island",
      islandType: "shop",
      character: bgmCharacterTag(activeCrew(player)),
      environment: ["food", "village"],
      eventTags: ["shop", "food", "npc", "daily"],
      storyMood: "warm",
    });
    const effects = getTeamEffects(player);
    const stock = readShopStock(islandState, player);
    const selectedItem = stock.find((entry) => entry.id === selectedItemId) || stock[0];
    const selectedCost = selectedItem ? Math.max(1, Math.round(selectedItem.cost * (1 - effects.shopDiscount))) : 0;
    const selectedLockedText = shopItemUnlockText(player, selectedItem);
    const canBuySelected = !!selectedItem && !selectedLockedText && player.coins >= selectedCost;
    const buyButtonText = selectedLockedText ? "懸賞不足" : (canBuySelected ? "購買" : "貝里不足");
    openModal(`
      <h3 class="shop-title">${escapeModalText(island?.name || "航海商店")}</h3>
      <div class="shop-shell">
        <aside class="shop-side">
          <div class="shop-money-box">
            <span>金錢</span>
            <strong>${formatCoin(player.coins)} 貝里</strong>
          </div>
          <div class="shop-counter" aria-hidden="true">
            <img class="shopkeeper-image" src="images/board/shops/shopkeeper.webp" alt="" onerror="this.hidden=true">
            <div class="shop-clerk-row"><span></span><span></span></div>
            <div class="shop-counter-desk"></div>
            <div class="shop-player-dot"></div>
          </div>
        </aside>
        <section class="shop-list-panel">
          <div class="shop-list-head">
            <span>商品</span>
            <span>售價</span>
          </div>
          <div class="shop-list">
        ${stock.map((item) => {
          const finalCost = Math.max(1, Math.round(item.cost * (1 - effects.shopDiscount)));
          const lockedText = shopItemUnlockText(player, item);
          return `
            <button type="button" class="shop-item-row ${item.id === selectedItem?.id ? "is-selected" : ""}${lockedText ? " is-locked" : ""}" data-shop-select="${escapeModalText(item.id)}">
              <span class="shop-cursor">▶</span>
              ${itemIconMarkup(item, "shop-row-thumb", { badge: shopItemIcon(item) })}
              <span class="shop-item-name">${escapeModalText(item.name)}</span>
              <span class="shop-item-price">${formatCoin(finalCost)} ฿</span>
              <em class="shop-row-status${lockedText ? " is-locked" : ""}">${lockedText ? "鎖" : ""}</em>
            </button>
          `;
        }).join("")}
            <button type="button" class="shop-item-row shop-cancel-row" id="leaveShopListBtn">
              <span class="shop-cursor"></span>
              <span class="shop-row-thumb item-thumb fallback" data-item-fallback=""><span class="item-thumb-fallback"></span></span>
              <span class="shop-item-name">取消</span>
              <span class="shop-item-price"></span>
              <em class="shop-row-status"></em>
            </button>
          </div>
        </section>
      </div>
      <div class="shop-description-bar">
        <div class="shop-desc-icon">${selectedItem ? itemIconMarkup(selectedItem, "shop-desc-thumb", { badge: shopItemIcon(selectedItem) }) : escapeModalText(shopItemIcon(selectedItem))}</div>
        <div class="shop-desc-text">
          <strong>${escapeModalText(selectedItem?.name || "沒有商品")}</strong>
          <span>${escapeModalText(selectedItem ? `${shopItemPocketName(selectedItem)} ・ ${selectedItem.desc}` : "這間商店目前沒有商品。")}</span>
          ${selectedLockedText ? `<em>${escapeModalText(selectedLockedText)}</em>` : ""}
          ${notice ? `<em>${escapeModalText(notice)}</em>` : ""}
        </div>
        <button type="button" class="modal-btn primary shop-buy-btn" id="shopBuyBtn" ${canBuySelected ? "" : "disabled"}>${buyButtonText}</button>
      </div>
      <div class="modal-row">
        <button type="button" class="modal-btn secondary" id="leaveShopBtn">離開商店</button>
      </div>
    `, "shop-modal no-backdrop-close");
    const shopList = refs.modal?.querySelector(".shop-list");
    if (shopList && Number(listScrollTop) > 0) {
      requestAnimationFrame(() => {
        shopList.scrollTop = Math.max(0, Number(listScrollTop) || 0);
      });
    }
    Array.from(refs.modal.querySelectorAll("[data-shop-select]")).forEach((button) => {
      button.addEventListener("click", () => {
        openShopModal(player, island, islandState, button.dataset.shopSelect, "", currentShopListScrollTop());
      });
    });
    document.getElementById("shopBuyBtn")?.addEventListener("click", () => {
      const item = selectedItem;
      if (!item) return;
      const lockedText = shopItemUnlockText(player, item);
      if (lockedText) {
        openShopModal(player, island, islandState, item.id, lockedText, currentShopListScrollTop());
        return;
      }
      const finalCost = Math.max(1, Math.round(item.cost * (1 - effects.shopDiscount)));
      if (player.coins < finalCost) {
        openShopModal(player, island, islandState, item.id, "貝里不足，無法購買。", currentShopListScrollTop());
        return;
      }
      openShopQuantityModal(player, island, islandState, item.id, currentShopListScrollTop());
    });
    const leaveShop = () => {
      finishIslandServiceTurn();
    };
    document.getElementById("leaveShopBtn")?.addEventListener("click", leaveShop);
    document.getElementById("leaveShopListBtn")?.addEventListener("click", leaveShop);
    emitSpectatorModalEvent("shop", player, shopSpectatorDetail(player, island, islandState, selectedItem?.id || selectedItemId, notice, spectatorExtra));
  }

  function finishIslandServiceTurn() {
    closeModal();
    endTurn();
    schedulePendingMoveLearn();
  }

  function researchInstanceToken(value, fallback = "card") {
    const token = String(value || "")
      .normalize("NFKD")
      .replace(/[^\w-]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .toLowerCase();
    return token || fallback;
  }

  function researchLevelForPoints(points = 0) {
    const normalized = Math.max(0, Math.floor(Number(points || 0)));
    let level = 1;
    RESEARCH_LEVEL_THRESHOLDS.forEach((threshold, index) => {
      if (normalized >= threshold) level = index + 1;
    });
    return Math.min(RESEARCH_LEVEL_THRESHOLDS.length, level);
  }

  function researchLevelForPlayer(player) {
    return ensurePlayerResearchLabState(player).researchLevel;
  }

  function researchExtractorConfig(itemOrId) {
    const id = typeof itemOrId === "string" ? itemOrId : itemOrId?.id;
    return RESEARCH_LAB_EXTRACTOR_DEFS.find((entry) => entry.id === id) || null;
  }

  function researchExtractorCounts(player) {
    return Object.fromEntries(RESEARCH_LAB_EXTRACTOR_DEFS.map((entry) => [entry.id, inventoryItemCount(player, entry.id)]));
  }

  const LINEAGE_EXISTING_TEMPLATE_BY_ENEMY_KEY = Object.freeze({
    aokiji: "kuzan",
    buggy: "prison_buggy",
    crocodile: "prison_crocodile",
    mr1_daz_bones: "prison_mr1_daz_bones",
    mr2_bon_clay: "prison_mr2_bon_clay",
    mr3: "prison_mr3",
  });
  const LINEAGE_ENEMY_KEY_ALIASES = Object.freeze({
    rob_lucci: "lucci",
    postgame_rob_lucci_awakened: "lucci",
  });
  const LINEAGE_ENDGAME_BOSS_KEYS = new Set([
    ...Object.keys(POSTGAME_BOSS_PROFILES),
    String(POSTGAME_ROCKS_PROFILE.key || "postgame_rocks"),
  ]);
  const LINEAGE_ENDGAME_BOSS_STAT_MULTIPLIER = 1.15;
  const LINEAGE_ROCKS_STAT_MULTIPLIER = 1.25;
  const LINEAGE_ENDGAME_BOSS_MOVE_POWERS = Object.freeze([65, 82, 102, 128]);
  const LINEAGE_ROCKS_MOVE_POWERS = Object.freeze([70, 90, 115, 140]);

  function lineageEndgameBossSourceKey(value) {
    const explicitCandidates = [
      value?.cultivatedFromEnemyKey,
      value?.lineageSourceEnemyKey,
      value?.enemyKey,
      value?.key,
    ];
    for (const candidate of explicitCandidates) {
      const key = String(candidate || "").trim();
      if (LINEAGE_ENDGAME_BOSS_KEYS.has(key)) return key;
    }
    const cardId = String(value?.id || "").trim();
    if (cardId.startsWith("lineage_")) {
      const inferred = cardId.slice("lineage_".length);
      if (LINEAGE_ENDGAME_BOSS_KEYS.has(inferred)) return inferred;
    }
    return "";
  }

  function lineageEndgameBossStatMultiplier(value) {
    const sourceKey = lineageEndgameBossSourceKey(value);
    if (!sourceKey) return 1;
    return sourceKey === String(POSTGAME_ROCKS_PROFILE.key || "postgame_rocks")
      ? LINEAGE_ROCKS_STAT_MULTIPLIER
      : LINEAGE_ENDGAME_BOSS_STAT_MULTIPLIER;
  }

  function applyLineageEndgameBossStatModifiers(stats, card) {
    const multiplier = lineageEndgameBossStatMultiplier(card);
    if (multiplier === 1) return { ...stats };
    return Object.fromEntries(TRAINING_STATS.map((stat) => [
      stat,
      Math.max(1, Math.round((Number(stats?.[stat] || 1) * multiplier) + 1e-8)),
    ]));
  }

  function lineageEndgameBossMovePowers(value) {
    const sourceKey = lineageEndgameBossSourceKey(value);
    if (!sourceKey) return null;
    return sourceKey === String(POSTGAME_ROCKS_PROFILE.key || "postgame_rocks")
      ? LINEAGE_ROCKS_MOVE_POWERS
      : LINEAGE_ENDGAME_BOSS_MOVE_POWERS;
  }

  function applyLineageEndgameBossMovePowers(moveSet, value) {
    const powers = lineageEndgameBossMovePowers(value);
    if (!powers) return moveSet;
    const damageMoveCount = (moveSet || []).filter((entry) => {
      const category = String(entry?.category || entry?.type || "");
      return ["attack", "special"].includes(category) && Number(entry?.power || 0) > 0;
    }).length;
    let damageIndex = 0;
    return (moveSet || []).map((entry) => {
      const next = { ...entry };
      const category = String(next.category || next.type || "");
      if (["attack", "special"].includes(category) && Number(next.power || 0) > 0) {
        const powerIndex = damageMoveCount <= 1
          ? powers.length - 1
          : damageMoveCount < powers.length
            ? Math.round((damageIndex * (powers.length - 1)) / (damageMoveCount - 1))
            : Math.min(powers.length - 1, damageIndex);
        next.power = powers[powerIndex] || powers[powers.length - 1];
        damageIndex += 1;
      }
      return next;
    });
  }

