  function playerOwnsShipGear(player, itemId) {
    const item = gameItemDef(itemId);
    if (!item || normalizeGameItemCategory(item.category) !== "ship" || item.effect?.kind !== "ship_equipment") return false;
    return inventoryItemCount(player, item.id) > 0;
  }

  function waterSevenCommandUpgrade(player, partId) {
    const part = WATER_SEVEN_UPGRADE_PARTS.includes(partId) ? partId : "";
    if (!part) return { ok: false, message: "找不到這個升級部位。" };
    const shipState = normalizePlayerShipState(player);
    const level = Math.max(0, Math.min(3, Math.round(Number(shipState.upgradeLevels[part] || 0))));
    if (level >= 3) return { ok: false, message: `${waterSevenPartLabel(part)} 已經滿級。` };
    const cost = WATER_SEVEN_UPGRADE_COSTS[part]?.[level];
    if (!cost) return { ok: false, message: "升級費用資料不完整。" };
    if (!waterSevenCanSpendCost(player, cost)) return { ok: false, message: `材料或貝里不足：${waterSevenCostSummary(cost)}` };
    waterSevenSpendCost(player, cost);
    player.shipUpgradeLevels[part] = level + 1;
    addLog(`${player.name} 在水之七島升級 ${waterSevenPartLabel(part)} 到 Lv.${level + 1}。`);
    recordMainMissionEvent(player, { type: "ship_upgrade", partId: part, level: level + 1 });
    return { ok: true, message: `${waterSevenPartLabel(part)} 升到 Lv${level + 1}` };
  }

  function waterSevenCommandOpenSlot(player) {
    const shipState = normalizePlayerShipState(player);
    const nextSlot = shipState.slotsUnlocked;
    if (nextSlot >= WATER_SEVEN_SLOT_COUNT) return { ok: false, message: "船隻孔位已全部開啟。" };
    const cost = WATER_SEVEN_SLOT_COSTS[nextSlot];
    if (!waterSevenCanSpendCost(player, cost)) return { ok: false, message: `開孔材料不足：${waterSevenCostSummary(cost)}` };
    waterSevenSpendCost(player, cost);
    player.shipSlotsUnlocked = nextSlot + 1;
    normalizePlayerShipState(player);
    addLog(`${player.name} 在水之七島開啟船隻孔位 ${nextSlot + 1}。`);
    recordMainMissionEvent(player, { type: "ship_slot_open", slot: nextSlot + 1 });
    return { ok: true, message: `船隻孔位 ${nextSlot + 1} 已開啟` };
  }

  function waterSevenCommandEquipGear(player, itemId) {
    const item = gameItemDef(itemId);
    if (!item || normalizeGameItemCategory(item.category) !== "ship" || item.effect?.kind !== "ship_equipment") {
      return { ok: false, message: "這不是船隻裝備。" };
    }
    if (!playerOwnsShipGear(player, item.id)) return { ok: false, message: "背包沒有這件船隻裝備。" };
    const shipState = normalizePlayerShipState(player);
    const currentIndex = shipState.equippedGear.indexOf(item.id);
    if (currentIndex >= 0) {
      player.shipEquippedGear[currentIndex] = null;
      normalizePlayerShipState(player);
      addLog(`${player.name} 卸下船隻裝備：${item.name}。`);
      return { ok: true, message: `已卸下 ${item.name}` };
    }
    const itemRank = itemRarityLabel(item.rarity);
    if (itemRank === "S" && shipState.equippedGear.some((gearId) => {
      const gear = gameItemDef(gearId);
      return gear && itemRarityLabel(gear.rarity) === "S";
    })) {
      return { ok: false, message: "每艘船同時只能裝 1 件 S 級船隻裝備。" };
    }
    const emptyIndex = shipState.equippedGear.findIndex((gearId, index) => index < shipState.slotsUnlocked && !gearId);
    if (emptyIndex < 0) return { ok: false, message: "沒有空孔位，先在水之七島開孔。" };
    player.shipEquippedGear[emptyIndex] = item.id;
    normalizePlayerShipState(player);
    addLog(`${player.name} 裝備船隻道具：${item.name}（孔位 ${emptyIndex + 1}）。`);
    recordMainMissionEvent(player, { type: "ship_gear_equip", itemId: item.id });
    return { ok: true, message: `${item.name} 已裝到孔位 ${emptyIndex + 1}` };
  }

  function waterSevenCommandUnequipSlot(player, slotIndex) {
    const index = Math.max(0, Math.min(WATER_SEVEN_SLOT_COUNT - 1, Math.round(Number(slotIndex || 0))));
    const shipState = normalizePlayerShipState(player);
    if (index >= shipState.slotsUnlocked) return { ok: false, message: "這個孔位尚未開啟。" };
    const itemId = shipState.equippedGear[index];
    if (!itemId) return { ok: false, message: "這個孔位沒有裝備。" };
    const item = gameItemDef(itemId);
    player.shipEquippedGear[index] = null;
    normalizePlayerShipState(player);
    addLog(`${player.name} 卸下船隻裝備：${item?.name || itemId}。`);
    return { ok: true, message: `已卸下 ${item?.name || "船隻裝備"}` };
  }

  function processWaterSevenPageCommand(command = {}) {
    const player = currentPlayer();
    if (!player) {
      postWaterSevenCommandResult(false, "目前沒有可寫入的玩家。");
      return;
    }
    if (warnBoardLanTurnLocked(player)) {
      postWaterSevenCommandResult(false, "現在不是你的回合，不能改造船隻。", player);
      return;
    }
    normalizePlayerShipState(player);
    let result = { ok: false, message: "無法辨識水之七島操作。" };
    if (command.type === "upgrade") result = waterSevenCommandUpgrade(player, String(command.upgradeId || ""));
    if (command.type === "open-slot") result = waterSevenCommandOpenSlot(player);
    if (command.type === "equip-gear") result = waterSevenCommandEquipGear(player, String(command.itemId || ""));
    if (command.type === "unequip-slot") result = waterSevenCommandUnequipSlot(player, command.slotIndex);
    if (result.ok) {
      recalcPlayerDerivedStats(player);
      renderAll();
      notifyWaterSevenWindow(player);
    } else {
      writeWaterSevenSnapshot(player);
    }
    postWaterSevenCommandResult(result.ok, result.message, player);
  }

