  async function waitBattleWindowVisual(event, fallbackDuration = 900) {
    if (!battleWindowIsActive()) return;
    const duration = Math.max(0, Number(event?.duration || fallbackDuration));
    await wait(duration + 420);
  }

  function renderBattleInterface() {
    syncBattleReplacementActiveCrewIndex();
    if (refs.modalBack?.classList.contains("open")) closeModal();
    playBgmForContext(bgmBattleContext(state.battleState));
    openBattleWindow();
    notifyBattleWindow();
    scheduleBattlePrebattleIntroRecovery(state.battleState);
    scheduleMarinefordBattleAutoFinish(battlePlayer(null, state.battleState), state.battleState);
    scheduleElbaphGodKnightBattleAutoFinish(battlePlayer(null, state.battleState), state.battleState);
    scheduleBattleLanStatePush("battle-open", 0);
  }

  function stageMultiplier(stage) {
    const value = Math.max(-BATTLE_STAGE_LIMIT, Math.min(BATTLE_STAGE_LIMIT, Number(stage || 0)));
    if (value >= 0) return 1 + value * BATTLE_STAGE_STEP_RATIO;
    return 1 / (1 + Math.abs(value) * BATTLE_STAGE_STEP_RATIO);
  }

  function currentBattleStat(side, stat, player, battle = state.battleState) {
    const normalizedStat = normalizeBattleStageKey(stat);
    if (side === "player") {
      const activeCard = battleActiveCard(player, battle);
      const base = activeCard.baseStats[normalizedStat] ?? activeCard.baseStats[stat] ?? 1;
      const stage = (battle.playerStages?.[normalizedStat] || 0) + (normalizedStat !== stat ? (battle.playerStages?.[stat] || 0) : 0);
      let value = base * stageMultiplier(stage);
      const statuses = battleStatusBag("player", battle);
      const carryContexts = activePlayerCarryContexts(player, battle);
      if ((normalizedStat === "atk" || normalizedStat === "satk") && statuses.burn > 0) {
        value *= BATTLE_STATUS_INFO.burn.attackMultiplier;
      }
      carryContexts.forEach(({ item }) => {
        const carryEffect = battleCarryItemEffect(item);
        if (normalizedStat === "atk" && carryEffect.kind === "postgame_rocks_eclipse") value *= Number(carryEffect.atkMultiplier || 1.2);
        if (normalizedStat === "satk" && carryEffect.kind === "postgame_rocks_eclipse") value *= Number(carryEffect.satkMultiplier || 1.2);
        if (normalizedStat === "atk" && carryEffect.kind === "postgame_shiki_oto_kogarashi") value *= Number(carryEffect.atkMultiplier || 1.2);
        if (normalizedStat === "atk" && carryEffect.kind === "zoro_enma") value *= Number(carryEffect.atkMultiplier || 1.15);
        if (normalizedStat === "satk" && carryEffect.kind === "postgame_katakuri_mogura") value *= Number(carryEffect.satkMultiplier || 1.3);
        if (normalizedStat === "satk" && carryEffect.kind === "postgame_loki_ragnir") value *= Number(carryEffect.satkMultiplier || 1.2);
      });
      if (normalizedStat === "spd") {
        if (statuses.paralyze > 0) value *= BATTLE_STATUS_INFO.paralyze.speedMultiplier;
        if (statuses.freeze > 0) value *= BATTLE_STATUS_INFO.freeze.speedMultiplier;
        carryContexts.forEach(({ item, state: carryState }) => {
          const carryEffect = battleCarryItemEffect(item);
          if (item.id === "wind_dial") value *= 1.15;
          if (carryEffect.kind === "temporary_speed_multiplier") value *= Number(carryEffect.multiplier || 1);
          if (carryEffect.kind === "choice_lock_speed_bonus") value *= 1 + Number(carryEffect.speedBonus || 0);
          if (item.id === "iron_ball" && carryEffect.kind !== "speed_down_damage_reduction") value *= 0.7;
          if (carryEffect.kind === "speed_down_immune_displacement") value *= Number(carryEffect.speedMultiplier || 1);
          if (carryEffect.kind === "speed_down_damage_reduction") value *= Number(carryEffect.speedMultiplier || 1);
          if (carryEffect.kind === "postgame_lucci_black_flame") value *= Number(carryEffect.speedMultiplier || 1.3);
          if (carryEffect.kind === "postgame_oars_giant_belt") value *= Number(carryEffect.speedMultiplier || 0.7);
          if (carryEffect.kind === "postgame_shiki_oto_kogarashi") value *= Number(carryEffect.speedMultiplier || 1.2);
          if (carryEffect.kind === "postgame_king_sword" && carryState?.kingFlameOn === false) value *= Number(carryEffect.unlitSpeedMultiplier || 1.25);
          if (item.id === "iron_cloud") value *= 0.95;
        });
      }
      if (normalizedStat === "spd") {
        if (battle.playerRoundEffects?.fieldSpeedUp) value += 6;
        const teamEffects = getTeamEffects(player);
        value *= 1 + Number(teamEffects.movementSpeedBonus || 0);
        if (Number(teamEffects.shipSpeedBoostTurns || 0) > 0 && Number(battle?.roundIndex || 0) <= Number(teamEffects.shipSpeedBoostTurns || 0)) {
          value *= 1.05;
        }
        if (isYonkoBattleKey(battle, "yonko_blackbeard") && blackbeardActiveDarkState(player, battle).stacks >= 1) value *= stageMultiplier(-1);
      }
      value *= characterPassiveStatMultiplier(activeCard, normalizedStat);
      return Math.max(1, Math.round(value));
    }
    const enemy = battle.enemyCombatant;
    const enemyStats = enemy.baseStats || enemy;
    const base = enemyStats[normalizedStat] ?? enemyStats[stat] ?? enemy[normalizedStat] ?? enemy[stat] ?? 1;
    const stage = (enemy.stages?.[normalizedStat] || 0) + (normalizedStat !== stat ? (enemy.stages?.[stat] || 0) : 0);
    let value = base * stageMultiplier(stage);
    const statuses = battleStatusBag("enemy", battle);
    if ((normalizedStat === "atk" || normalizedStat === "satk") && statuses.burn > 0) {
      value *= BATTLE_STATUS_INFO.burn.attackMultiplier;
    }
    if (normalizedStat === "spd") {
      if (statuses.paralyze > 0) value *= BATTLE_STATUS_INFO.paralyze.speedMultiplier;
      if (statuses.freeze > 0) value *= BATTLE_STATUS_INFO.freeze.speedMultiplier;
    }
    if (normalizedStat === "spd" && enemy.roundEffects?.fieldSpeedUp) value += 6;
    return postgameBossMechanicEnemyStat(Math.max(1, Math.round(value)), normalizedStat, player, battle);
  }

  function battleHpFor(player, battle = state.battleState) {
    const activeCard = battleActiveCard(player, battle);
    return activeCard?.currentHp ?? 0;
  }

  function opposingSideHasActed(side, battle) {
    return side === "player" ? !!battle?.enemyPerformedAction : !!battle?.playerPerformedAction;
  }

  function applyBattleShieldTiming(side, battle, ratio) {
    const value = Math.max(0, Number(ratio || 0));
    if (!value || !battle) return;
    const round = side === "player" ? battle.playerRoundEffects : battle.enemyCombatant?.roundEffects;
    if (!round) return;
    if (opposingSideHasActed(side, battle)) {
      round.nextShieldRatio = Math.max(Number(round.nextShieldRatio || 0), value);
      return;
    }
    round.shieldRatio = Math.max(Number(round.shieldRatio || 0), value);
  }

  function resetRoundEffects(target) {
    const carriedShieldRatio = Math.max(0, Number(target.nextShieldRatio || 0));
    target.shieldRatio = carriedShieldRatio;
    target.guaranteedFirst = false;
    target.guaranteedEscape = false;
    target.nextHitBoost = target.nextHitBoost || 0;
    target.nextShieldRatio = 0;
    target.damageTakenUp = 0;
    target.diceCapDown = 0;
    target.controlLock = false;
    target.fieldSpeedUp = false;
    target.reflectStatus = "";
    target.reflectRatio = 0;
    target.flinch = false;
  }

  function isBossLikeBattle(battle) {
    const rank = String(battle?.enemyCombatant?.rank || "").toUpperCase();
    return Boolean(
      battle?.isJudicialRaid
      || battle?.isMarineford
      || battle?.islandKind === "yonko"
      || battle?.enemyCombatant?.tier === "T1"
      || rank === "S"
    );
  }

  function applyShipBattleOpeningEffects(player, battle) {
    if (!battle || Number(battle.roundIndex || 0) !== 1) return;
    const effects = getTeamEffects(player);
    const bossLike = isBossLikeBattle(battle);
    const shieldRatio = bossLike && Number(effects.bossBattleStartShield || 0) > 0
      ? Number(effects.bossBattleStartShield || 0)
      : Number(effects.battleStartShield || 0);
    if (shieldRatio > 0) {
      battle.playerRoundEffects.shieldRatio = Math.max(Number(battle.playerRoundEffects.shieldRatio || 0), shieldRatio);
      battle.log.push(`船隻道具展開龍骨護盾，第一回合受到傷害 -${Math.round(shieldRatio * 100)}%。`);
    }
    if (Number(effects.firstBattleDamageReduction || 0) > 0) {
      battle.shipFirstDamageReduction = Math.max(Number(battle.shipFirstDamageReduction || 0), Number(effects.firstBattleDamageReduction || 0));
      battle.shipFirstDamageReductionUsed = false;
    }
    if (Number(effects.shipSpeedBoostTurns || 0) > 0) {
      battle.log.push(`船隻桅杆改造啟動，全隊速度 +5%，持續 ${Math.round(Number(effects.shipSpeedBoostTurns || 0))} 回合。`);
    }
  }

  function applyShipFirstBattleDamageReduction(totalDamage, player, battle) {
    let adjusted = Math.max(0, Number(totalDamage || 0));
    const firstReduction = Math.max(0, Math.min(0.75, Number(battle?.shipFirstDamageReduction || 0)));
    if (firstReduction && !battle?.shipFirstDamageReductionUsed && Number(battle?.roundIndex || 0) === 1) {
      battle.shipFirstDamageReductionUsed = true;
      adjusted = Math.max(1, Math.round(adjusted * (1 - firstReduction)));
      if (adjusted < totalDamage) battle.log.push(`${player.name} 的船隻防護減輕第一波衝擊，傷害 -${Math.round(firstReduction * 100)}%。`);
    }
    const switchReduction = Math.max(0, Math.min(0.75, Number(battle?.shipSwitchDamageReduction || 0)));
    if (switchReduction && !battle?.shipSwitchDamageReductionUsed) {
      battle.shipSwitchDamageReductionUsed = true;
      adjusted = Math.max(1, Math.round(adjusted * (1 - switchReduction)));
      battle.log.push(`${player.name} 的船尾改造保護換上場夥伴，下一次受傷 -${Math.round(switchReduction * 100)}%。`);
    }
    return adjusted;
  }

  function applyShipOpeningFirstStrikeDamageBonus(totalDamage, player, battle, side) {
    if (side !== "player" || Number(totalDamage || 0) <= 0) return totalDamage;
    if (Number(battle?.roundIndex || 0) !== 1 || battle?.enemyPerformedAction || battle?.shipOpeningFirstStrikeDamageBonusUsed) return totalDamage;
    const bonus = Math.max(0, Number(getTeamEffects(player).shipOpeningFirstStrikeDamageBonus || 0));
    if (!bonus) return totalDamage;
    battle.shipOpeningFirstStrikeDamageBonusUsed = true;
    const adjusted = Math.max(1, Math.round(Number(totalDamage || 0) * (1 + bonus)));
    if (adjusted > totalDamage) battle.log.push(`${player.name} 的桅杆改造搶到先手，首輪先制傷害 +${Math.round(bonus * 100)}%。`);
    return adjusted;
  }

  function startBattleRound(player, battle) {
    clearBattleRefreshRecoveryCheckpoint(battle);
    markBattleCrewParticipation(player, battle, battle?.activeCrewIndex);
    battle.roundIndex += 1;
    battle.result = "";
    battle.roundResolved = false;
    battle.waitingResume = false;
    battle.autoTurnPassScheduled = false;
    battle.playerAction = null;
    battle.enemyAction = null;
    battle.visualEvent = null;
    battle.playerEffectDice = null;
    battle.enemyEffectDice = null;
    if (isCoopBattle(battle)) {
      battle.coop ||= {};
      battle.coop.actions = {};
      battle.coop.roundStartedAt = Date.now();
    }
    battle.playerPerformedAction = false;
    battle.enemyPerformedAction = false;
    battle.playerDiceRoll = null;
    battle.enemyDiceRoll = null;
    battle.playerActionSummary = "";
    battle.enemyActionSummary = "";
    resetRoundEffects(battle.playerRoundEffects);
    resetRoundEffects(battle.enemyCombatant.roundEffects);
    if (battle.playerRoundEffects.nextGuaranteedFirst) {
      battle.playerRoundEffects.guaranteedFirst = true;
      battle.playerRoundEffects.nextGuaranteedFirst = false;
    }
    applyJudicialOpeningBoost(battle);
    if (postgameBossMechanicRoundStart(player, battle)) {
      battle.awaitingRoundStartContinuation = true;
      renderBattleInterface();
      return;
    }
    if (handleYonkoRoundStart(player, battle)) {
      battle.awaitingRoundStartContinuation = true;
      renderBattleInterface();
      return;
    }
    if (handleFinalGateRoundStart(player, battle)) {
      renderBattleInterface();
      return;
    }
    applyBattleStartStatusEffects(player, battle);
    if (battle.result || battle.needsReplacement) return;
    ensureSanjiRaidSuitTransformation(player, battle, battle.activeCrewIndex, { queueOpening: true });
    applyShipBattleOpeningEffects(player, battle);
    applyActiveCharacterPassiveOpening(player, battle);
    queueFinalGateBlackTurnCastIfNeeded(player, battle);
    queueKyubiMaskOpeningVisualIfNeeded(player, battle);
    scheduleOpeningPassiveVisualsIfReady(player, battle);
    if (isCoopBattle(battle)) {
      battle.log.push(`共鬥第 ${battle.roundIndex} 輪開始，輪到 ${player.name} 出手。`);
    } else {
      battle.log.push(`第 ${battle.roundIndex} 輪開始，請選擇 ${player.name} 的行動。`);
    }
  }

  function continueBattleRoundStartAfterPrompt(player, battle) {
    if (!battle || !player) return false;
    battle.awaitingRoundStartContinuation = false;
    applyBattleStartStatusEffects(player, battle);
    if (battle.result || battle.needsReplacement) return false;
    ensureSanjiRaidSuitTransformation(player, battle, battle.activeCrewIndex, { queueOpening: true });
    applyShipBattleOpeningEffects(player, battle);
    applyActiveCharacterPassiveOpening(player, battle);
    queueFinalGateBlackTurnCastIfNeeded(player, battle);
    queueKyubiMaskOpeningVisualIfNeeded(player, battle);
    scheduleOpeningPassiveVisualsIfReady(player, battle);
    return !(battle.result || battle.needsReplacement);
  }

  function applyBattleCarryRoundEndEffects(player, battle) {
    const contexts = activePlayerCarryContexts(player, battle);
    if (!contexts.length || Number(contexts[0].card.currentHp || 0) <= 0) return;
    contexts.forEach((ctx) => {
      const effect = battleCarryItemEffect(ctx.item);
      if (ctx.item.id === "sanji_bento") {
        const healed = healBattleTarget(ctx.card, 0.05);
        if (healed > 0) battle.log.push(`${ctx.card.name}吃下山治的便當，回復 ${healed} HP。`);
      }
      if (ctx.item.id === "leftovers_meat" || effect.kind === "heal_each_turn") {
        const healed = healBattleTarget(ctx.card, Number(effect.percent || 0.05));
        if (healed > 0) battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}回復 ${healed} HP。`);
      }
      if (effect.kind === "poison_affinity_heal_else_damage") {
        const hasAffinity = Boolean(ctx.card.poisonAffinity || ctx.card.tags?.includes?.("poisonAffinity") || ctx.card.tags?.includes?.("poison"));
        const amount = Math.max(1, Math.round(cardMaxHp(ctx.card) * Number(effect.hpPercent || 0.06)));
        if (hasAffinity) {
          const healed = healBattleTarget(ctx.card, Number(effect.hpPercent || 0.06));
          if (healed > 0) battle.log.push(`${ctx.card.name}吸收劇毒黑泥，回復 ${healed} HP。`);
        } else {
          ctx.card.currentHp = Math.max(1, Number(ctx.card.currentHp || 1) - amount);
          battle.log.push(`${ctx.card.name}受到劇毒黑泥侵蝕，損失 ${amount} HP。`);
          applyPlayerHpThresholdBattleCarryEffects(player, battle);
        }
      }
      if (effect.kind === "postgame_green_bull_life_seed") {
        const hpRate = Number(ctx.card.currentHp || 0) / Math.max(1, cardMaxHp(ctx.card));
        if (hpRate < Number(effect.hpThreshold || .7)) {
          if (!ctx.state?.greenBullReviveUsed) {
            ctx.state.greenBullSeeds = Math.min(Number(effect.maxSeeds || 3), Number(ctx.state.greenBullSeeds || 0) + 1);
          }
          const healed = healBattleTarget(ctx.card, Number(effect.healPerTurn || .03));
          if (healed > 0) {
            battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}回復 ${healed} HP${ctx.state?.greenBullReviveUsed ? "；本場復活已使用" : `，種子 ${Number(ctx.state?.greenBullSeeds || 0)}/${Number(effect.maxSeeds || 3)}`}。`);
          }
        }
      }
    });
  }

  function triggerRelayPirateFlagRoundEndSwitch(player, battle) {
    const action = battle?.playerAction;
    if (!player || !battle || battle.result || !battle.playerPerformedAction || !action) return false;
    const totMechanic = postgameBossMechanicFor(battle);
    if (action.type === "tot-dual" && totMechanic?.key === "postgame_tot_musica" && totMechanic.assigned) {
      const playerWorlds = postgameTotUsesPlayerWorlds(battle, totMechanic);
      let switched = false;
      for (const world of ["real", "song"]) {
        const worldAction = world === "real" ? action.realAction : action.songAction;
        if (!["move", "item"].includes(String(worldAction?.type || ""))) continue;
        const worldPlayer = playerWorlds ? postgameTotActiveWorldPlayer(battle, totMechanic, world) : player;
        if (!worldPlayer) continue;
        const switchWorldHolder = () => {
          const runtime = playerWorlds ? coopBattleRuntimeFor(worldPlayer, battle, true) : null;
          const activeIndex = Number(runtime?.activeCrewIndex ?? (world === "real" ? totMechanic.realActiveIndex : totMechanic.songActiveIndex));
          const ctx = playerCarryContextsForIndex(worldPlayer, battle, activeIndex).find((entry) => battleCarryItemEffect(entry.item).kind === "switch_out_after_action");
          const effect = battleCarryItemEffect(ctx?.item);
          if (!ctx || effect.kind !== "switch_out_after_action" || Number(ctx.card.currentHp || 0) <= 0) return false;
          const indices = playerWorlds
            ? (worldPlayer.crew || []).map((_card, index) => index)
            : world === "real" ? totMechanic.realIndices || [] : totMechanic.songIndices || [];
          const position = Math.max(0, indices.indexOf(activeIndex));
          const ordered = [...indices.slice(position + 1), ...indices.slice(0, position)];
          const nextIndex = ordered.find((index) => index !== activeIndex && Number(worldPlayer.crew?.[index]?.currentHp || 0) > 0);
          if (!Number.isInteger(nextIndex)) return false;
          const nextCard = setTotMusicaActiveWorldCrew(worldPlayer, battle, totMechanic, world, nextIndex);
          battle.log.push(`${world === "real" ? "現實世界" : "歌世界"}・${ctx.card.name}的${battleCarryItemName(ctx.item)}啟動，交棒給${cardDisplayName(nextCard)}。`);
          return true;
        };
        switched = (playerWorlds
          ? withCoopBattleRuntime(worldPlayer, battle, switchWorldHolder, { save: true })
          : switchWorldHolder()) || switched;
      }
      if (!playerWorlds) setTotMusicaActiveWorldCrew(player, battle, totMechanic, "real", totMechanic.realActiveIndex);
      if (switched) scheduleBattleLanStatePush("battle-tot-relay-flag-switch", 40);
      return switched;
    }
    if (!["move", "item", "zephyr-disarm"].includes(String(action.type || ""))) return false;
    const actorIndex = Number(action.actorCrewIndex);
    if (!Number.isInteger(actorIndex) || actorIndex < 0 || actorIndex !== Number(battle.activeCrewIndex)) return false;
    const ctx = playerCarryContextsForIndex(player, battle, actorIndex).find((entry) => battleCarryItemEffect(entry.item).kind === "switch_out_after_action");
    const effect = battleCarryItemEffect(ctx?.item);
    if (!ctx || effect.kind !== "switch_out_after_action" || Number(ctx.card.currentHp || 0) <= 0) return false;
    const candidates = livingCrewIndices(player).filter((index) => index !== actorIndex && battleCrewIndexIsEligible(player, battle, index));
    if (!candidates.length) return false;
    battle.needsReplacement = true;
    battle.result = "replacement";
    battle.roundResolved = false;
    battle.waitingResume = false;
    battle.replacementAfterAction = true;
    battle.replacementReason = "relay-pirate-flag";
    battle.pendingReplacementActiveCrewIndex = actorIndex;
    battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}在本回合行動完成後啟動；請選擇一名存活船員交棒上場。`);
    notifyBattleWindow();
    scheduleBattleLanStatePush("battle-relay-flag-replacement", 40);
    return true;
  }

  function ensureBattleRound(player, battle) {
    if (battle.needsReplacement) {
      renderBattleInterface();
      return;
    }
    if (battle.waitingResume || battle.roundResolved || !battle.roundIndex) {
      startBattleRound(player, battle);
    }
    renderBattleInterface();
  }

  function shouldEndTurnAfterBattleReplacement(player, battle) {
    if (!player || !battle || isCoopBattle(battle)) return false;
    return (state.gameState.players || []).length > 1;
  }

  function prepareBattleReplacementTurnPause(player, battle) {
    const activeCard = battleActiveCard(player, battle);
    battle.result = "round-pause";
    battle.roundResolved = true;
    battle.waitingResume = true;
    battle.replacementAfterAction = false;
    battle.playerAction = null;
    battle.enemyAction = null;
    battle.playerPerformedAction = false;
    battle.enemyPerformedAction = false;
    battle.playerDiceRoll = null;
    battle.enemyDiceRoll = null;
    battle.playerEffectDice = null;
    battle.enemyEffectDice = null;
    battle.playerActionSummary = "";
    battle.enemyActionSummary = "";
    battle.visualEvent = null;
    battle.log.push(`${activeCard?.name || "替補夥伴"} 已上場，本輪戰鬥結束，換下一位玩家。`);
  }

  function openBattleReplacementModal(player, battle) {
    const candidates = livingCrewIndices(player).filter((index) => index !== battle.activeCrewIndex);
    const relayFlagReplacement = String(battle.replacementReason || "") === "relay-pirate-flag";
    openModal(`
      <h3 class="modal-title">${relayFlagReplacement ? "交棒海賊旗啟動" : "角色瀕死"}</h3>
      <div class="modal-sub">${relayFlagReplacement ? "目前角色已完成行動，選擇下一名存活船員上場準備下一回合。" : "請先從剩餘夥伴中挑一位上場，再繼續這場戰鬥。"}</div>
      <div class="companion-grid">
        ${candidates.map((index) => {
          const card = player.crew[index];
          return `
            <article class="companion-card">
              <div class="companion-tier">${tierLabel(card.tier)} ・ ${card.attribute}</div>
              <div class="companion-name">${card.name}</div>
              <div class="companion-meta">生命值 ${card.currentHp}/${card.baseStats.hp} ・ 速度 ${card.baseStats.spd}<br>${moveSummary(card)}</div>
              <button type="button" class="modal-btn primary" data-battle-replace="${index}">派這位上場</button>
            </article>
          `;
        }).join("")}
      </div>
    `);
    refs.modal.querySelectorAll("[data-battle-replace]").forEach((button) => {
      button.addEventListener("click", () => {
        const nextIndex = Number(button.dataset.battleReplace);
        chooseBattleReplacement(nextIndex);
      });
    });
  }

  function chooseBattleReplacement(nextIndex) {
    const battle = state.battleState;
    if (!battle) return false;
    const player = isCoopBattle(battle) ? battleCommandPlayer(battle) : battlePlayer(null, battle);
    if (battle.postgameBossMechanic?.key === "postgame_gild_tesoro" && battle.postgameBossMechanic.forcedSwitch?.pending) {
      normalizePostgameBossMechanic(player, battle);
    }
    if (!battle.needsReplacement) return false;
    if (isCoopBattle(battle) ? warnBoardLanBattleLocked(player, battle) : warnBoardLanTurnLocked(player)) return false;
    const card = player?.crew?.[nextIndex];
    if (!card || !battleCrewIndexIsEligible(player, battle, nextIndex) || nextIndex === battle.activeCrewIndex || card.currentHp <= 0) return false;
    const shouldHandoffAfterCoopReplacement = isCoopBattle(battle);
    const shouldEndTurnAfterReplacement = shouldEndTurnAfterBattleReplacement(player, battle);
    const fromIndex = battle.activeCrewIndex;
    const fromName = player.crew?.[fromIndex]?.name || "夥伴";
    const replacementReason = String(battle.replacementReason || "");
    const tesoroGoldReplacement = replacementReason === "tesoro-gold";
    const relayFlagReplacement = replacementReason === "relay-pirate-flag";
    if (tesoroGoldReplacement) {
      const mechanic = postgameBossMechanicFor(battle);
      if (mechanic?.key === "postgame_gild_tesoro") {
        const goldFromIndex = Number(mechanic.forcedSwitch?.fromIndex ?? battle.pendingReplacementActiveCrewIndex ?? fromIndex);
        const goldFromCard = player.crew?.[goldFromIndex];
        const goldFromKey = postgameBossMechanicCrewKey(goldFromCard, goldFromIndex);
        mechanic.controlByCrew[goldFromKey] = 0;
        mechanic.goldByCrew[goldFromKey] = 0;
        mechanic.cancelQueuedPlayerAction = false;
        mechanic.forcedSwitch = null;
      }
    }
    syncActivePlayerStatusBag(player, battle);
    battle.activeCrewIndex = nextIndex;
    player.activeCrewIndex = nextIndex;
    syncActivePlayerStatusBag(player, battle);
    markBattleCrewParticipation(player, battle, nextIndex);
    battle.playerStages = emptyStages();
    battle.playerStageTurns = emptyStageTurns();
    battle.playerRoundEffects = emptyRoundEffects();
    applyCaptainCoatSwitchBonus(player, battle, fromIndex, nextIndex);
    battle.needsReplacement = false;
    battle.result = "";
    battle.roundResolved = false;
    battle.waitingResume = true;
    battle.replacementAfterAction = false;
    battle.visualEvent = createBattleSwitchVisualEvent(player, battle, {
      fromIndex,
      toIndex: nextIndex,
      fromName,
      toName: card.name,
      reason: tesoroGoldReplacement ? "tesoro-gold-replacement" : "replacement",
      duration: BATTLE_REPLACEMENT_ENTRY_DISPLAY_MS,
    });
    delete battle.pendingReplacementActiveCrewIndex;
    delete battle.replacementReason;
    addLog(tesoroGoldReplacement
      ? `${player.name} 解除金流並換上 ${card.name}。`
      : relayFlagReplacement
        ? `${player.name} 透過交棒海賊旗換上 ${card.name}。`
        : `${player.name} 派出 ${card.name} 作為替補。`);
    battle.log.push(tesoroGoldReplacement
      ? `${card.name} 接替上場，下回合開始行動。`
      : relayFlagReplacement
        ? `${fromName} 完成交棒，${card.name} 上場準備下一回合。`
        : `${card.name} 上場，戰鬥繼續。`);
    battle.animating = true;
    if (isCoopBattle(battle)) {
      const savedRuntime = saveCoopBattleRuntime(player, battle);
      if (savedRuntime) {
        savedRuntime.needsReplacement = false;
        savedRuntime.replacementAfterAction = false;
        savedRuntime.activeCrewIndex = nextIndex;
        delete savedRuntime.pendingReplacementActiveCrewIndex;
      }
      battle.playerId = player.id;
    }
    renderBattleInterface();
    notifyBattleWindow();
    scheduleBattleLanStatePush("battle-replacement-show", 40);
    const replacementEntryDisplayMs = Math.max(
      BATTLE_REPLACEMENT_ENTRY_DISPLAY_MS,
      Number(battle.visualEvent?.duration || 0),
    );
    window.setTimeout(() => {
      if (state.battleState !== battle) return;
      if (String(battle.playerId || "") !== String(player.id || "")) return;
      battle.animating = false;
      if (shouldHandoffAfterCoopReplacement) {
        battle.coop ||= {};
        battle.coop.actions = {};
        battle.playerAction = null;
        battle.enemyAction = null;
        battle.playerPerformedAction = false;
        battle.enemyPerformedAction = false;
        battle.playerDiceRoll = null;
        battle.enemyDiceRoll = null;
        battle.playerEffectDice = null;
        battle.enemyEffectDice = null;
        battle.playerActionSummary = "";
        battle.enemyActionSummary = "";
        const nextReplacementPlayer = coopBattleNextReplacementParticipantAfter(player, battle);
        if (nextReplacementPlayer) {
          battle.log.push(`替補完成，準備交棒給 ${nextReplacementPlayer.name} 選擇下一位上場。`);
          scheduleCoopBattleHandoffVisual(nextReplacementPlayer, battle, "battle-coop-replacement-handoff", "請先選擇下一位上場。", 40, () => {
            if (state.battleState !== battle) return false;
            if (!handoffCoopBattleToParticipant(nextReplacementPlayer, battle)) return false;
            battle.log.push(`替補完成，交棒給 ${nextReplacementPlayer.name} 選擇下一位上場。`);
            return true;
          });
          return true;
        }
        const nextPlayer = coopBattleNextReadyParticipantAfter(player, battle);
        if (nextPlayer) {
          battle.log.push(`替補完成，準備交棒給 ${nextPlayer.name}。`);
          scheduleCoopBattleHandoffVisual(nextPlayer, battle, "battle-coop-handoff", "準備選擇戰鬥行動。", 40, () => {
            if (state.battleState !== battle) return false;
            if (!handoffCoopBattleToParticipant(nextPlayer, battle)) return false;
            battle.log.push(`替補完成，交棒給 ${nextPlayer.name}。`);
            return true;
          });
          return true;
        }
        battle.result = "round-pause";
        battle.roundResolved = true;
        battle.waitingResume = true;
        battle.log.push("替補完成，本輪戰鬥暫停，返回地圖後換下一位玩家。");
        renderBattleInterface();
        notifyBattleWindow();
        scheduleBoardLanStatePush("battle-replacement", 60, { force: true });
        scheduleBattleRoundAutoPass(player, battle);
        return true;
      }
      if (shouldEndTurnAfterReplacement) {
        prepareBattleReplacementTurnPause(player, battle);
        renderBattleInterface();
        notifyBattleWindow();
        scheduleBattleLanStatePush("battle-replacement-turn-pause", 40);
        window.setTimeout(() => {
          if (state.battleState !== battle) return;
          if (!canEndBattleTurn(battle)) return;
          finishBattle();
        }, 220);
        return true;
      }
      ensureBattleRound(player, battle);
      renderBattleInterface();
      notifyBattleWindow();
      scheduleBattleLanStatePush("battle-replacement", 60);
    }, replacementEntryDisplayMs + 420);
    return true;
  }

  function canEndBattleTurn(battle) {
    return !!battle && !battle.needsReplacement && battle.result !== "judicial-switch" && (battle.roundResolved || (battle.result && battle.result !== ""));
  }

  let marinefordBattleAutoFinishKey = "";
  let marinefordBattleAutoFinishTimer = 0;
  let elbaphBattleAutoFinishKey = "";
  let elbaphBattleAutoFinishTimer = 0;

  function shouldAutoFinishMarinefordBattleStep(player, battle) {
    if (!player || !battle) return false;
    if (!(battle.isMarineford || battle.islandKind === "marineford")) return false;
    if (state.gameState?.battleExitLock) return false;
    if (battle.animating || battle.needsReplacement || battle.yonkoPrompt?.pending) return false;
    if (!battle.result || battle.result === "replacement" || battle.result === "judicial-switch") return false;
    if (!canBoardLanControlBattlePlayer(player, battle)) return false;
    return canEndBattleTurn(battle);
  }

  function marinefordBattleAutoFinishKeyFor(player, battle) {
    return [
      player?.id || "",
      battle?.marineford?.bossIndex ?? "",
      battle?.roundIndex ?? "",
      battle?.result || "",
      battle?.roundResolved ? 1 : 0,
      Math.max(0, Math.round(Number(battle?.enemyCombatant?.currentHp || 0))),
    ].join("|");
  }

  function scheduleMarinefordBattleAutoFinish(player, battle) {
    if (!shouldAutoFinishMarinefordBattleStep(player, battle)) return;
    const key = marinefordBattleAutoFinishKeyFor(player, battle);
    if (marinefordBattleAutoFinishTimer && marinefordBattleAutoFinishKey === key) return;
    if (marinefordBattleAutoFinishTimer) window.clearTimeout(marinefordBattleAutoFinishTimer);
    marinefordBattleAutoFinishKey = key;
    marinefordBattleAutoFinishTimer = window.setTimeout(() => {
      if (marinefordBattleAutoFinishKey !== key) return;
      marinefordBattleAutoFinishTimer = 0;
      if (state.battleState !== battle) return;
      if (!shouldAutoFinishMarinefordBattleStep(player, battle)) return;
      finishBattle();
    }, 1200);
  }

  function shouldAutoFinishElbaphGodKnightBattleStep(player, battle) {
    if (!player || !battle) return false;
    if (!isElbaphGodKnightBattle(battle) && !isFinalGateBlackTurnBattle(battle)) return false;
    if (state.gameState?.battleExitLock) return false;
    if (battle.animating || battle.needsReplacement || battle.yonkoPrompt?.pending) return false;
    if (!battle.result || battle.result === "replacement" || battle.result === "judicial-switch") return false;
    if (!canBoardLanControlBattlePlayer(player, battle)) return false;
    return canEndBattleTurn(battle);
  }

  function elbaphBattleAutoFinishKeyFor(player, battle) {
    return [
      player?.id || "",
      isFinalGateBlackTurnBattle(battle) ? "black_turn" : elbaphGodKnightBattleStep(battle),
      battle?.roundIndex ?? "",
      battle?.result || "",
      battle?.roundResolved ? 1 : 0,
      Math.max(0, Math.round(Number(battle?.enemyCombatant?.currentHp || 0))),
    ].join("|");
  }

  function scheduleElbaphGodKnightBattleAutoFinish(player, battle) {
    if (!shouldAutoFinishElbaphGodKnightBattleStep(player, battle)) return;
    const key = elbaphBattleAutoFinishKeyFor(player, battle);
    if (elbaphBattleAutoFinishTimer && elbaphBattleAutoFinishKey === key) return;
    if (elbaphBattleAutoFinishTimer) window.clearTimeout(elbaphBattleAutoFinishTimer);
    elbaphBattleAutoFinishKey = key;
    elbaphBattleAutoFinishTimer = window.setTimeout(() => {
      if (elbaphBattleAutoFinishKey !== key) return;
      elbaphBattleAutoFinishTimer = 0;
      if (state.battleState !== battle) return;
      if (!shouldAutoFinishElbaphGodKnightBattleStep(player, battle)) return;
      finishBattle();
    }, 1200);
  }

  function shouldAutoPassBattleRound(player, battle) {
    if (!player || !battle) return false;
    if ((state.gameState.players || []).length <= 1) return false;
    if (isCoopBattle(battle) && coopBattleNextLivingParticipantAfter(player, battle)) return false;
    if (battle.result !== "round-pause" || !battle.roundResolved || battle.needsReplacement) return false;
    if (battle.isJudicialRaid || battle.isMarineford || battle.isImpelDown) return false;
    return canEndBattleTurn(battle);
  }

  function scheduleBattleRoundAutoPass(player, battle) {
    if (!shouldAutoPassBattleRound(player, battle) || battle.autoTurnPassScheduled) return;
    battle.autoTurnPassScheduled = true;
    const players = state.gameState.players || [];
    const currentIndex = Math.max(0, players.findIndex((entry) => String(entry.id || "") === String(player.id || "")));
    const nextPlayer = players.length ? players[(currentIndex + 1) % players.length] : null;
    battle.log.push(`本輪戰鬥結束，${nextPlayer?.name || "下一位玩家"} 準備操作。`);
    notifyBattleWindow();
    window.setTimeout(() => {
      if (state.battleState !== battle || !shouldAutoPassBattleRound(player, battle)) return;
      finishBattle();
    }, 900);
  }

  function getBattleMoveDamageRange(side, moveEntry, player, battle) {
    if (!moveEntry || !battle || !player) return null;
    const moveType = moveEntry.category || moveEntry.type;
    if (!["attack", "special"].includes(moveType) || Number(moveEntry.power || 0) <= 0) return null;
    const maxDiceFace = maximumBattleActionDiceTotal(side, player, battle);
    if (isComboBattleMove(moveEntry)) {
      const minHits = battleCarryAdjustedMultiHit(side, moveEntry, 1, comboMoveMaxHits(moveEntry, 1), player, battle);
      const maxHits = battleCarryAdjustedMultiHit(side, moveEntry, maxDiceFace, comboMoveMaxHits(moveEntry, maxDiceFace), player, battle);
      return {
        min: battleDamageHitTotal(computeComboHitDamages(side, moveEntry, 1, minHits, 0, player, battle)),
        max: battleDamageHitTotal(computeComboHitDamages(side, moveEntry, maxDiceFace, maxHits, 0, player, battle)),
      };
    }
    return {
      min: computeMoveDamage(side, moveEntry, 1, player, battle),
      max: computeMoveDamage(side, moveEntry, maxDiceFace, player, battle),
    };
  }

  function battleMovePowerLabel(side, moveEntry, player, battle) {
    const power = Number(moveEntry?.power || 0);
    if (!battleMoveDealsDamage(moveEntry) || power <= 0) return "效果技";
    return `威力 ${power}`;
  }

  function stageMapText(stageMap = {}) {
    const merged = {};
    Object.entries(stageMap || {}).forEach(([stat, value]) => {
      const normalized = normalizeBattleStageKey(stat);
      merged[normalized] = Number(merged[normalized] || 0) + Number(value || 0);
    });
    return Object.entries(merged)
      .filter(([, value]) => Number(value || 0) !== 0)
      .map(([stat, value]) => signedStageLabel(stat, value))
      .join("、");
  }

  function percentText(value) {
    return `${Math.round(Number(value || 0) * 100)}%`;
  }

  function compactBaseEffectText(text = "") {
    return String(text || "")
      .replace(/戰術/g, "特攻")
      .replace(/意志/g, "特防")
      .replace(/[。；;]+$/g, "")
      .replace(/本回合受到傷害/g, "本回合傷害")
      .trim();
  }

  function pushUniqueText(list, text) {
    const value = compactBaseEffectText(text);
    if (value && !list.includes(value)) list.push(value);
  }

  function triggeredText(trigger, text) {
    const value = compactBaseEffectText(text);
    return trigger ? `${trigger}：${value}` : value;
  }

  function targetStageText(target, stageMap) {
    const text = stageMapText(stageMap);
    return text ? `${target}${text}` : "";
  }

  function statusNamesText(entry) {
    const names = [];
    const push = (status) => {
      const label = battleStatusLabel(status);
      if (label && !names.includes(label)) names.push(label);
    };
    if (!entry) return "";
    if (typeof entry === "string") push(entry);
    else if (Array.isArray(entry)) entry.forEach((item) => {
      if (typeof item === "object" && item) Object.keys(item || {}).forEach(push);
      else push(item);
    });
    else if (typeof entry === "object") Object.keys(entry).forEach(push);
    return names.join("、");
  }

  function statusEntryText(entry, defaultDuration) {
    const parts = [];
    const push = (status, turns = defaultDuration) => {
      const label = battleStatusLabel(status);
      if (label) parts.push(`${label}${Math.max(1, Number(turns || defaultDuration))}回合`);
    };
    if (!entry) return "";
    if (typeof entry === "string") push(entry, defaultDuration);
    else if (Array.isArray(entry)) entry.forEach((item) => parts.push(statusEntryText(item, defaultDuration)));
    else if (typeof entry === "object") Object.entries(entry).forEach(([status, turns]) => push(status, turns));
    return parts.filter(Boolean).join("、");
  }

  function moveEffectDetailItems(moveEntry) {
    const effects = moveEntry?.effects || {};
    const items = [];
    const statusDuration = normalizeStatusDuration(effects, 2);
    const pushItem = (item) => {
      if (!item?.label) return;
      const id = item.id || `${item.icon || "effect"}-${item.label}`;
      if (items.some((entry) => entry.id === id && entry.label === item.label)) return;
      items.push({
        id,
        icon: item.icon || "",
        iconUrl: item.icon ? effectIconUrl(item.icon) : "",
        label: item.label,
        turns: Number(item.turns || 0),
        badge: item.badge || "",
        durationText: item.durationText || "",
        type: item.type || "buff",
        description: item.description || item.label,
      });
    };
    const pushStages = (prefix, stageMap, typeOverride = "") => {
      Object.entries(stageMap || {}).forEach(([stat, value]) => {
        const amount = Number(value || 0);
        if (!amount) return;
        const normalized = normalizeBattleStageKey(stat);
        const label = `${prefix}${signedStageLabel(normalized, amount)}`;
        pushItem({
          id: `move-stage-${prefix}-${normalized}-${amount}`,
          icon: stageIconKey(normalized, amount),
          label,
          turns: 0,
          badge: stageBadge(amount),
          durationText: "常駐至換下或瀕死",
          type: typeOverride || (amount > 0 ? "buff" : "debuff"),
          description: `${label}，能力階級常駐至換下場或瀕死，最高 +${BATTLE_STAGE_LIMIT}、最低 -${BATTLE_STAGE_LIMIT}。`,
        });
      });
    };
    const pushStatuses = (prefix, entry, trigger = "") => {
      const add = (status, turns = statusDuration) => {
        const key = normalizeBattleStatus(status);
        const info = BATTLE_STATUS_INFO[key];
        if (!info) return;
        const duration = Math.max(1, Number(turns || statusDuration));
        const label = `${prefix}${info.label}`;
        pushItem({
          id: `move-status-${prefix}-${key}-${duration}`,
          icon: info.icon || key,
          label,
          turns: duration,
          type: info.type || "debuff",
          description: `${trigger}${label}，持續 ${duration} 回合。${info.description || ""}`,
        });
      };
      if (!entry) return;
      if (typeof entry === "string") add(entry, statusDuration);
      else if (Array.isArray(entry)) entry.forEach((item) => {
        if (typeof item === "object" && item) Object.entries(item).forEach(([status, turns]) => add(status, turns));
        else add(item, statusDuration);
      });
      else if (typeof entry === "object") Object.entries(entry).forEach(([status, turns]) => add(status, turns));
    };

    pushStages("自身", effects.selfStages, "buff");
    pushStages("敵方", effects.enemyStages, "debuff");
    pushStages("命中後敵方", effects.enemyStagesOnHit, "debuff");
    pushStages("骰到5以上敵方", effects.enemyStagesOnHighDice, "debuff");
    pushStages("骰到6時敵方", effects.enemyStagesOnSix, "debuff");
    pushStages("骰到4以上偶數敵方", effects.enemyStagesOnEvenHighDice, "debuff");
    pushStages("骰到5以上自身", effects.selfStagesOnHighDice);
    pushStages("使用後自身", effects.selfStagesAfterUse);
    pushStages("Boss命中敵方", effects.bossStageOnHit, "debuff");
    pushStatuses("附加", effects.status);
    pushStatuses("命中後", effects.statusOnHit, "命中後");
    pushStatuses("骰到5以上", effects.statusOnHighDice, "骰到5以上");
    pushStatuses("骰到6時", effects.statusOnSix, "骰到6時");
    pushStatuses("骰到4以上偶數", effects.statusOnEvenHighDice, "骰到4以上偶數");

    if (effects.shieldRatio) {
      pushItem({
        id: "move-shield",
        icon: "shield",
        label: `護盾-${Math.round(Number(effects.shieldRatio) * 100)}%`,
        turns: 1,
        type: "buff",
        description: `本回合受到傷害降低 ${Math.round(Number(effects.shieldRatio) * 100)}%。`,
      });
    }
    if (effects.shieldRatioBeforeAttack) {
      pushItem({
        id: "move-pre-shield",
        icon: "shield",
        label: `攻擊前減傷${Math.round(Number(effects.shieldRatioBeforeAttack) * 100)}%`,
        turns: 1,
        type: "buff",
        description: `攻擊前獲得本回合減傷 ${Math.round(Number(effects.shieldRatioBeforeAttack) * 100)}%。`,
      });
    }
    if (effects.reflectRatio || effects.reflectStatus) {
      pushItem({
        id: "move-reflect",
        icon: "reflect",
        label: effects.reflectStatus ? `反制${battleStatusLabel(effects.reflectStatus)}` : `反彈${Math.round(Number(effects.reflectRatio) * 100)}%`,
        turns: 1,
        type: "buff",
        description: effects.reflectStatus
          ? `本回合被攻擊時，反制${battleStatusLabel(effects.reflectStatus)}。`
          : `本回合反彈受到傷害的 ${Math.round(Number(effects.reflectRatio) * 100)}%。`,
      });
    }
    if (effects.teamShieldRatio) {
      pushItem({
        id: "move-team-shield",
        icon: "shield",
        label: `全隊減傷${percentText(effects.teamShieldRatio)}`,
        turns: 1,
        type: "buff",
        description: `本回合全隊受到傷害降低 ${percentText(effects.teamShieldRatio)}。`,
      });
    }
    if (effects.negateNextHit) {
      pushItem({ id: "move-negate-hit", icon: "shield", label: "抵擋傷害", turns: 1, type: "buff", description: "本回合完全抵擋下一次直接傷害。" });
    }
    if (moveEntry?.type === "heal" || moveEntry?.category === "heal" || effects.healRatio || effects.healLowestAllyRatio || effects.healTeamRatio || effects.reviveLowestAllyRatio || effects.regenSelfRatio) {
      const healLabel = effects.healTeamRatio
        ? `全隊回復${percentText(effects.healTeamRatio)}`
        : effects.healLowestAllyRatio
          ? `低血回復${percentText(effects.healLowestAllyRatio)}`
          : effects.reviveLowestAllyRatio
            ? `復活${percentText(effects.reviveLowestAllyRatio)}`
            : effects.regenSelfRatio
              ? `持續回復${percentText(effects.regenSelfRatio)}`
              : `治療${effects.healRatio ? percentText(effects.healRatio) : ""}`;
      pushItem({ id: "move-heal", icon: "heal", label: healLabel, type: "buff", description: "回復生命值或提供持續回復。" });
    }
    if (moveEntry?.priority || effects.priority || effects.priorityOnHighDice || effects.guaranteedFirst || effects.guaranteedFirstNextTurn) {
      pushItem({
        id: "move-first",
        icon: "first",
        label: effects.priorityOnHighDice ? "5+先制" : "先制",
        type: "buff",
        description: "提高本招行動順序；若為骰到5以上先制，會依骰子結果觸發。",
      });
    }
    if (effects.blockEnemyPriority) {
      pushItem({
        id: "move-block-priority",
        icon: "spd_down",
        label: "敵方速度-1",
        turns: 0,
        badge: "-1",
        durationText: "常駐至換下或瀕死",
        type: "debuff",
        description: "敵方速度下降 1 階，常駐至換下場或瀕死。",
      });
    }
    if (effects.blockEnemyBuff) {
      pushItem({ id: "move-block-buff", icon: "bind", label: "封鎖強化", turns: 1, type: "debuff", description: "本回合敵方不能使用強化技。" });
    }
    if (effects.enemyDamageTakenUp) {
      pushItem({ id: "move-damage-taken-up", icon: "damage_up", label: `易傷+${percentText(effects.enemyDamageTakenUp)}`, turns: 1, type: "debuff", description: `本回合敵方受到傷害增加 ${percentText(effects.enemyDamageTakenUp)}。` });
    }
    if (effects.ignoreDefenseRatio || effects.antiShieldBonus || effects.pierceShield || effects.pierceShieldOnHighDice || effects.nextHitBoost || effects.bonusOnHighDice || effects.bonusOnHighDiceFlat || effects.amplifyOnHighDice || effects.bonusWhenFaster || effects.strongerIfFaster || effects.strongerVsDebuffed || effects.highHpDamageBonus || effects.bossDamageBonus || effects.conditionalDamageBonus) {
      pushItem({
        id: "move-atk-up",
        icon: "atk_up",
        label: "傷害加成",
        type: "buff",
        description: "此招具有無視防禦、破盾、條件傷害、或骰到5以上傷害加成。",
      });
    }
    return items.slice(0, 6);
  }

  function formatMoveEffectText(moveEntry) {
    const base = compactBaseEffectText(moveEntry?.effectText || "");
    const effects = moveEntry?.effects || {};
    const notes = [];
    const addUnique = (text) => pushUniqueText(notes, text);
    const addStage = (trigger, target, stageMap) => {
      const text = targetStageText(target, stageMap);
      if (text) addUnique(triggeredText(trigger, text));
    };
    const addStatus = (trigger, entry) => {
      const text = statusNamesText(entry);
      if (text) addUnique(triggeredText(trigger, text));
    };
    if (effects.guaranteedCritical) addUnique("必定暴擊");
    else if (Number(effects.critRateBonus || 0) > 0) addUnique(`${percentText(effects.critRateBonus)}暴擊`);
    if (effects.criticalDamageMultiplier && Number(effects.criticalDamageMultiplier) !== BATTLE_CRITICAL_DAMAGE_MULTIPLIER) {
      addUnique(`暴擊傷害x${Number(effects.criticalDamageMultiplier)}`);
    }
    addStage("", "自身", effects.selfStages);
    addStage("", "敵方", effects.enemyStages);
    addStage("命中", "敵方", effects.enemyStagesOnHit);
    addStage("5+", "敵方", effects.enemyStagesOnHighDice);
    addStage("6", "敵方", effects.enemyStagesOnSix);
    addStage("4+偶數", "敵方", effects.enemyStagesOnEvenHighDice);
    addStage("5+", "自身", effects.selfStagesOnHighDice);
    addStage("使用後", "自身", effects.selfStagesAfterUse);
    addStage("Boss命中", "敵方", effects.bossStageOnHit);
    addStatus("附加", effects.status);
    addStatus("命中", effects.statusOnHit);
    addStatus("5+", effects.statusOnHighDice);
    addStatus("6", effects.statusOnSix);
    addStatus("4+偶數", effects.statusOnEvenHighDice);
    if (effects.shieldRatio) addUnique(`本回合減傷${percentText(effects.shieldRatio)}`);
    if (effects.teamShieldRatio) addUnique(`全隊減傷${percentText(effects.teamShieldRatio)}`);
    if (effects.negateNextHit) addUnique("抵擋下次傷害");
    if (effects.shieldRatioBeforeAttack) addUnique(`攻擊前減傷${percentText(effects.shieldRatioBeforeAttack)}`);
    if (effects.reflectRatio) addUnique(`反彈${percentText(effects.reflectRatio)}`);
    if (effects.reflectStatus) addUnique(`被攻擊時反制${battleStatusLabel(effects.reflectStatus)}（本回合）`);
    if (effects.enemyDamageTakenUp) addUnique(`敵方易傷+${percentText(effects.enemyDamageTakenUp)}`);
    if (effects.enemyDiceMod) addUnique(`敵方骰面-${Math.abs(Number(effects.enemyDiceMod || 0))}`);
    if (effects.nextHitBoost) addUnique(`下一擊+${percentText(effects.nextHitBoost)}`);
    const ignoreDefenseRatio = Math.max(Number(effects.ignoreDefenseRatio || 0), Number(effects.antiShieldBonus || 0));
    if (ignoreDefenseRatio) addUnique(`無視防禦${percentText(ignoreDefenseRatio)}`);
    if (effects.pierceShield) addUnique("無視護盾");
    if (effects.pierceShieldOnHighDice) addUnique("5+：無視護盾");
    if (effects.multiHit) addUnique(`依骰連擊`);
    if (effects.multiHitOnHighDice) addUnique(`5+：依骰連擊`);
    if (effects.bonusOnHighDice || effects.bonusOnHighDiceFlat) addUnique(`5+：傷害+${Number(effects.bonusOnHighDice || 0) + Number(effects.bonusOnHighDiceFlat || 0)}`);
    if (effects.bonusOnEvenHighDice) addUnique(`4+偶數：傷害+${Number(effects.bonusOnEvenHighDice)}`);
    if (effects.bonusWhenFaster) addUnique(`速度較高：傷害+${Number(effects.bonusWhenFaster)}`);
    if (effects.strongerIfFaster) addUnique(`速度較高：傷害+${percentText(effects.strongerIfFaster)}`);
    if (effects.amplifyOnHighDice) addUnique(`5+：傷害+${percentText(effects.amplifyOnHighDice)}`);
    if (effects.amplifyWhenLowHp) addUnique(`半血以下：傷害+${percentText(effects.amplifyWhenLowHp)}`);
    if (effects.amplifyVsControlled) addUnique(`對受控敵+${percentText(effects.amplifyVsControlled)}`);
    if (effects.amplifyVsLoweredSpeed) addUnique(`對降速敵+${percentText(effects.amplifyVsLoweredSpeed)}`);
    if (effects.highHpDamageBonus) addUnique(`高血量敵+${percentText(effects.highHpDamageBonus)}`);
    if (effects.conditionalDamageBonus) addUnique(`傷害+${percentText(effects.conditionalDamageBonus)}`);
    if (effects.strongerVsDebuffed) addUnique(`敵方弱化：傷害+${percentText(effects.strongerVsDebuffed)}`);
    if (effects.strongerIfShielded) addUnique(`有護盾：傷害+${percentText(effects.strongerIfShielded)}`);
    if (effects.strongerIfShieldedTarget) addUnique(`敵方護盾：傷害+${percentText(effects.strongerIfShieldedTarget)}`);
    Object.entries(effects.strongerVsStatus || {}).forEach(([status, ratio]) => addUnique(`對${battleStatusLabel(status)}+${percentText(ratio)}`));
    if (effects.amplifyVsStatus) addUnique(`對${battleStatusLabel(effects.amplifyVsStatus)}+${percentText(Math.max(0, Number(effects.multiplier || 1.2) - 1))}`);
    if (effects.bossDamageBonus) addUnique(`Boss/S敵+${percentText(effects.bossDamageBonus)}`);
    if (effects.bonusVsAttribute) addUnique(`對${effects.bonusVsAttribute}+${percentText(effects.amplifyVsAttribute || 0.1)}`);
    if (effects.flatBonusVsAttribute) addUnique(`對${effects.flatBonusVsAttribute}+${percentText(effects.amplifyVsAttribute || 0.1)}`);
    if (effects.dispelEnemyBuffs) addUnique("命中時解除敵方強化");
    if (effects.priorityOnHighDice) addUnique("5+：下回合先制");
    if (effects.guaranteedFirst) addUnique("本回合先制");
    if (effects.guaranteedFirstNextTurn) addUnique("下回合先制");
    if (effects.sanjiRaidSuitStealth) addUnique("重新啟動光學迷彩");
    if (effects.guaranteedEscape) addUnique("必定撤退");
    if (effects.healRatio) addUnique(`回復${percentText(effects.healRatio)}`);
    if (effects.healLowestAllyRatio) addUnique(`低血隊友回復${percentText(effects.healLowestAllyRatio)}`);
    if (effects.healTeamRatio) addUnique(`全隊回復${percentText(effects.healTeamRatio)}`);
    if (effects.reviveLowestAllyRatio) addUnique(`復活隊友${percentText(effects.reviveLowestAllyRatio)}`);
    if (effects.drainRatio) addUnique(`吸血${percentText(effects.drainRatio)}`);
    if (effects.drainOnSixRatio) addUnique(`6：吸血${percentText(effects.drainOnSixRatio)}`);
    if (effects.healSelfOnSixRatio) addUnique(`6：回復${percentText(effects.healSelfOnSixRatio)}`);
    if (effects.healTeamRatioAfterHit) addUnique(`命中：全隊回復${percentText(effects.healTeamRatioAfterHit)}`);
    if (effects.regenSelfRatio) addUnique(`持續回復${percentText(effects.regenSelfRatio)}`);
    if (effects.cleanseSelf) addUnique("清除自身異常");
    if (effects.cleanseTeam) addUnique("清除異常");
    if (effects.recoilRatio) addUnique(`反作用${percentText(effects.recoilRatio)}`);
    if (effects.selfHpCostRatio) addUnique(`消耗HP${percentText(effects.selfHpCostRatio)}`);
    if (effects.blockEnemyBuff) addUnique("封鎖敵方強化");
    if (effects.blockEnemyPriority) addUnique("敵方速度-1");
    if (effects.fieldSpeedUp) addUnique("速度場地+6");
    if (effects.fieldWeather) addUnique(`天候：${effects.fieldWeather}`);
    if (effects.fieldControl) addUnique(`場地：${effects.fieldControl}`);
    return notes.length ? notes.join(" / ") : (base || "無追加效果");
  }

  function serializeBattleMove(moveEntry, side = "player", player = null, battle = state.battleState) {
    const damageRange = getBattleMoveDamageRange(side, moveEntry, player, battle);
    const yonkoWarning = yonkoMoveWarningText(moveEntry, side, player || battlePlayer(null, battle), battle);
    const effectText = [formatMoveEffectText(moveEntry), yonkoWarning].filter(Boolean).join(" / ");
    return {
      id: moveEntry.id,
      name: moveEntry.name,
      displayName: boardMoveDisplayName(moveEntry),
      damageClass: boardMoveDamageClass(moveEntry),
      type: moveEntry.type || moveEntry.category,
      category: moveEntry.category || moveEntry.type,
      attribute: moveEntry.attribute || "",
      pp: moveEntry.pp,
      currentPP: moveEntry.currentPP ?? moveEntry.pp,
      power: moveEntry.power || 0,
      accuracy: moveEntry.accuracy ?? 100,
      priority: moveEntry.priority ?? 0,
      target: moveEntry.target || "enemy",
      damageRange,
      damageText: battleMovePowerLabel(side, moveEntry, player, battle),
      effectText,
      effectDetails: moveEffectDetailItems(moveEntry),
      critRateBonus: battleMoveCriticalRateBonus(moveEntry),
      guaranteedCritical: battleMoveGuaranteedCritical(moveEntry),
      cannotCritical: battleMoveCannotCritical(moveEntry),
      criticalDamageMultiplier: battleCriticalDamageMultiplier(moveEntry),
      unlockLevel: effectiveMoveUnlockLevel(moveEntry),
    };
  }

  function serializeBattleCrewCard(card, index, battle) {
    const maxHp = card?.baseStats?.hp || card?.hp || 1;
    const owner = battlePlayer(null, battle);
    const statusBag = battleCrewStatusBagForIndex(owner, battle, index);
    const cosmeticFrameId = activeCrewCosmeticFrameId(owner, card);
    const cosmeticFrame = cosmeticFrameDef(cosmeticFrameId);
    const raidSuitTransformed = sanjiRaidSuitDisplayedTransformed(card, owner, battle, index);
    return {
      index,
      id: card.id,
      name: sanjiRaidSuitBattleViewName(card, owner, battle, index),
      baseName: card.name,
      formId: card.formId || "base",
      formName: raidSuitTransformed ? "隱形黑・Stealth Black" : activeEvolutionForm(card)?.name || "",
      tier: card.tier,
      roleType: card.roleType,
      attribute: card.attribute,
      battlePortraits: sanjiRaidSuitBattleViewPortraits(card, owner, battle, index),
      passive: raidSuitTransformed ? SANJI_RAID_SUIT_PASSIVE.name : card.passive || "",
      passiveText: characterPassiveEffectText(card),
      raidSuitTransformed,
      level: card.level || 1,
      criticalStyle: characterCriticalStyle(card),
      criticalRateBase: characterCriticalBaseRate(card),
      criticalRate: index === Number(battle?.activeCrewIndex)
        ? battleActorCriticalRate("player", owner, battle)
        : characterCriticalRate(card, { includeEquipment: true }),
      criticalDamageMultiplier: index === Number(battle?.activeCrewIndex)
        ? battleActorCriticalDamageMultiplier("player", owner, battle)
        : characterCriticalDamageMultiplier(card),
      exp: card.exp || card.currentExp || 0,
      totalExp: card.totalExp || 0,
      nextLevelExp: card.nextLevelExp || expToNextLevel(card.level || 1, card),
      expText: expProgressText(card),
      currentHp: card.currentHp ?? maxHp,
      maxHp,
      statuses: statusBag,
      statusLabels: activeStatusLabels(statusBag),
      totalPP: (card.moveSet || []).reduce((sum, moveEntry) => sum + (moveEntry.currentPP ?? moveEntry.pp ?? 0), 0),
      isActive: index === battle.activeCrewIndex,
      cosmeticFrameId,
      cosmeticFrameLabel: cosmeticFrame?.label || "",
      carryItem: serializeBattleCarryItem(card, index, battle),
      battleStats: index === Number(battle?.activeCrewIndex)
        ? Object.fromEntries(["atk", "def", "satk", "sdef", "spd"].map((stat) => [stat, currentBattleStat("player", stat, owner, battle)]))
        : null,
      moves: getUnlockedMoves(card).map((moveEntry) => (
        index === battle.activeCrewIndex
          ? serializeBattleMove(moveEntry, "player", battlePlayer(null, battle), battle)
          : serializeBattleMove(moveEntry)
      )),
    };
  }

  function battleViewPlayerAttribute(player, battle, activeCard) {
    const naturalAttribute = activeCard?.attribute || "無";
    if (kyubiMaskVisualShouldHoldNaturalAttribute(battle)) return naturalAttribute;
    return devonKyubiMaskCounterAttribute(player, battle) || naturalAttribute;
  }

  function getBattleItemOptions(player) {
    ensurePlayerInventoryState(player);
    return Object.values(GAME_ITEMS)
      .filter((item) => normalizeGameItemCategory(item.category) === "battle")
      .filter((item) => item.usableInBattle !== false && (item.useTiming || []).includes("battle_turn"))
      .map((item) => {
        const legacyCount = item.id === "heal_2"
          ? Number(player?.smallSupplies || 0)
          : item.id === "battle_food"
            ? Number(player?.battleFood || 0)
            : item.id === "guard_charm"
              ? Number(player?.guardCharm || 0)
              : 0;
        return {
          id: item.id,
          name: item.name,
          count: Math.max(inventoryItemCount(player, item.id), legacyCount),
          desc: item.uiSummary || item.description || "戰鬥中主動使用，使用後消耗。",
          rarity: item.rarity,
          targetType: item.targetType || "self",
          targetMode: battleItemTargetMode(item),
          effectKind: item.effect?.kind || "",
          statuses: Array.isArray(item.effect?.statuses) ? item.effect.statuses.slice() : [],
        };
      })
      .filter((item) => item.count > 0)
      .sort((a, b) => a.name.localeCompare(b.name, "zh-Hant"));
  }

  let coopBattleViewRuntimeDepth = 0;

  function getBattleView(options = {}) {
    const battle = state.battleState;
    if (!battle) return null;
    if (battle.isSparBattle) return getSparBattleView(battle);
    if (battle.result === "win" && isCoopBattle(battle)) ensureCoopBattleRewardPreview(battle);
    if (isCoopBattle(battle) && !coopBattleViewRuntimeDepth) {
      const resultPlayer = battle.result === "win" ? coopBattleResultViewPlayer(battle) : null;
      const commandPlayer = resultPlayer || battleCommandPlayer(battle);
      const commandPlayerId = String(commandPlayer?.id || battle?.playerId || "");
      const requestedViewPlayerId = String(options?.coopViewPlayerId || "");
      const requestedViewPlayer = !resultPlayer && requestedViewPlayerId
        ? coopBattleParticipants(battle).find((entry) => String(entry?.id || "") === requestedViewPlayerId)
        : null;
      const viewerPlayer = resultPlayer || requestedViewPlayer || commandPlayer;
      if (viewerPlayer) {
        const previousViewerActiveCrewIndex = viewerPlayer.activeCrewIndex;
        coopBattleViewRuntimeDepth += 1;
        try {
          return withCoopBattleRuntime(viewerPlayer, battle, () => getBattleView({
            ...options,
            __coopCommandPlayerId: commandPlayerId,
          }), { save: false });
        } finally {
          coopBattleViewRuntimeDepth -= 1;
          if (requestedViewPlayer) viewerPlayer.activeCrewIndex = previousViewerActiveCrewIndex;
        }
      }
    }
    const player = battlePlayer(null, battle);
    if (!player) return null;
    normalizePostgameBossMechanic(player, battle);
    const activeCard = battleActiveCard(player, battle);
    if (!activeCard) return null;
    syncYonkoPhaseBattlePortraits(player, battle);
    const activeMaxHp = activeCard.baseStats?.hp || activeCard.hp || 1;
    const enemy = battle.enemyCombatant;
    const playerStatuses = battleStatusBag("player", battle);
    const raid = battle.isJudicialRaid ? ensureJudicialRaidState() : null;
    const coopCommandPlayerId = isCoopBattle(battle)
      ? String(options?.__coopCommandPlayerId || battleCommandPlayer(battle)?.id || battle?.playerId || "")
      : "";
    const canControlBattle = isCoopBattle(battle)
      ? String(player.id || "") === coopCommandPlayerId
        && (battle.result !== "win" || String(currentPlayer()?.id || "") === String(player.id || ""))
        && canBoardLanControlPlayerIdentity(player)
      : canBoardLanControlBattlePlayer(player, battle);
    const hasQueuedPlayerAction = !!battle.playerAction;
    const coopReady = isCoopBattle(battle) ? coopBattleReadyInfo(battle, coopCommandPlayerId) : null;
    const handoffPending = coopBattleHandoffPending(battle);
    const coopCommandPlayerName = coopReady?.participants?.find((entry) => String(entry.id || "") === coopCommandPlayerId)?.name || "目前玩家";
    const coopCommandPlayer = isCoopBattle(battle)
      ? coopBattleParticipants(battle).find((entry) => String(entry.id) === coopCommandPlayerId)
      : null;
    const coopRescueWait = coopCommandPlayer && coopBattleParticipantAwaitingRescue(coopCommandPlayer, battle)
      ? {
        active: true,
        playerId: coopCommandPlayer.id,
        playerName: coopCommandPlayer.name,
        turnsRemaining: Math.max(1, Number(coopBattleRuntimeFor(coopCommandPlayer, battle, false)?.rescueTurnsRemaining || 0)),
      }
      : null;
    const viewingCoopPartner = !!(isCoopBattle(battle) && String(player.id || "") !== coopCommandPlayerId);
    const viewerLockedReason = !canControlBattle
      ? viewingCoopPartner
        ? `觀看中：${player.name} 的戰鬥狀態；目前由 ${coopCommandPlayerName} 操作。`
        : `現在是 ${player.name} 的戰鬥，請觀看對方操作。`
      : "";
    const enemyViewAttribute = yonkoEffectiveEnemyAttribute(battle);
    const playerViewAttribute = battleViewPlayerAttribute(player, battle, activeCard);
    const baseAttributeMatchup = battleAttributeMatchup(playerViewAttribute, enemyViewAttribute);
    const attributeMatchupView = isYonkoBattleKey(battle)
      ? {
        ...baseAttributeMatchup,
        playerAttackMultiplier: kyubiMaskVisualShouldHoldNaturalAttribute(battle)
          ? baseAttributeMatchup.playerAttackMultiplier
          : sideMovePreviewMultiplierForActiveCard(activeCard, player, battle),
        enemyAttribute: enemyViewAttribute,
      }
      : baseAttributeMatchup;
    const raidInfo = raid ? {
      active: true,
      title: "司法島共鬥",
      phaseIndex: raid.phaseIndex,
      phaseTotal: JUDICIAL_RAID_PHASES.length,
      participantCount: activeJudicialRaidParticipants(raid).length,
      enemySharedHp: Math.max(0, Math.round(raid.enemyCurrentHp || enemy.currentHp || 0)),
      enemySharedMaxHp: Math.round(raid.enemyMaxHp || enemy.maxHp || 1),
      participants: judicialRaidBattleRosterInfo(raid, battle),
    } : null;
    const coopOwnRewards = isCoopBattle(battle) && battle.result === "win"
      ? coopBattleRewardPayloadForView(player, battle)
      : null;
    const playerCosmeticFrameId = activeCrewCosmeticFrameId(player, activeCard);
    const playerCosmeticFrameDef = cosmeticFrameDef(playerCosmeticFrameId);
    const lineageExtractionView = battle.result === "win" && (!isCoopBattle(battle) || canControlBattle)
      ? lineageExtractionViewForPlayer(player, battle)
      : null;
    return {
      player: {
        id: player.id,
        name: player.name,
        coins: player.coins,
        crew: battleCrewEntries(player, battle).map(({ card, index }) => serializeBattleCrewCard(card, index, battle)),
        activeCrewIndex: battle.activeCrewIndex,
        battleItems: getBattleItemOptions(player),
        inventory: player.items || [],
        ownedCosmeticFrameIds: ensurePlayerCosmeticFrameState(player).slice(),
        activeCosmeticFrameId: playerCosmeticFrameId,
      },
      activeCard: {
        ...serializeBattleCrewCard(activeCard, battle.activeCrewIndex, battle),
        cosmeticFrameId: playerCosmeticFrameId,
        cosmeticFrameLabel: playerCosmeticFrameDef?.label || "",
        naturalAttribute: activeCard.attribute || "無",
        attribute: playerViewAttribute,
        currentHp: activeCard.currentHp ?? activeMaxHp,
        maxHp: activeMaxHp,
        statuses: playerStatuses || emptyStatusEffects(),
        statusLabels: activeStatusLabels(playerStatuses),
        effectDice: Number(battle.playerEffectDice || battle.playerDiceRoll || 0),
        effectDetails: battleSideEffectDetails("player", battle),
      },
      enemy: {
        name: enemy.name,
        key: enemy.key || "",
        cosmeticFrameId: enemyCosmeticFrameIdFor(enemy),
        tier: enemy.tier,
        level: enemy.level || enemyLevelForProgress(enemy.tier),
        criticalRate: battleActorCriticalRate("enemy", player, battle),
        role: enemy.role || "",
        attribute: enemyViewAttribute,
        isDevilFruitUser: !!enemy.isDevilFruitUser,
        battlePortraits: enemy.battlePortraits || null,
        currentHp: enemy.currentHp,
        maxHp: enemy.maxHp,
        phaseHpBars: battlePhaseHpBarsForView(player, battle),
        atk: enemy.atk,
        def: enemy.def,
        satk: enemy.satk,
        sdef: enemy.sdef,
        spd: enemy.spd,
        statuses: enemy.statuses || emptyStatusEffects(),
        statusLabels: activeStatusLabels(enemy.statuses),
        effectDice: Number(battle.enemyEffectDice || battle.enemyDiceRoll || 0),
        effectDetails: battleSideEffectDetails("enemy", battle),
        moves: (enemy.moveSet || []).map((moveEntry) => serializeBattleMove(moveEntry, "enemy", player, battle)),
      },
      attributeMatchup: attributeMatchupView,
      battle: {
        islandId: battle.islandId,
        islandKind: battle.islandKind,
        isRegionalSpawnEncounter: Boolean(battle.isRegionalSpawnEncounter),
        activeCrewIndex: battle.activeCrewIndex,
        roundIndex: battle.roundIndex,
        result: battle.result,
        deferredCoopResult: battle.deferredCoopResult ? safeJsonClone(battle.deferredCoopResult) : null,
        animating: !!battle.animating,
        hasPlayerAction: hasQueuedPlayerAction,
        hasEnemyAction: !!battle.enemyAction,
        roundResolved: battle.roundResolved,
        waitingResume: battle.waitingResume,
        canControl: canControlBattle,
        viewerLockedReason,
        roundPauseReturnsToMap: (state.gameState.players || []).length > 1,
        canFinish: canControlBattle && canEndBattleTurn(battle) && (!lineageExtractionView || lineageExtractionView.allResolved),
        canAct: canControlBattle && !coopRescueWait && !handoffPending && !battlePrebattleIntroPending(battle) && !openingPassiveVisualPending(battle) && !battle.yonkoPrompt?.pending && !postgameBossMechanicPromptPending(battle) && !battle.animating && !hasQueuedPlayerAction && !battle.roundResolved && !battle.result && !battle.needsReplacement,
        handoffPending,
        coopInfo: coopReady,
        coopRescueWait,
        coopItemTargets: isCoopBattle(battle) ? coopBattleItemTargetPlayersForView(battle) : [],
        coopView: coopReady ? {
          viewingPlayerId: player.id,
          viewingPlayerName: player.name,
          currentPlayerId: coopCommandPlayerId,
          currentPlayerName: coopCommandPlayerName,
          isViewingCurrentActor: String(player.id || "") === coopCommandPlayerId,
          isViewingLocalPlayer: String(player.id || "") === String(coopReady.localPlayerId || ""),
          viewOnly: !canControlBattle,
        } : null,
        needsReplacement: !!battle.needsReplacement,
        replacementReason: String(battle.replacementReason || ""),
        luffyGearFifthAwakeningPending: !!battle.luffyGearFifthAwakeningPending,
        keepPlayerPortraitOnKnockout: !!battle.keepPlayerPortraitOnKnockout,
        yonkoStatus: yonkoBattleStatusForView(player, battle),
        finalGateStatus: finalGateBattleStatusForView(player, battle),
        yonkoPrompt: battle.yonkoPrompt?.pending ? safeJsonClone(battle.yonkoPrompt) : null,
        postgameBossMechanic: postgameBossMechanicView(player, battle),
        replacementCandidates: battleCrewEntries(player, battle)
          .map(({ card, index }) => serializeBattleCrewCard(card, index, battle))
          .filter((card) => !card.isActive && card.currentHp > 0),
        judicialSwitchPrompt: battle.judicialSwitchPrompt ? {
          ...safeJsonClone(battle.judicialSwitchPrompt),
          currentIndex: battle.activeCrewIndex,
          candidates: battleCrewEntries(player, battle)
            .map(({ card, index }) => serializeBattleCrewCard(card, index, battle))
            .filter((card) => card.currentHp > 0),
        } : null,
        log: battle.log || [],
        prebattleIntro: battle.prebattleIntro ? safeJsonClone(battle.prebattleIntro) : null,
        playerDiceRoll: battle.playerDiceRoll,
        enemyDiceRoll: battle.enemyDiceRoll,
        visualEvent: battle.visualEvent || null,
        openingPassiveVisualPending: openingPassiveVisualPending(battle),
        openingPassiveVisualQueue: openingPassiveVisualQueueForView(battle),
        kyubiMaskVisualPending: !!battle.kyubiMaskVisualPending || !!battle.kyubiMaskVisualAnimating,
        raidPhaseReward: battle.raidPhaseReward || null,
        judicialOpeningBoost: battle.judicialOpeningBoost || null,
        rewards: battle.result === "win" ? (coopOwnRewards || (battle.rewards ? safeJsonClone(battle.rewards) : getBattleRewards(battle))) : null,
        coopRewardDetails: battle.result === "win" && Array.isArray(battle.coopRewardDetails) ? safeJsonClone(battle.coopRewardDetails) : [],
        lineageExtraction: lineageExtractionView,
        escapeThreshold: (battle.isJudicialRaid || battle.isMarineford || battle.noEscape || battle.isNoEscape) ? 0 : getTeamEffects(player).escapeThreshold || 0,
        raidInfo,
      },
    };
  }

  function battlePhaseHpBarMarkup(phaseBars, activePercent, activeFillId = "") {
    if (!phaseBars) return "";
    const activePhase = Number(phaseBars.activePhase || 1);
    const percent = Math.max(0, Math.min(100, Number(phaseBars.layerPercent ?? activePercent ?? 0)));
    const badge = phaseBars.badge || "";
    return `
      <div class="battle-yonko-hp-wrap ${badge ? "has-badge" : ""}" data-active-phase="${activePhase}">
        <div class="battle-hp battle-yonko-hp yonko-phase-${activePhase}">
          <span ${activeFillId ? `id="${escapeModalText(activeFillId)}"` : ""} style="width:${percent}%;"></span>
        </div>
        ${badge ? `<span class="battle-yonko-hp-badge">${escapeModalText(badge)}</span>` : ""}
      </div>
    `;
  }

  function renderBattleModal() {
    const battle = state.battleState;
    const player = battlePlayer(null, battle);
    const activeCard = battleActiveCard(player, battle);
    const unlockedMoves = getUnlockedMoves(activeCard);
    const enemy = battle.enemyCombatant;
    const teamEffects = getTeamEffects(player);
    const playerAttributeMultiplier = attributeModifier(activeCard.attribute, enemy.attribute, teamEffects.disadvantagedFloor);
    const playerSpd = currentBattleStat("player", "spd", player, battle);
    const enemySpd = currentBattleStat("enemy", "spd", player, battle);
    const playerHpPercent = Math.max(0, Math.min(100, ((activeCard.currentHp || 0) / Math.max(1, activeCard.baseStats.hp)) * 100));
    const enemyHpPercent = Math.max(0, Math.min(100, ((enemy.currentHp || 0) / Math.max(1, enemy.maxHp)) * 100));
    const enemyPhaseHpBars = battlePhaseHpBarsForView(player, battle);
    const playerStatusText = activeStatusLabels(battleStatusBag("player", battle)).join("、") || "正常";
    const enemyStatusText = activeStatusLabels(enemy.statuses).join("、") || "正常";
    const viewerCanControl = canBoardLanControlCurrentPlayer(player);
    const isLocked = !viewerCanControl || battlePrebattleIntroPending(battle) || !!battle.animating || battle.roundResolved || !!battle.result || coopBattleHandoffPending(battle);
    const isYonkoBattle = battle.islandKind === "yonko";
    const firstActorLabel = battle.firstActor === "player" ? player.name : battle.firstActor === "enemy" ? "敵人" : "待命";
    const activeCarry = serializeBattleCarryItem(activeCard, battle.activeCrewIndex, battle);
    openModal(`
      <h3 class="modal-title">${isYonkoBattle ? "四皇決鬥" : "戰鬥回合"}</h3>
      <div class="modal-sub">寶可夢式回合戰鬥：先選行動，再比優先度與速度，最後擲 d6 加成骰。</div>
      <div class="battle-cinematic battle-cinematic-inline" id="battleCinematic" aria-hidden="true">
        <div class="battle-speedlines" id="battleSpeedlines"></div>
        <div class="battle-skill-banner" id="battleSkillBanner"></div>
        <div class="battle-dice" id="battleDice">?</div>
        <div class="battle-hit-spark" id="battleHitSpark"></div>
        <div class="battle-damage-number" id="battleDamageNumber"></div>
        <div class="battle-float-text" id="battleFloatText"></div>
      </div>
      <div class="battle-grid" id="battleDuelRoot">
        <div class="battle-box battle-fighter player" id="battleFighterPlayer">
          <div class="name">${player.name} ・ ${activeCard.name}</div>
            <div class="meta">${tierLabel(activeCard.tier)} ・ ${activeCard.roleType} ・ ${attributePill(activeCard.attribute)} ・ Lv.${activeCard.level || 1} ・ 生命值 <span id="battlePlayerHpText">${activeCard.currentHp}/${activeCard.baseStats.hp}</span> ・ 攻擊 ${currentBattleStat("player", "atk", player, battle)} ・ 防禦 ${currentBattleStat("player", "def", player, battle)} ・ 特攻 ${currentBattleStat("player", "satk", player, battle)} ・ 特防 ${currentBattleStat("player", "sdef", player, battle)} ・ 速度 ${playerSpd}</div>
          <div class="battle-hp"><span id="battlePlayerHpFill" style="width:${playerHpPercent}%;"></span></div>
          <div class="meta">狀態：${playerStatusText}</div>
          <div class="meta">被動：${activeCard.passive}${characterPassiveEffectText(activeCard) ? `（${escapeModalText(characterPassiveEffectText(activeCard))}）` : ""}</div>
          <div class="meta">攜帶物：${activeCarry.id ? `${activeCarry.name}（${activeCarry.status || "戰鬥中生效"}）` : "無"}</div>
          <div class="meta">船長：${player.activeCrewIndex === battle.activeCrewIndex ? "目前上場" : "候補"}</div>
          ${viewerCanControl ? `<div class="modal-row" style="margin-top:10px;"><button type="button" class="ghost-btn" data-view-battle-card="${battle.activeCrewIndex}" ${isLocked ? "disabled" : ""}>查看角色詳情</button></div>` : ""}
        </div>
        <div class="battle-box battle-fighter enemy" id="battleFighterEnemy">
          <div class="name">${enemy.name}</div>
          <div class="meta">級別 ${tierLabel(enemy.tier)} ・ Lv.${enemy.level || enemyLevelForProgress(enemy.tier)} ・ 推薦戰力 ${enemy.recommendedPower}+ ・ ${attributePill(enemy.attribute)} ・ 速度 ${enemySpd}</div>
          ${enemyPhaseHpBars
            ? battlePhaseHpBarMarkup(enemyPhaseHpBars, enemyHpPercent, "battleEnemyHpFill")
            : `<div class="battle-hp"><span id="battleEnemyHpFill" style="width:${enemyHpPercent}%;"></span></div>`}
            <div class="meta">生命值 <span id="battleEnemyHpText">${battleEnemyHpTextForDisplay(enemy, battle)}</span> ・ 攻擊 ${currentBattleStat("enemy", "atk", player, battle)} ・ 防禦 ${currentBattleStat("enemy", "def", player, battle)} ・ 特攻 ${currentBattleStat("enemy", "satk", player, battle)} ・ 特防 ${currentBattleStat("enemy", "sdef", player, battle)}</div>
          <div class="meta">狀態：${enemyStatusText}</div>
        </div>
      </div>
      <div class="companion-grid">
        ${player.crew.map((card, idx) => `
          <div class="companion-card ${idx === battle.activeCrewIndex ? "active" : ""}">
            <div class="name">${idx === battle.activeCrewIndex ? "上場：" : ""}${card.name}</div>
            <div class="meta">${tierLabel(card.tier)} ・ ${card.roleType} ・ Lv.${card.level || 1} ・ HP ${card.currentHp}/${card.baseStats.hp}<br>${
              (() => {
                const carry = serializeBattleCarryItem(card, idx, battle);
                return carry.id ? `攜帶物：${carry.name}（${carry.status || "戰鬥中生效"}）` : "攜帶物：無";
              })()
            }</div>
          </div>
        `).join("")}
      </div>
      <div class="tier-strip">
        <span>先手：${firstActorLabel}</span>
        <span>玩家骰 ${battle.playerDiceRoll || "?"}</span>
        <span>敵方骰 ${battle.enemyDiceRoll || "?"}</span>
        <span>屬性倍率 ${playerAttributeMultiplier.toFixed(1)}x</span>
      </div>
      ${viewerCanControl ? `
        <div class="companion-grid">
          ${unlockedMoves.map((entry) => `
            <button type="button" class="companion-card" data-battle-move="${entry.id}" ${isLocked || entry.currentPP <= 0 ? "disabled" : ""}>
              <div class="name">${entry.name}</div>
              <div class="meta">${entry.category || entry.type} ・ ${entry.attribute} ・ PP ${entry.currentPP}/${entry.pp} ・ ${battleMovePowerLabel("player", entry, player, battle)}</div>
              <div class="meta">${entry.effectText}</div>
            </button>
          `).join("")}
        </div>
      ` : `<div class="modal-sub">現在是 ${escapeModalText(player.name)} 的戰鬥，其他玩家只能觀看。</div>`}
      <div class="battle-log">
        ${battle.log.slice().reverse().map((item) => `<div class="battle-log-item">${item}</div>`).join("")}
      </div>
      ${viewerCanControl ? `
        <div class="modal-row">
          <button type="button" class="modal-btn secondary" id="battleItemBtn" ${isLocked ? "disabled" : ""}>道具</button>
          <button type="button" class="modal-btn secondary" id="battleSwitchBtn" ${isLocked ? "disabled" : ""}>換人</button>
          <button type="button" class="modal-btn secondary" id="battleEscapeBtn" ${isLocked ? "disabled" : ""}>逃跑</button>
          <button type="button" class="modal-btn secondary" id="battleCloseBtn" ${canEndBattleTurn(battle) && !battle.animating ? "" : "disabled"}>${battle.result === "round-pause" ? ((state.gameState.players || []).length > 1 ? "返回地圖，換下一位" : "進入下一輪") : battle.result ? "完成" : "等待本輪結算"}</button>
        </div>
      ` : ""}
    `);
    refs.modal.querySelectorAll("[data-battle-move]").forEach((button) => {
      button.addEventListener("click", () => queuePlayerBattleMove(button.dataset.battleMove));
    });
    refs.modal.querySelectorAll("[data-view-battle-card]").forEach((button) => {
      button.addEventListener("click", () => openCharacterDetail(player, Number(button.dataset.viewBattleCard)));
    });
    document.getElementById("battleItemBtn")?.addEventListener("click", openBattleItemPanel);
    document.getElementById("battleSwitchBtn")?.addEventListener("click", openSwitchCrewPanel);
    document.getElementById("battleEscapeBtn")?.addEventListener("click", attemptEscape);
    document.getElementById("battleCloseBtn")?.addEventListener("click", finishBattle);
  }

  function prefersReducedBattleMotion() {
    return window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;
  }

  function battleAnimationDuration(ms) {
    return prefersReducedBattleMotion() ? Math.min(160, Math.round(ms * 0.22)) : ms;
  }

  function restartBattleClass(element, className) {
    if (!element) return;
    element.classList.remove(className);
    void element.offsetWidth;
    element.classList.add(className);
  }

  function ensureBattleCinematicLayer() {
    return {
      root: document.getElementById("battleDuelRoot"),
      layer: document.getElementById("battleCinematic"),
      speedlines: document.getElementById("battleSpeedlines"),
      banner: document.getElementById("battleSkillBanner"),
      dice: document.getElementById("battleDice"),
      spark: document.getElementById("battleHitSpark"),
      damage: document.getElementById("battleDamageNumber"),
      floatText: document.getElementById("battleFloatText"),
      player: document.getElementById("battleFighterPlayer"),
      enemy: document.getElementById("battleFighterEnemy"),
      playerImg: document.getElementById("battlePlayerImg"),
      enemyImg: document.getElementById("battleEnemyImg"),
      playerHpFill: document.getElementById("battlePlayerHpFill"),
      enemyHpFill: document.getElementById("battleEnemyHpFill"),
      playerHpText: document.getElementById("battlePlayerHpText"),
      enemyHpText: document.getElementById("battleEnemyHpText"),
    };
  }

  function getBattleVisualSnapshot(player, battle) {
    const activeCard = battleActiveCard(player, battle);
    syncYonkoPhaseBattlePortraits(player, battle);
    const enemy = battle.enemyCombatant;
    const activeIndex = Math.max(0, Number(battle?.activeCrewIndex ?? player?.activeCrewIndex ?? 0));
    const activeMaxHp = cardMaxHp(activeCard);
    const raidSuitTransformed = sanjiRaidSuitDisplayedTransformed(activeCard, player, battle, activeIndex);
    const playerStatuses = battleStatusBag("player", battle) || emptyStatusEffects();
    const enemyStatuses = enemy?.statuses || emptyStatusEffects();
    return {
      player: {
        id: activeCard?.id || "",
        name: activeCard ? sanjiRaidSuitBattleViewName(activeCard, player, battle, activeIndex) : player?.name || "玩家",
        baseName: activeCard?.name || "",
        formId: activeCard?.formId || "base",
        formName: activeCard ? (raidSuitTransformed ? "隱形黑・Stealth Black" : activeEvolutionForm(activeCard)?.name || "") : "",
        tier: activeCard?.tier || "",
        roleType: activeCard?.roleType || "",
        attribute: activeCard?.attribute || "",
        battlePortraits: activeCard ? sanjiRaidSuitBattleViewPortraits(activeCard, player, battle, activeIndex) : null,
        passive: raidSuitTransformed ? SANJI_RAID_SUIT_PASSIVE.name : activeCard?.passive || "",
        passiveText: activeCard ? characterPassiveEffectText(activeCard) : "",
        raidSuitTransformed,
        level: activeCard?.level || 1,
        criticalStyle: activeCard ? characterCriticalStyle(activeCard) : "",
        criticalRateBase: activeCard ? characterCriticalBaseRate(activeCard) : 0,
        criticalRate: battleActorCriticalRate("player", player, battle),
        criticalDamageMultiplier: battleActorCriticalDamageMultiplier("player", player, battle),
        currentHp: activeCard?.currentHp || 0,
        maxHp: activeMaxHp,
        statuses: playerStatuses,
        statusLabels: activeStatusLabels(playerStatuses),
        effectDice: Number(battle?.playerEffectDice || battle?.playerDiceRoll || 0),
        effectDetails: battleSideEffectDetails("player", battle),
        carryItem: activeCard ? serializeBattleCarryItem(activeCard, activeIndex, battle) : null,
        isActive: true,
      },
      enemy: {
        name: enemy?.name || "敵人",
        key: enemy?.key || "",
        cosmeticFrameId: enemyCosmeticFrameIdFor(enemy),
        tier: enemy?.tier || "",
        level: enemy?.level || enemyLevelForProgress(enemy?.tier),
        criticalRate: battleActorCriticalRate("enemy", player, battle),
        criticalDamageMultiplier: battleActorCriticalDamageMultiplier("enemy", player, battle),
        role: enemy?.role || "",
        attribute: enemy ? yonkoEffectiveEnemyAttribute(battle) : "",
        battlePortraits: enemy?.battlePortraits || null,
        currentHp: enemy?.currentHp || 0,
        maxHp: enemy?.maxHp || 1,
        statuses: enemyStatuses,
        statusLabels: activeStatusLabels(enemyStatuses),
        effectDice: Number(battle?.enemyEffectDice || battle?.enemyDiceRoll || 0),
        effectDetails: battleSideEffectDetails("enemy", battle),
      },
    };
  }

  function battleVisualSnapshotSide(snapshot, side) {
    const entry = snapshot?.[side];
    return entry ? safeJsonClone(entry) : null;
  }

  function createBattleSwitchVisualEvent(player, battle, options = {}) {
    const toIndex = Number(options.toIndex ?? battle?.activeCrewIndex ?? player?.activeCrewIndex ?? 0);
    const snapshot = getBattleVisualSnapshot(player, battle);
    const fromName = options.fromName || "夥伴";
    const toName = options.toName || snapshot.player?.name || "新夥伴";
    const isReplacement = options.reason === "replacement";
    return {
      id: `switch-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      type: "switch",
      side: "player",
      reason: isReplacement ? "replacement" : "switch",
      fromIndex: Number(options.fromIndex ?? -1),
      toIndex,
      fromName,
      toName,
      actorName: toName,
      actorCombatant: battleVisualSnapshotSide(snapshot, "player"),
      finalSnapshot: safeJsonClone(snapshot),
      title: isReplacement ? `${toName} 上場！` : `換上 ${toName}！`,
      subtitle: fromName ? `${fromName} 退場，${toName} 上場。` : `${toName} 上場。`,
      duration: Math.max(900, Number(options.duration || BATTLE_SWITCH_ENTRY_DISPLAY_MS)),
    };
  }

  function buildBattleHitSnapshots(startSnapshot, targetSide, hitDamages = []) {
    if (!startSnapshot || !hitDamages.length) return [];
    const snapshots = [];
    let targetHp = targetSide === "enemy"
      ? Number(startSnapshot.enemy?.currentHp || 0)
      : Number(startSnapshot.player?.currentHp || 0);
    hitDamages.forEach((damage) => {
      targetHp = Math.max(0, targetHp - Math.max(0, Math.round(Number(damage || 0))));
      const nextSnapshot = safeJsonClone(startSnapshot);
      if (targetSide === "enemy" && nextSnapshot.enemy) nextSnapshot.enemy.currentHp = targetHp;
      if (targetSide === "player" && nextSnapshot.player) nextSnapshot.player.currentHp = targetHp;
      snapshots.push(nextSnapshot);
    });
    return snapshots;
  }

  function setBattleControlsLocked(locked) {
    const zone = document.getElementById("battleCommandZone");
    zone?.classList.toggle("is-locked", locked);
    refs.modal.querySelectorAll("[data-battle-move], #battleItemBtn, #battleSwitchBtn, #battleEscapeBtn, #battleCloseBtn").forEach((button) => {
      if (locked) button.setAttribute("disabled", "disabled");
    });
  }

  function updateBattleHpBars(snapshot) {
    const fx = ensureBattleCinematicLayer();
    if (fx.playerHpFill && snapshot?.player) {
      const pct = Math.max(0, Math.min(100, (snapshot.player.currentHp / Math.max(1, snapshot.player.maxHp)) * 100));
      fx.playerHpFill.style.width = `${pct}%`;
      if (fx.playerHpText) fx.playerHpText.textContent = `${snapshot.player.currentHp}/${snapshot.player.maxHp}`;
    }
    if (fx.enemyHpFill && snapshot?.enemy) {
      const pct = battleHpPercentForSnapshot(snapshot.enemy, state.battleState) ?? Math.max(0, Math.min(100, (snapshot.enemy.currentHp / Math.max(1, snapshot.enemy.maxHp)) * 100));
      fx.enemyHpFill.style.width = `${pct}%`;
      if (fx.enemyHpText) fx.enemyHpText.textContent = battleEnemyHpTextForDisplay(snapshot.enemy, state.battleState, snapshot.enemy.currentHp);
    }
  }

  function battleFighterElement(side) {
    const fx = ensureBattleCinematicLayer();
    return side === "enemy" ? fx.enemy : fx.player;
  }

  function setBattlePortraitState(side, stateName, player, battle) {
    const fx = ensureBattleCinematicLayer();
    const img = side === "enemy" ? fx.enemyImg : fx.playerImg;
    const activeCard = side === "player" ? battleActiveCard(player, battle) : null;
    const source = side === "enemy"
      ? battle?.enemyCombatant
      : activeCard
        ? { ...activeCard, battlePortraits: sanjiRaidSuitBattleViewPortraits(activeCard, player, battle, battle?.activeCrewIndex) }
        : null;
    if (!img || !source) return;
    const directionalHitKey = side === "player" ? "hitPlayerSide" : "hitEnemySide";
    const directionalHitSrc = stateName === "hit" ? source?.battlePortraits?.[directionalHitKey] : "";
    const mappedState = stateName === "hit" ? "hurt" : stateName === "normal" ? "idle" : stateName;
    const src = directionalHitSrc || getBattlePortraitUrl(source, mappedState);
    if (!src || img.src.endsWith(src)) return;
    img.classList.remove("is-hidden");
    img.src = src;
  }

  async function playBattleIntroIfNeeded(player, battle) {
    if (battle.introPlayed) return;
    battle.introPlayed = true;
    const fx = ensureBattleCinematicLayer();
    if (!fx.banner) return;
    fx.banner.textContent = `${player.name} VS ${battle.enemyCombatant.name}`;
    restartBattleClass(fx.banner, "show");
    await wait(battleAnimationDuration(520));
  }

  async function playBattleDiceAnimation({ title, subtitle, maxFace = 6, theme = "battle", settle = null }) {
    const fx = ensureBattleCinematicLayer();
    const hasForcedSettle = settle !== null && settle !== undefined && settle !== "";
    const forcedSettle = Number(settle);
    const settledFace = hasForcedSettle && Number.isFinite(forcedSettle)
      ? Math.max(1, Math.min(maxFace, Math.round(forcedSettle)))
      : randomInt(1, maxFace);
    if (!fx.dice || !fx.banner) return animateDice("battle", title, subtitle, maxFace, { settle: settledFace });
    fx.banner.textContent = title || "擲骰判定";
    restartBattleClass(fx.banner, "show");
    fx.dice.className = `battle-dice theme-${theme}`;
    fx.dice.textContent = "?";
    restartBattleClass(fx.dice, "show");
    const interval = setInterval(() => {
      fx.dice.textContent = String(randomInt(1, maxFace));
    }, battleAnimationDuration(80));
    await wait(battleAnimationDuration(1180));
    clearInterval(interval);
    fx.dice.textContent = String(settledFace);
    await wait(battleAnimationDuration(360));
    return settledFace;
  }

  async function playBattleDamageAnimation(targetSide, damage, snapshot) {
    const fx = ensureBattleCinematicLayer();
    const target = battleFighterElement(targetSide);
    if (!target || !fx.damage) return;
    const isEnemyTarget = targetSide === "enemy";
    const didConnect = Number(damage || 0) > 0;
    fx.damage.style.left = isEnemyTarget ? "74%" : "26%";
    fx.damage.style.top = isEnemyTarget ? "36%" : "42%";
    fx.damage.textContent = didConnect ? `-${damage}` : "MISS";
    if (didConnect) {
      restartBattleClass(fx.spark, "show");
      target.classList.add("hit");
      fx.root?.classList.add("battle-shake");
    }
    restartBattleClass(fx.damage, "show");
    updateBattleHpBars(snapshot);
    await wait(battleAnimationDuration(720));
    target.classList.remove("hit");
    fx.root?.classList.remove("battle-shake");
  }

  async function playBattleHealAnimation(side, amount, snapshot) {
    const fx = ensureBattleCinematicLayer();
    const fighter = battleFighterElement(side);
    if (!fighter || !fx.floatText) return;
    fighter.querySelector(".battle-portrait-stage")?.setAttribute("data-effect-label", "回復");
    fighter.classList.add("heal");
    fx.floatText.style.left = side === "enemy" ? "74%" : "26%";
    fx.floatText.textContent = `+${amount} HP`;
    restartBattleClass(fx.floatText, "show");
    updateBattleHpBars(snapshot);
    await wait(battleAnimationDuration(760));
    fighter.classList.remove("heal");
  }

  async function playBattleBuffAnimation(side, label = "能力上升") {
    const fx = ensureBattleCinematicLayer();
    const fighter = battleFighterElement(side);
    if (!fighter || !fx.floatText) return;
    fighter.querySelector(".battle-portrait-stage")?.setAttribute("data-effect-label", label);
    fighter.classList.add(label.includes("護盾") ? "shield" : "buff");
    fx.floatText.style.left = side === "enemy" ? "74%" : "26%";
    fx.floatText.textContent = label;
    restartBattleClass(fx.floatText, "show");
    await wait(battleAnimationDuration(760));
    fighter.classList.remove("buff", "shield");
  }

  async function playBattleDebuffAnimation(side, label = "能力下降") {
    const fx = ensureBattleCinematicLayer();
    const fighter = battleFighterElement(side);
    if (!fighter || !fx.floatText) return;
    fighter.querySelector(".battle-portrait-stage")?.setAttribute("data-effect-label", label);
    fighter.classList.add("debuff");
    fx.floatText.style.left = side === "enemy" ? "74%" : "26%";
    fx.floatText.textContent = label;
    restartBattleClass(fx.floatText, "show");
    await wait(battleAnimationDuration(760));
    fighter.classList.remove("debuff");
  }

  async function playBattleSwitchAnimation(side, fromName, toName) {
    const fx = ensureBattleCinematicLayer();
    const fighter = battleFighterElement(side);
    if (!fighter || !fx.floatText) return;
    fx.floatText.style.left = side === "enemy" ? "74%" : "26%";
    fx.floatText.textContent = `${fromName || "夥伴"} 退場，${toName || "新夥伴"} 上場！`;
    fighter.style.opacity = "0.35";
    fighter.style.transform = side === "enemy" ? "translateX(40px)" : "translateX(-40px)";
    restartBattleClass(fx.floatText, "show");
    await wait(battleAnimationDuration(160));
    fighter.style.opacity = "";
    fighter.style.transform = "";
    await wait(battleAnimationDuration(120));
  }

  async function playBattleEscapeAnimation(success) {
    const fx = ensureBattleCinematicLayer();
    const fighter = battleFighterElement("player");
    if (!fighter || !fx.floatText) return;
    fx.floatText.style.left = "28%";
    fx.floatText.textContent = success ? "逃跑成功！" : "逃跑失敗！";
    fighter.style.opacity = success ? "0.25" : "";
    fighter.style.transform = success ? "translateX(-80px)" : "translateX(-18px)";
    restartBattleClass(fx.floatText, "show");
    await wait(battleAnimationDuration(680));
    fighter.style.opacity = "";
    fighter.style.transform = "";
  }

  async function playBattleActionAnimation({ side, actorName, targetName, moveEntry, diceFace, damage, hitDamages = null, hitSnapshots = null, amount, resultText, snapshot, player, battle }) {
    // The iframe battle page is the sole visual timeline for the formal battle UI.
    // Do not let the retained legacy modal animation run (or delay the attack event)
    // after damage has already been committed to battle state.
    if (battleWindowIsActive()) return;
    const fx = ensureBattleCinematicLayer();
    const actor = battleFighterElement(side);
    const targetSide = side === "player" ? "enemy" : "player";
    const category = moveEntry?.category || moveEntry?.type || "attack";
    fx.layer?.classList.add("is-playing");
    setBattlePortraitState(targetSide, "idle", player, battle);
    setBattlePortraitState(side, "attack", player, battle);
    if (fx.banner) {
      fx.banner.textContent = `${actorName} 使用 ${moveEntry?.name || "行動"}！`;
      restartBattleClass(fx.banner, "show");
    }
    if (category === "attack" || category === "special") {
      const hits = Array.isArray(hitDamages) && hitDamages.length
        ? hitDamages.map((item) => Math.max(0, Math.round(Number(item || 0))))
        : [Math.max(0, Math.round(Number(damage || 0)))];
      restartBattleClass(fx.speedlines, "show");
      for (let index = 0; index < hits.length; index += 1) {
        if (actor) restartBattleClass(actor, "attack");
        await wait(battleAnimationDuration(index === 0 ? 460 : 170));
        if (hits[index] > 0) setBattlePortraitState(targetSide, "hit", player, battle);
        await playBattleDamageAnimation(targetSide, hits[index], hitSnapshots?.[index] || snapshot);
        actor?.classList.remove("attack");
        if (index < hits.length - 1) await wait(battleAnimationDuration(90));
      }
    } else if (category === "heal") {
      actor?.classList.add("attack");
      await wait(battleAnimationDuration(260));
      await playBattleHealAnimation(side, amount || 0, snapshot);
      actor?.classList.remove("attack");
    } else if (category === "buff" || category === "shield") {
      actor?.classList.add("attack");
      await wait(battleAnimationDuration(260));
      await playBattleBuffAnimation(side, category === "shield" ? "護盾展開" : "能力上升");
      actor?.classList.remove("attack");
    } else if (category === "debuff" || category === "control") {
      actor?.classList.add("attack");
      await wait(battleAnimationDuration(260));
      await playBattleDebuffAnimation(targetSide, category === "control" ? "控制壓制" : "能力下降");
      actor?.classList.remove("attack");
    } else {
      await playBattleBuffAnimation(side, resultText || "特殊效果");
    }
    setBattlePortraitState("player", "idle", player, battle);
    setBattlePortraitState("enemy", "idle", player, battle);
    fx.layer?.classList.remove("is-playing");
    await wait(battleAnimationDuration(180));
  }

  async function playBattleRoundEndAnimation(battle) {
    const fx = ensureBattleCinematicLayer();
    if (!fx.banner) return;
    fx.banner.textContent = battle.result === "round-pause" ? "本輪結束" : battle.result === "win" ? "勝利！" : battle.result === "lose" ? "戰敗..." : "戰鬥結果";
    restartBattleClass(fx.banner, "show");
    await wait(battleAnimationDuration(520));
  }

  function sparParticipantContext(battle, participant) {
    return sparBattleAdapter(battle, participant, sparOpponentParticipant(battle, participant.playerId));
  }

  function sparActionPriority(battle, participant) {
    const context = sparParticipantContext(battle, participant);
    if (!context.battle) return 0;
    return getBattleActionPriority("player", participant.action, context.player, context.battle);
  }

  function sparActionSpeed(battle, participant) {
    const context = sparParticipantContext(battle, participant);
    if (!context.battle) return 0;
    return battleSpeedForOrder("player", context.player, context.battle);
  }

  function sparActionLabel(participant) {
    const action = participant?.action;
    if (!action) return "等待行動";
    if (action.type === "switch") return `換上 ${participant.crew?.[Number(action.nextIndex)]?.name || "夥伴"}`;
    if (action.type === "surrender") return "投降";
    const card = sparActiveCard(participant);
    const move = getUnlockedMoves(card).find((entry) => entry.id === action.moveId);
    return `${card?.name || participant.name}：${move?.name || "技能"}`;
  }

  function sparActionBlocked(participant, battle) {
    const bag = sparParticipantStatusBag(participant);
    if (Number(bag.freeze || 0) > 0) {
      battle.log.push(`${sparActiveCard(participant)?.name || participant.name} 被冰凍，無法行動。`);
      return true;
    }
    if (Number(bag.bind || 0) > 0) {
      battle.log.push(`${sparActiveCard(participant)?.name || participant.name} 被束縛，無法行動。`);
      return true;
    }
    if (Number(bag.paralyze || 0) > 0) {
      const face = randomInt(1, 6);
      battle.log.push(`${sparActiveCard(participant)?.name || participant.name} 的麻痺判定骰出 ${face}。`);
      if (face <= 2) return true;
    }
    return false;
  }

  function sparHpSnapshot(battle) {
    return Object.fromEntries((battle.participantOrder || []).map((id) => [String(id), Number(sparActiveCard(sparBattleParticipant(battle, id))?.currentHp || 0)]));
  }

  function sparSetVisualEvent(battle, participant, data = {}) {
    battle.visualEvent = {
      id: `spar-${data.type || "event"}-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      actorId: participant.playerId,
      actorName: sparActiveCard(participant)?.name || participant.name,
      targetName: sparActiveCard(sparOpponentParticipant(battle, participant.playerId))?.name || "對手",
      duration: Number(data.duration || 1650),
      ...data,
    };
    notifyBattleWindow();
    scheduleBoardLanStatePush("spar-battle-visual", 10, { force: true });
    return battle.visualEvent;
  }

  function sparApplySwitch(battle, participant, nextIndex, reason = "switch") {
    const index = Number(nextIndex);
    const card = participant?.crew?.[index];
    if (!card || Number(card.currentHp || 0) <= 0 || index === Number(participant.activeCrewIndex)) return false;
    const previous = sparActiveCard(participant);
    participant.activeCrewIndex = index;
    participant.stages = emptyStages();
    participant.stageTurns = emptyStageTurns();
    participant.roundEffects = emptyRoundEffects();
    participant.statuses = sparParticipantStatusBag(participant, index);
    participant.needsReplacement = false;
    const context = sparParticipantContext(battle, participant);
    if (context.battle) {
      context.battle.activeCrewIndex = index;
      context.player.activeCrewIndex = index;
      ensureSanjiRaidSuitTransformation(context.player, context.battle, index, { queueOpening: false });
      syncSparParticipantFromAdapter(participant, context.battle);
    }
    battle.log.push(`${participant.name} ${reason === "replacement" ? "補上" : "換上"} ${card.name}。`);
    sparSetVisualEvent(battle, participant, {
      type: "switch",
      moveName: "更換出戰角色",
      moveType: "switch",
      fromName: previous?.name || "夥伴",
      toName: card.name,
      duration: BATTLE_SWITCH_ENTRY_DISPLAY_MS,
    });
    return true;
  }

  function sparTryReviveDefender(battle, defender, attacker) {
    const card = sparActiveCard(defender);
    if (!card || Number(card.currentHp || 0) > 0) return false;
    const context = sparBattleAdapter(battle, defender, attacker);
    if (!context.battle) return false;
    const revived = tryPlayerBattleCarryRevive(context.player, context.battle, card)
      || tryCharacterPassiveRevive(context.player, context.battle, card);
    syncSparParticipantFromAdapter(defender, context.battle);
    return Boolean(revived);
  }

  function sparMarkKnockouts(battle) {
    for (const id of battle.participantOrder || []) {
      const participant = sparBattleParticipant(battle, id);
      const card = sparActiveCard(participant);
      if (!participant || !card || Number(card.currentHp || 0) > 0) continue;
      if (card.id && !participant.knockedOutCrew.includes(card.id)) participant.knockedOutCrew.push(card.id);
      const living = sparLivingCrewIndices(participant);
      if (!living.length) {
        const winner = sparOpponentParticipant(battle, participant.playerId);
        battle.result = "complete";
        battle.winnerId = String(winner?.playerId || "");
        battle.loserId = String(participant.playerId);
        battle.log.push(`${participant.name} 的三名出戰角色全部瀕死；${winner?.name || "對手"} 贏得切磋。`);
        return true;
      }
      participant.needsReplacement = true;
      participant.action = null;
      battle.log.push(`${card.name} 已瀕死，${participant.name} 必須選擇下一名角色。`);
    }
    return false;
  }

  async function sparRollMoveDice(battle, participant, moveEntry, context) {
    const diceFace = await rollBattleActionDiceWithPassives(
      battleDiceThemeForMove(moveEntry),
      `${sparActiveCard(participant)?.name || participant.name} 使用 ${moveEntry.name}`,
      "決定招式最終效果…",
      context.battle,
      6,
      { side: "player", moveType: isComboBattleMove(moveEntry) ? "combo" : (moveEntry.category || moveEntry.type || "attack"), suppressVisual: true },
    );
    participant.diceRoll = diceFace;
    sparSetVisualEvent(battle, participant, {
      type: "dice",
      theme: battleDiceThemeForMove(moveEntry),
      title: `${sparActiveCard(participant)?.name || participant.name} 使用 ${moveEntry.name}`,
      subtitle: "切磋加成骰",
      maxFace: 6,
      settle: diceFace,
      moveName: moveEntry.name,
      moveType: isComboBattleMove(moveEntry) ? "combo" : (moveEntry.category || moveEntry.type || "attack"),
      bonusText: battleDiceBonusText(moveEntry.category || moveEntry.type || "attack", diceFace),
      duration: 1250,
    });
    await wait(1450);
    return diceFace;
  }

  async function executeSparMoveAction(battle, attacker, defender) {
    const attackerContext = sparBattleAdapter(battle, attacker, defender);
    if (!attackerContext.battle) return;
    const attackerCard = sparActiveCard(attacker);
    const moveEntry = getUnlockedMoves(attackerCard).find((entry) => entry.id === attacker.action?.moveId);
    if (!moveEntry || Number(moveEntry.currentPP || 0) <= 0 || Number(attackerCard?.currentHp || 0) <= 0) return;
    if (sparActionBlocked(attacker, battle)) {
      sparSetVisualEvent(battle, attacker, { type: "status", moveName: "行動受阻", moveType: "control", duration: 1000 });
      await wait(1100);
      return;
    }
    moveEntry.currentPP = Math.max(0, Number(moveEntry.currentPP || 0) - 1);
    const diceFace = await sparRollMoveDice(battle, attacker, moveEntry, attackerContext);
    const startHp = sparHpSnapshot(battle);
    let totalDamage = 0;
    let hitDamages = [];
    let hit = true;
    let effectFx = null;
    const attackVisualMeta = { critical: false, criticalCount: 0 };
    if (battleMoveDealsDamage(moveEntry)) {
      const hitCheck = battleMoveHits("player", moveEntry, attackerContext.player, attackerContext.battle);
      hit = hitCheck.hit;
      if (hit) {
        const bonus = bonusDamageFromMove(moveEntry, diceFace, attackerContext.player, attackerContext.battle, "player");
        if (isComboBattleMove(moveEntry)) {
          let maxHits = comboMoveMaxHits(moveEntry, diceFace);
          maxHits = battleCarryAdjustedMultiHit("player", moveEntry, diceFace, maxHits, attackerContext.player, attackerContext.battle);
          hitDamages = computeComboHitDamages("player", moveEntry, diceFace, maxHits, bonus, attackerContext.player, attackerContext.battle, attackVisualMeta);
        } else {
          const baseDamage = computeMoveDamage("player", moveEntry, diceFace, attackerContext.player, attackerContext.battle, attackVisualMeta);
          hitDamages = splitBattleDamageIntoHits(baseDamage, 1, bonus);
        }
        totalDamage = applyOffensiveBattleCarryAfterHit("player", battleDamageHitTotal(hitDamages), attackerContext.player, attackerContext.battle);
        const defenderContext = sparBattleAdapter(battle, defender, attacker);
        if (defenderContext.battle) {
          defenderContext.battle.enemyAction = { type: "move", moveId: moveEntry.id };
          totalDamage = applyDefensiveBattleCarryBeforeDamage("player", totalDamage, defenderContext.player, defenderContext.battle, attackVisualMeta);
          totalDamage = applyShipFirstBattleDamageReduction(totalDamage, defenderContext.player, defenderContext.battle);
          totalDamage = Math.max(0, Math.round(totalDamage * characterPassiveDamageTakenMultiplier(moveEntry, defenderContext.player, defenderContext.battle)));
          totalDamage = Math.max(0, Math.round(totalDamage * (1 - Number(getTeamEffects(defenderContext.player).supportDamageReduction || 0))));
          hitDamages = scaleBattleHitDamagesToTotal(hitDamages, totalDamage);
          const defenderCard = sparActiveCard(defender);
          const beforeHp = Number(defenderCard.currentHp || 0);
          defenderCard.currentHp = Math.max(0, beforeHp - totalDamage);
          const actualDamage = Math.max(0, beforeHp - Number(defenderCard.currentHp || 0));
          storeBattleCarryDamageAfterHit("player", actualDamage, defenderContext.player, defenderContext.battle);
          applyCharacterPassiveAfterDamageTaken(defenderContext.player, defenderContext.battle, defenderCard, actualDamage, moveEntry);
          syncSparParticipantFromAdapter(defender, defenderContext.battle);
          totalDamage = actualDamage;
        }
        applyPlayerCarryAfterDirectAction("player", moveEntry, true, totalDamage, diceFace, attackerContext.player, attackerContext.battle);
        const healingDone = applyMoveEffects(moveEntry, "player", diceFace, attackerContext.player, attackerContext.battle, "attack", totalDamage);
        effectFx = battleVisualEffectForMove(moveEntry, "player", "attack", healingDone, diceFace);
        battle.log.push(`${attacker.name} 的 ${attackerCard.name} 使用 ${moveEntry.name}，造成 ${totalDamage} 點傷害${battleHitBreakdownText(hitDamages)}。`);
      } else {
        applyMoveEffects(moveEntry, "player", diceFace, attackerContext.player, attackerContext.battle, "miss", 0);
        applyPlayerCarryAfterDirectAction("player", moveEntry, false, 0, diceFace, attackerContext.player, attackerContext.battle);
        applyPlayerMissBattleCarryEffects(attackerContext.player, attackerContext.battle);
        battle.log.push(`${attacker.name} 的 ${attackerCard.name} 使用 ${moveEntry.name}，但攻擊落空。`);
      }
    } else {
      const phase = (moveEntry.category || moveEntry.type) === "heal" ? "heal" : "status";
      const healingDone = applyMoveEffects(moveEntry, "player", diceFace, attackerContext.player, attackerContext.battle, phase, 0);
      effectFx = battleVisualEffectForMove(moveEntry, "player", phase, healingDone, diceFace);
      battle.log.push(`${attacker.name} 的 ${attackerCard.name} 使用 ${moveEntry.name}。`);
    }
    syncSparParticipantFromAdapter(attacker, attackerContext.battle);
    if (Number(sparActiveCard(defender)?.currentHp || 0) <= 0) sparTryReviveDefender(battle, defender, attacker);
    const finalHp = sparHpSnapshot(battle);
    const hitEffect = hit && totalDamage > 0 ? battleHitEffectForMove(moveEntry, diceFace, hitDamages) : "";
    sparSetVisualEvent(battle, attacker, {
      type: battleMoveDealsDamage(moveEntry) ? "attack" : ((moveEntry.category || moveEntry.type) === "heal" ? "heal" : "status"),
      moveName: moveEntry.name,
      moveType: moveEntry.category || moveEntry.type || "attack",
      damage: totalDamage,
      hitDamages,
      critical: !!attackVisualMeta.critical,
      criticalCount: Math.max(0, Number(attackVisualMeta.criticalCount || 0)),
      criticalHitIndexes: Array.isArray(attackVisualMeta.criticalHitIndexes) ? attackVisualMeta.criticalHitIndexes.slice() : [],
      hitEffect,
      hitSfx: hitEffect ? battleHitSfxForMove(moveEntry, hitEffect) : "",
      diceFace,
      miss: !hit,
      effectFx,
      startHpByPlayerId: startHp,
      finalHpByPlayerId: finalHp,
      duration: hitDamages.length > 1 ? Math.max(1900, 1200 + hitDamages.length * 520) : 1800,
    });
    await wait(Math.min(4200, Number(battle.visualEvent.duration || 1800) + 250));
  }

  function sparApplyRoundEnd(battle) {
    (battle.participantOrder || []).forEach((id) => {
      const participant = sparBattleParticipant(battle, id);
      const opponent = sparOpponentParticipant(battle, id);
      const context = sparBattleAdapter(battle, participant, opponent);
      if (!context.battle || Number(sparActiveCard(participant)?.currentHp || 0) <= 0) return;
      applyBattleCarryRoundEndEffects(context.player, context.battle);
      applyTeamSupportRoundEndHealing(context.player, context.battle);
      applyCharacterPassiveRoundEndEffects(context.player, context.battle);
      const relay = activePlayerCarryContexts(context.player, context.battle).find((ctx) => battleCarryItemEffect(ctx.item).kind === "switch_out_after_action");
      if (relay && participant.action?.type === "move" && sparLivingCrewIndices(participant).some((index) => index !== participant.activeCrewIndex)) {
        participant.needsReplacement = true;
        battle.log.push(`${relay.card.name}的${battleCarryItemName(relay.item)}在行動結算後啟動；請選擇下一名角色交棒。`);
      }
      syncSparParticipantFromAdapter(participant, context.battle);
      tickDownStatusBag(sparParticipantStatusBag(participant));
    });
  }

  function sparApplyRoundStart(battle) {
    (battle.participantOrder || []).forEach((id) => {
      const participant = sparBattleParticipant(battle, id);
      const card = sparActiveCard(participant);
      if (!card || Number(card.currentHp || 0) <= 0) return;
      const bag = sparParticipantStatusBag(participant);
      Object.entries(BATTLE_STATUS_INFO).forEach(([status, info]) => {
        if (!info.dotRatio || Number(bag[status] || 0) <= 0) return;
        const damage = Math.max(1, Math.round(cardMaxHp(card) * Number(info.dotRatio || 0)));
        card.currentHp = Math.max(0, Number(card.currentHp || 0) - damage);
        battle.log.push(`${card.name} 受到${info.label}影響，損失 ${damage} HP。`);
      });
      if (Number(participant.regen?.turns || 0) > 0 && Number(participant.regen?.ratio || 0) > 0) {
        const healed = healBattleTarget(card, participant.regen.ratio);
        if (healed > 0) battle.log.push(`${card.name} 的再生效果回復 ${healed} HP。`);
        participant.regen.turns -= 1;
      }
    });
    (battle.participantOrder || []).forEach((id) => {
      const participant = sparBattleParticipant(battle, id);
      const opponent = sparOpponentParticipant(battle, id);
      if (Number(sparActiveCard(participant)?.currentHp || 0) <= 0) sparTryReviveDefender(battle, participant, opponent);
    });
    sparMarkKnockouts(battle);
  }

  function startNextSparRound(battle) {
    battle.roundIndex += 1;
    battle.roundResolved = false;
    battle.visualEvent = null;
    (battle.participantOrder || []).forEach((id) => {
      const participant = sparBattleParticipant(battle, id);
      participant.action = null;
      participant.diceRoll = null;
      participant.actionSummary = "";
      resetRoundEffects(participant.roundEffects);
      if (participant.roundEffects.nextGuaranteedFirst) {
        participant.roundEffects.guaranteedFirst = true;
        participant.roundEffects.nextGuaranteedFirst = false;
      }
    });
    sparApplyRoundStart(battle);
    if (!battle.result) {
      const turnOwnerName = sparPlayerById(battle.turnOwnerId)?.name || "本回合玩家";
      battle.log.push(`切磋第 ${battle.roundIndex} 輪開始；由 ${turnOwnerName} 先選擇行動，對手再回應。`);
    }
  }

  function completeSparRoundAndAdvanceTurn(battle = state.battleState) {
    const spar = normalizeActiveSpar();
    const turnOwner = currentPlayer();
    if (!battle?.isSparBattle || !spar || battle.result || battle.animating) return false;
    if (String(turnOwner?.id || "") !== String(battle.turnOwnerId || "")) return false;
    if ((battle.participantOrder || []).some((id) => sparBattleParticipant(battle, id)?.needsReplacement)) return false;
    battle.roundResolved = true;
    battle.waitingMapTurn = true;
    battle.awaitingMapAdvance = false;
    battle.visualEvent = null;
    (battle.participantOrder || []).forEach((id) => {
      const participant = sparBattleParticipant(battle, id);
      if (!participant) return;
      participant.action = null;
      participant.actionSummary = "";
      participant.diceRoll = null;
    });
    spar.status = "battle";
    spar.battleSnapshot = safeJsonClone(battle);
    spar.lastTurnOwnerId = String(turnOwner.id);
    spar.lastResolvedRound = Number(battle.roundIndex || 1);
    state.battleState = null;
    state.gameState.resolutionLock = false;
    state.gameState.battleExitLock = false;
    closeBattlePageOverlay();
    closeSparSelectionOverlay();
    closeModal();
    addLog(`${turnOwner.name} 的切磋行動已結算；保留戰況並依原順序換下一位玩家。`);
    endTurn({
      sparRoundComplete: true,
      reason: "spar-turn-complete",
      context: "spar",
      subtitle: "切磋一輪已結算，回到原本玩家順序。",
    });
    return true;
  }

  function finishSparBattleAndAdvanceTurn() {
    const battle = state.battleState;
    const spar = normalizeActiveSpar();
    const turnOwner = currentPlayer();
    if (!battle?.isSparBattle || !battle.result || !spar || String(turnOwner?.id || "") !== String(battle.turnOwnerId || "")) return false;
    if (!canBoardLanControlCurrentPlayer(turnOwner)) return false;
    clearBattleRefreshRecoveryCheckpoint(battle);
    const winner = sparPlayerById(battle.winnerId)?.name || "勝方";
    const loser = sparPlayerById(battle.loserId)?.name || "敗方";
    addLog(`切磋結束：${winner} 擊敗 ${loser}；主線狀態未受影響。`);
    state.gameState.activeSpar = null;
    state.battleState = null;
    state.gameState.resolutionLock = false;
    state.gameState.battleExitLock = false;
    closeBattlePageOverlay();
    closeSparSelectionOverlay();
    closeModal();
    endTurn({
      sparRoundComplete: true,
      reason: "spar-finish",
      context: "spar",
      subtitle: "切磋結束，依原本玩家順序繼續航海。",
    });
    return true;
  }

  async function resolveSparBattleRound(battle) {
    if (!battle?.isSparBattle || battle.animating || battle.result) return false;
    const participants = battle.participantOrder.map((id) => sparBattleParticipant(battle, id));
    if (participants.some((entry) => !entry?.action)) return false;
    persistBattleRefreshRecoveryCheckpoint(battle);
    battle.animating = true;
    const ordered = participants.slice().sort((a, b) => {
      const priority = sparActionPriority(battle, b) - sparActionPriority(battle, a);
      if (priority) return priority;
      const speed = sparActionSpeed(battle, b) - sparActionSpeed(battle, a);
      if (speed) return speed;
      return battle.participantOrder.indexOf(a.playerId) - battle.participantOrder.indexOf(b.playerId);
    });
    battle.firstActorId = ordered[0].playerId;
    battle.secondActorId = ordered[1].playerId;
    battle.log.push(`第 ${battle.roundIndex} 輪由 ${ordered[0].name} 先手；雙方指令已同時鎖定。`);
    notifyBattleWindow();
    scheduleBoardLanStatePush("spar-round-order", 10, { force: true });
    for (const participant of ordered) {
      if (battle.result) break;
      const opponent = sparOpponentParticipant(battle, participant.playerId);
      if (Number(sparActiveCard(participant)?.currentHp || 0) <= 0) continue;
      if (participant.action.type === "surrender") {
        battle.result = "complete";
        battle.loserId = participant.playerId;
        battle.winnerId = opponent.playerId;
        battle.log.push(`${participant.name} 在切磋中認輸。`);
        break;
      }
      if (participant.action.type === "switch") {
        sparApplySwitch(battle, participant, participant.action.nextIndex, "switch");
        await wait(1100);
      } else {
        await executeSparMoveAction(battle, participant, opponent);
      }
      if (sparMarkKnockouts(battle)) break;
    }
    if (!battle.result) {
      sparApplyRoundEnd(battle);
      sparMarkKnockouts(battle);
    }
    battle.animating = false;
    (battle.participantOrder || []).forEach((id) => { sparBattleParticipant(battle, id).action = null; });
    clearBattleRefreshRecoveryCheckpoint(battle);
    battle.roundResolved = true;
    battle.awaitingMapAdvance = !battle.result;
    const spar = normalizeActiveSpar();
    if (battle.result && spar) spar.status = "result";
    notifyBattleWindow();
    if (battle.result || battle.participantOrder.some((id) => sparBattleParticipant(battle, id).needsReplacement)) {
      scheduleBoardLanStatePush(battle.result ? "spar-battle-result" : "spar-round-replacement", 20, { force: true });
    } else {
      completeSparRoundAndAdvanceTurn(battle);
    }
    return true;
  }

  function queueSparBattleAction(action, options = {}) {
    const battle = state.battleState;
    const local = options.playerId ? sparPlayerById(options.playerId) : localBoardPlayer();
    const participant = sparBattleParticipant(battle, local?.id);
    if (!battle?.isSparBattle || !participant || battle.animating || battle.result || participant.needsReplacement || participant.action) return false;
    if (!options.skipControl && !canBoardLanControlPlayerIdentity(local)) return false;
    if (sparExpectedActionPlayerId(battle) !== String(participant.playerId)) return false;
    const card = sparActiveCard(participant);
    if (action.type === "move") {
      const move = getUnlockedMoves(card).find((entry) => entry.id === action.moveId);
      if (!move || Number(move.currentPP || 0) <= 0) return false;
      const context = sparParticipantContext(battle, participant);
      const assault = context.battle ? activePlayerCarryContexts(context.player, context.battle).find((ctx) => battleCarryItemEffect(ctx.item).kind === "sdef_bonus_block_support_skills") : null;
      if (assault && !["attack", "special"].includes(move.category)) {
        battle.log.push(`${card.name}受到突擊防彈背心限制，不能使用純輔助技能。`);
        notifyBattleWindow();
        return false;
      }
      const choiceContext = context.battle ? activePlayerCarryContexts(context.player, context.battle).find((ctx) => {
        const kind = String(battleCarryItemEffect(ctx.item).kind || "");
        return ["choice_band", "choice_glasses", "choice_scarf"].includes(ctx.item.id) || /^choice_lock_/.test(kind);
      }) : null;
      if (choiceContext?.state?.lockedSkillId && choiceContext.state.lockedSkillId !== move.id) {
        battle.log.push(`${card.name}受到${battleCarryItemName(choiceContext.item)}限制，本場只能使用已鎖定招式。`);
        notifyBattleWindow();
        return false;
      }
      if (choiceContext?.state) choiceContext.state.lockedSkillId = move.id;
    }
    participant.action = { ...action, actorCrewIndex: participant.activeCrewIndex };
    participant.actionSummary = sparActionLabel(participant);
    battle.log.push(`${participant.name} 已秘密鎖定本輪行動。`);
    if (action.type === "surrender") {
      const opponent = sparOpponentParticipant(battle, participant.playerId);
      battle.result = "complete";
      battle.loserId = participant.playerId;
      battle.winnerId = opponent?.playerId || "";
      battle.roundResolved = true;
      battle.awaitingMapAdvance = false;
      const spar = normalizeActiveSpar();
      if (spar) spar.status = "result";
      battle.log.push(`${participant.name} 在切磋中認輸。`);
      notifyBattleWindow();
      scheduleBoardLanStatePush("spar-battle-result", 20, { force: true });
      return true;
    }
    notifyBattleWindow();
    scheduleBoardLanStatePush("spar-action", 20, { force: true });
    if (battle.participantOrder.every((id) => !!sparBattleParticipant(battle, id)?.action)) void resolveSparBattleRound(battle);
    return true;
  }

  function chooseSparReplacement(nextIndex, options = {}) {
    const battle = state.battleState;
    const local = options.playerId ? sparPlayerById(options.playerId) : localBoardPlayer();
    const participant = sparBattleParticipant(battle, local?.id);
    if (!battle?.isSparBattle || !participant?.needsReplacement || battle.animating || battle.result) return false;
    if (!options.skipControl && !canBoardLanControlPlayerIdentity(local)) return false;
    if (!sparApplySwitch(battle, participant, Number(nextIndex), "replacement")) return false;
    const waiting = battle.participantOrder.some((id) => sparBattleParticipant(battle, id)?.needsReplacement);
    if (!waiting && battle.awaitingMapAdvance) return completeSparRoundAndAdvanceTurn(battle);
    notifyBattleWindow();
    scheduleBoardLanStatePush("spar-replacement", 20, { force: true });
    return true;
  }

  function processSparBattleCommand(command) {
    if (!state.battleState?.isSparBattle || !command) return false;
    if (command.type === "move") return queueSparBattleAction({ type: "move", moveId: command.payload?.moveId });
    if (command.type === "switch") return queueSparBattleAction({ type: "switch", nextIndex: Number(command.payload?.nextIndex) });
    if (command.type === "replacement") return chooseSparReplacement(Number(command.payload?.nextIndex));
    if (command.type === "surrender") return queueSparBattleAction({ type: "surrender" });
    if (command.type === "finish") return finishSparBattleAndAdvanceTurn();
    return false;
  }

  function queuePlayerBattleMove(moveId, targetId = "") {
    const battle = state.battleState;
    if (!battle || battle.yonkoPrompt?.pending || postgameBossMechanicPromptPending(battle) || battle.animating || battle.roundResolved || battle.result || coopBattleHandoffPending(battle)) return false;
    if (isCoopBattle(battle) && !battle.__coopQueueRuntime) {
      const coopPlayer = battleCommandPlayer(battle);
      if (!coopPlayer || warnBoardLanBattleLocked(coopPlayer, battle)) return false;
      prepareCoopBattleCommandRuntime(coopPlayer, battle);
      battle.__coopQueueRuntime = true;
      try {
        return queuePlayerBattleMove(moveId, targetId);
      } finally {
        battle.__coopQueueRuntime = false;
      }
    }
    const player = battlePlayer(null, battle);
    if (isCoopBattle(battle) ? warnBoardLanBattleLocked(player, battle) : warnBoardLanTurnLocked(player)) return;
    if (postgameBossMechanicFor(battle)?.key === "postgame_charlotte_katakuri" && !postgameKatakuriMoveChoiceActive(player, battle)) return false;
    const activeCard = battleActiveCard(player, battle);
    const moveEntry = getUnlockedMoves(activeCard).find((entry) => entry.id === moveId);
    if (!moveEntry || (moveEntry.currentPP ?? 0) <= 0) return;
    if (activeBlackbeardCaptureTurns(player, battle) > 0 && (moveEntry.currentPP ?? 0) <= 1) {
      battle.log.push(`${activeCard.name} 被黑暗捕獲，技能需要額外 PP，${moveEntry.name} PP 不足。`);
      notifyBattleWindow();
      renderBattleInterface();
      return;
    }
    if (activeFinalGateBlackTurns(player, battle) > 0 && (moveEntry.currentPP ?? 0) <= 1) {
      battle.log.push(`${activeCard.name} 被黑轉支配，技能需要額外 PP，${moveEntry.name} PP 不足。`);
      notifyBattleWindow();
      renderBattleInterface();
      return;
    }
    const carryContexts = activePlayerCarryContexts(player, battle);
    const assaultCtx = carryContexts.find((ctx) => ctx.item?.id === "assault_vest" || battleCarryItemEffect(ctx.item).kind === "sdef_bonus_block_support_skills");
    if (assaultCtx && !["attack", "special"].includes(moveEntry.category)) {
      battle.log.push(`${assaultCtx.card.name}受到突擊防彈背心限制，不能使用純輔助技能。`);
      notifyBattleWindow();
      renderBattleInterface();
      return;
    }
    for (const ctx of carryContexts) {
      const carryEffect = battleCarryItemEffect(ctx.item);
      if (!(["choice_band", "choice_glasses", "choice_scarf"].includes(ctx.item.id) || /^choice_lock_/.test(carryEffect.kind || "")) || !["attack", "special"].includes(moveEntry.category)) continue;
      if (ctx.state.lockedSkillId && ctx.state.lockedSkillId !== moveId) {
        battle.log.push(`${ctx.card.name}受到${battleCarryItemName(ctx.item)}限制，本場只能使用 ${getUnlockedMoves(activeCard).find((entry) => entry.id === ctx.state.lockedSkillId)?.name || "已鎖定招式"}。`);
        notifyBattleWindow();
        renderBattleInterface();
        return;
      }
      ctx.state.lockedSkillId = moveId;
    }
    carryContexts.forEach((ctx) => {
      const carryEffect = battleCarryItemEffect(ctx.item);
      if (carryEffect.kind !== "skip_charge_once" || ctx.state.usedThisBattle || !["attack", "special"].includes(moveEntry.category)) return;
      ctx.state.usedThisBattle = true;
      battle.playerRoundEffects.nextHitBoost = Math.max(Number(battle.playerRoundEffects.nextHitBoost || 0), Number(carryEffect.fallbackDamageBonus || 0.15));
      battle.playerRoundEffects.guaranteedFirst = true;
      battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}讓攻勢立即爆發，本次攻擊更快且威力提升。`);
    });
    const validTargets = new Set(postgameBossMechanicTargets(player, battle).map((entry) => entry.id));
    const resolvedTargetId = validTargets.has(String(targetId || "")) ? String(targetId) : postgameBossDefaultTarget(player, battle);
    const actorCrewIndex = Math.max(0, Number(battle.activeCrewIndex ?? player.activeCrewIndex ?? 0));
    if (isCoopBattle(battle)) {
      return queueCoopBattleAction(player, battle, { type: "move", moveId, targetId: resolvedTargetId, actorCrewIndex });
    }
    battle.playerAction = {
      type: "move",
      moveId,
      targetId: resolvedTargetId,
      actorCrewIndex,
    };
    battle.enemyAction = chooseEnemyAction(battle);
    const plannedEnemyAction = safeJsonClone(battle.enemyAction);
    void resolvePlannedBattleActions(player, battle);
  }

  function queuePostgameZephyrDisarm() {
    const battle = state.battleState;
    if (!battle || battle.yonkoPrompt?.pending || postgameBossMechanicPromptPending(battle) || battle.animating || battle.roundResolved || battle.result || coopBattleHandoffPending(battle)) return false;
    if (isCoopBattle(battle) && !battle.__coopQueueRuntime) {
      const coopPlayer = battleCommandPlayer(battle);
      if (!coopPlayer || warnBoardLanBattleLocked(coopPlayer, battle)) return false;
      prepareCoopBattleCommandRuntime(coopPlayer, battle);
      battle.__coopQueueRuntime = true;
      try {
        return queuePostgameZephyrDisarm();
      } finally {
        battle.__coopQueueRuntime = false;
      }
    }
    const player = battlePlayer(null, battle);
    const mechanic = postgameBossMechanicFor(battle);
    if (!player || mechanic?.key !== "postgame_zephyr" || !mechanic.countdownActive || mechanic.dynaRockDisarmed || mechanic.detonated) return false;
    if (isCoopBattle(battle) ? warnBoardLanBattleLocked(player, battle) : warnBoardLanTurnLocked(player)) return false;
    const action = { type: "zephyr-disarm", actorCrewIndex: Math.max(0, Number(battle.activeCrewIndex ?? player.activeCrewIndex ?? 0)) };
    if (isCoopBattle(battle)) return queueCoopBattleAction(player, battle, action);
    battle.playerAction = action;
    battle.enemyAction = chooseEnemyAction(battle);
    void resolvePlannedBattleActions(player, battle);
    return true;
  }

  function queuePlayerBattleSwitch(nextIndex) {
    const battle = state.battleState;
    if (!battle || battle.yonkoPrompt?.pending || postgameBossMechanicPromptPending(battle) || battle.animating || battle.roundResolved || battle.result || coopBattleHandoffPending(battle)) return false;
    if (isCoopBattle(battle) && !battle.__coopQueueRuntime) {
      const coopPlayer = battleCommandPlayer(battle);
      if (!coopPlayer || warnBoardLanBattleLocked(coopPlayer, battle)) return false;
      prepareCoopBattleCommandRuntime(coopPlayer, battle);
      battle.__coopQueueRuntime = true;
      try {
        return queuePlayerBattleSwitch(nextIndex);
      } finally {
        battle.__coopQueueRuntime = false;
      }
    }
    const player = battlePlayer(null, battle);
    if (isCoopBattle(battle) ? warnBoardLanBattleLocked(player, battle) : warnBoardLanTurnLocked(player)) return false;
    const card = player?.crew?.[nextIndex];
    if (activeBlackbeardCaptureTurns(player, battle) > 0) return false;
    if (activeFinalGateBlackTurns(player, battle) > 0) return false;
    if (!card || !battleCrewIndexIsEligible(player, battle, nextIndex) || nextIndex === battle.activeCrewIndex || card.currentHp <= 0) return false;
    voidPostgameOarsPrediction(battle, "本回合選擇換人");
    if (isCoopBattle(battle)) {
      return queueCoopBattleAction(player, battle, {
        type: "switch",
        nextIndex,
      });
    }
    battle.playerAction = { type: "switch", nextIndex };
    battle.enemyAction = chooseEnemyAction(battle);
    void resolvePlannedBattleActions(player, battle);
    return true;
  }

  function queuePlayerBattleItem(itemId, targetIndex = null, targetPlayerId = "", targetSide = "") {
    const battle = state.battleState;
    if (!battle || battle.yonkoPrompt?.pending || postgameBossMechanicPromptPending(battle) || battle.animating || battle.roundResolved || battle.result || coopBattleHandoffPending(battle)) return false;
    if (isCoopBattle(battle) && !battle.__coopQueueRuntime) {
      const coopPlayer = battleCommandPlayer(battle);
      if (!coopPlayer || warnBoardLanBattleLocked(coopPlayer, battle)) return false;
      prepareCoopBattleCommandRuntime(coopPlayer, battle);
      battle.__coopQueueRuntime = true;
      try {
        return queuePlayerBattleItem(itemId, targetIndex, targetPlayerId, targetSide);
      } finally {
        battle.__coopQueueRuntime = false;
      }
    }
    const player = battlePlayer(null, battle);
    if (!player) return false;
    if (isCoopBattle(battle) ? warnBoardLanBattleLocked(player, battle) : warnBoardLanTurnLocked(player)) return false;
    const option = getBattleItemOptions(player).find((item) => item.id === itemId);
    if (!option || option.count <= 0) return false;
    const requestedTargetSide = option.targetMode === "battle_side"
      ? (targetSide === "enemy" ? "enemy" : "player")
      : "";
    const requestedTargetPlayerId = String(targetPlayerId || player.id || "");
    const targetPlayer = isCoopBattle(battle)
      ? coopBattleParticipants(battle).find((entry) => String(entry.id) === requestedTargetPlayerId)
      : player;
    if (!targetPlayer) return false;
    const parsedTargetIndex = Number(targetIndex);
    if (Number.isInteger(parsedTargetIndex) && !battleCrewIndexIsEligible(targetPlayer, battle, parsedTargetIndex)) return false;
    const awaitingRescue = isCoopBattle(battle) && coopBattleParticipantAwaitingRescue(player, battle);
    if (awaitingRescue) {
      if (option.effectKind !== "revive" || String(targetPlayer.id) !== String(player.id)) return false;
      if (!Number.isInteger(parsedTargetIndex) || Number(targetPlayer.crew?.[parsedTargetIndex]?.currentHp || 0) > 0) return false;
    }
    voidPostgameOarsPrediction(battle, "本回合使用戰鬥道具");
    battle.playerAction = {
      type: "item",
      itemId,
      actorCrewIndex: Math.max(0, Number(battle.activeCrewIndex ?? player.activeCrewIndex ?? 0)),
      targetIndex: Number.isInteger(parsedTargetIndex) ? parsedTargetIndex : null,
      targetPlayerId: String(targetPlayer.id),
      targetSide: requestedTargetSide,
      rescueUse: awaitingRescue,
    };
    if (isCoopBattle(battle)) {
      return queueCoopBattleAction(player, battle, battle.playerAction);
    }
    battle.enemyAction = chooseEnemyAction(battle);
    void resolvePlannedBattleActions(player, battle);
    return true;
  }

  function battleWaitForRescue() {
    const battle = state.battleState;
    if (!battle || !isCoopBattle(battle) || battle.animating || coopBattleHandoffPending(battle)) return false;
    const player = battleCommandPlayer(battle);
    if (!player || warnBoardLanBattleLocked(player, battle) || !coopBattleParticipantAwaitingRescue(player, battle)) return false;
    const runtime = coopBattleRuntimeFor(player, battle, true);
    runtime.rescueTurnsRemaining = Math.max(0, Number(runtime.rescueTurnsRemaining || 0) - 1);
    runtime.awaitingRescue = runtime.rescueTurnsRemaining > 0;
    runtime.defeated = !runtime.awaitingRescue;
    runtime.needsReplacement = false;
    runtime.replacementAfterAction = false;
    recordJudicialRaidContribution(battle, player, { turnsActed: 1 });
    markImpelDownCoopParticipantActed(player, battle);
    clearCoopSingleActionState(battle);
    if (runtime.defeated) {
      battle.log.push(`${player.name} 的兩次待救援回合都結束，永久退出本場共鬥。`);
    } else {
      battle.log.push(`${player.name} 本次沒有獲救，剩下 ${runtime.rescueTurnsRemaining} 次自己的待救援回合。`);
    }
    if (!coopBattleCanStillRecover(battle)) {
      battle.result = "lose";
      battle.roundResolved = true;
      battle.waitingResume = false;
      delete battle.coopRescueWait;
      battle.log.push("所有共鬥玩家都已倒下，且沒有復活道具可用，戰鬥立即失敗。");
    } else {
      const nextPlayer = coopBattleNextTurnParticipantAfter(player, battle);
      if (nextPlayer) {
        scheduleCoopBattleHandoffVisual(nextPlayer, battle, "battle-coop-rescue-pass", "等待隊友救援。", 60, () => {
          if (state.battleState !== battle) return false;
          return handoffCoopBattleToParticipant(nextPlayer, battle);
        });
      } else {
        battle.result = "round-pause";
        battle.roundResolved = true;
        battle.waitingResume = true;
        delete battle.coopRescueWait;
        scheduleBattleRoundAutoPass(player, battle);
      }
    }
    renderBattleInterface();
    notifyBattleWindow();
    scheduleBoardLanStatePush("battle-coop-rescue-pass", 80, { force: true });
    return true;
  }

  function chooseEnemyAction(battle) {
    const enemy = battle.enemyCombatant;
    const mechanic = postgameBossMechanicFor(battle);
    if (mechanic?.key === "postgame_rob_lucci_awakened" && mechanic.rokuoganPending) {
      return { type: "move", moveId: "postgame_lucci_ultimate_rokuogan" };
    }
    if (mechanic?.key === "postgame_douglas_bullet" && mechanic.bulletLockedSkillId) {
      const lockedMove = (enemy.moveSet || []).find((entry) => entry.id === mechanic.bulletLockedSkillId && (entry.currentPP ?? entry.pp) > 0);
      if (lockedMove) return { type: "move", moveId: lockedMove.id };
      mechanic.bulletLockedSkillId = "";
    }
    const available = (enemy.moveSet || []).filter((entry) => {
      if ((entry.currentPP ?? entry.pp) <= 0) return false;
      if (mechanic?.key === "postgame_rob_lucci_awakened" && entry.id === "postgame_lucci_ultimate_rokuogan") return false;
      if (mechanic?.key === "postgame_douglas_bullet" && postgameBossMechanicBulletEffectSlots(battle, "sdef_bonus_block_support_skills").length && !["attack", "special"].includes(entry.category)) return false;
      if (isYonkoBattleKey(battle, "yonko_blackbeard") && entry.effects?.yonkoMove === "blackbeard_black_hole_field") {
        return Number(ensureYonkoBattleState(battlePlayer(null, battle), battle)?.blackHoleCooldown || 0) <= 0;
      }
      if (isFinalGateBattle(battle) && entry.effects?.finalGateMove === "domi_reversi") {
        return Number(ensureFinalGateBattleState(battlePlayer(null, battle), battle)?.domiCooldown || 0) <= 0;
      }
      return true;
    });
    if (!available.length) {
      const fallback = enemyMove(`${enemy.key || "enemy"}_struggle`, "普通攻擊", "attack", 99, 35, "PP耗盡時的普通攻擊", {}, { attribute: enemy.attribute || "無" });
      fallback.currentPP = 99;
      enemy.moveSet = [...(enemy.moveSet || []), fallback];
      return { type: "move", moveId: fallback.id };
    }
    const hpRate = enemy.currentHp / Math.max(1, enemy.maxHp);
    if (isFinalGateBattle(battle)) {
      const finalState = ensureFinalGateBattleState(battlePlayer(null, battle), battle);
      const domi = available.find((entry) => entry.effects?.finalGateMove === "domi_reversi");
      if (finalState?.phase2 && domi && Number(battle.roundIndex || 0) % 3 === 0) return { type: "move", moveId: domi.id };
      const abyss = available.find((entry) => entry.effects?.finalGateMove === "deep_abyss");
      if (abyss && Number(finalState?.abyssTurns || 0) <= 0 && Number(battle.roundIndex || 0) % 4 === 0) return { type: "move", moveId: abyss.id };
    }
    if (hpRate < 0.35) {
      const survival = available.find((entry) => entry.category === "shield")
        || available.find((entry) => entry.category === "buff" && entry.effects?.selfStages?.def)
        || available.find((entry) => entry.category === "buff");
      if (survival && battle.roundIndex % 4 !== 1) return { type: "move", moveId: survival.id };
    }
    const playerStages = battle.playerStages || {};
    const playerIsSetUp = ["atk", "def", "spd", "accuracy", "evasion"].some((key) => (playerStages[key] || 0) < 0);
    if (playerIsSetUp) {
      const finisher = available
        .filter((entry) => entry.category === "attack")
        .sort((a, b) => (b.power || 0) - (a.power || 0))[0];
      if (finisher) return { type: "move", moveId: finisher.id };
    }
    const enemyTierRank = tierRank(enemy.tier);
    const utilityCadence = { 1: 2, 2: 2, 3: 3, 4: 4, 5: 4 }[enemyTierRank] || 4;
    const useUtility = battle.roundIndex % utilityCadence === 0;
    const debuff = available.find((entry) => entry.category === "debuff" || entry.category === "control" || entry.category === "status");
    if (useUtility && debuff) return { type: "move", moveId: debuff.id };
    const attackMoves = available.filter((entry) => entry.category === "attack" || entry.category === "special");
    const sortedAttacks = attackMoves.sort((a, b) => (b.power || 0) - (a.power || 0));
    const shouldPressure = enemyTierRank <= 3 || battle.roundIndex % 3 !== 1;
    const pick = shouldPressure
      ? (sortedAttacks[0] || available[0])
      : (sortedAttacks[Math.min(sortedAttacks.length - 1, battle.roundIndex % Math.max(1, sortedAttacks.length))] || available[0]);
    return { type: "move", moveId: pick.id };
  }

  function getBattleActionPriority(side, action, player, battle) {
    if (!action) return -99;
    if (side === "player" && action.type === "item" && action.rescueUse) return 99;
    if (side === "player" && action.type === "katakuri-defense") return 98;
    if (action.type === "tot-dual") {
      const mechanic = postgameBossMechanicFor(battle);
      if (side !== "player" || mechanic?.key !== "postgame_tot_musica" || !mechanic.assigned) return 0;
      const worldPriority = (world, worldAction = {}) => {
        if (worldAction.type === "switch") return 6;
        if (worldAction.type === "escape") return 4;
        if (worldAction.type === "item") return 3;
        if (worldAction.type !== "move") return 0;
        const worldPlayer = postgameTotUsesPlayerWorlds(battle, mechanic) ? postgameTotActiveWorldPlayer(battle, mechanic, world) : player;
        const runtime = worldPlayer && postgameTotUsesPlayerWorlds(battle, mechanic) ? coopBattleRuntimeFor(worldPlayer, battle, true) : null;
        const activeIndex = Number(runtime?.activeCrewIndex ?? (world === "real" ? mechanic.realActiveIndex : mechanic.songActiveIndex));
        const moveEntry = worldPlayer?.crew?.[activeIndex]?.moveSet?.find((entry) => entry.id === worldAction.moveId);
        return Number(moveEntry?.effects?.priority || moveEntry?.priority || 0);
      };
      return Math.max(worldPriority("real", action.realAction), worldPriority("song", action.songAction));
    }
    if (action.type === "switch") return 6;
    if (action.type === "escape") return 4;
    if (action.type === "item") return 3;
    if (action.type === "zephyr-disarm") return 0;
    if (action.type === "move") {
      const moveEntry = side === "player"
        ? battleActiveCard(player, battle).moveSet.find((entry) => entry.id === action.moveId)
        : battle.enemyCombatant.moveSet.find((entry) => entry.id === action.moveId);
      return moveEntry?.effects?.priority || moveEntry?.priority || 0;
    }
    return 0;
  }

  function battleSpeedForOrder(side, player, battle) {
    const roundEffects = side === "player" ? battle.playerRoundEffects : battle.enemyCombatant.roundEffects;
    if (roundEffects?.guaranteedFirst) return 9999;
    const mechanic = postgameBossMechanicFor(battle);
    if (side === "player" && mechanic?.key === "postgame_tot_musica" && mechanic.assigned) {
      const previousBattleIndex = Number(battle.activeCrewIndex ?? player?.activeCrewIndex ?? 0);
      const previousPlayerIndex = Number(player?.activeCrewIndex ?? previousBattleIndex);
      const orderSpeedForIndex = (worldPlayer, index, worldLabel) => {
        if (!Number.isInteger(index) || Number(worldPlayer?.crew?.[index]?.currentHp || 0) <= 0) return -1;
        syncActivePlayerStatusBag(worldPlayer, battle);
        battle.activeCrewIndex = index;
        worldPlayer.activeCrewIndex = index;
        syncActivePlayerStatusBag(worldPlayer, battle);
        let speed = currentBattleStat("player", "spd", worldPlayer, battle);
        const contexts = activePlayerCarryContexts(worldPlayer, battle);
        const lagCtx = contexts.find((ctx) => ctx.item.id === "lagging_tail" || battleCarryItemEffect(ctx.item).kind === "move_late_damage_bonus");
        const ctx = contexts.find((entry) => entry.item.id === "quick_claw" || battleCarryItemEffect(entry.item).kind === "quick_action_chance");
        const effect = battleCarryItemEffect(ctx?.item);
        if (lagCtx) return -1;
        if (ctx) {
          if (ctx.state.quickClawRound !== battle.roundIndex) {
            ctx.state.quickClawRound = battle.roundIndex;
            ctx.state.quickClawTriggered = Math.random() < Number(effect.chance || 0.15);
            if (ctx.state.quickClawTriggered) battle.log.push(`${worldLabel}${ctx.card.name}的疾風鉤爪觸發。`);
          }
          if (ctx.state.quickClawTriggered) speed = 9998;
        }
        return speed;
      };
      const playerWorlds = postgameTotUsesPlayerWorlds(battle, mechanic);
      const realPlayer = playerWorlds ? postgameTotActiveWorldPlayer(battle, mechanic, "real") : player;
      const songPlayer = playerWorlds ? postgameTotActiveWorldPlayer(battle, mechanic, "song") : player;
      const worldSpeed = (world, worldPlayer, label) => {
        if (!worldPlayer) return -1;
        if (!playerWorlds) return orderSpeedForIndex(worldPlayer, totMusicaLivingWorldIndex(worldPlayer, mechanic, world, battle), label);
        return withCoopBattleRuntime(worldPlayer, battle, () => {
          const runtime = coopBattleRuntimeFor(worldPlayer, battle, true);
          return orderSpeedForIndex(worldPlayer, livingActiveCrewIndex(worldPlayer, runtime?.activeCrewIndex ?? 0), label);
        }, { save: true });
      };
      const realSpeed = worldSpeed("real", realPlayer, "現實世界・");
      const songSpeed = worldSpeed("song", songPlayer, "歌世界・");
      syncActivePlayerStatusBag(player, battle);
      battle.activeCrewIndex = previousBattleIndex;
      player.activeCrewIndex = previousPlayerIndex;
      syncActivePlayerStatusBag(player, battle);
      const combinedSpeed = Math.max(realSpeed, songSpeed);
      battle.log.push(`雙世界先攻判定：現實世界速度 ${realSpeed}、歌世界速度 ${songSpeed}；同步行動採較快的 ${combinedSpeed}。`);
      return combinedSpeed;
    }
    const base = currentBattleStat(side, "spd", player, battle);
    if (side === "player") {
      const contexts = activePlayerCarryContexts(player, battle);
      const lagCtx = contexts.find((ctx) => ctx.item.id === "lagging_tail" || battleCarryItemEffect(ctx.item).kind === "move_late_damage_bonus");
      const ctx = contexts.find((entry) => entry.item.id === "quick_claw" || battleCarryItemEffect(entry.item).kind === "quick_action_chance");
      const effect = battleCarryItemEffect(ctx?.item);
      if (lagCtx) return -1;
      if (ctx) {
        if (ctx.state.quickClawRound !== battle.roundIndex) {
          ctx.state.quickClawRound = battle.roundIndex;
          ctx.state.quickClawTriggered = Math.random() < Number(effect.chance || 0.15);
          if (ctx.state.quickClawTriggered) battle.log.push(`${ctx.card.name}的疾風鉤爪觸發，搶先行動。`);
        }
        if (ctx.state.quickClawTriggered) return 9998;
      }
    } else {
      if (mechanic?.key === "postgame_douglas_bullet") {
        let quickTriggered = false;
        for (const quickSlot of postgameBossMechanicBulletEffectSlots(battle, "quick_action_chance")) {
          quickSlot.triggered ||= {};
          if (Number(quickSlot.triggered.quickClawRound || 0) !== Number(battle.roundIndex || 0)) {
            quickSlot.triggered.quickClawRound = Number(battle.roundIndex || 0);
            quickSlot.triggered.quickClawTriggered = Math.random() < Number(battleCarryItemEffect(quickSlot.itemId).chance || .15);
            if (quickSlot.triggered.quickClawTriggered) battle.log.push(`巴雷特吸收的${quickSlot.itemName}觸發，搶先行動。`);
          }
          quickTriggered ||= !!quickSlot.triggered.quickClawTriggered;
        }
        if (quickTriggered) return 9998;
        const enemyMove = getMoveByAction("enemy", battle.enemyAction, player, battle);
        if (postgameBossMechanicDirectMove(enemyMove) && postgameBossMechanicBulletEffectSlots(battle, "skip_charge_once").some((slot) => !slot.triggered?.powerHerbUsed)) return 9997;
        if (postgameBossMechanicBulletEffectSlots(battle, "move_late_damage_bonus").length) return -1;
      }
    }
    return base;
  }

  async function resolvePlannedBattleActions(player, battle) {
    if (!battle.playerAction || !battle.enemyAction) return;
    if (battle.yonkoPrompt?.pending) return;
    if (battle.animating) return;
    persistBattleRefreshRecoveryCheckpoint(battle);
    battle.animating = true;
    const playerPriority = getBattleActionPriority("player", battle.playerAction, player, battle);
    const enemyPriority = getBattleActionPriority("enemy", battle.enemyAction, player, battle);
    const playerSpeed = battleSpeedForOrder("player", player, battle);
    const enemySpeed = battleSpeedForOrder("enemy", player, battle);
    const storedOrder = [battle.firstActor, battle.secondActor];
    const hasStoredOrder = storedOrder.includes("player") && storedOrder.includes("enemy") && storedOrder[0] !== storedOrder[1];
    const playerFirst = hasStoredOrder
      ? battle.firstActor === "player"
      : playerPriority > enemyPriority || (playerPriority === enemyPriority && playerSpeed >= enemySpeed);
    battle.firstActor = playerFirst ? "player" : "enemy";
    battle.secondActor = playerFirst ? "enemy" : "player";
    if (!hasStoredOrder) battle.log.push(`第 ${battle.roundIndex} 輪採用 ${playerFirst ? `${player.name}` : "敵人"}先手。`);
    renderBattleInterface();
    await playBattleIntroIfNeeded(player, battle);
    await playOpeningPassiveVisualsIfNeeded(player, battle);
    const firstSide = playerFirst ? "player" : "enemy";
    const secondSide = playerFirst ? "enemy" : "player";
    const sideAlreadyPerformed = (side) => side === "player" ? !!battle.playerPerformedAction : !!battle.enemyPerformedAction;
    if (!sideAlreadyPerformed(firstSide)) await executeBattleAction(firstSide, player, battle);
    if (postgameOarsPurificationInterruptPending(battle)) {
      battle.animating = false;
      battle.roundResolved = false;
      battle.waitingResume = false;
      clearBattleRefreshRecoveryCheckpoint(battle);
      renderBattleInterface();
      notifyBattleWindow();
      return;
    }
    if (battle.result && battle.result !== "round-pause") {
      await playBattleRoundEndAnimation(battle);
      battle.animating = false;
      clearBattleRefreshRecoveryCheckpoint(battle);
      renderBattleInterface();
      return;
    }
    if (playerFirst && !sideAlreadyPerformed(secondSide)) {
      await wait(battle.playerAction?.type === "switch" ? battleAnimationDuration(140) : 1000);
    }
    if (!sideAlreadyPerformed(secondSide)) await executeBattleAction(secondSide, player, battle);
    if (postgameOarsPurificationInterruptPending(battle)) {
      battle.animating = false;
      battle.roundResolved = false;
      battle.waitingResume = false;
      clearBattleRefreshRecoveryCheckpoint(battle);
      renderBattleInterface();
      notifyBattleWindow();
      return;
    }
    if (!battle.result) {
      applyBattleCarryRoundEndEffects(player, battle);
      applyTeamSupportRoundEndHealing(player, battle);
      applyCharacterPassiveRoundEndEffects(player, battle);
      applyFinalGateRoundEnd(player, battle);
      await postgameBossMechanicRoundEnd(player, battle);
      tickDownBattleStatuses(battle);
      tickDownBattleStageTurns(battle);
      triggerRelayPirateFlagRoundEndSwitch(player, battle);
    }
    if (!battle.result) {
      if (isCoopBattle(battle) && battle.__coopSingleActionHandoff) {
        battle.roundResolved = false;
        battle.waitingResume = false;
        battle.log.push("共鬥行動結束，交棒中。");
        battle.animating = false;
        clearBattleRefreshRecoveryCheckpoint(battle);
        return;
      }
      if ((state.gameState.players || []).length === 1) {
        battle.roundResolved = true;
        battle.waitingResume = true;
        battle.log.push("雙方各完成一次行動，單人測試模式直接進入下一輪。");
        await playBattleRoundEndAnimation(battle);
        battle.animating = false;
        clearBattleRefreshRecoveryCheckpoint(battle);
        startBattleRound(player, battle);
        renderBattleInterface();
        return;
      }
      battle.result = "round-pause";
      battle.roundResolved = true;
      battle.waitingResume = true;
      battle.log.push("雙方各完成一次行動，這輪戰鬥暫停。");
    }
    await playBattleRoundEndAnimation(battle);
    battle.animating = false;
    clearBattleRefreshRecoveryCheckpoint(battle);
    scheduleBattleRoundAutoPass(player, battle);
    renderBattleInterface();
  }

  function getMoveByAction(side, action, player, battle) {
    if (!action || action.type !== "move") return null;
    return side === "player"
      ? getUnlockedMoves(battleActiveCard(player, battle)).find((entry) => entry.id === action.moveId)
      : battle.enemyCombatant.moveSet.find((entry) => entry.id === action.moveId);
  }

  function queueCoopBattleAction(player, battle, action) {
    if (!player || !battle || !isCoopBattleParticipant(player, battle)) return false;
    if (warnBoardLanBattleLocked(player, battle)) return false;
    if (battle.yonkoPrompt?.pending || battle.animating || battle.roundResolved || battle.result || coopBattleHandoffPending(battle)) return false;
    const awaitingRescueAction = coopBattleParticipantAwaitingRescue(player, battle)
      && action?.type === "item"
      && action?.rescueUse
      && gameItemDef(action.itemId)?.effect?.kind === "revive"
      && String(action.targetPlayerId || player.id) === String(player.id);
    if (!coopBattleRuntimeAlive(player, battle) && !awaitingRescueAction) {
      battle.log.push(`${player.name} 已無可戰鬥夥伴，不能加入本輪行動。`);
      renderBattleInterface();
      notifyBattleWindow();
      return false;
    }
    battle.coop ||= {};
    const id = String(player.id);
    const queuedAction = safeJsonClone(action);
    queuedAction.playerId = id;
    queuedAction.label = coopBattleActionLabel(queuedAction, player, battle);
    battle.coop.actions = {};
    battle.playerId = player.id;
    battle.playerAction = queuedAction;
    battle.enemyAction = chooseEnemyAction(battle);
    battle.log.push(`${player.name} 行動：${queuedAction.label || "行動"}。`);
    renderBattleInterface();
    notifyBattleWindow();
    scheduleBoardLanStatePush("coop-battle-action", 60, { force: true });
    void resolveCoopSingleBattleAction(player, battle);
    return true;
  }

  async function resolveCoopSingleBattleAction(player, battle) {
    if (!player || !battle || !isCoopBattle(battle) || !isCoopBattleParticipant(player, battle)) return false;
    const plannedPlayerAction = safeJsonClone(battle.playerAction);
    const plannedEnemyAction = safeJsonClone(battle.enemyAction);
    if (!plannedPlayerAction || !plannedEnemyAction) return false;
    if (battle.yonkoPrompt?.pending || battle.animating) return false;
    prepareCoopBattleCommandRuntime(player, battle);
    battle.playerAction = plannedPlayerAction;
    battle.enemyAction = plannedEnemyAction;
    battle.__coopSingleActionHandoff = true;
    try {
      await resolvePlannedBattleActions(player, battle);
    } finally {
      delete battle.__coopSingleActionHandoff;
    }
    finalizeCoopParticipantAfterAction(player, battle);
    saveCoopBattleRuntime(player, battle);
    markImpelDownCoopParticipantActed(player, battle);
    const actorRuntime = coopBattleRuntimeFor(player, battle, false);
    if (!battle.result && coopBattleParticipantAwaitingRescue(player, battle)) {
      clearCoopSingleActionState(battle);
      if (!coopBattleCanStillRecover(battle)) {
        coopBattleParticipants(battle).forEach((participant) => {
          const runtime = coopBattleRuntimeFor(participant, battle, false);
          if (!runtime?.awaitingRescue) return;
          runtime.awaitingRescue = false;
          runtime.rescueTurnsRemaining = 0;
          runtime.defeated = true;
        });
        battle.result = "lose";
        battle.roundResolved = true;
        battle.waitingResume = false;
        battle.log.push("所有共鬥玩家都已倒下，且沒有復活道具可用，戰鬥立即失敗。");
      } else {
        const nextPlayer = coopBattleNextTurnParticipantAfter(player, battle);
        if (nextPlayer) {
          battle.log.push(`共鬥交棒：準備輪到 ${nextPlayer.name} 出手。`);
          scheduleCoopBattleHandoffVisual(nextPlayer, battle, "battle-coop-rescue-handoff", "隊友仍在等待救援。", 60, () => {
            if (state.battleState !== battle) return false;
            return handoffCoopBattleToParticipant(nextPlayer, battle);
          });
        } else {
          battle.result = "round-pause";
          battle.roundResolved = true;
          battle.waitingResume = true;
          battle.log.push(`${player.name} 進入待救援狀態，本輪結束後返回地圖換下一位玩家。`);
          scheduleBattleRoundAutoPass(player, battle);
        }
      }
      renderBattleInterface();
      notifyBattleWindow();
      scheduleBoardLanStatePush("coop-battle-rescue-wait", 80, { force: true });
      return true;
    }
    if (!battle.result && (actorRuntime?.escaped || actorRuntime?.defeated)) {
      clearCoopSingleActionState(battle);
      if (!coopBattleCanStillRecover(battle)) {
        const allEscaped = coopBattleAllParticipantsEscaped(battle);
        battle.result = allEscaped ? "escape" : "lose";
        battle.roundResolved = true;
        battle.waitingResume = false;
        battle.log.push(allEscaped ? "所有共鬥玩家都已成功撤離戰鬥。" : "所有共鬥玩家都無法繼續戰鬥。");
      } else {
        const nextPlayer = coopBattleNextTurnParticipantAfter(player, battle);
        if (nextPlayer) {
          battle.log.push(`共鬥交棒：準備輪到 ${nextPlayer.name} 出手。`);
          scheduleCoopBattleHandoffVisual(nextPlayer, battle, "battle-coop-handoff", "準備選擇戰鬥行動。", 60, () => {
            if (state.battleState !== battle) return false;
            if (!handoffCoopBattleToParticipant(nextPlayer, battle)) return false;
            battle.log.push(`共鬥交棒：輪到 ${nextPlayer.name} 出手。`);
            return true;
          });
        } else {
          battle.result = "round-pause";
          battle.roundResolved = true;
          battle.waitingResume = true;
          battle.log.push("沒有其他共鬥玩家接棒，本輪結束後返回地圖換下一位玩家。");
          scheduleBattleRoundAutoPass(player, battle);
        }
      }
      renderBattleInterface();
      notifyBattleWindow();
      scheduleBoardLanStatePush("coop-battle-single-action", 80, { force: true });
      return true;
    }
    if (battle.needsReplacement || battle.result === "replacement") {
      battle.playerId = player.id;
      battle.roundResolved = false;
      battle.waitingResume = false;
      renderBattleInterface();
      notifyBattleWindow();
      scheduleBattleLanStatePush("battle-replacement-needed", 40);
      return true;
    }
    battle.coop ||= {};
    battle.coop.actions = {};
    if (!battle.result && battle.enemyCombatant?.currentHp <= 0) {
      battle.result = "win";
      battle.roundResolved = true;
      battle.waitingResume = false;
    }
    if (!battle.result && !coopBattleCanStillRecover(battle)) {
      battle.result = "lose";
      battle.roundResolved = true;
      battle.waitingResume = false;
      battle.log.push("所有共鬥玩家都無法繼續戰鬥。");
    }
    if (!battle.result && battle.playerPerformedAction && battle.enemyPerformedAction) {
      const nextPlayer = coopBattleNextTurnParticipantAfter(player, battle);
      if (nextPlayer) {
        battle.log.push(`共鬥交棒：準備輪到 ${nextPlayer.name} 出手。`);
        scheduleCoopBattleHandoffVisual(nextPlayer, battle, "battle-coop-handoff", "準備選擇戰鬥行動。", 60, () => {
          if (state.battleState !== battle) return false;
          if (!handoffCoopBattleToParticipant(nextPlayer, battle)) return false;
          battle.log.push(`共鬥交棒：輪到 ${nextPlayer.name} 出手。`);
          return true;
        });
        return true;
      }
      battle.result = "round-pause";
      battle.roundResolved = true;
      battle.waitingResume = true;
      battle.log.push("沒有其他共鬥玩家接棒，本輪結束後返回地圖換下一位玩家。");
      scheduleBattleRoundAutoPass(player, battle);
    }
    renderBattleInterface();
    notifyBattleWindow();
    scheduleBoardLanStatePush("coop-battle-single-action", 80, { force: true });
    return true;
  }

  function finalizeCoopParticipantAfterAction(player, battle) {
    const runtime = coopBattleRuntimeFor(player, battle, true);
    if (!runtime) return;
    if (battle.result === "coop-rescue-wait") {
      runtime.awaitingRescue = true;
      runtime.rescueTurnsRemaining = Math.max(1, Number(runtime.rescueTurnsRemaining || COOP_RESCUE_WAIT_TURNS));
      runtime.defeated = false;
      runtime.needsReplacement = false;
      runtime.replacementAfterAction = false;
      runtime.playerPerformedAction = false;
      battle.result = "";
      battle.roundResolved = false;
      battle.waitingResume = false;
      battle.needsReplacement = false;
      battle.playerAction = null;
      battle.enemyAction = null;
      battle.coop ||= {};
      battle.coop.actions = {};
      return;
    }
    if (battle.result === "escape") {
      runtime.escaped = true;
      runtime.needsReplacement = false;
      runtime.replacementAfterAction = false;
      runtime.playerPerformedAction = false;
      runtime.pendingEscapeRoll = null;
      runtime.pendingEscapeRollBase = null;
      runtime.pendingEscapeRollBonus = null;
      battle.replacementAfterAction = false;
      battle.log.push(`${player.name} 成功脫離本場共鬥。`);
      battle.result = "";
      battle.roundResolved = false;
      battle.waitingResume = false;
      battle.needsReplacement = false;
      return;
    }
    if (battle.result === "replacement" || battle.needsReplacement) {
      const currentIndex = Math.max(0, Number(battle.activeCrewIndex ?? runtime.activeCrewIndex ?? player.activeCrewIndex ?? 0));
      const survivors = livingCrewIndices(player).filter((index) => index !== currentIndex);
      const replacementAfterAction = !!(
        battle.__coopSingleActionHandoff
        || battle.playerPerformedAction
        || battle.enemyPerformedAction
        || battle.playerAction
        || battle.enemyAction
      );
      if (survivors.length > 0) {
        runtime.needsReplacement = true;
        runtime.activeCrewIndex = currentIndex;
        runtime.replacementAfterAction = replacementAfterAction;
        battle.playerId = player.id;
        battle.activeCrewIndex = currentIndex;
        battle.needsReplacement = true;
        battle.result = "replacement";
        battle.replacementAfterAction = replacementAfterAction;
        battle.roundResolved = false;
        battle.waitingResume = false;
        battle.playerAction = null;
        battle.enemyAction = null;
        battle.coop ||= {};
        battle.coop.actions = {};
        battle.log.push(`${player.name} 的上場夥伴瀕死，請選下一位夥伴上場。`);
        saveCoopBattleRuntime(player, battle);
        return;
      }
      autoResolveCoopBattleReplacement(player, battle);
      battle.waitingResume = false;
      return;
    }
    if (battle.result === "lose") {
      autoResolveCoopBattleReplacement(player, battle);
      battle.waitingResume = false;
    }
  }

  function clearCoopSingleActionState(battle) {
    if (!battle) return;
    battle.coop ||= {};
    battle.coop.actions = {};
    battle.playerAction = null;
    battle.enemyAction = null;
    battle.playerPerformedAction = false;
    battle.enemyPerformedAction = false;
    battle.playerDiceRoll = null;
    battle.enemyDiceRoll = null;
    battle.playerEffectDice = null;
    battle.enemyEffectDice = null;
    battle.playerActionSummary = "";
    battle.enemyActionSummary = "";
    delete battle.__coopQueueRuntime;
  }

  function coopBattleOrderEntry(player, battle) {
    const action = coopBattleActionFor(player, battle);
    return withCoopBattleRuntime(player, battle, () => {
      return {
        player,
        action: safeJsonClone(action),
        priority: getBattleActionPriority("player", action, player, battle),
        speed: battleSpeedForOrder("player", player, battle),
      };
    }, { save: true });
  }

  async function resolveCoopPlannedBattleActions(battle) {
    if (!isCoopBattle(battle) || !coopBattleAllActionsReady(battle)) return;
    if (battle.yonkoPrompt?.pending || battle.animating) return;
    const owner = battlePlayer(null, battle) || coopBattleParticipants(battle)[0];
    if (!owner) return;
    battle.animating = true;
    battle.enemyAction = chooseEnemyAction(battle);
    const plannedEnemyAction = safeJsonClone(battle.enemyAction);
    battle.firstActor = "coop";
    battle.secondActor = "enemy";
    const readyNames = coopBattleLivingParticipants(battle).map((player) => player.name).join("、");
    const enemyMove = getMoveByAction("enemy", battle.enemyAction, owner, battle);
    battle.log.push(`共鬥第 ${battle.roundIndex} 輪開始結算：${readyNames} 全部選好行動。`);
    battle.log.push(`敵方本輪準備使用 ${enemyMove?.name || "技能"}，會一次攻擊所有共鬥玩家。`);
    renderBattleInterface();
    notifyBattleWindow();
    await playBattleIntroIfNeeded(owner, battle);
    await playOpeningPassiveVisualsIfNeeded(owner, battle);

    const orderedPlayers = coopBattleLivingParticipants(battle)
      .map((player) => coopBattleOrderEntry(player, battle))
      .filter((entry) => entry?.action)
      .sort((a, b) => (b.priority - a.priority) || (b.speed - a.speed));

    for (const entry of orderedPlayers) {
      if (battle.enemyCombatant.currentHp <= 0) break;
      const outcome = await withCoopBattleRuntimeAsync(entry.player, battle, async () => {
        battle.playerAction = safeJsonClone(entry.action);
        battle.enemyAction = null;
        battle.result = "";
        battle.roundResolved = false;
        battle.waitingResume = false;
        battle.needsReplacement = false;
        await executeBattleAction("player", entry.player, battle);
        finalizeCoopParticipantAfterAction(entry.player, battle);
        return {
          result: battle.result,
          enemyHp: Number(battle.enemyCombatant.currentHp || 0),
          defeated: !!coopBattleRuntimeFor(entry.player, battle, true)?.defeated,
          escaped: !!coopBattleRuntimeFor(entry.player, battle, true)?.escaped,
        };
      }, { save: true });
      if (outcome?.result === "win" || Number(outcome?.enemyHp || 0) <= 0) {
        battle.result = "win";
        battle.roundResolved = true;
        battle.waitingResume = false;
        break;
      }
      if (postgameOarsPurificationInterruptPending(battle)) {
        battle.animating = false;
        battle.roundResolved = false;
        battle.waitingResume = false;
        renderBattleInterface();
        notifyBattleWindow();
        return;
      }
    }

    if (!battle.result) {
      const enemyAction = safeJsonClone(plannedEnemyAction || battle.enemyAction || chooseEnemyAction(battle));
      const enemyMoveEntry = getMoveByAction("enemy", enemyAction, owner, battle);
      const enemyPpBefore = enemyMoveEntry ? Math.max(1, Number(enemyMoveEntry.currentPP ?? enemyMoveEntry.pp ?? 1)) : 0;
      const enemyPpAfter = enemyMoveEntry ? Math.max(0, enemyPpBefore - 1) : 0;
      const targets = coopBattleLivingParticipants(battle);
      for (const targetPlayer of targets) {
        if (!coopBattleRuntimeAlive(targetPlayer, battle)) continue;
        if (enemyMoveEntry) enemyMoveEntry.currentPP = Math.max(1, enemyPpBefore);
        await withCoopBattleRuntimeAsync(targetPlayer, battle, async () => {
          battle.enemyAction = safeJsonClone(enemyAction);
          battle.playerAction = null;
          battle.result = "";
          battle.roundResolved = false;
          battle.waitingResume = false;
          battle.needsReplacement = false;
          await executeBattleAction("enemy", targetPlayer, battle);
          finalizeCoopParticipantAfterAction(targetPlayer, battle);
          return {
            result: battle.result,
            defeated: !!coopBattleRuntimeFor(targetPlayer, battle, true)?.defeated,
          };
        }, { save: true });
        if (enemyMoveEntry) enemyMoveEntry.currentPP = enemyPpAfter;
      }
    }

    if (!battle.result) {
      coopBattleLivingParticipants(battle).forEach((player) => {
        withCoopBattleRuntime(player, battle, () => {
          applyBattleCarryRoundEndEffects(player, battle);
          applyTeamSupportRoundEndHealing(player, battle);
          applyCharacterPassiveRoundEndEffects(player, battle);
          tickDownStatusBag(battleStatusBag("player", battle));
          tickDownStageTurns(battle.playerStages, battle.playerStageTurns);
        }, { save: true });
      });
      tickDownStatusBag(battle.enemyCombatant?.statuses);
      tickDownStageTurns(battle.enemyCombatant?.stages, battle.enemyCombatant?.stageTurns);
    }

    battle.playerAction = null;
    battle.enemyAction = null;
    battle.coop ||= {};
    battle.coop.actions = {};
    const aliveAfterRound = coopBattleLivingParticipants(battle);
    if (!battle.result && battle.enemyCombatant.currentHp <= 0) {
      battle.result = "win";
    }
    if (!battle.result && !aliveAfterRound.length) {
      const allEscaped = coopBattleAllParticipantsEscaped(battle);
      battle.result = allEscaped ? "escape" : "lose";
      battle.log.push(allEscaped ? "所有共鬥玩家都已成功撤離戰鬥。" : "所有共鬥玩家都無法繼續戰鬥。");
    }
    if (!battle.result) {
      battle.result = "round-pause";
      battle.roundResolved = true;
      battle.waitingResume = true;
      battle.log.push("共鬥本輪結束，戰鬥暫停，返回地圖後換下一位玩家。");
    } else {
      battle.roundResolved = true;
      battle.waitingResume = false;
    }
    await playBattleRoundEndAnimation(battle);
    battle.animating = false;
    renderBattleInterface();
    notifyBattleWindow();
    scheduleBoardLanStatePush("coop-battle-resolved", 80, { force: true });
  }

  function filteredStageMap(stageMap, predicate) {
    return Object.fromEntries(Object.entries(stageMap || {}).filter(([key, value]) => predicate(normalizeBattleStageKey(key), Number(value || 0))));
  }

  function tryAutoSwitchActiveCarry(player, battle, ctx, reasonText) {
    if (!player || !battle || !ctx) return false;
    const nextIndex = livingCrewIndices(player).find((index) => index !== Number(battle.activeCrewIndex || 0));
    if (nextIndex === undefined) return false;
    const fromName = ctx.card?.name || "夥伴";
    const toName = player.crew?.[nextIndex]?.name || "下一名夥伴";
    syncActivePlayerStatusBag(player, battle);
    battle.activeCrewIndex = nextIndex;
    player.activeCrewIndex = nextIndex;
    syncActivePlayerStatusBag(player, battle);
    markBattleCrewParticipation(player, battle, nextIndex);
    battle.playerStages = emptyStages();
    battle.playerStageTurns = emptyStageTurns();
    resetRoundEffects(battle.playerRoundEffects);
    battle.playerAction = null;
    battle.log.push(`${battleCarryItemName(ctx.item)}啟動，${fromName}${reasonText || "撤離不利局面"}，換上${toName}。`);
    return true;
  }

  function applyBattleCarryAwareStageSet(targetSide, targetStages, stageMap, delta, targetStageTurns, duration, player, battle) {
    let nextMap = { ...(stageMap || {}) };
    if (targetSide === "enemy" && postgameBossMechanicFor(battle)?.key === "postgame_douglas_bullet") {
      for (const slot of postgameBossMechanicBulletEffectSlots(battle, "yonko_counter_sun_badge")) {
        const protectedStats = ["spd", "accuracy"];
        const blocked = Object.entries(nextMap).some(([key, value]) => protectedStats.includes(normalizeBattleStageKey(key)) && Number(value || 0) < 0);
        const effect = battleCarryItemEffect(slot.itemId);
        if (blocked && Math.random() < Number(effect.statusResistChance || .35)) {
          nextMap = filteredStageMap(nextMap, (key, value) => !(protectedStats.includes(key) && value < 0));
          battle.log.push(`${slot.itemName}令巴雷特抵抗了速度或命中下降。`);
          break;
        }
      }
    }
    if (targetSide === "player") {
      for (const ctx of activePlayerCarryContexts(player, battle)) {
        const ctxEffect = battleCarryItemEffect(ctx.item);
      if (ctx?.item?.id === "lamp_dial" && !ctx.state?.lampTriggered && Number(nextMap.accuracy || nextMap.acc || 0) < 0) {
        ctx.state.lampTriggered = true;
        delete nextMap.accuracy;
        delete nextMap.acc;
        battle.log.push(`${ctx.card.name}的燈貝照亮視野，抵銷命中下降。`);
      }
      if (ctx?.item?.id === "sky_island_goggles" && !ctx.state?.skyGogglesTriggered) {
        const protectedStats = ["accuracy", "evasion", "spd"];
        const blocked = Object.entries(nextMap).some(([key, value]) => protectedStats.includes(normalizeBattleStageKey(key)) && Number(value || 0) < 0);
        if (blocked) {
          ctx.state.skyGogglesTriggered = true;
          nextMap = filteredStageMap(nextMap, (key, value) => !(protectedStats.includes(key) && value < 0));
          battle.log.push(`${ctx.card.name}的空島護目鏡擋下了能力下降。`);
        }
      }
      if ((ctx?.item?.id === "white_herb" || ctxEffect.kind === "clear_stat_down_once") && !ctx.state?.whiteHerbTriggered) {
        const blocked = Object.entries(nextMap).some(([, value]) => Number(value || 0) < 0);
        if (blocked) {
          ctx.state.whiteHerbTriggered = true;
          nextMap = filteredStageMap(nextMap, (_key, value) => Number(value || 0) >= 0);
          battle.log.push(`${ctx.card.name}的淨化香草清除了能力下降效果。`);
        }
      }
      if (ctx?.item?.id === "sun_pirates_badge" || ctxEffect.kind === "yonko_counter_sun_badge") {
        const protectedStats = ["spd", "accuracy"];
        const blocked = Object.entries(nextMap).some(([key, value]) => protectedStats.includes(normalizeBattleStageKey(key)) && Number(value || 0) < 0);
        if (blocked && Math.random() < Number(ctxEffect.statusResistChance || 0.35)) {
          nextMap = filteredStageMap(nextMap, (key, value) => !(protectedStats.includes(key) && value < 0));
          battle.log.push(`太陽海賊團的徽章發光！${ctx.card.name} 以陽光般的意志抵抗了能力下降。`);
        }
      }
      if ((ctx?.item?.id === "escape_pack" || ctxEffect.kind === "switch_out_when_stat_down_once") && !ctx.state?.escapePackTriggered) {
        const blocked = Object.entries(nextMap).some(([, value]) => Number(value || 0) < 0);
        if (blocked && tryAutoSwitchActiveCarry(player, battle, ctx, "在能力下降前撤退")) {
          ctx.state.escapePackTriggered = true;
          return;
        }
      }
      }
    }
    if (!Object.keys(nextMap).length) return;
    applyStageSet(targetStages, nextMap, delta, targetStageTurns, duration);
  }

  function mirrorEnemyStageBoostWithCarry(stageMap, delta, player, battle) {
    const ctx = activePlayerCarryContexts(player, battle).find((entry) => entry.item.id === "vision_dial" && !entry.state?.visionTriggered);
    if (!ctx) return;
    const entry = Object.entries(stageMap || {}).find(([, value]) => Number(value || 0) > 0);
    if (!entry) return;
    const [stat, value] = entry;
    const normalized = normalizeBattleStageKey(stat);
    const boost = Math.max(1, Number(value || 0) + Math.max(0, Number(delta || 0)));
    ctx.state.visionTriggered = true;
    applyStageSet(battle.playerStages, { [normalized]: boost }, 0, battle.playerStageTurns, 3);
    battle.log.push(`${ctx.card.name}的影像貝記錄敵方強化，複製了${signedStageLabel(normalized, boost)}。`);
  }

  function applyStageSet(targetStages, stageMap, delta, targetStageTurns = null, duration = 3) {
    Object.entries(stageMap || {}).forEach(([key, value]) => {
      const normalized = normalizeBattleStageKey(key);
      const baseValue = Number(value || 0);
      const adjustedValue = baseValue + Math.sign(baseValue) * Number(delta || 0);
      targetStages[normalized] = Math.max(-BATTLE_STAGE_LIMIT, Math.min(BATTLE_STAGE_LIMIT, (targetStages[normalized] || 0) + adjustedValue));
      if (targetStageTurns) targetStageTurns[normalized] = 0;
    });
  }

  function attackDiceMultiplier(face) {
    const value = Number(face) || 1;
    if (value <= 6) return { 1: 0.85, 2: 0.95, 3: 1, 4: 1.1, 5: 1.2, 6: 1.35 }[value] || 1;
    if (value <= 11) return 1.35 + (value - 6) * 0.12;
    return Math.min(2.95, 2.05 + (value - 12) * 0.15);
  }

  function battleAttackDiceMultiplier(side, face) {
    const value = Number(face) || 1;
    if (side !== "enemy" || value <= 6) return attackDiceMultiplier(value);
    return Math.min(1.62, 1.35 + (value - 6) * 0.04);
  }

  function healDiceMultiplier(face) {
    const value = Number(face) || 1;
    if (value <= 6) return { 1: 0.8, 2: 0.9, 3: 1, 4: 1.1, 5: 1.2, 6: 1.35 }[value] || 1;
    return Math.min(2.05, 1.35 + (value - 6) * 0.12);
  }

  function moveSearchText(moveEntry = {}) {
    return `${moveEntry.name || ""} ${moveEntry.category || ""} ${moveEntry.type || ""} ${moveEntry.attribute || ""} ${moveEntry.effectText || ""}`.toLowerCase();
  }

  function isShootingBattleMove(moveEntry) {
    return /射|狙|銃|槍|彈|弹|砲|炮|子彈|火藥|星|鐳射|雷射|laser|gun|bullet|shot|shoot|snipe/.test(moveSearchText(moveEntry));
  }

  function isFireBattleMove(moveEntry) {
    return /火|炎|燃|燒|灼|熔|岩漿|爆炸|flame|fire|burn/.test(moveSearchText(moveEntry));
  }

  function isWaterBattleMove(moveEntry) {
    return /水|海流|魚人|波|潮|雨|泡|water|aqua/.test(moveSearchText(moveEntry));
  }

  function isSoundBattleMove(moveEntry) {
    return /音|聲|吼|歌|笛|回音|音波|sonic|sound|voice/.test(moveSearchText(moveEntry));
  }

  function battleMoveHitChance(side, moveEntry, player, battle) {
    const attackerStages = side === "player" ? battle.playerStages : battle.enemyCombatant?.stages;
    const defenderStages = side === "player" ? battle.enemyCombatant?.stages : battle.playerStages;
    const base = Number(moveEntry?.accuracy ?? 100);
    let chance = base
      + Number(attackerStages?.accuracy || 0) * 8
      - Number(defenderStages?.evasion || 0) * 8;
    if (side === "player") {
      chance += Math.max(0, Number(battle.enemyCombatant?.intrinsicEvasionPenalty || 0));
      activePlayerCarryContexts(player, battle).forEach((ctx) => {
        const itemId = ctx.item?.id || "";
        if (itemId === "justice_cloak" && battle.enemyCombatant?.isDevilFruitUser) chance += 8;
        if (itemId === "sniper_king_goggles") chance += 8;
        if (itemId === "log_pose") chance += battle.enemyCombatant?.isDevilFruitUser ? 8 : 4;
        if (itemId === "eternal_pose" && ctx.state?.permanentPointerPrimed) chance += 16;
        if (itemId === "devon_kyubi_mask" && Number(battle.enemyCombatant?.stages?.evasion || 0) > 0 && ctx.state?.devonGeneralRound !== Number(battle.roundIndex || 0)) chance += 8;
      });
      chance += characterPassiveHitChanceBonus(side, moveEntry, player, battle);
      if (isYonkoBattleKey(battle, "yonko_blackbeard") && blackbeardActiveDarkState(player, battle).stacks >= 2) chance -= 8;
      const bullet = postgameBossMechanicFor(battle);
      if (bullet?.key === "postgame_douglas_bullet") {
        postgameBossMechanicBulletEffectSlots(battle, "incoming_accuracy_down").forEach((slot) => {
          chance -= Math.round(Number(battleCarryItemEffect(slot.itemId).value || .05) * 100);
        });
      }
      const activeLucciPower = postgameBossMechanicActiveLucciPower(battle);
      if (activeLucciPower?.stat === "evasion") chance /= POSTGAME_LUCCI_POWER_MULTIPLIER;
    } else {
      activePlayerCarryContexts(player, battle).forEach((ctx) => {
        const effect = battleCarryItemEffect(ctx.item);
        if (effect.kind === "incoming_accuracy_down") chance -= Math.round(Number(effect.value || 0) * 100);
        else if (ctx.item?.id === "bright_powder") chance -= 5;
      });
      chance += postgameBossMechanicEnemyHitChanceBonus(moveEntry, battle);
    }
    const minimum = side === "enemy"
      ? Math.max(0, Math.min(100, Number(battle.enemyCombatant?.minimumHitChance ?? 55)))
      : 55;
    return Math.max(minimum, Math.min(100, Math.round(chance)));
  }

  function battleMoveHits(side, moveEntry, player, battle) {
    const mechanic = postgameBossMechanicFor(battle);
    if (side === "enemy" && mechanic?.key === "postgame_rob_lucci_awakened" && moveEntry?.id === "postgame_lucci_ultimate_rokuogan") {
      return { chance: 100, hit: true, guaranteed: true };
    }
    const chance = battleMoveHitChance(side, moveEntry, player, battle);
    if (side === "enemy" && postgameBossMechanicDirectMove(moveEntry)) {
      const card = battleActiveCard(player, battle);
      const index = Number(battle?.activeCrewIndex ?? player?.activeCrewIndex ?? 0);
      const raidSuitState = sanjiRaidSuitFormState(card, player, battle, index, false);
      if (sanjiRaidSuitTransformed(card, player, battle, index) && raidSuitState?.stealthReady) {
        raidSuitState.stealthReady = false;
        battle.log.push(`${sanjiRaidSuitDisplayName(card, player, battle, index)}啟動光學迷彩，${moveEntry.name}失去目標而落空。`);
        return { chance: 0, hit: false, raidSuitStealth: true };
      }
      const moguraOverride = resolvePlayerMoguraHitOverride(moveEntry, player, battle);
      if (moguraOverride) return moguraOverride;
    }
    if (side === "player" && mechanic?.key === "postgame_douglas_bullet" && postgameBossMechanicDirectMove(moveEntry)) {
      const card = battleActiveCard(player, battle);
      const crewKey = postgameBossMechanicCrewKey(card, battle.activeCrewIndex);
      mechanic.bulletLastPlayerDirectMoves ||= {};
      mechanic.bulletLastPlayerActionWasDirect ||= {};
      const moguraSlot = postgameBossMechanicBulletEffectSlots(battle, "postgame_katakuri_mogura")
        .find((slot) => !slot.triggered?.moguraTriggered);
      if (moguraSlot && mechanic.bulletLastPlayerActionWasDirect[crewKey] && mechanic.bulletLastPlayerDirectMoves[crewKey] === moveEntry.id) {
        moguraSlot.triggered ||= {};
        moguraSlot.triggered.moguraTriggered = true;
        const effect = battleCarryItemEffect(moguraSlot.itemId);
        const before = Math.max(0, Number(card?.currentHp || 0));
        const counter = Math.min(before, Math.max(1, Math.round(cardMaxHp(card) * Number(effect.counterMaxHpRatio || .4))));
        if (card) card.currentHp = Math.max(0, before - counter);
        battle.log.push(`${moguraSlot.itemName}看穿重複招式，使 ${moveEntry.name} 必定落空並反擊 ${counter} 點傷害。`);
        return { chance: 0, hit: false, bulletMogura: true };
      }
      mechanic.bulletLastPlayerActionWasDirect[crewKey] = true;
      mechanic.bulletLastPlayerDirectMoves[crewKey] = moveEntry.id;
    }
    return { chance, hit: chance >= 100 || Math.random() * 100 < chance };
  }

  function playerCarryContextsForIndex(player, battle, index) {
    const resolvedIndex = Math.max(0, Number(index || 0));
    const card = player?.crew?.[resolvedIndex] || null;
    if (!card || postgameBulletCarryIsAbsorbed(battle, card, resolvedIndex)) return [];
    return battleCarryEquippedEntriesForCard(card).map(({ item, slotIndex, container }) => ({
      card,
      index: resolvedIndex,
      item,
      def: battleCarryItemDef(item),
      state: battleCarryStateForEquippedItem(card, resolvedIndex, item, battle, true, slotIndex),
      slotIndex,
      container,
    })).filter((ctx) => ctx.def);
  }

  function playerCarryContextForIndex(player, battle, index) {
    return playerCarryContextsForIndex(player, battle, index)[0] || null;
  }

  function activePlayerCarryContext(player, battle) {
    return playerCarryContextForIndex(player, battle, Number(battle?.activeCrewIndex || 0));
  }

  function activePlayerCarryContexts(player, battle) {
    return playerCarryContextsForIndex(player, battle, Number(battle?.activeCrewIndex || 0));
  }

  function playerBattleCarryIgnoreDefenseRatio(moveEntry, player, battle) {
    if (!postgameBossMechanicDirectMove(moveEntry)) return 0;
    let remainingDefense = 1;
    activePlayerCarryContexts(player, battle).forEach((ctx) => {
      const effect = battleCarryItemEffect(ctx.item);
      if (effect.kind !== "postgame_zephyr_battle_smasher" || !ctx.state?.battleSmasherReady) return;
      remainingDefense *= 1 - Math.max(0, Math.min(.85, Number(effect.ignoreDefenseRatio || .2)));
    });
    return Math.max(0, Math.min(.85, 1 - remainingDefense));
  }

  function applyPlayerCarryComboProgression(hitDamages, side, moveEntry, player, battle) {
    if (side !== "player" || !Array.isArray(hitDamages) || hitDamages.length <= 1 || !isComboBattleMove(moveEntry)) return hitDamages;
    const scores = activePlayerCarryContexts(player, battle)
      .map((ctx) => ({ ctx, effect: battleCarryItemEffect(ctx.item) }))
      .filter(({ effect }) => effect.kind === "postgame_tot_musica_demon_score");
    if (!scores.length) return hitDamages;
    return hitDamages.map((damage, index) => {
      let adjusted = Math.max(0, Number(damage || 0));
      scores.forEach(({ effect }) => {
        adjusted *= 1 + Math.max(0, Number(effect.firstHitBonus || .01)) * (2 ** index);
      });
      return Math.max(0, Math.round(adjusted));
    });
  }

  function preparePlayerMoguraForEnemyMove(moveEntry, player, battle) {
    const direct = postgameBossMechanicDirectMove(moveEntry);
    activePlayerCarryContexts(player, battle).forEach((ctx) => {
      const effect = battleCarryItemEffect(ctx.item);
      if (effect.kind !== "postgame_katakuri_mogura" || !ctx.state) return;
      const repeated = direct
        && !ctx.state.moguraTriggered
        && ctx.state.moguraLastEnemyActionDirect
        && String(ctx.state.moguraLastEnemyMoveId || "") === String(moveEntry?.id || "");
      ctx.state.moguraPendingCounter = repeated;
      ctx.state.moguraLastEnemyActionDirect = direct;
      ctx.state.moguraLastEnemyMoveId = direct ? String(moveEntry?.id || "") : "";
    });
  }

  function resolvePlayerMoguraHitOverride(moveEntry, player, battle) {
    const ctx = activePlayerCarryContexts(player, battle).find((entry) => (
      battleCarryItemEffect(entry.item).kind === "postgame_katakuri_mogura"
      && entry.state?.moguraPendingCounter
      && !entry.state?.moguraTriggered
    ));
    if (!ctx) return null;
    ctx.state.moguraPendingCounter = false;
    ctx.state.moguraTriggered = true;
    const effect = battleCarryItemEffect(ctx.item);
    const before = Math.max(0, Number(battle.enemyCombatant?.currentHp || 0));
    const counter = Math.min(before, Math.max(1, Math.round(Number(battle.enemyCombatant?.maxHp || 1) * Number(effect.counterMaxHpRatio || .4))));
    battle.enemyCombatant.currentHp = Math.max(0, before - counter);
    battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}看穿連續同招，使 ${moveEntry.name} 必定落空並反擊 ${counter} 點傷害。`);
    return { chance: 0, hit: false, moguraCounter: true, moguraCounterDamage: counter };
  }

  function applyPlayerCarryAfterDirectAction(side, moveEntry, didHit, actualDamage, diceFace, player, battle) {
    if (side !== "player" || !postgameBossMechanicDirectMove(moveEntry)) return;
    const contexts = activePlayerCarryContexts(player, battle).filter((ctx) => ctx.state);
    contexts.forEach((ctx) => {
      const effect = battleCarryItemEffect(ctx.item);
      if (effect.kind === "postgame_tesoro_gold_rings" && didHit && Number(actualDamage || 0) > 0 && !ctx.state.goldRingsTriggered) {
        ctx.state.goldStacks = Math.min(Number(effect.requiredStacks || 3), Number(ctx.state.goldStacks || 0) + 1);
        battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}累積黃金 ${ctx.state.goldStacks}/${Number(effect.requiredStacks || 3)}。`);
        if (ctx.state.goldStacks >= Number(effect.requiredStacks || 3)) {
          ctx.state.goldRingsTriggered = true;
          applyBattleStatus("enemy", battle, "bind", Number(effect.bindTurns || 1));
          applyStageSet(battle.enemyCombatant.stages, effect.enemyStages || { def: -1, sdef: -1 }, 0, battle.enemyCombatant.stageTurns, 99);
          battle.log.push(`三層黃金完成，敵人束縛一回合，防禦與特防各下降一階並持續整場。`);
        }
      }
      if (effect.kind === "postgame_zephyr_battle_smasher") {
        if (ctx.state.battleSmasherReady) {
          ctx.state.battleSmasherReady = false;
          ctx.state.battleSmasherHeat = 0;
          const recoil = Math.max(1, Math.round(cardMaxHp(ctx.card) * Number(effect.recoilMaxHp || .3)));
          const beforeHp = Math.max(1, Number(ctx.card.currentHp || 1));
          ctx.card.currentHp = Math.max(1, beforeHp - recoil);
          battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}${didHit ? "釋放" : "落空仍消耗"}過熱爆發，反噬 ${Math.max(0, beforeHp - ctx.card.currentHp)} HP，最低保留 1 HP。`);
        } else if (didHit) {
          ctx.state.battleSmasherHeat = Math.min(Number(effect.requiredHeat || 3), Number(ctx.state.battleSmasherHeat || 0) + 1);
          if (ctx.state.battleSmasherHeat >= Number(effect.requiredHeat || 3)) ctx.state.battleSmasherReady = true;
          battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}熱量 ${ctx.state.battleSmasherHeat}/${Number(effect.requiredHeat || 3)}${ctx.state.battleSmasherReady ? "，下次直接攻擊爆發" : ""}。`);
        }
      }
      if (effect.kind === "postgame_redfield_umbrella_sword" && didHit && Number(actualDamage || 0) > 0) {
        const recovery = Math.max(1, Math.round(Number(actualDamage || 0) * Number(effect.drainRatio || .2)));
        const beforeHp = Math.max(0, Number(ctx.card.currentHp || 0));
        const maxHp = cardMaxHp(ctx.card);
        const healed = Math.min(Math.max(0, maxHp - beforeHp), recovery);
        ctx.card.currentHp = Math.min(maxHp, beforeHp + healed);
        const overflow = recovery - healed;
        if (overflow > 0) {
          const cap = Math.max(1, Math.round(maxHp * Number(effect.maxOverflowShieldRatio || .15)));
          ctx.state.redfieldOverflowShield = Math.min(cap, Number(ctx.state.redfieldOverflowShield || 0) + overflow);
        }
        battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}吸收整招傷害，回復 ${healed} HP${overflow > 0 ? `，溢出護盾 ${Math.round(ctx.state.redfieldOverflowShield || 0)}` : ""}。`);
      }
      if (effect.kind === "postgame_loki_ragnir" && didHit && Number(actualDamage || 0) > 0) {
        ctx.state.ragnirClouds = Math.min(Number(effect.freezeClouds || 3), Number(ctx.state.ragnirClouds || 0) + 1);
        if (ctx.state.ragnirClouds >= Number(effect.freezeClouds || 3)) {
          const label = applyBattleStatus("enemy", battle, "freeze", Number(effect.freezeTurns || 1));
          if (effect.clearCloudsAfterFreeze !== false) ctx.state.ragnirClouds = 0;
          battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}生成第三朵冰雲，${label ? `使敵人陷入${label}` : "發動凍結"}，冰雲歸零。`);
        } else {
          battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}產生冰雲 ${ctx.state.ragnirClouds}/${Number(effect.freezeClouds || 3)}。`);
        }
      }
      if (effect.kind === "postgame_king_sword" && ctx.state.kingFlameOn === false) {
        ctx.state.kingFlameOn = true;
        battle.log.push(`${ctx.card.name}完成直接攻擊，${battleCarryItemName(ctx.item)}重新點燃背火。`);
      }
    });
  }

  function tryPlayerBattleCarryRevive(player, battle, card = battleActiveCard(player, battle)) {
    if (!card || Number(card.currentHp || 0) > 0) return false;
    const ctx = activePlayerCarryContexts(player, battle).find((entry) => {
      const effect = battleCarryItemEffect(entry.item);
      return effect.kind === "postgame_green_bull_life_seed"
        && !entry.state?.greenBullReviveUsed
        && Number(entry.state?.greenBullSeeds || 0) > 0;
    });
    if (!ctx) return false;
    const effect = battleCarryItemEffect(ctx.item);
    const seeds = Math.max(1, Math.min(Number(effect.maxSeeds || 3), Number(ctx.state.greenBullSeeds || 0)));
    ctx.state.greenBullSeeds = 0;
    ctx.state.greenBullReviveUsed = true;
    card.currentHp = Math.max(1, Math.round(cardMaxHp(card) * seeds * Number(effect.revivePerSeed || .12)));
    battle.log.push(`${card.name}的${battleCarryItemName(ctx.item)}消耗 ${seeds} 顆種子，以 ${Math.round(seeds * Number(effect.revivePerSeed || .12) * 100)}% 最大 HP 復活；本場不可再次復活。`);
    return true;
  }

  function devilFruitSuppressorActive(carryEffect, battle) {
    return carryEffect?.kind === "devil_fruit_suppressor" && battleEnemyIsDevilFruitUser(battle);
  }

  function applyOffensiveDevilFruitSuppressor(damage, ctx, battle, attackerCard) {
    const carryEffect = battleCarryItemEffect(ctx?.item);
    if (!devilFruitSuppressorActive(carryEffect, battle)) return damage;
    const nextDamage = Math.max(1, Math.round(Number(damage || 0) * (1 + Number(carryEffect.damageBonus || 0.2))));
    if (ctx?.state && !ctx.state.seastoneHandcuffsDamageLogged) {
      ctx.state.seastoneHandcuffsDamageLogged = true;
      battle.log.push(`${cardDisplayName(attackerCard)}的${battleCarryItemName(ctx.item)}壓制能力者，傷害提升。`);
    }
    return nextDamage;
  }

  function applyDefensiveBattleCarryBeforeDamage(defenderSide, damage, player, battle, visualMeta = null) {
    if (defenderSide !== "player" || damage <= 0) return damage;
    const contexts = activePlayerCarryContexts(player, battle);
    if (!contexts.length) return damage;
    let nextDamage = Math.max(1, Math.round(damage));
    const incomingMove = getMoveByAction("enemy", battle.enemyAction, player, battle);
    const incomingDirect = postgameBossMechanicDirectMove(incomingMove);
    if (incomingDirect) {
      contexts.forEach((ctx) => {
        const carryEffect = battleCarryItemEffect(ctx.item);
        if (carryEffect.kind === "postgame_shiki_oto_kogarashi" && !ctx.state?.shikiFirstGuardUsed) {
          ctx.state.shikiFirstGuardUsed = true;
          const reduction = Math.max(0, Math.min(.9, Number(carryEffect.firstDirectDamageReduction || .4)));
          nextDamage = Math.max(1, Math.round(nextDamage * (1 - reduction)));
          battle.log.push(`${ctx.card.name}以${battleCarryItemName(ctx.item)}擋下第一次直接攻擊，整招傷害降低 ${Math.round(reduction * 100)}%。`);
        }
        if (carryEffect.kind === "postgame_king_sword" && ctx.state?.kingFlameOn !== false) {
          const reduction = Math.max(0, Math.min(.9, Number(carryEffect.flameDamageReduction || .25)));
          nextDamage = Math.max(1, Math.round(nextDamage * (1 - reduction)));
          ctx.state.kingFlameOn = false;
          battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}以背火降低 ${Math.round(reduction * 100)}% 傷害，受擊後熄火。`);
        }
      });
    }
    for (const ctx of contexts) {
      const carryEffect = battleCarryItemEffect(ctx.item);
    if (devilFruitSuppressorActive(carryEffect, battle)) {
      nextDamage = Math.max(1, Math.round(nextDamage * (1 - Number(carryEffect.damageReduction || 0.2))));
      if (!ctx.state?.seastoneHandcuffsGuardLogged) {
        ctx.state.seastoneHandcuffsGuardLogged = true;
        battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}鎖住能力者攻勢，傷害降低。`);
      }
    }
    if (ctx.item.id === "vegapunk_mini_shield" && Number(ctx.state?.vegapunkShield || 0) > 0) {
      const absorbed = Math.min(nextDamage, Math.max(0, Math.round(Number(ctx.state.vegapunkShield || 0))));
      ctx.state.vegapunkShield = Math.max(0, Math.round(Number(ctx.state.vegapunkShield || 0)) - absorbed);
      nextDamage = Math.max(0, nextDamage - absorbed);
      battle.log.push(`${ctx.card.name}的貝加龐克小型護盾吸收了 ${absorbed} 傷害。`);
      if (nextDamage <= 0) return 0;
    }
    if (carryEffect.kind === "postgame_redfield_umbrella_sword" && Number(ctx.state?.redfieldOverflowShield || 0) > 0) {
      const absorbed = Math.min(nextDamage, Math.max(0, Math.round(Number(ctx.state.redfieldOverflowShield || 0))));
      ctx.state.redfieldOverflowShield = Math.max(0, Math.round(Number(ctx.state.redfieldOverflowShield || 0)) - absorbed);
      nextDamage = Math.max(0, nextDamage - absorbed);
      battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}溢出護盾吸收 ${absorbed} 傷害。`);
      if (nextDamage <= 0) return 0;
    }
    if (carryEffect.kind === "immune_first_skill_tag_once" && !ctx.state?.airBalloonTriggered) {
      const tags = carryEffect.tags || [];
      const moveText = moveSearchText(incomingMove);
      const matched = tags.some((tag) => new RegExp(tag === "quake" ? "震|地震|quake" : `${tag}|地|ground`, "i").test(moveText));
      if (matched) {
        ctx.state.airBalloonTriggered = true;
        battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}托起身體，免疫了這次地面衝擊。`);
        return 0;
      }
    }
    if (carryEffect.kind === "reduce_first_hit_damage" && !ctx.state?.cloudTriggered) {
      ctx.state.cloudTriggered = true;
      const reduction = Math.max(0, Math.min(0.9, Number(carryEffect.reduction || 0.25)));
      nextDamage = Math.max(1, Math.round(nextDamage * (1 - reduction)));
      battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}展開防護，傷害降低 ${Math.round(reduction * 100)}%。`);
    } else if ((ctx.item.id === "cloud_dial" || ctx.item.id === "cloud_shell") && !ctx.state?.cloudTriggered) {
      ctx.state.cloudTriggered = true;
      const reduction = ctx.item.id === "cloud_shell" ? 0.3 : 0.25;
      nextDamage = Math.max(1, Math.round(nextDamage * (1 - reduction)));
      battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}展開雲壁，傷害降低 ${Math.round(reduction * 100)}%。`);
    }
    if (ctx.item.id === "flash_dial" && !ctx.state?.flashTriggered) {
      ctx.state.flashTriggered = true;
      applyStageSet(battle.enemyCombatant.stages, { accuracy: -1 }, 0, battle.enemyCombatant.stageTurns, 3);
      battle.log.push(`${ctx.card.name}的閃光貝爆出強光，敵方命中下降。`);
    }
    if (ctx.item.id === "justice_cloak") {
      nextDamage = Math.max(1, Math.round(nextDamage * 0.92));
      battle.log.push(`正義的披風發動，${ctx.card.name}受到的傷害降低 8%。`);
    }
    if (carryEffect.kind === "speed_down_damage_reduction") {
      const reduction = Math.max(0, Math.min(0.8, Number(carryEffect.reduction || 0.12)));
      nextDamage = Math.max(1, Math.round(nextDamage * (1 - reduction)));
      battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}穩住身形，傷害降低 ${Math.round(reduction * 100)}%。`);
    }
    if (ctx.item.id === "water_dial" && isFireBattleMove(getMoveByAction("enemy", battle.enemyAction, player, battle))) {
      nextDamage = Math.max(1, Math.round(nextDamage * 0.8));
      battle.log.push(`${ctx.card.name}的水貝噴出水幕，火系傷害降低。`);
    }
    if (ctx.item.id === "iron_cloud") {
      nextDamage = Math.max(1, Math.round(nextDamage * 0.9));
      battle.log.push(`${ctx.card.name}的鐵雲承受衝擊，傷害降低 10%。`);
    }
    if (ctx.item.id === "opal_cloud" && Number(battle.playerRoundEffects?.shieldRatio || 0) > 0) {
      nextDamage = Math.max(1, Math.round(nextDamage * 0.9));
      battle.log.push(`${ctx.card.name}的蛋白石雲強化護盾，額外降低傷害。`);
    }
    if (carryEffect.kind === "boost_when_hit_by_weakness" && !ctx.state?.weaknessPolicyTriggered) {
      const enemyAttribute = battle.enemyCombatant?.attribute;
      const playerAttribute = ctx.card?.attribute;
      if (enemyAttribute && playerAttribute && attributeModifier(enemyAttribute, playerAttribute, 1) > 1) {
        ctx.state.weaknessPolicyTriggered = true;
        applyStageSet(battle.playerStages, carryEffect.statStages || { atk: 2, satk: 2 }, 0, battle.playerStageTurns, 3);
        battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}啟動，攻擊能力大幅提升。`);
      }
    }
    const maxHp = cardMaxHp(ctx.card);
    const beforeHp = Math.max(0, Number(ctx.card.currentHp || 0));
    if (carryEffect.kind === "postgame_judge_germa66_suit" && !ctx.state?.judgeFatalUsed && nextDamage >= beforeHp) {
      ctx.state.judgeFatalUsed = true;
      const reduction = Math.max(0, Math.min(1, Number(carryEffect.fatalDamageReduction ?? 1)));
      nextDamage = Math.max(0, Math.round(nextDamage * (1 - reduction)));
      applyStageSet(battle.playerStages, carryEffect.selfStages || { def: 1, spd: 1 }, 0, battle.playerStageTurns, 99);
      markBattleFatalGuardVisual(visualMeta, battleCarryItemName(ctx.item));
      battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}發動「不屈」，完全抵銷致命傷，防禦與速度提升。`);
    }
    if ((ctx.item.id === "life_paper" || ctx.item.id === "focus_sash" || carryEffect.kind === "survive_fatal_once_if_full_hp") && !ctx.state?.lifePaperTriggered && beforeHp >= maxHp && nextDamage >= beforeHp) {
      ctx.state.lifePaperTriggered = true;
      nextDamage = Math.max(0, beforeHp - 1);
      battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}發動，勉強保留 1 HP。`);
    }
    if (carryEffect.kind === "fatal_rescue_heal_once" && !ctx.state?.merryRescueTriggered && nextDamage >= beforeHp) {
      ctx.state.merryRescueTriggered = true;
      ctx.state.merryRescuePendingHealPercent = Number(carryEffect.healPercent || 0.5);
      nextDamage = Math.max(0, beforeHp - Math.max(1, Math.round(Number(carryEffect.hpLeft || 1))));
      battle.log.push(`${ctx.card.name}聽見梅利號的呼喚，撐住了致命傷。`);
    }
    const surviveChance = carryEffect.kind === "survive_fatal_chance" ? Number(carryEffect.chance || 0.2) : 0.2;
      if ((ctx.item.id === "focus_band" || carryEffect.kind === "survive_fatal_chance") && ctx.state.focusBandRound !== battle.roundIndex && nextDamage >= beforeHp && Math.random() < surviveChance) {
      ctx.state.focusBandRound = battle.roundIndex;
      nextDamage = Math.max(0, beforeHp - 1);
      battle.log.push(`${ctx.card.name}的不屈頭巾讓角色硬撐了下來。`);
      }
    }
    return nextDamage;
  }

  function storeBattleCarryDamageAfterHit(defenderSide, actualDamage, player, battle) {
    if (defenderSide !== "player" || actualDamage <= 0) return;
    activePlayerCarryContexts(player, battle).forEach((ctx) => {
      if (!ctx.state) return;
      const carryEffect = battleCarryItemEffect(ctx.item);
      const ratios = { impact_dial: 0.3, reject_dial: 0.7, impact_shell: 0.3, reject_shell: 0.7 };
      const ratio = carryEffect.kind === "store_damage_counter" ? Number(carryEffect.storeRate || 0) : ratios[ctx.item.id];
      if (ratio && Number(ctx.state.storedDamage || 0) <= 0) {
        const storedDamage = Math.max(1, Math.round(Number(actualDamage || 0) * ratio));
        ctx.state.storedDamage = storedDamage;
        battle.log.push(`${ctx.card.name}的${ctx.def.name}儲存了 ${storedDamage} 傷害。`);
      }
      if (ctx.item.id === "slash_dial" && ctx.state.slashReflectedRound !== battle.roundIndex) {
        const reflectDamage = Math.max(1, Math.round(Number(actualDamage || 0) * 0.12));
        ctx.state.slashReflectedRound = battle.roundIndex;
        battle.enemyCombatant.currentHp = Math.max(0, Number(battle.enemyCombatant.currentHp || 0) - reflectDamage);
        battle.log.push(`${ctx.card.name}的斬擊貝反彈 ${reflectDamage} 傷害。`);
      }
      if (carryEffect.kind === "reflect_damage_on_melee_hit") {
        const enemyMove = getMoveByAction("enemy", battle.enemyAction, player, battle);
        const skillKey = `${battle.roundIndex}:${enemyMove?.id || "attack"}`;
      const isMelee = !isShootingBattleMove(enemyMove) && (enemyMove?.category || enemyMove?.type || "attack") !== "special";
      if (isMelee && ctx.state.rockyHelmetSkillKey !== skillKey) {
        ctx.state.rockyHelmetSkillKey = skillKey;
        const reflectDamage = Math.max(1, Math.round(Number(battle.enemyCombatant.maxHp || 1) * Number(carryEffect.attackerMaxHpPercent || 0.08)));
        battle.enemyCombatant.currentHp = Math.max(0, Number(battle.enemyCombatant.currentHp || 0) - reflectDamage);
        battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}刺傷攻擊者，反彈 ${reflectDamage} 傷害。`);
      }
      }
      if (carryEffect.kind === "record_first_single_target_skill_then_counter" && !ctx.state.visionShellTriggered) {
        ctx.state.visionShellTriggered = true;
        const counterDamage = Math.max(1, Math.round(Number(actualDamage || 0) * Number(carryEffect.counterPowerRate || 0.5)));
        battle.enemyCombatant.currentHp = Math.max(0, Number(battle.enemyCombatant.currentHp || 0) - counterDamage);
        battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}記錄敵招並反擊 ${counterDamage} 傷害。`);
      }
      if (carryEffect.kind === "force_attacker_switch_once" && !ctx.state.redCardTriggered) {
        ctx.state.redCardTriggered = true;
        applyStageSet(battle.enemyCombatant.stages, { spd: -1, accuracy: -1 }, 0, battle.enemyCombatant.stageTurns, 2);
        battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}造成混亂，敵方速度與命中下降。`);
      }
      if (carryEffect.kind === "switch_out_after_hit_once" && !ctx.state.ejectTriggered && Number(ctx.card.currentHp || 0) > 0) {
        ctx.state.ejectTriggered = true;
        tryAutoSwitchActiveCarry(player, battle, ctx, "受傷後退到後方");
      }
      if (Number(ctx.state.merryRescuePendingHealPercent || 0) > 0) {
        const healPercent = Number(ctx.state.merryRescuePendingHealPercent || 0.5);
        ctx.state.merryRescuePendingHealPercent = 0;
        const healed = healBattleTarget(ctx.card, healPercent);
        if (healed > 0) battle.log.push(`${battleCarryItemName(ctx.item)}趕到救援，${ctx.card.name}回復 ${healed} HP。`);
      }
    });
    applyPlayerHpThresholdBattleCarryEffects(player, battle);
  }

  function applyPlayerHpThresholdBattleCarryEffects(player, battle) {
    const contexts = activePlayerCarryContexts(player, battle);
    if (!contexts.length || Number(contexts[0].card.currentHp || 0) <= 0) return;
    contexts.forEach((ctx) => {
      if (!ctx.state) return;
      const maxHp = cardMaxHp(ctx.card);
      const hpRate = Number(ctx.card.currentHp || 0) / Math.max(1, maxHp);
      const carryEffect = battleCarryItemEffect(ctx.item);
      if (ctx.item.id === "water_meat" && !ctx.state.meatTriggered && hpRate < 0.5) {
        ctx.state.meatTriggered = true;
        const healed = healBattleTarget(ctx.card, 0.25);
        if (healed > 0) battle.log.push(`${ctx.card.name}吃下水水肉，回復 ${healed} HP。`);
      }
      if ((ctx.item.id === "heal_shell" || carryEffect.kind === "auto_heal_when_low_hp") && !ctx.state.healShellTriggered && hpRate < Number(carryEffect.threshold || 0.3)) {
        ctx.state.healShellTriggered = true;
        const healed = healBattleTarget(ctx.card, Number(carryEffect.healPercent || 0.2));
        if (healed > 0) battle.log.push(`${ctx.card.name}的治癒雲貝釋放雲氣，回復 ${healed} HP。`);
      }
      if (ctx.item.id === "pirate_flag_charm" && !ctx.state.pirateFlagTriggered && hpRate < 0.3) {
        ctx.state.pirateFlagTriggered = true;
        applyStageSet(battle.playerStages, { atk: 1, accuracy: 1 }, 0, battle.playerStageTurns, 3);
        battle.log.push(`${ctx.card.name}的海賊旗護符燃起鬥志，攻擊與命中提升。`);
      }
    });
  }

  function applyOffensiveBattleCarryAfterHit(side, damage, player, battle) {
    if (side !== "player" || damage <= 0) return damage;
    const contexts = activePlayerCarryContexts(player, battle).filter((ctx) => ctx.state);
    if (!contexts.length) return damage;
    let nextDamage = Math.max(1, Math.round(damage));
    for (const ctx of contexts) {
      const carryEffect = battleCarryItemEffect(ctx.item);
    if ((ctx.item.id === "impact_dial" || ctx.item.id === "reject_dial" || ctx.item.id === "impact_shell" || ctx.item.id === "reject_shell" || carryEffect.kind === "store_damage_counter") && Number(ctx.state.storedDamage || 0) > 0) {
      const fixedDamage = Math.max(1, Math.round(Number(ctx.state.storedDamage || 0)));
      ctx.state.storedDamage = 0;
      nextDamage += fixedDamage;
      battle.log.push(`${ctx.card.name}釋放${ctx.def.name}，追加 ${fixedDamage} 傷害！`);
      const backlashRate = Number(carryEffect.selfDamageMaxHpPercentAfterRelease || 0);
      if (ctx.item.id === "reject_dial" || ctx.item.id === "reject_shell" || backlashRate > 0) {
        const maxHp = cardMaxHp(ctx.card);
        const backlash = Math.max(1, Math.round(maxHp * (backlashRate || 0.15)));
        ctx.card.currentHp = Math.max(1, Number(ctx.card.currentHp || 1) - backlash);
        battle.log.push(`排擊貝反噬，${ctx.card.name}損失最大 HP 的 15%。`);
      }
    }
    if (ctx.item.id === "seastone_bullet" && !ctx.state.seastoneTriggered && battle.enemyCombatant?.isDevilFruitUser) {
      const fixedDamage = Math.max(1, Math.round((battle.enemyCombatant.maxHp || 1) * 0.06));
      ctx.state.seastoneTriggered = true;
      nextDamage += fixedDamage;
      applyStageSet(battle.enemyCombatant.stages, { spd: -1 }, 0);
      battle.log.push(`海樓石子彈命中能力者！追加 ${fixedDamage} 固定傷害，敵方速度下降。`);
    }
    const moveEntry = getMoveByAction(side, side === "player" ? battle.playerAction : battle.enemyAction, player, battle);
    if (carryEffect.kind === "postgame_oars_giant_belt" && postgameBossMechanicDirectMove(moveEntry)) {
      nextDamage = Math.max(1, Math.round(nextDamage * (1 + Number(carryEffect.directDamageBonus || 0.2))));
    }
    if (ctx.item.id === "sniper_king_goggles" && isShootingBattleMove(moveEntry) && Math.random() < 0.15) {
      const before = nextDamage;
      nextDamage = Math.max(1, Math.round(nextDamage * 1.2));
      battle.log.push(`${ctx.card.name}透過狙擊王的護目鏡捕捉破綻，射擊傷害提升 ${nextDamage - before}。`);
    }
    if (ctx.item.id === "flame_dial" && Math.random() < 0.25) {
      const label = applyBattleStatus("enemy", battle, "burn", 2);
      if (label) battle.log.push(`${ctx.card.name}的炎貝點燃攻勢，敵人陷入${label}狀態。`);
    }
    if (carryEffect.kind === "skill_tag_damage_bonus_and_status_chance" && carryEffect.statusChance?.status) {
      const moveEntry = getMoveByAction(side, battle.playerAction, player, battle);
      const skillTag = String(carryEffect.skillTag || "");
      const matched = skillTag === "fire" ? isFireBattleMove(moveEntry)
        : skillTag === "thunder" ? /雷|電|閃|thunder|lightning/.test(moveSearchText(moveEntry))
          : moveSearchText(moveEntry).includes(skillTag);
      if (matched && Math.random() < Number(carryEffect.statusChance.chance || 0)) {
        const label = applyBattleStatus("enemy", battle, carryEffect.statusChance.status, 2);
        if (label) battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}追加效果，敵人陷入${label}。`);
      }
    }
    if (carryEffect.kind === "flinch_on_damage" && ctx.state.flinchRound !== battle.roundIndex && Math.random() < Number(carryEffect.chance || 0.1)) {
      ctx.state.flinchRound = battle.roundIndex;
      battle.enemyCombatant.roundEffects.flinch = true;
      battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}壓制了敵人氣勢，敵人畏縮。`);
    }
    if (ctx.item.id === "life_orb" || carryEffect.kind === "damage_bonus_with_self_damage") {
      nextDamage = Math.max(1, Math.round(nextDamage * (1 + Number(carryEffect.damageBonus || 0.3))));
      const backlash = Math.max(1, Math.round(cardMaxHp(ctx.card) * Number(carryEffect.selfDamageMaxHpPercent || 0.08)));
      ctx.card.currentHp = Math.max(1, Number(ctx.card.currentHp || 1) - backlash);
      battle.log.push(`生命燃燒寶珠釋放力量，也讓${ctx.card.name}損失 ${backlash} HP。`);
    }
      if (ctx.item.id === "shell_bell" || carryEffect.kind === "heal_by_direct_damage_dealt") {
      const healed = healBattleTarget(ctx.card, Math.max(0, nextDamage * Number(carryEffect.percent || 0.1)) / cardMaxHp(ctx.card));
      if (healed > 0) battle.log.push(`${ctx.card.name}的回音貝鈴回復 ${healed} HP。`);
      }
    }
    return nextDamage;
  }

  function resolvePermanentPointerAfterAttack(side, didHit, player, battle) {
    if (side !== "player") return;
    const ctx = activePlayerCarryContexts(player, battle).find((entry) => entry.item.id === "eternal_pose");
    if (!ctx?.state) return;
    if (ctx.state.permanentPointerPrimed) {
      ctx.state.permanentPointerPrimed = false;
      ctx.state.permanentPointerConsumed = true;
      battle.log.push(`${ctx.card.name}的永久指針完成修正。`);
      return;
    }
    if (!didHit && !ctx.state.permanentPointerMissed) {
      ctx.state.permanentPointerMissed = true;
      ctx.state.permanentPointerPrimed = true;
      battle.log.push(`${ctx.card.name}的永久指針記錄落點，下次攻擊命中提升。`);
    }
  }

  function applyPlayerMissBattleCarryEffects(player, battle) {
    activePlayerCarryContexts(player, battle).forEach((ctx) => {
      if (!ctx.state) return;
      const effect = battleCarryItemEffect(ctx.item);
      if (effect.kind === "boost_speed_when_miss" && !ctx.state.blunderPolicyTriggered) {
        ctx.state.blunderPolicyTriggered = true;
        applyStageSet(battle.playerStages, { spd: Number(effect.speedStage || 2) }, 0, battle.playerStageTurns, 3);
        battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}讓失手後的步伐變快，速度提升。`);
      }
    });
  }

  function battleCarryAdjustedMultiHit(side, moveEntry, diceFace, baseMulti, player, battle) {
    if (side === "enemy" && postgameBossMechanicHasBulletItem(battle, "ammo_pouch")) {
      const hasMultiHit = Number(moveEntry.effects?.multiHit || 0) > 0 || Number(moveEntry.effects?.multiHitOnHighDice || 0) > 0;
      if (!hasMultiHit || Number(baseMulti || 1) <= 1) return baseMulti;
      const mechanic = postgameBossMechanicFor(battle);
      if (mechanic && !mechanic.bulletAmmoLogged) {
        mechanic.bulletAmmoLogged = true;
        battle.log.push(`${postgameBossMechanicBulletSlotsById(battle, "ammo_pouch").length} 個彈藥袋強化巴雷特的連擊。`);
      }
      return Math.max(1, Number(baseMulti || 1) + postgameBossMechanicBulletSlotsById(battle, "ammo_pouch").length);
    }
    if (side !== "player") return baseMulti;
    const contexts = activePlayerCarryContexts(player, battle).filter((ctx) => ctx.item?.id === "ammo_pouch");
    if (!contexts.length) return baseMulti;
    const hasMultiHit = Number(moveEntry.effects?.multiHit || 0) > 0 || Number(moveEntry.effects?.multiHitOnHighDice || 0) > 0;
    if (!hasMultiHit || Number(baseMulti || 1) <= 1) return baseMulti;
    contexts.forEach((ctx) => {
      if (ctx.state && !ctx.state.ammoPouchTriggered) {
        ctx.state.ammoPouchTriggered = true;
        battle.log.push(`${ctx.card.name}的彈藥袋讓連擊多打 1 下。`);
      }
    });
    return Math.max(1, Number(baseMulti || 1) + contexts.length);
  }

  function normalizeBattleHitCount(value) {
    return Math.max(1, Math.min(12, Math.round(Number(value || 1))));
  }

  function battleDamageHitTotal(hitDamages = []) {
    return hitDamages.reduce((sum, damage) => sum + Math.max(0, Math.round(Number(damage || 0))), 0);
  }

  function isComboBattleMove(moveEntry = {}) {
    return Number(moveEntry.effects?.multiHit || 0) > 0 || Number(moveEntry.effects?.multiHitOnHighDice || 0) > 0;
  }

  function comboAtkRatio(moveEntry = {}) {
    const explicit = Number(moveEntry.effects?.comboAtkRatio || 0);
    if (explicit > 0) {
      return Math.max(
        Number(BATTLE_DAMAGE_TUNING.comboAtkRatioMin || 0.05),
        Math.min(Number(BATTLE_DAMAGE_TUNING.comboAtkRatioMax || 0.08), explicit),
      );
    }
    const power = Math.max(0, Number(moveEntry.power || 0));
    const category = moveEntry.category || moveEntry.type || "";
    const ratio = Number(BATTLE_DAMAGE_TUNING.comboAtkRatioBase || 0.055)
      + power * Number(BATTLE_DAMAGE_TUNING.comboAtkRatioPowerScale || 0.00008)
      + (boardMoveIsSpecialDamage(moveEntry) ? Number(BATTLE_DAMAGE_TUNING.comboAtkRatioSpecialBonus || 0.01) : 0);
    return Math.max(
      Number(BATTLE_DAMAGE_TUNING.comboAtkRatioMin || 0.05),
      Math.min(Number(BATTLE_DAMAGE_TUNING.comboAtkRatioMax || 0.08), ratio),
    );
  }

  function comboDiceMultiplier(face, side = "player") {
    return battleAttackDiceMultiplier(side, face);
  }

  function comboDiceHitCount(maxHits, face) {
    return normalizeBattleHitCount(maxHits || face);
  }

  function comboMoveMaxHits(moveEntry, diceFace) {
    const effects = moveEntry?.effects || {};
    if (Number(effects.multiHit || 0) > 0) return normalizeBattleHitCount(diceFace);
    if (Number(effects.multiHitOnHighDice || 0) > 0) {
      return diceFace >= 5 ? normalizeBattleHitCount(diceFace) : 1;
    }
    return 1;
  }

  function splitBattleDamageIntoHits(baseDamage, hitCount, bonusDamage = 0) {
    const count = normalizeBattleHitCount(hitCount);
    if (Number(baseDamage || 0) <= 0) {
      const blocked = Array.from({ length: count }, () => 0);
      const bonus = Math.max(0, Math.round(Number(bonusDamage || 0)));
      if (bonus) blocked[blocked.length - 1] = bonus;
      return blocked;
    }
    const hits = Array.from({ length: count }, () => Math.max(1, Math.round(Number(baseDamage || 1))));
    const bonus = Math.round(Number(bonusDamage || 0));
    if (bonus) hits[hits.length - 1] = Math.max(0, hits[hits.length - 1] + bonus);
    return hits;
  }

  function scaleBattleHitDamagesToTotal(hitDamages, targetTotal) {
    const hits = hitDamages.map((damage) => Math.max(0, Math.round(Number(damage || 0))));
    const total = Math.max(0, Math.round(Number(targetTotal || 0)));
    if (!hits.length) return total > 0 ? [total] : [0];
    if (total <= 0) return hits.map(() => 0);
    const rawTotal = battleDamageHitTotal(hits);
    if (rawTotal <= 0) {
      const spread = Array.from({ length: hits.length }, () => 0);
      for (let i = 0; i < total; i += 1) spread[i % spread.length] += 1;
      return spread;
    }
    const canKeepEveryHitVisible = total >= hits.filter((damage) => damage > 0).length;
    const scaled = hits.map((damage) => {
      if (damage <= 0) return 0;
      const value = Math.floor((damage / rawTotal) * total);
      return canKeepEveryHitVisible ? Math.max(1, value) : Math.max(0, value);
    });
    let diff = total - battleDamageHitTotal(scaled);
    let guard = 0;
    while (diff > 0 && guard < 200) {
      scaled[guard % scaled.length] += 1;
      diff -= 1;
      guard += 1;
    }
    guard = 0;
    while (diff < 0 && guard < 200) {
      const index = guard % scaled.length;
      const floor = canKeepEveryHitVisible && hits[index] > 0 ? 1 : 0;
      if (scaled[index] > floor) {
        scaled[index] -= 1;
        diff += 1;
      }
      guard += 1;
    }
    return scaled;
  }

  function adjustBattleHitDamagesToTotal(hitDamages, targetTotal) {
    const hits = hitDamages.map((damage) => Math.max(0, Math.round(Number(damage || 0))));
    const total = Math.max(0, Math.round(Number(targetTotal || 0)));
    const diff = total - battleDamageHitTotal(hits);
    if (!hits.length) return total > 0 ? [total] : [0];
    if (diff >= 0) {
      hits[hits.length - 1] += diff;
      return hits;
    }
    return scaleBattleHitDamagesToTotal(hits, total);
  }

  function battleHitBreakdownText(hitDamages = []) {
    const hits = hitDamages.map((damage) => Math.max(0, Math.round(Number(damage || 0))));
    return hits.length > 1 ? `（${hits.length} 下：${hits.join(" / ")}）` : "";
  }

  function isBattleTargetControlled(side, battle) {
    const targetSide = side === "player" ? "enemy" : "player";
    const statuses = battleStatusBag(targetSide, battle);
    const stages = targetSide === "player" ? battle.playerStages : battle.enemyCombatant?.stages;
    return Number(statuses.freeze || 0) > 0
      || Number(statuses.paralyze || 0) > 0
      || Number(statuses.bind || 0) > 0
      || Number(stages?.spd || 0) < 0;
  }

  function battleSideStages(side, battle) {
    return side === "player" ? battle?.playerStages : battle?.enemyCombatant?.stages;
  }

  function battleSideRoundEffects(side, battle) {
    return side === "player" ? battle?.playerRoundEffects : battle?.enemyCombatant?.roundEffects;
  }

  function isBattleSideDebuffed(side, battle) {
    const stages = battleSideStages(side, battle) || {};
    if (Object.values(stages).some((value) => Number(value || 0) < 0)) return true;
    const statuses = battleStatusBag(side, battle) || {};
    if (Object.values(statuses).some((turns) => Number(turns || 0) > 0)) return true;
    const round = battleSideRoundEffects(side, battle) || {};
    return Number(round.damageTakenUp || 0) > 0 || Boolean(round.controlLock);
  }

  function battleSideHasShield(side, battle) {
    return Number(battleSideRoundEffects(side, battle)?.shieldRatio || 0) > 0;
  }

  function clearPositiveBattleStages(targetSide, player, battle) {
    const stages = battleSideStages(targetSide, battle) || {};
    const turns = targetSide === "player" ? battle.playerStageTurns : battle.enemyCombatant?.stageTurns;
    let cleared = 0;
    Object.keys(stages).forEach((key) => {
      if (Number(stages[key] || 0) > 0) {
        stages[key] = 0;
        if (turns) turns[key] = 0;
        cleared += 1;
      }
    });
    return cleared;
  }

  function statusDamageBonusForTarget(side, battle, strongerVsStatus = {}) {
    const statuses = battleStatusBag(side, battle) || {};
    return Object.entries(strongerVsStatus || {}).reduce((bonus, [status, ratio]) => (
      Number(statuses[status] || 0) > 0 ? Math.max(bonus, Number(ratio || 0)) : bonus
    ), 0);
  }

  function conditionalDamageMultiplier(side, moveEntry, attackerSide, defenderSide, player, battle) {
    const effects = moveEntry?.effects || {};
    let multiplier = 1;
    const attackerSpeed = currentBattleStat(attackerSide, "spd", player, battle);
    const defenderSpeed = currentBattleStat(defenderSide, "spd", player, battle);
    if (effects.strongerIfFaster && attackerSpeed > defenderSpeed) {
      multiplier *= 1 + Number(effects.strongerIfFaster || 0);
    }
    if (effects.strongerVsDebuffed && isBattleSideDebuffed(defenderSide, battle)) {
      multiplier *= 1 + Number(effects.strongerVsDebuffed || 0);
    }
    if (effects.strongerIfShielded && battleSideHasShield(attackerSide, battle)) {
      multiplier *= 1 + Number(effects.strongerIfShielded || 0);
    }
    if (effects.strongerIfShieldedTarget && battleSideHasShield(defenderSide, battle)) {
      multiplier *= 1 + Number(effects.strongerIfShieldedTarget || 0);
    }
    if (effects.bonusVsAttribute) {
      const defender = defenderSide === "player" ? battleActiveCard(player, battle) : battle.enemyCombatant;
      if (defender?.attribute === effects.bonusVsAttribute) multiplier *= 1 + Number(effects.amplifyVsAttribute || 0.1);
    }
    if (effects.conditionalDamageBonus) {
      multiplier *= 1 + Number(effects.conditionalDamageBonus || 0);
    }
    const statusBonus = statusDamageBonusForTarget(defenderSide, battle, effects.strongerVsStatus);
    if (statusBonus) multiplier *= 1 + statusBonus;
    return Math.max(0.1, multiplier);
  }

  function statusDiceDelta(face) {
    if (face === 1) return -1;
    if (face === 6 || face >= 4) return 1;
    return 0;
  }

  function battleMoveDealsDamage(moveEntry) {
    return boardMoveDamageClass(moveEntry) === "physical" || boardMoveDamageClass(moveEntry) === "special";
  }

  function battleDiceThemeForMove(moveEntry = {}) {
    const category = moveEntry.category || moveEntry.type || "attack";
    if (battleMoveDealsDamage(moveEntry)) return "battle";
    if (category === "heal" || category === "buff" || category === "shield") return "skill";
    if (category === "debuff" || category === "control" || category === "status") return "skill";
    return "skill";
  }

  function stageVisualEffectFromMap(stageMap = {}) {
    const stageOrder = [
      ["atk", "attack", "攻擊"],
      ["satk", "attack", "特攻"],
      ["def", "defense", "防禦"],
      ["sdef", "defense", "特防"],
      ["spd", "speed", "速度"],
      ["accuracy", "speed", "命中"],
      ["acc", "speed", "命中"],
      ["evasion", "speed", "閃避"],
    ];
    for (const [key, kind, label] of stageOrder) {
      const value = Number(stageMap?.[key] || 0);
      if (value) {
        return {
          kind,
          direction: value > 0 ? "up" : "down",
          label: `${label}${value > 0 ? "提升" : "下降"}`,
        };
      }
    }
    return null;
  }

  function battleVisualEffectForMove(moveEntry = {}, side, phase, healingDone = 0, diceFace = 0) {
    const effects = moveEntry.effects || {};
    const category = moveEntry.category || moveEntry.type || "";
    const defender = side === "player" ? "enemy" : "player";
    if (phase === "heal" || Number(healingDone || 0) > 0 || effects.healRatio || effects.healLowestAllyRatio || effects.healTeamRatio) {
      return { targetSide: side, kind: "heal", direction: "up", label: "治癒" };
    }
    if (effects.shieldRatio || effects.teamShieldRatio || category === "shield") {
      return { targetSide: side, kind: "defense", direction: "up", label: "防禦提升" };
    }
    const selfStageMaps = [effects.selfStages];
    if (phase === "attack" && Number(diceFace || 0) >= 5) selfStageMaps.push(effects.selfStagesOnHighDice);
    if (phase === "attack") selfStageMaps.push(effects.selfStagesAfterUse);
    for (const stageMap of selfStageMaps) {
      const selfStage = stageVisualEffectFromMap(stageMap);
      if (selfStage) return { targetSide: side, ...selfStage };
    }
    const targetStageMaps = [effects.enemyStages];
    if (phase === "attack") {
      targetStageMaps.push(effects.enemyStagesOnHit);
      if (Number(diceFace || 0) >= 5) targetStageMaps.push(effects.enemyStagesOnHighDice);
      if (Number(diceFace || 0) === 6) targetStageMaps.push(effects.enemyStagesOnSix);
      if (Number(diceFace || 0) >= 4 && Number(diceFace || 0) % 2 === 0) targetStageMaps.push(effects.enemyStagesOnEvenHighDice);
    }
    for (const stageMap of targetStageMaps) {
      const targetStage = stageVisualEffectFromMap(stageMap);
      if (targetStage) return { targetSide: defender, ...targetStage };
    }
    if (category === "debuff" || category === "control" || effects.status || effects.statusOnHit) {
      return { targetSide: defender, kind: "debuff", direction: "down", label: "能力下降" };
    }
    if (category === "buff") return { targetSide: side, kind: "speed", direction: "up", label: "能力提升" };
    return null;
  }

