  let battleHitEffectChoiceCache = null;

  function battleHitEffectSettings() {
    return window.BattleHitEffectSettings || {};
  }

  function battleHitEffectChoices() {
    const settings = battleHitEffectSettings();
    const key = settings.storageKey || "onepiece-battle-hit-effect-choices-v1";
    try {
      const raw = localStorage.getItem(key);
      const parsed = raw ? JSON.parse(raw) : {};
      battleHitEffectChoiceCache = parsed && typeof parsed === "object" ? parsed : {};
    } catch (_error) {
      battleHitEffectChoiceCache = {};
    }
    return battleHitEffectChoiceCache || {};
  }

  function battleHitEffectChoiceForMove(moveId) {
    const choice = battleHitEffectChoices()[moveId];
    return choice && typeof choice === "object" ? choice : {};
  }

  function battleHitEffectForMove(moveEntry = {}, diceFace = 0, hitDamages = []) {
    if (!battleMoveDealsDamage(moveEntry)) return "";
    if (moveEntry.hitEffect) return String(moveEntry.hitEffect);
    const customChoice = battleHitEffectChoiceForMove(moveEntry.id);
    if (customChoice.effect) return String(customChoice.effect);
    const settingsMoveEffect = battleHitEffectSettings().moveEffects?.[moveEntry.id];
    if (settingsMoveEffect) return String(settingsMoveEffect);
    if (BATTLE_HIT_EFFECT_EXACT[moveEntry.id]) return BATTLE_HIT_EFFECT_EXACT[moveEntry.id];
    const effects = moveEntry.effects || {};
    const text = [
      moveEntry.id,
      moveEntry.name,
      moveEntry.effectText,
      moveEntry.attribute,
      moveEntry.category || moveEntry.type,
    ].filter(Boolean).join(" ");
    const lower = text.toLowerCase();
    const has = (...tokens) => tokens.some((token) => text.includes(token) || lower.includes(String(token).toLowerCase()));
    const hitCount = Array.isArray(hitDamages) ? hitDamages.length : 1;
    const power = Number(moveEntry.power || 0);
    if (hitCount > 1) {
      if (has("斬", "刀", "劍", "刃", "居合", "鬼斬", "虎狩", "鐮", "slash", "blade")) return "slash_multi.webp";
      if (has("踢", "腳", "串燒", "羊肉", "首肉", "反禮儀", "kick")) return "kick_mark.webp";
      if (has("射擊", "子彈", "彈", "鉛星", "火藥星", "狙", "bullet", "shot")) return "bullet_sparks.webp";
      return "punch_combo.webp";
    }
    if (Number(diceFace || 0) === 6 && effects.statusOnSix) {
      if (effects.statusOnSix.burn) return "fire_impact.webp";
      if (effects.statusOnSix.paralyze) return "lightning_hit.webp";
      if (effects.statusOnSix.freeze) return "ice_impact.webp";
      if (effects.statusOnSix.poison) return "poison_splash.webp";
    }
    if (has("火箭", "火藥", "爆", "炸", "砲", "炮", "雷射", "流星", "隕石", "explosion", "laser", "rocket", "bazooka")) return "explosion_burst.webp";
    if (has("火", "炎", "燒", "灼", "惡魔風腳", "火鳥", "狐火", "青炎", "fire", "burn")) return "fire_impact.webp";
    if (has("雷", "電", "雷鳴", "雷光", "thunder", "lightning", "electro")) return "lightning_hit.webp";
    if (has("冰", "寒", "凍", "雪", "ice", "freeze", "frost")) return "ice_impact.webp";
    if (has("毒", "劇毒", "poison")) return "poison_splash.webp";
    if (has("水", "海流", "魚人", "擊水", "water")) return "water_splash.webp";
    if (has("暗", "影", "幽靈", "消極", "黃泉", "靈魂", "恐懼", "dark", "ghost", "soul")) return "dark_impact.webp";
    if (has("風", "龍捲", "嵐腳", "疾風", "暴風", "旋風", "風刃", "wind", "storm", "tornado")) return "wind_slash.webp";
    if (has("衝擊貝", "排擊", "六王槍", "衝擊", "震波", "壓力砲", "熊之衝擊", "shockwave")) return "shockwave_ring.webp";
    if (has("斬", "刀", "劍", "刃", "居合", "鬼斬", "虎狩", "獅子歌歌", "煩惱鳳", "鐮", "slash", "blade")) {
      return power >= 95 || boardMoveIsSpecialDamage(moveEntry) ? "slash_cross.webp" : "slash_single.webp";
    }
    if (has("踢", "腳", "串燒", "羊肉", "首肉", "黑足", "反禮儀", "芳香腳", "踢擊", "kick")) {
      return power >= 85 || boardMoveIsSpecialDamage(moveEntry) ? "kick_mark_heavy.webp" : "kick_mark.webp";
    }
    if (has("爪", "鉤爪", "claw")) return "slash_single.webp";
    if (has("橡膠手槍", "JET手槍", "橡膠", "拳", "掌", "正拳", "空手道", "打擊", "撞擊", "punch", "fist")) {
      return power >= 85 || boardMoveIsSpecialDamage(moveEntry) ? "punch_mark_heavy.webp" : "punch_mark.webp";
    }
    if (has("刺", "突刺", "指槍", "長矛", "冰矛", "矛", "注射", "槍", "箭", "pierce", "spear")) return "pierce_mark.webp";
    if (has("射擊", "子彈", "彈", "鉛星", "狙", "手槍射擊", "bullet", "shot")) return "bullet_hit.webp";
    if (has("鎚", "錘", "鐵鎚", "重擊", "鈍", "blunt")) return "blunt_crack.webp";
    return power >= 85 || boardMoveIsSpecialDamage(moveEntry) ? "punch_mark_heavy.webp" : "punch_mark.webp";
  }

  function battleHitSfxForMove(moveEntry = {}, hitEffectFile = "") {
    if (moveEntry.hitSfx) return String(moveEntry.hitSfx);
    const choice = battleHitEffectChoiceForMove(moveEntry.id);
    if (typeof choice.sfx === "string") return choice.sfx;
    const settings = battleHitEffectSettings();
    if (settings.moveSfx?.[moveEntry.id]) return String(settings.moveSfx[moveEntry.id]);
    return settings.effectDefaultSfx?.[hitEffectFile] || "";
  }

  function battleCastSfxForMove(moveEntry = {}) {
    if (moveEntry.castSfx) return String(moveEntry.castSfx);
    const choice = battleHitEffectChoiceForMove(moveEntry.id);
    if (typeof choice.castSfx === "string") return choice.castSfx;
    const settings = battleHitEffectSettings();
    if (settings.moveCastSfx?.[moveEntry.id]) return String(settings.moveCastSfx[moveEntry.id]);
    return "";
  }

  function battleActorLevel(side, player, battle) {
    const actor = side === "player" ? battleActiveCard(player, battle) : battle?.enemyCombatant;
    return Math.max(1, Math.min(CHARACTER_MAX_LEVEL, Math.round(Number(actor?.level || 1))));
  }

  function pokemonAttackDefenseRatio(side, attackStat, defenseStat) {
    const ratio = Math.max(0.01, Number(attackStat || 1)) / Math.max(1, Number(defenseStat || 1));
    const maxRatio = Number(BATTLE_DAMAGE_TUNING.pokemonAttackDefenseRatioMax || 3.2);
    return Math.max(
      Number(BATTLE_DAMAGE_TUNING.pokemonAttackDefenseRatioMin || 0.5),
      Math.min(maxRatio, ratio),
    );
  }

  function pokemonStyleBaseDamage(side, level, power, attackStat, defenseStat) {
    const levelFloor = Math.max(1, Number(BATTLE_DAMAGE_TUNING.pokemonDamageLevelFloor || 1));
    const normalizedLevel = Math.max(levelFloor, Math.min(CHARACTER_MAX_LEVEL, Number(level || 1)));
    const normalizedPower = Math.max(1, Number(power || 1));
    const levelFactor = ((2 * normalizedLevel) / 5) + 2;
    const statRatio = pokemonAttackDefenseRatio(side, attackStat, defenseStat);
    const baseDamage = (((levelFactor * normalizedPower * statRatio) / 50) + 2);
    return Math.max(1, Math.round(baseDamage * Number(BATTLE_DAMAGE_TUNING.pokemonDamageScale || 1.6)));
  }

  function applyPlayerCarryDamageModifiers(damage, moveEntry, diceFace, player, battle, attackerCard, visualMeta = null) {
    let nextDamage = Math.max(1, Math.round(Number(damage || 1)));
    activePlayerCarryContexts(player, battle).forEach((ctx) => {
      const carryId = ctx.item.id;
      const carryEffect = battleCarryItemEffect(ctx.item);
      if (carryId === "flame_dial" && isFireBattleMove(moveEntry)) nextDamage = Math.round(nextDamage * 1.1);
      if (carryId === "water_dial" && isWaterBattleMove(moveEntry)) nextDamage = Math.round(nextDamage * 1.1);
      if (carryId === "ammo_pouch" && isShootingBattleMove(moveEntry)) {
        nextDamage = Math.round(nextDamage * 1.08);
        if (ctx.state && !ctx.state.ammoPouchTriggered) {
          ctx.state.ammoPouchTriggered = true;
          battle.log.push(`${ctx.card.name}的彈藥袋補足彈藥，射擊傷害提升。`);
        }
      }
      if ((carryId === "choice_band" || carryEffect.kind === "choice_lock_physical_damage") && boardMoveIsPhysicalDamage(moveEntry)) nextDamage = Math.round(nextDamage * (1 + Number(carryEffect.damageBonus || 0.25)));
      if ((carryId === "choice_glasses" || carryEffect.kind === "choice_lock_special_damage") && boardMoveIsSpecialDamage(moveEntry)) nextDamage = Math.round(nextDamage * (1 + Number(carryEffect.damageBonus || 0.25)));
      if (carryId === "lagging_tail" || carryEffect.kind === "move_late_damage_bonus") nextDamage = Math.round(nextDamage * (1 + Number(carryEffect.damageBonus || 0.15)));
      if (carryId === "flame_shell" && isFireBattleMove(moveEntry)) nextDamage = Math.round(nextDamage * 1.15);
      if (carryId === "thunder_shell" && /雷|電|閃|thunder|lightning/.test(moveSearchText(moveEntry))) nextDamage = Math.round(nextDamage * 1.15);
      if (carryEffect.kind === "sound_skill_bonus_and_satk_once" && isSoundBattleMove(moveEntry)) {
        nextDamage = Math.round(nextDamage * (1 + Number(carryEffect.damageBonus || 0.2)));
        if (ctx.state && !ctx.state.toneShellTriggered) {
          ctx.state.toneShellTriggered = true;
          applyStageSet(battle.playerStages, { satk: Number(carryEffect.satkStage || 1) }, 0, battle.playerStageTurns, 3);
          battle.log.push(`${attackerCard.name}的${battleCarryItemName(ctx.item)}放大聲波，戰術能力提升。`);
        }
      }
      if (carryEffect.kind === "same_skill_damage_stack" && ctx.state) {
        if (ctx.state.metronomeSkillId === moveEntry.id) ctx.state.stackCount = Math.min(Math.round(Number(carryEffect.maxBonus || 0.4) / Number(carryEffect.stackBonus || 0.1)), Number(ctx.state.stackCount || 0) + 1);
        else {
          ctx.state.metronomeSkillId = moveEntry.id;
          ctx.state.stackCount = 0;
        }
        const stackBonus = Math.min(Number(carryEffect.maxBonus || 0.4), Number(ctx.state.stackCount || 0) * Number(carryEffect.stackBonus || 0.1));
        if (stackBonus > 0) nextDamage = Math.round(nextDamage * (1 + stackBonus));
      }
      if (carryEffect.kind === "postgame_saga_seven_star_sword") {
        const hpRate = Number(attackerCard?.currentHp || 0) / Math.max(1, cardMaxHp(attackerCard));
        const steps = Math.max(0, Math.floor((1 - hpRate + 1e-9) / Math.max(.01, Number(carryEffect.lostHpStep || .05))));
        const bonus = Math.min(Number(carryEffect.maxDamageBonus || .76), steps * Number(carryEffect.damageBonusPerStep || .04));
        if (bonus > 0) nextDamage = Math.round(nextDamage * (1 + bonus));
      }
      if (carryEffect.kind === "postgame_zephyr_battle_smasher" && ctx.state?.battleSmasherReady) {
        nextDamage = Math.round(nextDamage * (1 + Number(carryEffect.damageBonus || .4)));
      }
      if (carryEffect.kind === "postgame_king_sword" && ctx.state?.kingFlameOn === false) {
        nextDamage = Math.round(nextDamage * (1 + Number(carryEffect.nextDirectDamageBonus || .25)));
      }
      if (carryEffect.kind === "postgame_loki_ragnir" && Number(diceFace || 0) >= Number(carryEffect.highDiceMinimum || 5)) {
        nextDamage = Math.round(nextDamage * (1 + Math.max(0, Number(ctx.state?.ragnirClouds || 0)) * Number(carryEffect.damageBonusPerCloud || .15)));
      }
      nextDamage = applyOffensiveDevilFruitSuppressor(nextDamage, ctx, battle, attackerCard);
    });
    return nextDamage;
  }

  function resolveBattleCriticalDamage(damage, side, moveEntry, player, battle, visualMeta = null, hitIndex = 0, randomValue = null) {
    const normalizedDamage = Math.max(0, Math.round(Number(damage || 0)));
    if (!visualMeta || normalizedDamage <= 0 || battleMoveCannotCritical(moveEntry)) return normalizedDamage;
    const rate = battleCriticalRate(side, moveEntry, player, battle);
    if (rate <= 0) return normalizedDamage;
    const guaranteed = battleMoveGuaranteedCritical(moveEntry);
    const roll = randomValue == null ? Math.random() : Math.max(0, Math.min(.999999, Number(randomValue || 0)));
    if (!guaranteed && roll >= rate) return normalizedDamage;
    const attacker = side === "player" ? battleActiveCard(player, battle) : battle?.enemyCombatant;
    const multiplier = battleCriticalDamageMultiplier(moveEntry, attacker, side, player, battle);
    const moveBonus = battleMoveCriticalRateBonus(moveEntry);
    const source = guaranteed
      ? `${moveEntry.name || "招式"}・必定暴擊`
      : moveBonus > 0
        ? `${moveEntry.name || "招式"}・高暴擊`
        : "角色暴擊";
    markBattleCriticalVisual(visualMeta, source, hitIndex);
    visualMeta.criticalRate = rate;
    visualMeta.criticalDamageMultiplier = multiplier;
    if (!visualMeta.criticalAnnounced && battle?.log) {
      visualMeta.criticalAnnounced = true;
      battle.log.push(`${attacker?.name || (side === "player" ? "我方" : "敵人")}命中要害，打出暴擊！`);
    }
    return Math.max(1, Math.round(normalizedDamage * multiplier));
  }

  function resolveBattleCriticalHitDamages(hitDamages, side, moveEntry, player, battle, visualMeta = null, randomValues = null) {
    if (!Array.isArray(hitDamages)) return [];
    return hitDamages.map((damage, index) => resolveBattleCriticalDamage(
      damage,
      side,
      moveEntry,
      player,
      battle,
      visualMeta,
      index,
      Array.isArray(randomValues) ? randomValues[index] : null,
    ));
  }

  function comboDamagePower(moveEntry = {}) {
    return Math.max(5, Math.round(comboAtkRatio(moveEntry) * 100));
  }

  function battleMoveDamageStatKeys(moveEntry = {}) {
    return boardMoveIsSpecialDamage(moveEntry)
      ? { attack: "satk", defense: "sdef" }
      : { attack: "atk", defense: "def" };
  }

  function computeMoveDamage(side, moveEntry, diceFace, player, battle, visualMeta = null) {
    const attackerSide = side === "player" ? "player" : "enemy";
    const defenderSide = side === "player" ? "enemy" : "player";
    const attackerCard = side === "player" ? battleActiveCard(player, battle) : battle.enemyCombatant;
    const attackerAttribute = side === "player" ? battleActiveCard(player, battle).attribute : battle.enemyCombatant.attribute;
    const defenderAttribute = side === "player" ? battle.enemyCombatant.attribute : battleActiveCard(player, battle).attribute;
    const statKeys = battleMoveDamageStatKeys(moveEntry);
    const attackStat = currentBattleStat(attackerSide, statKeys.attack, player, battle);
    let defenseStat = currentBattleStat(defenderSide, statKeys.defense, player, battle);
    const effects = moveEntry.effects || {};
    const piercesShield = Boolean(effects.pierceShield || (diceFace >= 5 && effects.pierceShieldOnHighDice));
    let ignoreDefenseRatio = Math.max(
      Number(effects.ignoreDefenseRatio || 0),
      Number(effects.antiShieldBonus || 0),
    );
    if (side === "player") {
      const carryIgnore = playerBattleCarryIgnoreDefenseRatio(moveEntry, player, battle);
      if (carryIgnore > 0) ignoreDefenseRatio = 1 - (1 - Math.max(0, Math.min(.85, ignoreDefenseRatio))) * (1 - carryIgnore);
    }
    if (side === "enemy") {
      const bulletIgnore = postgameBossMechanicBulletIgnoreDefenseRatio(battle, moveEntry);
      if (bulletIgnore > 0) ignoreDefenseRatio = 1 - (1 - Math.max(0, Math.min(.85, ignoreDefenseRatio))) * (1 - bulletIgnore);
    }
    if (ignoreDefenseRatio) {
      defenseStat = Math.max(1, Math.round(defenseStat * (1 - Math.max(0, Math.min(0.85, ignoreDefenseRatio)))));
    }
    if (side === "enemy") {
      activePlayerCarryContexts(player, battle).forEach((ctx) => {
        const defenderEffect = battleCarryItemEffect(ctx.item);
        if (defenderEffect.kind === "sdef_bonus_block_support_skills" && boardMoveIsSpecialDamage(moveEntry)) defenseStat = Math.round(defenseStat * Number(defenderEffect.sdefMultiplier || 1.4));
      });
    }
    const attackerBonus = side === "player" ? getTeamEffects(player) : null;
    const targetCard = side === "player" ? battle.enemyCombatant : battleActiveCard(player, battle);
    const targetMaxHp = side === "player"
      ? battle.enemyCombatant.maxHp
      : (targetCard?.baseStats?.hp || targetCard?.maxHp || targetCard?.hp || 1);
    let damage = pokemonStyleBaseDamage(side, battleActorLevel(side, player, battle), moveEntry.power || 1, attackStat, defenseStat);
    damage = Math.round(damage * battleAttackDiceMultiplier(side, diceFace));
    const attributeMultiplier = battleAttributeDamageMultiplier(side, moveEntry, attackerAttribute, defenderAttribute, player, battle);
    if (attributeMultiplier <= 0) return 0;
    damage = Math.round(damage * attributeMultiplier);
    const actorRound = side === "player" ? battle.playerRoundEffects : battle.enemyCombatant.roundEffects;
    if (actorRound?.nextHitBoost) damage = Math.round(damage * (1 + Number(actorRound.nextHitBoost || 0)));
    if (diceFace >= 5 && effects.amplifyOnHighDice) damage = Math.round(damage * (1 + Number(effects.amplifyOnHighDice)));
    if (effects.amplifyWhenLowHp) {
      const actorHp = Number(attackerCard?.currentHp ?? attackerCard?.hp ?? attackerCard?.maxHp ?? attackerCard?.baseStats?.hp ?? 1);
      const actorMaxHp = Number(attackerCard?.baseStats?.hp || attackerCard?.maxHp || attackerCard?.hp || 1);
      if (actorHp / Math.max(1, actorMaxHp) <= 0.5) damage = Math.round(damage * (1 + Number(effects.amplifyWhenLowHp)));
    }
    if (effects.amplifyVsControlled && isBattleTargetControlled(side, battle)) {
      damage = Math.round(damage * (1 + Number(effects.amplifyVsControlled)));
    }
    if (effects.bossDamageBonus && (battle.isJudicialRaid || battle.islandKind === "yonko" || targetCard?.tier === "T1" || targetCard?.rank === "S")) {
      damage = Math.round(damage * (1 + Number(effects.bossDamageBonus)));
    }
    if (effects.highHpDamageBonus) {
      const targetHp = Number(targetCard?.currentHp ?? targetCard?.hp ?? targetCard?.maxHp ?? targetCard?.baseStats?.hp ?? 1);
      if (targetHp / Math.max(1, targetMaxHp) >= 0.5) damage = Math.round(damage * (1 + Number(effects.highHpDamageBonus)));
    }
    damage = Math.round(damage * yonkoEnemyDamageMultiplier(side, moveEntry, player, battle));
    damage = Math.round(damage * finalGateEnemyDamageMultiplier(side, moveEntry, player, battle));
    damage = Math.round(damage * conditionalDamageMultiplier(side, moveEntry, attackerSide, defenderSide, player, battle));
    damage = Math.round(damage * characterPassiveDamageMultiplier(side, moveEntry, diceFace, player, battle));
    if (side === "player" && attackerCard?.roleType === "戰鬥型" && boardMoveIsPhysicalDamage(moveEntry)) {
      damage = Math.round(damage * (attackerBonus?.battleAttackMultiplier || 1.1));
    }
    if (side === "player") damage = applyPlayerCarryDamageModifiers(damage, moveEntry, diceFace, player, battle, attackerCard, visualMeta);
    const defenderEffects = side === "player" ? battle.enemyCombatant.roundEffects : battle.playerRoundEffects;
    let shieldRatio = Number(defenderEffects?.shieldRatio || 0);
    let fullShieldBlock = shieldRatio >= 1;
    if (shieldRatio && (effects.antiShieldBonus || piercesShield)) shieldRatio = Math.max(0, shieldRatio - Number(effects.antiShieldBonus || 1));
    fullShieldBlock = fullShieldBlock && shieldRatio >= 1;
    if (shieldRatio) damage = Math.round(damage * (1 - shieldRatio));
    if (defenderEffects?.damageTakenUp) damage = Math.round(damage * (1 + defenderEffects.damageTakenUp));
    if (side === "enemy") {
      damage = Math.round(damage * characterPassiveDamageTakenMultiplier(moveEntry, player, battle));
      damage = Math.round(damage * (1 - (getTeamEffects(player).supportDamageReduction || 0)));
      damage = Math.round(damage * Number(BATTLE_DAMAGE_TUNING.enemyDamageScale || 1));
    }
    const softCapRatio = side === "enemy"
      ? Number(BATTLE_DAMAGE_TUNING.enemySoftCapHpRatio || BATTLE_DAMAGE_TUNING.softCapHpRatio)
      : BATTLE_DAMAGE_TUNING.softCapHpRatio;
    const softCapOverflowScale = side === "enemy"
      ? Number(BATTLE_DAMAGE_TUNING.enemySoftCapOverflowScale || BATTLE_DAMAGE_TUNING.softCapOverflowScale)
      : BATTLE_DAMAGE_TUNING.softCapOverflowScale;
    const softCap = Math.max(18, Math.round(targetMaxHp * softCapRatio));
    if (damage > softCap) {
      damage = softCap + Math.round((damage - softCap) * softCapOverflowScale);
    }
    const resolvedDamage = fullShieldBlock && damage <= 0 ? 0 : Math.max(1, damage);
    return resolveBattleCriticalDamage(resolvedDamage, side, moveEntry, player, battle, visualMeta, 0);
  }

  function computeComboHitDamages(side, moveEntry, diceFace, maxHits, bonusDamage, player, battle, visualMeta = null) {
    const attackerSide = side === "player" ? "player" : "enemy";
    const defenderSide = side === "player" ? "enemy" : "player";
    const attackerCard = side === "player" ? battleActiveCard(player, battle) : battle.enemyCombatant;
    const attackerAttribute = side === "player" ? battleActiveCard(player, battle).attribute : battle.enemyCombatant.attribute;
    const defenderAttribute = side === "player" ? battle.enemyCombatant.attribute : battleActiveCard(player, battle).attribute;
    const statKeys = battleMoveDamageStatKeys(moveEntry);
    const attackStat = currentBattleStat(attackerSide, statKeys.attack, player, battle);
    let defenseStat = currentBattleStat(defenderSide, statKeys.defense, player, battle);
    const effects = moveEntry.effects || {};
    const piercesShield = Boolean(effects.pierceShield || (diceFace >= 5 && effects.pierceShieldOnHighDice));
    let ignoreDefenseRatio = Math.max(
      Number(effects.ignoreDefenseRatio || 0),
      Number(effects.antiShieldBonus || 0),
    );
    if (side === "player") {
      const carryIgnore = playerBattleCarryIgnoreDefenseRatio(moveEntry, player, battle);
      if (carryIgnore > 0) ignoreDefenseRatio = 1 - (1 - Math.max(0, Math.min(.85, ignoreDefenseRatio))) * (1 - carryIgnore);
    }
    if (side === "enemy") {
      const bulletIgnore = postgameBossMechanicBulletIgnoreDefenseRatio(battle, moveEntry);
      if (bulletIgnore > 0) ignoreDefenseRatio = 1 - (1 - Math.max(0, Math.min(.85, ignoreDefenseRatio))) * (1 - bulletIgnore);
    }
    if (ignoreDefenseRatio) {
      defenseStat = Math.max(1, Math.round(defenseStat * (1 - Math.max(0, Math.min(0.85, ignoreDefenseRatio)))));
    }
    if (side === "enemy") {
      activePlayerCarryContexts(player, battle).forEach((ctx) => {
        const defenderEffect = battleCarryItemEffect(ctx.item);
        if (defenderEffect.kind === "sdef_bonus_block_support_skills" && boardMoveIsSpecialDamage(moveEntry)) defenseStat = Math.round(defenseStat * Number(defenderEffect.sdefMultiplier || 1.4));
      });
    }
    const attackerBonus = side === "player" ? getTeamEffects(player) : null;
    const targetCard = side === "player" ? battle.enemyCombatant : battleActiveCard(player, battle);
    const targetMaxHp = side === "player"
      ? battle.enemyCombatant.maxHp
      : (targetCard?.baseStats?.hp || targetCard?.maxHp || targetCard?.hp || 1);
    const hitCount = comboDiceHitCount(maxHits, diceFace);
    let damage = pokemonStyleBaseDamage(side, battleActorLevel(side, player, battle), comboDamagePower(moveEntry), attackStat, defenseStat);
    damage = Math.round(damage * comboDiceMultiplier(diceFace, side));
    const attributeMultiplier = battleAttributeDamageMultiplier(side, moveEntry, attackerAttribute, defenderAttribute, player, battle);
    if (attributeMultiplier <= 0) return Array.from({ length: hitCount }, () => 0);
    damage = Math.round(damage * attributeMultiplier);
    const actorRound = side === "player" ? battle.playerRoundEffects : battle.enemyCombatant.roundEffects;
    if (actorRound?.nextHitBoost) damage = Math.round(damage * (1 + Number(actorRound.nextHitBoost || 0)));
    if (diceFace >= 5 && effects.amplifyOnHighDice) damage = Math.round(damage * (1 + Number(effects.amplifyOnHighDice)));
    if (effects.amplifyWhenLowHp) {
      const actorHp = Number(attackerCard?.currentHp ?? attackerCard?.hp ?? attackerCard?.maxHp ?? attackerCard?.baseStats?.hp ?? 1);
      const actorMaxHp = Number(attackerCard?.baseStats?.hp || attackerCard?.maxHp || attackerCard?.hp || 1);
      if (actorHp / Math.max(1, actorMaxHp) <= 0.5) damage = Math.round(damage * (1 + Number(effects.amplifyWhenLowHp)));
    }
    if (effects.amplifyVsControlled && isBattleTargetControlled(side, battle)) {
      damage = Math.round(damage * (1 + Number(effects.amplifyVsControlled)));
    }
    if (effects.bossDamageBonus && (battle.isJudicialRaid || battle.islandKind === "yonko" || targetCard?.tier === "T1" || targetCard?.rank === "S")) {
      damage = Math.round(damage * (1 + Number(effects.bossDamageBonus)));
    }
    if (effects.highHpDamageBonus) {
      const targetHp = Number(targetCard?.currentHp ?? targetCard?.hp ?? targetCard?.maxHp ?? targetCard?.baseStats?.hp ?? 1);
      if (targetHp / Math.max(1, targetMaxHp) >= 0.5) damage = Math.round(damage * (1 + Number(effects.highHpDamageBonus)));
    }
    damage = Math.round(damage * yonkoEnemyDamageMultiplier(side, moveEntry, player, battle));
    damage = Math.round(damage * finalGateEnemyDamageMultiplier(side, moveEntry, player, battle));
    damage = Math.round(damage * conditionalDamageMultiplier(side, moveEntry, attackerSide, defenderSide, player, battle));
    damage = Math.round(damage * characterPassiveDamageMultiplier(side, moveEntry, diceFace, player, battle));
    if (side === "player" && attackerCard?.roleType === "戰鬥型" && boardMoveIsPhysicalDamage(moveEntry)) {
      damage = Math.round(damage * (attackerBonus?.battleAttackMultiplier || 1.1));
    }
    if (side === "player") damage = applyPlayerCarryDamageModifiers(damage, moveEntry, diceFace, player, battle, attackerCard, visualMeta);
    const defenderEffects = side === "player" ? battle.enemyCombatant.roundEffects : battle.playerRoundEffects;
    let shieldRatio = Number(defenderEffects?.shieldRatio || 0);
    let fullShieldBlock = shieldRatio >= 1;
    if (shieldRatio && (effects.antiShieldBonus || piercesShield)) shieldRatio = Math.max(0, shieldRatio - Number(effects.antiShieldBonus || 1));
    fullShieldBlock = fullShieldBlock && shieldRatio >= 1;
    if (shieldRatio) damage = Math.round(damage * (1 - shieldRatio));
    if (defenderEffects?.damageTakenUp) damage = Math.round(damage * (1 + defenderEffects.damageTakenUp));
    if (side === "enemy") {
      damage = Math.round(damage * characterPassiveDamageTakenMultiplier(moveEntry, player, battle));
      damage = Math.round(damage * (1 - (getTeamEffects(player).supportDamageReduction || 0)));
      damage = Math.round(damage * Number(BATTLE_DAMAGE_TUNING.enemyDamageScale || 1));
    }
    const softCapRatio = BATTLE_DAMAGE_TUNING.comboHitSoftCapHpRatio;
    const softCap = Math.max(10, Math.round(targetMaxHp * Number(softCapRatio || 0.28)));
    if (damage > softCap) {
      damage = softCap + Math.round((damage - softCap) * BATTLE_DAMAGE_TUNING.softCapOverflowScale);
    }
    const hits = splitBattleDamageIntoHits(fullShieldBlock && damage <= 0 ? 0 : Math.max(1, damage), hitCount, bonusDamage);
    const progressedHits = applyPlayerCarryComboProgression(hits, side, moveEntry, player, battle);
    return resolveBattleCriticalHitDamages(progressedHits, side, moveEntry, player, battle, visualMeta);
  }

  function healBattleTarget(target, ratio, multiplier = 1) {
    if (!target || Number(target.currentHp || 0) <= 0) return 0;
    const maxHp = cardMaxHp(target);
    const before = Math.max(0, Number(target.currentHp || 0));
    const heal = Math.max(1, Math.round(maxHp * Number(ratio || 0) * Number(multiplier || 1)));
    target.currentHp = Math.min(maxHp, before + heal);
    return Math.max(0, target.currentHp - before);
  }

  function lowestLivingCrewCard(player) {
    return (player?.crew || [])
      .filter((card) => card && Number(card.currentHp || 0) > 0)
      .sort((a, b) => (Number(a.currentHp || 0) / cardMaxHp(a)) - (Number(b.currentHp || 0) / cardMaxHp(b)))[0] || null;
  }

  function clearStatusBag(bag) {
    Object.keys(emptyStatusEffects()).forEach((key) => {
      if (bag && Number(bag[key] || 0) > 0) bag[key] = 0;
    });
  }

  function applyBattleHealingEffects(moveEntry, side, diceFace, player, battle, phase, dealtDamage = 0) {
    const effects = moveEntry.effects || {};
    const actorCard = side === "player" ? battleActiveCard(player, battle) : battle.enemyCombatant;
    let multiplier = healDiceMultiplier(diceFace);
    multiplier *= characterPassiveHealMultiplier(side, player, battle);
    if (side === "player") activePlayerCarryContexts(player, battle).forEach((ctx) => {
      if (ctx.item?.id === "medical_bag") multiplier *= 1.25;
    });
    let totalHeal = 0;

    if (phase === "heal" && !effects.healLowestAllyRatio && !effects.healTeamRatio && !effects.reviveLowestAllyRatio) {
      totalHeal += healBattleTarget(actorCard, effects.healRatio || 0.2, multiplier);
    } else if (effects.healRatio && (phase === "status" || phase === "attack")) {
      totalHeal += healBattleTarget(actorCard, effects.healRatio, multiplier);
    }

    if (effects.healLowestAllyRatio && (phase === "heal" || phase === "status")) {
      const target = side === "player" ? lowestLivingCrewCard(player) : actorCard;
      totalHeal += healBattleTarget(target, effects.healLowestAllyRatio, multiplier);
    }

    if (effects.healTeamRatio && (phase === "heal" || phase === "status")) {
      if (side === "player") {
        (player?.crew || []).forEach((card) => {
          totalHeal += healBattleTarget(card, effects.healTeamRatio, multiplier);
        });
      } else {
        totalHeal += healBattleTarget(actorCard, effects.healTeamRatio, multiplier);
      }
    }

    if (effects.reviveLowestAllyRatio && (phase === "heal" || phase === "status")) {
      if (side === "player") {
        const revived = reviveOneCrewMember(player, Number(effects.reviveLowestAllyRatio || 0) * multiplier);
        if (revived) totalHeal += Number(revived.currentHp || 0);
      } else {
        totalHeal += healBattleTarget(actorCard, effects.reviveLowestAllyRatio, multiplier);
      }
    }

    if (phase === "attack" && dealtDamage > 0) {
      if (effects.drainRatio) totalHeal += healBattleTarget(actorCard, Math.max(0, Number(dealtDamage || 0) * Number(effects.drainRatio || 0)) / cardMaxHp(actorCard), multiplier);
      if (diceFace === 6 && effects.drainOnSixRatio) totalHeal += healBattleTarget(actorCard, Math.max(0, Number(dealtDamage || 0) * Number(effects.drainOnSixRatio || 0)) / cardMaxHp(actorCard), multiplier);
      if (diceFace === 6 && effects.healSelfOnSixRatio) totalHeal += healBattleTarget(actorCard, effects.healSelfOnSixRatio, multiplier);
      if (effects.healTeamRatioAfterHit) {
        if (side === "player") {
          (player?.crew || []).forEach((card) => {
            totalHeal += healBattleTarget(card, effects.healTeamRatioAfterHit, multiplier);
          });
        } else {
          totalHeal += healBattleTarget(actorCard, effects.healTeamRatioAfterHit, multiplier);
        }
      }
    }

    if (effects.regenSelfRatio && (phase === "heal" || phase === "status")) {
      const regen = side === "player"
        ? (battle.playerRegen ||= { ratio: 0, turns: 0 })
        : (battle.enemyCombatant.regen ||= { ratio: 0, turns: 0 });
      regen.ratio = Math.max(Number(regen.ratio || 0), Number(effects.regenSelfRatio || 0) * multiplier);
      regen.turns = Math.max(Number(regen.turns || 0), Number(effects.regenDuration || effects.duration || 3));
    }

    if (effects.cleanseSelf) clearStatusBag(battleStatusBag(side, battle));
    if (effects.cleanseTeam) clearStatusBag(battleStatusBag(side, battle));
    const medicalBagCtx = side === "player"
      ? activePlayerCarryContexts(player, battle).find((ctx) => ctx.item?.id === "medical_bag")
      : null;
    if (medicalBagCtx && totalHeal > 0) {
      const extra = healBattleTarget(medicalBagCtx.card, 0.05);
      if (extra > 0) {
        totalHeal += extra;
        battle.log.push(`${medicalBagCtx.card.name}的醫療背包追加回復 ${extra} HP。`);
      }
    }
    if (side === "enemy" && totalHeal > 0) {
      totalHeal = Math.max(0, totalHeal - clampYonkoEnemyHpToCurrentLayer(player, battle));
    }
    return totalHeal;
  }

  function applyMoveEffects(moveEntry, side, diceFace, player, battle, phase, dealtDamage = 0) {
    const effectDelta = statusDiceDelta(diceFace);
    if (side === "player") battle.playerEffectDice = diceFace;
    else battle.enemyEffectDice = diceFace;
    const actorCard = side === "player" ? battleActiveCard(player, battle) : battle.enemyCombatant;
    const actorStages = side === "player" ? battle.playerStages : battle.enemyCombatant.stages;
    const targetStages = side === "player" ? battle.enemyCombatant.stages : battle.playerStages;
    const actorStageTurns = side === "player" ? battle.playerStageTurns : battle.enemyCombatant.stageTurns;
    const targetStageTurns = side === "player" ? battle.enemyCombatant.stageTurns : battle.playerStageTurns;
    const actorRound = side === "player" ? battle.playerRoundEffects : battle.enemyCombatant.roundEffects;
    const targetRound = side === "player" ? battle.enemyCombatant.roundEffects : battle.playerRoundEffects;
    const stageDuration = normalizeEffectDuration(moveEntry.effects || {}, 3);
    const targetEffectsCanLand = phase !== "miss";

    if (moveEntry.effects?.selfStages) {
      if (side === "enemy") mirrorEnemyStageBoostWithCarry(moveEntry.effects.selfStages, effectDelta, player, battle);
      applyBattleCarryAwareStageSet(side, actorStages, moveEntry.effects.selfStages, effectDelta, actorStageTurns, stageDuration, player, battle);
    }
    if (targetEffectsCanLand && moveEntry.effects?.enemyStages) applyBattleCarryAwareStageSet(side === "player" ? "enemy" : "player", targetStages, moveEntry.effects.enemyStages, effectDelta, targetStageTurns, stageDuration, player, battle);
    if (phase === "attack" && moveEntry.effects?.enemyStagesOnHit) applyBattleCarryAwareStageSet(side === "player" ? "enemy" : "player", targetStages, moveEntry.effects.enemyStagesOnHit, effectDelta, targetStageTurns, stageDuration, player, battle);
    if (phase === "attack" && diceFace >= 5 && moveEntry.effects?.enemyStagesOnHighDice) applyBattleCarryAwareStageSet(side === "player" ? "enemy" : "player", targetStages, moveEntry.effects.enemyStagesOnHighDice, effectDelta, targetStageTurns, stageDuration, player, battle);
    if (phase === "attack" && diceFace === 6 && moveEntry.effects?.enemyStagesOnSix) applyBattleCarryAwareStageSet(side === "player" ? "enemy" : "player", targetStages, moveEntry.effects.enemyStagesOnSix, effectDelta, targetStageTurns, stageDuration, player, battle);
    if (phase === "attack" && diceFace >= 4 && moveEntry.effects?.enemyStagesOnEvenHighDice && diceFace % 2 === 0) applyBattleCarryAwareStageSet(side === "player" ? "enemy" : "player", targetStages, moveEntry.effects.enemyStagesOnEvenHighDice, effectDelta, targetStageTurns, stageDuration, player, battle);
    if (phase === "attack" && diceFace >= 5 && moveEntry.effects?.selfStagesOnHighDice) {
      if (side === "enemy") mirrorEnemyStageBoostWithCarry(moveEntry.effects.selfStagesOnHighDice, effectDelta, player, battle);
      applyBattleCarryAwareStageSet(side, actorStages, moveEntry.effects.selfStagesOnHighDice, effectDelta, actorStageTurns, stageDuration, player, battle);
    }
    if (phase === "attack" && moveEntry.effects?.selfStagesAfterUse) {
      if (side === "enemy") mirrorEnemyStageBoostWithCarry(moveEntry.effects.selfStagesAfterUse, effectDelta, player, battle);
      applyBattleCarryAwareStageSet(side, actorStages, moveEntry.effects.selfStagesAfterUse, effectDelta, actorStageTurns, stageDuration, player, battle);
    }
    if (phase === "attack" && moveEntry.effects?.bossStageOnHit) {
      const targetCard = side === "player" ? battle.enemyCombatant : battleActiveCard(player, battle);
      if (battle.isJudicialRaid || battle.islandKind === "yonko" || targetCard?.tier === "T1" || targetCard?.rank === "S") {
        applyBattleCarryAwareStageSet(side === "player" ? "enemy" : "player", targetStages, moveEntry.effects.bossStageOnHit, effectDelta, targetStageTurns, stageDuration, player, battle);
      }
    }
    if (moveEntry.effects?.shieldRatio) applyBattleShieldTiming(side, battle, characterPassiveShieldRatio(side, moveEntry.effects.shieldRatio, player, battle));
    if (moveEntry.effects?.teamShieldRatio) applyBattleShieldTiming(side, battle, characterPassiveShieldRatio(side, moveEntry.effects.teamShieldRatio, player, battle));
    if (moveEntry.effects?.negateNextHit) applyBattleShieldTiming(side, battle, 1);
    if (moveEntry.effects?.shieldRatioBeforeAttack) applyBattleShieldTiming(side, battle, moveEntry.effects.shieldRatioBeforeAttack);
    if (moveEntry.effects?.guaranteedEscape) actorRound.guaranteedEscape = true;
    if (moveEntry.effects?.guaranteedFirst) actorRound.guaranteedFirst = true;
    if (moveEntry.effects?.guaranteedFirstNextTurn) actorRound.nextGuaranteedFirst = true;
    if (phase === "attack" && diceFace >= 5 && moveEntry.effects?.priorityOnHighDice) actorRound.nextGuaranteedFirst = true;
    if (moveEntry.effects?.nextHitBoost) actorRound.nextHitBoost = Math.max(actorRound.nextHitBoost || 0, moveEntry.effects.nextHitBoost);
    if (targetEffectsCanLand && moveEntry.effects?.enemyDamageTakenUp) targetRound.damageTakenUp = Math.max(targetRound.damageTakenUp, moveEntry.effects.enemyDamageTakenUp);
    if (targetEffectsCanLand && moveEntry.effects?.enemyDiceMod) targetRound.diceCapDown = Math.max(targetRound.diceCapDown, Math.abs(moveEntry.effects.enemyDiceMod));
    if (targetEffectsCanLand && moveEntry.effects?.blockEnemyPriority) applyBattleCarryAwareStageSet(side === "player" ? "enemy" : "player", targetStages, { spd: -1 }, effectDelta, targetStageTurns, stageDuration, player, battle);
    if (moveEntry.effects?.fieldSpeedUp) actorRound.fieldSpeedUp = true;
    if (moveEntry.effects?.fieldWeather) battle.fieldWeather = moveEntry.effects.fieldWeather;
    if (moveEntry.effects?.fieldControl) battle.fieldControl = moveEntry.effects.fieldControl;
    if (moveEntry.effects?.reflectStatus) actorRound.reflectStatus = moveEntry.effects.reflectStatus;
    if (moveEntry.effects?.reflectRatio) actorRound.reflectRatio = Math.max(actorRound.reflectRatio || 0, moveEntry.effects.reflectRatio);
    if (targetEffectsCanLand && moveEntry.effects?.blockEnemyBuff) targetRound.controlLock = true;
    if (side === "player" && moveEntry.effects?.sanjiRaidSuitStealth) {
      const index = Number(battle?.activeCrewIndex ?? player?.activeCrewIndex ?? 0);
      const raidSuitState = sanjiRaidSuitFormState(actorCard, player, battle, index, false);
      if (raidSuitState) {
        raidSuitState.stealthReady = true;
        battle.log.push(`${sanjiRaidSuitDisplayName(actorCard, player, battle, index)}重新啟動光學迷彩；下一次敵方直接攻擊必定落空。`);
      }
    }
    if (moveEntry.effects?.selfHpCostRatio) {
      const maxHp = side === "player" ? cardMaxHp(actorCard) : Number(actorCard.maxHp || actorCard.hp || 1);
      const cost = Math.max(1, Math.round(maxHp * Number(moveEntry.effects.selfHpCostRatio || 0)));
      actorCard.currentHp = Math.max(1, Number(actorCard.currentHp || actorCard.hp || 1) - cost);
      if (side === "enemy") actorCard.hp = actorCard.currentHp;
      battle.log.push(`${battleSideName(side, player, battle)} 承受 ${cost} 點技能代價。`);
    }
    applyMoveStatusEffects(moveEntry, side, diceFace, player, battle, phase);
    const healingDone = applyBattleHealingEffects(moveEntry, side, diceFace, player, battle, phase, dealtDamage);
    applyYonkoMoveSpecialEffects(moveEntry, side, diceFace, player, battle, phase);
    applyFinalGateMoveSpecialEffects(moveEntry, side, diceFace, player, battle, phase);
    return healingDone;
  }

  function bonusDamageFromMove(moveEntry, diceFace, player, battle, side) {
    let bonus = 0;
    const actorCard = side === "player" ? battleActiveCard(player, battle) : battle.enemyCombatant;
    const targetAttribute = side === "player" ? battle.enemyCombatant.attribute : battleActiveCard(player, battle).attribute;
    if (diceFace >= 5 && moveEntry.effects?.bonusOnHighDice) bonus += moveEntry.effects.bonusOnHighDice;
    if (diceFace >= 5 && moveEntry.effects?.bonusOnHighDiceFlat) bonus += moveEntry.effects.bonusOnHighDiceFlat;
    if (diceFace >= 4 && diceFace % 2 === 0 && moveEntry.effects?.bonusOnEvenHighDice) bonus += moveEntry.effects.bonusOnEvenHighDice;
    if (diceFace >= 5 && diceFace % 2 === 1 && moveEntry.effects?.bonusOnOddHighDice) bonus += Math.round((moveEntry.power || 0) * moveEntry.effects.amplifyOnOddHighDice);
    if (moveEntry.effects?.flatBonusVsAttribute === targetAttribute) bonus += Math.round((moveEntry.power || 0) * (moveEntry.effects.amplifyVsAttribute || 0.1));
    if (diceFace === 6 && moveEntry.effects?.plusTwoOnSix) bonus += Math.round((actorCard.baseStats?.atk || actorCard.atk) * 2);
    if (moveEntry.effects?.bonusWhenFaster) {
      const actorSpeed = currentBattleStat(side === "player" ? "player" : "enemy", "spd", player, battle);
      const targetSpeed = currentBattleStat(side === "player" ? "enemy" : "player", "spd", player, battle);
      if (actorSpeed > targetSpeed) bonus += Number(moveEntry.effects.bonusWhenFaster || 0);
    }
    const targetStatuses = battleStatusBag(side === "player" ? "enemy" : "player", battle);
    const amplifyStatus = normalizeBattleStatus(moveEntry.effects?.amplifyVsStatus);
    if (amplifyStatus && Number(targetStatuses[amplifyStatus] || 0) > 0) {
      bonus += Math.round((moveEntry.power || 0) * Math.max(0, (moveEntry.effects.multiplier || 1.2) - 1));
    }
    if (moveEntry.effects?.amplifyVsLoweredSpeed) {
      const targetStages = side === "player" ? battle.enemyCombatant.stages : battle.playerStages;
      if ((targetStages?.spd || 0) < 0 || Number(targetStatuses.freeze || 0) > 0 || Number(targetStatuses.paralyze || 0) > 0) {
        bonus += Math.round((moveEntry.power || 0) * moveEntry.effects.amplifyVsLoweredSpeed);
      }
    }
    return bonus;
  }

  async function executeBattleAction(side, player, battle) {
    const action = side === "player" ? battle.playerAction : battle.enemyAction;
    if (!action || battle.result && battle.result !== "round-pause") return;
    if (side === "player") markBattleCrewParticipation(player, battle, battle.activeCrewIndex);
    if (side === "player" && action.type === "tot-dual") {
      await executeTotMusicaDualAction(player, battle, action);
      return;
    }
    const tesoroMechanic = postgameBossMechanicFor(battle);
    if (side === "player" && tesoroMechanic?.key === "postgame_gild_tesoro" && tesoroMechanic.cancelQueuedPlayerAction) {
      tesoroMechanic.cancelQueuedPlayerAction = false;
      battle.playerPerformedAction = true;
      recordJudicialRaidContribution(battle, player, { turnsActed: 1 });
      const cardName = battleActiveCard(player, battle)?.name || player.name;
      battle.log.push(`${cardName} 已完全黃金化，本輪預先選好的指令無法執行。`);
      renderBattleInterface();
      notifyBattleWindow();
      return;
    }
    if (postgameBossMechanicActionBlocked(side, player, battle)) {
      if (side === "player") battle.playerPerformedAction = true;
      else battle.enemyPerformedAction = true;
      renderBattleInterface();
      return;
    }
    if (side === "player" && action.type === "katakuri-defense") {
      const mechanic = postgameBossMechanicFor(battle);
      if (mechanic?.key !== "postgame_charlotte_katakuri" || mechanic.defenseActionKey !== action.actionKey) {
        battle.playerPerformedAction = true;
        battle.log.push("防禦判定已失去效力，本次行動結束。");
        renderBattleInterface();
        return;
      }
      if (await isBattleActionBlockedByStatus(side, player, battle)) {
        mechanic.defenseActionKey = "";
        mechanic.defenseReduction = 0;
        battle.playerPerformedAction = true;
        recordJudicialRaidContribution(battle, player, { turnsActed: 1 });
        battle.log.push(`${battleActiveCard(player, battle)?.name || player.name} 的防禦被異常狀態打斷，減傷沒有生效。`);
        renderBattleInterface();
        return;
      }
      battle.playerPerformedAction = true;
      battle.playerActionSummary = `防禦骰 ${mechanic.defenseDie}・減傷 ${Math.round(Number(mechanic.defenseReduction || 0) * 100)}%`;
      recordJudicialRaidContribution(battle, player, { turnsActed: 1 });
      battle.log.push(`${battleActiveCard(player, battle)?.name || player.name} 採取防禦姿態，減傷在速度判定前完成。`);
      renderBattleInterface();
      return;
    }
    if (side === "player" && action.type === "zephyr-disarm") {
      const mechanic = postgameBossMechanicFor(battle);
      if (mechanic?.key !== "postgame_zephyr" || !mechanic.countdownActive || mechanic.dynaRockDisarmed || mechanic.detonated) {
        battle.playerPerformedAction = true;
        battle.log.push("最後的炸藥岩目前不需要再處理，本次行動結束。");
        renderBattleInterface();
        return;
      }
      if (await isBattleActionBlockedByStatus(side, player, battle)) {
        battle.playerPerformedAction = true;
        recordJudicialRaidContribution(battle, player, { turnsActed: 1 });
        battle.log.push(`${battleActiveCard(player, battle)?.name || player.name} 的阻止引爆行動被異常狀態打斷。`);
        renderBattleInterface();
        return;
      }
      const activeCard = battleActiveCard(player, battle);
      const diceFace = await rollBattleActionDice(
        "move",
        `${cardDisplayName(activeCard)} 嘗試解除炸藥岩`,
        "骰到 5／6 可一次推進 2 點解除進度。",
        battle,
        6,
        { side: "player", moveType: "control" },
      );
      battle.playerDiceRoll = diceFace;
      postgameZephyrResolveDisarmRoll(player, battle, diceFace);
      battle.playerPerformedAction = true;
      recordJudicialRaidContribution(battle, player, { turnsActed: 1 });
      battle.visualEvent = attachBattleVisualEventSnapshots({
        id: `postgame-zephyr-disarm-${Date.now()}-${Math.random().toString(36).slice(2)}`,
        type: "status",
        side: "player",
        targetSide: "enemy",
        actorName: cardDisplayName(activeCard),
        moveName: mechanic.dynaRockDisarmed ? "炸藥岩解除成功" : "阻止引爆",
        moveType: "control",
        effectFx: { targetSide: "enemy", kind: "debuff", direction: "down", label: mechanic.dynaRockDisarmed ? "引爆解除" : `解除 ${mechanic.disarmProgress}/${POSTGAME_ZEPHYR_DISARM_TARGET}` },
        iconUrl: POSTGAME_ZEPHYR_DYNA_STONE_IMAGE,
        diceFace,
        duration: 1450,
      }, battle);
      notifyBattleWindow();
      await waitBattleWindowVisual(battle.visualEvent, 1450);
      renderBattleInterface();
      return;
    }
    if (side === "enemy" && battle.enemyCombatant?.roundEffects?.flinch) {
      battle.enemyPerformedAction = true;
      battle.log.push(`${battle.enemyCombatant.name} 畏縮，跳過了這次行動。`);
      renderBattleInterface();
      return;
    }
    if (side === "enemy" && postgameBossMechanicFor(battle)?.key === "postgame_tot_musica") {
      await executeTotMusicaEnemyAction(player, battle, action);
      return;
    }
    if (action.type === "switch") {
      const fromIndex = Number(battle.activeCrewIndex ?? player?.activeCrewIndex ?? 0);
      const fromName = action.fromName || battleActiveCard(player, battle)?.name || "";
      if (action.alreadyApplied && side === "player") {
        battle.playerPerformedAction = true;
      } else {
        applySwitchAction(side, action, player, battle);
      }
      if (side === "player") recordJudicialRaidContribution(battle, player, { turnsActed: 1 });
      const toName = action.toName || battleActiveCard(player, battle)?.name || "";
      if (side === "player") {
        battle.visualEvent = createBattleSwitchVisualEvent(player, battle, {
          fromIndex,
          toIndex: Number(action.nextIndex ?? battle.activeCrewIndex ?? player.activeCrewIndex ?? 0),
          fromName,
          toName,
          reason: "switch",
          duration: BATTLE_SWITCH_ENTRY_DISPLAY_MS,
        });
      }
      renderBattleInterface();
      if (!action.alreadyApplied) await playBattleSwitchAnimation(side, fromName, toName);
      if (side === "player" && ["switch", "sanji-raid-suit-transform"].includes(battle.visualEvent?.type)) {
        await waitBattleWindowVisual(battle.visualEvent, BATTLE_SWITCH_ENTRY_DISPLAY_MS);
      }
      renderBattleInterface();
      return;
    }
    if (action.type === "escape") {
      if (side === "player") {
        const teamEffects = getTeamEffects(player);
        const escapeThreshold = (battle.isJudicialRaid || battle.isMarineford || battle.noEscape || battle.isNoEscape) ? 0 : teamEffects.escapeThreshold || 0;
        const escapeRollBonus = Math.max(0, Math.round(Number(teamEffects.shipEscapeRollBonus || 0)));
        if (escapeThreshold > 0) {
          const baseEscapeRoll = await rollBattleActionDice("move", `${player.name} 嘗試逃跑`, `需要骰出 ${escapeThreshold}+ 才能脫離戰鬥。`, battle, 6, { side, moveType: "escape" });
          battle.pendingEscapeRollBase = baseEscapeRoll;
          battle.pendingEscapeRollBonus = escapeRollBonus;
          battle.pendingEscapeRoll = baseEscapeRoll + escapeRollBonus;
        } else {
          battle.pendingEscapeRoll = 0;
          battle.pendingEscapeRollBase = 0;
          battle.pendingEscapeRollBonus = 0;
          battle.log.push(`${player.name} 目前不能逃跑。`);
        }
      }
      applyEscapeAction(side, player, battle);
      if (side === "player") recordJudicialRaidContribution(battle, player, { turnsActed: 1 });
      await playBattleEscapeAnimation(battle.result === "escape");
      renderBattleInterface();
      return;
    }
    if (action.type === "item") {
      const targetPlayer = isCoopBattle(battle)
        ? coopBattleParticipants(battle).find((entry) => String(entry.id) === String(action.targetPlayerId || player.id)) || player
        : player;
      const beforeHp = isCoopBattle(battle)
        ? coopBattleParticipants(battle).reduce((sum, entry) => sum + (entry.crew || []).reduce((crewSum, card) => crewSum + Math.max(0, Number(card.currentHp || 0)), 0), 0)
        : Number(battleActiveCard(player, battle)?.currentHp || 0);
      const targetWasAwaitingRescue = isCoopBattle(battle) && coopBattleParticipantAwaitingRescue(targetPlayer, battle);
      applyBattleItemAction(side, action, player, battle);
      const afterHp = isCoopBattle(battle)
        ? coopBattleParticipants(battle).reduce((sum, entry) => sum + (entry.crew || []).reduce((crewSum, card) => crewSum + Math.max(0, Number(card.currentHp || 0)), 0), 0)
        : Number(battleActiveCard(player, battle)?.currentHp || 0);
      const targetRescued = targetWasAwaitingRescue && !coopBattleParticipantAwaitingRescue(targetPlayer, battle);
      if (side === "player") {
        recordJudicialRaidContribution(battle, player, {
          healingDone: Math.max(0, afterHp - beforeHp),
          turnsActed: 1,
          itemsUsed: battle.playerPerformedAction ? 1 : 0,
          rescuesDone: targetRescued ? 1 : 0,
        });
      }
      if (side === "player" && afterHp > beforeHp) {
        await playBattleHealAnimation("player", afterHp - beforeHp, getBattleVisualSnapshot(player, battle));
      } else if (side === "player") {
        await playBattleBuffAnimation("player", action.itemId === "guard_charm" ? "護盾展開" : "道具使用");
      }
      renderBattleInterface();
      return;
    }
    const moveEntry = getMoveByAction(side, action, player, battle);
    if (!moveEntry || (moveEntry.currentPP ?? 0) <= 0) return;
    if (await isBattleActionBlockedByStatus(side, player, battle)) {
      if (side === "player") battle.playerPerformedAction = true;
      else battle.enemyPerformedAction = true;
      if (side === "player") recordJudicialRaidContribution(battle, player, { turnsActed: 1 });
      battle.visualEvent = attachBattleVisualEventSnapshots({
        id: `blocked-${Date.now()}-${Math.random().toString(36).slice(2)}`,
        type: "status",
        side,
        targetSide: side,
        moveName: "行動受阻",
        moveType: "control",
        effectFx: { targetSide: side, kind: "debuff", direction: "down", label: "行動受阻" },
        duration: 1050,
      }, battle);
      notifyBattleWindow();
      await waitBattleWindowVisual(battle.visualEvent, 1050);
      renderBattleInterface();
      return;
    }
    if (side === "enemy") preparePlayerMoguraForEnemyMove(moveEntry, player, battle);
    moveEntry.currentPP -= 1;
    if (side === "player" && activeBlackbeardCaptureTurns(player, battle) > 0) {
      moveEntry.currentPP = Math.max(0, Number(moveEntry.currentPP || 0) - 1);
      battle.log.push(`${battleActiveCard(player, battle)?.name || player.name} 被黑暗捕獲，${moveEntry.name} 額外消耗 1 PP。`);
    }
    if (side === "player" && activeFinalGateBlackTurns(player, battle) > 0) {
      moveEntry.currentPP = Math.max(0, Number(moveEntry.currentPP || 0) - 1);
      battle.log.push(`${battleActiveCard(player, battle)?.name || player.name} 被黑轉支配，${moveEntry.name} 額外消耗 1 PP。`);
    }
    const actorRoundBeforeMove = side === "player" ? battle.playerRoundEffects : battle.enemyCombatant.roundEffects;
    if (actorRoundBeforeMove?.controlLock && moveEntry.category === "buff") {
      battle.log.push(`${battleSideName(side, player, battle)} 被封鎖，強化技無法發動。`);
      if (side === "player") battle.playerPerformedAction = true;
      else battle.enemyPerformedAction = true;
      renderBattleInterface();
      return;
    }
    const theme = battleDiceThemeForMove(moveEntry);
    battle.visualEvent = attachBattleVisualEventSnapshots({
      id: `prepare-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      type: "prepare",
      side,
      moveName: moveEntry.name,
      moveType: moveEntry.category || moveEntry.type || "attack",
    }, battle);
    notifyBattleWindow();
    await wait(520);
    let firstDiceFace = 0;
    const diceFace = await rollBattleActionDiceWithPassives(theme, `${side === "player" ? battleActiveCard(player, battle).name : battle.enemyCombatant.name} 使用 ${moveEntry.name}`, "決定招式最終效果…", battle, 6, {
      side,
      moveType: isComboBattleMove(moveEntry) ? "combo" : (moveEntry.category || moveEntry.type || "attack"),
      castSfx: battleCastSfxForMove(moveEntry),
      onFirstDie: (value) => { firstDiceFace = Number(value || 0); },
      onDiceResolved: side === "player"
        ? (dice, total) => settlePostgameOarsPrediction(player, battle, dice, total)
        : undefined,
    });
    if (side === "player") battle.playerDiceRoll = diceFace;
    else battle.enemyDiceRoll = diceFace;

    const katakuriMechanic = postgameBossMechanicFor(battle);
    if (side === "player" && katakuriMechanic?.key === "postgame_charlotte_katakuri") {
      const actionKey = postgameKatakuriActionKey(player, battle);
      const playerFirstDie = Math.max(1, Math.min(6, Number(firstDiceFace || diceFace || 1)));
      if (katakuriMechanic.forecastActionKey === actionKey && katakuriMechanic.choiceMode === "move" && katakuriMechanic.forecastDie > 0) {
        katakuriMechanic.lastPlayerFirstDie = playerFirstDie;
        if (playerFirstDie < Number(katakuriMechanic.forecastDie || 0)) {
          katakuriMechanic.lastOutcome = "predicted";
          battle.playerPerformedAction = true;
          battle.playerActionSummary = `${moveEntry.name}・被預知失效`;
          battle.playerRoundEffects.nextHitBoost = 0;
          recordJudicialRaidContribution(battle, player, { turnsActed: 1 });
          battle.log.push(`預知骰 ${katakuriMechanic.forecastDie} 高於 ${moveEntry.name} 的第一骰 ${playerFirstDie}；卡塔庫栗看穿未來，整招失效但 PP 已消耗。`);
          battle.visualEvent = attachBattleVisualEventSnapshots({
            id: `postgame-katakuri-predicted-${Date.now()}-${Math.random().toString(36).slice(2)}`,
            type: "status",
            side: "enemy",
            targetSide: "player",
            actorName: battle.enemyCombatant?.name || "卡塔庫栗",
            moveName: "預知未來",
            moveType: "control",
            effectFx: { targetSide: "player", kind: "debuff", direction: "down", label: `預見 ${katakuriMechanic.forecastDie}＞${playerFirstDie}` },
            diceFace: katakuriMechanic.forecastDie,
            duration: 1500,
          }, battle);
          notifyBattleWindow();
          await waitBattleWindowVisual(battle.visualEvent, 1500);
          renderBattleInterface();
          return;
        }
        katakuriMechanic.lastOutcome = "breakthrough";
        battle.log.push(`${moveEntry.name} 的第一骰 ${playerFirstDie} 達到預知骰 ${katakuriMechanic.forecastDie}，成功突破未來視；接著照原本命中與效果判定。`);
      }
    }

    if (battleMoveDealsDamage(moveEntry)) {
      const hitCheck = battleMoveHits(side, moveEntry, player, battle);
      let totalDamage = 0;
      let hitDamages = [];
      let hitSnapshots = [];
      let beforeDamageSnapshot = null;
      let knockedOutSide = "";
      let knockedOutName = "";
      let effectFx = null;
      const attackVisualMeta = { critical: false, criticalCount: 0 };
      if (hitCheck.hit) {
        beforeDamageSnapshot = getBattleVisualSnapshot(player, battle);
        if (moveEntry.effects?.dispelEnemyBuffs) {
          const targetSide = side === "player" ? "enemy" : "player";
          const cleared = clearPositiveBattleStages(targetSide, player, battle);
          if (cleared > 0) battle.log.push(`${battleSideName(targetSide, player, battle)} 的強化效果被解除。`);
        }
        prepareYonkoPlayerAttackResolution(side, moveEntry, diceFace, player, battle);
        const bonus = bonusDamageFromMove(moveEntry, diceFace, player, battle, side);
        if (isComboBattleMove(moveEntry)) {
          let maxHits = comboMoveMaxHits(moveEntry, diceFace);
          maxHits = battleCarryAdjustedMultiHit(side, moveEntry, diceFace, maxHits, player, battle);
          hitDamages = computeComboHitDamages(side, moveEntry, diceFace, maxHits, bonus, player, battle, attackVisualMeta);
        } else {
          const baseDamage = computeMoveDamage(side, moveEntry, diceFace, player, battle, attackVisualMeta);
          hitDamages = splitBattleDamageIntoHits(baseDamage, 1, bonus);
        }
        totalDamage = battleDamageHitTotal(hitDamages);
        resolvePermanentPointerAfterAttack(side, true, player, battle);
        if (side === "player") {
          totalDamage = applyOffensiveBattleCarryAfterHit(side, totalDamage, player, battle);
          totalDamage = applyShipOpeningFirstStrikeDamageBonus(totalDamage, player, battle, side);
          hitDamages = adjustBattleHitDamagesToTotal(hitDamages, totalDamage);
          hitDamages = applyYonkoPlayerHitDamageRules(hitDamages, side, moveEntry, diceFace, player, battle);
          hitDamages = applyPostgameBossDamageRules(hitDamages, side, moveEntry, diceFace, player, battle, action, attackVisualMeta);
          totalDamage = battleDamageHitTotal(hitDamages);
          const beforeHp = Number(battle.enemyCombatant.currentHp || 0);
          const cappedLayerDamage = capLayeredBossHitDamagesAtFirstHpBar(hitDamages, side, player, battle, beforeHp);
          if (cappedLayerDamage.capped) {
            hitDamages = cappedLayerDamage.hitDamages;
            totalDamage = cappedLayerDamage.totalDamage;
          }
          battle.enemyCombatant.currentHp = Math.max(0, beforeHp - totalDamage);
          const actualDamageDealt = Math.max(0, beforeHp - Number(battle.enemyCombatant.currentHp || 0));
          applyPlayerCarryAfterDirectAction(side, moveEntry, true, actualDamageDealt, diceFace, player, battle);
          postgameBossMechanicAfterDirectHit(side, moveEntry, diceFace, actualDamageDealt, player, battle, action);
          const mechanic = postgameBossMechanicFor(battle);
          if (mechanic?.key !== "postgame_aramaki") postgameBossMechanicPreventEnemyKnockout(player, battle);
          hitSnapshots = buildBattleHitSnapshots(beforeDamageSnapshot, "enemy", hitDamages);
          recordJudicialRaidContribution(battle, player, { damageDone: actualDamageDealt, turnsActed: 1 });
          if (battle.enemyCombatant.currentHp <= 0) {
            if (!canTriggerYonkoSecondHpBar(player, battle) && !canTriggerFinalGateSecondHpBar(player, battle)) {
              knockedOutSide = "enemy";
              knockedOutName = battle.enemyCombatant.name;
            }
          }
        } else {
          const activeCard = battleActiveCard(player, battle);
          totalDamage = applyDefensiveBattleCarryBeforeDamage("player", totalDamage, player, battle, attackVisualMeta);
          totalDamage = applyShipFirstBattleDamageReduction(totalDamage, player, battle);
          totalDamage = applyYonkoEnemyTotalDamageBeforeApply(totalDamage, side, moveEntry, player, battle);
          hitDamages = scaleBattleHitDamagesToTotal(hitDamages, totalDamage);
          hitDamages = applyPostgameBossDamageRules(hitDamages, side, moveEntry, diceFace, player, battle, action, attackVisualMeta);
          totalDamage = battleDamageHitTotal(hitDamages);
          const beforeHp = Number(activeCard.currentHp || 0);
          activeCard.currentHp = Math.max(0, beforeHp - totalDamage);
          hitSnapshots = buildBattleHitSnapshots(beforeDamageSnapshot, "player", hitDamages);
          const actualDamageTaken = Math.max(0, beforeHp - Number(activeCard.currentHp || 0));
          postgameBossMechanicAfterDirectHit(side, moveEntry, diceFace, actualDamageTaken, player, battle, action);
          recordJudicialRaidContribution(battle, player, { damageTaken: actualDamageTaken });
          storeBattleCarryDamageAfterHit("player", actualDamageTaken, player, battle);
          applyCharacterPassiveAfterDamageTaken(player, battle, activeCard, actualDamageTaken, moveEntry);
          applyYonkoEnemyHitAfterDamage(side, actualDamageTaken, moveEntry, diceFace, player, battle);
          applyFinalGateEnemyHitAfterDamage(side, actualDamageTaken, moveEntry, diceFace, player, battle);
          if (activeCard.currentHp <= 0 && tryPlayerBattleCarryRevive(player, battle, activeCard)) {
            hitSnapshots = buildBattleHitSnapshots(beforeDamageSnapshot, "player", hitDamages);
          } else if (activeCard.currentHp <= 0 && tryCharacterPassiveRevive(player, battle, activeCard)) {
            hitSnapshots = buildBattleHitSnapshots(beforeDamageSnapshot, "player", hitDamages);
          } else if (activeCard.currentHp <= 0) {
            knockedOutSide = "player";
            knockedOutName = activeCard.name;
          }
        }
        const defenderRound = side === "player" ? battle.enemyCombatant.roundEffects : battle.playerRoundEffects;
        if (defenderRound?.reflectStatus) {
          const label = applyBattleStatus(side, battle, defenderRound.reflectStatus, 2);
          if (label) battle.log.push(`${battleSideName(side, player, battle)} 受到反制，陷入${label}狀態。`);
        }
        if (Number(defenderRound?.reflectRatio || 0) > 0) {
          const reflectDamage = Math.max(1, Math.round(totalDamage * Number(defenderRound.reflectRatio)));
          if (side === "player") {
            const activeCard = battleActiveCard(player, battle);
            activeCard.currentHp = Math.max(0, activeCard.currentHp - reflectDamage);
            applyPlayerHpThresholdBattleCarryEffects(player, battle);
            battle.log.push(`${battle.enemyCombatant.name} 反彈 ${reflectDamage} 點傷害。`);
          } else {
            battle.enemyCombatant.currentHp = Math.max(0, battle.enemyCombatant.currentHp - reflectDamage);
            battle.log.push(`${battleActiveCard(player, battle).name} 反彈 ${reflectDamage} 點傷害。`);
          }
        }
        if (moveEntry.effects?.recoilRatio) {
          const recoilDamage = Math.max(1, Math.round(totalDamage * Number(moveEntry.effects.recoilRatio)));
          if (side === "player") {
            const activeCard = battleActiveCard(player, battle);
            activeCard.currentHp = Math.max(0, activeCard.currentHp - recoilDamage);
            applyPlayerHpThresholdBattleCarryEffects(player, battle);
          } else {
            battle.enemyCombatant.currentHp = Math.max(0, battle.enemyCombatant.currentHp - recoilDamage);
          }
          battle.log.push(`${battleSideName(side, player, battle)} 承受 ${recoilDamage} 點反作用傷害。`);
        }
        const healingDone = applyMoveEffects(moveEntry, side, diceFace, player, battle, "attack", totalDamage);
        postgameBossMechanicAfterMove(side, moveEntry, diceFace, true, totalDamage, player, battle, firstDiceFace);
        if (side === "player" && queuePostgameAramakiRevival(battle)) {
          knockedOutSide = "";
          knockedOutName = "";
        }
        applyYonkoPlayerHitAfterDamage(side, totalDamage, moveEntry, diceFace, player, battle);
        applyFinalGatePlayerHitAfterDamage(side, totalDamage, moveEntry, diceFace, player, battle);
        effectFx = battleVisualEffectForMove(moveEntry, side, "attack", healingDone, diceFace);
        if (side === "player" && healingDone > 0) recordJudicialRaidContribution(battle, player, { healingDone });
        battle.log.push(`${side === "player" ? player.name : "敵人"} 使用 ${moveEntry.name}，骰出 ${diceFace}，造成 ${totalDamage} 點傷害${battleHitBreakdownText(hitDamages)}。`);
      } else {
        applyMoveEffects(moveEntry, side, diceFace, player, battle, "miss", 0);
        postgameBossMechanicAfterMove(side, moveEntry, diceFace, false, 0, player, battle, firstDiceFace);
        if (side === "player") applyPlayerCarryAfterDirectAction(side, moveEntry, false, 0, diceFace, player, battle);
        if (side === "player") applyYonkoPlayerAfterActionNoDamage(player, battle);
        resolvePermanentPointerAfterAttack(side, false, player, battle);
        if (side === "player") applyPlayerMissBattleCarryEffects(player, battle);
        if (side === "player") recordJudicialRaidContribution(battle, player, { turnsActed: 1 });
        battle.log.push(`${side === "player" ? player.name : "敵人"} 使用 ${moveEntry.name}，命中率 ${hitCheck.chance}%，攻擊落空。`);
      }
      clearPendingYonkoAttack(battle);
      const actorRound = side === "player" ? battle.playerRoundEffects : battle.enemyCombatant.roundEffects;
      actorRound.nextHitBoost = 0;
      await playBattleActionAnimation({
        side,
        actorName: side === "player" ? battleActiveCard(player, battle).name : battle.enemyCombatant.name,
        targetName: side === "player" ? battle.enemyCombatant.name : battleActiveCard(player, battle).name,
        moveEntry,
        diceFace,
        damage: totalDamage,
        hitDamages,
        hitSnapshots,
        resultText: hitCheck.hit ? `造成 ${totalDamage} 點傷害` : "MISS",
        snapshot: getBattleVisualSnapshot(player, battle),
        player,
        battle,
      });
      const baseAttackVisualDuration = hitCheck.hit && hitDamages.length > 1
        ? Math.max(1850, 1250 + hitDamages.length * 620)
        : 1850;
      const isLucciRokuoganVisual = side === "enemy" && moveEntry.id === "postgame_lucci_ultimate_rokuogan";
      const attackVisualDuration = isLucciRokuoganVisual
        ? 7600
        : hitCheck.hit && effectFx
          ? baseAttackVisualDuration + 1900
          : baseAttackVisualDuration;
      const hitEffectFile = hitCheck.hit ? battleHitEffectForMove(moveEntry, diceFace, hitDamages) : "";
      const attackStartSnapshot = beforeDamageSnapshot || getBattleVisualSnapshot(player, battle);
      const attackFinalSnapshot = getBattleVisualSnapshot(player, battle);
      const attackTargetSide = side === "player" ? "enemy" : "player";
      battle.visualEvent = {
        id: `attack-${Date.now()}-${Math.random().toString(36).slice(2)}`,
        type: "attack",
        side,
        targetSide: attackTargetSide,
        actorName: side === "player" ? battleActiveCard(player, battle)?.name || player.name : battle.enemyCombatant?.name || "敵人",
        targetName: side === "player" ? battle.enemyCombatant?.name || "敵人" : battleActiveCard(player, battle)?.name || player.name,
        actorCombatant: battleVisualSnapshotSide(attackFinalSnapshot, side),
        targetCombatant: battleVisualSnapshotSide(attackFinalSnapshot, attackTargetSide),
        startCombatant: battleVisualSnapshotSide(attackStartSnapshot, attackTargetSide),
        startSnapshot: safeJsonClone(attackStartSnapshot),
        finalSnapshot: safeJsonClone(attackFinalSnapshot),
        moveName: moveEntry.name,
        moveType: moveEntry.category || moveEntry.type || "attack",
        specialFx: isLucciRokuoganVisual ? "lucci-rokuogan" : "",
        voiceSfx: isLucciRokuoganVisual ? "audio/board_game/sfx/postgame_boss/lucci_rokuogan/lucci_rokuogan_call.mp3" : "",
        hitVoiceSfx: isLucciRokuoganVisual ? "audio/board_game/sfx/postgame_boss/lucci_rokuogan/lucci_rokuogan_hit.mp3" : "",
        damage: totalDamage,
        hitDamages,
        critical: !!attackVisualMeta.critical,
        criticalCount: Math.max(0, Number(attackVisualMeta.criticalCount || 0)),
        criticalHitIndexes: Array.isArray(attackVisualMeta.criticalHitIndexes) ? attackVisualMeta.criticalHitIndexes.slice() : [],
        fatalGuard: !!attackVisualMeta.fatalGuard,
        fatalGuardLabel: String(attackVisualMeta.fatalGuardLabel || ""),
        fatalGuardItemName: String(attackVisualMeta.fatalGuardItemName || ""),
        kyubiMaskActive: !!attackVisualMeta.kyubiMaskActive,
        kyubiMaskLabel: String(attackVisualMeta.kyubiMaskLabel || ""),
        kingFlameGuarded: !!attackVisualMeta.kingFlameGuarded,
        kingFlameGuardLabel: String(attackVisualMeta.kingFlameGuardLabel || ""),
        katakuriDefenseActive: !!attackVisualMeta.katakuriDefenseActive,
        katakuriDefensePercent: Math.max(0, Number(attackVisualMeta.katakuriDefensePercent || 0)),
        judgeCloneBlocks: Array.isArray(attackVisualMeta.judgeCloneBlocks) ? attackVisualMeta.judgeCloneBlocks.slice() : [],
        judgeCloneCountBefore: Math.max(0, Number(attackVisualMeta.judgeCloneCountBefore || 0)),
        judgeCloneCountAfter: Math.max(0, Number(attackVisualMeta.judgeCloneCountAfter || 0)),
        judgeCloneTargetId: String(attackVisualMeta.judgeCloneTargetId || ""),
        shikiIslandId: String(attackVisualMeta.shikiIslandId || ""),
        shikiIslandName: String(attackVisualMeta.shikiIslandName || ""),
        shikiIslandDamage: Math.max(0, Number(attackVisualMeta.shikiIslandDamage || 0)),
        shikiIslandHitDamages: Array.isArray(attackVisualMeta.shikiIslandHitDamages) ? attackVisualMeta.shikiIslandHitDamages.slice() : [],
        shikiIslandHitTargetIds: Array.isArray(attackVisualMeta.shikiIslandHitTargetIds) ? attackVisualMeta.shikiIslandHitTargetIds.slice() : [],
        shikiIslandHitTargetNames: Array.isArray(attackVisualMeta.shikiIslandHitTargetNames) ? attackVisualMeta.shikiIslandHitTargetNames.slice() : [],
        shikiIslandHitDestroyed: Array.isArray(attackVisualMeta.shikiIslandHitDestroyed) ? attackVisualMeta.shikiIslandHitDestroyed.slice() : [],
        shikiIslandBreaks: Array.isArray(attackVisualMeta.shikiIslandBreaks) ? safeJsonClone(attackVisualMeta.shikiIslandBreaks) : [],
        shikiIslandVisualIslands: Array.isArray(attackVisualMeta.shikiIslandVisualIslands) ? safeJsonClone(attackVisualMeta.shikiIslandVisualIslands) : [],
        shikiIslandDestroyed: !!attackVisualMeta.shikiIslandDestroyed,
        hitEffect: hitEffectFile,
        hitSfx: hitCheck.hit ? battleHitSfxForMove(moveEntry, hitEffectFile) : "",
        startHp: beforeDamageSnapshot ? {
          player: beforeDamageSnapshot.player?.currentHp ?? null,
          enemy: beforeDamageSnapshot.enemy?.currentHp ?? null,
        } : null,
        finalHp: {
          player: battleActiveCard(player, battle)?.currentHp ?? null,
          enemy: battle.enemyCombatant?.currentHp ?? null,
        },
        diceFace,
        miss: !hitCheck.hit,
        raidSuitStealth: !!hitCheck.raidSuitStealth,
        effectFx,
        duration: attackVisualDuration,
      };
      notifyBattleWindow();
      await waitBattleWindowVisual(battle.visualEvent, attackVisualDuration);
      await resolvePostgameTesoroPhaseTransition(player, battle);
      if (Number(battle.enemyCombatant?.currentHp || 0) <= 0) queuePostgameAramakiRevival(battle);
      if (await resolvePostgameAramakiRevival(player, battle)) {
        knockedOutSide = "";
        knockedOutName = "";
      }
      if ((battle.openingPassiveVisualQueue || []).some((event) => event?.type === "postgame-saga-fusion")) {
        await playOpeningPassiveVisualsIfNeeded(player, battle);
      }
      const transitionedYonkoPhase = await applyYonkoPhaseTransitions(player, battle);
      if (transitionedYonkoPhase) {
        knockedOutSide = "";
        knockedOutName = "";
      }
      if (!transitionedYonkoPhase && !knockedOutSide && canTriggerFinalGateSecondHpBar(player, battle)) {
        await applyFinalGatePhaseTransitions(player, battle);
      }
      renderBattleInterface();
      if (knockedOutSide) {
        if (knockedOutSide === "player") {
          const pendingAwakeningCard = battleActiveCard(player, battle);
          if (pendingAwakeningCard && canTriggerLuffyGearFifthAwakening(player, battle, pendingAwakeningCard)) {
            battle.luffyGearFifthAwakeningPending = true;
            battle.keepPlayerPortraitOnKnockout = true;
            renderBattleInterface();
            notifyBattleWindow();
          }
        }
        await wait(1450);
        const knockoutEvent = emitBattleKnockoutEvent(knockedOutSide, battle, knockedOutName);
        await waitBattleWindowVisual(knockoutEvent, 4250);
      }
    } else if (moveEntry.category === "heal") {
      const baseHeal = applyMoveEffects(moveEntry, side, diceFace, player, battle, "heal", 0);
      postgameBossMechanicAfterMove(side, moveEntry, diceFace, true, 0, player, battle, firstDiceFace);
      const effectFx = battleVisualEffectForMove(moveEntry, side, "heal", baseHeal, diceFace);
      if (side === "player") recordJudicialRaidContribution(battle, player, { healingDone: baseHeal, turnsActed: 1 });
      battle.log.push(`${side === "player" ? player.name : "敵人"} 使用 ${moveEntry.name}，骰出 ${diceFace}，恢復 ${baseHeal} 生命。`);
      await playBattleActionAnimation({
        side,
        actorName: side === "player" ? battleActiveCard(player, battle).name : battle.enemyCombatant.name,
        targetName: side === "player" ? battleActiveCard(player, battle).name : battle.enemyCombatant.name,
        moveEntry,
        diceFace,
        amount: baseHeal,
        resultText: `恢復 ${baseHeal} HP`,
        snapshot: getBattleVisualSnapshot(player, battle),
        player,
        battle,
      });
      battle.visualEvent = attachBattleVisualEventSnapshots({
        id: `heal-${Date.now()}-${Math.random().toString(36).slice(2)}`,
        type: "heal",
        side,
        moveName: moveEntry.name,
        moveType: moveEntry.category || moveEntry.type || "heal",
        amount: baseHeal,
        diceFace,
        effectFx,
        duration: 1350,
      }, battle);
      notifyBattleWindow();
      await waitBattleWindowVisual(battle.visualEvent, 1350);
      renderBattleInterface();
    } else {
      const healingDone = applyMoveEffects(moveEntry, side, diceFace, player, battle, "status", 0);
      postgameBossMechanicAfterMove(side, moveEntry, diceFace, true, 0, player, battle, firstDiceFace);
      const effectFx = battleVisualEffectForMove(moveEntry, side, "status", healingDone, diceFace);
      if (side === "player") recordJudicialRaidContribution(battle, player, { healingDone, turnsActed: 1 });
      battle.log.push(`${side === "player" ? player.name : "敵人"} 使用 ${moveEntry.name}，骰出 ${diceFace}，${healingDone > 0 ? `恢復 ${healingDone} 生命。` : "狀態效果已套用。"}`);
      await playBattleActionAnimation({
        side,
        actorName: side === "player" ? battleActiveCard(player, battle).name : battle.enemyCombatant.name,
        targetName: healingDone > 0
          ? (side === "player" ? battleActiveCard(player, battle).name : battle.enemyCombatant.name)
          : (side === "player" ? battle.enemyCombatant.name : battleActiveCard(player, battle).name),
        moveEntry,
        diceFace,
        amount: healingDone,
        resultText: healingDone > 0 ? `恢復 ${healingDone} HP` : "狀態效果已套用",
        snapshot: getBattleVisualSnapshot(player, battle),
        player,
        battle,
      });
      battle.visualEvent = attachBattleVisualEventSnapshots({
        id: `status-${Date.now()}-${Math.random().toString(36).slice(2)}`,
        type: "status",
        side,
        moveName: moveEntry.name,
        moveType: moveEntry.category || moveEntry.type || "status",
        amount: healingDone,
        diceFace,
        effectFx,
        duration: 1250,
      }, battle);
      notifyBattleWindow();
      await waitBattleWindowVisual(battle.visualEvent, 1250);
      renderBattleInterface();
    }

    if (side === "player") battle.playerPerformedAction = true;
    else battle.enemyPerformedAction = true;
    if (battle.isJudicialRaid) {
      const raid = ensureJudicialRaidState();
      raid.enemyCurrentHp = Math.max(0, Math.min(raid.enemyMaxHp || battle.enemyCombatant.maxHp || 1, battle.enemyCombatant.currentHp ?? raid.enemyCurrentHp));
      raid.enemyStages = battle.enemyCombatant.stages || raid.enemyStages || emptyStages();
      raid.enemyStageTurns = battle.enemyCombatant.stageTurns || raid.enemyStageTurns || emptyStageTurns();
      raid.enemyStatuses = battle.enemyCombatant.statuses || raid.enemyStatuses || emptyStatusEffects();
    }

    if (await applyYonkoPhaseTransitions(player, battle)) {
      renderBattleInterface();
      notifyBattleWindow();
    }
    if (await handleKnockoutAfterActionWithAwakening(player, battle)) return;
    postgameBossMechanicPreventEnemyKnockout(player, battle);
    if (battle.enemyCombatant.currentHp <= 0) {
      battle.result = "win";
      battle.log.push("戰鬥勝利。");
    }
  }

  function isSClassOrAboveBattleEnemy(battle) {
    const enemy = battle?.enemyCombatant || {};
    const rawTier = enemy.tier || enemy.rank || battle?.enemyTier || "";
    const label = tierLabel(rawTier);
    if (/^S/i.test(String(rawTier || "")) || /^S/i.test(String(label || ""))) return true;
    if (battle?.isYonko || battle?.isFinalGate || battle?.isFinalBoss || enemy.isFinalBoss) return true;
    return tierRank(rawTier) <= tierRank("T1");
  }

  function canTriggerLuffyGearFifthAwakening(player, battle, card) {
    if (!player || !battle || !card) return false;
    if (card.id !== "luffy") return false;
    if (battle.luffyGearFifthAwakeningUsed) return false;
    if (activeEvolutionForm(card)?.id !== LUFFY_GEAR_FOURTH_FORM_ID) return false;
    if (Number(card.level || 1) <= 50) return false;
    if ((card.unlockedEvolutionFormIds || []).includes(LUFFY_GEAR_FIFTH_FORM_ID)) return false;
    return isSClassOrAboveBattleEnemy(battle);
  }

  function firstPortraitSource(portraits = {}) {
    return portraits.morale
      || portraits.normal
      || portraits.idle
      || portraits.attack
      || portraits.damage
      || Object.values(portraits).find(Boolean)
      || "";
  }

  function createLuffyGearFifthLayer(extraClass = "") {
    const layer = document.createElement("div");
    layer.className = `luffy-gear-fifth-layer ${extraClass}`.trim();
    layer.setAttribute("role", "presentation");
    Object.assign(layer.style, {
      position: "fixed",
      inset: "0",
      zIndex: "99999",
      display: "grid",
      placeItems: "center",
      background: "radial-gradient(circle at center, rgba(255,255,255,.18), rgba(15,16,24,.94) 46%, #000 100%)",
      color: "#fff",
      overflow: "hidden",
      opacity: "1",
      transition: "opacity .55s ease",
      fontFamily: "'Noto Sans TC', 'Microsoft JhengHei', sans-serif",
    });
    const style = document.createElement("style");
    style.textContent = `
      @keyframes luffyGearFifthHeartbeat {
        0%, 100% { transform: translate(-50%, -50%) scale(.72); opacity: .12; }
        42% { transform: translate(-50%, -50%) scale(1.05); opacity: .82; }
        58% { transform: translate(-50%, -50%) scale(.92); opacity: .38; }
      }
      @keyframes luffyGearFifthFlash {
        0%, 100% { opacity: .08; }
        50% { opacity: .42; }
      }
      @keyframes luffyGearFifthFloat {
        0%, 100% { transform: translateY(0); }
        50% { transform: translateY(-12px); }
      }
      @keyframes luffyGearFifthTextIn {
        from { opacity: 0; transform: translateY(12px); }
        to { opacity: 1; transform: translateY(0); }
      }
      @keyframes luffyGearFifthBattleVideoCuts {
        0%, 12.5% { opacity: 1; }
        13.2%, 16.8% { opacity: 0; }
        17.5%, 32.5% { opacity: 1; }
        33.2%, 36.8% { opacity: 0; }
        37.5%, 52.5% { opacity: 1; }
        53.2%, 56.8% { opacity: 0; }
        57.5%, 72.5% { opacity: 1; }
        73.2%, 76.8% { opacity: 0; }
        77.5%, 100% { opacity: 1; }
        100% { opacity: 1; }
      }
      @keyframes luffyGearFifthBattlePulseCuts {
        0%, 12.5% { opacity: 0; }
        13.2%, 16.8% { opacity: 1; }
        17.5%, 32.5% { opacity: 0; }
        33.2%, 36.8% { opacity: 1; }
        37.5%, 52.5% { opacity: 0; }
        53.2%, 56.8% { opacity: 1; }
        57.5%, 72.5% { opacity: 0; }
        73.2%, 76.8% { opacity: 1; }
        77.5%, 100% { opacity: 0; }
        100% { opacity: 0; }
      }
      @keyframes luffyGearFifthNearDeathPulse {
        0%, 100% { transform:translate(-50%, -50%) scale(.88); opacity:.2; }
        42% { transform:translate(-50%, -50%) scale(1.08); opacity:.76; }
        62% { transform:translate(-50%, -50%) scale(.98); opacity:.34; }
      }
    `;
    layer.appendChild(style);
    document.body.appendChild(layer);
    return layer;
  }

  function fadeOutAndRemoveLayer(layer, delay = 560) {
    if (!layer) return;
    layer.style.opacity = "0";
    window.setTimeout(() => layer.remove(), delay);
  }

  function emitLuffyGearFifthBattleHeartbeat(battle, duration = 920) {
    if (!battle) return;
    battle.visualEvent = {
      id: `nika-heartbeat-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      type: "nika-heartbeat",
      side: "player",
      duration,
    };
    notifyBattleWindow();
  }

  async function playLuffyGearFifthBattleHeartbeat(battle, duration = 920) {
    emitLuffyGearFifthBattleHeartbeat(battle, duration);
    await wait(duration + 180);
  }

  async function playLuffyGearFifthDeathTransition(card, battle) {
    await playLuffyGearFifthBattleHeartbeat(battle, 920);
  }

  async function playLuffyGearFifthPostEvolutionEffect(details = {}) {
    if (typeof document === "undefined" || !document.body) return;
    const layer = createLuffyGearFifthLayer("post-evolution");
    const beforeSrc = escapeModalText(firstPortraitSource(details.beforePortraits));
    const afterSrc = escapeModalText(firstPortraitSource(details.afterPortraits));
    const beforeName = escapeModalText(details.beforeName || "魯夫");
    const afterName = escapeModalText(details.afterName || "五檔・尼卡");
    layer.innerHTML += `
      <div style="position:absolute; inset:-12%; background:
        radial-gradient(circle at 50% 48%, rgba(255,255,255,.64), rgba(255,255,255,.16) 18%, transparent 39%),
        conic-gradient(from 20deg, rgba(255,255,255,.16), transparent 22%, rgba(255,231,141,.18), transparent 55%, rgba(255,255,255,.24), transparent 78%);
        filter:blur(1px); animation:luffyGearFifthFlash .9s ease-in-out infinite;"></div>
      <div style="position:absolute; inset:0; background:linear-gradient(180deg, rgba(0,0,0,.02), rgba(0,0,0,.34) 54%, rgba(0,0,0,.86));"></div>
      <div style="position:relative; width:min(1080px,94vw); height:min(680px,88vh); display:grid; grid-template-rows:1fr 164px; gap:18px; align-items:end;">
        <div style="position:relative; min-height:0; display:flex; justify-content:center; align-items:end;">
          <div style="position:absolute; left:8%; bottom:5%; width:min(30vw,250px); aspect-ratio:.72; opacity:.32; filter:grayscale(1) brightness(.7) blur(.2px);">
            ${beforeSrc ? `<img src="${beforeSrc}" alt="${beforeName}" style="width:100%; height:100%; object-fit:contain;" onerror="this.style.display='none';">` : ""}
          </div>
          <div style="position:absolute; inset:auto 0 7% 0; margin:auto; width:min(52vw,520px); aspect-ratio:1; border-radius:50%; border:2px solid rgba(255,255,255,.42); box-shadow:0 0 70px rgba(255,255,255,.55), inset 0 0 70px rgba(255,255,255,.32); animation:luffyGearFifthHeartbeat 1.08s ease-in-out infinite;"></div>
          <div style="position:relative; z-index:2; width:min(45vw,410px); height:min(66vh,560px); display:grid; place-items:end center; animation:luffyGearFifthFloat 2.1s ease-in-out infinite;">
            ${afterSrc ? `<img src="${afterSrc}" alt="${afterName}" style="max-width:100%; max-height:100%; object-fit:contain; filter:drop-shadow(0 0 34px rgba(255,255,255,.72));" onerror="this.style.display='none'; this.parentElement.querySelector('[data-nika-fallback]').style.display='grid';">` : ""}
            <div data-nika-fallback style="${afterSrc ? "display:none;" : "display:grid;"} place-items:center; width:min(44vw,360px); aspect-ratio:1; border-radius:50%; border:3px solid rgba(255,255,255,.58); background:rgba(255,255,255,.16); box-shadow:0 0 70px rgba(255,255,255,.68); font-size:clamp(26px,4vw,54px); font-weight:950;">五檔<br>尼卡</div>
          </div>
        </div>
        <div style="position:relative; width:100%; min-height:164px; border:1px solid rgba(255,255,255,.34); border-radius:18px; background:linear-gradient(180deg, rgba(6,8,16,.9), rgba(0,0,0,.76)); box-shadow:0 22px 70px rgba(0,0,0,.48), inset 0 1px rgba(255,255,255,.18); padding:22px 30px; display:grid; align-content:center; gap:10px;">
          <div style="font-size:clamp(16px,1.9vw,22px); font-weight:900; color:#ffeeb3;">羅賓</div>
          <div style="font-size:clamp(21px,2.7vw,34px); font-weight:900; line-height:1.38; text-shadow:0 2px 16px rgba(0,0,0,.55);">不，這不是單純的復活。這是解放之鼓。</div>
          <div style="font-size:clamp(18px,2.1vw,26px); font-weight:850; color:rgba(255,255,255,.82);">魯夫：「嘻嘻……我還能打。五檔・尼卡！」</div>
        </div>
      </div>
    `;
    await wait(5200);
    fadeOutAndRemoveLayer(layer);
    await wait(560);
  }

  function silenceBgmForLuffyGearFifthVideo() {
    const manager = window.BgmManager;
    if (!manager) return { ready: Promise.resolve(), restore: () => {} };
    const previousStatus = typeof manager.status === "function" ? manager.status() : {};
    const shouldResume = previousStatus.enabled !== false && !!previousStatus.currentChoice;
    luffyGearFifthVideoBgmPaused = true;
    const unlockAutoSwitch = manager.lockAutoSwitch?.("luffy-gear-fifth-video");
    const ready = Promise.resolve(manager.fadeOut?.(0)).catch(() => {});
    let restored = false;
    return {
      ready,
      restore() {
        if (restored) return;
        restored = true;
        luffyGearFifthVideoBgmPaused = false;
        try {
          unlockAutoSwitch?.();
        } catch (_error) {}
        const latestStatus = typeof manager.status === "function" ? manager.status() : {};
        if (!shouldResume || latestStatus.enabled === false) return;
        try {
          void manager.fadeIn?.(520);
          window.setTimeout(() => refreshBgmForState({ force: false }), 640);
        } catch (_error) {
          refreshBgmForState({ force: true });
        }
      },
    };
  }

  async function playLuffyGearFifthAwakeningVideo(details = {}) {
    if (typeof document === "undefined" || !document.body) return;
    const bgmHold = silenceBgmForLuffyGearFifthVideo();
    await bgmHold.ready;
    try {
      await new Promise((resolve) => {
      const battle = details.battle || state.battleState;
      const layer = createLuffyGearFifthLayer("video");
      layer.style.background = "transparent";
      layer.style.display = "block";
      layer.style.placeItems = "unset";
      layer.style.padding = "0";
      layer.style.boxSizing = "border-box";
      const videoBackdrop = document.createElement("div");
      Object.assign(videoBackdrop.style, {
        position: "absolute",
        inset: "0",
        background: "#000",
        animation: "luffyGearFifthBattleVideoCuts 30s linear forwards",
      });
      const videoFrame = document.createElement("div");
      Object.assign(videoFrame.style, {
        position: "absolute",
        inset: "0",
        zIndex: "1",
        width: "100%",
        height: "100%",
        display: "block",
        overflow: "visible",
        background: "#000",
        boxSizing: "border-box",
        animation: "luffyGearFifthBattleVideoCuts 30s linear forwards",
      });
      const video = document.createElement("video");
      video.src = LUFFY_GEAR_FIFTH_VIDEO_SRC;
      video.playsInline = true;
      video.preload = "auto";
      video.autoplay = true;
      video.controls = false;
      Object.assign(video.style, {
        position: "absolute",
        inset: "0",
        margin: "auto",
        width: "100%",
        height: "100%",
        maxWidth: "100%",
        maxHeight: "100%",
        objectFit: "contain",
        objectPosition: "center center",
        background: "#000",
        display: "block",
      });
      const fallback = document.createElement("div");
      fallback.textContent = "解放之鼓響起。五檔・尼卡覺醒。";
      Object.assign(fallback.style, {
        position: "absolute",
        left: "50%",
        bottom: "8%",
        transform: "translateX(-50%)",
        padding: "14px 22px",
        borderRadius: "999px",
        background: "rgba(0,0,0,.58)",
        border: "1px solid rgba(255,255,255,.35)",
        fontWeight: "900",
        letterSpacing: ".08em",
        textShadow: "0 2px 12px rgba(0,0,0,.75)",
        opacity: "0",
        zIndex: "4",
        transition: "opacity .35s ease",
      });
      videoFrame.appendChild(video);
      layer.append(videoBackdrop, videoFrame, fallback);
      let done = false;
      let metadataLoaded = false;
      let failTimer = null;
      let watchdogTimer = null;
      let progressTimer = null;
      let fallbackFinishTimer = null;
      const heartbeatTimers = [];
      let lastTime = 0;
      let stalledTicks = 0;
      const clearTimers = () => {
        [failTimer, watchdogTimer, fallbackFinishTimer].forEach((timer) => {
          if (timer) window.clearTimeout(timer);
        });
        heartbeatTimers.forEach((timer) => window.clearTimeout(timer));
        heartbeatTimers.length = 0;
        if (progressTimer) window.clearInterval(progressTimer);
        progressTimer = null;
      };
      [4000, 10000, 16000, 22000].forEach((delay) => {
        heartbeatTimers.push(window.setTimeout(() => {
          emitLuffyGearFifthBattleHeartbeat(battle, 920);
        }, delay));
      });
      const finish = () => {
        if (done) return;
        done = true;
        clearTimers();
        video.pause?.();
        fadeOutAndRemoveLayer(layer, 520);
        resolve();
      };
      const showFallbackThenFinish = (delay = 2200, text = "影片未完成播放，改以覺醒演出繼續。") => {
        if (done || fallbackFinishTimer) return;
        fallback.textContent = text;
        fallback.style.opacity = "1";
        fallbackFinishTimer = window.setTimeout(finish, delay);
      };
      const armWatchdog = (ms) => {
        if (watchdogTimer) window.clearTimeout(watchdogTimer);
        watchdogTimer = window.setTimeout(() => {
          showFallbackThenFinish(2200, "影片播放時間過長，先接續尼卡覺醒演出。");
        }, Math.max(8000, Math.round(ms || 0)));
      };
      video.addEventListener("loadedmetadata", () => {
        metadataLoaded = true;
        const duration = Number(video.duration || 0);
        const maxMs = Number.isFinite(duration) && duration > 0
          ? Math.min(150000, Math.max(9000, Math.round(duration * 1000 + 3500)))
          : 42000;
        armWatchdog(maxMs);
      }, { once: true });
      video.addEventListener("ended", finish, { once: true });
      video.addEventListener("error", () => showFallbackThenFinish(2200, "尼卡進化影片尚未放入或無法讀取，改以覺醒演出繼續。"), { once: true });
      video.addEventListener("abort", () => showFallbackThenFinish(1900, "影片播放中斷，改以覺醒演出繼續。"), { once: true });
      video.addEventListener("stalled", () => {
        window.setTimeout(() => {
          if (!done && !video.ended && video.readyState < 3) {
            showFallbackThenFinish(2200, "影片讀取停住，改以覺醒演出繼續。");
          }
        }, 5200);
      });
      const playPromise = video.play?.();
      if (playPromise?.catch) {
        playPromise.catch(() => {
          video.muted = true;
          video.play?.().catch(() => showFallbackThenFinish(2400, "瀏覽器阻擋影片播放，改以覺醒演出繼續。"));
        });
      }
      failTimer = window.setTimeout(() => {
        if (!done && !metadataLoaded && video.readyState === 0) {
          showFallbackThenFinish(2400, "尼卡進化影片尚未讀取完成，改以覺醒演出繼續。");
        }
      }, 6000);
      progressTimer = window.setInterval(() => {
        if (done || video.paused || video.ended) return;
        const current = Number(video.currentTime || 0);
        if (current > lastTime + 0.08) {
          lastTime = current;
          stalledTicks = 0;
          return;
        }
        stalledTicks += 1;
        if (stalledTicks >= 10 && video.readyState < 4) {
          showFallbackThenFinish(2200, "影片播放卡住，改以覺醒演出繼續。");
        }
      }, 800);
      });
    } finally {
      bgmHold.restore();
    }
  }

  function applyLuffyGearFifthAwakening(player, battle, card) {
    const form = EVOLUTION_FORMS[LUFFY_GEAR_FIFTH_FORM_ID];
    if (!form) return false;
    const previousStats = { ...(card.baseStats || {}) };
    const previousName = cardDisplayName(card);
    card.formId = form.id;
    card.unlockedEvolutionFormIds = Array.from(new Set([...(card.unlockedEvolutionFormIds || []), form.id]));
    syncCardMoveSetFromCatalog(card);
    const eligibleMoveIds = (card.moveSet || [])
      .filter((moveEntry) => effectiveMoveUnlockLevel(moveEntry) <= Number(card.level || 1))
      .map((moveEntry) => moveEntry.id);
    card.unlockedMoveIds = buildActiveMoveIdsForCard(card, eligibleMoveIds, formPreferredMoveIds(form, eligibleMoveIds));
    applyCardLevelStats(card, previousStats);
    card.currentHp = cardMaxHp(card);
    syncUnlockedMoveIds(card);
    battle.luffyGearFifthAwakeningUsed = true;
    battle.result = "";
    battle.needsReplacement = false;
    battle.roundResolved = false;
    battle.waitingResume = true;
    battle.playerAction = null;
    battle.enemyAction = null;
    battle.playerPerformedAction = false;
    battle.enemyPerformedAction = false;
    battle.playerDiceRoll = null;
    battle.enemyDiceRoll = null;
    battle.playerStages = emptyStages();
    battle.playerStageTurns = emptyStageTurns();
    battle.playerRoundEffects = emptyRoundEffects();
    battle.luffyGearFifthAwakeningPending = false;
    battle.keepPlayerPortraitOnKnockout = false;
    clearStatusBag(battleStatusBag("player", battle));
    recalcPlayerDerivedStats(player);
    battle.log.push(`${previousName} 倒下的瞬間，解放之鼓響起。魯夫覺醒為五檔・尼卡，滿血復活並繼續戰鬥！`);
    return true;
  }

  async function tryLuffyGearFifthAwakening(player, battle, card) {
    if (!canTriggerLuffyGearFifthAwakening(player, battle, card)) return false;
    const form = EVOLUTION_FORMS[LUFFY_GEAR_FIFTH_FORM_ID];
    const beforeName = cardDisplayName(card);
    const beforePortraits = { ...(cardPortraitsForDisplay(card) || {}) };
    const afterName = form?.displayName || form?.name || "五檔・尼卡";
    const afterPortraits = { ...(form?.battlePortraits || {}) };
    battle.animating = true;
    battle.luffyGearFifthAwakeningPending = true;
    battle.keepPlayerPortraitOnKnockout = true;
    renderBattleInterface();
    notifyBattleWindow();
    await playLuffyGearFifthDeathTransition(card, battle);
    await playLuffyGearFifthAwakeningVideo({ beforeName, beforePortraits, battle });
    if (!applyLuffyGearFifthAwakening(player, battle, card)) {
      battle.animating = false;
      battle.luffyGearFifthAwakeningPending = false;
      battle.keepPlayerPortraitOnKnockout = false;
      return false;
    }
    await playLuffyGearFifthPostEvolutionEffect({ beforeName, beforePortraits, afterName, afterPortraits });
    battle.animating = false;
    battle.visualEvent = {
      id: `luffy-gear-fifth-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      type: "status",
      side: "player",
      moveName: "五檔・尼卡覺醒",
      moveType: "buff",
      duration: 1450,
    };
    renderBattleInterface();
    notifyBattleWindow();
    await waitBattleWindowVisual(battle.visualEvent, 1450);
    ensureBattleRound(player, battle);
    notifyBattleWindow();
    return true;
  }

  async function handleKnockoutAfterActionWithAwakening(player, battle) {
    const activeCard = battleActiveCard(player, battle);
    if (!activeCard || activeCard.currentHp > 0) return false;
    if (tryPlayerBattleCarryRevive(player, battle, activeCard)) return false;
    if (await tryLuffyGearFifthAwakening(player, battle, activeCard)) return true;
    return handleKnockoutAfterAction(player, battle);
  }

  function handleKnockoutAfterAction(player, battle) {
    const activeCard = battleActiveCard(player, battle);
    if (!activeCard || activeCard.currentHp > 0) return false;
    if (tryPlayerBattleCarryRevive(player, battle, activeCard)) return false;
    if (tryCharacterPassiveRevive(player, battle, activeCard)) return false;
    activeCard.currentHp = 0;
    if (!battle.knockedOutCrew.includes(activeCard.id)) battle.knockedOutCrew.push(activeCard.id);
    battle.playerStages = emptyStages();
    battle.playerStageTurns = emptyStageTurns();
    const survivors = livingCrewIndices(player).filter((index) => index !== battle.activeCrewIndex);
    if (survivors.length > 0) {
      battle.needsReplacement = true;
      battle.result = "replacement";
      battle.roundResolved = false;
      battle.log.push(`${activeCard.name} 瀕死，請先選下一位夥伴上場。`);
      notifyBattleWindow();
      scheduleBattleLanStatePush("battle-replacement-needed", 40);
    } else if (isCoopBattle(battle)) {
      beginCoopBattleRescueWait(player, battle);
      notifyBattleWindow();
      scheduleBattleLanStatePush("battle-coop-rescue-wait", 40);
    } else {
      battle.result = "lose";
      const destination = battle?.impelDown ? "將被押往海軍本部" : "將被送進推進城";
      battle.log.push(`${player.name} 的隊伍全員瀕死，${destination}。`);
    }
    return true;
  }

  function applyCaptainCoatSwitchBonus(player, battle, fromIndex, toIndex) {
    const fromCard = player?.crew?.[fromIndex];
    const toCard = player?.crew?.[toIndex];
    const equipped = battleCarryEquippedEntriesForCard(fromCard).find(({ item }) => item.id === "captain_coat");
    if (!fromCard || !toCard || !equipped) return;
    const stateEntry = battleCarryStateForEquippedItem(fromCard, fromIndex, equipped.item, battle, true, equipped.slotIndex);
    if (!stateEntry || stateEntry.captainCoatTriggered) return;
    stateEntry.captainCoatTriggered = true;
    applyStageSet(battle.playerStages, { def: 1 }, 0, battle.playerStageTurns, 3);
    battle.log.push(`${fromCard.name}的船長大衣鼓舞了${toCard.name}，防禦提升。`);
  }

  function applySwitchAction(side, action, player, battle) {
    if (side !== "player") {
      battle.enemyPerformedAction = true;
      battle.log.push("敵人重新調整站位。");
      return;
    }
    const fromIndex = battle.activeCrewIndex;
    const nextIndex = action.nextIndex;
    if (!battleCrewIndexIsEligible(player, battle, nextIndex)) {
      battle.playerPerformedAction = true;
      battle.log.push("競技場只能換上入場前選定的兩名船員。");
      return;
    }
    if (activeBlackbeardCaptureTurns(player, battle) > 0) {
      battle.playerPerformedAction = true;
      battle.log.push(`${battleActiveCard(player, battle)?.name || player.name} 被黑暗捕獲，無法換人。`);
      return;
    }
    if (activeFinalGateBlackTurns(player, battle) > 0) {
      battle.playerPerformedAction = true;
      battle.log.push(`${battleActiveCard(player, battle)?.name || player.name} 被黑轉支配，無法換人。`);
      return;
    }
    reduceBlackbeardDarkStackOnSwitch(player, battle, fromIndex);
    syncActivePlayerStatusBag(player, battle);
    battle.activeCrewIndex = nextIndex;
    player.activeCrewIndex = nextIndex;
    syncActivePlayerStatusBag(player, battle);
    markBattleCrewParticipation(player, battle, nextIndex);
    battle.playerStages = emptyStages();
    battle.playerStageTurns = emptyStageTurns();
    resetRoundEffects(battle.playerRoundEffects);
    applyCaptainCoatSwitchBonus(player, battle, fromIndex, nextIndex);
    const switchReduction = Math.max(0, Math.min(0.75, Number(getTeamEffects(player).shipSwitchDamageReduction || 0)));
    if (switchReduction > 0) {
      battle.shipSwitchDamageReduction = switchReduction;
      battle.shipSwitchDamageReductionUsed = false;
      battle.log.push(`${player.name} 的船尾改造預先掩護換人，下一次受傷 -${Math.round(switchReduction * 100)}%。`);
    }
    battle.playerPerformedAction = true;
    battle.log.push(`${player.name} 換上 ${player.crew[nextIndex].name}，本回合不再攻擊。`);
    if (isCoopBattle(battle)) saveCoopBattleRuntime(player, battle);
  }

  function applyEscapeAction(side, player, battle) {
    if (side !== "player") {
      battle.enemyPerformedAction = true;
      return;
    }
    const effects = getTeamEffects(player);
    const escapeRoll = Number(battle.pendingEscapeRoll || 0);
    const escapeRollBase = Number(battle.pendingEscapeRollBase || 0);
    const escapeRollBonus = Math.max(0, Math.round(Number(battle.pendingEscapeRollBonus || 0)));
    const escapeRollText = escapeRollBonus > 0 && escapeRollBase > 0
      ? `${escapeRollBase}+${escapeRollBonus}=${escapeRoll}`
      : `${escapeRoll}`;
    const escapeThreshold = Number(effects.escapeThreshold || 0);
    battle.pendingEscapeRoll = null;
    battle.pendingEscapeRollBase = null;
    battle.pendingEscapeRollBonus = null;
    const ctx = activePlayerCarryContexts(player, battle).find((entry) => battleCarryItemEffect(entry.item).kind === "guaranteed_escape_once" && !entry.state?.usedThisBattle);
    const carryEffect = battleCarryItemEffect(ctx?.item);
    if (battle.isJudicialRaid || battle.isMarineford || battle.noEscape || battle.isNoEscape) {
      battle.log.push("這場戰鬥無法逃跑。");
      battle.playerPerformedAction = true;
      return;
    }
    if (ctx && carryEffect.kind === "guaranteed_escape_once" && !battle.noEscape && !battle.isNoEscape) {
      ctx.state.usedThisBattle = true;
      battle.result = "escape";
      battle.log.push(`${ctx.card.name}的${battleCarryItemName(ctx.item)}啟動，隊伍成功撤退。`);
      return;
    }
    if (battle.playerRoundEffects.guaranteedEscape || (escapeThreshold > 0 && escapeRoll >= escapeThreshold)) {
      battle.result = "escape";
      battle.log.push(`${player.name} 逃跑骰 ${escapeRollText}，成功脫離戰鬥。`);
    } else {
      battle.log.push(escapeThreshold <= 0 ? `${player.name} 沒有移動型夥伴或船隻逃生裝備，無法逃跑。` : `${player.name} 逃跑骰 ${escapeRollText}，需要 ${escapeThreshold}+，逃跑失敗。`);
      battle.playerPerformedAction = true;
    }
  }

  function consumeBattleItem(player, itemId) {
    const def = gameItemDef(itemId);
    if (!def) return false;
    const hadSmallSupply = def.id === "heal_2" && Number(player.smallSupplies || 0) > 0;
    const hadBattleFood = def.id === "battle_food" && Number(player.battleFood || 0) > 0;
    const hadGuardCharm = def.id === "guard_charm" && Number(player.guardCharm || 0) > 0;
    const hadInventory = removeInventoryItem(player, def.id, 1);
    if (hadSmallSupply) player.smallSupplies -= 1;
    if (hadBattleFood) player.battleFood -= 1;
    if (hadGuardCharm) player.guardCharm -= 1;
    return hadInventory || hadSmallSupply || hadBattleFood || hadGuardCharm;
  }

  function hasAnyBattleStatus(bag, statuses) {
    return (statuses || []).some((status) => {
      const key = normalizeBattleStatus(status);
      return key && Number(bag?.[key] || 0) > 0;
    });
  }

  function cureBattleStatuses(bag, statuses) {
    let cured = 0;
    (statuses || []).forEach((status) => {
      const key = normalizeBattleStatus(status);
      if (!key || Number(bag?.[key] || 0) <= 0) return;
      bag[key] = 0;
      cured += 1;
    });
    return cured;
  }

  function battleItemTargetMode(itemDef = {}) {
    const kind = itemDef.effect?.kind || "";
    if (kind === "force_first_die_parity" || itemDef.targetType === "battle_side") return "battle_side";
    if (kind === "revive") return "downed_ally";
    if (["heal_hp", "heal_hp_percent", "heal_percent_and_cure_status", "cure_status", "cure_all_status", "restore_skill_use"].includes(kind)) {
      return "living_ally";
    }
    if (kind === "heal_party_percent_battle" || kind === "heal_party_percent_outside_battle" || itemDef.targetType === "party") {
      return "party";
    }
    return "none";
  }

  function battleItemNeedsCrewTarget(itemDef = {}) {
    return ["living_ally", "downed_ally"].includes(battleItemTargetMode(itemDef));
  }

  function battleItemTargetFallbackIndex(player, battle, mode) {
    const crew = player?.crew || [];
    const activeIndex = Math.max(0, Number(battle?.activeCrewIndex ?? player?.activeCrewIndex ?? 0));
    const isValid = (index) => {
      const card = crew[index];
      if (!card || !battleCrewIndexIsEligible(player, battle, index)) return false;
      if (mode === "downed_ally") return Number(card.currentHp || 0) <= 0;
      return Number(card.currentHp ?? cardMaxHp(card)) > 0;
    };
    if (isValid(activeIndex)) return activeIndex;
    return battleCrewEntries(player, battle).find(({ index }) => isValid(index))?.index ?? -1;
  }

  function resolveBattleItemTarget(player, battle, itemDef, action = {}) {
    const mode = battleItemTargetMode(itemDef);
    if (!battleItemNeedsCrewTarget(itemDef)) {
      const activeIndex = Math.max(0, Number(battle?.activeCrewIndex ?? player?.activeCrewIndex ?? 0));
      return {
        index: activeIndex,
        card: player?.crew?.[activeIndex] || null,
        statuses: battleCrewStatusBagForIndex(player, battle, activeIndex),
        mode,
      };
    }
    const crew = player?.crew || [];
    const rawIndex = Number(action.targetIndex);
    const isValid = (index) => {
      const card = crew[index];
      if (!card || !battleCrewIndexIsEligible(player, battle, index)) return false;
      if (mode === "downed_ally") return Number(card.currentHp || 0) <= 0;
      return Number(card.currentHp ?? cardMaxHp(card)) > 0;
    };
    let index = Number.isInteger(rawIndex) && isValid(rawIndex)
      ? rawIndex
      : battleItemTargetFallbackIndex(player, battle, mode);
    if (!Number.isInteger(index) || index < 0) {
      return { index: -1, card: null, statuses: emptyStatusEffects(), mode };
    }
    return {
      index,
      card: crew[index],
      statuses: battleCrewStatusBagForIndex(player, battle, index),
      mode,
    };
  }

  function battleItemTargetMissingText(itemDef = {}) {
    const mode = battleItemTargetMode(itemDef);
    if (mode === "downed_ally") return "目前沒有倒下的夥伴可以復活。";
    return "目前沒有可使用這個道具的隊友。";
  }

  function applyBattleItemAction(side, action, player, battle) {
    if (side !== "player") {
      battle.enemyPerformedAction = true;
      return;
    }
    const activeCard = battleActiveCard(player, battle);
    if (!activeCard) return;
    const itemDef = gameItemDef(action.itemId);
    if (!itemDef || normalizeGameItemCategory(itemDef.category) !== "battle") {
      battle.playerPerformedAction = true;
      battle.log.push(`${player.name} 想使用道具，但這不是戰鬥道具。`);
      return;
    }
    const effect = itemDef.effect || {};
    const targetPlayerId = String(action.targetPlayerId || player.id || "");
    const targetPlayer = isCoopBattle(battle)
      ? coopBattleParticipants(battle).find((entry) => String(entry.id) === targetPlayerId)
      : player;
    if (!targetPlayer) {
      battle.playerPerformedAction = true;
      battle.log.push("找不到這個共鬥道具目標。");
      return;
    }
    const playerStatuses = battleStatusBag("player", battle);
    const targetInfo = resolveBattleItemTarget(player, battle, itemDef, action);
    const targetCard = targetInfo.card || activeCard;
    const targetStatuses = targetInfo.statuses || playerStatuses;
    const ensureTarget = () => {
      if (!battleItemNeedsCrewTarget(itemDef) || targetInfo.card) return true;
      battle.log.push(battleItemTargetMissingText(itemDef));
      return false;
    };
    const consumeAndMark = () => {
      const maxUses = Math.max(0, Math.round(Number(effect.maxUsesPerBattle || 0)));
      battle.itemUseCounts = battle.itemUseCounts && typeof battle.itemUseCounts === "object" ? battle.itemUseCounts : {};
      const itemUseCountKey = isCoopBattle(battle) ? `${player.id}:${itemDef.id}` : itemDef.id;
      if (maxUses > 0 && Number(battle.itemUseCounts[itemUseCountKey] || 0) >= maxUses) {
        battle.log.push(`${itemDef.name}在本場戰鬥已達使用上限。`);
        return false;
      }
      if (!consumeBattleItem(player, itemDef.id)) {
        battle.log.push(`${player.name} 想使用 ${itemDef.name}，但目前沒有可用數量。`);
        return false;
      }
      battle.itemUseCounts[itemUseCountKey] = Number(battle.itemUseCounts[itemUseCountKey] || 0) + 1;
      battle.playerPerformedAction = true;
      recordMissionEvent(player, { type: "use_item_category", category: "battle", itemId: itemDef.id, itemName: itemDef.name });
      if (["heal_hp", "heal_hp_percent", "heal_party_percent_battle", "heal_party_percent_outside_battle", "heal_percent_and_cure_status", "revive", "cure_status", "cure_all_status"].includes(effect.kind)) {
        recordMissionEvent(player, { type: "use_heal_item", category: "battle", itemId: itemDef.id, itemName: itemDef.name });
      }
      return true;
    };

    const crossPlayerKinds = new Set([
      "revive",
      "heal_hp",
      "heal_hp_percent",
      "heal_percent_and_cure_status",
      "cure_status",
      "cure_all_status",
      "restore_skill_use",
      "heal_party_percent_battle",
      "heal_party_percent_outside_battle",
    ]);
    if (isCoopBattle(battle) && String(targetPlayer.id) !== String(player.id)) {
      if (!crossPlayerKinds.has(effect.kind)) {
        battle.playerPerformedAction = true;
        battle.log.push(`${itemDef.name}只能用在自己的隊伍。`);
        return;
      }
      const targetRuntime = coopBattleRuntimeFor(targetPlayer, battle, false);
      if (targetRuntime?.escaped || targetRuntime?.defeated) {
        battle.playerPerformedAction = true;
        battle.log.push(`${targetPlayer.name} 已離開本場共鬥，無法成為道具目標。`);
        return;
      }
      let applied = false;
      let rescued = false;
      let totalHealed = 0;
      let message = "";
      withCoopBattleRuntime(targetPlayer, battle, () => {
        const crossTargetInfo = resolveBattleItemTarget(targetPlayer, battle, itemDef, action);
        const crossTargetCard = crossTargetInfo.card;
        const crossTargetStatuses = crossTargetInfo.statuses;
        if (battleItemNeedsCrewTarget(itemDef) && !crossTargetCard) {
          message = battleItemTargetMissingText(itemDef);
          return;
        }
        if (effect.kind === "revive") {
          if (!crossTargetCard || Number(crossTargetCard.currentHp || 0) > 0) return;
          if (!consumeAndMark()) return;
          crossTargetCard.currentHp = Math.max(1, Math.round(cardMaxHp(crossTargetCard) * Number(effect.hpPercent || 0.3)));
          totalHealed = crossTargetCard.currentHp;
          clearCoopBattleRescueWait(targetPlayer, battle, crossTargetInfo.index);
          rescued = true;
          applied = true;
          message = `${player.name} 使用${itemDef.name}救回 ${targetPlayer.name} 的${crossTargetCard.name}，回復 ${totalHealed} HP。`;
        } else if (effect.kind === "heal_hp" || effect.kind === "heal_hp_percent") {
          const before = Math.max(0, Number(crossTargetCard?.currentHp || 0));
          if (!crossTargetCard || before >= cardMaxHp(crossTargetCard)) return;
          if (!consumeAndMark()) return;
          if (effect.kind === "heal_hp") {
            crossTargetCard.currentHp = Math.min(cardMaxHp(crossTargetCard), before + Math.max(1, Math.round(Number(effect.amount || 0))));
            totalHealed = crossTargetCard.currentHp - before;
          } else {
            totalHealed = healBattleTarget(crossTargetCard, Number(effect.percent || 0.25));
          }
          applied = true;
          message = `${player.name} 對 ${targetPlayer.name} 的${crossTargetCard.name}使用${itemDef.name}，回復 ${totalHealed} HP。`;
        } else if (effect.kind === "heal_percent_and_cure_status") {
          const hpMissing = Number(crossTargetCard.currentHp || 0) < cardMaxHp(crossTargetCard);
          const canCure = hasAnyBattleStatus(crossTargetStatuses, effect.statuses || []);
          if (!hpMissing && !canCure) return;
          if (!consumeAndMark()) return;
          totalHealed = healBattleTarget(crossTargetCard, Number(effect.percent || 0.35));
          const cured = cureBattleStatuses(crossTargetStatuses, effect.statuses || []);
          applied = true;
          message = `${player.name} 對 ${targetPlayer.name} 的${crossTargetCard.name}使用${itemDef.name}，回復 ${totalHealed} HP${cured ? `並解除 ${cured} 個異常狀態` : ""}。`;
        } else if (effect.kind === "cure_status" || effect.kind === "cure_all_status") {
          const statuses = effect.kind === "cure_all_status" ? Object.keys(emptyStatusEffects()) : (effect.statuses || []);
          if (!hasAnyBattleStatus(crossTargetStatuses, statuses)) return;
          if (!consumeAndMark()) return;
          const cured = effect.kind === "cure_all_status"
            ? (clearStatusBag(crossTargetStatuses), statuses.length)
            : cureBattleStatuses(crossTargetStatuses, statuses);
          applied = true;
          message = `${player.name} 對 ${targetPlayer.name} 的${crossTargetCard.name}使用${itemDef.name}，解除異常狀態。`;
        } else if (effect.kind === "restore_skill_use") {
          const amount = Math.max(1, Math.round(Number(effect.amount || 1)));
          const targetMove = getUnlockedMoves(crossTargetCard)
            .filter((entry) => Number(entry.pp || 0) > 0 && Number(entry.currentPP ?? entry.pp ?? 0) < Number(entry.pp || 0))
            .sort((a, b) => Number(a.currentPP ?? a.pp ?? 0) - Number(b.currentPP ?? b.pp ?? 0))[0];
          if (!targetMove || !consumeAndMark()) return;
          const before = Number(targetMove.currentPP ?? targetMove.pp ?? 0);
          targetMove.currentPP = effect.cannotExceedMax === false
            ? before + amount
            : Math.min(Number(targetMove.pp || before + amount), before + amount);
          applied = true;
          message = `${player.name} 對 ${targetPlayer.name} 的${crossTargetCard.name}使用${itemDef.name}，${targetMove.name}恢復 ${targetMove.currentPP - before} 次。`;
        } else if (effect.kind === "heal_party_percent_battle" || effect.kind === "heal_party_percent_outside_battle") {
          const eligibleCrew = battleCrewEntries(targetPlayer, battle).map(({ card }) => card);
          if (!eligibleCrew.some((card) => Number(card.currentHp || 0) > 0 && Number(card.currentHp || 0) < cardMaxHp(card))) return;
          if (!consumeAndMark()) return;
          eligibleCrew.forEach((card) => { totalHealed += healBattleTarget(card, Number(effect.percent || 0.35)); });
          applied = true;
          message = `${player.name} 對 ${targetPlayer.name} 的全隊使用${itemDef.name}，合計回復 ${totalHealed} HP。`;
        }
        if (applied) recalcPlayerDerivedStats(targetPlayer);
      }, { save: true });
      if (!applied) {
        battle.log.push(message || `${targetPlayer.name} 的隊伍目前不需要這個道具。`);
        return;
      }
      battle.playerPerformedAction = true;
      battle.log.push(message);
      return;
    }

    if (effect.kind === "force_first_die_parity") {
      const targetSide = action.targetSide === "enemy" ? "enemy" : "player";
      if (!consumeAndMark()) return;
      const parity = normalizeBattleFirstDiceParity(effect.parity);
      const entry = setBattleFirstDiceParityEffect(targetSide, battle, player, parity, Number(effect.turns || 2), itemDef.id);
      if (!entry) {
        battle.log.push(`${itemDef.name}沒有產生有效效果。`);
        return;
      }
      const targetLabel = targetSide === "enemy" ? battle.enemyCombatant?.name || "敵方" : `${activeCard.name}所屬的我方`;
      battle.log.push(`${player.name}將${itemDef.name}用在${targetLabel}；接下來 ${entry.turnsRemaining} 次行動的第一顆戰鬥骰只會出現${parity === "odd" ? "單數" : "雙數"}。`);
      return;
    }

    if (effect.kind === "revive") {
      if (!ensureTarget()) return;
      const target = targetCard;
      if (!consumeAndMark()) return;
      target.currentHp = Math.max(1, Math.round(cardMaxHp(target) * Number(effect.hpPercent || 0.3)));
      if (isCoopBattle(battle)) clearCoopBattleRescueWait(player, battle, targetInfo.index);
      battle.log.push(`${itemDef.name}讓${target.name}重新站了起來，回復 ${target.currentHp} HP。`);
      recalcPlayerDerivedStats(player);
      return;
    }

    if (effect.kind === "cure_status") {
      if (!ensureTarget()) return;
      if (!hasAnyBattleStatus(targetStatuses, effect.statuses)) {
        battle.log.push(`${targetCard.name} 沒有可解除的對應異常。`);
        return;
      }
      if (!consumeAndMark()) return;
      const cured = cureBattleStatuses(targetStatuses, effect.statuses);
      battle.log.push(`${player.name} 對${targetCard.name}使用${itemDef.name}，解除 ${cured} 個異常狀態。`);
      return;
    }

    if (effect.kind === "cure_all_status") {
      if (!ensureTarget()) return;
      if (!hasAnyBattleStatus(targetStatuses, Object.keys(emptyStatusEffects()))) {
        battle.log.push(`${targetCard.name} 目前沒有異常狀態。`);
        return;
      }
      if (!consumeAndMark()) return;
      clearStatusBag(targetStatuses);
      battle.log.push(itemDef.logText?.use || `${player.name} 對${targetCard.name}使用${itemDef.name}，清除了所有異常狀態。`);
      return;
    }

    if (effect.kind === "escape_battle") {
      if (battle.isJudicialRaid || battle.noEscape || battle.isNoEscape) {
        battle.log.push(`${itemDef.name}在這場戰鬥無法使用。`);
        return;
      }
      if (!consumeAndMark()) return;
      battle.playerRoundEffects.guaranteedEscape = true;
      battle.pendingEscapeRoll = 6;
      applyEscapeAction("player", player, battle);
      battle.log.push(itemDef.logText?.use || `${itemDef.name}噴出濃煙，隊伍趁亂脫離戰鬥。`);
      return;
    }

    if (effect.kind === "restore_skill_use") {
      if (!ensureTarget()) return;
      const amount = Math.max(1, Math.round(Number(effect.amount || 1)));
      const targetMove = getUnlockedMoves(targetCard)
        .filter((entry) => Number(entry.pp || 0) > 0 && Number(entry.currentPP ?? entry.pp ?? 0) < Number(entry.pp || 0))
        .sort((a, b) => (Number(a.currentPP ?? a.pp ?? 0) - Number(b.currentPP ?? b.pp ?? 0)))[0];
      if (!targetMove) {
        battle.log.push(`${targetCard.name} 目前沒有需要恢復使用次數的技能。`);
        return;
      }
      if (!consumeAndMark()) return;
      const before = Math.max(0, Number(targetMove.currentPP ?? targetMove.pp ?? 0));
      targetMove.currentPP = effect.cannotExceedMax === false
        ? before + amount
        : Math.min(Number(targetMove.pp || before + amount), before + amount);
      battle.log.push(`${player.name} 對${targetCard.name}使用${itemDef.name}，${targetMove.name} 使用次數恢復 ${targetMove.currentPP - before}。`);
      return;
    }

    if (effect.kind === "heal_hp") {
      if (!ensureTarget()) return;
      const maxHp = cardMaxHp(targetCard);
      const before = Math.max(0, Number(targetCard.currentHp || 0));
      if (before >= maxHp) {
        battle.log.push(`${targetCard.name} 目前 HP 已滿。`);
        return;
      }
      if (!consumeAndMark()) return;
      targetCard.currentHp = Math.min(maxHp, before + Math.max(1, Math.round(Number(effect.amount || 0))));
      const healed = Math.max(0, targetCard.currentHp - before);
      battle.log.push(`${player.name} 對${targetCard.name}使用${itemDef.name}，回復 ${healed} HP。`);
      recalcPlayerDerivedStats(player);
      return;
    }
    if (effect.kind === "heal_hp_percent") {
      if (!ensureTarget()) return;
      const before = Math.max(0, Number(targetCard.currentHp || 0));
      if (before >= cardMaxHp(targetCard)) {
        battle.log.push(`${targetCard.name} 目前 HP 已滿。`);
        return;
      }
      if (!consumeAndMark()) return;
      const healed = healBattleTarget(targetCard, Number(effect.percent || 0.25));
      battle.log.push(`${player.name} 對${targetCard.name}使用${itemDef.name}，回復 ${healed} HP。`);
      recalcPlayerDerivedStats(player);
      return;
    }
    if (effect.kind === "heal_percent_and_cure_status") {
      if (!ensureTarget()) return;
      const hasHpMissing = Math.max(0, Number(targetCard.currentHp || 0)) < cardMaxHp(targetCard);
      const hasCureTarget = hasAnyBattleStatus(targetStatuses, effect.statuses || []);
      if (!hasHpMissing && !hasCureTarget) {
        battle.log.push(`${targetCard.name} 目前不需要這個道具。`);
        return;
      }
      if (!consumeAndMark()) return;
      const healed = healBattleTarget(targetCard, Number(effect.percent || 0.35));
      const cured = cureBattleStatuses(targetStatuses, effect.statuses || []);
      battle.log.push(`${player.name} 對${targetCard.name}使用${itemDef.name}，回復 ${healed} HP${cured ? `，並解除 ${cured} 個異常狀態` : ""}。`);
      recalcPlayerDerivedStats(player);
      return;
    }
    if (effect.kind === "heal_party_percent_battle" || effect.kind === "heal_party_percent_outside_battle") {
      const eligibleCrew = battleCrewEntries(player, battle).map(({ card }) => card);
      const hasAnyMissingHp = eligibleCrew.some((card) => Number(card.currentHp || 0) > 0 && Number(card.currentHp || 0) < cardMaxHp(card));
      if (!hasAnyMissingHp) {
        battle.log.push("目前全隊 HP 都是滿的。");
        return;
      }
      if (!consumeAndMark()) return;
      let totalHealed = 0;
      eligibleCrew.forEach((card) => {
        totalHealed += healBattleTarget(card, Number(effect.percent || 0.35));
      });
      battle.log.push(`${player.name} 使用${itemDef.name}，全隊合計回復 ${totalHealed} HP。`);
      recalcPlayerDerivedStats(player);
      return;
    }
    if (effect.kind === "temporary_shield") {
      if (!consumeAndMark()) return;
      applyBattleShieldTiming("player", battle, Number(effect.shieldRatio || 0.35));
      battle.log.push(`${player.name} 使用${itemDef.name}，受到傷害降低。`);
      return;
    }
    if (effect.kind === "apply_stat_stage") {
      if (!consumeAndMark()) return;
      const statKey = normalizeBattleStageKey(effect.stat || "spd");
      const targetStages = effect.target === "self" ? battle.playerStages : battle.enemyCombatant.stages;
      const targetTurns = effect.target === "self" ? battle.playerStageTurns : battle.enemyCombatant.stageTurns;
      applyStageSet(targetStages, { [statKey]: Number(effect.stage || 0) }, 0, targetTurns, Number(effect.turns || 3));
      battle.log.push(itemDef.logText?.use || `${player.name} 使用${itemDef.name}，${effect.target === "self" ? activeCard.name : "敵人"}的${signedStageLabel(statKey, Number(effect.stage || 0))}。`);
      return;
    }
    if (effect.kind === "apply_accuracy_modifier") {
      if (!consumeAndMark()) return;
      applyStageSet(battle.enemyCombatant.stages, { accuracy: -1 }, 0, battle.enemyCombatant.stageTurns, Number(effect.turns || 2));
      battle.log.push(itemDef.logText?.use || `${player.name} 使用${itemDef.name}，敵人的命中下降。`);
      return;
    }
    if (effect.kind === "apply_speed_multiplier_and_status_chance") {
      if (!consumeAndMark()) return;
      applyStageSet(battle.enemyCombatant.stages, { spd: -1 }, 0, battle.enemyCombatant.stageTurns, Number(effect.turns || 3));
      if (effect.statusChance?.status && Math.random() < Number(effect.statusChance.chance || 0)) {
        const label = applyBattleStatus("enemy", battle, effect.statusChance.status, 1);
        if (label) battle.log.push(`${itemDef.name}追加效果，敵人陷入${label}。`);
      }
      battle.log.push(`${player.name} 使用${itemDef.name}，敵人速度下降。`);
      return;
    }
    if (!consumeAndMark()) return;
    battle.playerPerformedAction = true;
    battle.log.push(`${player.name} 使用${itemDef.name}，但效果暫未接上。`);
  }

  function canSelectBattleItemTargetInModal(item, player, battle, card, index) {
    const hp = Number(card?.currentHp || 0);
    if (item.targetMode === "downed_ally") return hp <= 0;
    if (hp <= 0) return false;
    const kind = item.effectKind || "";
    if (kind === "heal_hp" || kind === "heal_hp_percent") return hp < cardMaxHp(card);
    if (kind === "heal_percent_and_cure_status") {
      return hp < cardMaxHp(card) || hasAnyBattleStatus(battleCrewStatusBagForIndex(player, battle, index), item.statuses || []);
    }
    if (kind === "cure_status") return hasAnyBattleStatus(battleCrewStatusBagForIndex(player, battle, index), item.statuses || []);
    if (kind === "cure_all_status") return hasAnyBattleStatus(battleCrewStatusBagForIndex(player, battle, index), Object.keys(emptyStatusEffects()));
    if (kind === "restore_skill_use") {
      return getUnlockedMoves(card).some((entry) => Number(entry.pp || 0) > 0 && Number(entry.currentPP ?? entry.pp ?? 0) < Number(entry.pp || 0));
    }
    return true;
  }

  function openBattleItemSideTargetPanel(itemId) {
    const battle = state.battleState;
    const player = battlePlayer(null, battle);
    const item = getBattleItemOptions(player).find((entry) => entry.id === itemId && entry.targetMode === "battle_side");
    if (!battle || !player || !item || warnBoardLanTurnLocked(player)) return;
    const parityLabel = item.id === "odd_dice" ? "單數" : "雙數";
    openModal(`
      <h3 class="modal-title">${item.name}</h3>
      <div class="modal-sub">選擇要控制哪一側接下來兩次行動的第一顆戰鬥骰。</div>
      <div class="companion-grid">
        <article class="companion-card">
          <div class="companion-tier">我方</div>
          <div class="companion-name">${battleActiveCard(player, battle)?.name || player.name}</div>
          <div class="companion-meta">接下來 2 次第一顆戰鬥骰只會出現${parityLabel}。</div>
          <button type="button" class="modal-btn primary" data-battle-item-side="player">使用在我方</button>
        </article>
        <article class="companion-card">
          <div class="companion-tier">敵方</div>
          <div class="companion-name">${battle.enemyCombatant?.name || "敵人"}</div>
          <div class="companion-meta">接下來 2 次第一顆戰鬥骰只會出現${parityLabel}。</div>
          <button type="button" class="modal-btn primary" data-battle-item-side="enemy">使用在敵方</button>
        </article>
      </div>
      <div class="modal-row"><button type="button" class="modal-btn secondary" id="backBattleItemListBtn">返回道具</button></div>
    `);
    refs.modal.querySelectorAll("[data-battle-item-side]").forEach((button) => {
      button.addEventListener("click", () => queuePlayerBattleItem(item.id, null, "", button.dataset.battleItemSide));
    });
    document.getElementById("backBattleItemListBtn")?.addEventListener("click", openBattleItemPanel);
  }

  function openBattleItemTargetPanel(itemId) {
    const battle = state.battleState;
    const player = battlePlayer(null, battle);
    const item = getBattleItemOptions(player).find((entry) => entry.id === itemId);
    if (!battle || !player || !item) return;
    if (warnBoardLanTurnLocked(player)) return;
    openModal(`
      <h3 class="modal-title">${item.name}</h3>
      <div class="modal-sub">選擇要使用道具的隊友，場下夥伴也可以被指定。</div>
      <div class="companion-grid">
        ${battleCrewEntries(player, battle).map(({ card, index }) => {
          const maxHp = cardMaxHp(card);
          const canTarget = canSelectBattleItemTargetInModal(item, player, battle, card, index);
          const ppCurrent = (card.moveSet || []).reduce((sum, entry) => sum + Number(entry.currentPP ?? entry.pp ?? 0), 0);
          const ppMax = (card.moveSet || []).reduce((sum, entry) => sum + Number(entry.pp || 0), 0);
          const statuses = activeStatusLabels(battleCrewStatusBagForIndex(player, battle, index));
          return `
            <article class="companion-card">
              <div class="companion-tier">${tierLabel(card.tier)} ・ ${card.attribute}${index === battle.activeCrewIndex ? " ・ 上場中" : " ・ 場下"}</div>
              <div class="companion-name">${cardDisplayName(card)}</div>
              <div class="companion-meta">生命值 ${Math.max(0, Number(card.currentHp || 0))}/${maxHp} ・ 技能 ${ppCurrent}/${ppMax}${statuses.length ? ` ・ 異常 ${statuses.join("、")}` : ""}</div>
              <button type="button" class="modal-btn primary" data-battle-item-target="${index}" ${canTarget ? "" : "disabled"}>使用在這位</button>
            </article>
          `;
        }).join("")}
      </div>
      <div class="modal-row">
        <button type="button" class="modal-btn secondary" id="backBattleItemListBtn">返回道具</button>
      </div>
    `);
    refs.modal.querySelectorAll("[data-battle-item-target]").forEach((button) => {
      button.addEventListener("click", () => queuePlayerBattleItem(item.id, Number(button.dataset.battleItemTarget)));
    });
    document.getElementById("backBattleItemListBtn")?.addEventListener("click", openBattleItemPanel);
  }

  function openBattleItemPanel() {
    const battle = state.battleState;
    const player = battlePlayer(null, battle);
    if (!battle || !player) return;
    if (warnBoardLanTurnLocked(player)) return;
    const items = getBattleItemOptions(player);
    openModal(`
      <h3 class="modal-title">戰鬥道具</h3>
      <div class="modal-sub">使用道具會消耗本回合行動，並保留原本戰鬥結算流程。</div>
      <div class="companion-grid">
        ${items.length ? items.map((item) => `
          <article class="companion-card">
            <div class="companion-tier">持有 ${item.count}</div>
            <div class="companion-name">${item.name}</div>
            <div class="companion-meta">${item.desc}</div>
            <button type="button" class="modal-btn primary" data-battle-item="${item.id}" ${item.count <= 0 ? "disabled" : ""}>使用道具</button>
          </article>
        `).join("") : `<div class="empty-note">目前沒有可用戰鬥道具。</div>`}
      </div>
      <div class="modal-row">
        <button type="button" class="modal-btn secondary" id="backBattleModalBtn">返回戰鬥</button>
      </div>
    `);
    refs.modal.querySelectorAll("[data-battle-item]").forEach((button) => {
      button.addEventListener("click", () => {
        const item = items.find((entry) => entry.id === button.dataset.battleItem);
        if (item?.targetMode === "battle_side") {
          openBattleItemSideTargetPanel(item.id);
          return;
        }
        if (item && ["living_ally", "downed_ally"].includes(item.targetMode)) {
          openBattleItemTargetPanel(item.id);
          return;
        }
        queuePlayerBattleItem(button.dataset.battleItem);
      });
    });
    document.getElementById("backBattleModalBtn")?.addEventListener("click", renderBattleInterface);
  }

  function openSwitchCrewPanel() {
    const battle = state.battleState;
    const player = isCoopBattle(battle) ? battleCommandPlayer(battle) : battlePlayer(null, battle);
    if (!battle || !player) return;
    if (coopBattleHandoffPending(battle)) return;
    if (isCoopBattle(battle) ? warnBoardLanBattleLocked(player, battle) : warnBoardLanTurnLocked(player)) return;
    const switchLocked = withCoopBattleRuntime(player, battle, () => activeBlackbeardCaptureTurns(player, battle) > 0 || activeFinalGateBlackTurns(player, battle) > 0, { save: false });
    const activeCrewIndex = isCoopBattle(battle)
      ? Math.max(0, Number(coopBattleRuntimeFor(player, battle, true)?.activeCrewIndex ?? player.activeCrewIndex ?? 0))
      : battle.activeCrewIndex;
    openModal(`
      <h3 class="modal-title">換人</h3>
      <div class="modal-sub">${switchLocked ? "目前上場角色被拘束，暫時不能換人。" : "換人等同一個完整動作，本回合將不再攻擊。"}</div>
      <div class="companion-grid">
        ${battleCrewEntries(player, battle).map(({ card, index }) => `
          <article class="companion-card">
            <div class="companion-tier">${tierLabel(card.tier)} ・ ${card.attribute}</div>
            <div class="companion-name">${card.name}${index === activeCrewIndex ? "・目前上場" : ""}</div>
            <div class="companion-meta">生命值 ${card.currentHp}/${card.baseStats.hp} ・ 剩餘 PP ${card.moveSet.reduce((sum, entry) => sum + (entry.currentPP ?? entry.pp), 0)}</div>
            <button type="button" class="modal-btn ${switchLocked || index === activeCrewIndex || card.currentHp <= 0 ? "secondary" : "primary"}" data-switch-crew="${index}" ${switchLocked || index === activeCrewIndex || card.currentHp <= 0 ? "disabled" : ""}>切換上場</button>
          </article>
        `).join("")}
      </div>
    `);
    Array.from(refs.modal.querySelectorAll("[data-switch-crew]")).forEach((button) => {
      button.addEventListener("click", () => {
        const nextIndex = Number(button.dataset.switchCrew);
        queuePlayerBattleSwitch(nextIndex);
      });
    });
  }

  function attemptEscape() {
    const battle = state.battleState;
    if (!battle || postgameBossMechanicPromptPending(battle) || battle.animating || battle.roundResolved || battle.result || coopBattleHandoffPending(battle)) return false;
    if (isCoopBattle(battle) && !battle.__coopQueueRuntime) {
      const coopPlayer = battleCommandPlayer(battle);
      if (!coopPlayer || warnBoardLanBattleLocked(coopPlayer, battle)) return false;
      prepareCoopBattleCommandRuntime(coopPlayer, battle);
      battle.__coopQueueRuntime = true;
      try {
        return attemptEscape();
      } finally {
        battle.__coopQueueRuntime = false;
      }
    }
    const player = battlePlayer(null, battle);
    if (isCoopBattle(battle) ? warnBoardLanBattleLocked(player, battle) : warnBoardLanTurnLocked(player)) return false;
    if (battle.isJudicialRaid || battle.isMarineford || battle.noEscape || battle.isNoEscape) {
      battle.log.push("這場戰鬥無法逃跑。");
      notifyBattleWindow();
      return false;
    }
    if (!getTeamEffects(player).escapeThreshold) {
      battle.log.push(`${player.name} 沒有移動型夥伴或船隻逃生裝備，不能逃跑。`);
      notifyBattleWindow();
      return false;
    }
    voidPostgameOarsPrediction(battle, "本回合嘗試逃跑");
    if (isCoopBattle(battle)) {
      return queueCoopBattleAction(player, battle, { type: "escape" });
    }
    battle.playerAction = { type: "escape" };
    battle.enemyAction = chooseEnemyAction(battle);
    void resolvePlannedBattleActions(player, battle);
    return true;
  }

  function surrenderBattle() {
    const battle = state.battleState;
    if (!battle || battle.animating || battle.result || coopBattleHandoffPending(battle)) return false;
    const player = battlePlayer(null, battle);
    if (!player) return false;
    if (warnBoardLanTurnLocked(player)) return false;
    battle.knockedOutCrew = Array.isArray(battle.knockedOutCrew) ? battle.knockedOutCrew : [];
    (player.crew || []).forEach((card) => {
      if (!card) return;
      card.currentHp = 0;
      if (card.id && !battle.knockedOutCrew.includes(card.id)) battle.knockedOutCrew.push(card.id);
    });
    battle.playerAction = { type: "surrender" };
    battle.enemyAction = null;
    battle.playerPerformedAction = true;
    battle.enemyPerformedAction = true;
    battle.needsReplacement = false;
    battle.roundResolved = true;
    battle.result = "lose";
    battle.pendingEscapeRoll = null;
    battle.log.push(`${player.name} 選擇投降，隊伍全員瀕死。`);
    recalcPlayerDerivedStats(player);
    notifyBattleWindow();
    renderBattleInterface();
    return true;
  }

  function battleMarkPrebattleIntroDone(introId = "", introKey = "") {
    const battle = state.battleState;
    if (!battle?.prebattleIntro) return false;
    const player = battlePlayer(null, battle);
    if (isCoopBattle(battle) ? warnBoardLanBattleLocked(player, battle) : warnBoardLanTurnLocked(player)) return false;
    const currentIntroKey = battle.prebattleIntro.key || prebattleIntroStableKey(player, battle, battle.prebattleIntro.heroKey, battle.prebattleIntro.enemyKey);
    if (introId && battle.prebattleIntro.id && introId !== battle.prebattleIntro.id && (!introKey || introKey !== currentIntroKey)) return false;
    battle.prebattleIntro.done = true;
    clearBattlePrebattleIntroRecoveryTimer();
    notifyBattleWindow();
    scheduleOpeningPassiveVisualsIfReady(player, battle);
    return true;
  }

  let lastProcessedBattleCommandId = "";

  function processBattlePageCommand(command) {
    if (!command || command.id === lastProcessedBattleCommandId) return;
    lastProcessedBattleCommandId = command.id;
    if (!state.battleState) return;
    if (state.battleState.isSparBattle) {
      processSparBattleCommand(command);
      return;
    }
    if (command.type === "move") queuePlayerBattleMove(command.payload?.moveId, command.payload?.targetId);
    else if (command.type === "katakuri-choice") choosePostgameKatakuriAction(command.payload?.choice);
    else if (command.type === "zephyr-disarm") queuePostgameZephyrDisarm();
    else if (command.type === "oars-prediction") lockPostgameOarsPredictions(command.payload?.bets || command.payload?.optionIds || command.payload?.optionId);
    else if (command.type === "oars-purify") purifyPostgameOars();
    else if (command.type === "switch") queuePlayerBattleSwitch(Number(command.payload?.nextIndex));
    else if (command.type === "replacement") chooseBattleReplacement(Number(command.payload?.nextIndex));
    else if (command.type === "postgame-forced-switch") resolvePostgameBossForcedSwitch(Number(command.payload?.nextIndex));
    else if (command.type === "tot-team-setup") confirmTotMusicaTeams(command.payload?.realIndices, command.payload?.songIndices);
    else if (command.type === "tot-dual-action") queueTotMusicaAction(command.payload?.realAction, command.payload?.songAction);
    else if (command.type === "tot-world-action") queueTotMusicaWorldAction(command.payload?.world, command.payload?.action);
    else if (command.type === "item") queuePlayerBattleItem(command.payload?.itemId, command.payload?.targetIndex, command.payload?.targetPlayerId, command.payload?.targetSide);
    else if (command.type === "rescue-wait") battleWaitForRescue();
    else if (command.type === "yonkoSoulChoice") resolveBigMomSoulChoice(command.payload?.choice);
    else if (command.type === "judicial-next-switch") void startJudicialRaidNextPhaseAfterSwitch(command.payload?.nextIndex);
    else if (command.type === "escape") attemptEscape();
    else if (command.type === "surrender") surrenderBattle();
    else if (command.type === "intro-done") battleMarkPrebattleIntroDone(command.payload?.introId, command.payload?.introKey);
    else if (command.type === "zephyr-story-done") battleZephyrExplosionStoryDone(command.payload?.eventId);
    else if (command.type === "lineage-extraction-start") battleStartLineageExtraction(command.payload?.extractorId, command.payload?.playerId);
    else if (command.type === "lineage-extraction-complete") battleCompleteLineageExtraction(command.payload?.grades, command.payload?.playerId);
    else if (command.type === "lineage-extraction-decline") battleDeclineLineageExtraction(command.payload?.playerId);
    else if (command.type === "finish") finishBattle();
  }

  function readBattlePageCommand() {
    try {
      const raw = localStorage.getItem(BATTLE_COMMAND_KEY);
      if (!raw) return;
      processBattlePageCommand(JSON.parse(raw));
    } catch (_error) {
      // Ignore malformed cross-window commands.
    }
  }

  function marinefordBossProfile(index = 0) {
    const base = MARINEFORD_BOSSES[Math.max(0, Math.min(MARINEFORD_BOSSES.length - 1, Number(index || 0)))] || MARINEFORD_BOSSES[0];
    return balanceEnemyProfile(safeJsonClone(base));
  }

  function marinefordValidateSlots(player, slots) {
    return (Array.isArray(slots) ? slots : [])
      .filter((slot) => {
        if (!slot?.cardId) return false;
        if (slot.source === "whitebeard") return WHITEBEARD_RECRUIT_CARD_IDS.has(slot.cardId);
        const owner = (state.gameState.players || []).find((entry) => entry.id === slot.playerId) || player;
        return (owner?.crew || []).some((card) => card.id === slot.cardId);
      })
      .slice(0, 4)
      .map((slot, index) => ({
        playerId: slot.playerId || player.id,
        playerName: slot.playerName || player.name,
        cardId: slot.cardId,
        source: slot.source === "whitebeard" ? "whitebeard" : "crew",
        cleanOnLoss: slot.cleanOnLoss !== false,
        canJoinOnWin: slot.canJoinOnWin !== false,
        roundsLeft: Math.max(0, Number(slot.roundsLeft ?? marinefordExecutionTurnsFor(index))),
        rescued: Boolean(slot.rescued),
        executed: Boolean(slot.executed),
      }));
  }

  function marinefordApplyCrewDraw(player, slots) {
    const hold = normalizeMarinefordHold(player);
    hold.slots = marinefordValidateSlots(player, slots);
    hold.setupStep = hold.slots.length ? "drawSupport" : "drawCrew";
    hold.rounds = hold.slots.reduce((min, slot) => Math.min(min, Number(slot.roundsLeft ?? 99)), 99);
    addLog(`${player.name} 的海軍本部處刑台抽籤完成。`);
    recordMainMissionEvent(player, { type: "marineford_rescue_selected" });
    renderAll();
    notifyMarinefordWindow(player);
    return { ok: true };
  }

  function marinefordApplySupportDraw(player, helpers) {
    const hold = normalizeMarinefordHold(player);
    const unavailable = marinefordUnavailableWhitebeardIds();
    const used = new Set();
    hold.helpers = marinefordLimitSupportHelpers(player, helpers, { unavailable })
      .filter((entry) => {
        if (used.has(entry.cardId)) return false;
        used.add(entry.cardId);
        return true;
      })
      .map((entry) => {
        return {
          playerId: entry.playerId || player.id,
          playerName: entry.playerName || player.name,
          cardId: entry.cardId,
          source: "support",
          temporary: true,
        };
      });
    hold.setupStep = "ready";
    addLog(`${player.name} 抽出白鬍子海賊團支援：${hold.helpers.map((entry) => cardDisplayName(marinefordCardEntry(entry.cardId))).filter(Boolean).join("、") || "無"}。`);
    renderAll();
    notifyMarinefordWindow(player);
    return { ok: true };
  }

  function marinefordAssignExecution(player, slotIndex, cardId) {
    const hold = normalizeMarinefordHold(player);
    const index = Math.max(0, Math.min(3, Math.floor(Number(slotIndex || 0))));
    if (!WHITEBEARD_RECRUIT_CARD_IDS.has(cardId) || marinefordUnavailableWhitebeardIds().has(cardId)) return { ok: false, error: "角色不可用" };
    hold.slots[index] ||= {
      playerId: player.id,
      playerName: player.name,
      source: "whitebeard",
      canJoinOnWin: true,
      roundsLeft: marinefordExecutionTurnsFor(index),
    };
    hold.slots[index].playerId = hold.slots[index].playerId || player.id;
    hold.slots[index].playerName = hold.slots[index].playerName || player.name;
    hold.slots[index].cardId = cardId;
    hold.slots[index].source = "whitebeard";
    hold.slots[index].canJoinOnWin = true;
    hold.slots[index].roundsLeft = Math.max(0, Number(hold.slots[index].roundsLeft ?? marinefordExecutionTurnsFor(index)));
    hold.setupStep = hold.slots.every((slot) => slot?.cardId) ? "ready" : "chooseExecution";
    hold.selectedSlotIndex = hold.slots.findIndex((slot) => !slot?.cardId);
    if (hold.selectedSlotIndex < 0) hold.selectedSlotIndex = index;
    addLog(`${player.name} 選擇 ${cardDisplayName(marinefordCardEntry(cardId))} 上處刑台。`);
    renderAll();
    notifyMarinefordWindow(player);
    return { ok: true };
  }

  function marinefordUseHormone(player, playerId = player?.id) {
    const target = (state.gameState.players || []).find((entry) => entry.id === playerId) || player;
    const hold = normalizeMarinefordHold(player);
    if (!target || hold.hormoneUsed[target.id]) return { ok: false };
    hold.hormoneUsed[target.id] = true;
    hold.hormoneBoost[target.id] = true;
    (target.crew || []).forEach((card) => {
      const maxHp = cardMaxHp(card);
      card.currentHp = maxHp;
      (card.moveSet || []).forEach((move) => {
        move.currentPP = Math.max(0, Number(move.pp || move.currentPP || 0));
      });
    });
    recalcPlayerDerivedStats(target);
    addLog(`${target.name} 接受賀爾蒙注射，全隊 HP / PP 完全恢復，下次海軍本部戰鬥開場獲得強化。`);
    renderAll();
    notifyMarinefordWindow(player);
    return { ok: true };
  }

  function marinefordEnsureTemporaryHelpers(player, hold) {
    (hold.helpers || [])
      .filter((entry) => entry.playerId === player.id && WHITEBEARD_RECRUIT_CARD_IDS.has(entry.cardId))
      .forEach((entry) => {
        if ((player.crew || []).some((card) => card.id === entry.cardId && card.marinefordTemporary)) return;
        if ((player.crew || []).some((card) => card.id === entry.cardId && !card.marinefordTemporary)) return;
        const base = marinefordCardEntry(entry.cardId);
        if (!base) return;
        const recruit = cloneRecruitAtPartyFloor(player, base);
        recruit.marinefordTemporary = true;
        recruit.marinefordSupport = true;
        recruit.currentHp = cardMaxHp(recruit);
        (recruit.moveSet || []).forEach((move) => { move.currentPP = Number(move.pp || 0); });
        player.crew.push(recruit);
        queueRecruitSyncedMoveChoices(player, recruit);
      });
  }

  function marinefordRemoveTemporaryHelpers(player) {
    const before = (player.crew || []).length;
    player.crew = (player.crew || []).filter((card) => !card?.marinefordTemporary);
    if (player.activeCrewIndex >= player.crew.length) player.activeCrewIndex = Math.max(0, player.crew.length - 1);
    if (before !== player.crew.length) recalcPlayerDerivedStats(player);
  }

  function marinefordSelectBattleLeader(player, hold) {
    const captured = new Set((hold.slots || []).filter((slot) => slot.playerId === player.id && slot.source === "crew" && !slot.rescued).map((slot) => slot.cardId));
    const desired = hold.nextLeader?.[player.id] || "";
    const desiredIndex = (player.crew || []).findIndex((card) => card.id === desired && !captured.has(card.id) && Number(card.currentHp || 0) > 0);
    if (desiredIndex >= 0) {
      player.activeCrewIndex = desiredIndex;
      return true;
    }
    const fallback = (player.crew || []).findIndex((card) => !captured.has(card.id) && Number(card.currentHp || 0) > 0);
    if (fallback >= 0) {
      player.activeCrewIndex = fallback;
      return true;
    }
    return false;
  }

  function marinefordApplyOpeningBoost(player, battle, hold) {
    if (!hold.hormoneBoost?.[player.id]) return;
    ["atk", "def", "evasion"].forEach((stat) => {
      battle.playerStages[stat] = Math.min(BATTLE_STAGE_LIMIT, Number(battle.playerStages[stat] || 0) + 2);
      battle.playerStageTurns[stat] = 0;
    });
    hold.hormoneBoost[player.id] = false;
    battle.log.push("賀爾蒙注射效果發動：開場攻擊、防禦、閃避 +10%。");
  }

  function startMarinefordBattle(player) {
    if (isPendingMarinefordBattle(player?.pendingBattle) && canResumeBattle(player)) {
      return resumeMarinefordBattle(player) ? { ok: true } : { ok: false };
    }
    const hold = normalizeMarinefordHold(player);
    const island = getMarinefordIsland();
    const islandState = island ? getIslandState(island.id) : null;
    if (!player || !island || !islandState || !hold.active) return { ok: false };
    if (!hold.slots.some((slot) => slot.cardId)) return { ok: false, error: "尚未設定處刑台" };
    if (marinefordHasExpiredExecutionSlot(hold)) {
      if (hold.rescueDice > 0) return { ok: false, error: "處刑倒數已到 0，請先擲救援骰爭取時間。" };
      finishMarinefordRaid(player, false, "處刑倒數歸零");
      return { ok: false, error: "處刑倒數歸零" };
    }
    marinefordEnsureTemporaryHelpers(player, hold);
    if (!marinefordSelectBattleLeader(player, hold)) {
      finishMarinefordRaid(player, false, "沒有可出戰角色");
      return { ok: false };
    }
    const profile = marinefordBossProfile(hold.bossIndex);
    islandState.enemyProfile = profile;
    islandState.enemyTier = profile.tier;
    islandState.maxHp = profile.maxHp;
    islandState.currentHp = profile.maxHp;
    islandState.isDefeated = false;
    closeMarinefordPageOverlay();
    state.gameState.resolutionLock = false;
    state.battleState = createBattleState(player, island, islandState);
    state.battleState.islandKind = "marineford";
    state.battleState.isMarineford = true;
    state.battleState.canEscape = false;
    state.battleState.enemyTier = profile.tier;
    state.battleState.marineford = {
      playerId: player.id,
      bossIndex: hold.bossIndex,
      mode: hold.mode,
    };
    state.battleState.log = [`頂上戰爭篇 第 ${hold.bossIndex + 1}/${MARINEFORD_BOSSES.length} 戰：${profile.name} 出現。`];
    marinefordApplyOpeningBoost(player, state.battleState, hold);
    hold.started = true;
    hold.finished = false;
    hold.win = false;
    recordMainMissionEvent(player, { type: "marineford_started", bossIndex: hold.bossIndex });
    playBgmForContext(bgmBattleContext(state.battleState), { force: true });
    renderAll();
    ensureBattleRound(player, state.battleState);
    return { ok: true };
  }

  function marinefordTickExecutionTimers(hold, turns) {
    let expired = false;
    (hold.slots || []).forEach((slot) => {
      if (!slot.cardId || slot.rescued || slot.executed) return;
      slot.roundsLeft = Math.max(0, Number(slot.roundsLeft ?? marinefordExecutionTurnsFor(0)) - Math.max(0, Number(turns || 0)));
      if (slot.roundsLeft <= 0) expired = true;
    });
    marinefordRefreshExecutionTimerSummary(hold);
    return expired;
  }

  function marinefordRefreshExecutionTimerSummary(hold) {
    hold.rounds = (hold.slots || []).filter((slot) => slot.cardId && !slot.rescued && !slot.executed).reduce((min, slot) => Math.min(min, Number(slot.roundsLeft ?? 99)), 99);
    if (hold.rounds >= 99) hold.rounds = 0;
    return hold.rounds;
  }

  function marinefordGrantRescueBonusTurns(hold, amount) {
    const bonus = Math.max(0, Math.floor(Number(amount || 0)));
    if (!bonus) return 0;
    let applied = false;
    (hold.slots || []).forEach((slot) => {
      if (!slot.cardId || slot.rescued || slot.executed) return;
      slot.roundsLeft = Math.max(0, Number(slot.roundsLeft ?? 0)) + bonus;
      applied = true;
    });
    if (applied) marinefordRefreshExecutionTimerSummary(hold);
    return applied ? bonus : 0;
  }

  function marinefordHasExpiredExecutionSlot(hold) {
    return (hold.slots || []).some((slot) => slot.cardId && !slot.rescued && !slot.executed && Number(slot.roundsLeft || 0) <= 0);
  }

  function marinefordBattleTurnCost(battle) {
    return Math.max(1, Math.floor(Number(battle?.roundIndex || 1)));
  }

  function shouldAdvanceMarinefordBattleTurn() {
    return (state.gameState?.players || []).length > 1;
  }

  function finalizeMarinefordBattleStep(player, afterFinalize = null, options = {}) {
    const advanceTurn = options.advanceTurn === false ? false : shouldAdvanceMarinefordBattleTurn();
    const wrappedFinalize = () => {
      if (typeof afterFinalize === "function") afterFinalize();
      notifyMarinefordWindow(player);
    };
    const afterClear = typeof options.afterClear === "function" ? options.afterClear : () => openMarinefordWindow(player);
    finalizeBattleAndAdvanceTurn(player, wrappedFinalize, advanceTurn
      ? {}
      : { advanceTurn: false, afterClear });
  }

  function finishMarinefordRaid(player, win, reason = "") {
    const hold = normalizeMarinefordHold(player);
    hold.started = false;
    hold.finished = true;
    hold.win = Boolean(win);
    hold.helpers = [];
    hold.rescueDice = 0;
    marinefordRemoveTemporaryHelpers(player);
    if (win) {
      (hold.slots || []).forEach((slot) => { slot.rescued = true; });
      if (!hold.rewards.includes("3D2Y 的報紙")) hold.rewards.push("3D2Y 的報紙");
      grantFormalItemToPlayer(player, "new_world_newspaper_3d2y", 1, { reveal: true });
      grantCosmeticFrameToPlayer(player, "threeDTwoY");
      recordMissionEvent(player, { type: "marineford_clear", islandKind: "marineford" });
      addLog(`${player.name} 突破海軍本部，救出處刑台角色並獲得 3D2Y 的報紙。`);
    } else if (hold.mode === "wipe") {
      const ownersToReset = new Set();
      (hold.slots || []).forEach((slot) => {
        const owner = (state.gameState.players || []).find((entry) => entry.id === slot.playerId) || player;
        ownersToReset.add(owner);
        const index = (owner.crew || []).findIndex((card) => card.id === slot.cardId);
        const removed = index >= 0 ? owner.crew.splice(index, 1)[0] : null;
        if (removed) {
          returnRecruitCardToPool(marinefordCardEntry(removed.id) || removed);
          hold.returnedCardPool.push({ cardId: removed.id, fromPlayer: owner.name, clean: true });
          recalcPlayerDerivedStats(owner);
        }
        slot.executed = true;
      });
      ownersToReset.forEach((owner) => revivePlayerAtStart(owner));
      addLog(`${player.name} 海軍本部救援失敗，處刑台夥伴回歸招募池並清除額外養成，剩餘隊伍回到羅格鎮重新出發。${reason ? `（${reason}）` : ""}`);
    } else {
      const lost = marinefordGlobalList("marinefordLostWhitebeardIds");
      (hold.slots || []).forEach((slot) => {
        slot.executed = true;
        if (WHITEBEARD_RECRUIT_CARD_IDS.has(slot.cardId) && !lost.includes(slot.cardId)) lost.push(slot.cardId);
      });
      addLog(`${player.name} 海軍本部挑戰失敗，處刑台上的白鬍子成員之後不能再被選。${reason ? `（${reason}）` : ""}`);
    }
    recalcPlayerDerivedStats(player);
    notifyMarinefordWindow(player);
  }

  function finishMarinefordBattle(player, battle) {
    const hold = normalizeMarinefordHold(player);
    const won = battle.result === "win";
    if (won) {
      player.pendingBattle = null;
      const boss = battle.enemyCombatant?.name || "海軍本部敵人";
      const phaseIndex = Math.max(0, Math.min(MARINEFORD_BOSSES.length - 1, Number(battle.marineford?.bossIndex ?? hold.bossIndex ?? 0)));
      grantExpToLivingCrew(player, battle.activeCrewIndex, battleExpRewardForEnemy(battle.enemyTier || "T1", battle.enemyCombatant?.level || 90, 1.35), "頂上戰爭");
      recordDefeatedEnemy(player, battle, "頂上戰爭");
      recordMissionEvent(player, { type: "battle_win", tier: battle.enemyTier || "T1", islandKind: "marineford" });
      hold.started = false;
      hold.setupStep = "ready";
      const isFinal = phaseIndex >= MARINEFORD_BOSSES.length - 1;
      const turnCost = marinefordBattleTurnCost(battle);
      const expired = marinefordTickExecutionTimers(hold, turnCost);
      if (isFinal) {
        hold.bossIndex = MARINEFORD_BOSSES.length - 1;
        finalizeMarinefordBattleStep(player, () => {
          addLog(`${player.name} 擊敗 ${boss}，完成頂上戰爭篇。`);
          finishMarinefordRaid(player, true);
        }, { advanceTurn: false, afterClear: () => openMarinefordWindow(player) });
        return;
      }
      hold.rescueDice = Math.max(0, Math.floor(Number(hold.rescueDice || 0))) + 1;
      recordMainMissionEvent(player, { type: "marineford_rescue_die", bossIndex: phaseIndex });
      const stillExpired = marinefordHasExpiredExecutionSlot(hold);
      hold.bossIndex = Math.min(MARINEFORD_BOSSES.length - 1, phaseIndex + 1);
      if (expired && stillExpired && hold.rescueDice <= 0) {
        finalizeMarinefordBattleStep(player, () => finishMarinefordRaid(player, false, "處刑倒數歸零"));
        return;
      }
      finalizeMarinefordBattleStep(player, () => {
        addLog(`${player.name} 擊敗 ${boss}，獲得 1 顆救援骰，可在頂上戰爭頁面選擇時機擲出。`);
      });
      return;
    }
    if (battle.result === "lose" || battle.result === "knockout") {
      player.pendingBattle = null;
      finalizeMarinefordBattleStep(player, () => finishMarinefordRaid(player, false, "戰鬥失敗"));
      return;
    }
    const turnCost = marinefordBattleTurnCost(battle);
    const expired = marinefordTickExecutionTimers(hold, turnCost);
    hold.started = false;
    hold.setupStep = "ready";
    if (expired) {
      player.pendingBattle = null;
      finalizeMarinefordBattleStep(player, () => finishMarinefordRaid(player, false, "處刑倒數歸零"));
      return;
    }
    const pending = cloneBattleState(battle);
    pending.playerId = player.id;
    pending.isMarineford = true;
    pending.islandKind = "marineford";
    pending.canEscape = false;
    player.pendingBattle = pending;
    finalizeMarinefordBattleStep(player, () => {
      addLog(`${player.name} 暫停頂上戰爭篇第 ${Number(hold.bossIndex || 0) + 1} 戰，下一次輪到時從目前 HP 繼續。`);
    });
  }

  function marinefordJoinSlot(player, slotIndex, replaceCrewIndex = -1) {
    const hold = normalizeMarinefordHold(player);
    const slot = hold.slots[Math.max(0, Number(slotIndex || 0))];
    if (!slot?.cardId || !WHITEBEARD_RECRUIT_CARD_IDS.has(slot.cardId) || !hold.win) return { ok: false };
    const owner = (state.gameState.players || []).find((entry) => entry.id === slot.playerId) || player;
    if ((owner.crew || []).some((card) => card.id === slot.cardId)) return { ok: false };
    const base = marinefordCardEntry(slot.cardId);
    if (!base) return { ok: false };
    const recruit = cloneRecruitAtPartyFloor(owner, base);
    let replaced = null;
    if ((owner.crew || []).length >= TEAM_LIMIT) {
      const index = Math.floor(Number(replaceCrewIndex));
      if (index < 0 || index >= owner.crew.length) return { ok: false, error: "隊伍已滿，需選擇替換角色" };
      replaced = owner.crew[index];
      const returnedCarryName = returnBattleCarryFromRemovedCard(owner, replaced);
      const returnedPrisoner = returnImpelDownPrisonerToPool(owner, replaced);
      const returnedToRecruitPool = returnedPrisoner ? false : returnRecruitCardToPool(replaced);
      owner.crew.splice(index, 1, recruit);
      if (owner.activeCrewIndex === index) owner.activeCrewIndex = index;
      if (owner.activeCrewIndex >= owner.crew.length) owner.activeCrewIndex = 0;
      if (returnedCarryName) addLog(`${cardDisplayName(replaced)} 的 ${returnedCarryName} 已回到背包。`);
      if (returnedPrisoner) addLog(`${cardDisplayName(replaced)} 回到推進城隱藏囚犯抽池。`);
      else if (returnedToRecruitPool) addLog(`${cardDisplayName(replaced)} 回到可招募角色池。`);
    } else {
      owner.crew.push(recruit);
    }
    queueRecruitSyncedMoveChoices(owner, recruit);
    const joined = marinefordGlobalList("marinefordJoinedWhitebeardIds");
    if (!joined.includes(slot.cardId)) joined.push(slot.cardId);
    hold.joinedWhitebeard = Array.from(new Set([...hold.joinedWhitebeard, slot.cardId]));
    recalcPlayerDerivedStats(owner);
    addLog(replaced ? `${owner.name} 讓 ${cardDisplayName(recruit)} 替換 ${cardDisplayName(replaced)}，正式加入隊伍。` : `${owner.name} 讓 ${cardDisplayName(recruit)} 正式加入隊伍。`);
    renderAll();
    notifyMarinefordWindow(player);
    schedulePendingMoveLearn(120);
    return { ok: true };
  }

  function marinefordDeclineSlot(player, slotIndex) {
    const hold = normalizeMarinefordHold(player);
    hold.slots.splice(Math.max(0, Number(slotIndex || 0)), 1);
    renderAll();
    notifyMarinefordWindow(player);
    return { ok: true };
  }

  function marinefordRollRescueDie(player) {
    const hold = normalizeMarinefordHold(player);
    if (!hold.active || hold.finished) return { ok: false, message: "頂上戰爭已結束。" };
    if (hold.rescueDice <= 0) return { ok: false, message: "目前沒有救援骰。" };
    const hasTarget = (hold.slots || []).some((slot) => slot.cardId && !slot.rescued && !slot.executed);
    if (!hasTarget) return { ok: false, message: "沒有可增加倒數的處刑台角色。" };
    const roll = randomInt(1, MARINEFORD_RESCUE_BONUS_DICE_MAX);
    hold.rescueDice = Math.max(0, Math.floor(Number(hold.rescueDice || 0))) - 1;
    const bonus = marinefordGrantRescueBonusTurns(hold, roll);
    addLog(`${player.name} 擲出頂上戰爭救援骰 ${roll}，處刑倒數 +${bonus} 回合。`);
    renderAll();
    notifyMarinefordWindow(player);
    return { ok: true, roll, bonus, rescueDice: hold.rescueDice, rounds: hold.rounds };
  }

  function marinefordClose(player) {
    const hold = normalizeMarinefordHold(player);
    if (hold.finished) hold.active = false;
    closeMarinefordPageOverlay();
    renderAll();
    if (hold.finished) endTurn();
    return { ok: true };
  }

  let lastProcessedMarinefordCommandId = "";

  function writeMarinefordCommandResult(command, result) {
    if (!command?.id) return;
    try {
      const player = currentPlayer();
      localStorage.setItem(MARINEFORD_COMMAND_RESULT_KEY, JSON.stringify({
        commandId: command.id,
        type: command.type || "",
        updatedAt: Date.now(),
        result: result || null,
        view: player ? getMarinefordView(player) : null,
      }));
    } catch (_error) {}
  }

  function processMarinefordPageCommand(command) {
    if (!command || command.id === lastProcessedMarinefordCommandId) return;
    lastProcessedMarinefordCommandId = command.id;
    const player = currentPlayer();
    if (!player) return;
    if (warnBoardLanTurnLocked(player)) {
      writeMarinefordCommandResult(command, { ok: false, message: "現在不是你的回合，不能操作海軍本部。" });
      return;
    }
    const payload = command.payload || {};
    let result = null;
    if (command.type === "ready") result = { ok: true };
    else if (command.type === "rulesShown") {
      normalizeMarinefordHold(player).rulesShown = true;
      result = { ok: true };
    } else if (command.type === "drawCrew") result = marinefordApplyCrewDraw(player, payload.slots);
    else if (command.type === "drawSupport") result = marinefordApplySupportDraw(player, payload.helpers);
    else if (command.type === "assignExecution") result = marinefordAssignExecution(player, payload.slotIndex, payload.cardId);
    else if (command.type === "startRaid") {
      const hold = normalizeMarinefordHold(player);
      hold.started = true;
      hold.finished = false;
      hold.win = false;
      notifyMarinefordWindow(player);
      result = { ok: true };
    } else if (command.type === "startBattle") result = startMarinefordBattle(player);
    else if (command.type === "rollRescueDie") result = marinefordRollRescueDie(player);
    else if (command.type === "switchLeader") {
      const targetPlayerId = payload.playerId || player.id;
      const target = (state.gameState.players || []).find((entry) => entry.id === targetPlayerId) || player;
      const hold = normalizeMarinefordHold(player);
      const cardId = payload.cardId || "";
      const captured = new Set((hold.slots || [])
        .filter((slot) => slot.playerId === target.id && slot.source === "crew" && !slot.rescued)
        .map((slot) => slot.cardId));
      const index = (target.crew || []).findIndex((card) => card.id === cardId && !captured.has(card.id) && Number(card.currentHp || 0) > 0);
      const pendingHelper = (hold.helpers || []).some((entry) => entry.playerId === target.id && entry.cardId === cardId);
      if (index >= 0) target.activeCrewIndex = index;
      if (cardId && (index >= 0 || pendingHelper)) hold.nextLeader[target.id] = cardId;
      else delete hold.nextLeader[target.id];
      renderAll();
      notifyMarinefordWindow(player);
      result = { ok: true };
    } else if (command.type === "useHormone") result = marinefordUseHormone(player, payload.playerId);
    else if (command.type === "joinSlot") result = marinefordJoinSlot(player, payload.slotIndex, payload.replaceCrewIndex);
    else if (command.type === "declineSlot") result = marinefordDeclineSlot(player, payload.slotIndex);
    else if (command.type === "close") result = marinefordClose(player);
    writeMarinefordCommandResult(command, result);
  }

  function readMarinefordPageCommand() {
    try {
      const raw = localStorage.getItem(MARINEFORD_COMMAND_KEY);
      if (!raw) return;
      processMarinefordPageCommand(JSON.parse(raw));
    } catch (_error) {
      // Ignore malformed cross-window commands.
    }
  }

  let lastProcessedImpelDownCommandId = "";

  function writeImpelDownCommandResult(command, result) {
    if (!command?.id) return;
    try {
      const player = impelCurrentPlayer() || currentPlayer();
      localStorage.setItem(IMPEL_DOWN_COMMAND_RESULT_KEY, JSON.stringify({
        commandId: command.id,
        type: command.type || "",
        updatedAt: Date.now(),
        result: result || null,
        view: player ? getImpelDownView(player) : null,
      }));
    } catch (_error) {
      // Direct iframe calls return their result synchronously; this is for the storage bridge.
    }
  }

  function processImpelDownPageCommand(command) {
    if (!command || command.id === lastProcessedImpelDownCommandId) return;
    lastProcessedImpelDownCommandId = command.id;
    const player = impelCurrentPlayer() || currentPlayer();
    if (player && warnBoardLanTurnLocked(player)) {
      writeImpelDownCommandResult(command, { ok: false, message: "現在不是你的回合，不能操作推進城。" });
      return;
    }
    const payload = command.payload || {};
    let result = null;
    if (command.type === "rollEscape") result = impelRollEscape();
    else if (command.type === "drawEvent") result = impelDrawEvent();
    else if (command.type === "resolveEventPrimary") result = impelResolveEventPrimary();
    else if (command.type === "resolveEventSecondary") result = impelResolveEventSecondary();
    else if (command.type === "move") result = impelMove(payload.direction);
    else if (command.type === "directEscape") result = impelDirectEscape();
    else if (command.type === "selectRecruit") result = impelSelectRecruit(payload.prisonerId);
    else if (command.type === "boostRecruit") result = impelBoostRecruit();
    else if (command.type === "drawRecruit") result = impelDrawRecruit();
    else if (command.type === "skipRecruit") result = impelSkipRecruit();
    else if (command.type === "switchLeader") result = impelSwitchLeader(Number(payload.index));
    else if (command.type === "invitePlayer") result = impelInvitePlayer(payload);
    else if (command.type === "acceptTeamInvite") result = impelAcceptTeamInvite();
    else if (command.type === "declineTeamInvite") result = impelDeclineTeamInvite();
    else if (command.type === "endTurn") result = impelEndTurn();
    else if (command.type === "close") result = impelClose();
    writeImpelDownCommandResult(command, result);
  }

  function readImpelDownPageCommand() {
    try {
      const raw = localStorage.getItem(IMPEL_DOWN_COMMAND_KEY);
      if (!raw) return;
      processImpelDownPageCommand(JSON.parse(raw));
    } catch (_error) {
      // Ignore malformed cross-window commands.
    }
  }

  function getBattleRewards(battle) {
    if (battle.isJudicialRaid || battle.islandKind === "judicial") {
      return { coins: 0, bounty: 0, exp: 0, item: "", itemText: "通關後統一發放", summary: "司法島共鬥獎勵會在通關後依貢獻統一發放" };
    }
    const enemyLevel = Number(battle.enemyCombatant?.level || enemyLevelForProgress(battle.enemyTier));
    if (battle.isFinalGate || battle.islandKind === "final_gate") {
      const exp = battleExpRewardForEnemy(battle.enemyTier || "T1", enemyLevel, 2.8);
      return cacheBattleRewardPayload(battle, () => addBattleCarryEnemyLootToReward(battle, {
        coins: 30000,
        bounty: 500000000,
        exp,
        item: "",
        itemText: "無道具",
        summary: `獲得 30000 貝里、5億賞金與 ${exp} EXP`,
      }));
    }
    if (battle.isSeaEncounter || battle.islandKind === "sea-encounter") {
      const seaRewards = {
        T5: { coins: 660, bounty: 10000000, item: "" },
        T4: { coins: 1020, bounty: 12000000, item: "" },
        T3: { coins: 1560, bounty: 18000000, item: "" },
        T2: { coins: 2280, bounty: 28000000, item: "" },
        T1: { coins: 3150, bounty: 42000000, item: "" },
      };
      const reward = {
        ...(seaRewards[battle.enemyTier] || seaRewards.T5),
        exp: battleExpRewardForEnemy(battle.enemyTier, enemyLevel, 1.15),
      };
      return cacheBattleRewardPayload(battle, () => {
        const shipRewards = rollSeaEncounterShipRewards(battle);
        const shipRewardText = shipRewardSummaryText(shipRewards);
        return addBattleCarryEnemyLootToReward(battle, {
          ...reward,
          item: "",
          shipRewards,
          itemText: "無道具",
          summary: `獲得 ${reward.coins} 貝里、${formatCoin(reward.bounty)} 賞金與 ${reward.exp} EXP${shipRewardText ? `，船隻獎賞：${shipRewardText}` : ""}`,
        });
      });
    }
    if (battle.islandKind === "yonko") {
      const exp = battleExpRewardForEnemy(battle.enemyTier || "T1", enemyLevel, 2.2);
      return cacheBattleRewardPayload(battle, () => addBattleCarryEnemyLootToReward(battle, {
        coins: 15600,
        bounty: 120000000,
        exp,
        item: "",
        itemText: "無道具",
        summary: `獲得 15600 貝里、1億2000萬賞金與 ${exp} EXP`,
      }));
    }
    const tierRewards = {
      T5: { coins: 1260, bounty: 10000000 },
      T4: { coins: 2040, bounty: 18000000 },
      T3: { coins: 2940, bounty: 32000000 },
      T2: { coins: 4350, bounty: 55000000 },
      T1: { coins: 6300, bounty: 90000000 },
    };
    const reward = {
      ...(tierRewards[battle.enemyTier] || { coins: 1260, bounty: 10000000 }),
      exp: battleExpRewardForEnemy(battle.enemyTier, enemyLevel, 1.5),
    };
    return cacheBattleRewardPayload(battle, () => addBattleCarryEnemyLootToReward(battle, {
      ...reward,
      item: "",
      itemText: "無道具",
      summary: `獲得 ${reward.coins} 貝里、${formatCoin(reward.bounty)} 賞金與 ${reward.exp} EXP`,
    }));
  }

  function playerHasEquippedCarry(player, itemId) {
    return (player?.crew || []).some((card) => cardHasBattleCarryItem(card, itemId));
  }

  function participatingBattleCarryEntries(player, battle) {
    const participated = battleParticipatedCrewIndexSet(player, battle);
    return (player?.crew || [])
      .flatMap((card, index) => battleCarryItemsForCard(card).map((item) => ({ card, index, item })))
      .filter((entry) => participated.has(entry.index) && !postgameBulletCarryIsAbsorbed(battle, entry.card, entry.index))
      .map((entry) => ({ ...entry, effect: battleCarryItemEffect(entry.item) }));
  }

  function goldRingsBattleCoinBonus(player, battle, baseCoins) {
    const entry = participatingBattleCarryEntries(player, battle)
      .find(({ effect }) => effect.kind === "postgame_tesoro_gold_rings");
    if (!entry) return 0;
    return Math.max(0, Math.round(Number(baseCoins || 0) * Number(entry.effect.battleCoinBonus || 2)));
  }

  function applyBattleRewardBonuses(player, reward, battle, options = {}) {
    const next = { ...reward };
    const silent = !!options.silent;
    const baseCoins = Math.max(0, Number(reward?.coins || 0));
    const carryEntries = participatingBattleCarryEntries(player, battle);
    const coinCarry = carryEntries.find((entry) => entry.item?.id === "treasure_coin" || entry.effect.kind === "battle_coin_bonus_if_participated");
    if (coinCarry) {
      const bonusRate = Number(coinCarry.effect.bonus || 0.5);
      const bonus = Math.max(0, Math.round(baseCoins * bonusRate));
      next.coins = Math.max(0, Number(next.coins || 0) + bonus);
      if (!silent && bonus > 0) addLog(`寶藏幸運金幣讓這場戰鬥收穫增加，金幣 +${bonus}。`);
    }
    if (!options.skipGoldRings) {
      const bonus = goldRingsBattleCoinBonus(player, battle, baseCoins);
      next.coins = Math.max(0, Number(next.coins || 0) + bonus);
      if (!silent && bonus > 0) addLog(`Gran Tesoro 黃金戒讓這場勝利的貝里 +200%，額外獲得 ${bonus} 貝里。`);
    }
    const buffs = Array.isArray(player?.activeMapBuffs) ? player.activeMapBuffs : [];
    const coinBuff = buffs.find((buff) => buff?.kind === "increase_encounter_with_reward");
    if (coinBuff?.data?.coinBonusOnWin) {
      const bonus = Math.max(0, Math.round(Number(next.coins || 0) * Number(coinBuff.data.coinBonusOnWin || 0)));
      next.coins += bonus;
      if (!silent && bonus > 0) addLog(`航海道具效果讓勝利金幣 +${bonus}。`);
    }
    const expBuff = buffs.find((buff) => buff?.kind === "increase_battle_event_with_exp");
    if (expBuff?.data?.expBonusOnWin) {
      const bonus = Math.max(0, Math.round(Number(next.exp || 0) * Number(expBuff.data.expBonusOnWin || 0)));
      next.exp += bonus;
      if (!silent && bonus > 0) addLog(`航海道具效果讓戰鬥經驗 +${bonus}。`);
    }
    return next;
  }

  function clearBattleTransientState(options = {}) {
    const deferOverlayClose = !!options.deferOverlayClose;
    clearBattleRefreshRecoveryCheckpoint(state.battleState);
    if (state.battleState) {
      postgameBossMechanicRestoreBulletArsenalCarriers(battlePlayer(null, state.battleState), state.battleState);
    }
    state.battleState = null;
    if (!deferOverlayClose) closeBattlePageOverlay();
    state.battleWindow = null;
    state.gameState.routePrompt = null;
    state.gameState.islandDecision = null;
    state.gameState.coopBattlePrompt = null;
    state.gameState.pendingMove = null;
    state.gameState.resolutionLock = false;
  }

  function finalizeBattleAndAdvanceTurn(player, afterFinalize, options = {}) {
    if (state.gameState.battleExitLock) return;
    state.gameState.battleExitLock = true;
    if (typeof afterFinalize === "function") afterFinalize();
    const shouldAdvanceTurn = options.advanceTurn !== false;
    const afterClear = typeof options.afterClear === "function" ? options.afterClear : null;
    if (shouldAdvanceTurn) {
      closeModal();
      // Important post-battle drops (Boss clue cards, lineage factors, etc.)
      // are rendered by the map page. Do not leave the full-screen battle
      // iframe above that reveal while endTurn is deliberately waiting for
      // the player to dismiss it, otherwise returning appears to be frozen.
      if (itemRevealIsPending()) {
        closeBattlePageOverlay();
        notifyBattleWindow();
      }
      endTurn({
        context: "battle",
        subtitle: "準備切換到下一位玩家。",
        keepBattleExitLock: true,
        beforeAnnouncement: () => {
          clearBattleTransientState({ deferOverlayClose: true });
          state.gameState.battleExitLock = false;
        },
        beforeVisualUpdate: () => {
          closeBattlePageOverlay();
          notifyBattleWindow();
        },
        afterVisualUpdate: () => {
          schedulePendingMoveLearn();
          state.gameState.battleExitLock = false;
        },
      });
    } else {
      clearBattleTransientState();
      closeModal();
      renderAll();
      notifyBattleWindow();
      if (afterClear) afterClear();
      state.gameState.battleExitLock = false;
    }
  }

  function persistCoopBattlePendingForParticipants(battle) {
    if (!isCoopBattle(battle)) return [];
    const saved = [];
    coopBattleParticipants(battle).forEach((participant) => {
      if (!participant) return;
      const runtime = coopBattleRuntimeFor(participant, battle, false);
      participant.activeCrewIndex = Math.max(0, Number(runtime?.activeCrewIndex ?? participant.activeCrewIndex ?? 0));
      recalcPlayerDerivedStats(participant);
      if (runtime?.escaped || runtime?.defeated) {
        participant.pendingBattle = null;
        return;
      }
      const pendingBattle = cloneBattleState(battle);
      const pendingRuntime = pendingBattle.coop?.runtimes?.[String(participant.id)] || runtime;
      if (pendingRuntime) applyCoopBattleRuntimeSnapshot(participant, pendingBattle, pendingRuntime);
      pendingBattle.playerId = participant.id;
      pendingBattle.needsReplacement = false;
      participant.pendingBattle = pendingBattle;
      saved.push(participant);
    });
    return saved;
  }

  function clearActiveCoopPendingBattles(battle) {
    if (!isCoopBattle(battle)) return [];
    const cleared = [];
    coopBattleParticipants(battle).forEach((participant) => {
      if (!participant) return;
      participant.pendingBattle = null;
      cleared.push(participant);
    });
    return cleared;
  }

  function judicialRaidParticipationMultiplier(score) {
    if (score <= 0) return 0;
    if (score < 80) return 0.3;
    if (score < 200) return 0.6;
    return 1;
  }

  function grantExpToLivingCrew(player, activeIndex, exp, sourceLabel = "") {
    const expResults = [];
    const totalExp = Math.max(0, Math.round(Number(exp || 0)));
    if (totalExp <= 0) return;
    const averageLevel = crewAverageLevelForExp(player);
    (player.crew || []).forEach((card, index) => {
      if (!card) return;
      const currentHpValue = Number(card.currentHp);
      const isFainted = Number.isFinite(currentHpValue) && currentHpValue <= 0;
      const isActive = index === activeIndex;
      const shareRatio = isFainted ? FAINTED_CREW_EXP_RATIO : (isActive ? 1 : SUPPORT_CREW_EXP_RATIO);
      const baseExp = Math.max(1, Math.round(totalExp * shareRatio));
      const bonusInfo = cardSelfExpBonusInfo(card);
      let expAmount = applyLowLevelExpCatchup(baseExp, card, averageLevel);
      if (bonusInfo) expAmount = Math.max(1, Math.round(expAmount * (1 + bonusInfo.bonus)));
      const result = gainCardExp(card, expAmount);
      if (result.gainedExp > 0) expResults.push({ card, result, isActive, isFainted, bonusInfo });
    });
    expResults.forEach(({ card, result, isActive, isFainted, bonusInfo }) => {
      const roleLabel = isFainted ? "（瀕死成長）" : (isActive ? "" : "（支援成長）");
      const sourceText = sourceLabel ? `（${sourceLabel}）` : "";
      const bonusText = bonusInfo ? `，${bonusInfo.itemName}+${Math.round(bonusInfo.bonus * 100)}%` : "";
      addLog(`${card.name}${roleLabel} 獲得 ${result.gainedExp} EXP${sourceText}${bonusText}。`);
      if (result.levelsGained > 0) {
        const gains = statGainText(result.statGain);
        addLog(`${card.name} 從 Lv.${result.fromLevel} 升到 Lv.${result.toLevel}${gains ? `，能力提升：${gains}` : ""}。`);
      }
      result.learnedMoves.forEach((moveName) => addLog(`${card.name} 學會了 ${moveName}。`));
      (result.pendingMoveChoices || []).forEach((choice) => {
        addLog(`${card.name} 達到 Lv.${choice.unlockLevel || effectiveMoveUnlockLevel(card.moveSet.find((move) => move.id === choice.moveId))}，可以學習 ${choice.moveName}。`);
        queueMoveLearnChoice(player, card, choice.moveId);
      });
    });
    if (expResults.length) {
      recordMissionEvent(player, { type: "crew_exp", amount: 1 });
      if (expResults.some(({ result }) => Number(result.levelsGained || 0) > 0)) {
        recordMissionEvent(player, { type: "crew_level", amount: 1 });
      }
    }
    recalcPlayerDerivedStats(player);
  }

  function cardSelfExpBonusInfo(card) {
    const entries = battleCarryItemsForCard(card)
      .map((item) => ({ item, effect: battleCarryItemEffect(item) }))
      .filter(({ effect }) => effect?.kind === "exp_bonus_self");
    if (!entries.length) return null;
    const bonus = entries.reduce((sum, { effect }) => sum + Math.max(0, Number(effect.bonus || 0)), 0);
    if (bonus <= 0) return null;
    return {
      bonus,
      itemName: entries.map(({ item }) => battleCarryItemName(item)).join("＋"),
    };
  }

  function battleEnemyIdentityKey(battle) {
    const enemy = battle?.enemyCombatant || {};
    return String(enemy.key || enemy.id || enemy.name || "").trim();
  }

  function enemyReservationLocationKeyForIslandId(islandId) {
    const id = String(islandId || "").trim();
    return id ? `island:${id}` : "";
  }

  function enemyReservationLocationKeyForIsland(island) {
    return enemyReservationLocationKeyForIslandId(island?.id);
  }

  function enemyReservationLocationKeyForSea(tile, player) {
    if (player?.location?.kind === "route") {
      return `route:${String(player.location.routeId || "")}:${Number(player.location.tileIndex ?? -1)}`;
    }
    const routeId = String(tile?.routeId || "").trim();
    const tileIndex = Number(tile?.index ?? -1);
    if (routeId || tileIndex >= 0) return `route:${routeId}:${tileIndex}`;
    const tileId = String(tile?.id || "").trim();
    return tileId ? `sea:${tileId}` : "";
  }

  function enemyReservationLocationKeyForBattle(battle) {
    if (!battle) return "";
    if (battle.isSeaEncounter || battle.islandKind === "sea-encounter") {
      const routeId = String(battle.routeId || battle.seaTile?.routeId || "").trim();
      const tileIndex = Number(battle.tileIndex ?? battle.seaTile?.index ?? -1);
      if (routeId || tileIndex >= 0) return `route:${routeId}:${tileIndex}`;
      const tileId = String(battle.seaTileId || battle.seaTile?.id || "").trim();
      return tileId ? `sea:${tileId}` : "";
    }
    return enemyReservationLocationKeyForIslandId(battle.islandId);
  }

  function battleStillReservesEnemy(battle) {
    if (!battle) return false;
    const result = String(battle.result || "");
    return !["win", "escape", "lose"].includes(result);
  }

  function activeEnemyReservationKeys(options = {}) {
    const reserved = new Set();
    const skipLocationKey = String(options.skipLocationKey || "").trim();
    const addBattle = (battle) => {
      if (!battleStillReservesEnemy(battle)) return;
      const key = battleEnemyIdentityKey(battle);
      if (!key) return;
      const locationKey = enemyReservationLocationKeyForBattle(battle);
      if (skipLocationKey && locationKey && locationKey === skipLocationKey) return;
      reserved.add(key);
    };
    addBattle(state.battleState);
    (state.gameState?.players || []).forEach((player) => addBattle(player?.pendingBattle));
    return reserved;
  }

  function isSharedClearEligibleEnemyIslandBattle(battle, island) {
    if (!battle || !battle.islandId) return false;
    if (battle.isSeaEncounter || battle.isJudicialRaid || battle.isImpelDown || battle.isMarineford) return false;
    if (isFinalGateBattle(battle) || isElbaphGodKnightBattle(battle)) return false;
    return ["enemy", "postgame_boss", "postgame_egghead"].includes(battle.islandKind) || ["enemy", "postgame_boss", "postgame_egghead"].includes(island?.kind);
  }

  function pendingBattleMatchesSharedEnemyIslandClear(player, battle) {
    const pending = player?.pendingBattle;
    if (!pending || !battle?.islandId) return false;
    if (String(pending.islandId || "") !== String(battle.islandId || "")) return false;
    if (pending.isSeaEncounter || pending.isJudicialRaid || pending.isImpelDown || pending.isMarineford) return false;
    if (isFinalGateBattle(pending) || isElbaphGodKnightBattle(pending)) return false;
    if (pending.islandKind && !["enemy", "postgame_boss", "postgame_egghead"].includes(pending.islandKind)) return false;
    const pendingKey = battleEnemyIdentityKey(pending);
    const battleKey = battleEnemyIdentityKey(battle);
    if (pendingKey && battleKey && pendingKey !== battleKey) return false;
    return true;
  }

  function sharedEnemyIslandClearParticipants(winner, battle) {
    const winnerId = String(winner?.id || "");
    const participants = (state.gameState.players || []).filter((entry) => (
      entry
      && String(entry.id || "") !== winnerId
      && pendingBattleMatchesSharedEnemyIslandClear(entry, battle)
    ));
    if (isCoopBattle(battle)) {
      coopBattleParticipants(battle).forEach((entry) => {
        if (!entry || String(entry.id || "") === winnerId) return;
        if (!participants.some((item) => String(item.id || "") === String(entry.id || ""))) {
          participants.push(entry);
        }
      });
    }
    return participants;
  }

  function rewardLineForSharedEnemyClear(rewards) {
    const parts = [];
    if (Number(rewards?.coins || 0) > 0) parts.push(`貝里 +${Math.round(Number(rewards.coins || 0))}`);
    if (Number(rewards?.bounty || 0) > 0) parts.push(`懸賞金 +${formatCoin(rewards.bounty)}`);
    if (Number(rewards?.exp || 0) > 0) parts.push(`EXP +${Math.round(Number(rewards.exp || 0))}`);
    return parts.join("、") || "戰鬥參與紀錄";
  }

  function battleRewardItemText(rewards) {
    const grantedItems = Array.isArray(rewards?.grantedItems)
      ? rewards.grantedItems.map(String).filter(Boolean)
      : [];
    if (grantedItems.length) return grantedItems.join("、");
    if (rewards?.battleCarryDropLabel) return rewards.battleCarryDropLabel;
    if (rewards?.battleCarryDropName) return rewards.battleCarryDropName;
    if (rewards?.itemText && rewards.itemText !== "無道具") return rewards.itemText;
    if (rewards?.itemDrop?.name) return rewards.itemDrop.name;
    if (rewards?.item) return rewards.item;
    const shipText = shipRewardSummaryText(rewards?.shipRewards || []);
    return shipText || rewards?.itemText || "無道具";
  }

  function battleRewardDetailForPlayer(player, rewards, battle, placeName = "") {
    return {
      playerId: player?.id || "",
      playerName: player?.name || "玩家",
      placeName: placeName || battle?.enemyCombatant?.name || "共鬥戰鬥",
      coins: Math.max(0, Math.round(Number(rewards?.coins || 0))),
      bounty: Math.max(0, Math.round(Number(rewards?.bounty || 0))),
      bountyText: formatCoin(rewards?.bounty || 0),
      exp: Math.max(0, Math.round(Number(rewards?.exp || 0))),
      itemText: battleRewardItemText(rewards),
      summary: rewards?.summary || rewardLineForSharedEnemyClear(rewards),
    };
  }

  function battleRewardPlaceName(battle) {
    if (!battle) return "共鬥戰鬥";
    if (battle.isSeaEncounter || battle.islandKind === "sea-encounter") return "海格遭遇戰";
    return getIslandById(battle.islandId)?.name || battle.enemyCombatant?.name || "共鬥戰鬥";
  }

  function coopBattleRewardRecipients(battle, fallbackPlayer = null) {
    if (!isCoopBattle(battle)) return fallbackPlayer ? [fallbackPlayer] : [];
    const byId = (id) => (state.gameState.players || []).find((entry) => String(entry?.id || "") === String(id || ""));
    const storedIds = Array.isArray(battle.coopRewardRecipientIds) ? battle.coopRewardRecipientIds.map(String).filter(Boolean) : [];
    const storedRecipients = storedIds.map(byId).filter(Boolean);
    if (storedRecipients.length) return storedRecipients;
    const recipients = coopBattleParticipants(battle).filter((entry) => {
      const runtime = coopBattleRuntimeFor(entry, battle, false);
      return entry && !runtime?.escaped && !runtime?.defeated;
    });
    if (fallbackPlayer && !recipients.some((entry) => String(entry?.id || "") === String(fallbackPlayer.id || ""))) {
      recipients.unshift(fallbackPlayer);
    }
    return recipients;
  }

  function ensureCoopBattleResultTurnPlayer(battle) {
    if (!isCoopBattle(battle) || battle?.result !== "win") return battleCommandPlayer(battle);
    const participants = coopBattleParticipants(battle);
    const byId = (id) => participants.find((entry) => String(entry?.id || "") === String(id || "")) || null;
    const deferredId = String(battle.deferredCoopResult?.playerId || "");
    const savedId = String(battle.coopResultTurnPlayerId || "");
    const boardTurnPlayer = currentPlayer();
    const resultPlayer = byId(deferredId)
      || byId(savedId)
      || byId(boardTurnPlayer?.id)
      || battleCommandPlayer(battle)
      || participants[0]
      || null;
    if (resultPlayer) {
      battle.coopResultTurnPlayerId = String(resultPlayer.id || "");
      battle.playerId = resultPlayer.id;
    }
    return resultPlayer;
  }

  function lineageExtractionResultPlayerReady(battle) {
    const extraction = ensureLineageExtractionOpportunity(battle);
    if (!extraction) return true;
    if (!isCoopBattle(battle) || battle?.result !== "win") return lineageExtractionAllResolved(battle);
    const resultPlayer = ensureCoopBattleResultTurnPlayer(battle);
    const playerId = String(resultPlayer?.id || "");
    const entry = extraction.entries?.[playerId] || null;
    return !entry || LINEAGE_EXTRACTION_TERMINAL_STATUSES.has(entry.status);
  }

  function coopDeferredResultSourceId(battle) {
    if (!battle) return "";
    if (!battle.coopDeferredResultSourceId) {
      battle.coopDeferredResultSourceId = [
        lineageExtractionScopeKey(battle),
        Math.max(0, Number(battle.roundIndex || 0)),
        Date.now().toString(36),
      ].join("|");
    }
    return String(battle.coopDeferredResultSourceId);
  }

  function queueDeferredCoopBattleResults(battle, resultPlayer) {
    if (!isCoopBattle(battle) || battle?.result !== "win" || battle?.deferredCoopResult) return [];
    ensureCoopBattleRewardPreview(battle, resultPlayer);
    const extraction = ensureLineageExtractionOpportunity(battle);
    const resultPlayerId = String(resultPlayer?.id || "");
    const sourceId = coopDeferredResultSourceId(battle);
    battle.coopDeferredResultQueuedPlayerIds = Array.isArray(battle.coopDeferredResultQueuedPlayerIds)
      ? [...new Set(battle.coopDeferredResultQueuedPlayerIds.map(String).filter(Boolean))]
      : [];
    const queued = [];
    coopBattleRewardRecipients(battle, resultPlayer).forEach((participant) => {
      const participantId = String(participant?.id || "");
      if (!participantId || participantId === resultPlayerId || isCpuPlayer(participant)) return;
      const id = `${sourceId}|${participantId}`;
      const participantQueue = normalizePendingCoopBattleResults(participant);
      if (battle.coopDeferredResultQueuedPlayerIds.includes(participantId) || participantQueue.some((entry) => entry.id === id)) return;
      const deferredBattle = cloneBattleState(battle);
      deferredBattle.deferredCoopResult = {
        id,
        playerId: participantId,
        sourcePlayerId: resultPlayerId,
      };
      deferredBattle.coopResultTurnPlayerId = participantId;
      deferredBattle.playerId = participantId;
      deferredBattle.result = "win";
      deferredBattle.animating = false;
      deferredBattle.roundResolved = true;
      deferredBattle.waitingResume = false;
      deferredBattle.needsReplacement = false;
      deferredBattle.entryTransition = null;
      deferredBattle.visualEvent = null;
      deferredBattle.lastVisualEvent = null;
      if (deferredBattle.lineageExtraction?.entries) {
        const ownEntry = extraction?.entries?.[participantId]
          ? safeJsonClone(extraction.entries[participantId])
          : null;
        deferredBattle.lineageExtraction.entries = ownEntry ? { [participantId]: ownEntry } : {};
      }
      participantQueue.push({
        id,
        playerId: participantId,
        createdAt: Date.now(),
        battle: deferredBattle,
      });
      battle.coopDeferredResultQueuedPlayerIds.push(participantId);
      queued.push(participant);
    });
    if (queued.length) {
      battle.log.push(`${queued.map((entry) => entry.name).join("、")} 的提取與戰鬥結算已保留，輪到各自的大富翁回合才會開啟。`);
    }
    return queued;
  }

  function coopBattleRewardPayloadForPlayer(player, battle, baseRewards, sharedNumericRewards) {
    const runtime = coopBattleRuntimeFor(player, battle, false);
    const rewardBattle = safeJsonClone(battle);
    rewardBattle.resolvedRewards = null;
    if (runtime) {
      rewardBattle.activeCrewIndex = Math.max(0, Number(runtime.activeCrewIndex ?? player.activeCrewIndex ?? battle.activeCrewIndex ?? 0));
    }
    const payload = cloneBattleRewardPayload(independentSharedEnemyIslandRewards(rewardBattle, baseRewards));
    if (sharedNumericRewards) {
      payload.coins = Math.max(0, Math.round(Number(sharedNumericRewards.coins || 0)));
      payload.bounty = Math.max(0, Math.round(Number(sharedNumericRewards.bounty || 0)));
      payload.exp = Math.max(0, Math.round(Number(sharedNumericRewards.exp || 0)));
    }
    payload.coins += goldRingsBattleCoinBonus(player, rewardBattle, Number(baseRewards?.coins || 0));
    payload.itemText = battleRewardItemText(payload);
    return payload;
  }

  function coopBattleResultViewPlayer(battle) {
    if (!isCoopBattle(battle)) return null;
    if (battle?.result === "win") return ensureCoopBattleResultTurnPlayer(battle);
    return battleCommandPlayer(battle);
  }

  function coopBattleRewardPayloadForView(player, battle) {
    if (!player || !isCoopBattle(battle) || battle.result !== "win") return null;
    ensureCoopBattleRewardPreview(battle, player);
    const payloads = battle.coopRewardPayloads && typeof battle.coopRewardPayloads === "object" ? battle.coopRewardPayloads : {};
    return payloads[String(player.id || "")] ? safeJsonClone(payloads[String(player.id || "")]) : null;
  }

  function ensureCoopBattleRewardPreview(battle, fallbackPlayer = null) {
    if (!isCoopBattle(battle) || battle.result !== "win") return null;
    const existingPayloads = battle.coopRewardPayloads && typeof battle.coopRewardPayloads === "object" ? battle.coopRewardPayloads : null;
    const existingDetails = Array.isArray(battle.coopRewardDetails) ? battle.coopRewardDetails : [];
    if (existingPayloads && existingDetails.length) {
      return {
        recipients: coopBattleRewardRecipients(battle, fallbackPlayer),
        payloads: existingPayloads,
        details: existingDetails,
      };
    }

    const recipients = coopBattleRewardRecipients(battle, fallbackPlayer);
    if (!recipients.length) return null;
    const baseRewards = getBattleRewards(battle);
    const rewardOwner = recipients.find((entry) => String(entry?.id || "") === String(battle.playerId || ""))
      || fallbackPlayer
      || battlePlayer(null, battle)
      || recipients[0];
    const sharedNumericRewards = applyBattleRewardBonuses(rewardOwner, safeJsonClone(baseRewards), battle, { silent: true, skipGoldRings: true });
    const placeName = battleRewardPlaceName(battle);
    const payloads = {};
    const details = [];
    recipients.forEach((entry) => {
      const payload = coopBattleRewardPayloadForPlayer(entry, battle, baseRewards, sharedNumericRewards);
      payloads[String(entry.id)] = payload;
      details.push(battleRewardDetailForPlayer(entry, payload, battle, placeName));
    });
    battle.coopRewardRecipientIds = recipients.map((entry) => String(entry.id));
    battle.coopRewardPayloads = safeJsonClone(payloads);
    battle.coopRewardDetails = safeJsonClone(details);
    battle.rewards = safeJsonClone(payloads[String(rewardOwner?.id || "")] || payloads[String(recipients[0]?.id || "")] || baseRewards);
    return { recipients, payloads: battle.coopRewardPayloads, details: battle.coopRewardDetails };
  }

  function grantBattleRewardDropsToPlayer(player, rewards, sourceLabel = "") {
    if (!player || !rewards) return [];
    const sourceText = sourceLabel ? `（${sourceLabel}）` : "";
    const granted = [];
    if (rewards.item) {
      const rewardItem = grantFormalItemToPlayer(player, rewards.item, 1, { reveal: true });
      if (rewardItem) {
        granted.push(rewardItem.name);
        addLog(`${player.name}${sourceText} 獲得道具：${rewardItem.name}。`);
        recordMissionEvent(player, { type: "obtain_item", itemId: rewardItem.id, itemName: rewardItem.name, category: normalizeGameItemCategory(rewardItem.category) });
      }
    }
    if (Array.isArray(rewards.shipRewards)) {
      rewards.shipRewards.forEach((entry) => {
        if (!entry?.id) return;
        const quantity = Math.max(1, Math.round(Number(entry.quantity || 1)));
        const shipRewardItem = grantFormalItemToPlayer(player, entry.id, quantity, { reveal: true });
        if (shipRewardItem) {
          granted.push(`${shipRewardItem.name} x${quantity}`);
          addLog(`${player.name}${sourceText} 獲得船隻獎賞：${shipRewardItem.name} x${quantity}。`);
          recordMissionEvent(player, { type: "obtain_item", itemId: shipRewardItem.id, itemName: shipRewardItem.name, category: normalizeGameItemCategory(shipRewardItem.category) });
        }
      });
    }
    if (rewards.itemDrop?.id) {
      const droppedItem = gameItemDef(rewards.itemDrop.id);
      if (droppedItem && normalizeGameItemCategory(droppedItem.category) !== "held") {
        addInventoryItem(player, droppedItem.id, 1);
        if (droppedItem.important) queueImportantItemReveal(droppedItem, 1);
        granted.push(droppedItem.name);
        addLog(`${player.name}${sourceText} 獲得${ITEM_CATEGORY_LABELS[normalizeGameItemCategory(droppedItem.category)] || "道具"}：${droppedItem.name}。`);
        recordMissionEvent(player, { type: "obtain_item", itemId: droppedItem.id, itemName: droppedItem.name, category: normalizeGameItemCategory(droppedItem.category) });
      }
    }
    if (rewards.battleCarryDrop) {
      const carryDrop = normalizeBattleCarryItem(rewards.battleCarryDrop);
      const addedCarry = carryDrop ? addBattleCarryItemToBackpack(player, carryDrop) : null;
      if (addedCarry) {
        const carryName = battleCarryLootLabel(addedCarry);
        granted.push(carryName);
        addLog(`${player.name}${sourceText} 獲得角色攜帶物：${carryName}，已放入背包（未裝備 ${countBattleCarryItemsInBackpack(player, addedCarry)} 個）。`);
        recordMissionEvent(player, { type: "obtain_item", itemId: addedCarry.id, itemName: battleCarryItemName(addedCarry), category: "held" });
      }
    }
    return granted;
  }

  function grantBattleWinRewardsToPlayer(player, battle, baseRewards, options = {}) {
    if (!player || !battle || !baseRewards) return null;
    const runtime = isCoopBattle(battle) ? coopBattleRuntimeFor(player, battle, false) : null;
    const rewardBattle = safeJsonClone(battle);
    if (runtime) {
      rewardBattle.activeCrewIndex = Math.max(0, Number(runtime.activeCrewIndex ?? player.activeCrewIndex ?? battle.activeCrewIndex ?? 0));
    }
    const rewardPayload = options.precomputedRewards
      ? cloneBattleRewardPayload(options.precomputedRewards)
      : safeJsonClone(options.independentDrops ? independentSharedEnemyIslandRewards(rewardBattle, baseRewards) : baseRewards);
    if (options.fixedNumericRewards) {
      rewardPayload.coins = Math.max(0, Math.round(Number(options.fixedNumericRewards.coins || 0)));
      rewardPayload.bounty = Math.max(0, Math.round(Number(options.fixedNumericRewards.bounty || 0)));
      rewardPayload.exp = Math.max(0, Math.round(Number(options.fixedNumericRewards.exp || 0)));
    }
    const rewards = options.skipRewardBonuses
      ? rewardPayload
      : applyBattleRewardBonuses(player, rewardPayload, rewardBattle);
    recordDefeatedEnemy(player, battle, options.placeName || "");
    player.coins += rewards.coins || 0;
    rewards.bounty = addBounty(player, rewards.bounty || 0);
    const grantedItems = grantBattleRewardDropsToPlayer(player, rewards, options.sourceLabel || "");
    rewards.grantedItems = grantedItems;
    rewards.itemText = battleRewardItemText(rewards);
    grantExpToLivingCrew(
      player,
      Math.max(0, Number(rewardBattle.activeCrewIndex ?? player.activeCrewIndex ?? 0)),
      rewards.exp || 0,
      options.expLabel || "",
    );
    return rewards;
  }

  function independentSharedEnemyIslandRewards(battle, fallbackRewards) {
    const rewardBattle = safeJsonClone(battle || {});
    rewardBattle.resolvedRewards = null;
    return getBattleRewards(rewardBattle) || fallbackRewards || {};
  }

  function grantSharedEnemyIslandClearRewards(winner, battle, baseRewards, placeName, serviceKind = "") {
    const island = getIslandById(battle?.islandId);
    if (!isSharedClearEligibleEnemyIslandBattle(battle, island)) return [];
    const participants = sharedEnemyIslandClearParticipants(winner, battle);
    if (!participants.length) return [];
    const defeatedTier = legacyTier(battle.enemyTier || battle.enemyCombatant?.tier || "T5");
    participants.forEach((entry) => {
      const pending = entry.pendingBattle;
      const rewards = applyBattleRewardBonuses(
        entry,
        safeJsonClone(independentSharedEnemyIslandRewards(pending || battle, baseRewards)),
        pending || battle,
      );
      recordDefeatedEnemy(entry, battle, placeName);
      entry.coins += rewards.coins || 0;
      rewards.bounty = addBounty(entry, rewards.bounty || 0);
      grantBattleRewardDropsToPlayer(entry, rewards, "協力清島");
      grantExpToLivingCrew(
        entry,
        Math.max(0, Number(pending?.activeCrewIndex ?? entry.activeCrewIndex ?? 0)),
        rewards.exp || 0,
        "協力清島",
      );
      recordMissionEvent(entry, { type: "battle_win", tier: defeatedTier, islandKind: "enemy" });
      recordMissionEvent(entry, { type: "defeat_tier", tier: defeatedTier });
      recordMissionEvent(entry, { type: "enemy_island_win", tier: defeatedTier, islandKind: "enemy" });
      if (battleEnemyIsDevilFruitUser(battle)) recordMissionEvent(entry, { type: "defeat_devil_fruit", tier: defeatedTier });
      applyShipBattleWinRecovery(entry, pending || battle);
      entry.pendingBattle = null;
      addLog(`${entry.name} 先前參與了 ${placeName} 的戰鬥，也取得協力清島獎勵：${rewardLineForSharedEnemyClear(rewards)}。`);
      if (serviceKind) {
        addLog(`${entry.name} 下次輪到時若仍停在 ${placeName}，可直接進入臨時${serviceIslandLabel(serviceKind)}。`);
      }
    });
    return participants;
  }

  function judicialPhaseReward(phaseIndex) {
    const rewards = [
      { coins: 1950, bounty: 10000000, exp: 260 },
      { coins: 2700, bounty: 14000000, exp: 340 },
      { coins: 3750, bounty: 22000000, exp: 460 },
      { coins: 5100, bounty: 32000000, exp: 620 },
      { coins: 7200, bounty: 46000000, exp: 820 },
      { coins: 10800, bounty: 70000000, exp: 1100 },
    ];
    const index = Math.max(0, Math.min(rewards.length - 1, Number(phaseIndex) || 0));
    const reward = rewards[index] || rewards[0];
    const enemy = createJudicialRaidPhaseEnemy(index);
    return {
      ...reward,
      exp: Math.max(reward.exp, battleExpRewardForEnemy(enemy?.tier, enemy?.level, 1.15)),
    };
  }

  function randomJudicialPhaseBonus() {
    const index = randomInt(0, JUDICIAL_PHASE_BONUS_POOL.length - 1);
    return {
      ...JUDICIAL_PHASE_BONUS_POOL[index],
      index,
      segments: JUDICIAL_PHASE_BONUS_POOL.map((entry) => ({
        id: entry.id,
        label: entry.label,
        iconKey: entry.iconKey || entry.id,
      })),
    };
  }

  function cardBaseMaxHp(card) {
    return Math.max(1, Number(card?.baseStats?.hp || card?.maxHp || card?.hp || card?.currentHp || 1));
  }

  function cardMaxHpIncludingCarry(card) {
    const baseMaxHp = cardBaseMaxHp(card);
    const multiplier = battleCarryItemsForCard(card).reduce((value, item) => {
      const carryEffect = battleCarryItemEffect(item);
      if (carryEffect.kind === "postgame_lucci_black_flame") return value * Math.max(1, Number(carryEffect.maxHpMultiplier || 1.3));
      if (carryEffect.kind === "postgame_oars_giant_belt") return value * Math.max(1, Number(carryEffect.maxHpMultiplier || 1.5));
      return value;
    }, 1);
    return Math.max(1, Math.round(baseMaxHp * multiplier));
  }

  function bulletArsenalCarryMaxHpIsSealed(card, battle = state.battleState) {
    const mechanic = postgameBossMechanicFor(battle);
    if (!card || mechanic?.key !== "postgame_douglas_bullet") return false;
    const player = battlePlayer(null, battle);
    const index = (player?.crew || []).indexOf(card);
    if (index < 0) return false;
    const slot = postgameBulletSlotForCrew(battle, card, index);
    return slot?.itemId === BULLET_ARSENAL_ITEM_ID && !slot.destroyed;
  }

  function cardMaxHp(card) {
    return bulletArsenalCarryMaxHpIsSealed(card) ? cardBaseMaxHp(card) : cardMaxHpIncludingCarry(card);
  }

  function restoreCrewHpPercent(player, ratio) {
    let total = 0;
    if (player && Number(player.maxHp || 0) > 0 && Number(player.hp || 0) > 0) {
      const beforePlayerHp = Number(player.hp || 0);
      const heal = Math.max(1, Math.round(Number(player.maxHp || 1) * Number(ratio || 0)));
      player.hp = Math.min(Number(player.maxHp || beforePlayerHp), beforePlayerHp + heal);
      total += player.hp - beforePlayerHp;
    }
    (player?.crew || []).forEach((card) => {
      if ((card.currentHp || 0) <= 0) return;
      const maxHp = cardMaxHp(card);
      const heal = Math.max(1, Math.round(maxHp * ratio));
      const before = Number(card.currentHp || maxHp);
      card.currentHp = Math.min(maxHp, before + heal);
      total += card.currentHp - before;
    });
    return total;
  }

  function restoreCrewPpPercent(player, ratio) {
    let total = 0;
    (player?.crew || []).forEach((card) => {
      (card.moveSet || []).forEach((moveEntry) => {
        const cap = Math.max(0, Number(moveEntry.pp || 0));
        if (cap <= 0) return;
        const before = Math.max(0, Number(moveEntry.currentPP ?? cap));
        const restore = Math.max(1, Math.round(cap * ratio));
        moveEntry.currentPP = Math.min(cap, before + restore);
        total += moveEntry.currentPP - before;
      });
    });
    return total;
  }

  function reviveOneCrewMember(player, ratio = 0.35) {
    const target = (player?.crew || []).find((card) => (card.currentHp || 0) <= 0);
    if (!target) return null;
    const maxHp = cardMaxHp(target);
    target.currentHp = Math.max(1, Math.round(maxHp * ratio));
    (target.moveSet || []).forEach((moveEntry) => {
      const cap = Math.max(0, Number(moveEntry.pp || 0));
      if (cap <= 0) return;
      moveEntry.currentPP = Math.max(moveEntry.currentPP || 0, Math.ceil(cap * 0.3));
    });
    return target;
  }

  function applyJudicialPhaseBonus(player, bonus) {
    if (!player || !bonus) return bonus;
    if (bonus.id === "heal") {
      bonus.appliedText = `全隊回復 ${restoreCrewHpPercent(player, 0.45)} HP`;
      recalcPlayerDerivedStats(player);
      return bonus;
    }
    if (bonus.id === "pp") {
      bonus.appliedText = `全隊回復 ${restoreCrewPpPercent(player, 0.5)} PP`;
      return bonus;
    }
    if (bonus.id === "revive") {
      const revived = reviveOneCrewMember(player, 0.35);
      if (revived) {
        bonus.appliedText = `${revived.name} 復活並回復 35% HP`;
      } else {
        bonus.appliedText = `無瀕死夥伴，改為全隊回復 ${restoreCrewHpPercent(player, 0.3)} HP`;
      }
      recalcPlayerDerivedStats(player);
      return bonus;
    }
    const stageBoosts = {
      attack: { atk: 2, spd: 1 },
      defense: { def: 2 },
      speed: { spd: 2, accuracy: 1 },
      burst: { atk: 1, def: 1, spd: 1 },
    };
    player.pendingJudicialRaidBoost = {
      ...bonus,
      stageBoost: stageBoosts[bonus.id] || null,
      shieldRatio: bonus.id === "shield" ? 0.55 : bonus.id === "defense" ? 0.25 : bonus.id === "burst" ? 0.2 : 0,
    };
    bonus.appliedText = "下一戰開場發動";
    return bonus;
  }

  function applyPendingJudicialRaidBoost(player, battle) {
    const boost = player?.pendingJudicialRaidBoost;
    if (!boost || !battle) return;
    battle.pendingJudicialOpeningBoost = {
      ...boost,
      stageBoost: boost.stageBoost ? { ...boost.stageBoost } : null,
    };
    delete player.pendingJudicialRaidBoost;
  }

  function applyJudicialOpeningBoost(battle) {
    if (!battle?.isJudicialRaid || battle.judicialOpeningBoostApplied) return;
    const boost = battle.pendingJudicialOpeningBoost;
    if (!boost || Number(battle.roundIndex || 0) !== 1) return;
    if (boost.stageBoost) applyStageSet(battle.playerStages, boost.stageBoost, 0);
    if (boost.shieldRatio) battle.playerRoundEffects.shieldRatio = Math.max(battle.playerRoundEffects.shieldRatio || 0, boost.shieldRatio);
    battle.judicialOpeningBoost = boost;
    battle.judicialOpeningBoostApplied = true;
    battle.pendingJudicialOpeningBoost = null;
    battle.log.push(`突破補給「${boost.label}」發動：${boost.description}`);
  }

  function grantJudicialPhaseReward(player, battle, phaseIndex, defeatedKey, defeatedName) {
    const raid = ensureJudicialRaidState();
    const rewardKey = `${defeatedKey || phaseIndex}:${player.id}`;
    if (raid.phaseRewardClaimedKeys.includes(rewardKey)) return null;
    const reward = judicialPhaseReward(phaseIndex);
    const bounty = addBounty(player, reward.bounty);
    player.coins += reward.coins;
    grantExpToLivingCrew(player, battle.activeCrewIndex, reward.exp, `擊敗 ${defeatedName}`);
    const bonus = applyJudicialPhaseBonus(player, randomJudicialPhaseBonus());
    raid.phaseRewardClaimedKeys.push(rewardKey);
    const payload = { ...reward, bounty, bonus };
    addLog(`${player.name} 擊敗 ${defeatedName}，獲得 ${reward.coins} 貝里、${formatCoin(bounty)} 賞金、${reward.exp} EXP，突破補給：${bonus.label}。`);
    recordMissionEvent(player, { type: "judicial_phase", phase: Number(phaseIndex || 0) + 1 });
    return payload;
  }

  function grantJudicialRaidRewards() {
    const raid = ensureJudicialRaidState();
    Object.values(raid.participants || {}).forEach((entry) => {
      if (!entry?.playerId || raid.rewardClaimedBy.includes(entry.playerId)) return;
      const player = state.gameState.players.find((item) => item.id === entry.playerId);
      if (!player) return;
      const score = (entry.damageDone || 0) + (entry.damageTaken || 0) * 0.4 + (entry.healingDone || 0) * 0.8 + (entry.turnsActed || 0) * 20;
      const multiplier = judicialRaidParticipationMultiplier(score);
      if (multiplier <= 0) return;
      const coins = Math.round(JUDICIAL_RAID_BASE_REWARD.coins * multiplier);
      const bounty = bountyGain(JUDICIAL_RAID_BASE_REWARD.bounty * multiplier);
      const exp = Math.round(JUDICIAL_RAID_BASE_REWARD.exp * multiplier);
      player.coins += coins;
      player.bounty += bounty;
      const clearItem = gameItemDef(JUDICIAL_RAID_BASE_REWARD.item);
      if (clearItem) {
        grantFormalItemToPlayer(player, clearItem.id, 1, { reveal: true });
        grantCosmeticFrameToPlayer(player, "goldenDenDen");
        addLog(`${player.name} 獲得司法島通關寶箱：${clearItem.name}。`);
      }
      grantExpToLivingCrew(player, Math.max(0, Number(player.activeCrewIndex || 0)), exp, "司法島通關");
      raid.rewardClaimedBy.push(entry.playerId);
      addLog(`${player.name} 司法島貢獻 ${Math.round(score)}，獲得 ${coins} 貝里、${formatCoin(bounty)} 賞金、${exp} EXP。`);
      recordMissionEvent(player, { type: "judicial_clear" });
    });
  }

  function promptJudicialRaidNextSwitch(battle, player, defeatedName, nextPhaseIndex, nextEnemy) {
    battle.result = "judicial-switch";
    battle.roundResolved = true;
    battle.waitingResume = true;
    battle.animating = false;
    battle.visualEvent = null;
    battle.judicialSwitchPrompt = {
      nextPhaseIndex,
      nextEnemyName: nextEnemy?.name || "下一名敵人",
      phaseTotal: JUDICIAL_RAID_PHASES.length,
      defeatedName,
    };
    battle.log.push(`${defeatedName} 已被擊敗。下一戰開始前可以更換上場角色。`);
    addJudicialRaidLog(`${player.name} 擊敗 ${defeatedName}，下一戰開始前可以更換上場角色。`);
    notifyBattleWindow();
    renderAll();
  }

  async function startJudicialRaidNextPhaseAfterSwitch(nextIndex) {
    const battle = state.battleState;
    if (!battle?.isJudicialRaid || battle.result !== "judicial-switch" || !battle.judicialSwitchPrompt) return false;
    const player = battlePlayer(null, battle);
    if (!player) return false;
    if (warnBoardLanTurnLocked(player)) return false;
    const prompt = battle.judicialSwitchPrompt;
    const currentIndex = Math.max(0, Number(battle.activeCrewIndex ?? player.activeCrewIndex ?? 0));
    const parsedIndex = Number(nextIndex);
    const requestedIndex = Number.isInteger(parsedIndex) ? parsedIndex : currentIndex;
    const targetCard = player.crew?.[requestedIndex];
    if (!targetCard || Number(targetCard.currentHp || 0) <= 0) return false;
    const fromCard = player.crew?.[currentIndex];
    syncActivePlayerStatusBag(player, battle);
    battle.activeCrewIndex = requestedIndex;
    player.activeCrewIndex = requestedIndex;
    syncActivePlayerStatusBag(player, battle);
    const nextPhaseIndex = Math.max(0, Math.min(JUDICIAL_RAID_PHASES.length - 1, Number(prompt.nextPhaseIndex || 0)));
    const raid = ensureJudicialRaidState();
    initializeJudicialRaidPhase(raid, nextPhaseIndex);
    if (nextPhaseIndex === 1) recordMainMissionEvent(player, { type: "judicial_intermission_ready" });
    raid.currentActorPlayerId = "";
    const preserveCoopRescuePending = isCoopBattle(battle)
      && battle.result === "round-pause"
      && coopBattleParticipantAwaitingRescue(player, battle);
    if (!preserveCoopRescuePending) player.pendingBattle = null;
    addJudicialRaidLog(requestedIndex === currentIndex
      ? `${player.name} 維持 ${targetCard.name} 上場，下一次司法島行動將迎戰 ${prompt.nextEnemyName || "下一名敵人"}。`
      : `${player.name} 將 ${fromCard?.name || "目前角色"} 換成 ${targetCard.name}，下一次司法島行動將迎戰 ${prompt.nextEnemyName || "下一名敵人"}。`);
    finalizeBattleAndAdvanceTurn(player, () => {
      addJudicialRaidLog(`司法島討伐進入第 ${nextPhaseIndex + 1}/${JUDICIAL_RAID_PHASES.length} 戰，等待下一位玩家行動。`);
    });
    return true;
  }

  async function finishJudicialRaidBattle(battle) {
    const player = battlePlayer(null, battle);
    if (!player) return;
    if (battle._judicialSettlementDone) return;
    battle._judicialSettlementDone = true;
    let raid = ensureJudicialRaidState();
    const islandState = getIslandState(raid.islandId);
    player.activeCrewIndex = battle.activeCrewIndex;
    player.pendingBattle = null;
    recordJudicialRaidContribution(battle, player);

    if (battle.result === "win") {
      const defeatedKey = battle.raidEnemyKey || raid.enemyKey;
      const defeatedName = battle.enemyCombatant.name;
      raid.enemyCurrentHp = 0;
      raid.currentActorPlayerId = "";
      recordDefeatedEnemy(player, battle, "司法島討伐戰");
      if (defeatedKey && !raid.phaseClearedKeys.includes(defeatedKey)) raid.phaseClearedKeys.push(defeatedKey);
      const defeatedPhaseIndex = Math.max(0, JUDICIAL_RAID_PHASES.indexOf(defeatedKey));
      const phaseReward = grantJudicialPhaseReward(player, battle, defeatedPhaseIndex, defeatedKey, defeatedName);
      battle.raidPhaseReward = phaseReward;
      raid = ensureJudicialRaidState();
      const nextPhaseIndex = Math.max(Number(raid.phaseIndex || 0) + 1, defeatedPhaseIndex + 1);
      if (nextPhaseIndex < JUDICIAL_RAID_PHASES.length) {
        const nextEnemy = getJudicialRaidEnemyProfile(nextPhaseIndex);
        battle.visualEvent = {
          id: `judicial-phase-${Date.now()}-${Math.random().toString(36).slice(2)}`,
          type: "raid-phase-reward",
          defeatedName,
          nextEnemyName: nextEnemy?.name || "下一名敵人",
          phaseIndex: defeatedPhaseIndex,
          nextPhaseIndex,
          phaseTotal: JUDICIAL_RAID_PHASES.length,
          reward: phaseReward,
          bonus: phaseReward?.bonus || null,
          segments: JUDICIAL_PHASE_BONUS_POOL.map((entry) => ({ id: entry.id, label: entry.label, iconKey: entry.iconKey || entry.id })),
          duration: 11000,
        };
        notifyBattleWindow();
        await waitBattleWindowVisual(battle.visualEvent, 11000);
        promptJudicialRaidNextSwitch(battle, player, defeatedName, nextPhaseIndex, nextEnemy);
        return;
      }
      finalizeBattleAndAdvanceTurn(player, () => {
        raid.active = false;
        raid.cleared = true;
        raid.failed = false;
        raid.clearCount = Math.max(0, Number(raid.clearCount || 0)) + 1;
        raid.lastClearedAtRound = Math.max(1, Number(state.gameState.round || 1));
        if (islandState) {
          islandState.isDefeated = true;
          islandState.currentKind = "judicial";
          islandState.currentHp = 0;
        }
        addJudicialRaidLog(`司法島討伐戰第 ${raid.clearCount} 次通關！`);
        grantJudicialRaidRewards();
      });
      return;
    }

    if (battle.result === "lose") {
      raid.currentActorPlayerId = "";
      const participant = ensureJudicialRaidParticipant(player, raid);
      if (participant) {
        participant.defeated = true;
        participant.active = false;
      }
      const survivors = activeJudicialRaidParticipants(raid);
      finalizeBattleAndAdvanceTurn(player, () => {
        sendPlayerToImpelDown(player, "司法島討伐戰敗北");
        addJudicialRaidLog(`${player.name} 在司法島討伐戰敗北，退出本次討伐並被送進推進城。`);
        if (!survivors.length) {
          raid.active = false;
          raid.failed = true;
          raid.phaseIndex = 0;
          raid.enemyKey = "";
          raid.enemyCurrentHp = 0;
          raid.enemyMaxHp = 0;
          raid.currentActorPlayerId = "";
          raid.participants = {};
          raid.turnQueue = [];
          raid.pendingJoinPlayerIds = [];
          addJudicialRaidLog("司法島討伐戰全員敗北，進度重置。");
        }
      });
      return;
    }

    if (battle.result === "knockout" || battle.result === "round-pause" || !battle.result) {
      player.pendingBattle = cloneBattleState(battle);
      raid.currentActorPlayerId = "";
      finalizeBattleAndAdvanceTurn(player, () => {
        addJudicialRaidLog(`${player.name} 暫停司法島討伐，下一次可從共享 HP 繼續。`);
      });
      return;
    }

    finalizeBattleAndAdvanceTurn(player);
  }

  function reviveOneCrewAtOneHp(player) {
    const target = (player?.crew || []).find((card) => card && Number(card.currentHp || 0) <= 0);
    if (!target) return null;
    target.currentHp = 1;
    return target;
  }

  function crewAverageHpRatio(player) {
    const crew = (player?.crew || []).filter(Boolean);
    if (!crew.length) return 1;
    const totalRatio = crew.reduce((sum, card) => sum + (Math.max(0, Number(card.currentHp || 0)) / cardMaxHp(card)), 0);
    return totalRatio / crew.length;
  }

  function restoreRandomConsumedMovePP(card, amount = 1) {
    if (!card?.moveSet?.length) return null;
    const candidates = card.moveSet.filter((entry) => {
      const current = Math.max(0, Number(entry.currentPP ?? entry.pp ?? 0));
      const max = Math.max(0, Number(entry.pp || current));
      return current < max;
    });
    if (!candidates.length) return null;
    const entry = candidates[Math.floor(Math.random() * candidates.length)];
    const current = Math.max(0, Number(entry.currentPP ?? entry.pp ?? 0));
    const max = Math.max(0, Number(entry.pp || current));
    const restored = Math.min(Math.max(1, Math.round(Number(amount || 1))), max - current);
    entry.currentPP = current + restored;
    return { move: entry, restored };
  }

  function applyShipBattleWinRecovery(player, battle) {
    if (!player || battle?.result !== "win") return;
    const effects = getTeamEffects(player);
    let totalHealed = 0;
    if (Number(effects.battleWinTeamHeal || 0) > 0) {
      const healed = restoreCrewHpPercent(player, Number(effects.battleWinTeamHeal || 0));
      totalHealed += healed;
      if (healed > 0) addLog(`${player.name} 的船隻廚房整備完成，全隊回復 ${healed} HP。`);
    }
    if (Number(effects.battleWinLowestHeal || 0) > 0) {
      const target = lowestLivingCrewCard(player);
      const healed = target ? healBattleTarget(target, Number(effects.battleWinLowestHeal || 0)) : 0;
      totalHealed += healed;
      if (healed > 0) addLog(`${player.name} 的乾糧木桶補給 ${target.name}，回復 ${healed} HP。`);
    }
    if (Number(effects.battleWinLowHpExtraHeal || 0) > 0) {
      const threshold = Math.max(0.01, Number(effects.battleWinLowHpThreshold || 0.3));
      const target = lowestLivingCrewCard(player);
      const ratio = target ? Number(target.currentHp || 0) / cardMaxHp(target) : 1;
      if (target && ratio <= threshold) {
        const healed = healBattleTarget(target, Number(effects.battleWinLowHpExtraHeal || 0));
        totalHealed += healed;
        if (healed > 0) addLog(`${player.name} 的改良火爐替 ${target.name} 加餐，額外回復 ${healed} HP。`);
      }
    }
    if (Number(effects.battleWinTeamHealWhenAverageLow || 0) > 0 && crewAverageHpRatio(player) < Number(effects.battleWinTeamHealAverageThreshold || 0.5)) {
      const healed = restoreCrewHpPercent(player, Number(effects.battleWinTeamHealWhenAverageLow || 0));
      totalHealed += healed;
      if (healed > 0) addLog(`${player.name} 的廚房改造在苦戰後補給全隊，回復 ${healed} HP。`);
    }
    if (Number(effects.battleWinRestoreRandomPP || 0) > 0) {
      const activeCard = player.crew?.[Math.max(0, Number(battle.activeCrewIndex ?? player.activeCrewIndex ?? 0))];
      const restored = restoreRandomConsumedMovePP(activeCard, Number(effects.battleWinRestoreRandomPP || 1));
      if (restored) addLog(`${player.name} 的廚房改造替 ${activeCard.name} 補足 ${restored.move.name} PP +${restored.restored}。`);
    }
    if (effects.battleWinReviveOneHp) {
      const revived = reviveOneCrewAtOneHp(player);
      if (revived) addLog(`${player.name} 的夢幻廚房與醫療聯艙救回 ${revived.name}，以 1 HP 回到隊伍。`);
    }
    if (totalHealed > 0 || effects.battleWinReviveOneHp) recalcPlayerDerivedStats(player);
  }

  function finishArenaBattle(player, battle) {
    if (!player || !battle) return;
    const opponentName = battle.enemyCombatant?.name || "競技場對手";
    if (battle.result === "round-pause" || !battle.result) {
      player.activeCrewIndex = Math.max(0, Number(battle.activeCrewIndex ?? player.activeCrewIndex ?? 0));
      player.pendingBattle = cloneBattleState(battle);
      addLog(`${player.name} 與 ${opponentName} 的競技場挑戰暫停，下一回合繼續。`);
      finalizeBattleAndAdvanceTurn(player);
      return;
    }

    restoreArenaCrew(player, battle);
    player.pendingBattle = null;
    if (battle.result === "win") {
      const points = Math.max(0, Math.floor(Number(battle.arenaResearchPoints || arenaResearchPointsForTier(battle.enemyTier))));
      const lab = ensurePlayerResearchLabState(player);
      lab.researchPoints += points;
      addLog(`${player.name} 擊敗 Lv.${ARENA_OPPONENT_LEVEL}・滿修行・SSS ${opponentName}，獲得 ${points} 研究點數；血統因子抽取已結算，未獲得貝里、懸賞金或 EXP。`);
      recordMissionEvent(player, {
        type: "arena_win",
        islandKind: "arena",
        opponentId: battle.arenaOpponentCardId || "",
        tier: legacyTier(battle.enemyTier || battle.enemyCombatant?.tier || "T6"),
        researchPoints: points,
      });
    } else if (battle.result === "escape") {
      addLog(`${player.name} 退出了與 ${opponentName} 的競技場挑戰，入場前的 HP 與 PP 已恢復。`);
    } else {
      addLog(`${player.name} 挑戰 ${opponentName} 失敗，未送往推進城；入場前的 HP 與 PP 已恢復。`);
    }
    scheduleBoardLanStatePush("arena-battle-finish", 80, { force: true });
    finalizeBattleAndAdvanceTurn(player);
  }

  function postgameClueCollectionSummary(player) {
    const owned = POSTGAME_BOSS_DEFS.filter((entry) => inventoryItemCount(player, entry.clueItemId) > 0);
    return {
      unique: owned.length,
      total: POSTGAME_BOSS_DEFS.reduce((sum, entry) => sum + inventoryItemCount(player, entry.clueItemId), 0),
      missing: POSTGAME_BOSS_DEFS.filter((entry) => inventoryItemCount(player, entry.clueItemId) <= 0),
    };
  }

  function canActivateYorkTracking(player) {
    const world = normalizePostgameWorldState();
    return Boolean(
      player
      && world.unlocked
      && postgameClueCollectionSummary(player).unique === POSTGAME_BOSS_DEFS.length
    );
  }

  function canRevealYorkTrackingWorld(player) {
    const world = normalizePostgameWorldState();
    return Boolean(
      player
      && world.unlocked
      && !world.eggheadUnlocked
      && postgameClueCollectionSummary(player).unique === POSTGAME_BOSS_DEFS.length
      && normalizePlayerYorkDecoderState(player) > 0
    );
  }

  function announceYorkTrackingWorldReveal(player, options = {}) {
    if (!player) return false;
    const world = normalizePostgameWorldState();
    closeModal();
    renderAll();
    const event = emitBoardUiEvent("postgame-egghead-reveal", {
      player,
      title: "約克座標鎖定",
      subtitle: "移動蛋頭島與洛克斯終戰航路已顯現。",
      theme: "final",
      symbol: "終",
      duration: options.immediate ? 1600 : 7600,
      detail: {
        playerName: player.name,
        eggheadAnchorIslandId: world.eggheadAnchorIslandId,
      },
    }, { immediate: true, clearDelay: options.immediate ? 2200 : 15000 });
    if (!options.skipCinematic) {
      state.gameState.resolutionLock = true;
      handleBoardUiEvent(event);
    } else {
      showBoardUiHud(event.title, event.subtitle, { theme: "final", symbol: "終" });
    }
    return true;
  }

  function completeYorkTrackingActivation(player, options = {}) {
    if (!canRevealYorkTrackingWorld(player)) return false;
    const world = normalizePostgameWorldState();
    world.eggheadUnlocked = true;
    world.eggheadUnlockedByPlayerId = String(player.id || "");
    world.eggheadUnlockedByPlayerName = String(player.name || "");
    world.eggheadUnlockedAtRound = Math.max(1, Number(state.gameState.round || 1));
    world.eggheadUnlockedAt = Date.now();
    world.eggheadStoryPlayed = true;
    ensurePostgameWorldLayout();
    addLog(`${player.name} 將十三張約克線索牌完成解碼，移動蛋頭島與通往洛克斯的五格航路出現在世界地圖。`);
    if (options.deferCinematic) renderAll();
    else announceYorkTrackingWorldReveal(player, options);
    scheduleBoardLanStatePush("postgame-egghead-unlock", 80, { force: true });
    return true;
  }

  function completeYorkPuzzleDifficulty(player, difficultyKey, order, options = {}) {
    const difficulty = YORK_CLUE_PUZZLE_API?.DIFFICULTIES?.[String(difficultyKey || "")];
    if (!player || !difficulty) return { ok: false, reason: "invalid_difficulty" };
    if (!options.skipControl && (!canBoardLanControlCurrentPlayer(player) || String(currentPlayer()?.id || "") !== String(player.id || ""))) {
      return { ok: false, reason: "not_controller" };
    }
    if (!canActivateYorkTracking(player)) return { ok: false, reason: "not_eligible" };
    const currentTier = normalizePlayerYorkDecoderState(player);
    const isPractice = currentTier >= 3;
    const puzzleVariant = isPractice ? String(options.puzzleVariant || "").trim().slice(0, 160) : "";
    if (isPractice && !puzzleVariant) return { ok: false, reason: "practice_variant_required" };
    if (!isPractice && difficulty.targetTier <= currentTier) return { ok: false, reason: "already_completed" };
    const world = normalizePostgameWorldState();
    const puzzle = YORK_CLUE_PUZZLE_API.createPuzzle(world.layoutSeed, player.id, difficulty.key, puzzleVariant);
    if (!YORK_CLUE_PUZZLE_API.arraysEqual(order, puzzle.solution)) return { ok: false, reason: "wrong_order" };
    const clueCountBefore = postgameClueCollectionSummary(player).total;
    if (isPractice) {
      return {
        ok: true,
        practice: true,
        rewardGranted: false,
        firstReveal: false,
        tier: currentTier,
        itemId: YORK_DECODER_ITEM_IDS[currentTier - 1] || "",
        itemName: gameItemDef(YORK_DECODER_ITEM_IDS[currentTier - 1])?.name || "約克座標解碼器・三階",
        dropRate: yorkDecoderDropRate(currentTier),
        eggheadRevealed: world.eggheadUnlocked,
        clueCountBefore,
        clueCountAfter: postgameClueCollectionSummary(player).total,
      };
    }
    const upgrade = grantYorkDecoderTier(player, difficulty.targetTier, { source: options.source || "york_clue_puzzle" });
    if (!upgrade) return { ok: false, reason: "upgrade_failed" };
    const firstReveal = !world.eggheadUnlocked;
    if (firstReveal) completeYorkTrackingActivation(player, { deferCinematic: Boolean(options.deferWorldCinematic), skipCinematic: Boolean(options.skipWorldCinematic), immediate: Boolean(options.immediate) });
    addLog(`${player.name} 完成${difficulty.label}約克座標解碼，取得「${upgrade.itemDef.name}」；名刀『日蝕』最終掉落率為 ${Math.round(upgrade.dropRate * 100)}%。`);
    renderAll();
    scheduleBoardLanStatePush("postgame-york-decoder-upgrade", 80, { force: true });
    return {
      ok: true,
      firstReveal,
      tier: upgrade.tier,
      itemId: upgrade.itemId,
      itemName: upgrade.itemDef.name,
      dropRate: upgrade.dropRate,
      eggheadRevealed: normalizePostgameWorldState().eggheadUnlocked,
      clueCountBefore,
      clueCountAfter: postgameClueCollectionSummary(player).total,
    };
  }

  let yorkPuzzleOverlaySession = null;

  function closeYorkPuzzleOverlay(options = {}) {
    const session = yorkPuzzleOverlaySession;
    if (!session) return false;
    window.removeEventListener("message", session.messageHandler);
    session.overlay.remove();
    yorkPuzzleOverlaySession = null;
    if (session.pendingWorldReveal && options.afterSuccess) {
      announceYorkTrackingWorldReveal(session.player, { immediate: false, skipCinematic: false });
    } else {
      renderAll();
    }
    return true;
  }

  function openYorkPuzzleOverlay(player) {
    if (
      !player
      || !canActivateYorkTracking(player)
      || !YORK_CLUE_PUZZLE_API
      || !canBoardLanControlCurrentPlayer(player)
      || String(currentPlayer()?.id || "") !== String(player.id || "")
    ) return false;
    closeYorkPuzzleOverlay();
    closeModal();
    const world = normalizePostgameWorldState();
    const channel = window.crypto?.randomUUID?.() || `york-${Date.now()}-${Math.random().toString(36).slice(2)}`;
    const puzzleVariant = normalizePlayerYorkDecoderState(player) >= 3 ? channel : "";
    const params = new URLSearchParams({
      embed: "1",
      channel,
      layoutSeed: String(world.layoutSeed || state.gameState.seed || "layout"),
      playerId: String(player.id || "player"),
      tier: String(normalizePlayerYorkDecoderState(player)),
      eggheadUnlocked: world.eggheadUnlocked ? "1" : "0",
    });
    if (puzzleVariant) params.set("puzzleVariant", puzzleVariant);
    const overlay = document.createElement("section");
    overlay.id = "yorkPuzzleOverlay";
    overlay.setAttribute("aria-label", "約克十三張線索座標解碼");
    overlay.style.cssText = "position:fixed;inset:0;z-index:2147483000;background:#02080d;";
    const iframe = document.createElement("iframe");
    iframe.title = "約克十三張線索座標解碼";
    iframe.src = `${YORK_PUZZLE_PAGE}?${params}`;
    iframe.style.cssText = "display:block;width:100%;height:100%;border:0;background:#02080d;";
    iframe.setAttribute("allow", "fullscreen");
    overlay.appendChild(iframe);
    document.body.appendChild(overlay);

    const messageHandler = (event) => {
      if (event.origin !== window.location.origin || event.source !== iframe.contentWindow) return;
      const message = event.data || {};
      if (message.channel !== channel) return;
      if (message.type === "york-puzzle-close") {
        closeYorkPuzzleOverlay({ afterSuccess: Boolean(message.afterSuccess) });
        return;
      }
      if (message.type !== "york-puzzle-submit") return;
      const controlledPlayer = (state.gameState.players || []).find((entry) => String(entry?.id || "") === String(player.id || ""));
      const result = completeYorkPuzzleDifficulty(controlledPlayer, message.difficultyKey, message.order, {
        source: "york_clue_puzzle_human",
        deferWorldCinematic: true,
        puzzleVariant,
      });
      if (result.ok && result.firstReveal && yorkPuzzleOverlaySession) yorkPuzzleOverlaySession.pendingWorldReveal = true;
      iframe.contentWindow?.postMessage({ type: "york-puzzle-result", channel, ...result }, window.location.origin);
    };
    yorkPuzzleOverlaySession = { overlay, iframe, player, channel, puzzleVariant, messageHandler, pendingWorldReveal: false };
    window.addEventListener("message", messageHandler);
    iframe.addEventListener("load", () => iframe.focus(), { once: true });
    return true;
  }

  function canCpuAutoDecodeYork(player) {
    return Boolean(
      isCpuPlayer(player)
      && normalizePostgameWorldState().unlocked
      && postgameClueCollectionSummary(player).unique === POSTGAME_BOSS_DEFS.length
      && normalizePlayerYorkDecoderState(player) < 2
    );
  }

  function completeYorkCpuDecoder(player, options = {}) {
    if (!canCpuAutoDecodeYork(player)) return false;
    const upgrade = grantYorkDecoderTier(player, 2, { source: "york_clue_puzzle_cpu" });
    if (!upgrade) return false;
    const firstReveal = !normalizePostgameWorldState().eggheadUnlocked;
    if (firstReveal) completeYorkTrackingActivation(player, { skipCinematic: true, immediate: options.immediate !== false });
    addLog(`${player.name} 自動完成普通約克座標解碼，取得「${upgrade.itemDef.name}」；不會自動升到三階。`);
    renderAll();
    scheduleBoardLanStatePush("postgame-york-decoder-cpu", 80, { force: true });
    return true;
  }

  function activateYorkTrackingFromBackpack(player) {
    const world = normalizePostgameWorldState();
    const collection = postgameClueCollectionSummary(player);
    if (collection.unique < POSTGAME_BOSS_DEFS.length) {
      addLog(`${player.name} 只有 ${collection.unique}/13 種約克線索，尚缺 ${collection.missing.length} 種。`);
      openBackpackModal({ pocketId: "key" });
      return false;
    }
    const tier = normalizePlayerYorkDecoderState(player);
    if (tier >= 3) {
      addLog(`${player.name} 以三階約克座標解碼器開啟新題目練習；完成後不會獲得道具、階級、掉落率或其他加成。`);
    }
    if (isCpuPlayer(player)) return completeYorkCpuDecoder(player);
    return openYorkPuzzleOverlay(player);
  }

  function grantPostgameBossClue(player, battle) {
    const bossDef = postgameBossDef(battle?.postgameBossKey || battle?.enemyCombatant?.key);
    const clueDef = gameItemDef(battle?.postgameClueItemId || bossDef?.clueItemId);
    if (!player || !bossDef || !clueDef) return null;
    addInventoryItem(player, clueDef.id, 1);
    recordMissionEvent(player, {
      type: "obtain_item",
      itemId: clueDef.id,
      itemName: clueDef.name,
      category: normalizeGameItemCategory(clueDef.category),
      amount: 1,
      source: "postgame_boss",
      bossKey: bossDef.key,
    }, 1);
    if (!isCpuPlayer(player) && canBoardLanControlCurrentPlayer(player)) queueImportantItemReveal(clueDef, 1);
    const result = {
      bossDef,
      clueDef,
      collection: postgameClueCollectionSummary(player),
    };
    if (isCpuPlayer(player) && result.collection.unique === POSTGAME_BOSS_DEFS.length) {
      result.cpuDecoded = completeYorkCpuDecoder(player, { immediate: true });
    }
    return result;
  }

  function grantPostgameBossRelicDrop(player, battle, options = {}) {
    const bossDef = postgameBossDef(battle?.postgameBossKey || battle?.enemyCombatant?.key);
    const relicItemId = bossDef ? POSTGAME_BOSS_RELIC_ITEM_BY_KEY[bossDef.key] : "";
    const relicDef = gameItemDef(relicItemId);
    if (!player || !battle || !bossDef || !relicDef) return null;
    battle.postgameRelicRewardedPlayerIds = Array.isArray(battle.postgameRelicRewardedPlayerIds)
      ? battle.postgameRelicRewardedPlayerIds.map(String)
      : [];
    const playerId = String(player.id || player.userId || player.name || "");
    if (!playerId || battle.postgameRelicRewardedPlayerIds.includes(playerId)) return null;
    battle.postgameRelicRewardedPlayerIds.push(playerId);
    const rand = typeof options.rand === "function" ? options.rand : Math.random;
    const roll = Math.max(0, Math.min(1, Number(rand())));
    const dropped = roll < POSTGAME_BOSS_RELIC_DROP_RATE;
    if (dropped) {
      addBattleCarryItemToBackpack(player, relicItemId);
      recordMissionEvent(player, {
        type: "obtain_item",
        itemId: relicItemId,
        itemName: relicDef.name,
        category: "held",
        amount: 1,
        source: "postgame_boss",
        bossKey: bossDef.key,
      }, 1);
      if (!isCpuPlayer(player) && canBoardLanControlCurrentPlayer(player)) queueImportantItemReveal(relicDef, 1);
    }
    return {
      bossDef,
      relicDef,
      dropRate: POSTGAME_BOSS_RELIC_DROP_RATE,
      roll,
      dropped,
    };
  }

  function grantPostgameBossBonusRelicDrops(player, battle, options = {}) {
    const bossDef = postgameBossDef(battle?.postgameBossKey || battle?.enemyCombatant?.key);
    const itemIds = bossDef ? (POSTGAME_BOSS_BONUS_RELIC_ITEMS_BY_KEY[bossDef.key] || []) : [];
    if (!player || !battle || !bossDef || !itemIds.length) return [];
    battle.postgameBonusRelicRewardKeys = Array.isArray(battle.postgameBonusRelicRewardKeys)
      ? battle.postgameBonusRelicRewardKeys.map(String)
      : [];
    const playerId = String(player.id || player.userId || player.name || "");
    if (!playerId) return [];
    const rand = typeof options.rand === "function" ? options.rand : Math.random;
    return itemIds.map((itemId) => {
      const relicDef = gameItemDef(itemId);
      const rewardKey = `${playerId}:${itemId}`;
      if (!relicDef || battle.postgameBonusRelicRewardKeys.includes(rewardKey)) return null;
      battle.postgameBonusRelicRewardKeys.push(rewardKey);
      const roll = Math.max(0, Math.min(1, Number(rand())));
      const dropped = roll < POSTGAME_BOSS_RELIC_DROP_RATE;
      if (dropped) {
        addBattleCarryItemToBackpack(player, itemId);
        recordMissionEvent(player, {
          type: "obtain_item",
          itemId,
          itemName: relicDef.name,
          category: "held",
          amount: 1,
          source: "postgame_boss_bonus",
          bossKey: bossDef.key,
        }, 1);
        if (!isCpuPlayer(player) && canBoardLanControlCurrentPlayer(player)) queueImportantItemReveal(relicDef, 1);
      }
      return { bossDef, relicDef, dropRate: POSTGAME_BOSS_RELIC_DROP_RATE, roll, dropped };
    }).filter(Boolean);
  }

  function grantElbaphLokiRelicDrop(player, battle, options = {}) {
    const relicDef = gameItemDef("loki_ragnir");
    if (!player || !battle || !relicDef) return null;
    battle.elbaphLokiRelicRewardedPlayerIds = Array.isArray(battle.elbaphLokiRelicRewardedPlayerIds)
      ? battle.elbaphLokiRelicRewardedPlayerIds.map(String)
      : [];
    const playerId = String(player.id || player.userId || player.name || "");
    if (!playerId || battle.elbaphLokiRelicRewardedPlayerIds.includes(playerId)) return null;
    battle.elbaphLokiRelicRewardedPlayerIds.push(playerId);
    const rand = typeof options.rand === "function" ? options.rand : Math.random;
    const roll = Math.max(0, Math.min(1, Number(rand())));
    const dropped = roll < POSTGAME_BOSS_RELIC_DROP_RATE;
    if (dropped) {
      addBattleCarryItemToBackpack(player, relicDef.id);
      recordMissionEvent(player, {
        type: "obtain_item",
        itemId: relicDef.id,
        itemName: relicDef.name,
        category: "held",
        amount: 1,
        source: "elbaph_loki_trial",
        bossKey: "postgame_loki",
      }, 1);
      if (!isCpuPlayer(player) && canBoardLanControlCurrentPlayer(player)) queueImportantItemReveal(relicDef, 1);
    }
    return { relicDef, dropRate: POSTGAME_BOSS_RELIC_DROP_RATE, roll, dropped };
  }

  function grantRocksVictoryRewards(player, battle, options = {}) {
    if (!player || !battle) return null;
    battle.rocksRewardedPlayerIds = Array.isArray(battle.rocksRewardedPlayerIds)
      ? battle.rocksRewardedPlayerIds.map(String)
      : [];
    const playerId = String(player.id || player.userId || player.name || "");
    if (!playerId || battle.rocksRewardedPlayerIds.includes(playerId)) return null;
    battle.rocksRewardedPlayerIds.push(playerId);
    const frameWasOwned = ensurePlayerCosmeticFrameState(player).includes("rocksConqueror");
    const coreDef = gameItemDef(PERFECT_LINEAGE_CORE_ITEM_ID);
    addInventoryItem(player, PERFECT_LINEAGE_CORE_ITEM_ID, 1);
    const decoderTier = normalizePlayerYorkDecoderState(player);
    const eclipseRate = yorkDecoderDropRate(decoderTier);
    const rand = typeof options.rand === "function" ? options.rand : Math.random;
    const eclipseRoll = eclipseRate > 0 ? Math.max(0, Math.min(1, Number(rand()))) : null;
    const eclipseDropped = eclipseRate > 0 && eclipseRoll < eclipseRate;
    const eclipseDef = eclipseDropped ? gameItemDef(ROCKS_ECLIPSE_ITEM_ID) : null;
    if (eclipseDropped && eclipseDef) {
      addBattleCarryItemToBackpack(player, ROCKS_ECLIPSE_ITEM_ID);
      recordMissionEvent(player, {
        type: "obtain_item",
        itemId: ROCKS_ECLIPSE_ITEM_ID,
        itemName: eclipseDef.name,
        category: "held",
        amount: 1,
        source: "postgame_rocks",
      }, 1);
      if (!isCpuPlayer(player) && canBoardLanControlCurrentPlayer(player)) queueImportantItemReveal(eclipseDef, 1);
    }
    grantCosmeticFrameToPlayer(player, "rocksConqueror", { autoEquip: !frameWasOwned });
    recordMissionEvent(player, {
      type: "postgame_rocks_win",
      islandKind: "postgame_egghead",
      bossKey: POSTGAME_ROCKS_PROFILE.key,
      perfectLineageCore: 1,
      researchPoints: 25,
    });
    if (!isCpuPlayer(player) && canBoardLanControlCurrentPlayer(player) && coreDef) queueImportantItemReveal(coreDef, 1);
    return {
      coreDef,
      firstFrameUnlock: !frameWasOwned,
      researchPoints: postgameResearchPointsForBattle(battle),
      decoderTier,
      eclipseRate,
      eclipseRoll,
      eclipseDropped: Boolean(eclipseDropped && eclipseDef),
      eclipseDef,
    };
  }

  function finishDeferredCoopBattleResult(player, battle) {
    const deferred = battle?.deferredCoopResult;
    if (!player || !deferred || String(deferred.playerId || "") !== String(player.id || "")) return false;
    if (warnBoardLanTurnLocked(player) || !lineageExtractionResultPlayerReady(battle)) return false;
    const queue = normalizePendingCoopBattleResults(player);
    player.pendingCoopBattleResults = queue.filter((entry) => String(entry.id || "") !== String(deferred.id || ""));
    addLog(`${player.name} 已在自己的回合查看共鬥結算。`);
    state.gameState.turnStep = "擲骰前進";
    clearBattleTransientState();
    closeModal();
    renderAll();
    notifyBattleWindow();
    scheduleBoardLanStatePush("coop-deferred-result-complete", 60, { force: true });
    window.setTimeout(() => {
      if (state.battleState || String(currentPlayer()?.id || "") !== String(player.id || "")) return;
      if (!autoResumeBattleForCurrentPlayer()) {
        schedulePendingPostgameBossVoyageForCurrentPlayer();
        schedulePendingMoveLearn();
        scheduleTurnStartIslandServiceChoiceForCurrentPlayer();
      }
    }, 180);
    return true;
  }

  async function finishBattle() {
    const battle = state.battleState;
    if (!battle) return;
    if (battle.zorojuroEvolutionResolving) return;
    if (!canEndBattleTurn(battle)) return;
    if (battle.result === "win" && !lineageExtractionResultPlayerReady(battle)) {
      notifyBattleWindow();
      return;
    }
    const playerForTurnLock = isCoopBattle(battle) && battle.result === "win"
      ? coopBattleResultViewPlayer(battle)
      : isCoopBattle(battle)
        ? battleCommandPlayer(battle)
        : battlePlayer(null, battle);
    if (playerForTurnLock && warnBoardLanTurnLocked(playerForTurnLock)) return;
    if (battle.result === "win") {
      battle.zorojuroEvolutionResolving = true;
      try {
        await resolveZorojuroVictoryEvolutions(playerForTurnLock, battle);
      } finally {
        if (state.battleState === battle) battle.zorojuroEvolutionResolving = false;
      }
    }
    if (battle.deferredCoopResult) {
      finishDeferredCoopBattleResult(playerForTurnLock, battle);
      return;
    }
    if (isCoopBattle(battle) && battle.result === "win") {
      queueDeferredCoopBattleResults(battle, playerForTurnLock);
    }
    if (battle.isJudicialRaid) {
      finishJudicialRaidBattle(battle);
      return;
    }
    const player = isCoopBattle(battle) && battle.result === "win"
      ? coopBattleResultViewPlayer(battle)
      : isCoopBattle(battle)
        ? battleCommandPlayer(battle)
        : battlePlayer(null, battle);
    if (battle.isArenaBattle || battle.islandKind === "arena") {
      finishArenaBattle(player, battle);
      return;
    }
    if (isCoopBattle(battle)) {
      coopBattleParticipants(battle).forEach((participant) => {
        const runtime = coopBattleRuntimeFor(participant, battle, false);
        if (!runtime) return;
        participant.activeCrewIndex = Math.max(0, Number(runtime.activeCrewIndex ?? participant.activeCrewIndex ?? 0));
        recalcPlayerDerivedStats(participant);
      });
      const ownerRuntime = coopBattleRuntimeFor(player, battle, false);
      if (ownerRuntime) applyCoopBattleRuntimeSnapshot(player, battle, ownerRuntime);
      if (battle.result === "round-pause") {
        const saved = persistCoopBattlePendingForParticipants(battle);
        battle.log.push(`共鬥戰鬥暫停，已替 ${saved.map((entry) => entry.name).join("、") || "參戰者"} 保留續戰進度。`);
      } else if (battle.result) {
        clearActiveCoopPendingBattles(battle);
      }
    }
    const isSeaEncounter = battle.isSeaEncounter || battle.islandKind === "sea-encounter";
    const island = isSeaEncounter ? null : getIslandById(battle.islandId);
    const islandState = isSeaEncounter ? null : getIslandState(battle.islandId);
    const battlePlaceName = isSeaEncounter ? "海格遭遇戰" : island.name;
    player.activeCrewIndex = battle.activeCrewIndex;
    recalcPlayerDerivedStats(player);
    if (islandState && battle.result !== "lose" && !isFinalGateBattle(battle) && !isElbaphGodKnightBattle(battle) && !isElbaphLokiTrialBattle(battle) && !isFinalGateBlackTurnBattle(battle)) islandState.currentHp = Math.max(0, battle.enemyCombatant.currentHp);
    player.pendingBattle = null;
    let immediateServiceKind = "";
    if (isFinalGateBattle(battle) && battle.finalGateResolving) return;

    if (battle.isImpelDown || battle.islandKind === "impel_down") {
      finishImpelDownBattle(player, battle, islandState);
      return;
    }
    if (battle.isMarineford || battle.islandKind === "marineford") {
      finishMarinefordBattle(player, battle);
      return;
    }

    if (battle.result === "win") {
      if (isFinalGateBlackTurnBattle(battle)) {
        handleFinalGateBlackTurnBattleWin(player, battle);
        return;
      }
      const baseRewards = getBattleRewards(battle);
      const coopRewardPreview = isCoopBattle(battle) ? ensureCoopBattleRewardPreview(battle, player) : null;
      const rewardRecipients = isCoopBattle(battle)
        ? (coopRewardPreview?.recipients?.length ? coopRewardPreview.recipients : coopBattleRewardRecipients(battle, player))
        : [player];
      if (!rewardRecipients.some((entry) => String(entry?.id || "") === String(player.id || ""))) rewardRecipients.unshift(player);
      const coopRewardPayloads = isCoopBattle(battle) && battle.coopRewardPayloads && typeof battle.coopRewardPayloads === "object"
        ? battle.coopRewardPayloads
        : {};
      const sharedNumericRewards = isCoopBattle(battle) && !Object.keys(coopRewardPayloads).length
        ? applyBattleRewardBonuses(player, safeJsonClone(baseRewards), battle, { skipGoldRings: true })
        : null;
      let rewards = null;
      const coopRewardDetails = [];
      rewardRecipients.forEach((entry) => {
        const precomputedRewards = isCoopBattle(battle) ? coopRewardPayloads[String(entry.id)] : null;
        const entryRewards = grantBattleWinRewardsToPlayer(entry, battle, baseRewards, {
          precomputedRewards,
          independentDrops: isCoopBattle(battle) && !precomputedRewards,
          fixedNumericRewards: isCoopBattle(battle) && !precomputedRewards ? sharedNumericRewards : null,
          skipRewardBonuses: isCoopBattle(battle),
          placeName: battlePlaceName,
          sourceLabel: isCoopBattle(battle) && String(entry.id) !== String(player.id) ? "共鬥勝利" : "",
          expLabel: isCoopBattle(battle) && String(entry.id) !== String(player.id) ? "共鬥勝利" : "",
        });
        if (isCoopBattle(battle) && entryRewards) {
          coopRewardDetails.push(battleRewardDetailForPlayer(entry, entryRewards, battle, battlePlaceName));
        }
        if (String(entry.id) === String(player.id)) rewards = entryRewards;
      });
      rewards ||= safeJsonClone(baseRewards);
      if (isCoopBattle(battle) && rewardRecipients.length > 1) {
        battle.rewards = safeJsonClone(rewards);
        battle.coopRewardDetails = safeJsonClone(coopRewardDetails.length ? coopRewardDetails : battle.coopRewardDetails || []);
        addLog(`共鬥勝利：${rewardRecipients.map((entry) => entry.name).join("、")} 都獲得貝里、賞金與 EXP，掉落物各自結算。`);
      }
      const defeatedTier = legacyTier(battle.enemyTier || battle.enemyCombatant?.tier || "T5");
      const noCrewFainted = (player.crew || []).every((card) => Number(card?.currentHp || 0) > 0);
      recordMissionEvent(player, { type: "battle_win", tier: defeatedTier, islandKind: battle.islandKind || (isSeaEncounter ? "sea-encounter" : island?.kind || "") });
      recordMissionEvent(player, { type: "defeat_tier", tier: defeatedTier });
      if (battleEnemyIsDevilFruitUser(battle)) recordMissionEvent(player, { type: "defeat_devil_fruit", tier: defeatedTier });
      if (battleHadHeldTrigger(battle)) recordMissionEvent(player, { type: "held_trigger", tier: defeatedTier });
      if (noCrewFainted) recordMissionEvent(player, { type: "no_ko_battle_win", tier: defeatedTier });
      applyShipBattleWinRecovery(player, battle);
      if (isSeaEncounter) {
        recordMissionEvent(player, { type: "sea_battle_win", tier: defeatedTier, zone: battle.seaTile?.zone || "" });
      } else if (battle.islandKind === "yonko" || island?.kind === "yonko") {
        recordMissionEvent(player, { type: "yonko_win", tier: defeatedTier, islandKind: "yonko" });
      } else if (battle.islandKind === "enemy" || island?.kind === "enemy") {
        recordMissionEvent(player, { type: "enemy_island_win", tier: defeatedTier, islandKind: "enemy" });
      }
      if (isElbaphGodKnightBattle(battle)) {
        battle.isElbaphGodKnight = true;
        battle.elbaphStep = elbaphGodKnightBattleStep(battle);
        addLog(`${player.name} 擊退了 ${battle.enemyCombatant.name}。`);
        addLog(`${player.name} 的艾爾巴夫救援戰獎勵：${rewards.summary}。`);
        handleElbaphGodKnightBattleWin(player, battle);
        return;
      }
      if (isElbaphLokiTrialBattle(battle)) {
        const lokiRewardResults = rewardRecipients.map((entry) => ({
          player: entry,
          relic: grantElbaphLokiRelicDrop(entry, battle),
        }));
        addLog(`${rewardRecipients.map((entry) => entry.name).join("、")} 通過洛基的王子試煉；不獲得約克線索，血統因子抽取照常開放。`);
        lokiRewardResults.forEach(({ player: entry, relic }) => {
          if (relic?.dropped) addLog(`${entry.name} 的 10% 判定成功，取得「${relic.relicDef.name}」。`);
          else if (relic) addLog(`${entry.name} 的 10% 鐵雷 Ragnir 判定未掉落。`);
        });
        rewardRecipients.forEach((entry) => recordMissionEvent(entry, { type: "elbaph_loki_trial_win", tier: defeatedTier, islandKind: "elbaph_loki_trial", bossKey: "postgame_loki" }));
        finalizeBattleAndAdvanceTurn(player);
        return;
      }
      if (isSeaEncounter) {
        addLog(`${player.name} 擊退了海格遭遇敵人 ${battle.enemyCombatant.name}。`);
        addLog(`${player.name} 的遭遇戰獎勵：${rewards.summary}。`);
        finalizeBattleAndAdvanceTurn(player);
        return;
      }
      if (isFinalGateBattle(battle)) {
        if (battle.finalGateResolving) return;
        battle.finalGateResolving = true;
        const alreadyDefeated = player.finalGateDefeated || state.gameState.finalGateDefeatedBy?.[player.id];
        if (!alreadyDefeated) {
          player.finalGateDefeated = true;
          state.gameState.finalGateDefeatedBy = state.gameState.finalGateDefeatedBy && typeof state.gameState.finalGateDefeatedBy === "object" ? state.gameState.finalGateDefeatedBy : {};
          state.gameState.finalGateDefeatedBy[player.id] = true;
          if (islandState) {
            islandState.currentHp = islandState.maxHp || FINAL_GATE_ENEMY_PROFILE.maxHp;
            islandState.isDefeated = false;
            islandState.enemyProfile = null;
          }
          addLog(`${player.name} 擊退伊姆，通往最終之島的航路被打開。`);
          addLog(`${player.name} 的勝利獎勵：${rewards.summary}。`);
          grantCosmeticFrameToPlayer(player, "finalImu");
        }
        if (!player.finalGateAftermathSeen) {
          finalizeBattleAndAdvanceTurn(player, null, {
            advanceTurn: false,
            afterClear: () => startFinalGateAftermath(player, () => {
              closeModal();
              renderAll();
              endTurn({
                context: "battle",
                subtitle: "伊姆戰後劇情結束，準備切換到下一位玩家。",
              });
            }),
          });
        } else {
          finalizeBattleAndAdvanceTurn(player);
        }
        return;
      }
      if (battle.isRocksBattle || battle.islandKind === "postgame_egghead" || island?.kind === "postgame_egghead") {
        const rocksRewards = rewardRecipients
          .map((entry) => ({ player: entry, result: grantRocksVictoryRewards(entry, battle) }))
          .filter((entry) => entry.result);
        if (islandState) {
          islandState.enemyProfile = safeJsonClone(POSTGAME_ROCKS_PROFILE);
          islandState.maxHp = POSTGAME_ROCKS_PROFILE.maxHp;
          islandState.currentHp = islandState.maxHp;
          islandState.isDefeated = false;
          islandState.currentKind = "postgame_egghead";
          islandState.temporaryServiceKind = "";
          islandState.temporaryServiceStartedRound = 0;
          islandState.temporaryServiceExpiresAtRound = 0;
          islandState.bossKey = POSTGAME_ROCKS_PROFILE.key;
        }
        const extractionTimingText = isCoopBattle(battle) && rewardRecipients.length > 1
          ? "；血統因子提取與結算將依各自的大富翁回合處理"
          : "，並已完成血統因子抽取結算";
        addLog(`${rewardRecipients.map((entry) => entry.name).join("、")} 擊敗洛克斯；每位實際參戰者獲得完美血統核心 ×1、研究點數 25${extractionTimingText}。`);
        rocksRewards.forEach(({ player: entry, result }) => {
          if (result.firstFrameUnlock) addLog(`${entry.name} 首次討伐洛克斯，解鎖「神之谷霸王框」。`);
          if (result.eclipseDropped) addLog(`${entry.name} 的個人解碼器判定成功，取得「名刀『日蝕』」；此攜帶物可重複取得但不可交易。`);
        });
        addLog(`${island.name} 的終戰培養艙開始重建；參戰者必須先離島，之後重新登島才能再次挑戰。`);
        finalizeBattleAndAdvanceTurn(player);
        return;
      }
      if (battle.isPostgameBoss || battle.islandKind === "postgame_boss" || island?.kind === "postgame_boss") {
        const bossRewardResults = rewardRecipients.map((entry) => ({
          player: entry,
          clue: grantPostgameBossClue(entry, battle),
          relic: grantPostgameBossRelicDrop(entry, battle),
          bonusRelics: grantPostgameBossBonusRelicDrops(entry, battle),
        }));
        if (islandState) {
          const profile = postgameBossProfile(battle.postgameBossKey || battle.enemyCombatant?.key);
          islandState.enemyProfile = profile ? safeJsonClone(profile) : islandState.enemyProfile;
          islandState.maxHp = Math.max(1, Number(islandState.enemyProfile?.maxHp || islandState.maxHp || 1));
          islandState.currentHp = islandState.maxHp;
          islandState.isDefeated = false;
          islandState.currentKind = "postgame_boss";
          islandState.temporaryServiceKind = "";
          islandState.temporaryServiceStartedRound = 0;
          islandState.temporaryServiceExpiresAtRound = 0;
        }
        const bossName = battle.enemyCombatant?.name || postgameBossDef(battle.postgameBossKey)?.name || "無風帶 Boss";
        addLog(`${rewardRecipients.map((entry) => entry.name).join("、")} 擊敗 ${bossName}；每位實際參戰者都取得對應的約克線索，並各自進行 10% 專屬攜帶物判定。`);
        bossRewardResults.forEach(({ player: entry, clue, relic, bonusRelics }) => {
          if (clue) addLog(`${entry.name} 取得「${clue.clueDef.name}」；目前持有 ${clue.collection.unique}/13 種、合計 ${clue.collection.total} 張。`);
          if (relic?.dropped) addLog(`${entry.name} 的 10% 判定成功，取得「${relic.relicDef.name}」；此攜帶物可重複取得但不可交易。`);
          else if (relic) addLog(`${entry.name} 的 10% 專屬攜帶物判定未掉落。`);
          (bonusRelics || []).forEach((bonusRelic) => {
            if (bonusRelic.dropped) addLog(`${entry.name} 的 KING 額外 10% 判定成功，取得「${bonusRelic.relicDef.name}」；KING 的佩刀判定不受影響。`);
            else addLog(`${entry.name} 的 KING 額外 10%「${bonusRelic.relicDef.name}」判定未掉落。`);
          });
        });
        addLog(`${island.name} 的複製人培養艙開始重建；參戰者必須先離島，之後重新登島才能再次挑戰。`);
        rewardRecipients.forEach((entry) => recordMissionEvent(entry, { type: "postgame_boss_win", tier: defeatedTier, islandKind: "postgame_boss", bossKey: battle.postgameBossKey || "" }));
        finalizeBattleAndAdvanceTurn(player);
        return;
      }
      islandState.isDefeated = true;
      islandState.currentHp = 0;
      if (battle.islandKind === "yonko") {
        islandState.isYonkoDefeated = true;
        state.gameState.yonkoStatus[battle.islandId] = true;
        const firstClear = grantYonkoFirstClearRewards(player, island, islandState);
        addLog(`${player.name} 擊敗了 ${island.name} 的四皇據點。`);
        addLog(`${player.name} 的勝利獎勵：${rewards.summary}。`);
        if (firstClear) addLog(`${player.name} 首次打倒此四皇，已標記擊敗並取得歷史本文拓本。`);
        else addLog(`${player.name} 已打倒過此四皇，本次只取得一般重複挑戰獎勵。`);
        const allYonkoIds = (state.gameState.boardData?.islands || [])
          .filter((entry) => entry.kind === "yonko")
          .map((entry) => entry.id);
        const allYonkoDefeated = allYonkoIds.length > 0
          ? allYonkoIds.every((id) => Boolean(state.gameState.yonkoStatus[id]))
          : Object.values(state.gameState.yonkoStatus).every(Boolean);
        if (allYonkoDefeated && !state.gameState.finalIslandCandidate) {
          state.gameState.finalIslandCandidate = true;
          addLog("四皇全倒，最終之島開始出現線索。");
          const readyPlayer = state.gameState.players.find((entry) => playerHasAllRoadPoneglyphs(entry));
          if (readyPlayer && !state.gameState.finalIslandUnlocked) {
            addLog(`${readyPlayer.name} 已備齊 4 張拓本，可在背包啟動最終之島。`);
          }
        }
      } else {
        const serviceKind = activateTemporaryEnemyIslandService(island, islandState, player);
        immediateServiceKind = serviceKind;
        const sharedClearParticipants = isCoopBattle(battle)
          ? []
          : grantSharedEnemyIslandClearRewards(player, battle, baseRewards, battlePlaceName, serviceKind);
        const postBattleChoicePlayers = isCoopBattle(battle) ? rewardRecipients : sharedClearParticipants;
        const markedChoicePlayers = markPendingIslandServiceChoiceForPlayers(postBattleChoicePlayers, island, serviceKind, battle, player);
        clearPendingIslandServiceChoice(player);
        addLog(`${player.name} 擊敗了 ${island.name}。`);
        addLog(`${player.name} 的勝利獎勵：${rewards.summary}。`);
        if (sharedClearParticipants.length) {
          addLog(`共同參戰者 ${sharedClearParticipants.map((entry) => entry.name).join("、")} 的未完成戰鬥已結算，戰鬥中圖示已清除。`);
        }
        if (markedChoicePlayers.length) {
          addLog(`${markedChoicePlayers.map((entry) => entry.name).join("、")} 下次輪到時可選擇進入${serviceIslandLabel(serviceKind)}或擲骰出發。`);
        }
        addLog(`${island.name} 暫時變成${serviceIslandLabel(serviceKind)}，可以立刻進入；${TEMPORARY_ENEMY_ISLAND_SERVICE_ROUNDS} 回合後敵人會換人回來。`);
      }
    } else if (battle.result === "escape") {
      const escapedPlayers = isCoopBattle(battle) ? coopBattleEscapedParticipants(battle) : [player];
      (escapedPlayers.length ? escapedPlayers : [player]).forEach((escapedPlayer) => {
        addLog(`${escapedPlayer.name} 成功脫離 ${battlePlaceName}。`);
        const escapeMoveBonus = Math.max(0, Math.round(Number(getTeamEffects(escapedPlayer).shipEscapeMoveBonus || 0)));
        if (escapeMoveBonus > 0) {
          escapedPlayer.nextDiceModifier = Number(escapedPlayer.nextDiceModifier || 0) + escapeMoveBonus;
          addLog(`${escapedPlayer.name} 的風來砲改造口推進船身，下次移動骰 +${escapeMoveBonus}。`);
        }
        if (!isSeaEncounter && markForcedReturnRoute(escapedPlayer, island, "escape")) {
          addLog(`${escapedPlayer.name} 下次航行只能沿來時航線原路返回。`);
        }
      });
    } else if (battle.result === "knockout") {
      if (isSeaEncounter) {
        addLog(`${player.name} 在海格遭遇戰暫時失去戰力，戰鬥結束。`);
      } else if (isFinalGateBlackTurnBattle(battle)) {
        player.pendingBattle = cloneBattleState(battle);
        addLog(`${player.name} 在黑轉支配前哨戰暫時失去戰力，下一回合須先派替補。`);
      } else if (isFinalGateBattle(battle)) {
        player.pendingBattle = cloneBattleState(battle);
        addLog(`${player.name} 在伊姆戰暫時失去戰力，下一回合須先派替補。`);
      } else {
        player.pendingBattle = cloneBattleState(battle);
        addLog(`${player.name} 在 ${island.name} 有未完成戰鬥，下一回合須先派替補。`);
      }
    } else if (battle.result === "lose") {
      if (islandState && !isFinalGateBattle(battle) && !isElbaphLokiTrialBattle(battle) && !isFinalGateBlackTurnBattle(battle)) islandState.currentHp = islandState.maxHp;
      if (isFinalGateBattle(battle)) {
        state.gameState.elbaphGateContinuationPending = "";
        player.finalGateElbaphStep = "";
        player.pendingBattle = null;
      } else if (isFinalGateBlackTurnBattle(battle)) {
        state.gameState.elbaphGateContinuationPending = "";
        player.finalGateElbaphStep = "";
        player.pendingBattle = null;
      } else if (isElbaphGodKnightBattle(battle)) {
        state.gameState.elbaphGateContinuationPending = "";
        player.finalGateElbaphStep = "";
        player.pendingBattle = null;
      }
      sendPlayerToImpelDown(player, `${battlePlaceName} 挑戰失敗`);
      addLog(`${battlePlaceName} 的敵人恢復全滿。`);
    } else if (battle.result === "round-pause" || !battle.result) {
      if (isSeaEncounter) {
        player.pendingBattle = cloneBattleState(battle);
        addLog(`${player.name} 與海格遭遇敵人的戰鬥暫時中止，進度已保留。`);
      } else if (isFinalGateBlackTurnBattle(battle)) {
        player.pendingBattle = cloneBattleState(battle);
        addLog(`${player.name} 與被黑轉支配的 ${battle.blackTurnCrewName || "夥伴"} 的戰鬥暫時中止，進度已保留。`);
      } else if (isFinalGateBattle(battle)) {
        player.pendingBattle = cloneBattleState(battle);
        addLog(`${player.name} 與伊姆的戰鬥暫時中止，進度已保留。`);
      } else {
        player.pendingBattle = cloneBattleState(battle);
        addLog(`${player.name} 與 ${island.name} 的戰鬥暫時中止，進度已保留。`);
      }
    }
    if (immediateServiceKind && island && islandState) {
      finalizeBattleAndAdvanceTurn(player, null, {
        advanceTurn: false,
        afterClear: () => {
          enterIslandService({
            player,
            island,
            islandState,
            kind: immediateServiceKind,
            label: serviceIslandLabel(immediateServiceKind),
          });
        },
      });
      return;
    }
    finalizeBattleAndAdvanceTurn(player);
  }

  function processEnemyRegen() {
    const occupiedIslands = new Set(
      state.gameState.players.filter((player) => player.location.kind === "island").map((player) => player.location.islandId)
    );
    state.gameState.boardData.islands.forEach((island) => {
      if (island.kind !== "enemy" && island.kind !== "yonko") return;
      const islandState = getIslandState(island.id);
      if (!islandState || islandState.isDefeated || occupiedIslands.has(island.id)) return;
      if (islandState.currentHp < islandState.maxHp) {
        islandState.currentHp += 1;
        addLog(`${island.name} 的敵人恢復了 1 HP。`);
      }
    });
  }

  function processTemporaryEnemyIslandServices() {
    const round = Math.max(1, Number(state.gameState.round || 1));
    state.gameState.boardData.islands.forEach((island) => {
      const islandState = getIslandState(island.id);
      if (!isTemporaryEnemyIslandService(island, islandState)) return;
      if (Number(islandState.temporaryServiceExpiresAtRound || 0) > round) return;
      const oldServiceKind = islandState.currentKind;
      const profile = refreshEnemyIslandProfile(island, islandState);
      addLog(`${island.name} 的${serviceIslandLabel(oldServiceKind)}結束，新的敵人 ${profile?.name || "未知敵人"} 佔據了島嶼。`);
    });
  }

  function endTurn(options = {}) {
      const player = currentPlayer();
      if (!options.sparRoundComplete && warnBoardLanTurnLocked(player)) return;
      if (!options.itemRevealWaitComplete && itemRevealIsPending()) {
        deferEndTurnUntilItemRevealIdle(options);
        return;
      }
      if (player) {
        player.routeChoice = null;
        player.finalGateRetreat = null;
        tickPlayerMapBuffTurns(player);
      }
      state.gameState.resolutionLock = false;
      if (!options.keepBattleExitLock) state.gameState.battleExitLock = false;
    state.gameState.routePrompt = null;
    state.gameState.tradePrompt = null;
    state.gameState.activeTrade = null;
    state.gameState.coopBattlePrompt = null;
    state.gameState.islandDecision = null;
    processEnemyRegen();
    const playerCount = Math.max(1, state.gameState.players.length);
    const nextPlayerIndex = (state.gameState.currentPlayerIndex + 1) % playerCount;
    state.gameState.currentPlayerIndex = nextPlayerIndex;
    if (nextPlayerIndex === 0) {
      state.gameState.round = Math.max(1, Number(state.gameState.round || 1)) + 1;
      maybeRefreshSeaEncounterTiles();
      processTemporaryEnemyIslandServices();
    }
    state.gameState.turnStep = "擲骰前進";
    applyTurnStartPassives(currentPlayer());
    if (typeof options.beforeAnnouncement === "function") options.beforeAnnouncement();
    const nextPlayer = currentPlayer();
    runAfterTurnHandoffBanner(nextPlayer, () => {
      if (typeof options.beforeVisualUpdate === "function") options.beforeVisualUpdate();
      renderAll();
      scheduleBoardLanStatePush(options.reason || "turn-end", 80);
      scheduleActiveSparUiForLocalPlayer();
      schedulePendingPostgameBossVoyageForCurrentPlayer();
      scheduleAutoResumeBattleForCurrentPlayer();
      scheduleTurnStartIslandServiceChoiceForCurrentPlayer();
      if (typeof options.afterVisualUpdate === "function") options.afterVisualUpdate();
    }, {
      context: options.context || "map",
      subtitle: options.subtitle || "準備擲骰前進。",
    });
  }

  function groupedRegularBackpackItems(player) {
    const groups = new Map();
    (player?.items || []).forEach((item) => {
      if (isBattleCarryItem(item)) return;
      const rawName = typeof item === "string"
        ? item
        : item?.name || item?.title || item?.id || "未知道具";
      const name = {
        pierced_flag: "被打穿的旗幟",
        prime_vivre_card: "舊時代的記憶",
      }[rawName] || rawName;
      groups.set(name, (groups.get(name) || 0) + 1);
    });
    return Array.from(groups, ([name, count]) => ({ name, count }))
      .sort((a, b) => a.name.localeCompare(b.name, "zh-Hant"));
  }

  function groupedBattleCarryBackpackItems(player) {
    const groups = new Map();
    battleCarryInventoryEntries(player).forEach(({ item }) => {
      const def = battleCarryItemDef(item);
      if (!def) return;
      const entry = groups.get(def.id) || { def, count: 0 };
      entry.count += 1;
      groups.set(def.id, entry);
    });
    return Array.from(groups.values())
      .sort((a, b) => a.def.name.localeCompare(b.def.name, "zh-Hant"));
  }

  function createBackpackItem({
    pocket,
    name,
    count,
    tier,
    meta,
    badge,
    action = "",
    image = "",
    itemId = "",
    kind = "",
    frameImage = "",
    portraitImage = "",
  }) {
    return {
      pocket,
      itemId,
      kind,
      frameImage,
      portraitImage,
      name,
      count: Number(count || 0),
      tier,
      meta: compactBackpackMeta(meta),
      badge: badge || String(name || "?").slice(0, 1),
      image: image || itemImageForDisplay(itemId || name),
      action,
    };
  }

  function compactBackpackMeta(value, maxLength = 60) {
    const text = String(value || "效果未登錄。")
      .replace(/\s+/g, " ")
      .replace(/可由敵人戰利品取得。?/g, "")
      .replace(/未裝備的攜帶物會留在背包；已裝備的攜帶物顯示在角色卡。?/g, "裝備後生效。")
      .replace(/背包使用時需選擇 1 名船員。?/g, "選 1 名船員。")
      .trim();
    if (text.length <= maxLength) return text;
    const sentences = text.split(/(?<=[。！？!?])/).map((part) => part.trim()).filter(Boolean);
    let output = "";
    for (const sentence of sentences) {
      if (!output || `${output}${sentence}`.length <= maxLength) output += sentence;
      else break;
    }
    if (output) return output;
    return `${text.slice(0, Math.max(12, maxLength - 1)).trim()}。`;
  }

  function roadPoneglyphBackpackItems(player) {
    const ownedGlyphs = new Set(Array.isArray(player?.roadPoneglyphs) ? player.roadPoneglyphs : []);
    const totalOwned = playerRoadPoneglyphCount(player);
    const canActivateFinal = totalOwned >= 4 && !state.gameState.finalIslandUnlocked;
    const finalMeta = state.gameState.finalIslandUnlocked
      ? "最終之島已開啟。"
      : canActivateFinal
        ? "4/4 已集滿，按啟動讓最終之島現身。"
        : `目前 ${Math.min(4, totalOwned)}/4，集滿東、西、南、北後可啟動最終之島。`;
    const items = Object.entries(ROAD_PONEGLYPH_BY_GLYPH)
      .map(([glyphId, info]) => {
        const count = Math.max(ownedGlyphs.has(glyphId) ? 1 : 0, inventoryItemCount(player, info.itemId));
        if (count <= 0) return null;
        return createBackpackItem({
          pocket: "key",
          itemId: info.itemId,
          name: info.name,
          count,
          tier: `重要道具 ・ ${info.direction}拓本`,
          meta: finalMeta,
          badge: info.direction,
          image: itemImageForDisplay(info.itemId),
          action: canActivateFinal ? "activate_final_island" : "",
        });
      })
      .filter(Boolean)
      .sort((a, b) => "東西南北".indexOf(a.badge) - "東西南北".indexOf(b.badge));
    const legacyCount = inventoryItemCount(player, "road_poneglyph");
    if (!items.length && legacyCount > 0) {
      items.push(createBackpackItem({
        pocket: "key",
        itemId: "road_poneglyph",
        name: "歷史本文拓本",
        count: legacyCount,
        tier: `重要道具 ・ ${legacyCount}/4`,
        meta: finalMeta || "舊存檔拓本；新取得的拓本會分為東、西、南、北。",
        badge: "拓",
        action: canActivateFinal ? "activate_final_island" : "",
      }));
    }
    return items;
  }

  function backpackKeyItemShortMeta(itemDef) {
    const effect = itemDef?.effect || {};
    const kind = effect.kind || "";
    if (["training_material", "training_material_small"].includes(kind)) {
      return `${trainingStatBonusText(effect.trainingType, trainingItemPoints(itemDef))}。選 1 名船員。`;
    }
    if (kind === "training_tier_material") {
      return `修行 +${trainingItemPoints(itemDef)}，補到最低修行項。`;
    }
    if (kind === "skill_training_material") return "補學已達等級的招式，滿 4 招可替換。";
    if (kind === "switch_unlocked_passive") return "戰鬥記憶 +1，依定位小幅加成。";
    if (kind === "reset_training_build") return "重置修行，返還部分修行點。";
    if (kind === "crew_evolution_material") return "Lv.20 草帽團進化用，使用後消耗。";
    if (kind === "new_world_evolution_material") return "新世界進化用，使用後消耗。";
    if (kind === "prime_era_evolution_material") return "S級任務取得；舊時代巔峰進化用。";
    if (kind === "judicial_clear_chest") return "四個通關獎勵選 1 個。";
    if (kind === "sea_train_golden_ticket") return "可前往固定站水之七島，也能標記島嶼後直達。";
    if (kind === "story_unlock_material") return "劇情與最終航線線索。";
    if (kind === "story_clear_proof") return "劇情通關證明。";
    return "";
  }

  function backpackItemShortMeta(itemDef, category) {
    if (!itemDef) return "效果未登錄。";
    if (category === "key") return backpackKeyItemShortMeta(itemDef) || compactBackpackMeta(itemDef.uiSummary || itemDef.description);
    const base = itemDef.uiSummary || itemDef.description || "效果未登錄。";
    if (category === "ship" && itemDef.effect?.kind === "ship_equipment") return compactBackpackMeta(`${base} 裝到船隻孔位後生效。`);
    if (category === "ship" && itemDef.effect?.kind === "ship_material") return compactBackpackMeta(`${base} 船隻改造素材。`);
    if (isBackpackHealingItem(itemDef)) return compactBackpackMeta(`${base} 選 1 名船員。`);
    return compactBackpackMeta(base);
  }

  function backpackCarryShortMeta(def) {
    return compactBackpackMeta(`${def?.summary || "裝備後戰鬥中生效。"} 裝備後生效。`);
  }

  function keyBackpackAction(itemDef) {
    const kind = itemDef?.effect?.kind || "";
    if (kind === "judicial_clear_chest") return `open_judicial_chest:${itemDef.id}`;
    if (kind === "sea_train_golden_ticket") return `use_sea_train_ticket:${itemDef.id}`;
    if (["training_material", "training_material_small", "training_tier_material"].includes(kind)) return `select_training_target:${itemDef.id}`;
    if (kind === "skill_training_material") return `select_skill_training_target:${itemDef.id}`;
    if (kind === "switch_unlocked_passive") return `select_passive_target:${itemDef.id}`;
    if (kind === "reset_training_build") return `select_training_reset:${itemDef.id}`;
    if (kind === "crew_evolution_material") return `select_evolution_target:${itemDef.id}`;
    if (kind === "new_world_evolution_material") return `select_evolution_target:${itemDef.id}`;
    if (kind === "prime_era_evolution_material") return `select_evolution_target:${itemDef.id}`;
    return "";
  }

  function keyItemUseHint(itemDef) {
    const kind = itemDef?.effect?.kind || "";
    if (kind === "judicial_clear_chest") return " 可從背包打開。";
    if (kind === "sea_train_golden_ticket") return " 可從背包前往水之七島、標記島嶼或搭乘海上列車。";
    if (["training_material", "training_material_small", "training_tier_material"].includes(kind)) return " 可從背包選船員修行。";
    if (kind === "skill_training_material") return " 可從背包選船員補學招式。";
    if (kind === "switch_unlocked_passive") return " 可從背包選船員強化戰鬥記憶。";
    if (kind === "reset_training_build") return " 可從背包選船員重置修行。";
    if (kind === "crew_evolution_material") return " 可從背包選角色進化。";
    if (kind === "new_world_evolution_material") return " 可從背包選角色進化。";
    if (kind === "prime_era_evolution_material") return " 可從背包選角色進化。";
    return "";
  }

  const JUDICIAL_CLEAR_CHEST_CHOICES = [
    { id: "pierced_flag", type: "key" },
    { id: "sea_train_golden_ticket", type: "key" },
    { id: "seastone_handcuffs", type: "held" },
    { id: "going_merry_rescue", type: "held" },
  ];

  function judicialClearChestChoiceDisplay(choice) {
    if (!choice) return null;
    if (choice.type === "held") {
      const def = battleCarryItemDef(choice.id);
      if (!def) return null;
      return {
        id: def.id,
        type: "held",
        name: battleCarryItemName(def),
        tier: def.rarity || "司法島通關",
        summary: def.summary || "角色攜帶物。",
        image: def.image || battleCarryItemImage(def),
        category: "held",
      };
    }
    const def = gameItemDef(choice.id);
    if (!def) return null;
    return {
      id: def.id,
      type: "key",
      name: def.name,
      tier: def.rarity || "司法島通關",
      summary: def.uiSummary || def.description || "重要道具。",
      image: itemImageForDisplay(def),
      category: normalizeGameItemCategory(def.category),
    };
  }

  function grantJudicialClearChestContents(player, choiceId = "") {
    const rewards = [];
    const choice = JUDICIAL_CLEAR_CHEST_CHOICES.find((entry) => entry.id === choiceId) || JUDICIAL_CLEAR_CHEST_CHOICES[0];
    const choiceDisplay = judicialClearChestChoiceDisplay(choice);
    if (choice?.type === "held") {
      const item = addBattleCarryItemToBackpack(player, choice.id);
      if (item) {
        rewards.push(battleCarryItemName(item));
        recordMissionEvent(player, { type: "obtain_item", itemId: item.id, itemName: battleCarryItemName(item), category: "held" });
      }
    } else if (choice?.id) {
      const item = grantFormalItemToPlayer(player, choice.id, 1, { reveal: !!gameItemDef(choice.id)?.important });
      if (item) rewards.push(item.name);
    }
    return { rewards, choice: choiceDisplay };
  }

  function confirmJudicialClearChestChoice(player, itemId, choiceId) {
    const itemDef = gameItemDef(itemId);
    if (!player || !itemDef || inventoryItemCount(player, itemDef.id) <= 0) return;
    if (!removeFormalItemFromPlayer(player, itemDef.id, 1)) return;
    const { rewards, choice } = grantJudicialClearChestContents(player, choiceId);
    addLog(`${player.name} 打開${itemDef.name}，獲得 ${rewards.join("、")}。`);
    emitItemUseBoardEvent(player, itemDef, `${player.name} 打開${itemDef.name}。`);
    recordMissionEvent(player, { type: "use_item_category", category: "key", itemId: itemDef.id, itemName: itemDef.name });
    renderAll();
    openBackpackModal({ pocketId: choice?.type === "held" ? "held" : "key", itemName: choice?.name || "被打穿的旗幟" });
  }

  function openJudicialClearChest(player, itemId = "judicial_clear_chest") {
    const itemDef = gameItemDef(itemId);
    if (!player || !itemDef || inventoryItemCount(player, itemDef.id) <= 0) return;
    const choices = JUDICIAL_CLEAR_CHEST_CHOICES
      .map(judicialClearChestChoiceDisplay)
      .filter(Boolean);
    openModal(`
      <h3 class="modal-title">${escapeModalText(itemDef.name)}</h3>
      <div class="modal-sub">從 4 個司法島通關獎勵中選 1 個。選定後才會消耗寶箱。</div>
      <div class="companion-grid">
        ${choices.map((choice) => `
          <article class="companion-card">
            <div class="companion-tier">四選一 ・ ${escapeModalText(choice.tier)}</div>
            <div class="crew-target-row">
              ${itemIconMarkup({ name: choice.name, category: choice.category, image: choice.image }, "companion-item-thumb", { badge: choice.name.slice(0, 1) })}
              <span>
                <div class="companion-name">${escapeModalText(choice.name)}</div>
                <div class="companion-meta">${escapeModalText(compactBackpackMeta(choice.summary, 54))}</div>
              </span>
            </div>
            <button type="button" class="modal-btn primary" data-judicial-chest-choice="${escapeModalText(choice.id)}">選這個</button>
          </article>
        `).join("")}
      </div>
      <div class="modal-row"><button type="button" class="modal-btn secondary" id="backToBackpackFromJudicialChestBtn">返回背包</button></div>
    `);
    refs.modal.querySelectorAll("[data-judicial-chest-choice]").forEach((button) => {
      button.addEventListener("click", () => confirmJudicialClearChestChoice(player, itemDef.id, button.dataset.judicialChestChoice));
    });
    document.getElementById("backToBackpackFromJudicialChestBtn")?.addEventListener("click", () => {
      openBackpackModal({ pocketId: "key", itemName: itemDef.name });
    });
  }

  function quadraticPathPoint(start, control, end, t) {
    const u = 1 - t;
    return {
      x: u * u * start.x + 2 * u * t * control.x + t * t * end.x,
      y: u * u * start.y + 2 * u * t * control.y + t * t * end.y,
    };
  }

  function quadraticPathTangent(start, control, end, t) {
    return {
      x: 2 * (1 - t) * (control.x - start.x) + 2 * t * (end.x - control.x),
      y: 2 * (1 - t) * (control.y - start.y) + 2 * t * (end.y - control.y),
    };
  }

  function seaTrainControlPoint(start, end) {
    const mid = { x: (start.x + end.x) * 0.5, y: (start.y + end.y) * 0.5 };
    const board = boardPixelSize();
    let away = { x: mid.x - board.width * 0.5, y: mid.y - board.height * 0.5 };
    let length = Math.hypot(away.x, away.y);
    if (length < 1) {
      away = { x: -(end.y - start.y), y: end.x - start.x };
      length = Math.hypot(away.x, away.y) || 1;
    }
    const distance = Math.hypot(end.x - start.x, end.y - start.y);
    const arc = Math.min(940, Math.max(260, distance * 0.28));
    return {
      x: mid.x + (away.x / length) * arc,
      y: mid.y + (away.y / length) * arc,
    };
  }

  function seaTrainFrameMarkup() {
    return SEA_TRAIN_FRAME_URLS.map((src, index) => (
      `<img class="sea-train-map-frame" src="${src}" alt="" style="--frame:${index}" draggable="false">`
    )).join("");
  }

  function seaTrainReadableHeading(angle) {
    const flip = angle > 90 || angle < -90 ? -1 : 1;
    const readableAngle = flip < 0
      ? angle + (angle > 0 ? -180 : 180)
      : angle;
    return { angle: readableAngle, flip };
  }

  function setSeaTrainTokenPose(train, point, angle) {
    if (!train || !point) return;
    const heading = seaTrainReadableHeading(angle);
    train.style.left = `${point.x}px`;
    train.style.top = `${point.y}px`;
    train.style.setProperty("--sea-train-facing-flip", String(heading.flip));
    train.style.transform = `translate(-50%,-50%) rotate(${heading.angle}deg)`;
  }

  function playSeaTrainGoldenTicketAnimation(player, destinationIsland, onComplete) {
    const board = refs.boardGameMap;
    if (!player || !destinationIsland || !board) {
      onComplete?.();
      return;
    }
    const reduceMotion = window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;
    const start = playerShipTokenPositionPx(player);
    const end = playerShipTokenPositionPx(player, nodeToPx(destinationIsland));
    const control = seaTrainControlPoint(start, end);
    const boardSize = boardPixelSize();
    const railPath = `M ${start.x} ${start.y} Q ${control.x} ${control.y} ${end.x} ${end.y}`;
    const trackMaskId = `sea-train-track-mask-${Date.now()}-${Math.random().toString(36).slice(2)}`;
    const layer = document.createElement("div");
    layer.className = "sea-train-map-layer";
    layer.innerHTML = `
      <svg class="sea-train-map-rail-svg" viewBox="0 0 ${boardSize.width} ${boardSize.height}" aria-hidden="true">
        <defs>
          <mask id="${trackMaskId}" maskUnits="userSpaceOnUse">
            <rect x="0" y="0" width="${boardSize.width}" height="${boardSize.height}" fill="black"></rect>
            <path class="sea-train-map-track-reveal" pathLength="1" d="${railPath}"></path>
          </mask>
        </defs>
        <g class="sea-train-map-track-group" mask="url(#${trackMaskId})">
          <path class="sea-train-map-water-cut" d="${railPath}"></path>
          <path class="sea-train-map-track-shadow" d="${railPath}"></path>
          <path class="sea-train-map-track-support" d="${railPath}"></path>
          <path class="sea-train-map-track-bed" d="${railPath}"></path>
          <path class="sea-train-map-track-deck" d="${railPath}"></path>
          <path class="sea-train-map-track-sleepers" d="${railPath}"></path>
          <path class="sea-train-map-rail" transform="translate(0 -5)" d="${railPath}"></path>
          <path class="sea-train-map-rail" transform="translate(0 5)" d="${railPath}"></path>
          <path class="sea-train-map-rail-highlight" transform="translate(0 -6)" d="${railPath}"></path>
          <path class="sea-train-map-rail-highlight" transform="translate(0 4)" d="${railPath}"></path>
          <path class="sea-train-map-rail-bolts" transform="translate(0 -5)" d="${railPath}"></path>
          <path class="sea-train-map-rail-bolts" transform="translate(0 5)" d="${railPath}"></path>
          <path class="sea-train-map-rail-guard" transform="translate(0 -10)" d="${railPath}"></path>
          <path class="sea-train-map-rail-guard" transform="translate(0 10)" d="${railPath}"></path>
          <path class="sea-train-map-steam-line" transform="translate(0 -14)" d="${railPath}"></path>
        </g>
      </svg>
      <div class="sea-train-map-burst" style="left:${start.x}px;top:${start.y}px" aria-hidden="true"></div>
      <div class="sea-train-map-token has-frame-art" style="--sea-train-token-size:${SEA_TRAIN_TOKEN_SIZE_PX}px;--sea-train-sprite-correction:-${SEA_TRAIN_SPRITE_FORWARD_DEG}deg;--sea-train-rail-seat:-14px" aria-hidden="true">
        <div class="sea-train-map-facing">
          <div class="sea-train-map-fallback"><i></i><b></b><em></em><span></span></div>
          <div class="sea-train-map-sprite">
            <div class="sea-train-map-frames">${seaTrainFrameMarkup()}</div>
            <div class="sea-train-map-sparks"><span></span><span></span><span></span></div>
          </div>
        </div>
      </div>
    `;
    board.appendChild(layer);
    state.seaTrainAnimation = { playerId: player.id };
    const escapedPlayerId = window.CSS?.escape ? CSS.escape(player.id) : String(player.id).replace(/"/g, '\\"');
    const sourceShip = refs.boardGameMap?.querySelector(`.ship-token[data-player-id="${escapedPlayerId}"]`);
    sourceShip?.classList.add("sea-train-transforming-source");
    const train = layer.querySelector(".sea-train-map-token");
    const initialTangent = quadraticPathTangent(start, control, end, 0);
    const initialAngle = Math.atan2(initialTangent.y, initialTangent.x) * 180 / Math.PI;
    setSeaTrainTokenPose(train, start, initialAngle);
    const transformDelay = reduceMotion ? 220 : 1080;
    const trackRevealDuration = reduceMotion ? 80 : 1050;
    const duration = reduceMotion ? 920 : Math.max(3400, Math.min(6200, Math.hypot(end.x - start.x, end.y - start.y) * 1.08));
    const followScale = Math.max(0.68, Math.min(0.96, state.panZoom.scale || 0.8));
    const ease = (t) => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
    let startTime = 0;
    const tick = (timestamp) => {
      if (!startTime) startTime = timestamp;
      const raw = Math.min(1, (timestamp - startTime) / duration);
      const t = ease(raw);
      const point = quadraticPathPoint(start, control, end, t);
      const tangent = quadraticPathTangent(start, control, end, t);
      const angle = Math.atan2(tangent.y, tangent.x) * 180 / Math.PI;
      setSeaTrainTokenPose(train, point, angle);
      panToBoardPoint(point.x, point.y, { immediate: true, scale: followScale });
      if (raw < 1) {
        requestAnimationFrame(tick);
        return;
      }
      layer.classList.add("arrived");
      window.setTimeout(() => {
        layer.remove();
        state.seaTrainAnimation = null;
        onComplete?.();
      }, reduceMotion ? 80 : 220);
    };
    panToBoardPoint(start.x, start.y, { immediate: false, scale: followScale });
    window.setTimeout(() => {
      sourceShip?.classList.add("sea-train-hidden-source");
      layer.classList.add("moving");
      window.setTimeout(() => {
        layer.classList.add("train-moving");
        requestAnimationFrame(tick);
      }, trackRevealDuration);
    }, transformDelay);
  }

  function seaTrainTicketDestinationCardMarkup(destination, currentIsland = null) {
    const island = destination?.island;
    if (!island) return "";
    const islandImage = getIslandImageUrl(island, getIslandState(island.id)) || ISLAND_IMAGE_MAP.unknown;
    const isCurrent = currentIsland?.id === island.id;
    const status = isCurrent ? "目前所在" : destination.key === "water-seven" ? "固定站" : "標記站";
    const kicker = destination.key === "water-seven" ? "海上列車固定停靠點" : "玩家設定的列車終點";
    return `
      <button type="button" class="sea-train-destination-card" data-sea-train-destination="${escapeModalText(destination.key)}" aria-label="${escapeModalText(destination.label)}">
        <span class="sea-train-destination-visual">
          <img src="${escapeModalText(islandImage)}" alt="${escapeModalText(island.name)}" loading="eager" data-fallback-src="${escapeModalText(ISLAND_IMAGE_MAP.unknown)}" onerror="if(this.dataset.fallbackSrc){this.src=this.dataset.fallbackSrc;this.dataset.fallbackSrc='';}else{this.src='images/board/attribute_icons/neutral.webp';}">
        </span>
        <img class="sea-train-destination-frame" src="${SEA_TRAIN_TICKET_UI_ASSETS.destination}" alt="" aria-hidden="true">
        <span class="sea-train-destination-copy">
          <small>${escapeModalText(kicker)}</small>
          <strong>${escapeModalText(island.name)}</strong>
          <b>${escapeModalText(destination.label)}</b>
        </span>
        <span class="sea-train-destination-status">${escapeModalText(status)}</span>
      </button>
    `;
  }

  function seaTrainTicketActionMarkup(id, label, primary = false) {
    return `
      <button type="button" class="sea-train-ticket-action ${primary ? "primary" : "secondary"}" id="${escapeModalText(id)}">
        <img src="${SEA_TRAIN_TICKET_UI_ASSETS.actionButton}" alt="" aria-hidden="true">
        <span>${escapeModalText(label)}</span>
      </button>
    `;
  }

  function openSeaTrainGoldenTicketModal(player, itemId = "sea_train_golden_ticket") {
    const itemDef = gameItemDef(itemId);
    if (!player || !itemDef || inventoryItemCount(player, itemDef.id) <= 0) return;
    const currentIsland = player.location?.kind === "island" ? getIslandById(player.location.islandId) : null;
    const station = player.seaTrainGoldenTicketStationId ? getIslandById(player.seaTrainGoldenTicketStationId) : null;
    const waterSeven = getIslandById(WATER_SEVEN_ISLAND_ID);
    const destinations = [
      station ? { key: "station", island: station, label: currentIsland?.id === station.id ? "進入標記島" : "搭乘到標記島", primary: true } : null,
      waterSeven && station?.id !== waterSeven.id ? { key: "water-seven", island: waterSeven, label: currentIsland?.id === waterSeven.id ? "進入水之七島" : "搭乘到水之七島", primary: !station } : null,
    ].filter(Boolean);
    const subtitle = station
      ? `目前標記：${station.name}。水之七島可直接作為固定停靠點。`
      : "尚未標記島嶼。可先搭乘到水之七島，或在任意島上標記終點。";
    const ticketImage = itemImageForDisplay(itemDef) || "images/board/items/sea_train_golden_ticket.webp";
    openModal(`
      <section class="sea-train-ticket-ui" aria-label="海上列車黃金票">
        <div class="sea-train-ticket-art">
          <img src="${escapeModalText(ticketImage)}" alt="${escapeModalText(itemDef.name)}" loading="eager" onerror="this.hidden=true;this.parentElement.classList.add('fallback');">
          <span><img src="${escapeModalText(itemFallbackIconPath(itemDef))}" alt="" aria-hidden="true"></span>
        </div>
        <img class="sea-train-ticket-panel-frame" src="${SEA_TRAIN_TICKET_UI_ASSETS.panel}" alt="" aria-hidden="true">
        <header class="sea-train-ticket-heading"><h3>海上列車黃金票</h3></header>
        <div class="sea-train-ticket-subtitle">${escapeModalText(subtitle)}</div>
        <div class="sea-train-ticket-status-grid">
          <div><span>目前位置</span><strong>${escapeModalText(currentIsland?.name || "目前在海路上")}</strong></div>
          <div><span>標記終點</span><strong>${escapeModalText(station?.name || "尚未設定")}</strong></div>
          <div><span>固定車站</span><strong>${escapeModalText(waterSeven?.name || "水之七島")}</strong></div>
        </div>
        <div class="sea-train-destination-list count-${destinations.length}">
          ${destinations.map((destination) => seaTrainTicketDestinationCardMarkup(destination, currentIsland)).join("") || `<div class="sea-train-destination-empty">目前沒有可用目的地</div>`}
        </div>
        <div class="sea-train-ticket-actions">
          ${currentIsland ? seaTrainTicketActionMarkup("seaTrainMarkBtn", station ? "改標記目前島" : "標記目前島", !station) : ""}
          ${seaTrainTicketActionMarkup("seaTrainCancelBtn", "取消")}
        </div>
      </section>
    `, "sea-train-ticket-nautical-modal");
    document.getElementById("seaTrainMarkBtn")?.addEventListener("click", () => {
      if (!currentIsland) return;
      player.seaTrainGoldenTicketStationId = currentIsland.id;
      addLog(`${player.name} 使用${itemDef.name}標記了 ${currentIsland.name}。`);
      emitItemUseBoardEvent(player, itemDef, `${player.name} 使用${itemDef.name}標記了目前島嶼。`);
      recordMissionEvent(player, { type: "use_item_category", category: "key", itemId: itemDef.id, itemName: itemDef.name });
      renderAll();
      openBackpackModal({ pocketId: "key", itemName: itemDef.name });
    });
    refs.modal.querySelectorAll("[data-sea-train-destination]").forEach((button) => {
      button.addEventListener("click", () => {
        const destination = destinations.find((entry) => entry.key === button.dataset.seaTrainDestination);
        const targetIsland = destination?.island;
        if (!targetIsland) return;
        if (currentIsland?.id === targetIsland.id) {
          addLog(`${player.name} 使用${itemDef.name}進入 ${targetIsland.name}。`);
          closeModal();
          resolveLanding(player);
          return;
        }
        closeModal();
        state.gameState.movementAnimating = true;
        state.gameState.turnStep = "海上列車移動中";
        renderAll();
        playSeaTrainGoldenTicketAnimation(player, targetIsland, () => {
          state.gameState.pendingMove = null;
          state.gameState.routePrompt = null;
          state.gameState.islandDecision = null;
          state.gameState.movementAnimating = false;
          player.location = { kind: "island", islandId: targetIsland.id, entryDirection: null };
          player.routeChoice = null;
          state.gameState.turnStep = "停靠結算";
          addLog(`${player.name} 搭乘${itemDef.name}抵達 ${targetIsland.name}。`);
          emitItemUseBoardEvent(player, itemDef, `${player.name} 搭乘${itemDef.name}抵達 ${targetIsland.name}。`);
          handleIslandArrival(player, targetIsland);
          renderAll();
          resolveLanding(player);
        });
      });
    });
    document.getElementById("seaTrainCancelBtn")?.addEventListener("click", () => {
      openBackpackModal({ pocketId: "key", itemName: itemDef.name });
    });
  }

  function trainingItemPoints(itemDef) {
    const effect = itemDef?.effect || {};
    if (effect.kind === "training_material_small") return TRAINING_ITEM_POINTS.training_material_small;
    if (effect.kind === "training_material") return TRAINING_ITEM_POINTS.training_material;
    if (effect.kind === "training_tier_material") return TRAINING_ITEM_POINTS[`training_tier_${effect.tier}`] || 1;
    return 0;
  }

  function addTrainingPoint(card, stat, amount = 1) {
    normalizeCardTraining(card);
    const key = TRAINING_STATS.includes(stat) ? stat : "hp";
    const before = Number(card.training[key] || 0);
    card.training[key] = Math.max(0, Math.min(TRAINING_MAX_PER_STAT, before + Math.max(0, Math.floor(Number(amount || 0)))));
    return card.training[key] - before;
  }

  function addGeneralTrainingPoints(card, amount = 1) {
    normalizeCardTraining(card);
    const changes = {};
    let remaining = Math.max(0, Math.floor(Number(amount || 0)));
    while (remaining > 0) {
      const candidates = TRAINING_STATS
        .filter((stat) => Number(card.training[stat] || 0) < TRAINING_MAX_PER_STAT)
        .sort((a, b) => Number(card.training[a] || 0) - Number(card.training[b] || 0));
      if (!candidates.length) break;
      const stat = candidates[0];
      const added = addTrainingPoint(card, stat, 1);
      if (added <= 0) break;
      changes[stat] = (changes[stat] || 0) + added;
      remaining -= 1;
    }
    return changes;
  }

  function trainingChangeText(changes = {}) {
    return Object.entries(changes)
      .filter(([, value]) => Number(value || 0) > 0)
      .map(([stat, value]) => `${TRAINING_STAT_LABELS[stat] || stat}+${value}`)
      .join("、");
  }

  function trainingItemTargetReason(itemDef, card) {
    if (!itemDef || !card) return "無法使用";
    const effect = itemDef.effect || {};
    if (["training_material", "training_material_small"].includes(effect.kind)) {
      const stat = effect.trainingType;
      normalizeCardTraining(card);
      return Number(card.training?.[stat] || 0) >= TRAINING_MAX_PER_STAT ? `${TRAINING_STAT_LABELS[stat] || stat}修行已滿` : "";
    }
    if (effect.kind === "training_tier_material") {
      normalizeCardTraining(card);
      return TRAINING_STATS.every((stat) => Number(card.training?.[stat] || 0) >= TRAINING_MAX_PER_STAT) ? "全修行已滿" : "";
    }
    return "";
  }

  function maxTrainingItemQuantity(player, itemDef, card) {
    const available = backpackUsableItemCount(player, itemDef?.id);
    if (!itemDef || !card || available <= 0 || trainingItemTargetReason(itemDef, card)) return 0;
    const effect = itemDef.effect || {};
    const points = Math.max(1, trainingItemPoints(itemDef));
    normalizeCardTraining(card);
    if (["training_material", "training_material_small"].includes(effect.kind)) {
      const stat = effect.trainingType;
      const remaining = Math.max(0, TRAINING_MAX_PER_STAT - Number(card.training?.[stat] || 0));
      return Math.max(1, Math.min(available, Math.ceil(remaining / points)));
    }
    if (effect.kind === "training_tier_material") {
      const remaining = TRAINING_STATS.reduce((sum, stat) => sum + Math.max(0, TRAINING_MAX_PER_STAT - Number(card.training?.[stat] || 0)), 0);
      return Math.max(1, Math.min(available, Math.ceil(remaining / points)));
    }
    return 0;
  }

  function returnToTrainingDetailAfterMaterial(player, targetIndex, options = {}) {
    if (!options?.returnToTrainingDetail) return false;
    openTrainingDetailModal(player, targetIndex, { returnTo: String(options.trainingDetailReturnTo || "") });
    return true;
  }

  function openBackpackTrainingQuantityModal(player, itemId, targetIndex, options = {}) {
    const itemDef = gameItemDef(itemId);
    const card = player?.crew?.[targetIndex];
    if (!player || !itemDef || !card) return;
    const maxQuantity = maxTrainingItemQuantity(player, itemDef, card);
    if (maxQuantity <= 1) {
      applyTrainingItemToTarget(player, itemDef.id, targetIndex, 1, options);
      return;
    }
    const available = backpackUsableItemCount(player, itemDef.id);
    let quantity = 1;
    openModal(`
      <section class="training-quantity-ui" aria-label="對 ${escapeModalText(cardDisplayName(card))} 使用 ${escapeModalText(itemDef.name)}">
        <img class="training-quantity-frame" src="images/board/training_ui/training_item_quantity_frame.webp" alt="" aria-hidden="true">
        <h3 class="training-quantity-title">使用數量</h3>
        <span class="training-quantity-icon"><img src="${escapeModalText(itemImageForDisplay(itemDef.id))}" alt="${escapeModalText(itemDef.name)}" onerror="this.hidden=true;"></span>
        <div class="training-quantity-item-line"><strong>${escapeModalText(itemDef.name)}</strong><span>持有 ${available} 個</span></div>
        <div class="training-quantity-target-line">${escapeModalText(cardDisplayName(card))} ・ ${escapeModalText(trainingSummary(card))}</div>
        <button type="button" class="training-quantity-step" id="backpackTrainingQtyMinus" aria-label="減少使用數量">−</button>
        <strong class="training-quantity-value" id="backpackTrainingQtyValue">1</strong>
        <button type="button" class="training-quantity-step" id="backpackTrainingQtyPlus" aria-label="增加使用數量">＋</button>
        <div class="training-quantity-note"><span>最多有效 ${maxQuantity} 個</span><strong id="backpackTrainingQtyPreview">使用 1 個</strong></div>
        <button type="button" class="training-quantity-confirm" id="backpackTrainingQtyConfirm">確定使用</button>
        <button type="button" class="training-quantity-cancel" id="backpackTrainingQtyCancel">${options?.returnToTrainingDetail ? "返回修行詳情" : "返回選人"}</button>
      </section>
    `, "training-quantity-nautical-modal");
    const qtyValue = document.getElementById("backpackTrainingQtyValue");
    const qtyPreview = document.getElementById("backpackTrainingQtyPreview");
    const updateQuantity = () => {
      qtyValue.textContent = String(quantity);
      qtyPreview.textContent = `使用 ${quantity} 個`;
    };
    document.getElementById("backpackTrainingQtyMinus")?.addEventListener("click", () => {
      quantity = quantity <= 1 ? maxQuantity : Math.max(1, quantity - 1);
      updateQuantity();
    });
    document.getElementById("backpackTrainingQtyPlus")?.addEventListener("click", () => {
      quantity = Math.min(maxQuantity, quantity + 1);
      updateQuantity();
    });
    document.getElementById("backpackTrainingQtyConfirm")?.addEventListener("click", () => {
      applyTrainingItemToTarget(player, itemDef.id, targetIndex, quantity, options);
    });
    document.getElementById("backpackTrainingQtyCancel")?.addEventListener("click", () => {
      if (!returnToTrainingDetailAfterMaterial(player, targetIndex, options)) openBackpackCrewTargetModal(player, itemDef.id, "training");
    });
  }

  function applyTrainingItemToTarget(player, itemId, targetIndex, quantity = 1, options = {}) {
    const itemDef = gameItemDef(itemId);
    const card = player?.crew?.[targetIndex];
    if (!player || !itemDef || !card || backpackUsableItemCount(player, itemDef.id) <= 0) return;
    const reason = trainingItemTargetReason(itemDef, card);
    if (reason) {
      addLog(`${cardDisplayName(card)} 目前不能使用 ${itemDef.name}：${reason}。`);
      if (!returnToTrainingDetailAfterMaterial(player, targetIndex, options)) openBackpackCrewTargetModal(player, itemDef.id, "training");
      return;
    }
    const previousStats = { ...(card.baseStats || {}) };
    const effect = itemDef.effect || {};
    let changes = {};
    let used = 0;
    const requested = Math.max(1, Math.round(Number(quantity || 1)));
    for (let index = 0; index < requested; index += 1) {
      if (trainingItemTargetReason(itemDef, card)) break;
      if (!consumeMapBackpackItem(player, itemDef.id)) break;
      let currentChanges = {};
      if (["training_material", "training_material_small"].includes(effect.kind)) {
        const added = addTrainingPoint(card, effect.trainingType, trainingItemPoints(itemDef));
        currentChanges[effect.trainingType] = added;
      } else if (effect.kind === "training_tier_material") {
        currentChanges = addGeneralTrainingPoints(card, trainingItemPoints(itemDef));
      }
      if (!Object.values(currentChanges).some((value) => Number(value || 0) > 0)) break;
      Object.entries(currentChanges).forEach(([stat, value]) => {
        changes[stat] = Number(changes[stat] || 0) + Number(value || 0);
      });
      used += 1;
    }
    if (used <= 0) {
      addLog(`${itemDef.name}沒有產生效果。`);
      if (!returnToTrainingDetailAfterMaterial(player, targetIndex, options)) openBackpackCrewTargetModal(player, itemDef.id, "training");
      return;
    }
    const statGain = applyCardLevelStats(card, previousStats);
    recalcPlayerDerivedStats(player);
    const changeText = trainingChangeText(changes) || "沒有提升";
    const gainText = statGainText(statGain);
    const itemText = used > 1 ? `${itemDef.name} ×${used}` : itemDef.name;
    addLog(`${player.name} 對 ${cardDisplayName(card)} 使用${itemText}，修行 ${changeText}${gainText ? `，能力提升：${gainText}` : ""}。`);
    emitItemUseBoardEvent(player, itemDef, `${player.name} 對 ${cardDisplayName(card)} 使用${itemText}。`, { quantity: used, cardName: cardDisplayName(card) });
    recordMissionEvent(player, { type: "use_item_category", category: "key", itemId: itemDef.id, itemName: itemDef.name }, used);
    renderAll();
    if (!returnToTrainingDetailAfterMaterial(player, targetIndex, options)) openBackpackModal({ pocketId: "key", itemName: itemDef.name });
  }

  function skillTrainingCandidate(card, itemDef) {
    syncCardMoveSetFromCatalog(card);
    syncUnlockedMoveIds(card);
    const activeIds = new Set((card.unlockedMoveIds || []).slice(0, MAX_ACTIVE_MOVES));
    const level = Number(card.level || 1);
    const candidates = (card.moveSet || [])
      .filter((moveEntry) => effectiveMoveUnlockLevel(moveEntry) <= level && !activeIds.has(moveEntry.id))
      .sort((a, b) => {
        const ultimateBias = itemDef?.effect?.level === "ultimate"
          ? Number(boardMoveIsSpecialDamage(b) || effectiveMoveUnlockLevel(b) >= 35) - Number(boardMoveIsSpecialDamage(a) || effectiveMoveUnlockLevel(a) >= 35)
          : 0;
        return ultimateBias
          || effectiveMoveUnlockLevel(b) - effectiveMoveUnlockLevel(a)
          || Number(b.power || 0) - Number(a.power || 0);
      });
    return candidates[0] || null;
  }

  function applySkillTrainingItemToTarget(player, itemId, targetIndex, options = {}) {
    const itemDef = gameItemDef(itemId);
    const card = player?.crew?.[targetIndex];
    if (!player || !itemDef || !card || backpackUsableItemCount(player, itemDef.id) <= 0) return;
    const moveEntry = skillTrainingCandidate(card, itemDef);
    if (!moveEntry) {
      addLog(`${cardDisplayName(card)} 目前沒有可用 ${itemDef.name} 補學的招式。`);
      if (!returnToTrainingDetailAfterMaterial(player, targetIndex, options)) openBackpackCrewTargetModal(player, itemDef.id, "skillTraining");
      return;
    }
    if (!consumeMapBackpackItem(player, itemDef.id)) return;
    const needsReplacement = (card.unlockedMoveIds || []).length >= MAX_ACTIVE_MOVES;
    if (!needsReplacement) {
      card.unlockedMoveIds = Array.from(new Set([...(card.unlockedMoveIds || []), moveEntry.id])).slice(0, MAX_ACTIVE_MOVES);
      addLog(`${cardDisplayName(card)} 研讀${itemDef.name}，學會了 ${moveEntry.name}。`);
    } else {
      addLog(`${cardDisplayName(card)} 研讀${itemDef.name}，可以學習 ${moveEntry.name}。`);
      queueMoveLearnChoice(player, card, moveEntry.id);
    }
    emitItemUseBoardEvent(player, itemDef, `${player.name} 讓 ${cardDisplayName(card)} 研讀${itemDef.name}。`, { cardName: cardDisplayName(card) });
    recordMissionEvent(player, { type: "use_item_category", category: "key", itemId: itemDef.id, itemName: itemDef.name });
    renderAll();
    if (needsReplacement) {
      closeModal();
      processNextPendingMoveLearn({ playerId: player.id, notify: true });
      return;
    }
    shared.showToast(`${cardDisplayName(card)} 學會了 ${moveEntry.name}。`);
    if (!returnToTrainingDetailAfterMaterial(player, targetIndex, options)) {
      openBackpackModal({ pocketId: "key", itemName: itemDef.name });
    }
  }

  function passiveItemTargetReason(itemDef, card) {
    const kind = itemDef?.effect?.kind || "";
    if (kind === "switch_unlocked_passive" && Number(card?.passiveMemoryLevel || 0) >= 3) return "戰鬥記憶已滿";
    return "";
  }

  function openBackpackPassiveQuantityModal(player, itemId, targetIndex, options = {}) {
    const itemDef = gameItemDef(itemId);
    const card = player?.crew?.[targetIndex];
    if (!player || !itemDef || !card) return;
    const kind = itemDef.effect?.kind || "";
    const available = backpackUsableItemCount(player, itemDef.id);
    const maxQuantity = kind === "switch_unlocked_passive"
      ? Math.max(0, Math.min(available, 3 - Number(card.passiveMemoryLevel || 0)))
      : Math.min(available, 1);
    if (maxQuantity <= 1) {
      applyPassiveItemToTarget(player, itemDef.id, targetIndex, 1, options);
      return;
    }
    let quantity = 1;
    openModal(`
      <section class="training-quantity-ui" aria-label="對 ${escapeModalText(cardDisplayName(card))} 使用 ${escapeModalText(itemDef.name)}">
        <img class="training-quantity-frame" src="images/board/training_ui/training_item_quantity_frame.webp" alt="" aria-hidden="true">
        <h3 class="training-quantity-title">使用數量</h3>
        <span class="training-quantity-icon"><img src="${escapeModalText(itemImageForDisplay(itemDef.id))}" alt="${escapeModalText(itemDef.name)}" onerror="this.hidden=true;"></span>
        <div class="training-quantity-item-line"><strong>${escapeModalText(itemDef.name)}</strong><span>持有 ${available} 個</span></div>
        <div class="training-quantity-target-line">${escapeModalText(cardDisplayName(card))} ・ 戰鬥記憶 ${Number(card.passiveMemoryLevel || 0)}/3</div>
        <button type="button" class="training-quantity-step" id="backpackPassiveQtyMinus" aria-label="減少使用數量">−</button>
        <strong class="training-quantity-value" id="backpackPassiveQtyValue">1</strong>
        <button type="button" class="training-quantity-step" id="backpackPassiveQtyPlus" aria-label="增加使用數量">＋</button>
        <div class="training-quantity-note"><span>最多有效 ${maxQuantity} 個</span><strong id="backpackPassiveQtyPreview">使用 1 個</strong></div>
        <button type="button" class="training-quantity-confirm" id="backpackPassiveQtyConfirm">確定使用</button>
        <button type="button" class="training-quantity-cancel" id="backpackPassiveQtyCancel">${options?.returnToTrainingDetail ? "返回修行詳情" : "返回選人"}</button>
      </section>
    `, "training-quantity-nautical-modal");
    const qtyValue = document.getElementById("backpackPassiveQtyValue");
    const qtyPreview = document.getElementById("backpackPassiveQtyPreview");
    const updateQuantity = () => {
      qtyValue.textContent = String(quantity);
      qtyPreview.textContent = `使用 ${quantity} 個`;
    };
    document.getElementById("backpackPassiveQtyMinus")?.addEventListener("click", () => {
      quantity = quantity <= 1 ? maxQuantity : Math.max(1, quantity - 1);
      updateQuantity();
    });
    document.getElementById("backpackPassiveQtyPlus")?.addEventListener("click", () => {
      quantity = Math.min(maxQuantity, quantity + 1);
      updateQuantity();
    });
    document.getElementById("backpackPassiveQtyConfirm")?.addEventListener("click", () => {
      applyPassiveItemToTarget(player, itemDef.id, targetIndex, quantity, options);
    });
    document.getElementById("backpackPassiveQtyCancel")?.addEventListener("click", () => {
      if (!returnToTrainingDetailAfterMaterial(player, targetIndex, options)) openBackpackCrewTargetModal(player, itemDef.id, "passiveTraining");
    });
  }

  function applyPassiveItemToTarget(player, itemId, targetIndex, quantity = 1, options = {}) {
    const itemDef = gameItemDef(itemId);
    const card = player?.crew?.[targetIndex];
    if (!player || !itemDef || !card || backpackUsableItemCount(player, itemDef.id) <= 0) return;
    const reason = passiveItemTargetReason(itemDef, card);
    if (reason) {
      addLog(`${cardDisplayName(card)} 目前不能使用 ${itemDef.name}：${reason}。`);
      if (!returnToTrainingDetailAfterMaterial(player, targetIndex, options)) openBackpackCrewTargetModal(player, itemDef.id, "passiveTraining");
      return;
    }
    const previousStats = { ...(card.baseStats || {}) };
    const kind = itemDef.effect?.kind || "";
    let used = 0;
    const requested = Math.max(1, Math.round(Number(quantity || 1)));
    for (let index = 0; index < requested; index += 1) {
      if (passiveItemTargetReason(itemDef, card)) break;
      if (!consumeMapBackpackItem(player, itemDef.id)) break;
      if (kind === "switch_unlocked_passive") {
        card.passiveMemoryLevel = Math.max(0, Math.min(3, Number(card.passiveMemoryLevel || 0) + 1));
      }
      used += 1;
    }
    if (used <= 0) return;
    const statGain = applyCardLevelStats(card, previousStats);
    recalcPlayerDerivedStats(player);
    const itemText = used > 1 ? `${itemDef.name} ×${used}` : itemDef.name;
    addLog(`${player.name} 對 ${cardDisplayName(card)} 使用${itemText}，戰鬥記憶提升到 ${card.passiveMemoryLevel}/3${statGainText(statGain) ? `，能力提升：${statGainText(statGain)}` : ""}。`);
    emitItemUseBoardEvent(player, itemDef, `${player.name} 對 ${cardDisplayName(card)} 使用${itemText}。`, { quantity: used, cardName: cardDisplayName(card) });
    recordMissionEvent(player, { type: "use_item_category", category: "key", itemId: itemDef.id, itemName: itemDef.name }, used);
    renderAll();
    if (!returnToTrainingDetailAfterMaterial(player, targetIndex, options)) openBackpackModal({ pocketId: "key", itemName: itemDef.name });
  }

  function resetTrainingTargetReason(card) {
    normalizeCardTraining(card);
    const total = TRAINING_STATS.reduce((sum, stat) => sum + Number(card.training?.[stat] || 0), 0)
      + Number(card.passiveMemoryLevel || 0);
    return total > 0 ? "" : "尚未修行";
  }

  function applyTrainingResetItemToTarget(player, itemId, targetIndex) {
    const itemDef = gameItemDef(itemId);
    const card = player?.crew?.[targetIndex];
    if (!player || !itemDef || !card || backpackUsableItemCount(player, itemDef.id) <= 0) return;
    const reason = resetTrainingTargetReason(card);
    if (reason) {
      addLog(`${cardDisplayName(card)} 目前不能使用 ${itemDef.name}：${reason}。`);
      openBackpackCrewTargetModal(player, itemDef.id, "resetTraining");
      return;
    }
    if (!consumeMapBackpackItem(player, itemDef.id)) return;
    normalizeCardTraining(card);
    const refundSource = TRAINING_STATS.reduce((sum, stat) => sum + Number(card.training?.[stat] || 0), 0);
    const refund = Math.max(0, Math.floor(refundSource * Number(itemDef.effect?.refundRate || 0.6)));
    const previousStats = { ...(card.baseStats || {}) };
    card.training = {};
    card.passiveMemoryLevel = 0;
    normalizeCardTraining(card);
    applyCardLevelStats(card, previousStats);
    if (refund > 0) grantFormalItemToPlayer(player, "training_dust", refund);
    recalcPlayerDerivedStats(player);
    addLog(`${player.name} 對 ${cardDisplayName(card)} 使用${itemDef.name}，修行已重置${refund > 0 ? `，返還修行細沙 x${refund}` : ""}。`);
    emitItemUseBoardEvent(player, itemDef, `${player.name} 對 ${cardDisplayName(card)} 使用${itemDef.name}。`, { cardName: cardDisplayName(card) });
    recordMissionEvent(player, { type: "use_item_category", category: "key", itemId: itemDef.id, itemName: itemDef.name });
    renderAll();
    openBackpackModal({ pocketId: "key", itemName: itemDef.name });
  }

  function useSmallSupplyFromBackpack(player) {
    ensurePlayerInventoryState(player);
    const count = Math.max(inventoryItemCount(player, "heal_2"), Number(player?.smallSupplies || 0));
    if (count <= 0) return;
    openBackpackCrewTargetModal(player, "heal_2", "heal");
  }

  const BACKPACK_HEALING_EFFECT_KINDS = new Set([
    "heal_hp",
    "heal_hp_percent",
    "heal_percent_and_cure_status",
    "heal_party_percent_battle",
    "heal_party_percent_outside_battle",
    "revive",
  ]);

  function isBackpackHealingItem(itemDef) {
    return BACKPACK_HEALING_EFFECT_KINDS.has(itemDef?.effect?.kind || "");
  }

  function backpackUsableItemCount(player, itemOrId) {
    const def = gameItemDef(itemOrId);
    if (!player || !def) return 0;
    let count = inventoryItemCount(player, def.id);
    if (def.id === "heal_2") count = Math.max(count, Number(player.smallSupplies || 0));
    if (def.id === "battle_food") count = Math.max(count, Number(player.battleFood || 0));
    if (def.id === "guard_charm") count = Math.max(count, Number(player.guardCharm || 0));
    return Math.max(0, Math.round(count));
  }

  function consumeMapBackpackItem(player, itemOrId) {
    const def = gameItemDef(itemOrId);
    if (!player || !def) return false;
    if (removeFormalItemFromPlayer(player, def.id, 1)) return true;
    if (def.id === "heal_2" && Number(player.smallSupplies || 0) > 0) {
      player.smallSupplies = Math.max(0, Number(player.smallSupplies || 0) - 1);
      return true;
    }
    if (def.id === "battle_food" && Number(player.battleFood || 0) > 0) {
      player.battleFood = Math.max(0, Number(player.battleFood || 0) - 1);
      return true;
    }
    if (def.id === "guard_charm" && Number(player.guardCharm || 0) > 0) {
      player.guardCharm = Math.max(0, Number(player.guardCharm || 0) - 1);
      return true;
    }
    return false;
  }

  function healActiveCrewAndShipPercent(player, ratio) {
    const percent = Math.max(0, Number(ratio || 0));
    let total = 0;
    if (player && Number(player.maxHp || 0) > 0 && Number(player.hp || 0) > 0) {
      const beforePlayerHp = Number(player.hp || 0);
      const heal = Math.max(1, Math.round(Number(player.maxHp || 1) * percent));
      player.hp = Math.min(Number(player.maxHp || beforePlayerHp), beforePlayerHp + heal);
      total += player.hp - beforePlayerHp;
    }
    const current = activeCrew(player);
    const card = current && Number(current.currentHp || 0) > 0
      ? current
      : (player?.crew || []).find((entry) => Number(entry.currentHp || 0) > 0);
    if (card && Number(card.currentHp || 0) > 0) {
      const maxHp = cardMaxHp(card);
      const before = Number(card.currentHp || 0);
      const heal = Math.max(1, Math.round(maxHp * percent));
      card.currentHp = Math.min(maxHp, before + heal);
      total += card.currentHp - before;
    }
    return total;
  }

  function healCrewCardFlat(card, amount) {
    if (!card || Number(card.currentHp || 0) <= 0) return 0;
    const maxHp = cardMaxHp(card);
    const before = Math.max(0, Number(card.currentHp || 0));
    card.currentHp = Math.min(maxHp, before + Math.max(1, Math.round(Number(amount || 0))));
    return Math.max(0, Math.round(card.currentHp - before));
  }

  function healCrewCardPercent(card, percent) {
    if (!card || Number(card.currentHp || 0) <= 0) return 0;
    const maxHp = cardMaxHp(card);
    return healCrewCardFlat(card, Math.max(1, Math.round(maxHp * Math.max(0, Number(percent || 0)))));
  }

  function reviveCrewCardWithItem(card, percent) {
    if (!card || Number(card.currentHp || 0) > 0) return 0;
    const maxHp = cardMaxHp(card);
    card.currentHp = Math.max(1, Math.round(maxHp * Math.max(0.01, Number(percent || 0.3))));
    return card.currentHp;
  }

  function backpackTargetStatusLabel(card) {
    return `Lv.${card.level || 1} ・ HP ${Math.max(0, Math.round(Number(card.currentHp || 0)))}/${cardMaxHp(card)}`;
  }

  function canUseHealingItemOnCard(itemDef, card) {
    const kind = itemDef?.effect?.kind || "";
    const currentHp = Number(card?.currentHp || 0);
    const maxHp = cardMaxHp(card);
    if (kind === "revive") return currentHp <= 0;
    return currentHp > 0 && currentHp < maxHp;
  }

  function healingItemTargetReason(itemDef, card) {
    const kind = itemDef?.effect?.kind || "";
    const currentHp = Number(card?.currentHp || 0);
    const maxHp = cardMaxHp(card);
    if (kind === "revive") return currentHp <= 0 ? "" : "只有瀕死角色可以復活";
    if (currentHp <= 0) return "瀕死角色需要復活道具";
    if (currentHp >= maxHp) return "HP 已滿";
    return "";
  }

  function backpackHealingUnitAmount(player, itemDef, card) {
    const effect = itemDef?.effect || {};
    const maxHp = cardMaxHp(card);
    if (effect.kind === "heal_hp") {
      const bonus = itemDef.id === "heal_2" ? Number(getTeamEffects(player).healItemBonus || 0) : 0;
      return Math.max(1, Math.round(Number(effect.amount || 0) + bonus));
    }
    if (["heal_hp_percent", "heal_party_percent_battle", "heal_party_percent_outside_battle", "heal_percent_and_cure_status"].includes(effect.kind)) {
      return Math.max(1, Math.round(maxHp * Number(effect.percent || 0.25)));
    }
    if (effect.kind === "revive") {
      return Math.max(1, Math.round(maxHp * Math.max(0.01, Number(effect.hpPercent || 0.3))));
    }
    return 0;
  }

  function maxBackpackHealingQuantity(player, itemDef, card) {
    const available = backpackUsableItemCount(player, itemDef?.id);
    if (!itemDef || !card || available <= 0 || !canUseHealingItemOnCard(itemDef, card)) return 0;
    const effect = itemDef.effect || {};
    if (effect.kind === "revive") return Math.min(available, 1);
    const unit = backpackHealingUnitAmount(player, itemDef, card);
    const missing = cardMaxHp(card) - Math.max(0, Number(card.currentHp || 0));
    if (unit <= 0 || missing <= 0) return 0;
    return Math.max(1, Math.min(available, Math.ceil(missing / unit)));
  }

  function estimateBackpackHealingForQuantity(player, itemDef, card, quantity) {
    const effect = itemDef?.effect || {};
    const maxHp = cardMaxHp(card);
    const unit = backpackHealingUnitAmount(player, itemDef, card);
    let hp = Math.max(0, Number(card?.currentHp || 0));
    let total = 0;
    const count = Math.max(1, Math.round(Number(quantity || 1)));
    for (let index = 0; index < count; index += 1) {
      if (effect.kind === "revive") {
        if (hp > 0) break;
        const revived = Math.min(maxHp, unit);
        total += revived;
        hp = revived;
        break;
      }
      if (hp <= 0 || hp >= maxHp || unit <= 0) break;
      const healed = Math.max(0, Math.min(maxHp, hp + unit) - hp);
      if (healed <= 0) break;
      total += healed;
      hp += healed;
    }
    return Math.max(0, Math.round(total));
  }

  function openBackpackHealingQuantityModal(player, itemId, targetIndex) {
    const itemDef = gameItemDef(itemId);
    const card = player?.crew?.[targetIndex];
    if (!player || !itemDef || !card) return;
    const maxQuantity = maxBackpackHealingQuantity(player, itemDef, card);
    if (maxQuantity <= 1) {
      applyBackpackHealingToTarget(player, itemDef.id, targetIndex, 1);
      return;
    }
    const available = backpackUsableItemCount(player, itemDef.id);
    const targetName = cardDisplayName(card);
    const effect = itemDef.effect || {};
    const actionLabel = effect.kind === "revive" ? "復活回復" : "預計回復";
    let quantity = 1;
    openModal(`
      <section class="healing-quantity-ui" aria-label="對 ${escapeModalText(targetName)} 使用 ${escapeModalText(itemDef.name)}">
        <img class="healing-quantity-frame" src="images/board/healing_quantity_ui/healing_item_quantity_frame.webp" alt="" aria-hidden="true">
        <h3 class="healing-quantity-title">使用數量</h3>
        <span class="healing-quantity-icon"><img src="${escapeModalText(itemImageForDisplay(itemDef.id))}" alt="${escapeModalText(itemDef.name)}" onerror="this.hidden=true;"></span>
        <div class="healing-quantity-item-line"><strong>${escapeModalText(itemDef.name)}</strong><span>持有 ${available} 個</span></div>
        <div class="healing-quantity-target-line"><strong>${escapeModalText(targetName)}</strong><span>HP ${Math.max(0, Math.round(Number(card.currentHp || 0)))}/${cardMaxHp(card)}</span></div>
        <button type="button" class="healing-quantity-step" id="backpackHealQtyMinus" aria-label="減少使用數量">−</button>
        <strong class="healing-quantity-value" id="backpackHealQtyValue" aria-live="polite">1</strong>
        <button type="button" class="healing-quantity-step" id="backpackHealQtyPlus" aria-label="增加使用數量">＋</button>
        <div class="healing-quantity-note"><span>最多有效 ${maxQuantity} 個</span><strong id="backpackHealQtyPreview">${actionLabel} ${estimateBackpackHealingForQuantity(player, itemDef, card, 1)} HP</strong></div>
        <button type="button" class="healing-quantity-confirm" id="backpackHealQtyConfirm">確定使用</button>
        <button type="button" class="healing-quantity-cancel" id="backpackHealQtyCancel">返回選人</button>
      </section>
    `, "healing-quantity-nautical-modal");
    const qtyValue = document.getElementById("backpackHealQtyValue");
    const qtyPreview = document.getElementById("backpackHealQtyPreview");
    const updateQuantity = () => {
      qtyValue.textContent = String(quantity);
      qtyPreview.textContent = `${actionLabel} ${estimateBackpackHealingForQuantity(player, itemDef, card, quantity)} HP`;
    };
    document.getElementById("backpackHealQtyMinus")?.addEventListener("click", () => {
      quantity = quantity <= 1 ? maxQuantity : Math.max(1, quantity - 1);
      updateQuantity();
    });
    document.getElementById("backpackHealQtyPlus")?.addEventListener("click", () => {
      quantity = Math.min(maxQuantity, quantity + 1);
      updateQuantity();
    });
    document.getElementById("backpackHealQtyConfirm")?.addEventListener("click", () => {
      applyBackpackHealingToTarget(player, itemDef.id, targetIndex, quantity);
    });
    document.getElementById("backpackHealQtyCancel")?.addEventListener("click", () => {
      openBackpackCrewTargetModal(player, itemDef.id, "heal");
    });
  }

  function applyBackpackHealingToTarget(player, itemId, targetIndex, quantity = 1) {
    const itemDef = gameItemDef(itemId);
    const card = player?.crew?.[targetIndex];
    if (!player || !itemDef || !card || backpackUsableItemCount(player, itemDef.id) <= 0) return;
    if (!canUseHealingItemOnCard(itemDef, card)) {
      addLog(`${cardDisplayName(card)} 目前不能使用 ${itemDef.name}。`);
      openBackpackCrewTargetModal(player, itemDef.id, "heal");
      return;
    }
    const effect = itemDef.effect || {};
    const supportedKinds = new Set(["heal_hp", "heal_hp_percent", "heal_party_percent_battle", "heal_party_percent_outside_battle", "heal_percent_and_cure_status", "revive"]);
    if (!supportedKinds.has(effect.kind)) {
      addLog(`${itemDef.name}不是可指定船員的治癒道具。`);
      openBackpackModal({ pocketId: normalizeGameItemCategory(itemDef.category), itemName: itemDef.name });
      return;
    }
    const requested = Math.max(1, Math.round(Number(quantity || 1)));
    let used = 0;
    let amount = 0;
    for (let index = 0; index < requested; index += 1) {
      if (!canUseHealingItemOnCard(itemDef, card)) break;
      if (!consumeMapBackpackItem(player, itemDef.id)) break;
      let healed = 0;
      if (effect.kind === "heal_hp") {
        healed = healCrewCardFlat(card, backpackHealingUnitAmount(player, itemDef, card));
      } else if (["heal_hp_percent", "heal_party_percent_battle", "heal_party_percent_outside_battle", "heal_percent_and_cure_status"].includes(effect.kind)) {
        healed = healCrewCardPercent(card, Number(effect.percent || 0.25));
        if (effect.kind === "heal_percent_and_cure_status") {
          card.statusEffects = emptyStatusEffects();
        }
      } else if (effect.kind === "revive") {
        healed = reviveCrewCardWithItem(card, Number(effect.hpPercent || 0.3));
      }
      if (healed <= 0) break;
      used += 1;
      amount += healed;
    }
    if (amount <= 0 || used <= 0) {
      addLog(`${itemDef.name}沒有產生效果。`);
      openBackpackCrewTargetModal(player, itemDef.id, "heal");
      return;
    }
    const actionText = effect.kind === "revive" ? "復活並回復" : "回復";
    const itemText = used > 1 ? `${itemDef.name} ×${used}` : itemDef.name;
    addLog(`${player.name} 對 ${cardDisplayName(card)} 使用${itemText}，${actionText} ${amount} HP。`);
    emitItemUseBoardEvent(player, itemDef, `${player.name} 對 ${cardDisplayName(card)} 使用${itemText}。`, { quantity: used, cardName: cardDisplayName(card) });
    recordMissionEvent(player, { type: "use_item_category", category: normalizeGameItemCategory(itemDef.category), itemId: itemDef.id, itemName: itemDef.name }, used);
    recordMissionEvent(player, { type: "use_heal_item", category: normalizeGameItemCategory(itemDef.category), itemId: itemDef.id, itemName: itemDef.name }, used);
    recalcPlayerDerivedStats(player);
    renderAll();
    openBackpackModal({ pocketId: "battle", itemName: itemDef.name });
  }

  function openBackpackCrewTargetModal(player, itemId, mode = "heal") {
    const itemDef = gameItemDef(itemId);
    if (!player || !itemDef) return;
    const title = {
      evolution: `要把 ${itemDef.name} 給誰？`,
      training: `要讓誰使用 ${itemDef.name} 修行？`,
      skillTraining: `要讓誰研讀 ${itemDef.name}？`,
      passiveTraining: `要讓誰使用 ${itemDef.name}？`,
      resetTraining: `要重置誰的修行？`,
    }[mode] || `要對誰使用 ${itemDef.name}？`;
    const availableCount = backpackUsableItemCount(player, itemDef.id);
    const itemImage = itemDef.image || itemImageForDisplay(itemDef);
    const itemDescription = keyItemDetailText(itemDef)?.trim() || itemDef.description || itemDef.uiSummary || "選擇一名船員使用這項道具。";
    openModal(`
      <section class="backpack-target-ui" aria-label="${escapeModalText(title)}">
      <img class="backpack-target-panel-frame" src="images/board/backpack_target_ui/backpack_target_panel_frame.webp" alt="" aria-hidden="true">
      <header class="backpack-target-heading">
        <h3>${escapeModalText(title)}</h3>
        <p>選擇這次要使用道具的船員</p>
      </header>
      <div class="backpack-target-item-stage">
        <img src="${escapeModalText(itemImage)}" alt="${escapeModalText(itemDef.name)}" loading="eager" onerror="this.remove();this.parentElement.classList.add('fallback');">
        <span><img src="${escapeModalText(itemFallbackIconPath(itemDef))}" alt="" aria-hidden="true"></span>
      </div>
      <div class="backpack-target-item-name">
        <strong>${escapeModalText(itemDef.name)}*${availableCount}</strong>
      </div>
      <div class="backpack-target-item-info">${escapeModalText(itemDescription)}</div>
      <div class="companion-grid backpack-target-grid">
        ${(player.crew || []).map((card, index) => {
          syncCrewCardProgress(card);
          const portraits = cardPortraitsForDisplay(card);
          const fallbackInitial = String(cardDisplayName(card) || "?").slice(0, 1);
          if (mode === "training") {
            const reason = trainingItemTargetReason(itemDef, card);
            const ok = !reason;
            return `
              <article class="companion-card">
                <div class="companion-tier">${tierLabel(card.tier)} ・ ${card.attribute}</div>
                <div class="crew-target-row">
                  <span class="crew-manage-avatar">
                    <img src="${escapeModalText(portraits.normal)}" alt="${escapeModalText(cardDisplayName(card))}" loading="lazy" data-fallback-src="${escapeModalText(portraits.idle || portraits.normal)}" onerror="if(this.dataset.fallbackSrc){this.src=this.dataset.fallbackSrc;this.dataset.fallbackSrc='';}else{this.remove();this.parentElement.classList.add('fallback');}">
                    <span>${escapeModalText(fallbackInitial)}</span>
                  </span>
                  <span>
                    <div class="companion-name">${escapeModalText(cardDisplayName(card))}</div>
                    <div class="companion-meta"><span>${escapeModalText(backpackTargetStatusLabel(card))}</span><span>修行：${escapeModalText(trainingSummary(card))}${ok ? "" : ` ・ <strong>${escapeModalText(reason)}</strong>`}</span></div>
                  </span>
                </div>
                <button type="button" class="modal-btn ${ok ? "primary" : "secondary"}" data-backpack-training-target="${index}" ${ok ? "" : "disabled"}>修行</button>
              </article>
            `;
          }
          if (mode === "skillTraining") {
            const moveEntry = skillTrainingCandidate(card, itemDef);
            const ok = !!moveEntry;
            return `
              <article class="companion-card">
                <div class="companion-tier">${tierLabel(card.tier)} ・ ${card.attribute}</div>
                <div class="crew-target-row">
                  <span class="crew-manage-avatar">
                    <img src="${escapeModalText(portraits.normal)}" alt="${escapeModalText(cardDisplayName(card))}" loading="lazy" data-fallback-src="${escapeModalText(portraits.idle || portraits.normal)}" onerror="if(this.dataset.fallbackSrc){this.src=this.dataset.fallbackSrc;this.dataset.fallbackSrc='';}else{this.remove();this.parentElement.classList.add('fallback');}">
                    <span>${escapeModalText(fallbackInitial)}</span>
                  </span>
                  <span>
                    <div class="companion-name">${escapeModalText(cardDisplayName(card))}</div>
                    <div class="companion-meta"><span>${escapeModalText(backpackTargetStatusLabel(card))}</span><span>${ok ? `可補學：${escapeModalText(moveEntry.name)}（Lv.${effectiveMoveUnlockLevel(moveEntry)}）` : "目前沒有可補學招式"}</span></div>
                  </span>
                </div>
                <button type="button" class="modal-btn ${ok ? "primary" : "secondary"}" data-backpack-skill-training-target="${index}" ${ok ? "" : "disabled"}>研讀</button>
              </article>
            `;
          }
          if (mode === "passiveTraining") {
            const reason = passiveItemTargetReason(itemDef, card);
            const ok = !reason;
            return `
              <article class="companion-card">
                <div class="companion-tier">${tierLabel(card.tier)} ・ ${card.attribute}</div>
                <div class="crew-target-row">
                  <span class="crew-manage-avatar">
                    <img src="${escapeModalText(portraits.normal)}" alt="${escapeModalText(cardDisplayName(card))}" loading="lazy" data-fallback-src="${escapeModalText(portraits.idle || portraits.normal)}" onerror="if(this.dataset.fallbackSrc){this.src=this.dataset.fallbackSrc;this.dataset.fallbackSrc='';}else{this.remove();this.parentElement.classList.add('fallback');}">
                    <span>${escapeModalText(fallbackInitial)}</span>
                  </span>
                  <span>
                    <div class="companion-name">${escapeModalText(cardDisplayName(card))}</div>
                    <div class="companion-meta"><span>${escapeModalText(backpackTargetStatusLabel(card))}</span><span>戰鬥記憶：${Number(card.passiveMemoryLevel || 0)}/3${ok ? "" : ` ・ <strong>${escapeModalText(reason)}</strong>`}</span></div>
                  </span>
                </div>
                <button type="button" class="modal-btn ${ok ? "primary" : "secondary"}" data-backpack-passive-target="${index}" ${ok ? "" : "disabled"}>使用</button>
              </article>
            `;
          }
          if (mode === "resetTraining") {
            const reason = resetTrainingTargetReason(card);
            const ok = !reason;
            return `
              <article class="companion-card">
                <div class="companion-tier">${tierLabel(card.tier)} ・ ${card.attribute}</div>
                <div class="crew-target-row">
                  <span class="crew-manage-avatar">
                    <img src="${escapeModalText(portraits.normal)}" alt="${escapeModalText(cardDisplayName(card))}" loading="lazy" data-fallback-src="${escapeModalText(portraits.idle || portraits.normal)}" onerror="if(this.dataset.fallbackSrc){this.src=this.dataset.fallbackSrc;this.dataset.fallbackSrc='';}else{this.remove();this.parentElement.classList.add('fallback');}">
                    <span>${escapeModalText(fallbackInitial)}</span>
                  </span>
                  <span>
                    <div class="companion-name">${escapeModalText(cardDisplayName(card))}</div>
                    <div class="companion-meta"><span>${escapeModalText(backpackTargetStatusLabel(card))}</span><span>修行：${escapeModalText(trainingSummary(card))}${ok ? "" : ` ・ <strong>${escapeModalText(reason)}</strong>`}</span></div>
                  </span>
                </div>
                <button type="button" class="modal-btn ${ok ? "danger" : "secondary"}" data-backpack-training-reset-target="${index}" ${ok ? "" : "disabled"}>重置</button>
              </article>
            `;
          }
          if (mode === "evolution") {
            const form = nextEvolutionFormForCard(card);
            const status = form ? evolutionRequirementStatus(player, card, form) : { ok: false, reasons: ["尚無進化"] };
            const usesThisItem = form && evolutionMaterialCosts(form).some((cost) => cost.itemId === itemDef.id);
            const ok = !!form && usesThisItem && status.ok;
            const reason = !form ? "尚無進化" : !usesThisItem ? `不使用${itemDef.name}` : status.reasons.join("、");
            return `
              <article class="companion-card">
                <div class="companion-tier">${tierLabel(card.tier)} ・ ${card.attribute}</div>
                <div class="crew-target-row">
                  <span class="crew-manage-avatar">
                    <img src="${escapeModalText(portraits.normal)}" alt="${escapeModalText(cardDisplayName(card))}" loading="lazy" data-fallback-src="${escapeModalText(portraits.idle || portraits.normal)}" onerror="if(this.dataset.fallbackSrc){this.src=this.dataset.fallbackSrc;this.dataset.fallbackSrc='';}else{this.remove();this.parentElement.classList.add('fallback');}">
                    <span>${escapeModalText(fallbackInitial)}</span>
                  </span>
                  <span>
                    <div class="companion-name">${escapeModalText(cardDisplayName(card))}</div>
                    <div class="companion-meta"><span>${escapeModalText(backpackTargetStatusLabel(card))}</span><span>${form ? `可進化：${escapeModalText(form.name)}` : "尚無可進化形態"}${ok ? "" : ` ・ <strong>${escapeModalText(reason || "條件不足")}</strong>`}</span></div>
                  </span>
                </div>
                <button type="button" class="modal-btn ${ok ? "primary" : "secondary"}" data-backpack-evolve-target="${index}" ${ok ? "" : "disabled"}>${form ? `進化為 ${escapeModalText(form.name)}` : "不能進化"}</button>
              </article>
            `;
          }
          const ok = canUseHealingItemOnCard(itemDef, card);
          const reason = healingItemTargetReason(itemDef, card);
          return `
            <article class="companion-card">
              <div class="companion-tier">${tierLabel(card.tier)} ・ ${card.attribute}</div>
              <div class="crew-target-row">
                <span class="crew-manage-avatar">
                  <img src="${escapeModalText(portraits.normal)}" alt="${escapeModalText(cardDisplayName(card))}" loading="lazy" data-fallback-src="${escapeModalText(portraits.idle || portraits.normal)}" onerror="if(this.dataset.fallbackSrc){this.src=this.dataset.fallbackSrc;this.dataset.fallbackSrc='';}else{this.remove();this.parentElement.classList.add('fallback');}">
                  <span>${escapeModalText(fallbackInitial)}</span>
                </span>
                <span>
                  <div class="companion-name">${escapeModalText(cardDisplayName(card))}</div>
                  <div class="companion-meta"><span>${escapeModalText(backpackTargetStatusLabel(card))}</span><span>${ok ? "可使用" : `<strong>${escapeModalText(reason)}</strong>`}</span></div>
                </span>
              </div>
              <button type="button" class="modal-btn ${ok ? "primary" : "secondary"}" data-backpack-heal-target="${index}" ${ok ? "" : "disabled"}>使用</button>
            </article>
          `;
        }).join("")}
      </div>
      <div class="backpack-target-hint">
        <strong>請選擇一名船員</strong>
        <span>不可使用的角色會顯示原因，點擊可用角色右下方按鈕繼續。</span>
      </div>
      <button type="button" class="backpack-target-cancel" id="backToBackpackFromTargetBtn">返回背包</button>
      </section>
    `, "backpack-target-modal backpack-target-nautical-modal no-backdrop-close");
    refs.modal.querySelectorAll("[data-backpack-heal-target]").forEach((button) => {
      button.addEventListener("click", () => openBackpackHealingQuantityModal(player, itemDef.id, Number(button.dataset.backpackHealTarget)));
    });
    refs.modal.querySelectorAll("[data-backpack-evolve-target]").forEach((button) => {
      button.addEventListener("click", () => evolveCrewCard(player, Number(button.dataset.backpackEvolveTarget), { returnToBackpack: false }));
    });
    refs.modal.querySelectorAll("[data-backpack-training-target]").forEach((button) => {
      button.addEventListener("click", () => openBackpackTrainingQuantityModal(player, itemDef.id, Number(button.dataset.backpackTrainingTarget)));
    });
    refs.modal.querySelectorAll("[data-backpack-skill-training-target]").forEach((button) => {
      button.addEventListener("click", () => applySkillTrainingItemToTarget(player, itemDef.id, Number(button.dataset.backpackSkillTrainingTarget)));
    });
    refs.modal.querySelectorAll("[data-backpack-passive-target]").forEach((button) => {
      button.addEventListener("click", () => openBackpackPassiveQuantityModal(player, itemDef.id, Number(button.dataset.backpackPassiveTarget)));
    });
    refs.modal.querySelectorAll("[data-backpack-training-reset-target]").forEach((button) => {
      button.addEventListener("click", () => applyTrainingResetItemToTarget(player, itemDef.id, Number(button.dataset.backpackTrainingResetTarget)));
    });
    document.getElementById("backToBackpackFromTargetBtn")?.addEventListener("click", () => {
      openBackpackModal({ pocketId: normalizeGameItemCategory(itemDef.category), itemName: itemDef.name });
    });
  }

  function importantBackpackItemInfo(name) {
    const defs = {
      "被打穿的旗幟": {
        meta: "Lv.20 草帽團進化用，使用後消耗。",
        badge: "旗",
        action: "select_evolution_target:pierced_flag",
      },
    };
    return defs[name] || null;
  }

  function lineageExtractorBackpackItems(player) {
    return RESEARCH_LAB_EXTRACTOR_DEFS.map((config) => {
      const item = gameItemDef(config.id);
      const count = inventoryItemCount(player, config.id);
      if (!item || count <= 0) return null;
      return createBackpackItem({
        pocket: "key",
        itemId: item.id,
        name: item.name,
        count,
        tier: `重要道具 ・ ${item.rarity}`,
        meta: backpackItemShortMeta(item, "key"),
        badge: "取",
        image: item.image || "",
      });
    }).filter(Boolean);
  }

  function lineageFactorBackpackItems(player) {
    const groups = new Map();
    ensurePlayerResearchLabState(player).completeFactors.forEach((factor) => {
      const view = lineageFactorViewData(factor);
      if (!view) return;
      const groupKey = String(view.enemyKey || view.sourceCardId || view.name || factor.id);
      const entry = groups.get(groupKey) || {
        name: view.name,
        count: 0,
        rank: view.rank,
        tier: view.tier,
        image: view.portrait || view.characterImage || "",
        extractorNames: new Set(),
        canCultivate: false,
      };
      entry.count += 1;
      entry.canCultivate ||= Boolean(view.canCultivate);
      if (view.extractorName) entry.extractorNames.add(view.extractorName);
      groups.set(groupKey, entry);
    });
    return Array.from(groups.values())
      .sort((a, b) => a.name.localeCompare(b.name, "zh-Hant"))
      .map((entry) => {
        const sourceText = Array.from(entry.extractorNames)
          .map((name) => String(name).replace("血統因子", ""))
          .join("、") || "抽取器";
        const gradeText = Array.from(new Set([entry.rank, entry.tier].filter(Boolean))).join("／");
        const useText = entry.canCultivate
          ? "可於研究所培育、同角色突破或解析研究點數"
          : "模板尚未開放，因子會保留";
        return createBackpackItem({
          pocket: "key",
          name: `${entry.name}・完整血統因子`,
          count: entry.count,
          tier: `${gradeText || "完整"} ・ 重要道具`,
          meta: `${useText}；不可在背包消耗或交易。來源：${sourceText}。`,
          badge: "因",
          image: entry.image,
          kind: "lineage-factor",
          frameImage: LINEAGE_FACTOR_BACKPACK_FRAME_IMAGE,
          portraitImage: entry.image,
        });
      });
  }

  function buildBackpackPockets(player) {
    ensurePlayerInventoryState(player);
    const inventory = player.inventory?.items || {};
    const fixedStepTokens = Math.max(Number(player.fixedStepTokens || 0), inventoryItemCount(player, "fixed_step"));
    const routeInsight = Math.max(Number(player.routeInsight || 0), inventoryItemCount(player, "pointer"));
    const smallPointer = Number(player.smallPointer || 0);
    const rerollTickets = Number(player.rerollTickets || 0);
    const smallSupplies = Math.max(Number(player.smallSupplies || 0), inventoryItemCount(player, "heal_2"));
    const battleFood = Math.max(Number(player.battleFood || 0), inventoryItemCount(player, "battle_food"));
    const guardCharm = Math.max(Number(player.guardCharm || 0), inventoryItemCount(player, "guard_charm"));
    const roadPoneglyphs = Array.isArray(player.roadPoneglyphs) ? player.roadPoneglyphs : [];
    const carryGroups = groupedBattleCarryBackpackItems(player);
    const regularGroups = groupedRegularBackpackItems(player);
    const postgameClueSummary = postgameClueCollectionSummary(player);
    const manuallyRenderedItemIds = new Set(["heal_2", "fixed_step", "pointer", "battle_food", "guard_charm", "road_poneglyph", ...ROAD_PONEGLYPH_ITEM_IDS, ...YORK_DECODER_ITEM_IDS]);
    const formalItemsByCategory = { navigation: [], battle: [], ship: [], key: [] };
    Object.entries(inventory).forEach(([itemId, count]) => {
      const def = gameItemDef(itemId);
      const quantity = Math.max(0, Math.round(Number(count || 0)));
      if (!def || quantity <= 0 || manuallyRenderedItemIds.has(def.id) || LINEAGE_EXTRACTOR_IDS.has(def.id)) return;
      const category = normalizeGameItemCategory(def.category);
      if (category === "held") return;
      const label = ITEM_CATEGORY_LABELS[category] || "道具";
      const action = category === "key"
        ? keyBackpackAction(def)
        : isBackpackHealingItem(def)
          ? `select_heal_target:${def.id}`
          : ((category === "navigation" && (def.useTiming || []).some((timing) => ["before_move", "after_move", "before_island_event"].includes(timing))) || (category === "battle" && def.usableOnMap))
            ? `use_map_item:${def.id}`
            : "";
      const clueBossDef = def.effect?.kind === "postgame_york_clue"
        ? postgameBossDef(def.effect.bossKey)
        : null;
      const clueNumber = Math.max(0, Number(def.effect?.clueNumber || clueBossDef?.clueNumber || 0));
      const isPostgameClue = Boolean(clueBossDef && clueNumber);
      formalItemsByCategory[category]?.push(createBackpackItem({
        pocket: category,
        itemId: def.id,
        name: def.name,
        count: quantity,
        tier: isPostgameClue ? `線索牌 ${postgameClueCardLabel(clueNumber)} ・ S` : `${label} ・ ${def.rarity}`,
        meta: isPostgameClue
          ? `${clueBossDef.name} 的據點線索；可重複取得與交易。目前持有 ${postgameClueSummary.unique}/13 種、合計 ${postgameClueSummary.total} 張。`
          : backpackItemShortMeta(def, category),
        badge: isPostgameClue ? postgameClueCardLabel(clueNumber) : def.name.slice(0, 1),
        image: def.image || "",
        kind: isPostgameClue ? "postgame-clue" : "",
        frameImage: isPostgameClue ? def.image || "" : "",
        portraitImage: isPostgameClue ? clueBossDef.islandImage || ISLAND_IMAGE_MAP.postgame_boss : "",
        action,
      }));
    });
    const navigationItems = [
      fixedStepTokens > 0 ? createBackpackItem({
        pocket: "navigation",
        name: "指定步數券",
        count: fixedStepTokens,
        tier: "航海道具",
        meta: "指定本回合 1～6 步。",
        badge: "券",
        action: "fixed_step",
      }) : null,
      routeInsight > 0 ? createBackpackItem({
        pocket: "navigation",
        name: "航海指針",
        count: routeInsight,
        tier: "航海道具",
        meta: "選路時顯示更多路線資訊。",
        badge: "針",
      }) : null,
      smallPointer > 0 ? createBackpackItem({
        pocket: "navigation",
        name: "小型指針",
        count: smallPointer,
        tier: "航海道具",
        meta: "保留中的航海道具。",
        badge: "小",
      }) : null,
      rerollTickets > 0 ? createBackpackItem({
        pocket: "navigation",
        name: "重骰券",
        count: rerollTickets,
        tier: "航海道具",
        meta: "保留中的航海道具。",
        badge: "骰",
      }) : null,
      ...formalItemsByCategory.navigation,
    ].filter(Boolean);
    const battleItems = [
      smallSupplies > 0 ? createBackpackItem({
        pocket: "battle",
        name: "小補給",
        count: smallSupplies,
        tier: "戰鬥道具",
        meta: "選 1 名船員，回復 25 HP。",
        badge: "補",
        action: "small_supply",
      }) : null,
      battleFood > 0 ? createBackpackItem({
        pocket: "battle",
        name: "戰鬥糧食",
        count: battleFood,
        tier: "戰鬥道具",
        meta: "選 1 名船員，回復 40% 最大 HP。",
        badge: "食",
        action: "select_heal_target:battle_food",
      }) : null,
      guardCharm > 0 ? createBackpackItem({
        pocket: "battle",
        name: "防具 / 守護護符",
        count: guardCharm,
        tier: "戰鬥道具",
        meta: "戰鬥中使用，本回合減傷。",
        badge: "護",
      }) : null,
      ...formalItemsByCategory.battle,
    ].filter(Boolean);
    const shipItems = [
      ...formalItemsByCategory.ship,
    ].filter(Boolean);
    const carryItems = carryGroups.map(({ def, count }) => createBackpackItem({
      pocket: "held",
      itemId: def.id,
      name: def.name,
      count,
      tier: `${def.rarity} ・ ${def.category}`,
      meta: backpackCarryShortMeta(def),
      badge: def.name.slice(0, 1),
      image: def.image || battleCarryItemImage(def),
      action: "crew",
    }));
    const importantRegularItems = regularGroups.map(({ name, count }) => {
      const info = importantBackpackItemInfo(name);
      return info ? createBackpackItem({
        pocket: "key",
        name,
        count,
        tier: "重要道具",
        meta: info.meta,
        badge: info.badge,
        action: info.action || "",
      }) : null;
    }).filter(Boolean);
    const postgameWorld = normalizePostgameWorldState();
    const yorkDecoderTier = normalizePlayerYorkDecoderState(player);
    const yorkDecoderDef = yorkDecoderTier > 0 ? gameItemDef(YORK_DECODER_ITEM_IDS[yorkDecoderTier - 1]) : null;
    const yorkTrackingItems = postgameClueSummary.unique === POSTGAME_BOSS_DEFS.length || yorkDecoderTier > 0 || postgameWorld.eggheadUnlocked
      ? [createBackpackItem({
          pocket: "key",
          itemId: yorkDecoderDef?.id || "",
          name: yorkDecoderDef?.name || (postgameWorld.eggheadUnlocked ? "蛋頭島追蹤座標" : "約克追蹤座標"),
          count: 1,
          tier: yorkDecoderDef
            ? `個人解碼器 T${yorkDecoderTier} ・ 日蝕 ${Math.round(yorkDecoderDropRate(yorkDecoderTier) * 100)}%`
            : (postgameWorld.eggheadUnlocked ? "終局座標 ・ 全房已揭露" : "線索牌 A～K ・ 13/13"),
          meta: yorkDecoderTier >= 3
            ? "已達三階；仍可反覆遊玩每次更新的十三張牌題目，但不再獲得道具、掉落率或其他加成。"
            : postgameClueSummary.unique === POSTGAME_BOSS_DEFS.length
              ? `${postgameWorld.eggheadUnlocked ? "蛋頭島已顯現；" : ""}可挑戰尚未完成的更高難度，提升個人名刀『日蝕』掉落率。`
              : "移動蛋頭島已顯現在世界地圖；尚未集齊十三種線索，個人名刀掉落率仍為 0%。",
          badge: yorkDecoderTier > 0 ? `T${yorkDecoderTier}` : (postgameWorld.eggheadUnlocked ? "終" : "追"),
          image: yorkDecoderDef?.image || ISLAND_IMAGE_MAP.postgame_egghead,
          action: canActivateYorkTracking(player) ? "activate_york_tracking" : "",
        })]
      : [];
    const keyItems = [
      ...yorkTrackingItems,
      ...lineageExtractorBackpackItems(player),
      ...lineageFactorBackpackItems(player),
      ...roadPoneglyphBackpackItems(player),
      ...importantRegularItems,
      ...formalItemsByCategory.key,
    ].filter(Boolean);
    return [
      { id: "navigation", title: "航海道具", badge: "航", empty: "這個分類目前沒有航海道具。", items: navigationItems },
      { id: "battle", title: "戰鬥道具", badge: "戰", empty: "這個分類目前沒有戰鬥道具。", items: battleItems },
      { id: "ship", title: "船隻道具", badge: "船", empty: "這個分類目前沒有船隻道具或船材。", items: shipItems },
      { id: "held", title: "角色攜帶物", badge: "攜", empty: "這個分類目前沒有未裝備的角色攜帶物。", items: carryItems },
      { id: "key", title: "重要道具", badge: "重", empty: "這個分類目前沒有重要道具。", items: keyItems },
    ];
  }

  function renderBackpackPocketRows(pocket) {
    if (!pocket?.items?.length) {
      return `<div class="backpack-empty-row">${escapeModalText(pocket?.empty || "這個分類目前沒有道具。")}</div>`;
    }
    return pocket.items.map((item) => `
      <button type="button" class="backpack-item-row" data-backpack-name="${escapeModalText(item.name)}" data-backpack-count="${item.count}" data-backpack-tier="${escapeModalText(item.tier)}" data-backpack-meta="${escapeModalText(item.meta)}" data-backpack-badge="${escapeModalText(item.badge)}" data-backpack-image="${escapeModalText(item.image || "")}" data-backpack-frame-image="${escapeModalText(item.frameImage || "")}" data-backpack-portrait-image="${escapeModalText(item.portraitImage || "")}" data-backpack-action="${escapeModalText(item.action)}" data-backpack-kind="${escapeModalText(item.kind || "")}">
        <img class="backpack-item-slot-frame" src="images/board/backpack_ui/backpack_category_tab_frame.webp" alt="" aria-hidden="true">
        <span class="backpack-cursor">▶</span>
        ${itemIconMarkup({
          name: item.name,
          category: item.pocket,
          image: item.image,
          kind: item.kind,
          frameImage: item.frameImage,
          portraitImage: item.portraitImage,
        }, "backpack-row-thumb", { badge: item.badge })}
        <span class="backpack-item-copy">
          <span class="backpack-item-name">${escapeModalText(item.name)}</span>
          <span class="backpack-row-tier">${escapeModalText(item.tier)}</span>
        </span>
        <span class="backpack-item-count">× ${item.count}</span>
      </button>
    `).join("");
  }

  function useMapItemFromBackpack(player, itemId) {
    const itemDef = gameItemDef(itemId);
    if (!player || !itemDef || backpackUsableItemCount(player, itemDef.id) <= 0) return;
    const effect = itemDef.effect || {};
    let summary = itemDef.logText?.use || `${player.name} 使用了 ${itemDef.name}。`;
    let applied = false;
    if (effect.kind === "heal_party_percent_outside_battle" || effect.kind === "heal_party_percent_battle") {
      const healed = restoreCrewHpPercent(player, Number(effect.percent || 0.3));
      summary = `${player.name} 使用${itemDef.name}，全隊回復 ${healed} HP。`;
      applied = true;
    } else if (effect.kind === "heal_hp_percent") {
      const healed = healActiveCrewAndShipPercent(player, Number(effect.percent || 0.25));
      const targetCard = (activeCrew(player) && Number(activeCrew(player).currentHp || 0) > 0)
        ? activeCrew(player)
        : (player.crew || []).find((card) => Number(card.currentHp || 0) > 0);
      const targetName = targetCard?.name || "目前夥伴";
      summary = `${player.name} 使用${itemDef.name}，${targetName} 回復 ${healed} HP。`;
      applied = true;
    } else if (effect.kind === "heal_percent_and_cure_status") {
      const healed = healActiveCrewAndShipPercent(player, Number(effect.percent || 0.35));
      const targetCard = (activeCrew(player) && Number(activeCrew(player).currentHp || 0) > 0)
        ? activeCrew(player)
        : (player.crew || []).find((card) => Number(card.currentHp || 0) > 0);
      const targetName = targetCard?.name || "目前夥伴";
      summary = `${player.name} 使用${itemDef.name}，${targetName} 回復 ${healed} HP。`;
      applied = true;
    } else if (effect.kind === "revive") {
      const revived = reviveOneCrewMember(player, Number(effect.hpPercent || 0.3));
      if (!revived) {
        addLog("目前沒有瀕死的夥伴可以復活。");
        openBackpackModal({ pocketId: normalizeGameItemCategory(itemDef.category), itemName: itemDef.name });
        return;
      }
      summary = `${player.name} 使用${itemDef.name}，${revived.name} 復活並回復 ${revived.currentHp} HP。`;
      applied = true;
    } else if (effect.kind === "teleport_to_nearest_hospital_and_heal_party") {
      const service = HOSPITAL_SERVICES.find((entry) => entry.id === "full_crew_restore");
      const restoreText = service?.apply?.(player) || "全隊恢復。";
      const hospital = findNearestHospitalIsland(player);
      if (hospital) player.location = { kind: "island", islandId: hospital.id, entryDirection: null };
      summary = `${player.name} 使用${itemDef.name}，${restoreText}${hospital ? `，移動到 ${hospital.name}` : ""}。`;
      applied = true;
    } else if (Number(effect.steps || 0) > 0 || Number(effect.turns || 0) > 0 || effect.kind === "scare_low_level_enemy") {
      addMapBuffFromItem(player, itemDef);
      summary = itemDef.logText?.use || `${player.name} 使用${itemDef.name}，航海道具效果已啟動。`;
      applied = true;
    } else if (effect.kind === "heal_hp") {
      const heal = Math.max(1, Math.round(Number(effect.amount || 0)));
      player.hp = Math.min(player.maxHp, player.hp + heal);
      healCrew(player, heal);
      summary = `${player.name} 使用${itemDef.name}，恢復 ${heal} HP。`;
      applied = true;
    }
    if (!applied) {
      addLog(`${itemDef.name}目前不能在這個時機使用。`);
      openBackpackModal({ pocketId: normalizeGameItemCategory(itemDef.category), itemName: itemDef.name });
      return;
    }
    if (!consumeMapBackpackItem(player, itemDef.id)) {
      addLog(`${player.name} 想使用 ${itemDef.name}，但目前沒有可用數量。`);
      openBackpackModal({ pocketId: normalizeGameItemCategory(itemDef.category), itemName: itemDef.name });
      return;
    }
    addLog(summary);
    emitItemUseBoardEvent(player, itemDef, summary);
    recordMissionEvent(player, { type: "use_item_category", category: normalizeGameItemCategory(itemDef.category), itemId: itemDef.id, itemName: itemDef.name });
    if (["heal_hp", "heal_hp_percent", "heal_party_percent_battle", "heal_party_percent_outside_battle", "heal_percent_and_cure_status", "revive"].includes(effect.kind)) {
      recordMissionEvent(player, { type: "use_heal_item", category: normalizeGameItemCategory(itemDef.category), itemId: itemDef.id, itemName: itemDef.name });
    }
    if (effect.kind === "teleport_to_nearest_hospital_and_heal_party") {
      recordMissionEvent(player, { type: "medical_ticket_or_hospital", itemId: itemDef.id, itemName: itemDef.name });
    }
    recalcPlayerDerivedStats(player);
    renderAll();
    openBackpackModal({ pocketId: normalizeGameItemCategory(itemDef.category), itemName: itemDef.name });
  }

  function bindBackpackModal(player, pockets, preferredPocketId = "", preferredItemName = "") {
    const list = document.getElementById("backpackList");
    const currentPocketButton = document.getElementById("backpackPocketCurrent");
    const categoryButtons = Array.from(refs.modal?.querySelectorAll("[data-backpack-pocket]") || []);
    const previewBadge = document.getElementById("backpackPreviewBadge");
    const previewName = document.getElementById("backpackPreviewName");
    const previewTier = document.getElementById("backpackPreviewTier");
    const previewMeta = document.getElementById("backpackPreviewMeta");
    const actionButton = document.getElementById("backpackPreviewAction");
    const listPanel = refs.modal?.querySelector(".backpack-list-panel");
    const bagArt = refs.modal?.querySelector(".backpack-bag-art");
    const OPEN_ANIMATION_MS = 760;
    const CONTENT_REVEAL_AFTER_OPEN_MS = -400;
    let selectedAction = "";
    let currentPocketIndex = 0;
    let contentRevealTimer = 0;
    let contentRevealToken = 0;

    const playBackpackOpenAnimation = () => {
      if (!bagArt) return;
      bagArt.classList.remove("is-closing");
      bagArt.classList.remove("is-opening");
      void bagArt.offsetWidth;
      bagArt.classList.add("is-opening");
      window.setTimeout(() => bagArt.classList.remove("is-opening"), OPEN_ANIMATION_MS);
    };

    const hideBackpackContentForReveal = () => {
      contentRevealToken += 1;
      window.clearTimeout(contentRevealTimer);
      previewBadge.classList.remove("is-revealing");
      previewBadge.classList.add("is-waiting-reveal");
      listPanel?.classList.remove("is-revealing");
      listPanel?.classList.add("is-waiting-reveal");
    };

    const revealBackpackContentAfterOpen = () => {
      const token = contentRevealToken;
      contentRevealTimer = window.setTimeout(() => {
        if (token !== contentRevealToken) return;
        previewBadge.classList.remove("is-waiting-reveal");
        previewBadge.classList.add("is-revealing");
        listPanel?.classList.remove("is-waiting-reveal");
        listPanel?.classList.add("is-revealing");
        window.setTimeout(() => {
          if (token === contentRevealToken) {
            previewBadge.classList.remove("is-revealing");
            listPanel?.classList.remove("is-revealing");
          }
        }, 360);
      }, Math.max(0, OPEN_ANIMATION_MS + CONTENT_REVEAL_AFTER_OPEN_MS));
    };

    const selectRow = (row) => {
      Array.from(list.querySelectorAll(".backpack-item-row")).forEach((entry) => entry.classList.toggle("is-selected", entry === row));
      selectedAction = row.dataset.backpackAction || "";
      setItemIconElement(previewBadge, {
        name: row.dataset.backpackName || "道具",
        image: row.dataset.backpackImage || "",
        category: currentPocketButton.dataset.backpackTab || "key",
        kind: row.dataset.backpackKind || "",
        frameImage: row.dataset.backpackFrameImage || "",
        portraitImage: row.dataset.backpackPortraitImage || "",
      }, row.dataset.backpackBadge || "?");
      previewName.textContent = row.dataset.backpackName || "沒有道具";
      previewTier.textContent = row.dataset.backpackTier || "";
      previewMeta.textContent = row.dataset.backpackMeta || "";
      const isLineageFactor = row.dataset.backpackKind === "lineage-factor";
      previewName.classList.toggle("lineage-factor-preview", isLineageFactor);
      previewMeta.classList.toggle("lineage-factor-preview", isLineageFactor);
      if (selectedAction === "fixed_step") {
        actionButton.hidden = false;
        actionButton.textContent = "使用";
      } else if (selectedAction === "small_supply") {
        actionButton.hidden = false;
        actionButton.textContent = "使用";
      } else if (selectedAction === "crew") {
        actionButton.hidden = false;
        actionButton.textContent = "前往隊伍裝備";
      } else if (selectedAction.startsWith("select_heal_target:")) {
        actionButton.hidden = false;
        actionButton.textContent = "選擇船員";
      } else if (selectedAction.startsWith("select_evolution_target:")) {
        actionButton.hidden = false;
        actionButton.textContent = "選擇角色";
      } else if (selectedAction.startsWith("select_training_target:")) {
        actionButton.hidden = false;
        actionButton.textContent = "選擇船員";
      } else if (selectedAction.startsWith("select_skill_training_target:")) {
        actionButton.hidden = false;
        actionButton.textContent = "選擇船員";
      } else if (selectedAction.startsWith("select_passive_target:")) {
        actionButton.hidden = false;
        actionButton.textContent = "選擇船員";
      } else if (selectedAction.startsWith("select_training_reset:")) {
        actionButton.hidden = false;
        actionButton.textContent = "選擇船員";
      } else if (selectedAction.startsWith("open_judicial_chest:")) {
        actionButton.hidden = false;
        actionButton.textContent = "打開";
      } else if (selectedAction.startsWith("use_sea_train_ticket:")) {
        actionButton.hidden = false;
        actionButton.textContent = "使用";
      } else if (selectedAction === "activate_final_island") {
        actionButton.hidden = false;
        actionButton.textContent = "啟動";
      } else if (selectedAction === "activate_york_tracking") {
        actionButton.hidden = false;
        actionButton.textContent = normalizePlayerYorkDecoderState(player) >= 3 ? "再玩新題目" : "開始追蹤";
      } else if (selectedAction.startsWith("use_map_item:")) {
        actionButton.hidden = false;
        actionButton.textContent = "使用";
      } else {
        actionButton.hidden = true;
        actionButton.textContent = "";
      }
    };

    const showEmptyPreview = (pocket) => {
      selectedAction = "";
      setItemIconElement(previewBadge, { name: pocket.title, image: "", category: pocket.id }, pocket.badge);
      previewName.textContent = "沒有道具";
      previewTier.textContent = pocket.title;
      previewMeta.textContent = pocket.empty;
      previewName.classList.remove("lineage-factor-preview");
      previewMeta.classList.remove("lineage-factor-preview");
      actionButton.hidden = true;
      actionButton.textContent = "";
    };

    const renderPocketList = (pocket, nextPreferredItemName = "") => {
      list.innerHTML = renderBackpackPocketRows(pocket);
      const visibleRows = Array.from(list.querySelectorAll(".backpack-item-row"));
      visibleRows.forEach((row) => {
        row.addEventListener("click", () => selectRow(row));
      });
      const firstRow = visibleRows.find((row) => row.dataset.backpackName === nextPreferredItemName) || visibleRows[0];
      if (firstRow) {
        selectRow(firstRow);
        if (nextPreferredItemName) firstRow.scrollIntoView({ block: "nearest" });
      }
      else showEmptyPreview(pocket);
    };

    const selectPocket = (pocketId, nextPreferredItemName = "") => {
      hideBackpackContentForReveal();
      playBackpackOpenAnimation();
      const foundIndex = pockets.findIndex((entry) => entry.id === pocketId);
      currentPocketIndex = foundIndex >= 0 ? foundIndex : 0;
      const pocket = pockets[currentPocketIndex] || pockets[0];
      currentPocketButton.dataset.backpackTab = pocket.id;
      categoryButtons.forEach((button) => button.classList.toggle("is-active", button.dataset.backpackPocket === pocket.id));
      renderPocketList(pocket, nextPreferredItemName);
      revealBackpackContentAfterOpen();
    };

    categoryButtons.forEach((button) => button.addEventListener("click", () => selectPocket(button.dataset.backpackPocket || "")));
    actionButton?.addEventListener("click", () => {
      if (selectedAction === "fixed_step") openFixedStepModal(player);
      if (selectedAction === "small_supply") useSmallSupplyFromBackpack(player);
      if (selectedAction === "crew") openCrewManagementModal(player);
      if (selectedAction.startsWith("select_heal_target:")) openBackpackCrewTargetModal(player, selectedAction.slice("select_heal_target:".length), "heal");
      if (selectedAction.startsWith("select_evolution_target:")) openBackpackCrewTargetModal(player, selectedAction.slice("select_evolution_target:".length), "evolution");
      if (selectedAction.startsWith("select_training_target:")) openBackpackCrewTargetModal(player, selectedAction.slice("select_training_target:".length), "training");
      if (selectedAction.startsWith("select_skill_training_target:")) openBackpackCrewTargetModal(player, selectedAction.slice("select_skill_training_target:".length), "skillTraining");
      if (selectedAction.startsWith("select_passive_target:")) openBackpackCrewTargetModal(player, selectedAction.slice("select_passive_target:".length), "passiveTraining");
      if (selectedAction.startsWith("select_training_reset:")) openBackpackCrewTargetModal(player, selectedAction.slice("select_training_reset:".length), "resetTraining");
      if (selectedAction.startsWith("open_judicial_chest:")) openJudicialClearChest(player, selectedAction.slice("open_judicial_chest:".length));
      if (selectedAction.startsWith("use_sea_train_ticket:")) openSeaTrainGoldenTicketModal(player, selectedAction.slice("use_sea_train_ticket:".length));
      if (selectedAction === "activate_final_island") activateFinalIslandFromBackpack(player);
      if (selectedAction === "activate_york_tracking") activateYorkTrackingFromBackpack(player);
      if (selectedAction.startsWith("use_map_item:")) useMapItemFromBackpack(player, selectedAction.slice("use_map_item:".length));
    });
    const initialPocket = pockets.find((pocket) => pocket.id === preferredPocketId)?.id || pockets.find((pocket) => pocket.items.length)?.id || pockets[0].id;
    selectPocket(initialPocket, preferredItemName);
  }

  function openBackpackModal(options = {}) {
    const player = currentPlayer();
    if (state.gameState.phase !== "main" || state.gameState.pendingMove || state.gameState.movementAnimating || state.battleState || state.gameState.routePrompt || state.gameState.tradePrompt || state.gameState.activeTrade || activeSparBlocksCurrentTurn() || state.gameState.islandDecision) return;
    if (warnBoardLanTurnLocked(player)) return;
    recordMainMissionEvent(player, { type: "backpack_open" });
    const normalizedOptions = (!options || typeof options !== "object" || typeof options.preventDefault === "function") ? {} : options;
    const preferredPocketId = normalizedOptions.pocketId || "";
    const preferredItemName = normalizedOptions.itemName || "";
    const pockets = buildBackpackPockets(player);
    const playerIndex = Math.max(0, (state.gameState.players || []).indexOf(player));
    const shipSkin = shipSkinForPlayer(player, playerIndex);
    openModal(`
      <img class="backpack-ui-frame" src="images/board/backpack_ui/backpack_panel_frame.webp" alt="" aria-hidden="true">
      <h3 class="modal-title">航海背包</h3>
      <div class="backpack-owner-line">${escapeModalText(player.name || "玩家")} ・ ${escapeModalText(shipSkin?.name || "玩家船隻")}</div>
      <div class="backpack-category-tabs" id="backpackPocketCurrent" aria-label="背包分類">
        ${pockets.map((pocket) => `
          <button type="button" class="backpack-category-tab" data-backpack-pocket="${pocket.id}">
            <img src="images/board/backpack_ui/backpack_category_tab_frame.webp" alt="" aria-hidden="true">
            <span>${escapeModalText(pocket.title)}</span>
            <small>${pocket.items.reduce((sum, item) => sum + item.count, 0)}</small>
          </button>
        `).join("")}
      </div>
      <div class="backpack-shell">
        <aside class="backpack-side">
          <div class="backpack-preview">
            <div class="backpack-preview-top">
              <div class="backpack-item-icon" id="backpackPreviewBadge"><span class="inline-item-thumb item-thumb fallback"><span class="item-thumb-fallback"><img src="images/board/judicial_raid_ui/reward_icons/unknown.webp" alt=""></span></span></div>
            </div>
            <div class="backpack-preview-name" id="backpackPreviewName">沒有道具</div>
            <div class="backpack-preview-tier" id="backpackPreviewTier">背包</div>
            <p class="backpack-preview-meta" id="backpackPreviewMeta">這個分類目前沒有道具。</p>
            <button type="button" class="modal-btn primary backpack-preview-action" id="backpackPreviewAction" hidden></button>
          </div>
        </aside>
        <section class="backpack-list-panel">
          <div class="backpack-list" id="backpackList"></div>
        </section>
      </div>
      <div class="backpack-footer-actions">
        <span aria-hidden="true"></span>
        <button type="button" class="backpack-footer-btn" id="closeItemModalBtn">返回指令盤</button>
        <span aria-hidden="true"></span>
      </div>
    `, "backpack-modal");
    bindBackpackModal(player, pockets, preferredPocketId, preferredItemName);
    document.getElementById("closeItemModalBtn")?.addEventListener("click", () => {
      const bagArt = refs.modal?.querySelector(".backpack-bag-art");
      if (!bagArt) {
        closeModal();
        const pos = playerShipTokenPositionPx(player);
        openShipActionMenu(player, pos.x, pos.y);
        return;
      }
      bagArt.classList.remove("is-opening");
      bagArt.classList.add("is-closing");
      window.setTimeout(() => {
        closeModal();
        const pos = playerShipTokenPositionPx(player);
        openShipActionMenu(player, pos.x, pos.y);
      }, 240);
    });
  }

  function openPreDiceItemModal() {
    openBackpackModal();
  }

  function openFixedStepModal(player) {
    if (warnBoardLanTurnLocked(player)) return;
    const itemDef = gameItemDef("fixed_step") || {
      id: "fixed_step",
      name: "指定步數券",
      description: "指定本回合 1~6 步數。",
      image: "images/board/items/fixed_step.webp",
    };
    const availableCount = Math.max(Number(player.fixedStepTokens || 0), inventoryItemCount(player, "fixed_step"));
    openModal(`
      <section class="fixed-step-ui" aria-label="指定本回合步數">
        <img class="fixed-step-panel-frame" src="images/board/fixed_step_ui/fixed_step_panel_frame.webp" alt="" aria-hidden="true">
        <header class="fixed-step-heading">
          <h3>指定本回合步數</h3>
          <p>選擇這回合要直接航行的步數</p>
        </header>
        <div class="fixed-step-item-stage">
          <img src="${escapeModalText(itemDef.image || itemImageForDisplay(itemDef))}" alt="${escapeModalText(itemDef.name)}" loading="eager" onerror="this.remove();this.parentElement.classList.add('fallback');">
          <span><img src="${escapeModalText(itemFallbackIconPath(itemDef))}" alt="" aria-hidden="true"></span>
        </div>
        <div class="fixed-step-item-name">${escapeModalText(itemDef.name)}</div>
        <div class="fixed-step-item-info">
          <strong>目前持有 ${availableCount} 張</strong>
          <span>${escapeModalText(itemDef.description || itemDef.uiSummary || "指定本回合 1～6 步數。")}</span>
          <small>使用後會直接顯示可走路線與抵達格，不需要再次擲骰。</small>
        </div>
        <div class="fixed-step-choice-grid" aria-label="選擇步數">
          ${[1, 2, 3, 4, 5, 6].map((step) => `
            <button type="button" class="fixed-step-choice" data-fixed-step="${step}" aria-label="航行 ${step} 格">
              <strong>${step}</strong>
              <span>航行 ${step} 格</span>
            </button>
          `).join("")}
        </div>
        <div class="fixed-step-hint">
          <strong>點選步數後立即使用</strong>
          <span>將直接顯示可走路線與抵達格，不會再次擲骰。</span>
        </div>
        <button type="button" class="fixed-step-cancel" id="cancelFixedStepBtn">返回背包</button>
      </section>
    `, "fixed-step-modal fixed-step-nautical-modal no-backdrop-close");
    Array.from(refs.modal.querySelectorAll("[data-fixed-step]")).forEach((button) => {
      button.addEventListener("click", () => {
        const step = Number(button.dataset.fixedStep);
        if (Math.max(Number(player.fixedStepTokens || 0), inventoryItemCount(player, "fixed_step")) <= 0) return;
        if (!removeFormalItemFromPlayer(player, "fixed_step", 1)) {
          player.fixedStepTokens = Math.max(0, Number(player.fixedStepTokens || 0) - 1);
        }
        player.presetStep = step;
        addLog(`${player.name} 使用了指定步數道具。`);
        addLog(`${player.name} 指定本回合步數為 ${step}。`);
        closeModal();
        renderAll();
        void rollDice();
      });
    });
    document.getElementById("cancelFixedStepBtn")?.addEventListener("click", openBackpackModal);
  }

  function mapInfoIslandKindLabel(kind) {
    return {
      start: "起始島",
      enemy: "敵人島",
      yonko: "四皇據點",
      shop: "商店島",
      hospital: "醫院島",
      research_lab: "研究所島",
      tavern: "酒館島",
      arena: "競技場島",
      mission: "任務島",
      "event-island": "事件島",
      judicial: "司法島",
      impel_down: "推進城",
      marineford: "海軍本部",
      final: "最終之島",
      elbaph: "艾爾巴夫",
      postgame_boss: "無風帶孤島",
      postgame_egghead: "移動蛋頭島",
    }[kind] || "島嶼節點";
  }

  function renderMapNodeInfoPanel(config = {}) {
    const imageName = String(config.imageName || config.title || "未知節點");
    const imageSrc = String(config.imageSrc || ISLAND_IMAGE_MAP.unknown || PLACEHOLDER_BATTLE_PORTRAIT);
    const imageFallback = String(config.imageFallback || ISLAND_IMAGE_MAP.unknown || PLACEHOLDER_BATTLE_PORTRAIT);
    const stats = Array.from({ length: 6 }, (_, index) => {
      const entry = config.stats?.[index] || ["情報", "—"];
      return `
        <div class="map-node-stat">
          <span>${escapeModalText(entry[0])}</span>
          <strong title="${escapeModalText(entry[1])}">${escapeModalText(entry[1])}</strong>
        </div>
      `;
    }).join("");
    return `
      <section class="map-node-info-ui">
        <img class="map-node-info-frame" src="images/board/map_info_ui/map_node_info_panel_frame.webp" alt="" aria-hidden="true">
        <div class="map-node-visual ${config.imageMode === "portrait" ? "portrait" : "landscape"}">
          <img src="${escapeModalText(imageSrc)}" alt="${escapeModalText(imageName)}" loading="eager" data-fallback-src="${escapeModalText(imageFallback)}" onerror="if(this.dataset.fallbackSrc){this.src=this.dataset.fallbackSrc;this.dataset.fallbackSrc='';}else{this.remove();this.parentElement.classList.add('fallback');}">
          <span>${escapeModalText(imageName.slice(0, 1) || "？")}</span>
        </div>
        <header class="map-node-heading"><h3>${escapeModalText(config.title || "地圖情報")}</h3></header>
        <div class="map-node-caption">
          <strong title="${escapeModalText(imageName)}">${escapeModalText(imageName)}</strong>
          <span>${escapeModalText(config.imageMeta || "偉大航路節點")}</span>
        </div>
        <div class="map-node-summary" title="${escapeModalText(config.summary || "節點情報")}">${escapeModalText(config.summary || "節點情報")}</div>
        <div class="map-node-stat-grid">${stats}</div>
        <section class="map-node-description">
          <strong>${escapeModalText(config.descriptionTitle || "情報說明")}</strong>
          <p>${escapeModalText(config.description || "尚無更多情報。")}</p>
        </section>
        <div class="map-node-route" title="${escapeModalText(config.routeText || "航線情報尚未揭露")}">${escapeModalText(config.routeText || "航線情報尚未揭露")}</div>
        <div class="map-node-actions">${config.actionsMarkup || ""}</div>
      </section>
    `;
  }

  function inspectSeaTile(tile) {
    const player = currentPlayer();
    const viewer = mapViewerPlayer();
    const canMark = canBoardLanControlCurrentPlayer(player);
    const markerTarget = markerTargetFromSeaTile(tile);
    const scoutedEncounter = getScoutEncounterTileIds(viewer).has(tile?.id);
    const canIdentifyScoutedEnemy = scoutedEncounter && playerShipUpgradeLevel(viewer, "watchtower") >= 1;
    const scoutedEnemy = canIdentifyScoutedEnemy ? pickSeaEncounterEnemy(tile, viewer) : null;
    const scoutedEnemyName = scoutedEnemy?.name || "未知敵人";
    const scoutedEnemyPortraits = scoutedEnemy ? battleEnemyPortraitsFor(scoutedEnemy.key || "sea_enemy") : null;
    const routeItem = getRouteById(tile?.routeId);
    const routeFrom = getIslandById(routeItem?.from)?.name || "起點";
    const routeTo = getIslandById(routeItem?.to)?.name || "終點";
    const imageName = canIdentifyScoutedEnemy ? scoutedEnemyName : (scoutedEncounter ? "未辨識敵影" : "未知海域");
    const stats = scoutedEncounter
      ? [
        ["座標", `${tile?.col ?? "?"}, ${tile?.row ?? "?"}`],
        ["航線", `${routeFrom}－${routeTo}`],
        ["格子", "黑色遭遇格"],
        ["事件", "停靠後進入戰鬥"],
        ["偵查", "已發現敵影"],
        ["敵人", canIdentifyScoutedEnemy ? scoutedEnemyName : "需偵查台 Lv1"],
      ]
      : [
        ["座標", `${tile?.col ?? "?"}, ${tile?.row ?? "?"}`],
        ["航線", `${routeFrom}－${routeTo}`],
        ["格子", "未知海格"],
        ["事件", "停靠後二選一"],
        ["偵查", "尚未辨識"],
        ["敵影", "未知"],
      ];
    openModal(renderMapNodeInfoPanel({
      title: canIdentifyScoutedEnemy ? "瞭望台敵影情報" : (scoutedEncounter ? "偵查到敵影的海格" : "未知海域格"),
      imageName,
      imageMeta: canIdentifyScoutedEnemy
        ? "偵查被動標出黑格；偵查台完成辨識"
        : (scoutedEncounter ? "偵查被動已發現敵影；尚未辨識身份" : "停靠後才會揭露真正效果"),
      imageSrc: canIdentifyScoutedEnemy ? scoutedEnemyPortraits?.normal : ISLAND_IMAGE_MAP.unknown,
      imageFallback: ISLAND_IMAGE_MAP.unknown,
      imageMode: canIdentifyScoutedEnemy ? "portrait" : "landscape",
      summary: canIdentifyScoutedEnemy
        ? `瞭望台辨識：${scoutedEnemyName}`
        : (scoutedEncounter ? "偵查型被動確認這格有敵影" : "這片海域仍被迷霧籠罩"),
      stats,
      descriptionTitle: scoutedEncounter ? "黑色遭遇格" : "海域規則",
      description: scoutedEncounter
        ? (canIdentifyScoutedEnemy
          ? `偵查台已確認這格埋伏的是「${scoutedEnemyName}」。其他能力與完整數值會在船隻真正停靠、觸發遭遇後確認。`
          : "偵查型被動只能確認這格會出現敵影；升級偵查台後，才能點擊這個黑色遭遇格辨識敵人。")
        : "停上去後會抽出兩張事件類型卡，選擇其中一張後才會揭露真正效果。",
      routeText: `${routeFrom} ⇄ ${routeTo} ・ 座標 ${tile?.col ?? "?"}, ${tile?.row ?? "?"}`,
      actionsMarkup: `
        ${canMark ? mapMarkerButtonsMarkup(player, markerTarget, "markSeaTileBtn") : ""}
        <button type="button" class="modal-btn secondary" id="closeInspectBtn">關閉</button>
      `,
    }), "map-node-info-nautical-modal backdrop-close");
    bindMapMarkerButtons(player, markerTarget, scoutedEncounter ? "偵查敵影" : "海格", "markSeaTileBtn");
    document.getElementById("closeInspectBtn")?.addEventListener("click", closeModal);
  }

  function inspectIsland(island) {
    if (island.id === INVERSION_MOUNTAIN_ID) {
      openInversionMountainOverview();
      return;
    }
    const islandState = getIslandState(island.id);
    const viewer = mapViewerPlayer();
    const islandView = getVisibleIslandView(viewer, island);
    const player = currentPlayer();
    const canMark = canBoardLanControlCurrentPlayer(player);
    const markerTarget = markerTargetFromIsland(island);
    if (islandView.hidden) {
      openModal(renderMapNodeInfoPanel({
        title: islandView.displayName,
        imageName: islandView.displayName,
        imageMeta: "需要偵查或親自抵達",
        imageSrc: islandView.imageUrl,
        imageFallback: ISLAND_IMAGE_MAP.unknown,
        summary: `${islandView.displayBrief} ・ ${islandView.displayHint}`,
        stats: [
          ["島名", "尚未揭露"],
          ["類型", "未知"],
          ["偵查", "尚未完成"],
          ["航線", "未公開"],
          ["拓本", "未知"],
          ["狀態", "等待探索"],
        ],
        descriptionTitle: "未知島嶼",
        description: "需要偵查型夥伴提供視野，或由玩家親自抵達後，才會揭露島名、類型與完整效果。",
        routeText: "可先標記此處；正式航線情報會在探索後顯示。",
        actionsMarkup: `
          ${canMark ? mapMarkerButtonsMarkup(player, markerTarget, "markIslandBtn") : ""}
          <button type="button" class="modal-btn secondary" id="closeIslandBtn">關閉</button>
        `,
      }), "map-node-info-nautical-modal backdrop-close");
      bindMapMarkerButtons(player, markerTarget, "未知島嶼", "markIslandBtn");
      document.getElementById("closeIslandBtn")?.addEventListener("click", closeModal);
      return;
    }
    const islandKind = getEffectiveIslandKind(island, islandState);
    const islandKindLabel = mapInfoIslandKindLabel(islandKind);
    const routes = getAvailableRoutes(island.id, player);
    const entryDirection = player?.location?.kind === "island" && player.location.islandId === island.id
      ? player.location.entryDirection
      : null;
    const routeDirections = routes
      .map((routeItem) => {
        const travel = traversalFromIsland(routeItem, island.id);
        return `${directionLabel(travel.exitDirection)}：${getIslandById(travel.toIslandId).name}`;
      })
      .join(" ・ ");
    let extra = island.hint || "";
    const postgameAssignment = isPostgameIsland(island) ? postgameBossAssignment(island) : null;
    if (isPostgameIsland(island)) {
      extra = islandView.bossRevealed && postgameAssignment?.boss
        ? `${postgameAssignment.boss.name} 的專屬據點；勝利後所有實際參戰者各取得「約克的線索 ${postgameAssignment.boss.clueNumber}」並進入各自的血統因子抽取流程。每次勝利都可重複取得，但重戰前必須先離島。`
        : "無風帶消失後顯現的孤島；第一次登島後才會揭露駐守 Boss 與專屬島圖。";
    } else if (island.kind === "enemy" && islandState?.enemyProfile && !islandState.isDefeated) {
      extra = canRevealEnemyIslandInfo(viewer, island)
        ? `敵人 ${islandState.enemyProfile.name} ・ 階級 ${tierLabel(islandState.enemyProfile.tier)} ・ Lv.${islandState.enemyProfile.level || enemyLevelForProgress(islandState.enemyProfile.tier)} ・ 屬性 ${islandState.enemyProfile.attribute} ・ 類型 ${islandState.enemyProfile.role || "敵人"} ・ 剩餘 HP ${islandState.currentHp}/${islandState.maxHp}`
        : `${enemyIslandShadowText()}；需偵查台 Lv3，且位於目前所在或偵查範圍內，才會顯示敵人資訊`;
    } else if (island.kind === "yonko" && islandState?.enemyProfile && !islandState.isDefeated) {
      extra = `敵人級別 ${tierLabel(islandState.enemyProfile.tier)} ・ Lv.${islandState.enemyProfile.level || enemyLevelForProgress(islandState.enemyProfile.tier)} ・ 推薦戰力 ${islandState.enemyProfile.recommendedPower}+ ・ HP ${islandState.currentHp}/${islandState.maxHp}`;
      if (getTeamEffects(viewer).enemyInfoBonus > 0) extra += ` ・ 屬性 ${islandState.enemyProfile.attribute}`;
    } else if (island.kind === "yonko" && !islandState?.enemyProfile) {
      extra = "四皇敵人待設定，暫時不進入戰鬥";
    } else if (islandKind === "shop") {
      extra = isTemporaryEnemyIslandService(island, islandState)
        ? `臨時商店，可購買補給與道具；剩 ${temporaryEnemyIslandTurnsLeft(islandState)} 回合後敵人會換人回來`
        : "商店島，可購買補給與道具";
    } else if (islandKind === "hospital") {
      extra = isTemporaryEnemyIslandService(island, islandState)
        ? `臨時醫院，可恢復 HP / PP / 狀態；剩 ${temporaryEnemyIslandTurnsLeft(islandState)} 回合後敵人會換人回來`
        : "醫院島，可恢復 HP / PP / 狀態";
    } else if (islandKind === "research_lab") {
      extra = "正式研究所，可免費恢復全隊，並管理角色收藏與六名登船成員";
    } else if (islandKind === "tavern") {
      extra = isTemporaryEnemyIslandService(island, islandState)
        ? `臨時酒館，可花錢招募新夥伴；剩 ${temporaryEnemyIslandTurnsLeft(islandState)} 回合後敵人會換人回來`
        : "酒館島，可花錢招募新夥伴";
    } else if (islandKind === "arena") {
      extra = "競技場島，可從 51 名 Lv.99 最高型態對手中指定一名，選兩名船員挑戰並取得研究點數";
    } else if (islandKind === "mission") {
      extra = "任務島，可接委託賺取貝里、EXP 與懸賞；船內可查看已接任務進度";
    } else if (island.kind === "yonko" && islandState?.isYonkoDefeated) {
      extra = `四皇已倒，${roadPoneglyphLabelForGlyph(islandState.glyphId)}已出現；可再次挑戰`;
    } else if (islandKind === "event-island") {
      extra = "事件島，登陸後會觸發特殊探索";
    } else if (island.kind === "final") {
      extra = state.gameState.finalIslandUnlocked
        ? "最終之島已正式開啟，仍需自己收滿 4 份拓本"
        : state.gameState.finalIslandCandidate
          ? "四皇全倒，最終之島線索已浮現；需有人集滿 4 份拓本才會正式開啟"
          : "四皇全倒後才會出現線索";
    }
    const enemyVisible = Boolean(
      islandState?.enemyProfile
      && !islandState.isDefeated
      && (island.kind !== "enemy" || canRevealEnemyIslandInfo(viewer, island))
    );
    const glyphCopiedCount = Array.isArray(islandState?.copiedByPlayers) ? islandState.copiedByPlayers.length : 0;
    const islandStatus = islandState?.isDefeated || islandState?.isYonkoDefeated
      ? "已解放"
      : islandState?.enemyProfile
        ? "敵人駐守"
        : "可探索";
    const stats = isPostgameIsland(island)
      ? [
        ["類型", "無風帶孤島"],
        ["駐守者", islandView.bossRevealed ? (postgameAssignment?.boss?.name || "未知") : "尚未揭露"],
        ["血統階級", islandView.bossRevealed ? (islandState?.enemyProfile?.extractionRank || "SSS") : "未知"],
        ["等級", islandView.bossRevealed ? `Lv.${islandState?.enemyProfile?.level || 99}` : "未知"],
        ["生命", islandView.bossRevealed ? `${islandState?.currentHp || 0}/${islandState?.maxHp || 0}` : "未知"],
        ["線索牌", islandView.bossRevealed ? postgameClueCardLabel(postgameAssignment?.boss?.clueNumber) : "未知"],
      ]
      : enemyVisible
      ? [
        ["敵人", islandState.enemyProfile.name || "未知敵人"],
        ["階級", tierLabel(islandState.enemyProfile.tier)],
        ["等級", `Lv.${islandState.enemyProfile.level || enemyLevelForProgress(islandState.enemyProfile.tier)}`],
        ["屬性", islandState.enemyProfile.attribute || "未知"],
        ["類型", islandState.enemyProfile.role || "敵人"],
        ["生命", `${islandState.currentHp}/${islandState.maxHp}`],
      ]
      : [
        ["類型", islandKindLabel],
        ["航線", `${routes.length} 條`],
        ["來時", entryDirection ? directionLabel(entryDirection) : "未停靠"],
        ["狀態", islandStatus],
        ["拓本", islandState?.glyphId ? `${glyphCopiedCount}/${state.gameState.players.length}` : "無"],
        ["座標", `${island.col ?? "?"}, ${island.row ?? "?"}`],
      ];
    openModal(renderMapNodeInfoPanel({
      title: islandView.displayName,
      imageName: islandView.displayName,
      imageMeta: `${islandView.displayBrief || islandKindLabel} ・ ${islandStatus}`,
      imageSrc: islandView.imageUrl || getIslandImageUrl(island, islandState),
      imageFallback: isPostgameEggheadIsland(island)
        ? ISLAND_IMAGE_MAP.research_lab
        : isPostgameBossIsland(island)
          ? ISLAND_IMAGE_MAP.postgame_boss
          : ISLAND_IMAGE_MAP.unknown,
      summary: `${islandKindLabel} ・ ${islandView.displayBrief || "偉大航路節點"}`,
      stats,
      descriptionTitle: enemyVisible ? "駐守情報" : "島嶼說明",
      description: extra || "目前沒有額外情報。",
      routeText: routeDirections || "目前沒有可走航線",
      actionsMarkup: `
        ${canMark ? mapMarkerButtonsMarkup(player, markerTarget, "markIslandBtn") : ""}
        <button type="button" class="modal-btn secondary" id="closeIslandBtn">關閉</button>
      `,
    }), "map-node-info-nautical-modal backdrop-close");
    bindMapMarkerButtons(player, markerTarget, islandKindLabel, "markIslandBtn");
    document.getElementById("closeIslandBtn")?.addEventListener("click", closeModal);
  }

  function openInversionMountainOverview() {
    const routes = state.gameState.boardData.inversionMountainRoutes || [];
    openModal(`
      <section class="inversion-overview-ui">
        <img class="inversion-overview-frame" src="images/board/map_info_ui/inversion_mountain_overview_frame.webp" alt="" aria-hidden="true">
        <header class="inversion-overview-heading"><h3>顛倒山航線總覽</h3></header>
        <div class="inversion-overview-rule">
          <strong>五條主航線採唯一占用制</strong>
          <span>先到先選；後到玩家不能再選擇已被占用的航線。</span>
        </div>
        <div class="inversion-route-list">
          ${routes.slice(0, 5).map((entry, index) => {
            const ownerId = state.gameState.claimedBranchRoutes?.[entry.branchId];
            const owner = ownerId ? state.gameState.players.find((player) => player.id === ownerId) : null;
            const destination = getIslandById(entry.gateId)?.name || "偉大航路";
            return `
              <article class="inversion-route-row ${owner ? "claimed" : "available"}">
                <div class="inversion-route-badge">${index + 1}</div>
                <div class="inversion-route-copy">
                  <strong>${escapeModalText(routeLabel(entry.branchId))}</strong>
                  <span title="${escapeModalText(destination)}">通往 ${escapeModalText(destination)}</span>
                </div>
                <div class="inversion-route-status">
                  <strong>${owner ? "已占用" : "可選擇"}</strong>
                  <span title="${escapeModalText(owner?.name || "尚未被占用")}">${escapeModalText(owner?.name || "尚未被占用")}</span>
                </div>
              </article>
            `;
          }).join("")}
        </div>
        <div class="inversion-overview-actions">
          <button type="button" class="modal-btn secondary" id="closeInversionOverviewBtn">關閉</button>
        </div>
      </section>
    `, "inversion-overview-nautical-modal backdrop-close");
    document.getElementById("closeInversionOverviewBtn")?.addEventListener("click", closeModal);
  }

  function currentIslandServiceAction(player = currentPlayer()) {
    if (!player || player.location?.kind !== "island") return null;
    if (!canBoardLanControlCurrentPlayer(player)) return null;
    if (state.gameState.phase !== "main" || state.battleState || isGameActionLocked()) return null;
    const island = getIslandById(player.location.islandId);
    const islandState = getIslandState(player.location.islandId);
    const kind = getEffectiveIslandKind(island, islandState);
    if (!isServiceIslandKind(kind)) return null;
    const label = island.id === WATER_SEVEN_ISLAND_ID ? "水之七島船塢" : serviceIslandLabel(kind);
    return { player, island, islandState, kind, label };
  }

  function clearPendingIslandServiceChoice(player) {
    if (player?.pendingIslandServiceChoice) player.pendingIslandServiceChoice = null;
  }

  function pendingIslandServiceChoiceOwnsResolutionLock() {
    return Boolean(
      state.gameState?.resolutionLock
      && /：進島或出發$/.test(String(state.gameState?.turnStep || ""))
    );
  }

  function releasePendingIslandServiceChoiceLock() {
    if (!pendingIslandServiceChoiceOwnsResolutionLock()) return false;
    state.gameState.resolutionLock = false;
    state.gameState.turnStep = "擲骰前進";
    return true;
  }

  function markPendingIslandServiceChoice(player, island, serviceKind, battle) {
    if (!player || !island?.id || !isServiceIslandKind(serviceKind)) return false;
    if (player.location?.kind !== "island" || String(player.location.islandId || "") !== String(island.id)) return false;
    player.pendingIslandServiceChoice = {
      islandId: island.id,
      serviceKind,
      battleId: battle?.islandId || island.id,
      enemyKey: battle?.enemyCombatant?.key || battle?.enemyCombatant?.name || "",
      round: Math.max(1, Number(state.gameState?.round || 1)),
      createdAt: Date.now(),
    };
    return true;
  }

  function markPendingIslandServiceChoiceForPlayers(players, island, serviceKind, battle, immediatePlayer = null) {
    const immediateId = String(immediatePlayer?.id || "");
    const seen = new Set();
    return (players || []).filter(Boolean).filter((player) => {
      const id = String(player.id || "");
      if (!id || id === immediateId || seen.has(id)) return false;
      seen.add(id);
      return markPendingIslandServiceChoice(player, island, serviceKind, battle);
    });
  }

  function pendingIslandServiceChoiceAction(player = currentPlayer()) {
    if (!player?.pendingIslandServiceChoice) return null;
    if (player.location?.kind !== "island") {
      clearPendingIslandServiceChoice(player);
      releasePendingIslandServiceChoiceLock();
      return null;
    }
    const choice = player.pendingIslandServiceChoice;
    if (String(choice.islandId || "") !== String(player.location.islandId || "")) {
      clearPendingIslandServiceChoice(player);
      releasePendingIslandServiceChoiceLock();
      return null;
    }
    const island = getIslandById(player.location.islandId);
    const islandState = getIslandState(player.location.islandId);
    const kind = getEffectiveIslandKind(island, islandState);
    if (!island || !islandState || !isServiceIslandKind(kind)) {
      clearPendingIslandServiceChoice(player);
      releasePendingIslandServiceChoiceLock();
      return null;
    }
    if (choice.serviceKind && choice.serviceKind !== kind && isTemporaryEnemyIslandService(island, islandState)) {
      choice.serviceKind = kind;
    }
    return {
      player,
      island,
      islandState,
      kind,
      label: island.id === WATER_SEVEN_ISLAND_ID ? "水之七島船塢" : serviceIslandLabel(kind),
      choice,
    };
  }

  function canOpenPendingIslandServiceChoice(player = currentPlayer()) {
    if (!pendingIslandServiceChoiceAction(player)) return false;
    return state.gameState.phase === "main"
      && !state.battleState
      && !state.gameState.pendingMove
      && !state.gameState.movementAnimating
      && !state.gameState.diceRolling
      && !state.gameState.routePrompt
      && !state.gameState.tradePrompt
      && !state.gameState.coopBattlePrompt
      && !state.gameState.activeTrade
      && !activeSparBlocksCurrentTurn()
      && !state.gameState.islandDecision
      && (!state.gameState.resolutionLock || pendingIslandServiceChoiceOwnsResolutionLock())
      && canBoardLanControlCurrentPlayer(player);
  }

  function cpuShouldEnterPendingIslandService(action) {
    const player = action?.player;
    if (!player || !isCpuPlayer(player)) return false;
    if (action.kind === "hospital") return devObserverNeedsRecovery(player, true);
    if (action.kind === "research_lab") {
      return devObserverNeedsRecovery(player, true) || Boolean(devObserverDesiredResearchLabExtractor(player));
    }
    if (action.kind === "shop") return Boolean(devObserverDesiredShopItemId(player));
    if (action.kind === "tavern") return devObserverShouldRollTavern(player);
    if (action.kind === "mission") {
      return Boolean(devObserverCompletedMission(player) || devObserverBestMissionChoice(player, action.island));
    }
    if (action.kind === "arena") return Boolean(cpuChooseArenaPlan(player, action.island));
    return false;
  }

  function resolvePendingIslandServiceChoice(action, decision = "roll", options = {}) {
    const liveAction = pendingIslandServiceChoiceAction(action?.player);
    if (!liveAction || String(liveAction.player?.id || "") !== String(currentPlayer()?.id || "")) return false;
    if (!canBoardLanControlCurrentPlayer(liveAction.player)) return false;
    const enter = decision === "enter";
    clearPendingIslandServiceChoice(liveAction.player);
    releasePendingIslandServiceChoiceLock();
    if (refs.modal?.querySelector(".island-service-choice-ui")) closeModal();
    if (options.cpu) {
      addLog(enter
        ? `${liveAction.player.name} 在共鬥後選擇進入${liveAction.label}。`
        : `${liveAction.player.name} 在共鬥後略過${liveAction.label}，繼續擲骰航行。`);
    }
    if (enter) {
      scheduleBoardLanStatePush("post-battle-island-enter", 80, { force: true });
      if (enterIslandService(liveAction)) return true;
    }
    renderAll();
    scheduleBoardLanStatePush("post-battle-island-roll", 80, { force: true });
    rollDice();
    return true;
  }

  function openPendingIslandServiceChoice(player = currentPlayer()) {
    const action = pendingIslandServiceChoiceAction(player);
    if (!action || !canOpenPendingIslandServiceChoice(player)) return false;
    state.gameState.resolutionLock = true;
    state.gameState.turnStep = `${action.island.name}：進島或出發`;
    const turnsLeft = isTemporaryEnemyIslandService(action.island, action.islandState)
      ? temporaryEnemyIslandTurnsLeft(action.islandState)
      : 0;
    const islandImage = getIslandImageUrl(action.island, action.islandState) || ISLAND_IMAGE_MAP.unknown;
    const fallbackImage = ISLAND_IMAGE_MAP.unknown;
    const enterLabel = `進入${action.label.replace(/島$/, "")}`;
    openModal(`
      <section class="island-decision-ui island-service-choice-ui" aria-labelledby="postBattleIslandChoiceTitle">
        <div class="island-decision-visual">
          <img
            src="${escapeModalText(islandImage)}"
            alt="${escapeModalText(action.island.name)}"
            loading="eager"
            decoding="async"
            draggable="false"
            data-fallback-src="${escapeModalText(fallbackImage)}"
            onerror="if(this.dataset.fallbackSrc){this.src=this.dataset.fallbackSrc;this.dataset.fallbackSrc='';}else{this.remove();this.parentElement.classList.add('fallback');}"
          >
          <span aria-hidden="true"><img src="images/board/attribute_icons/neutral.webp" alt=""></span>
        </div>
        <img class="island-decision-panel-frame" src="images/board/island_decision_ui/island_decision_panel_frame.webp?v=20260725-island-decision-ui-v1" alt="" aria-hidden="true">
        <header class="island-decision-heading">
          <h3 id="postBattleIslandChoiceTitle">${escapeModalText(action.island.name)}</h3>
        </header>
        <div class="island-decision-remaining">
          <span>這座敵人島已被共鬥打退，現在是</span>
          <strong>${escapeModalText(action.label)}</strong>
          <span>。</span>
        </div>
        <div class="island-decision-brief">${escapeModalText(action.label)}${turnsLeft ? ` ・ 剩 ${escapeModalText(String(turnsLeft))} 回合` : ""}</div>
        <div class="island-decision-hint"><p>要進島使用功能，還是擲骰子出發？</p></div>
        <div class="island-decision-actions">
          <button type="button" class="island-decision-action stay" id="enterPostBattleIslandBtn">
            <img src="images/board/island_decision_ui/island_decision_stay_button_frame.webp?v=20260725-island-decision-ui-v1" alt="" aria-hidden="true">
            <span>${escapeModalText(enterLabel)}</span>
          </button>
          <button type="button" class="island-decision-action continue" id="rollFromPostBattleIslandBtn">
            <img src="images/board/island_decision_ui/island_decision_continue_button_frame.webp?v=20260725-island-decision-ui-v1" alt="" aria-hidden="true">
            <span>擲骰子出發</span>
          </button>
        </div>
      </section>
    `, "island-decision-nautical-modal force-choice no-backdrop-close");
    document.getElementById("enterPostBattleIslandBtn")?.addEventListener("click", () => {
      resolvePendingIslandServiceChoice(action, "enter");
    });
    document.getElementById("rollFromPostBattleIslandBtn")?.addEventListener("click", () => {
      resolvePendingIslandServiceChoice(action, "roll");
    });
    renderAll();
    scheduleBoardLanStatePush("post-battle-island-choice", 80, { force: true });
    return true;
  }

  function scheduleTurnStartIslandServiceChoiceForCurrentPlayer() {
    [0, 180, 520].forEach((delay) => {
      window.setTimeout(() => {
        const player = currentPlayer();
        if (!player || pendingCoopBattleResultForPlayer(player) || refs.modalBack?.classList.contains("open")) return;
        openPendingIslandServiceChoice(player);
      }, delay);
    });
  }

  function enterIslandService(action) {
    if (!action?.player || !action.island || !action.islandState) return false;
    if (warnBoardLanTurnLocked(action.player)) return false;
    recordMissionEvent(action.player, { type: "visit_island_kind", islandKind: action.kind, islandId: action.island.id });
    if (action.island.id === WATER_SEVEN_ISLAND_ID) {
      openWaterSevenWindow(action.player);
      return true;
    }
    if (action.kind === "shop") {
      openShopModal(action.player, action.island, action.islandState);
      return true;
    }
    if (action.kind === "hospital") {
      openHospitalModal(action.player, action.island);
      return true;
    }
    if (action.kind === "research_lab") {
      openResearchLabModal(action.player, action.island);
      return true;
    }
    if (action.kind === "tavern") {
      openTavernModal(action.player, action.island);
      return true;
    }
    if (action.kind === "arena") {
      openArenaModal(action.player, action.island);
      return true;
    }
    if (action.kind === "mission") {
      openMissionBoardModal(action.player, action.island, action.islandState, "", "", { newVisit: true });
      return true;
    }
    return false;
  }

  function inspectCurrentTile() {
    const player = currentPlayer();
    if (openPendingIslandServiceChoice(player)) return;
    const serviceAction = currentIslandServiceAction(player);
    if (serviceAction && enterIslandService(serviceAction)) return;
    if (player.location.kind === "island") inspectIsland(getIslandById(player.location.islandId));
    else inspectSeaTile(getTileByLocation(player.location.routeId, player.location.tileIndex));
  }

  function describeLocation(location) {
    if (location.kind === "island") return `位於 ${getIslandById(location.islandId).name}`;
    const tile = getTileByLocation(location.routeId, location.tileIndex);
    return `未知海域格 (${tile.col}, ${tile.row})`;
  }

  function processLowHpRecovery(player) {
    const effects = getTeamEffects(player);
    if (!effects.lowHpRecover || player._lowHpRecoveredThisBattle) return;
    if (battlePercent(player) < 0.3) {
      player._lowHpRecoveredThisBattle = true;
      healCrew(player, effects.lowHpRecover);
      recalcPlayerDerivedStats(player);
    }
  }

  function battlePercent(player) {
    return player.hp / Math.max(1, player.maxHp);
  }

  function formatCoin(value) {
    return `${Math.max(0, value).toLocaleString()}`;
  }

  function randomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  function wait(ms) {
    const speed = devObserver?.running ? Math.max(0.25, Number(devObserver.speed || 1)) : 1;
    return new Promise((resolve) => setTimeout(resolve, Math.max(16, Math.round(Number(ms || 0) / speed))));
  }

  function disableFriendUiForGame() {
    ["boardFriendDock", "boardChatTray", "boardInviteBack", "boardToastWrap"].forEach((id) => {
      const node = document.getElementById(id);
      if (node) {
        node.style.display = "none";
        node.setAttribute("aria-hidden", "true");
      }
    });
    document.body.classList.add("board-game-no-friends");
  }

  function bindEvents() {
    refs.backToLobbyBtn?.addEventListener("click", () => {
      const lobbyUrl = `board_start.html?view=lobby&room=${encodeURIComponent(state.lobby.roomCode || "")}`;
      if (new URLSearchParams(window.location.search).get("desktop_frame") === "1" && window.top !== window.self) {
        window.top.location.href = lobbyUrl;
        return;
      }
      location.href = lobbyUrl;
    });
    refs.useItemBtn?.addEventListener("click", () => {
      if (warnBoardLanTurnLocked()) return;
      openBackpackModal();
    });
    refs.rollDiceBtn?.addEventListener("click", rollDice);
    refs.inspectTileBtn?.addEventListener("click", () => {
      if (warnBoardLanTurnLocked()) return;
      inspectCurrentTile();
    });
    refs.focusPlayerBtn?.addEventListener("click", () => {
      state.autoCenterEnabled = true;
      autoCenterOnCurrentPlayer();
    });
    refs.viewWholeMapBtn?.addEventListener("click", () => {
      viewWholeMap();
    });
    refs.cpuSpeedSelect?.addEventListener("change", (event) => {
      setCpuTurnSpeed(event.target.value);
    });
    refs.cpuStrategyBtn?.addEventListener("click", openCpuStrategyModal);
    refs.saveGameBtn?.addEventListener("click", saveManualGame);
    refs.loadGameBtn?.addEventListener("click", openLoadGameModal);
    const activateShipTokenFromEvent = (event) => {
      const token = event.target.closest(".ship-token.current,.ship-token.actionable");
      if (!token) return;
      const player = state.gameState.players.find((entry) => String(entry.id || "") === String(token.dataset.playerId || ""));
      if (!player) return;
      event.preventDefault();
      event.stopPropagation();
      const clickedMoveLearnBadge = event.target instanceof Element
        && !!event.target.closest(".ship-move-learn-badge");
      if (canOpenMoveLearnPanelFor(player) && (clickedMoveLearnBadge || !canOpenShipActionsFor(player))) {
        closeShipActionMenu();
        processNextPendingMoveLearn({ playerId: player.id, notify: true });
        return;
      }
      if (!canOpenShipActionsFor(player)) {
        if (canOpenCpuShipControlFor(player)) {
          const pos = playerShipTokenPositionPx(player);
          openShipActionMenu(player, pos.x, pos.y);
          return;
        }
        if (token.classList.contains("current")) {
          if (!warnBoardLanTurnLocked(player)) {
            shared.showToast("目前還有移動、事件或彈窗要先處理。");
          }
        }
        return;
      }
      const pos = playerShipTokenPositionPx(player);
      openShipActionMenu(player, pos.x, pos.y);
    };
    refs.boardGameMap?.addEventListener("click", activateShipTokenFromEvent);
    refs.boardGameMap?.addEventListener("pointerup", (event) => {
      if (event.pointerType === "mouse") return;
      activateShipTokenFromEvent(event);
    });
    refs.boardGameMap?.addEventListener("touchend", activateShipTokenFromEvent, { passive: false });
    refs.boardGameMap?.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" && event.key !== " ") return;
      activateShipTokenFromEvent(event);
    });
    refs.boardViewport?.addEventListener("click", (event) => {
      if (event.target.closest(".ship-token.actionable,.ship-action-menu,.ship-move-learn-badge")) return;
      closeShipActionMenu();
    });
    refs.modalBack?.addEventListener("click", (event) => {
      if (event.target !== refs.modalBack) return;
      if (refs.modalBack.dataset.forceChoice === "true") return;
      if (refs.modalBack.dataset.backdropClose === "false") return;
      const explicitlyAllowsBackdropClose = refs.modalBack.dataset.backdropClose === "true";
      if (!explicitlyAllowsBackdropClose) {
        if (String(state.gameState?.phase || "").startsWith("setup")) return;
        if (state.battleState || state.gameState?.resolutionLock || state.gameState?.islandDecision || state.gameState?.routePrompt || state.gameState?.tradePrompt || state.gameState?.activeTrade || activeSparBlocksCurrentTurn()) return;
      }
      if (manualLoadModalActive && refs.modal?.classList.contains("save-load-nautical-modal")) {
        closeManualLoadModal();
        return;
      }
      closeModal();
    });
    setupBoardPanZoom();
    window.addEventListener("message", (event) => {
      if (event.origin && event.origin !== window.location.origin && event.origin !== "null") return;
      if (event?.data?.type === "board-battle-command" && event.data.command) {
        processBattlePageCommand(event.data.command);
        return;
      }
      if (event?.data?.type === "board-spar-selection-ready") {
        notifySparSelectionWindow();
        return;
      }
      if (event?.data?.type === "board-spar-selection-command" && event.data.command) {
        processSparSelectionCommand(event.data.command);
        return;
      }
      if (event?.data?.type === "board-marineford-command" && event.data.command) {
        processMarinefordPageCommand(event.data.command);
      }
    });
    window.addEventListener("storage", (event) => {
      if (event.key === MARINEFORD_COMMAND_KEY && event.newValue) {
        try {
          processMarinefordPageCommand(JSON.parse(event.newValue));
        } catch (_error) {
          // Ignore malformed cross-window commands.
        }
        return;
      }
      if (event.key === IMPEL_DOWN_COMMAND_KEY && event.newValue) {
        try {
          processImpelDownPageCommand(JSON.parse(event.newValue));
        } catch (_error) {
          // Ignore malformed cross-window commands.
        }
        return;
      }
      if (event.key !== BATTLE_COMMAND_KEY || !event.newValue) return;
      try {
        processBattlePageCommand(JSON.parse(event.newValue));
      } catch (_error) {
        // Ignore malformed cross-window commands.
      }
    });
    setInterval(readBattlePageCommand, 350);
    setInterval(readImpelDownPageCommand, 350);
    setInterval(readMarinefordPageCommand, 350);
  }

  function devObserverDelay(ms = 900) {
    return Math.max(80, Math.round(Number(ms || 900) / Math.max(0.5, Number(devObserver.speed || 1))));
  }

  function setDevObserverStatus(text) {
    const label = text || "待機";
    if (devObserver.statusEl) devObserver.statusEl.textContent = label;
    if (devObserver.panel) devObserver.panel.dataset.running = devObserver.running ? "true" : "false";
  }

  function persistDevObserverSettings() {
    try {
      localStorage.setItem(DEV_OBSERVER_STORAGE_KEY, JSON.stringify({
        visible: !!devObserver.visible,
        speed: Number(devObserver.speed || 4),
      }));
    } catch (_error) {
      // Ignore private-mode storage failures.
    }
  }

  function loadDevObserverSettings() {
    try {
      const saved = JSON.parse(localStorage.getItem(DEV_OBSERVER_STORAGE_KEY) || "{}");
      if (Number.isFinite(Number(saved.speed))) devObserver.speed = Math.max(0.5, Math.min(16, Number(saved.speed)));
      if (saved.visible === true) devObserver.visible = true;
    } catch (_error) {
      // Ignore malformed settings.
    }
  }

  function ensureDevObserverStyles() {
    if (document.getElementById("boardDevObserverStyles")) return;
    const style = document.createElement("style");
    style.id = "boardDevObserverStyles";
    style.textContent = `
      .board-dev-observer{
        position:fixed;
        left:14px;
        bottom:14px;
        z-index:620;
        width:min(310px, calc(100vw - 28px));
        color:#f7fbff;
        background:linear-gradient(180deg, rgba(11,38,53,.88), rgba(8,24,35,.86));
        border:1px solid rgba(154,220,255,.36);
        border-radius:16px;
        box-shadow:0 16px 44px rgba(0,20,35,.34), inset 0 1px 0 rgba(255,255,255,.12);
        backdrop-filter:blur(12px);
        overflow:hidden;
        font-family:"Noto Sans TC",system-ui,-apple-system,Segoe UI,sans-serif;
      }
      .board-dev-observer[hidden]{display:none}
      .board-dev-observer-head{
        display:flex;
        align-items:center;
        justify-content:space-between;
        gap:10px;
        padding:10px 12px 8px;
        border-bottom:1px solid rgba(255,255,255,.12);
      }
      .board-dev-observer-title{
        display:flex;
        flex-direction:column;
        gap:2px;
        min-width:0;
      }
      .board-dev-observer-title strong{
        font-size:13px;
        font-weight:950;
        letter-spacing:.04em;
      }
      .board-dev-observer-title span{
        color:rgba(226,244,255,.74);
        font-size:11px;
        font-weight:800;
      }
      .board-dev-observer-close{
        width:28px;
        height:28px;
        border-radius:10px;
        border:1px solid rgba(255,255,255,.18);
        background:rgba(255,255,255,.08);
        color:#fff;
        cursor:pointer;
        font-weight:950;
      }
      .board-dev-observer-body{
        display:grid;
        gap:10px;
        padding:10px 12px 12px;
      }
      .board-dev-observer-status{
        min-height:34px;
        padding:8px 10px;
        border-radius:12px;
        background:rgba(255,255,255,.08);
        color:#d9f3ff;
        font-size:12px;
        font-weight:850;
        line-height:1.35;
      }
      .board-dev-observer-speed{
        display:grid;
        gap:6px;
      }
      .board-dev-observer-speed label{
        display:flex;
        justify-content:space-between;
        color:rgba(236,249,255,.88);
        font-size:12px;
        font-weight:900;
      }
      .board-dev-observer-speed input{width:100%}
      .board-dev-observer-actions{
        display:grid;
        grid-template-columns:1fr 1fr;
        gap:8px;
      }
      .board-dev-observer button{
        min-height:34px;
        border-radius:12px;
        border:1px solid rgba(255,255,255,.18);
        background:rgba(255,255,255,.1);
        color:#f8fdff;
        font-weight:950;
        cursor:pointer;
      }
      .board-dev-observer button.primary{
        background:linear-gradient(180deg, rgba(40,176,225,.88), rgba(13,105,161,.82));
        border-color:rgba(152,230,255,.55);
      }
      .board-dev-observer[data-running="true"] button[data-dev-observer-start]{
        background:linear-gradient(180deg, rgba(238,118,92,.9), rgba(169,51,45,.86));
        border-color:rgba(255,190,170,.46);
      }
      .board-dev-observer-foot{
        color:rgba(225,244,255,.68);
        font-size:11px;
        line-height:1.35;
      }
    `;
    document.head.appendChild(style);
  }

  function ensureDevObserverPanel() {
    if (devObserver.panel) return devObserver.panel;
    ensureDevObserverStyles();
    const panel = document.createElement("section");
    panel.id = "boardDevObserverPanel";
    panel.className = "board-dev-observer";
    panel.hidden = !devObserver.visible;
    panel.innerHTML = `
      <div class="board-dev-observer-head">
        <div class="board-dev-observer-title">
          <strong>開發者觀察</strong>
          <span>Ctrl + Shift + D 切換</span>
        </div>
        <button type="button" class="board-dev-observer-close" data-dev-observer-close aria-label="關閉">×</button>
      </div>
      <div class="board-dev-observer-body">
        <div class="board-dev-observer-status" data-dev-observer-status>待機</div>
        <div class="board-dev-observer-speed">
          <label>自動速度 <span data-dev-observer-speed-label>${Number(devObserver.speed || 4).toFixed(1)}x</span></label>
          <input type="range" min="0.5" max="16" step="0.5" value="${Number(devObserver.speed || 4)}" data-dev-observer-speed>
        </div>
        <div class="board-dev-observer-actions">
          <button type="button" class="primary" data-dev-observer-start>開始自動</button>
          <button type="button" data-dev-observer-step>單步</button>
          <button type="button" data-dev-observer-rewind>退回伊姆前</button>
          <button type="button" data-dev-observer-grant>測試補給</button>
        </div>
        <div class="board-dev-observer-foot">這是可觀看的前台自動跑；背景壓測仍用 runner。</div>
      </div>
    `;
    document.body.appendChild(panel);
    devObserver.panel = panel;
    devObserver.statusEl = panel.querySelector("[data-dev-observer-status]");
    devObserver.speedLabel = panel.querySelector("[data-dev-observer-speed-label]");
    devObserver.startBtn = panel.querySelector("[data-dev-observer-start]");

    panel.querySelector("[data-dev-observer-close]")?.addEventListener("click", () => toggleDevObserverPanel(false));
    panel.querySelector("[data-dev-observer-speed]")?.addEventListener("input", (event) => {
      devObserver.speed = Math.max(0.5, Math.min(16, Number(event.target.value || 4)));
      if (devObserver.speedLabel) devObserver.speedLabel.textContent = `${devObserver.speed.toFixed(1)}x`;
      persistDevObserverSettings();
    });
    devObserver.startBtn?.addEventListener("click", () => setDevObserverRunning(!devObserver.running));
    panel.querySelector("[data-dev-observer-step]")?.addEventListener("click", () => void runDevObserverStep(true));
    panel.querySelector("[data-dev-observer-rewind]")?.addEventListener("click", async () => {
      setDevObserverRunning(false);
      setDevObserverStatus("退回艾爾巴夫 / 伊姆入口前...");
      const result = await rewindCurrentPlayerBeforeFinalGate({ save: true });
      setDevObserverStatus(result?.ok ? "已退回伊姆入口前。" : (result?.reason || "退回失敗。"));
    });
    panel.querySelector("[data-dev-observer-grant]")?.addEventListener("click", () => {
      grantBattleCarryItemsForTesting();
      grantGameItemsForTesting();
      setDevObserverStatus("已補測試道具與攜帶物。");
    });
    setDevObserverStatus("待機");
    return panel;
  }

  function toggleDevObserverPanel(force = null) {
    const panel = ensureDevObserverPanel();
    devObserver.visible = force == null ? !devObserver.visible : !!force;
    panel.hidden = !devObserver.visible;
    if (!devObserver.visible) setDevObserverRunning(false);
    persistDevObserverSettings();
  }

  function setDevObserverRunning(running) {
    devObserver.running = !!running;
    if (devObserver.startBtn) devObserver.startBtn.textContent = devObserver.running ? "暫停自動" : "開始自動";
    if (!devObserver.running && devObserver.timer) {
      window.clearTimeout(devObserver.timer);
      devObserver.timer = 0;
    }
    setDevObserverStatus(devObserver.running ? "自動觀察中..." : "已暫停。");
    if (devObserver.running) scheduleDevObserverStep(80);
  }

  function scheduleDevObserverStep(delay = 0) {
    if (!devObserver.running) return;
    if (devObserver.timer) window.clearTimeout(devObserver.timer);
    devObserver.timer = window.setTimeout(() => {
      devObserver.timer = 0;
      void runDevObserverStep(false);
    }, Math.max(0, delay));
  }

  function isDevObserverClickable(node) {
    if (!node || node.disabled || node.hidden) return false;
    const style = window.getComputedStyle(node);
    if (style.display === "none" || style.visibility === "hidden" || style.pointerEvents === "none") return false;
    const rect = node.getBoundingClientRect();
    return rect.width > 0 && rect.height > 0;
  }

  function clickFirstDevObserverButton(selectors) {
    for (const selector of selectors) {
      const nodes = Array.from(document.querySelectorAll(selector));
      const node = nodes.find(isDevObserverClickable);
      if (node) {
        node.click();
        return node.textContent?.trim() || selector;
      }
    }
    return "";
  }

  function devObserverCardScore(card) {
    if (!card) return 0;
    const stats = card.baseStats || card.stats || {};
    const tierScore = Math.max(0, 7 - tierRank(card.tier)) * 1000;
    const role = String(card.roleType || "");
    const roleBonus = /戰鬥|攻擊|輸出/.test(role) ? 160
      : /補給|治療|輔助|防禦/.test(role) ? 130
      : /偵查|移動/.test(role) ? 90
      : 50;
    return tierScore
      + Math.max(1, Number(card.level || 1)) * 16
      + Math.max(0, Number(stats.hp || card.hp || 0)) * 0.5
      + Math.max(0, Number(stats.atk || card.atk || 0)) * 4
      + Math.max(0, Number(stats.def || card.def || 0)) * 3
      + Math.max(0, Number(stats.spd || card.spd || 0)) * 3
      + roleBonus;
  }

  function devObserverWeakestCrew(player) {
    const crew = player?.crew || [];
    if (!crew.length) return null;
    return crew
      .map((card, index) => ({ card, index, score: devObserverCardScore(card) }))
      .sort((a, b) => a.score - b.score)[0] || null;
  }

  function devObserverVisibleRecruitName() {
    return document.querySelector(".tavern-result-card .companion-name")?.textContent?.trim() || "";
  }

  function devObserverVisibleRecruitTier() {
    const badge = document.querySelector(".tavern-result-card .tavern-grade-badge")?.textContent?.trim();
    return legacyTier(badge || "");
  }

  function devObserverFindRecruitFromResult(player) {
    const name = devObserverVisibleRecruitName();
    if (!name) return null;
    const candidates = [
      ...(state.gameState.availableCards || []),
      ...(player?.crew || []),
    ];
    return candidates.find((card) => cardDisplayName(card) === name || card.name === name) || {
      name,
      tier: devObserverVisibleRecruitTier() || "T6",
      roleType: document.querySelector(".tavern-result-card .companion-tier")?.textContent?.trim() || "",
      baseStats: {},
      level: 1,
    };
  }

  function devObserverRecruitReserve(player) {
    const crewCount = (player?.crew || []).length;
    if (crewCount <= 2) return 0;
    if (crewCount <= 4) return 800;
    return 1600;
  }

  function devObserverAliveCrew(player) {
    return (player?.crew || []).filter((card) => card && Number(card.currentHp || 0) > 0);
  }

  function devObserverAveragePpRatio(player) {
    const moves = (player?.crew || []).flatMap((card) => card?.moveSet || []);
    const ppMoves = moves.filter((move) => Number(move.pp || 0) > 0);
    if (!ppMoves.length) return 1;
    const total = ppMoves.reduce((sum, move) => {
      const max = Math.max(1, Number(move.pp || 1));
      const current = Math.max(0, Number(move.currentPP ?? max));
      return sum + Math.min(1, current / max);
    }, 0);
    return total / ppMoves.length;
  }

  function devObserverInventoryCount(player, itemId) {
    const def = gameItemDef(itemId);
    if (!def) return Math.max(0, inventoryItemCount(player, itemId));
    return Math.max(0, backpackUsableItemCount(player, def.id), inventoryItemCount(player, def.id));
  }

  function devObserverTeamPower(player) {
    const alive = devObserverAliveCrew(player);
    const crew = alive.length ? alive : (player?.crew || []).filter(Boolean);
    if (!crew.length) return 0;
    const avgLevel = crewAverageLevelForExp(player);
    const avgCombat = crew.reduce((sum, card) => {
      const stats = card.baseStats || card.stats || {};
      const attack = Math.max(Number(stats.atk || card.atk || 0), Number(stats.satk || card.satk || 0));
      const defense = Math.max(Number(stats.def || card.def || 0), Number(stats.sdef || card.sdef || 0));
      return sum + attack + defense * 0.28 + Number(stats.spd || card.spd || 0) * 0.18;
    }, 0) / crew.length;
    const crewBonus = Math.min(6, crew.length) * 2.6;
    const hpPenalty = crewAverageHpRatio(player) < 0.55 ? -8 : 0;
    return Math.max(1, Math.round(avgCombat + Number(avgLevel || 1) * 0.32 + crewBonus + hpPenalty));
  }

  function devObserverEnemyRisk(player, enemyProfile = null) {
    const enemyPower = Math.max(1, Number(enemyProfile?.recommendedPower || enemyProfile?.baseStats?.recommendedPower || enemyProfile?.power || 1));
    const teamPower = devObserverTeamPower(player);
    const crewCount = (player?.crew || []).length;
    const hpRatio = crewAverageHpRatio(player);
    const ppRatio = devObserverAveragePpRatio(player);
    let readiness = teamPower - enemyPower;
    if (crewCount < 4) readiness -= 12;
    else if (crewCount < TEAM_LIMIT) readiness -= 5;
    if (hpRatio < 0.45) readiness -= 16;
    else if (hpRatio < 0.65) readiness -= 8;
    if (ppRatio < 0.35) readiness -= 8;
    return {
      teamPower,
      enemyPower,
      readiness,
      isTooHard: readiness < -12,
      isRisky: readiness < -4,
      isComfortable: readiness >= 6,
    };
  }

  function devObserverNeedsRecovery(player, strict = false) {
    if (!player) return false;
    const crew = player.crew || [];
    const hasDown = crew.some((card) => Number(card?.currentHp || 0) <= 0);
    const hpRatio = crewAverageHpRatio(player);
    const ppRatio = devObserverAveragePpRatio(player);
    return hasDown || hpRatio < (strict ? 0.72 : 0.52) || ppRatio < (strict ? 0.42 : 0.22);
  }

  function devObserverMapHealingItem(player) {
    const items = Object.values(GAME_ITEMS || {})
      .filter((item) => item && isBackpackHealingItem(item) && devObserverInventoryCount(player, item.id) > 0);
    if (!items.length) return null;
    const hasDown = (player?.crew || []).some((card) => Number(card?.currentHp || 0) <= 0);
    const hpRatio = crewAverageHpRatio(player);
    return items
      .map((item) => {
        const kind = item.effect?.kind || "";
        let score = 0;
        if (kind === "revive") score += hasDown ? 220 : -80;
        if (kind === "heal_party_percent_battle" || kind === "heal_party_percent_outside_battle") score += hpRatio < 0.7 ? 180 : 80;
        if (kind === "heal_percent_and_cure_status") score += 150;
        if (kind === "heal_hp_percent") score += 110;
        if (kind === "heal_hp") score += 70;
        score += Number(item.effect?.percent || item.effect?.hpPercent || 0) * 100;
        return { item, score };
      })
      .sort((a, b) => b.score - a.score)[0]?.item || null;
  }

  function devObserverTryUseMapRecovery(player) {
    if (!player || state.gameState.resolutionLock || state.gameState.movementAnimating || state.gameState.pendingMove) return "";
    if (!devObserverNeedsRecovery(player, false)) return "";
    const item = devObserverMapHealingItem(player);
    if (!item) return "";
    useMapItemFromBackpack(player, item.id);
    closeModal();
    return `血量/PP 偏低，使用背包補給：${item.name}`;
  }

  function devObserverMapMaintenanceBlocked() {
    return state.gameState.phase !== "main"
      || !!state.battleState
      || !!state.gameState.routePrompt
      || !!state.gameState.islandDecision
      || !!state.gameState.pendingMove
      || !!state.gameState.movementAnimating
      || !!state.gameState.diceRolling
      || !!state.gameState.resolutionLock
      || refs.modalBack?.classList.contains("open")
      || refs.itemRevealHud?.classList.contains("show")
      || refs.evolutionHud?.classList.contains("show");
  }

  function devObserverCardMoveEntries(card) {
    return (card?.moves || card?.moveSet || []).filter(Boolean);
  }

  function devObserverCardMoveProfile(card) {
    const moves = devObserverCardMoveEntries(card);
    const attacks = moves.filter(battleMoveDealsDamage);
    const physical = attacks.filter(boardMoveIsPhysicalDamage).length;
    const special = attacks.filter(boardMoveIsSpecialDamage).length;
    return {
      moves,
      attacks,
      physical,
      special,
      hasFire: moves.some(isFireBattleMove),
      hasWater: moves.some(isWaterBattleMove),
      hasThunder: moves.some((move) => /雷|電|閃|thunder|lightning/.test(moveSearchText(move))),
      hasShooting: moves.some(isShootingBattleMove),
      hasHeal: moves.some((move) => /回復|治療|heal|cure/.test(moveSearchText(move)) || (move.category || move.type) === "heal"),
      hasShield: moves.some((move) => /護盾|減傷|防禦|shield|guard/.test(moveSearchText(move)) || (move.category || move.type) === "shield"),
    };
  }

  function devObserverMoveEffectValue(moveEntry) {
    const effects = moveEntry?.effects || {};
    const text = moveSearchText(moveEntry);
    let score = 0;
    const stageValue = (stages = {}) => Object.values(stages || {}).reduce((sum, value) => sum + Math.abs(Number(value || 0)), 0);
    score += stageValue(effects.selfStages) * 42;
    score += stageValue(effects.enemyStages) * 45;
    score += stageValue(effects.enemyStagesOnHit) * 38;
    score += stageValue(effects.enemyStagesOnSix) * 24;
    if (effects.shieldRatio || effects.shieldRatioBeforeAttack) score += Number(effects.shieldRatio || effects.shieldRatioBeforeAttack || 0) * 220;
    if (effects.healRatio || effects.healTeamRatio || effects.healLowestAllyRatio) {
      score += Number(effects.healRatio || 0) * 280;
      score += Number(effects.healTeamRatio || 0) * 390;
      score += Number(effects.healLowestAllyRatio || 0) * 310;
    }
    if (effects.reviveLowestAllyRatio) score += 210;
    if (effects.restoreSkillUse || effects.restorePp || effects.restorePP) score += 80;
    if (effects.multiHit || effects.comboAtkRatio) score += 48 + Number(effects.comboAtkRatio || 0) * 420;
    if (effects.ignoreDefenseRatio) score += Number(effects.ignoreDefenseRatio || 0) * 180;
    if (effects.bossDamageBonus) score += Number(effects.bossDamageBonus || 0) * 160;
    if (effects.amplifyOnHighDice) score += Number(effects.amplifyOnHighDice || 0) * 95;
    if (effects.bonusOnHighDice) score += Math.min(70, Number(effects.bonusOnHighDice || 0) * 1.4);
    if (/灼傷|流血|麻痺|中毒|冰凍|束縛|混亂|burn|bleed|paraly|poison|freeze|bind|confuse/.test(text)) score += 34;
    if (/破防|防禦下降|速度下降|命中下降|攻擊下降|意志下降/.test(text)) score += 24;
    if (/全隊|隊伍|最低|復活/.test(text)) score += 28;
    return score;
  }

  function devObserverMoveScoreForCard(card, moveEntry, moveSet = []) {
    if (!card || !moveEntry) return -9999;
    const category = moveEntry.category || moveEntry.type || "";
    const role = String(card.roleType || "");
    const stats = card.baseStats || card.stats || {};
    const attackStat = Math.max(1, Number(stats.atk || card.atk || 1));
    const specialStat = Math.max(1, Number(stats.satk || card.satk || 1));
    const pp = Math.max(0, Number(moveEntry.pp || 0));
    const accuracy = Math.max(0.45, Math.min(1.15, Number(moveEntry.accuracy || 100) / 100));
    const power = Math.max(0, Number(moveEntry.power || 0));
    const unlockLevel = effectiveMoveUnlockLevel(moveEntry);
    const effectValue = devObserverMoveEffectValue(moveEntry);
    const text = moveSearchText(moveEntry);
    const damageClass = boardMoveDamageClass(moveEntry);
    let score = unlockLevel * 2.3 + Math.min(24, pp * 1.2) + Number(moveEntry.priority || 0) * 18 + effectValue;
    if (damageClass === "physical" || damageClass === "special") {
      const statBias = damageClass === "special" ? specialStat / attackStat : attackStat / specialStat;
      score += 72 + power * 1.65 * accuracy + Math.max(-18, Math.min(28, (statBias - 1) * 26));
      if (role === "戰鬥型") score += 28;
      if (role === "偵查型" && damageClass === "special") score += 16;
      if (role === "移動型" && Number(moveEntry.priority || 0) > 0) score += 20;
    } else if (category === "heal") {
      score += 128;
      if (role === "輔助型") score += 54;
    } else if (category === "shield") {
      score += 112;
      if (role === "輔助型") score += 38;
    } else if (category === "buff") {
      score += 88;
      if (role === "戰鬥型" || role === "輔助型") score += 22;
    } else if (["debuff", "control", "status"].includes(category)) {
      score += 96 + accuracy * 25;
      if (role === "偵查型" || role === "輔助型") score += 34;
    } else {
      score += 58;
    }
    if (moveEntry.attribute && moveEntry.attribute === card.attribute) score += 18;
    if (damageClass === "special" || /奧義|覺醒|最終|王|神|霸氣/.test(text)) score += 18;
    if (pp <= 2 && power < 90 && !["heal", "shield"].includes(category)) score -= 24;
    const sameCategoryCount = (moveSet || []).filter((move) => (move.category || move.type || "") === category).length;
    if (sameCategoryCount >= 3 && !["attack", "special"].includes(category)) score -= (sameCategoryCount - 2) * 18;
    return score;
  }

  function devObserverMoveSetScoreForCard(card, moves = []) {
    const validMoves = (moves || []).filter(Boolean).slice(0, MAX_ACTIVE_MOVES);
    if (!validMoves.length) return -9999;
    let score = validMoves.reduce((sum, move) => sum + devObserverMoveScoreForCard(card, move, validMoves), 0);
    const categories = validMoves.map((move) => move.category || move.type || "");
    const damageCount = validMoves.filter(devObserverBattleMoveCanDamage).length;
    const hasHeal = categories.includes("heal");
    const hasShield = categories.includes("shield");
    const hasControl = categories.some((category) => ["debuff", "control", "status"].includes(category));
    const role = String(card?.roleType || "");
    if (damageCount <= 0) score -= 520;
    else if (damageCount === 1) score -= 25;
    else if (damageCount >= 2) score += 42;
    if (hasControl) score += role === "偵查型" ? 58 : 28;
    if (hasHeal) score += role === "輔助型" ? 78 : 26;
    if (hasShield) score += role === "輔助型" ? 45 : 18;
    if (role === "輔助型" && !hasHeal && !hasShield && !hasControl) score -= 55;
    if (role === "戰鬥型" && damageCount < 2) score -= 42;
    const categoryCounts = categories.reduce((map, category) => {
      map[category] = Number(map[category] || 0) + 1;
      return map;
    }, {});
    Object.entries(categoryCounts).forEach(([category, count]) => {
      if (count > 2 && !["attack", "special"].includes(category)) score -= (count - 2) * 35;
    });
    return score;
  }

  function devObserverMoveLearnReplacementDecision(card, newMove) {
    if (!card || !newMove) return { type: "skip", reason: "沒有技能資料" };
    syncCardMoveSetFromCatalog(card);
    syncUnlockedMoveIds(card);
    const currentMoves = getUnlockedMoves(card).slice(0, MAX_ACTIVE_MOVES);
    if ((card.unlockedMoveIds || []).includes(newMove.id)) return { type: "known" };
    if (currentMoves.length < MAX_ACTIVE_MOVES) return { type: "learn", newMove };
    const currentScore = devObserverMoveSetScoreForCard(card, currentMoves);
    const currentDamageCount = currentMoves.filter(devObserverBattleMoveCanDamage).length;
    const newMoveCanDamage = devObserverBattleMoveCanDamage(newMove);
    const candidates = currentMoves.map((oldMove) => {
      const nextMoves = currentMoves.map((move) => move.id === oldMove.id ? newMove : move);
      const afterScore = devObserverMoveSetScoreForCard(card, nextMoves);
      return {
        oldMove,
        newMove,
        afterScore,
        gain: afterScore - currentScore,
        oldScore: devObserverMoveScoreForCard(card, oldMove, currentMoves),
        newScore: devObserverMoveScoreForCard(card, newMove, nextMoves),
      };
    }).filter((candidate) => {
      if (newMoveCanDamage) return true;
      if (currentDamageCount > 1) return true;
      return !devObserverBattleMoveCanDamage(candidate.oldMove);
    }).sort((a, b) => (b.gain - a.gain) || (a.oldScore - b.oldScore))[0];
    if (!candidates) return { type: "skip", reason: "沒有可替換技能" };
    return { type: "replace", ...candidates };
  }

  function devObserverApplyMoveLearnDecision(player, card, newMove, decision, jobIndex = 0) {
    const queue = state.gameState.pendingMoveLearnQueue || [];
    if (!player || !card || !newMove || !decision) return "";
    const removeJob = () => {
      const index = Math.floor(Number(jobIndex));
      if (index >= 0 && index < queue.length) queue.splice(index, 1);
      else queue.shift();
    };
    const continueForPlayer = () => processNextPendingMoveLearn({ playerId: player.id });
    if (decision.type === "known") {
      removeJob();
      closeModal();
      syncMoveLearnQueueAfterChange("move-learn-known");
      continueForPlayer();
      return `${cardDisplayName(card)} 已會 ${newMove.name}。`;
    }
    if (decision.type === "learn") {
      card.unlockedMoveIds = Array.from(new Set([...(card.unlockedMoveIds || []), newMove.id])).slice(0, MAX_ACTIVE_MOVES);
      addLog(`${cardDisplayName(card)} 學會了 ${newMove.name}。`);
      recordMainMissionEvent(player, { type: "move_learned", cardId: card.id, moveId: newMove.id });
      removeJob();
      closeModal();
      syncMoveLearnQueueAfterChange("move-learn-auto");
      continueForPlayer();
      return `自動學會技能：${cardDisplayName(card)} / ${newMove.name}`;
    }
    if (decision.type === "replace" && decision.oldMove?.id) {
      card.unlockedMoveIds = (card.unlockedMoveIds || [])
        .map((id) => id === decision.oldMove.id ? newMove.id : id)
        .slice(0, MAX_ACTIVE_MOVES);
      addLog(`${cardDisplayName(card)} 遺忘了 ${decision.oldMove.name}，學會了 ${newMove.name}。`);
      recordMainMissionEvent(player, { type: "move_learned", cardId: card.id, moveId: newMove.id });
      removeJob();
      closeModal();
      syncMoveLearnQueueAfterChange("move-learn-replace");
      continueForPlayer();
      return `自動替換技能：${cardDisplayName(card)} 忘掉 ${decision.oldMove.name}，學 ${newMove.name}`;
    }
    addLog(`${cardDisplayName(card)} 判斷後暫時沒有學習 ${newMove.name}。`);
    removeJob();
    closeModal();
    syncMoveLearnQueueAfterChange("move-learn-skip");
    continueForPlayer();
    return `自動放棄技能：${cardDisplayName(card)} / ${newMove.name}`;
  }

  function devObserverHandleMoveLearnChoice(options = {}) {
    const queue = state.gameState.pendingMoveLearnQueue || [];
    if (!queue.length || state.battleState) return "";
    const targetPlayerId = String(options.playerId || "");
    const cpuOnly = !!options.cpuOnly;
    let jobIndex = -1;
    let player = null;
    let card = null;
    let newMove = null;
    for (let index = 0; index < queue.length; index += 1) {
      const job = queue[index];
      const context = moveLearnJobContext(job);
      if (!context.player || !context.card || !context.newMove) {
        queue.splice(index, 1);
        closeModal();
        renderAll();
        processNextPendingMoveLearn(targetPlayerId ? { playerId: targetPlayerId } : {});
        return "清除失效的技能學習佇列。";
      }
      if (targetPlayerId && String(context.player.id || "") !== targetPlayerId) continue;
      if (cpuOnly && !canLocalDriveCpuPlayer(context.player)) continue;
      if (!canResolveMoveLearnForPlayer(context.player)) continue;
      jobIndex = index;
      player = context.player;
      card = context.card;
      newMove = context.newMove;
      break;
    }
    if (jobIndex < 0 || !player || !card || !newMove) return "";
    const decision = devObserverMoveLearnReplacementDecision(card, newMove);
    return devObserverApplyMoveLearnDecision(player, card, newMove, decision, jobIndex);
  }

  function devObserverRarityScore(itemOrDef) {
    const label = `${itemRarityLabel(itemOrDef?.rarity)} ${itemOrDef?.rarity || ""}`;
    if (/S|史詩|司法島|四皇|通關|secret/i.test(label)) return 210;
    if (/A|高級|稀有|rare|advanced/i.test(label)) return 145;
    if (/B|普通|common/i.test(label)) return 85;
    if (/C/i.test(label)) return 45;
    return 60;
  }

  function devObserverCarryScoreForCard(item, card, cardIndex, player) {
    const def = battleCarryItemDef(item);
    if (!def || !card) return -9999;
    if (!validateBattleCarryEquip(card, item).ok) return -9999;
    const effect = battleCarryItemEffect(item);
    const id = def.id;
    const text = `${id} ${def.name} ${def.category || ""} ${def.summary || ""} ${effect.kind || ""}`.toLowerCase();
    const stats = card.baseStats || card.stats || {};
    const maxHp = Math.max(1, Number(card.maxHp || stats.hp || 1));
    const hpRatio = Math.max(0, Number(card.currentHp ?? maxHp)) / maxHp;
    const moveProfile = devObserverCardMoveProfile(card);
    const attackStat = Number(stats.atk || card.atk || 0);
    const specialStat = Number(stats.satk || card.satk || 0);
    const defenseStat = Number(stats.def || card.def || 0) + Number(stats.sdef || card.sdef || 0);
    const activeBonus = Number(player?.activeCrewIndex ?? 0) === cardIndex ? 38 : 0;
    let score = devObserverRarityScore(def) + devObserverCardScore(card) * 0.03 + activeBonus;

    if (id === "lucky_egg" || effect.kind === "exp_bonus_self") {
      const level = Number(card.level || 1);
      score += Math.max(0, 95 - level) * 2.2;
      if (cardIndex !== Number(player?.activeCrewIndex ?? 0)) score += 20;
    }
    if (id === "choice_band" || effect.kind === "choice_lock_physical_damage") score += moveProfile.physical >= moveProfile.special ? 190 : -90;
    if (id === "choice_glasses" || effect.kind === "choice_lock_special_damage") score += moveProfile.special > moveProfile.physical ? 190 : -90;
    if (id === "choice_scarf" || /速度|speed|spd/.test(text)) score += Math.max(0, Number(stats.spd || card.spd || 0)) * 0.55 + 70;
    if (id === "life_orb" || effect.kind === "damage_bonus_with_self_damage") score += Math.max(attackStat, specialStat) * 1.4 + (hpRatio > 0.72 ? 80 : -70);
    if (id === "flame_dial" || id === "flame_shell") score += moveProfile.hasFire ? 170 : 8;
    if (id === "water_dial") score += moveProfile.hasWater ? 155 : 28;
    if (id === "thunder_shell") score += moveProfile.hasThunder ? 175 : 12;
    if (id === "ammo_pouch" || id === "sniper_king_goggles") score += moveProfile.hasShooting ? 175 : 20;
    if (id === "medical_bag") score += moveProfile.hasHeal ? 210 : -35;
    if (id === "opal_cloud") score += moveProfile.hasShield ? 180 : 35;
    if (id === "focus_sash" || id === "life_paper" || id === "going_merry_rescue") score += hpRatio < 0.9 ? 120 : 165;
    if (id === "cloud_dial" || id === "vegapunk_mini_shield") score += defenseStat < 80 ? 130 : 85;
    if (id === "sanji_bento" || id === "water_meat") score += hpRatio < 0.75 ? 165 : 105;
    if (id === "medicine_pack" || id === "sky_island_goggles" || id === "lamp_dial") score += 85;
    if (id === "impact_dial" || id === "reject_dial" || id === "slash_dial" || id === "pirate_flag_charm") score += hpRatio > 0.55 ? 110 : 45;
    if (id === "seastone_bullet" || id === "seastone_handcuffs" || effect.kind === "devil_fruit_suppressor") score += isDevilFruitCharacter(card) ? -999 : 150;
    if (id === "devon_kyubi_mask") score += 260 + Math.max(attackStat, specialStat) * 0.8;
    if (id === SANJI_RAID_SUIT_ITEM_ID) {
      score += card.id === "sanji" && activeEvolutionForm(card)?.id === SANJI_RAID_SUIT_FORM_ID ? 900 : 130;
    }
    if (id === ENMA_ITEM_ID) {
      const formId = activeEvolutionForm(card)?.id || "";
      score += card.id === "zoro" && formId === ZORO_NEW_WORLD_FORM_ID
        ? 980
        : card.id === "zoro" && formId === ZORO_ZOROJURO_FORM_ID
          ? 620
          : 190 + attackStat * 1.15;
    }
    if (id === "griffon_sword") score += 270 + attackStat * 1.1 + moveProfile.physical * 25;
    if (id === "fearless_heart") score += 300 + moveProfile.attacks.length * 28;
    if (id === "sun_pirates_badge") score += 245 + (hpRatio < 0.7 ? 55 : 0);
    return score;
  }

  function devObserverTryEquipCarryItems(player) {
    if (!player || devObserverMapMaintenanceBlocked()) return "";
    ensurePlayerBattleCarryState(player);
    const entries = battleCarryInventoryEntries(player);
    if (!entries.length || !(player.crew || []).length) return "";
    const plans = [];
    entries.forEach(({ item, index }) => {
      (player.crew || []).forEach((card, cardIndex) => {
        if (!card) return;
        const validation = validateBattleCarryEquip(card, item);
        if (!validation.ok) return;
        if (isLockedBattleCarryItem(card.battleCarryItem)) return;
        const score = devObserverCarryScoreForCard(item, card, cardIndex, player);
        const current = normalizeBattleCarryItem(card.battleCarryItem);
        const currentScore = current ? devObserverCarryScoreForCard(current, card, cardIndex, player) : 0;
        const gain = score - currentScore;
        if (gain > (current ? 55 : 20)) plans.push({ item, inventoryIndex: index, card, cardIndex, score, gain });
      });
    });
    const best = plans.sort((a, b) => b.gain - a.gain || b.score - a.score)[0];
    if (!best) return "";
    const result = equipBattleCarryItemFromInventory(player, best.cardIndex, best.inventoryIndex);
    if (!result.ok) return "";
    recalcPlayerDerivedStats(player);
    renderAll();
    return `整備攜帶物：${cardDisplayName(best.card)} 裝備 ${battleCarryItemName(best.item)}。`;
  }

  function devObserverEvolutionCandidate(player) {
    if (!player || devObserverMapMaintenanceBlocked()) return null;
    return (player.crew || [])
      .map((card, index) => {
        if (!card) return null;
        syncCrewCardProgress(card);
        const form = nextEvolutionFormForCard(card);
        const status = evolutionRequirementStatus(player, card, form);
        if (!form || !status.ok) return null;
        const stage = Number(form.stage || 1);
        const activeBonus = Number(player.activeCrewIndex ?? 0) === index ? 90 : 0;
        return {
          card,
          index,
          form,
          score: devObserverCardScore(card) + stage * 260 + Number(card.level || 1) * 18 + activeBonus,
        };
      })
      .filter(Boolean)
      .sort((a, b) => b.score - a.score)[0] || null;
  }

  function devObserverTryEvolveCrew(player) {
    const candidate = devObserverEvolutionCandidate(player);
    if (!candidate) return "";
    void evolveCrewCard(player, candidate.index);
    return `進化整備：${cardDisplayName(candidate.card)} 進化為 ${candidate.form.name || candidate.form.displayName}。`;
  }

  function devObserverSkillTrainingPlan(player) {
    if (!player || devObserverMapMaintenanceBlocked()) return null;
    const itemDefs = Object.values(GAME_ITEMS || {})
      .filter((item) => item?.effect?.kind === "skill_training_material" && devObserverInventoryCount(player, item.id) > 0);
    if (!itemDefs.length) return null;
    const plans = [];
    itemDefs.forEach((itemDef) => {
      (player.crew || []).forEach((card, index) => {
        if (!card) return;
        const moveEntry = skillTrainingCandidate(card, itemDef);
        if (!moveEntry) return;
        const decision = devObserverMoveLearnReplacementDecision(card, moveEntry);
        if (!["learn", "replace"].includes(decision.type)) return;
        const gain = decision.type === "learn"
          ? devObserverMoveScoreForCard(card, moveEntry, [...getUnlockedMoves(card), moveEntry])
          : Number(decision.gain || 0);
        const activeBonus = Number(player.activeCrewIndex ?? 0) === index ? 24 : 0;
        const rarityBonus = devObserverRarityScore(itemDef);
        const ultimateBonus = itemDef.effect?.level === "ultimate" ? 80 : 0;
        plans.push({
          itemDef,
          card,
          index,
          moveEntry,
          decision,
          score: gain + rarityBonus + ultimateBonus + Number(card.level || 1) * 1.2 + activeBonus,
        });
      });
    });
    return plans.sort((a, b) => b.score - a.score)[0] || null;
  }

  function devObserverTryUseSkillTrainingItems(player) {
    const plan = devObserverSkillTrainingPlan(player);
    if (!plan) return "";
    applySkillTrainingItemToTarget(player, plan.itemDef.id, plan.index);
    return `招式整備：${cardDisplayName(plan.card)} 研讀 ${plan.itemDef.name}，準備學 ${plan.moveEntry.name}。`;
  }

  function devObserverCompletedMission(player) {
    return activeMissionEntries(player).find((entry) => entry.completed) || null;
  }

  function devObserverTryClaimCompletedMission(player) {
    if (!player || devObserverMapMaintenanceBlocked()) return "";
    const active = devObserverCompletedMission(player);
    const mission = missionDef(active);
    if (!active || !mission) return "";
    if (!claimActiveMissionReward(player, active.missionId)) return "";
    return `領取任務獎勵：${mission.title}。`;
  }

  function devObserverMissionGradeScore(mission) {
    return Math.max(0, Number(BOARD_MISSION_GRADE_RANK?.[mission?.grade || "E"] ?? 0)) * 72;
  }

  function devObserverMissionRewardScore(player, mission) {
    if (!mission) return -9999;
    const avgLevel = devObserverAverageCrewLevel(player);
    const coins = Math.max(0, Number(mission.coins || 0));
    const bounty = Math.max(0, Number(mission.bounty || 0));
    const exp = Math.max(0, Number(boostedMissionExp(mission) || 0));
    let score = devObserverMissionGradeScore(mission)
      + Math.min(260, coins / 170)
      + Math.min(220, bounty / 2200000)
      + Math.min(260, exp / 45);
    const special = String(mission.special || "");
    if (/大量經驗/.test(special)) score += avgLevel < 75 ? 150 : 75;
    if (/大量貝里/.test(special)) score += Number(player?.coins || 0) < 12000 ? 155 : 85;
    if (/大量懸賞/.test(special)) score += playerBountyValue(player) < 3000000000 ? 160 : 55;
    (mission.items || []).forEach((item) => {
      const def = missionRewardItemDef(item, mission);
      if (!def) return;
      score += devObserverRarityScore(def) * 0.65;
      const category = normalizeGameItemCategory(def.category);
      if (category === "held") score += 55;
      if (category === "ship") score += 85;
      if (def.effect?.kind === "skill_training_material") score += avgLevel >= 25 ? 70 : 25;
      if (/修行|奧義|記憶|進化|船|龍骨|廚房|引擎|瞭望/.test(`${def.name} ${def.id}`)) score += 55;
    });
    return score;
  }

  function devObserverMissionGoalScore(player, mission) {
    const goal = mission?.goal || {};
    const kind = goal.kind || "";
    const crewCount = (player?.crew || []).length;
    const hpRatio = crewAverageHpRatio(player);
    const ppRatio = devObserverAveragePpRatio(player);
    const avgLevel = devObserverAverageCrewLevel(player);
    const power = devObserverTeamPower(player);
    let score = 0;
    if (["sea_step", "sea_event", "sea_event_or_chest", "chest_open", "crew_exp", "crew_level"].includes(kind)) score += 155;
    if (["visit_island_kind", "island_service", "shop_buy", "hospital_service", "tavern_action"].includes(kind)) score += 170;
    if (kind === "tavern_action" && crewCount < TEAM_LIMIT) score += 140;
    if (kind === "shop_buy" && Number(player?.coins || 0) > devObserverShopReserve(player) + 800) score += 100;
    if (kind === "hospital_service" || kind === "medical_ticket_or_hospital") score += devObserverNeedsRecovery(player, true) ? 165 : 55;
    if (["battle_win", "no_ko_battle_win", "sea_battle_win", "enemy_island_win", "defeat_tier", "defeat_devil_fruit", "held_trigger"].includes(kind)) {
      score += crewCount >= 4 && hpRatio >= 0.52 && ppRatio >= 0.25 ? 175 : -80;
      if (avgLevel >= 35 || power >= 34) score += 75;
    }
    if (["judicial_phase", "judicial_clear"].includes(kind)) score += crewCount >= 4 && power >= 28 && hpRatio >= 0.62 ? 120 : -210;
    if (kind === "yonko_win") {
      const ready = devObserverFinalReadiness(player);
      score += ready.crewCount >= TEAM_LIMIT && ready.teamPower >= 62 && ready.avgLevel >= 58 && ready.hpRatio >= 0.7 ? 170 : -360;
    }
    if (kind === "old_era_trial") score += avgLevel >= 45 && power >= 45 ? 120 : -100;
    if (["use_item_category", "use_heal_item", "equip_held", "obtain_item"].includes(kind)) score += 80;
    return score;
  }

  function devObserverMissionScore(player, mission) {
    if (!mission) return -9999;
    if (player?.completedMissionIds?.includes(mission.id)) return -9999;
    if (activeMissionEntry(player, mission.id)) return -9999;
    return devObserverMissionRewardScore(player, mission) + devObserverMissionGoalScore(player, mission);
  }

  function devObserverBestMissionChoice(player, island) {
    normalizePlayerMissionState(player);
    if (!player || !island) return null;
    if (activeMissionEntries(player).length >= MISSION_ACTIVE_LIMIT) return null;
    ensureMissionBoardChoices(player, island);
    const acceptedThisVisit = Math.max(0, Number(player.missionBoardChoices?.acceptedThisVisit || 0));
    if (acceptedThisVisit >= MISSION_ACCEPT_PER_VISIT_LIMIT) return null;
    return (player.missionBoardChoices?.choices || [])
      .map(missionDef)
      .filter(Boolean)
      .map((mission) => ({ mission, score: devObserverMissionScore(player, mission) }))
      .sort((a, b) => b.score - a.score)[0]?.mission || null;
  }

  function devObserverMissionNeedScore(player) {
    if (!player) return 0;
    normalizePlayerMissionState(player);
    const active = activeMissionEntries(player);
    if (active.some((entry) => entry.completed)) return 120;
    if (active.length >= MISSION_ACTIVE_LIMIT) return 0;
    return 130 + Math.max(0, 4 - active.length) * 42;
  }

  function devObserverTryEnterMissionBoard(player) {
    if (!player || devObserverMapMaintenanceBlocked()) return "";
    const action = currentIslandServiceAction(player);
    if (action?.kind !== "mission") return "";
    if (!devObserverBestMissionChoice(player, action.island) && !devObserverCompletedMission(player)) return "";
    enterIslandService(action);
    return "進入任務牆，接取或領取適合目前進度的任務。";
  }

  function devObserverHandleMissionOverlay() {
    const player = currentPlayer();
    if (!player || !document.querySelector(".mission-board-modal .mission-shell, .mission-shell")) return "";
    const claimBtn = document.getElementById("claimMissionRewardBtn");
    if (isDevObserverClickable(claimBtn)) {
      const mission = missionDef(claimBtn.dataset.claimMission);
      claimBtn.click();
      return `任務牆：領取 ${mission?.title || "已完成任務"}。`;
    }
    const islandId = player.missionBoardChoices?.islandId || player.location?.islandId || "";
    const island = getIslandById(islandId);
    const best = devObserverBestMissionChoice(player, island);
    if (best) {
      const selectedId = document.querySelector(".mission-card.selected")?.dataset.missionSelect || "";
      if (selectedId !== best.id) {
        const cardBtn = Array.from(document.querySelectorAll("[data-mission-select]"))
          .find((node) => node?.dataset?.missionSelect === best.id);
        if (isDevObserverClickable(cardBtn)) {
          cardBtn.click();
          return `任務牆：查看 ${best.title}。`;
        }
      }
      const acceptBtn = document.getElementById("acceptMissionBtn");
      if (isDevObserverClickable(acceptBtn)) {
        acceptBtn.click();
        return `任務牆：接取 ${best.title}。`;
      }
    }
    const leaveBtn = document.getElementById("leaveMissionBoardBtn");
    if (isDevObserverClickable(leaveBtn)) {
      leaveBtn.click();
      return "任務牆：完成任務整理，離開任務島。";
    }
    return "";
  }

  function devObserverYonkoKeyForIsland(island, islandState = null) {
    const key = island?.glyphId || islandState?.enemyProfile?.key || "";
    return YONKO_BOSS_PROFILES[key] ? key : "";
  }

  function devObserverYonkoDefeated(island, islandState = null) {
    return Boolean(islandState?.isYonkoDefeated || islandState?.isDefeated || state.gameState?.yonkoStatus?.[island?.id]);
  }

  function devObserverHasCarryItemAnywhere(player, itemId) {
    if (!itemId || !player) return false;
    if (battleCarryInventoryEntries(player).some((entry) => entry.item?.id === itemId)) return true;
    return (player.crew || []).some((card) => cardHasBattleCarryItem(card, itemId));
  }

  function devObserverHasYonkoCounter(player, yonkoKey) {
    const itemId = ({
      yonko_shanks: "devon_kyubi_mask",
      yonko_kaido: "griffon_sword",
      yonko_bigmom: "fearless_heart",
      yonko_blackbeard: "sun_pirates_badge",
    })[yonkoKey];
    return devObserverHasCarryItemAnywhere(player, itemId);
  }

  function devObserverYonkoRouteScore(player, island, islandState, enemyRisk = null) {
    if (!player || !island) return 0;
    const key = devObserverYonkoKeyForIsland(island, islandState);
    if (devObserverYonkoDefeated(island, islandState)) {
      return devObserverPlayerHasYonkoGlyph(player, key)
        ? (devObserverFinalReadiness(player).hasRoads ? -170 : 10)
        : 720;
    }
    const profile = islandState?.enemyProfile || YONKO_BOSS_PROFILES[key] || yonkoBossProfileForIsland(island);
    const risk = enemyRisk || devObserverEnemyRisk(player, profile);
    const ready = devObserverFinalReadiness(player);
    const hasCounter = devObserverHasYonkoCounter(player, key);
    let score = 0;
    score += ready.crewCount >= TEAM_LIMIT ? 160 : -330;
    score += ready.hpRatio >= 0.75 && ready.ppRatio >= 0.45 ? 150 : -260;
    score += ready.teamPower >= Number(profile?.recommendedPower || 68) - (hasCounter ? 5 : 1) ? 230 : -250;
    score += ready.avgLevel >= (hasCounter ? 58 : 64) ? 120 : -160;
    score += hasCounter ? 165 : 0;
    score += risk?.isComfortable ? 300 : risk?.isRisky ? 40 : 150;
    if (risk?.isTooHard) score -= 360;
    if (!ROAD_PONEGLYPH_BY_GLYPH[key] || devObserverInventoryCount(player, ROAD_PONEGLYPH_BY_GLYPH[key].itemId) <= 0) score += 210;
    else score -= 80;
    const preferredOrder = ["yonko_blackbeard", "yonko_shanks", "yonko_kaido", "yonko_bigmom"];
    const orderIndex = preferredOrder.indexOf(key);
    if (orderIndex >= 0) score += (preferredOrder.length - orderIndex) * 12;
    return score;
  }

  function devObserverMissionRouteBonus(player, kind, target, targetState, enemyRisk) {
    if (!player) return 0;
    const missions = activeMissionEntries(player).map((entry) => ({ entry, mission: missionDef(entry) })).filter((entry) => entry.mission && !entry.entry.completed);
    if (!missions.length) return 0;
    let bonus = 0;
    missions.forEach(({ mission }) => {
      const goal = mission.goal || {};
      const goalKind = goal.kind || "";
      const goalIslandKind = goal.islandKind || "";
      const progressNeed = Math.max(1, Number(goal.target || 1));
      const progressWeight = 1 + Math.min(0.35, progressNeed / 12);
      let missionBonus = 0;
      if (goalKind === "visit_island_kind" && goalIslandKind === kind) missionBonus += 300;
      if (goalKind === "island_service" && isServiceIslandKind(kind)) missionBonus += 190;
      if (goalKind === "shop_buy" && kind === "shop") missionBonus += 260;
      if (goalKind === "hospital_service" && isMedicalServiceIslandKind(kind)) missionBonus += 250;
      if (goalKind === "medical_ticket_or_hospital" && isMedicalServiceIslandKind(kind)) missionBonus += 190;
      if (goalKind === "tavern_action" && kind === "tavern") missionBonus += 275;
      if (goalKind === "judicial_phase" || goalKind === "judicial_clear") {
        if (kind === "judicial") missionBonus += 360;
      }
      if (goalKind === "yonko_win" || goalKind === "judicial_clear_or_yonko_win") {
        if (kind === "yonko") missionBonus += devObserverYonkoRouteScore(player, target, targetState, enemyRisk) > 0 ? 430 : -140;
        if (kind === "judicial" && goalKind === "judicial_clear_or_yonko_win") missionBonus += 220;
      }
      if (goalKind === "enemy_island_win" && kind === "enemy") missionBonus += enemyRisk?.isTooHard ? -120 : 320;
      if (["battle_win", "no_ko_battle_win", "held_trigger", "defeat_devil_fruit", "defeat_tier", "old_era_trial"].includes(goalKind)) {
        if (["enemy", "yonko", "judicial", "impel_down", "marineford"].includes(kind)) {
          let fightBonus = enemyRisk?.isTooHard ? -90 : 210;
          if (goal.minRank || goal.minTier) {
            const profile = targetState?.enemyProfile || (kind === "yonko" ? yonkoBossProfileForIsland(target) : null);
            const tier = profile?.tier || profile?.rank || "";
            if (tier && tierRank(tier) <= tierRank(goal.minRank || goal.minTier)) fightBonus += 135;
            else fightBonus -= 80;
          }
          missionBonus += fightBonus;
        }
      }
      if (goalKind === "sea_battle_win" && kind === "event") missionBonus += 120;
      if (["sea_step", "sea_event", "sea_event_or_chest", "chest_open"].includes(goalKind)) missionBonus += 35;
      bonus += missionBonus * progressWeight;
    });
    return bonus;
  }

  function devObserverShipReserve(player) {
    if (!player) return 0;
    if ((player.crew || []).length < 4) return Math.min(TAVERN_RECRUIT_ROLL_COST, Math.max(0, Number(player.coins || 0) * 0.55));
    if ((player.crew || []).length < TEAM_LIMIT) return 1100;
    return devObserverNeedsRecovery(player, true) ? 500 : 0;
  }

  function devObserverWaterSevenAffordable(player, cost = {}, urgent = false) {
    if (!waterSevenCanSpendCost(player, cost)) return false;
    const berries = Math.max(0, Math.round(Number(cost.berries || 0)));
    return urgent || Math.max(0, Number(player?.coins || 0) - berries) >= devObserverShipReserve(player);
  }

  function devObserverShipGearScore(item, player) {
    if (!item) return -9999;
    const id = item.id;
    let score = devObserverRarityScore(item);
    const hpRatio = crewAverageHpRatio(player);
    if (id === "ship_dream_medical_galley") score += 430;
    if (id === "ship_adam_sub_keel") score += 380;
    if (id === "ship_cola_aux_engine") score += 345;
    if (id === "ship_bird_nest_tower") score += 310;
    if (id === "ship_stove_upgrade") score += 285;
    if (id === "ship_tailwind_sail") score += 260;
    if (id === "ship_reinforced_bottom_plate") score += 245;
    if (id === "ship_observer_spyglass") score += 230;
    if (id === "ship_ration_barrel") score += 205;
    if (id === "ship_coup_de_burst_port") score += 190;
    if (id === "ship_escape_ladder") score += 145;
    if (id === "ship_patch_canvas") score += 120;
    if (/galley|stove|ration/.test(id) && hpRatio < 0.72) score += 55;
    if (/engine|sail/.test(id) && (player?.crew || []).length < TEAM_LIMIT) score += 35;
    return score;
  }

  function devObserverOwnedShipGear(player) {
    const inventory = ensurePlayerInventoryState(player);
    return Object.values(GAME_ITEMS || {})
      .filter((item) => normalizeGameItemCategory(item?.category) === "ship" && item?.effect?.kind === "ship_equipment")
      .filter((item) => Math.max(0, Math.round(Number(inventory.items?.[item.id] || 0))) > 0);
  }

  function devObserverBestShipGearPlan(player) {
    const shipState = normalizePlayerShipState(player);
    const owned = devObserverOwnedShipGear(player);
    if (!owned.length) return null;
    const equipped = shipState.equippedGear.slice();
    const equippedSet = new Set(equipped.filter(Boolean));
    const equippedHasS = equipped.some((itemId) => itemRarityLabel(gameItemDef(itemId)?.rarity) === "S");
    const openIndex = equipped.findIndex((gearId, index) => index < shipState.slotsUnlocked && !gearId);
    const candidates = owned
      .filter((item) => !equippedSet.has(item.id))
      .map((item) => ({ item, score: devObserverShipGearScore(item, player) }))
      .sort((a, b) => b.score - a.score);
    if (!candidates.length) return null;
    const equipCandidate = candidates.find((entry) => itemRarityLabel(entry.item.rarity) !== "S" || !equippedHasS);
    if (openIndex >= 0 && equipCandidate) return { type: "equip", item: equipCandidate.item, score: equipCandidate.score };
    if (shipState.slotsUnlocked < Math.min(WATER_SEVEN_SLOT_COUNT, owned.length)) {
      const cost = WATER_SEVEN_SLOT_COSTS[shipState.slotsUnlocked];
      if (devObserverWaterSevenAffordable(player, cost, shipState.slotsUnlocked === 0)) return { type: "open-slot" };
    }
    const equippedRanked = equipped
      .map((itemId, slotIndex) => ({ item: gameItemDef(itemId), itemId, slotIndex }))
      .filter((entry) => entry.item)
      .map((entry) => ({ ...entry, score: devObserverShipGearScore(entry.item, player) }))
      .sort((a, b) => a.score - b.score);
    const best = candidates[0];
    const lowest = itemRarityLabel(best.item.rarity) === "S" && equippedHasS
      ? equippedRanked.find((entry) => itemRarityLabel(entry.item?.rarity) === "S")
      : equippedRanked[0];
    if (lowest && best.score >= lowest.score + 95) return { type: "replace", slotIndex: lowest.slotIndex, oldItem: lowest.item, item: best.item };
    return null;
  }

  function devObserverWaterSevenUpgradePart(player) {
    const shipState = normalizePlayerShipState(player);
    const priorities = [
      ["training", 0, 340], ["kitchen", 0, 315], ["watchtower", 0, 265], ["sail", 0, 190], ["rudder", 0, 185],
      ["training", 1, 270], ["watchtower", 1, 255], ["kitchen", 1, 235], ["rudder", 1, 170], ["sail", 1, 165],
      ["training", 2, 205], ["kitchen", 2, 190], ["watchtower", 2, 180], ["rudder", 2, 165], ["sail", 2, 160],
    ];
    return priorities
      .map(([part, level, score]) => ({ part, level, score, cost: WATER_SEVEN_UPGRADE_COSTS[part]?.[level] }))
      .filter((entry) => shipState.upgradeLevels[entry.part] === entry.level && entry.cost)
      .filter((entry) => devObserverWaterSevenAffordable(player, entry.cost, entry.level === 0 && (entry.part === "training" || entry.part === "kitchen")))
      .sort((a, b) => b.score - a.score)[0]?.part || "";
  }

  function devObserverApplyWaterSevenCommand(player, result) {
    if (!result?.ok) return "";
    recalcPlayerDerivedStats(player);
    renderAll();
    notifyWaterSevenWindow(player);
    return result.message || "水之七島整備完成一項操作。";
  }

  function devObserverTryWaterSevenAction(player) {
    if (!player) return "";
    normalizePlayerShipState(player);
    const gearPlan = devObserverBestShipGearPlan(player);
    if (gearPlan?.type === "equip") {
      return devObserverApplyWaterSevenCommand(player, waterSevenCommandEquipGear(player, gearPlan.item.id))
        || "";
    }
    if (gearPlan?.type === "open-slot") {
      return devObserverApplyWaterSevenCommand(player, waterSevenCommandOpenSlot(player))
        || "";
    }
    if (gearPlan?.type === "replace") {
      return devObserverApplyWaterSevenCommand(player, waterSevenCommandUnequipSlot(player, gearPlan.slotIndex))
        || "";
    }
    const upgradePart = devObserverWaterSevenUpgradePart(player);
    if (upgradePart) {
      return devObserverApplyWaterSevenCommand(player, waterSevenCommandUpgrade(player, upgradePart))
        || "";
    }
    return "";
  }

  function devObserverHandleWaterSevenOverlay() {
    const overlay = document.getElementById("waterSevenPageOverlay");
    if (!overlay?.classList.contains("open")) return "";
    const player = currentPlayer();
    const action = devObserverTryWaterSevenAction(player);
    if (action) return `水之七島：${action}`;
    closeWaterSevenPageOverlay();
    return "水之七島整備完成，離開船塢。";
  }

  function devObserverBestLivingCrewEntry(player, view = null) {
    return (player?.crew || [])
      .map((card, index) => ({ card, index, score: view ? devObserverBattleCrewScore(card, view) : devObserverCardScore(card) }))
      .filter((entry) => Number(entry.card?.currentHp || 0) > 0)
      .sort((a, b) => b.score - a.score)[0] || null;
  }

  function devObserverScoreImpelPrisoner(player, prisoner) {
    if (!prisoner) return -9999;
    const card = cloneImpelDownPrisonerCard(player, prisoner);
    return devObserverCardScore(card) + Math.max(0, Number(prisoner.unlockLevel || 1)) * 90;
  }

  function devObserverBestImpelRecruit(player) {
    return impelDownRecruitPool(player)
      .map((prisoner) => ({ prisoner, score: devObserverScoreImpelPrisoner(player, prisoner) }))
      .sort((a, b) => b.score - a.score)[0]?.prisoner || null;
  }

  function devObserverShouldRecruitInImpelDown(player, prisoner) {
    if (!player || !prisoner) return false;
    const crewCount = (player.crew || []).length;
    if (crewCount < 4) return true;
    if (crewCount >= TEAM_LIMIT) return false;
    const prison = normalizeImpelDownState(player);
    const deepEnough = Number(prison.level || 1) >= 4;
    const healthyEnough = crewAverageHpRatio(player) >= 0.74 && devObserverAveragePpRatio(player) >= 0.36;
    if (!deepEnough || !healthyEnough) return false;
    const weakest = devObserverWeakestCrew(player);
    return weakest ? devObserverScoreImpelPrisoner(player, prisoner) >= weakest.score + 260 : false;
  }

  function devObserverHandleImpelRecruitModal() {
    const player = currentPlayer();
    if (!player) return "";
    const acceptBtn = document.getElementById("acceptImpelRecruitBtn");
    if (isDevObserverClickable(acceptBtn)) {
      const prison = normalizeImpelDownState(player);
      const prisoner = impelDownPrisonerDef(prison?.pendingRecruitId || prison?.lastRecruitId);
      acceptBtn.click();
      return `推進城招募：收下 ${prisoner?.name || "隱藏囚犯"}。`;
    }
    const replaceButtons = Array.from(document.querySelectorAll("[data-impel-replace-crew]")).filter(isDevObserverClickable);
    if (replaceButtons.length) {
      const prison = normalizeImpelDownState(player);
      const prisoner = impelDownPrisonerDef(prison?.pendingRecruitId || prison?.lastRecruitId);
      const recruitScore = devObserverScoreImpelPrisoner(player, prisoner);
      const weakest = devObserverWeakestCrew(player);
      const shouldReplace = weakest && recruitScore >= weakest.score + 150;
      if (shouldReplace) {
        const button = replaceButtons.find((node) => Number(node.dataset.impelReplaceCrew) === weakest.index) || replaceButtons[0];
        button.click();
        return `推進城招募替換：${prisoner?.name || "隱藏囚犯"} > ${cardDisplayName(weakest.card)}。`;
      }
      const rejectFullBtn = document.getElementById("rejectFullImpelRecruitBtn");
      if (isDevObserverClickable(rejectFullBtn)) {
        rejectFullBtn.click();
        return `推進城招募：放棄 ${prisoner?.name || "隱藏囚犯"}，未明顯優於現有隊伍。`;
      }
    }
    const rejectBtn = document.getElementById("rejectImpelRecruitBtn");
    if (isDevObserverClickable(rejectBtn) && (player.crew || []).length >= TEAM_LIMIT) {
      rejectBtn.click();
      return "推進城招募：隊伍已滿，放棄隱藏囚犯。";
    }
    return "";
  }

  function devObserverHandleImpelDownOverlay() {
    const overlay = document.getElementById("impelDownPageOverlay");
    if (!overlay?.classList.contains("open")) return "";
    const player = currentPlayer();
    if (!player || !isPlayerInImpelDown(player)) {
      closeImpelDownPageOverlay();
      return "推進城狀態已結束，關閉推進城畫面。";
    }
    if (state.battleState || state.gameState.resolutionLock) return "";
    const prison = normalizeImpelDownState(player);
    const bestLeader = devObserverBestLivingCrewEntry(player);
    if (bestLeader && bestLeader.index !== Number(player.activeCrewIndex || 0)) {
      const current = player.crew?.[player.activeCrewIndex] || null;
      const currentHpRatio = Number(current?.currentHp || 0) / Math.max(1, Number(current?.maxHp || current?.baseStats?.hp || 1));
      if (currentHpRatio < 0.38 || devObserverCardScore(bestLeader.card) >= devObserverCardScore(current) + 180) {
        impelSwitchLeader(bestLeader.index);
        return `推進城：換 ${cardDisplayName(bestLeader.card)} 當隊長。`;
      }
    }
    if (prison.pendingRecruitId) {
      impelEndTurn();
      return "推進城：結算隱藏囚犯招募結果。";
    }
    if (prison.status === "locked") {
      const result = impelRollEscape();
      if (!result) return "";
      if (!result.success) {
        impelEndTurn();
        return `推進城：逃籠失敗（${result.total}/${result.target}），結束本回合等下次加成。`;
      }
      return `推進城：逃籠成功（${result.total}/${result.target}），準備抽事件。`;
    }
    if (prison.status === "free" || prison.status === "wait_event") {
      const eventDef = impelDrawEvent();
      return eventDef ? `推進城：抽到事件「${eventDef.title}」。` : "";
    }
    if (prison.status === "event") {
      const eventDef = impelDownEventById(prison.eventId);
      const safeFight = (player.crew || []).length >= 3
        && crewAverageHpRatio(player) >= 0.46
        && devObserverAveragePpRatio(player) >= 0.18;
      if (["patrol", "magellan"].includes(eventDef?.id) && !safeFight) {
        impelResolveEventSecondary();
        return `推進城：狀態不足，避開「${eventDef.title}」並結束回合。`;
      }
      impelResolveEventPrimary();
      return `推進城：處理事件「${eventDef?.title || "未知事件"}」。`;
    }
    if (prison.status === "move") {
      if (prison.allowEscape) {
        impelDirectEscape();
        return "推進城：可直接逃出，優先安全撤離。";
      }
      const result = impelMove("up");
      return result ? "推進城：往上逃離。" : "";
    }
    if (prison.status === "recruit") {
      const best = devObserverBestImpelRecruit(player);
      const reserve = devObserverRecruitReserve(player);
      if (!best || !devObserverShouldRecruitInImpelDown(player, best) || player.coins < IMPEL_DOWN_RECRUIT_DRAW_COST + reserve) {
        impelSkipRecruit();
        return "推進城：逃獄優先，放棄隱藏囚犯招募。";
      }
      if (prison.focusRecruitId !== best.id) {
        impelSelectRecruit(best.id);
        return `推進城：鎖定隱藏囚犯 ${best.name}。`;
      }
      const boostCost = Number(best.unlockLevel || 1) * IMPEL_DOWN_RECRUIT_BOOST_UNIT_COST;
      const currentBoost = impelDownRecruitBoost(player, best);
      if (currentBoost < Math.min(2, IMPEL_DOWN_MAX_RECRUIT_BOOST)
        && player.coins >= IMPEL_DOWN_RECRUIT_DRAW_COST + boostCost + reserve) {
        impelBoostRecruit();
        return `推進城：提高 ${best.name} 抽中率。`;
      }
      impelDrawRecruit();
      return `推進城：抽選隱藏囚犯，目標 ${best.name}。`;
    }
    closeImpelDownPageOverlay();
    return "推進城：沒有可處理狀態，先關閉畫面。";
  }

  function devObserverMarinefordCardScore(cardId) {
    return devObserverCardScore(marinefordCardEntry(cardId));
  }

  function devObserverBestMarinefordWhitebeardIds(limit = 4) {
    const unavailable = marinefordUnavailableWhitebeardIds();
    return Array.from(WHITEBEARD_RECRUIT_CARD_IDS)
      .filter((id) => !unavailable.has(id))
      .map((id) => ({ id, score: devObserverMarinefordCardScore(id) }))
      .sort((a, b) => b.score - a.score)
      .slice(0, limit)
      .map((entry) => entry.id);
  }

  function devObserverHandleMarinefordOverlay() {
    const overlay = document.getElementById("marinefordPageOverlay");
    if (!overlay?.classList.contains("open")) return "";
    const player = currentPlayer();
    if (!player || !isPlayerInMarineford(player)) {
      closeMarinefordPageOverlay();
      return "頂上戰爭狀態已結束，關閉畫面。";
    }
    if (state.battleState || state.gameState.resolutionLock) return "";
    const hold = normalizeMarinefordHold(player);
    if (!hold.rulesShown) {
      hold.rulesShown = true;
      notifyMarinefordWindow(player);
      return "頂上戰爭：略過規則，開始處理救援。";
    }
    if (hold.finished) {
      if (hold.win) {
        const joinableIndex = (hold.slots || []).findIndex((slot) => slot?.cardId && slot.canJoinOnWin && WHITEBEARD_RECRUIT_CARD_IDS.has(slot.cardId));
        if (joinableIndex >= 0) {
          const slot = hold.slots[joinableIndex];
          const recruitScore = devObserverMarinefordCardScore(slot.cardId);
          if ((player.crew || []).length < TEAM_LIMIT) {
            marinefordJoinSlot(player, joinableIndex);
            return `頂上戰爭：收下 ${cardDisplayName(marinefordCardEntry(slot.cardId))}。`;
          }
          const weakest = devObserverWeakestCrew(player);
          if (weakest && recruitScore >= weakest.score + 180) {
            marinefordJoinSlot(player, joinableIndex, weakest.index);
            return `頂上戰爭：讓 ${cardDisplayName(marinefordCardEntry(slot.cardId))} 替換 ${cardDisplayName(weakest.card)}。`;
          }
          marinefordDeclineSlot(player, joinableIndex);
          return `頂上戰爭：放棄 ${cardDisplayName(marinefordCardEntry(slot.cardId))}，現有隊伍較適合。`;
        }
      }
      marinefordClose(player);
      return hold.win ? "頂上戰爭：獎勵與招募處理完成，離開海軍本部。" : "頂上戰爭：救援失敗或已結束，回到羅格鎮重新出發。";
    }
    if (hold.setupStep === "drawCrew") {
      const captured = (player.crew || [])
        .map((card, index) => ({ card, index, score: devObserverCardScore(card) }))
        .filter((entry) => entry.card)
        .sort((a, b) => a.score - b.score)
        .slice(0, Math.max(1, Math.min(2, (player.crew || []).length)))
        .map((entry, index) => ({
          playerId: player.id,
          playerName: player.name,
          cardId: entry.card.id,
          source: "crew",
          cleanOnLoss: true,
          canJoinOnWin: false,
          roundsLeft: marinefordExecutionTurnsFor(index),
        }));
      if (!captured.length) {
        marinefordClose(player);
        return "頂上戰爭：沒有可放上處刑台的角色，關閉畫面。";
      }
      marinefordApplyCrewDraw(player, captured);
      return "頂上戰爭：處刑台抽籤完成，保留主力出戰。";
    }
    if (hold.setupStep === "chooseExecution") {
      const cardId = devObserverBestMarinefordWhitebeardIds(1)[0];
      if (!cardId) {
        marinefordClose(player);
        return "頂上戰爭：沒有可用白鬍子成員，關閉畫面。";
      }
      marinefordAssignExecution(player, hold.selectedSlotIndex || 0, cardId);
      return `頂上戰爭：選擇 ${cardDisplayName(marinefordCardEntry(cardId))} 上處刑台。`;
    }
    if (hold.setupStep === "drawSupport") {
      const helpers = devObserverBestMarinefordWhitebeardIds(1).map((cardId) => ({
        playerId: player.id,
        playerName: player.name,
        cardId,
        source: "support",
        temporary: true,
      }));
      marinefordApplySupportDraw(player, helpers);
      return "頂上戰爭：抽出白鬍子海賊團支援。";
    }
    if (devObserverNeedsRecovery(player, true) && !hold.hormoneUsed?.[player.id]) {
      marinefordUseHormone(player, player.id);
      return "頂上戰爭：使用賀爾蒙注射，補滿 HP / PP。";
    }
    if (hold.setupStep === "ready" || hold.started) {
      const result = startMarinefordBattle(player);
      return result?.ok ? `頂上戰爭：開始第 ${hold.bossIndex + 1} 戰。` : "頂上戰爭：等待開戰條件。";
    }
    return "";
  }

  function devObserverTryEnterWaterSeven(player) {
    if (!player || devObserverMapMaintenanceBlocked()) return "";
    const action = currentIslandServiceAction(player);
    if (action?.island?.id !== WATER_SEVEN_ISLAND_ID) return "";
    if (!devObserverHasWaterSevenWork(player)) return "";
    enterIslandService(action);
    return "進入水之七島船塢，檢查船裝、開孔與永久升級。";
  }

  function devObserverHasWaterSevenWork(player) {
    if (!player) return false;
    normalizePlayerShipState(player);
    return !!devObserverBestShipGearPlan(player) || !!devObserverWaterSevenUpgradePart(player);
  }

  function devObserverShouldRollTavern(player) {
    if (!player) return false;
    if ((player.crew || []).length >= TEAM_LIMIT) return false;
    if (player.coins < TAVERN_RECRUIT_ROLL_COST) return false;
    if (!tavernRecruitRollPool(tavernRecruitPool(player), player).length) return false;
    if ((player.crew || []).length <= 3) return true;
    return player.coins >= TAVERN_RECRUIT_ROLL_COST + devObserverRecruitReserve(player);
  }

  function devObserverShopReserve(player) {
    if (!player) return 0;
    if ((player.crew || []).length < TEAM_LIMIT) return Math.min(TAVERN_RECRUIT_ROLL_COST, Math.max(0, player.coins * 0.45));
    return devObserverNeedsRecovery(player, true) ? 0 : 500;
  }

  function devObserverDesiredShopItemId(player) {
    if (!player) return "";
    const hpRatio = crewAverageHpRatio(player);
    const reserve = devObserverShopReserve(player);
    const candidateIds = [
      { id: "heal_2", target: hpRatio < 0.55 ? 10 : 6, urgent: hpRatio < 0.55 },
      { id: "battle_food", target: hpRatio < 0.7 ? 4 : 2, urgent: hpRatio < 0.45 },
      { id: "guard_charm", target: 2, urgent: false },
      { id: "fixed_step", target: (player.crew || []).length >= 4 ? 2 : 1, urgent: false },
      { id: "pointer", target: 1, urgent: false },
    ];
    return candidateIds.find(({ id, target, urgent }) => {
      const item = SHOP_ITEM_BY_ID[id];
      if (!item || !itemUnlockedByBounty(player, id)) return false;
      if (devObserverInventoryCount(player, id) >= target) return false;
      const cost = Math.max(1, Math.round(item.cost * (1 - getTeamEffects(player).shopDiscount)));
      return player.coins >= cost + (urgent ? 0 : reserve);
    })?.id || "";
  }

  function devObserverHandleShopModal() {
    const player = currentPlayer();
    if (!player) return "";
    const qtyConfirm = document.getElementById("shopQtyConfirm");
    if (isDevObserverClickable(qtyConfirm)) {
      qtyConfirm.click();
      return "確認購買補給。";
    }
    const shopBuyBtn = document.getElementById("shopBuyBtn");
    const leaveShopBtn = document.getElementById("leaveShopBtn") || document.getElementById("leaveShopListBtn");
    if (!shopBuyBtn && !leaveShopBtn) return "";
    const desiredId = devObserverDesiredShopItemId(player);
    if (desiredId) {
      const selected = document.querySelector(".shop-item-row.is-selected")?.dataset?.shopSelect || "";
      if (selected !== desiredId) {
        const row = Array.from(document.querySelectorAll("[data-shop-select]"))
          .find((node) => node.dataset.shopSelect === desiredId && isDevObserverClickable(node));
        if (row) {
          row.click();
          return `選擇商店補給：${SHOP_ITEM_BY_ID[desiredId]?.name || desiredId}`;
        }
      }
      if (isDevObserverClickable(shopBuyBtn) && !shopBuyBtn.disabled) {
        shopBuyBtn.click();
        return `購買補給：${SHOP_ITEM_BY_ID[desiredId]?.name || desiredId}`;
      }
    }
    if (isDevObserverClickable(leaveShopBtn)) {
      leaveShopBtn.click();
      return "補給已足或資金需保留，離開商店。";
    }
    return "";
  }

  function devObserverHandleHospitalModal() {
    const player = currentPlayer();
    if (!player) return "";
    const serviceBtn = Array.from(document.querySelectorAll("[data-hospital-service]")).find(isDevObserverClickable);
    const leaveBtn = document.getElementById("leaveHospitalBtn");
    if (!serviceBtn && !leaveBtn) return "";
    if (serviceBtn && devObserverNeedsRecovery(player, true)) {
      serviceBtn.click();
      return "醫院整備：恢復全隊 HP / PP。";
    }
    if (isDevObserverClickable(leaveBtn)) {
      leaveBtn.click();
      return "隊伍狀態良好，離開醫院。";
    }
    return "";
  }

  function devObserverDesiredResearchLabExtractor(player) {
    if (!player) return null;
    const lab = ensurePlayerResearchLabState(player);
    const level = lab.researchLevel;
    const targetCounts = {
      lineage_extractor_standard: 3,
      lineage_extractor_precision: 2,
      lineage_extractor_resonance_power: 1,
      lineage_extractor_resonance_skill: 1,
      lineage_extractor_resonance_speed: 1,
      lineage_extractor_ability: 1,
      lineage_extractor_emperor: 1,
    };
    return RESEARCH_LAB_EXTRACTOR_DEFS.find((config) => {
      if (level < config.unlockLevel || inventoryItemCount(player, config.id) >= (targetCounts[config.id] || 1)) return false;
      if (Number(player.coins || 0) < config.price + (config.id === RESEARCH_LAB_STANDARD_EXTRACTOR_ID ? 0 : 1200)) return false;
      return config.mode !== "craft" || lab.researchPoints >= config.researchPointCost;
    }) || null;
  }

  function devObserverHandleResearchLabModal() {
    const player = currentPlayer();
    if (!player) return "";
    const healBtn = document.querySelector("[data-research-action='heal']");
    const leaveBtn = document.getElementById("leaveResearchLabBtn");
    if (!healBtn && !leaveBtn) return "";
    if (isDevObserverClickable(healBtn) && devObserverNeedsRecovery(player, true)) {
      healBtn.click();
      return "研究所整備：恢復全隊 HP / PP。";
    }
    const desired = devObserverDesiredResearchLabExtractor(player);
    if (desired) {
      const acquireBtn = document.querySelector(`[data-research-acquire="${desired.id}"]`);
      if (isDevObserverClickable(acquireBtn)) {
        acquireBtn.click();
        return `研究所補給：${desired.mode === "craft" ? "製作" : "購買"} ${gameItemDef(desired.id)?.name || desired.id}。`;
      }
      const supplyTab = document.querySelector("[data-research-tab='supply']");
      if (isDevObserverClickable(supplyTab)) {
        supplyTab.click();
        return "前往科研補給區。";
      }
    }
    if (isDevObserverClickable(leaveBtn)) {
      leaveBtn.click();
      return "研究所作業完成，返回航程。";
    }
    return "";
  }

  function devObserverScoreSeaChoiceButton(button, player) {
    const typeId = button?.dataset?.seaType || "unknown";
    const hpRatio = crewAverageHpRatio(player);
    const crewCount = (player?.crew || []).length;
    const teamPower = devObserverTeamPower(player);
    const strategy = cpuStrategyForPlayer(player);
    const text = button?.closest(".choice-card")?.textContent || button?.textContent || "";
    const lowResource = player.coins < TAVERN_RECRUIT_ROLL_COST || crewCount < TEAM_LIMIT;
    const readyForFight = crewCount >= 4 && hpRatio >= 0.62 && teamPower >= 18;
    let score = 0;
    if (typeId === "medicine") score += hpRatio < 0.75 ? 150 : 55;
    if (typeId === "money") score += lowResource ? 130 : 60;
    if (typeId === "treasure" || typeId === "chest") score += hpRatio < 0.45 ? 20 : 90;
    if (typeId === "encounter") score += readyForFight ? 80 : -180;
    if (typeId === "weather") score += hpRatio < 0.55 ? -95 : 10;
    if (typeId === "unknown") score -= hpRatio < 0.65 ? 80 : 20;
    if (strategy === "level") {
      if (typeId === "encounter") score += readyForFight ? 150 : 20;
      if (typeId === "treasure" || typeId === "chest") score += 45;
    }
    if (strategy === "support") {
      if (typeId === "medicine") score += 110;
      if (typeId === "money") score += 45;
      if (typeId === "encounter") score += readyForFight ? 35 : -45;
    }
    if (strategy === "objective") {
      if (typeId === "treasure" || typeId === "chest") score += 95;
      if (typeId === "encounter") score += readyForFight ? 85 : -35;
    }
    if (/恢復|獲得|貝里|補給|寶箱|前進|賞金|線索|指定步數/.test(text)) score += 70;
    if (/陷阱|損失|失去|扣|副作用|暴風|逆風|海軍|傳送/.test(text)) score -= hpRatio < 0.8 ? 130 : 65;
    return score;
  }

  function devObserverHandleSeaChoice() {
    const player = currentPlayer();
    const buttons = Array.from(document.querySelectorAll("[data-sea-choice]")).filter(isDevObserverClickable);
    if (!player || !buttons.length) return "";
    const byChoice = new Map();
    buttons.forEach((button) => {
      const key = button.dataset.seaChoice || `${button.dataset.seaType}-${byChoice.size}`;
      if (!byChoice.has(key)) byChoice.set(key, button);
    });
    const ranked = Array.from(byChoice.values())
      .map((button) => ({ button, score: devObserverScoreSeaChoiceButton(button, player) }))
      .sort((a, b) => b.score - a.score);
    const best = ranked[0]?.button;
    if (!best) return "";
    const label = SEA_EVENT_TYPE_INFO[best.dataset.seaType]?.type || best.dataset.seaType || "未知";
    best.click();
    return `海格二選一：選 ${label}（策略分 ${Math.round(ranked[0].score)}）。`;
  }

  function devObserverHandleTavernModal() {
    const player = currentPlayer();
    if (!player) return "";

    const acceptBtn = document.getElementById("acceptRecruitBtn");
    if (isDevObserverClickable(acceptBtn)) {
      const recruit = devObserverFindRecruitFromResult(player);
      acceptBtn.click();
      return `收下招募：${recruit ? cardDisplayName(recruit) : "新夥伴"}`;
    }

    const replaceButtons = Array.from(document.querySelectorAll("[data-replace-crew]")).filter(isDevObserverClickable);
    if (replaceButtons.length) {
      const recruit = devObserverFindRecruitFromResult(player);
      const recruitScore = devObserverCardScore(recruit);
      const weakest = devObserverWeakestCrew(player);
      const shouldReplace = weakest && recruitScore >= weakest.score + 180;
      if (shouldReplace) {
        const button = replaceButtons.find((node) => Number(node.dataset.replaceCrew) === weakest.index) || replaceButtons[0];
        button.click();
        return `招募替換：${cardDisplayName(recruit)} > ${cardDisplayName(weakest.card)}`;
      }
      const rejectFullBtn = document.getElementById("rejectFullRecruitBtn");
      if (isDevObserverClickable(rejectFullBtn)) {
        rejectFullBtn.click();
        return `放棄招募：${recruit ? cardDisplayName(recruit) : "新夥伴"} 未明顯優於現有隊伍`;
      }
    }

    const rejectBtn = document.getElementById("rejectRecruitBtn");
    if (isDevObserverClickable(rejectBtn) && (player.crew || []).length >= TEAM_LIMIT) {
      rejectBtn.click();
      return "隊伍已滿，放棄一般招募。";
    }

    const rollBtn = document.getElementById("rollRecruitBtn");
    const leaveTavernBtn = document.getElementById("leaveTavernBtn");
    if (rollBtn || leaveTavernBtn) {
      if (isDevObserverClickable(rollBtn) && devObserverShouldRollTavern(player)) {
        rollBtn.click();
        return `花 ${formatCoin(TAVERN_RECRUIT_ROLL_COST)} 貝里招募（隊伍 ${(player.crew || []).length}/${TEAM_LIMIT}）。`;
      }
      if (isDevObserverClickable(leaveTavernBtn)) {
        leaveTavernBtn.click();
        return player.coins < TAVERN_RECRUIT_ROLL_COST
          ? `貝里不足招募（${formatCoin(player.coins)}），離開酒館。`
          : `保留資金，不在酒館花費（隊伍 ${(player.crew || []).length}/${TEAM_LIMIT}）。`;
      }
    }

    return "";
  }

  function devObserverHandleFinalEndingCinematic() {
    const screen = document.querySelector(".final-ending-screen.final-ending-cinematic");
    if (!screen) return "";
    const nextButton = document.getElementById("finalEndingNextBtn");
    if (isDevObserverClickable(nextButton)) {
      nextButton.click();
      return nextButton.textContent?.trim() || "推進結局劇情。";
    }
    const dialogue = screen.querySelector(".final-ending-dialogue");
    if (isDevObserverClickable(dialogue)) {
      dialogue.click();
      return dialogue.classList.contains("waiting") ? "解除劇情等待鎖。" : "推進劇情對話。";
    }
    if (isDevObserverClickable(screen)) {
      screen.click();
      return "推進全螢幕劇情。";
    }
    return "";
  }

  function cpuStrategyShouldJoinCoop(player, battle) {
    if (!isCpuPlayer(player)) return true;
    const strategy = cpuStrategyForPlayer(player);
    const hpRatio = crewAverageHpRatio(player);
    const ppRatio = devObserverAveragePpRatio(player);
    const hasHumanParticipant = coopBattleParticipants(battle).some((entry) => !isCpuPlayer(entry));
    if (strategy === "support") return hpRatio >= 0.28 || hasHumanParticipant;
    if (["enemy", "postgame_boss", "postgame_egghead"].includes(battle?.islandKind)) return true;
    if (strategy === "level") return hpRatio >= 0.5 && ppRatio >= 0.18;
    if (strategy === "objective") return hasHumanParticipant && hpRatio >= 0.55 && ppRatio >= 0.24;
    return hasHumanParticipant ? hpRatio >= 0.42 : hpRatio >= 0.62 && ppRatio >= 0.22;
  }

  function devObserverHandleCoopBattlePrompt() {
    const prompt = state.gameState?.coopBattlePrompt;
    const player = currentPlayer();
    if (!prompt || !player || String(prompt.playerId || "") !== String(player.id || "")) return "";
    const joinBtn = document.getElementById("joinCoopBattleBtn");
    const skipBtn = document.getElementById("skipCoopBattleBtn");
    if (!joinBtn && !skipBtn) return "";
    const battle = activeCoopBattleAtPlayerLocation(player);
    const shouldJoin = cpuStrategyShouldJoinCoop(player, battle);
    if (shouldJoin && isDevObserverClickable(joinBtn)) {
      joinBtn.click();
      return `${player.name} 依「${cpuStrategyLabel(cpuStrategyForPlayer(player))}」指令加入共鬥。`;
    }
    if (!shouldJoin && isDevObserverClickable(skipBtn)) {
      skipBtn.click();
      return `${player.name} 依「${cpuStrategyLabel(cpuStrategyForPlayer(player))}」指令略過共鬥。`;
    }
    if (isDevObserverClickable(joinBtn)) {
      joinBtn.click();
      return "同島共鬥不能略過，加入戰鬥。";
    }
    return "";
  }

  function devObserverHandlePostgameEncounterModal() {
    const player = currentPlayer();
    const lokiChallenge = document.getElementById("elbaphLokiChallengeBtn");
    const lokiLeave = document.getElementById("elbaphLokiLeaveBtn");
    const bossChallenge = document.getElementById("postgameBossChallengeBtn");
    const bossLeave = document.getElementById("postgameBossLeaveBtn");
    const rocksChallenge = document.getElementById("postgameRocksChallengeBtn");
    const rocksLeave = document.getElementById("postgameRocksLeaveBtn");
    const challengeButton = lokiChallenge || rocksChallenge || bossChallenge;
    const leaveButton = lokiLeave || rocksLeave || bossLeave;
    if (!player || (!challengeButton && !leaveButton)) return "";
    if (isDevObserverClickable(challengeButton) && devObserverAliveCrew(player).length > 0) {
      const targetName = lokiChallenge ? "洛基王子試煉" : rocksChallenge ? "洛克斯" : "全破後 Boss";
      challengeButton.click();
      return `${player.name} 已完成基本整備，開始挑戰${targetName}。`;
    }
    if (isDevObserverClickable(leaveButton)) {
      leaveButton.click();
      return `${player.name} 沒有可戰鬥船員，先離島整備。`;
    }
    return "";
  }

  function devObserverHandlePendingIslandServiceChoice() {
    const player = currentPlayer();
    const action = pendingIslandServiceChoiceAction(player);
    if (!action || !isCpuPlayer(player) || !canLocalDriveCpuPlayer(player)) return "";
    const choiceModalOpen = Boolean(refs.modal?.querySelector(".island-service-choice-ui"));
    if (refs.modalBack?.classList.contains("open") && !choiceModalOpen) return "";
    const decision = cpuShouldEnterPendingIslandService(action) ? "enter" : "roll";
    if (!resolvePendingIslandServiceChoice(action, decision, { cpu: true })) return "";
    return decision === "enter"
      ? `${player.name} 選擇進入${action.label}。`
      : `${player.name} 選擇略過${action.label}並擲骰出發。`;
  }

  function devObserverHandleVisibleOverlay() {
    const cpuMoveLearnTarget = devObserver.running ? null : cpuAutomationTargetPlayer();
    const moveLearnAction = devObserverHandleMoveLearnChoice(cpuMoveLearnTarget
      ? { playerId: cpuMoveLearnTarget.id, cpuOnly: true }
      : {});
    if (moveLearnAction) return moveLearnAction;
    const pendingIslandServiceAction = devObserverHandlePendingIslandServiceChoice();
    if (pendingIslandServiceAction) return pendingIslandServiceAction;
    const coopPromptAction = devObserverHandleCoopBattlePrompt();
    if (coopPromptAction) return coopPromptAction;
    const finalEndingAction = devObserverHandleFinalEndingCinematic();
    if (finalEndingAction) return finalEndingAction;
    if (refs.itemRevealHud?.classList.contains("show")) {
      refs.itemRevealContinue?.click();
      return "收下道具獎勵。";
    }
    if (refs.evolutionHud?.classList.contains("show")) {
      refs.evolutionHudContinue?.click();
      return "略過進化演出。";
    }
    const waterSevenAction = devObserverHandleWaterSevenOverlay();
    if (waterSevenAction) return waterSevenAction;
    const impelRecruitAction = devObserverHandleImpelRecruitModal();
    if (impelRecruitAction) return impelRecruitAction;
    const impelAction = devObserverHandleImpelDownOverlay();
    if (impelAction) return impelAction;
    const marinefordAction = devObserverHandleMarinefordOverlay();
    if (marinefordAction) return marinefordAction;
    const tavernAction = devObserverHandleTavernModal();
    if (tavernAction) return tavernAction;
    const researchLabAction = devObserverHandleResearchLabModal();
    if (researchLabAction) return researchLabAction;
    const postgameEncounterAction = devObserverHandlePostgameEncounterModal();
    if (postgameEncounterAction) return postgameEncounterAction;
    const hospitalAction = devObserverHandleHospitalModal();
    if (hospitalAction) return hospitalAction;
    const shopAction = devObserverHandleShopModal();
    if (shopAction) return shopAction;
    const missionAction = devObserverHandleMissionOverlay();
    if (missionAction) return missionAction;
    const seaChoiceAction = devObserverHandleSeaChoice();
    if (seaChoiceAction) return seaChoiceAction;
    const yonkoStart = document.getElementById("yonkoStoryStartBtn");
    const yonkoLeave = document.getElementById("yonkoStoryLeaveBtn");
    if (yonkoStart && yonkoLeave) {
      const player = currentPlayer();
      const island = getIslandById(player?.location?.islandId);
      const islandState = island ? getIslandState(island.id) : null;
      if (!devObserverShouldChallengeYonkoNow(player, island, islandState) && isDevObserverClickable(yonkoLeave)) {
        yonkoLeave.click();
        return devObserverIsCpuEndingCaptain(player) ? "終局船長尚未整備完成，暫不挑戰四皇。" : "非終局船長略過四皇挑戰。";
      }
      if (devObserverShouldChallengeYonkoNow(player, island, islandState) && isDevObserverClickable(yonkoStart)) {
        yonkoStart.click();
        return `${player?.name || "CPU"} 進入四皇據點劇情戰。`;
      }
    }
    const clicked = clickFirstDevObserverButton([
      "#finalEndingNextBtn",
      "#continueElbaphImuStoryBtn",
      "#confirmFinalGateBtn",
      "#seaEncounterStartBtn",
      "#confirmSeaEventBtn",
      "#startSeaChestShuffleBtn:not(:disabled)",
      "[data-sea-treasure-chest]:not(:disabled)",
      "#confirmChestBtn",
      "#challengeBtn",
      "#startJudicialRaidBtn",
      "#joinJudicialRaidBtn",
      "#confirmEventIslandBtn",
      "#openDefeatedCodexBtn + .modal-btn.primary",
      "#closeModalBtn",
      "#finalGateCloseBtn",
      "#leaveShopBtn",
      "#leaveHospitalBtn",
      "#leaveImpelIslandBtn",
      "#leaveMarinefordIslandBtn",
      ".final-imu-btn.primary:not(:disabled)",
      ".final-ending-btn.primary:not(:disabled)",
      ".modal-btn.primary:not(:disabled)",
    ]);
    return clicked ? `按下：${clicked}` : "";
  }

  function routeTargetForDevObserver(routeItem, fromIslandId) {
    const travel = traversalFromIsland(routeItem, fromIslandId);
    return getIslandById(travel?.toIslandId || "");
  }

  function devObserverIslandRouteDistance(source, targets = []) {
    const sourceId = typeof source === "string" ? source : source?.id;
    const targetIds = new Set((targets || []).map((target) => typeof target === "string" ? target : target?.id).filter(Boolean));
    if (!sourceId || !targetIds.size) return Infinity;
    if (targetIds.has(sourceId)) return 0;
    const graph = new Map();
    (state.gameState.boardData?.routesBetweenIslands || []).forEach((routeItem) => {
      if (!routeItem?.from || !routeItem?.to) return;
      if (!graph.has(routeItem.from)) graph.set(routeItem.from, []);
      if (!graph.has(routeItem.to)) graph.set(routeItem.to, []);
      graph.get(routeItem.from).push(routeItem.to);
      graph.get(routeItem.to).push(routeItem.from);
    });
    const queue = [{ id: sourceId, distance: 0 }];
    const visited = new Set([sourceId]);
    for (let index = 0; index < queue.length; index += 1) {
      const entry = queue[index];
      for (const nextId of graph.get(entry.id) || []) {
        if (visited.has(nextId)) continue;
        const distance = entry.distance + 1;
        if (targetIds.has(nextId)) return distance;
        visited.add(nextId);
        queue.push({ id: nextId, distance });
      }
    }
    return Infinity;
  }

  function devObserverNextIslandIdsTowardTargets(source, targets = []) {
    const sourceId = typeof source === "string" ? source : source?.id;
    const targetIds = new Set((targets || []).map((target) => typeof target === "string" ? target : target?.id).filter(Boolean));
    if (!sourceId || !targetIds.size) return new Set();
    const graph = new Map();
    (state.gameState.boardData?.routesBetweenIslands || []).forEach((routeItem) => {
      if (!routeItem?.from || !routeItem?.to) return;
      if (!graph.has(routeItem.from)) graph.set(routeItem.from, []);
      if (!graph.has(routeItem.to)) graph.set(routeItem.to, []);
      graph.get(routeItem.from).push(routeItem.to);
      graph.get(routeItem.to).push(routeItem.from);
    });
    const queue = [{ id: sourceId, distance: 0, first: "" }];
    const visited = new Map([[sourceId, 0]]);
    const nextIds = new Set();
    let bestDistance = Infinity;
    for (let index = 0; index < queue.length; index += 1) {
      const entry = queue[index];
      if (entry.distance > bestDistance) continue;
      if (targetIds.has(entry.id) && entry.id !== sourceId) {
        bestDistance = entry.distance;
        if (entry.first) nextIds.add(entry.first);
        continue;
      }
      for (const nextId of graph.get(entry.id) || []) {
        const distance = entry.distance + 1;
        if (distance > bestDistance) continue;
        if (visited.has(nextId) && visited.get(nextId) < distance) continue;
        visited.set(nextId, distance);
        queue.push({ id: nextId, distance, first: entry.first || nextId });
      }
    }
    return nextIds;
  }

  function devObserverYonkoTargetsForPlayer(player) {
    return (state.gameState.boardData?.islands || []).filter((island) => {
      if (island.kind !== "yonko") return false;
      const islandState = getIslandState(island.id);
      const key = devObserverYonkoKeyForIsland(island, islandState);
      return !devObserverYonkoDefeated(island, islandState) || !devObserverPlayerHasYonkoGlyph(player, key);
    });
  }

  function devObserverAverageCrewLevel(player) {
    const crew = (player?.crew || []).filter(Boolean);
    if (!crew.length) return 1;
    return crew.reduce((sum, card) => sum + Math.max(1, Number(card.level || 1)), 0) / crew.length;
  }

  function devObserverRoadPoneglyphCount(player) {
    const fromItems = ROAD_PONEGLYPH_ITEM_IDS.filter((itemId) => devObserverInventoryCount(player, itemId) > 0).length;
    const fromState = Array.isArray(player?.roadPoneglyphs) ? player.roadPoneglyphs.length : 0;
    return Math.max(fromItems, fromState);
  }

  function devObserverAverageTraining(player) {
    const crew = (player?.crew || []).filter(Boolean);
    if (!crew.length) return 0;
    return crew.reduce((crewSum, card) => (
      crewSum + TRAINING_STATS.reduce((sum, stat) => sum + Number(card?.training?.[stat] || 0), 0)
    ), 0) / crew.length;
  }

  function devObserverAllYonkoDefeated() {
    const yonkoIds = (state.gameState.boardData?.islands || []).filter((island) => island.kind === "yonko").map((island) => island.id);
    if (!yonkoIds.length) return Object.values(state.gameState.yonkoStatus || {}).every(Boolean);
    return yonkoIds.every((id) => Boolean(state.gameState.yonkoStatus?.[id]));
  }

  function devObserverFinalReadiness(player) {
    const crewCount = (player?.crew || []).length;
    const hpRatio = crewAverageHpRatio(player);
    const ppRatio = devObserverAveragePpRatio(player);
    const teamPower = devObserverTeamPower(player);
    const avgLevel = devObserverAverageCrewLevel(player);
    const roadCount = devObserverRoadPoneglyphCount(player);
    return {
      crewCount,
      hpRatio,
      ppRatio,
      teamPower,
      avgLevel,
      roadCount,
      hasRoads: roadCount >= 4 || Boolean(state.gameState.finalIslandUnlocked),
      readyForGate: crewCount >= TEAM_LIMIT && hpRatio >= 0.72 && ppRatio >= 0.42 && teamPower >= 62 && avgLevel >= 62,
      readyForFinal: crewCount >= TEAM_LIMIT && hpRatio >= 0.78 && ppRatio >= 0.5 && teamPower >= 72 && avgLevel >= 72,
    };
  }

  function devObserverSamePlayer(a, b) {
    if (!a || !b) return false;
    if (a.id && b.id) return String(a.id) === String(b.id);
    return String(a.name || "") === String(b.name || "");
  }

  function devObserverPlayerHasYonkoGlyph(player, yonkoKey) {
    const info = ROAD_PONEGLYPH_BY_GLYPH[String(yonkoKey || "")];
    if (!player || !info) return false;
    const glyphs = new Set(Array.isArray(player.roadPoneglyphs) ? player.roadPoneglyphs.map((id) => String(id || "")) : []);
    return glyphs.has(String(yonkoKey || "")) || devObserverInventoryCount(player, info.itemId) > 0;
  }

  function devObserverCpuEndingCaptainScore(player) {
    if (!player) return -Infinity;
    const readiness = devObserverFinalReadiness(player);
    const defeatedGlyphs = new Set(Array.isArray(player.defeatedYonkoGlyphs) ? player.defeatedYonkoGlyphs : []).size;
    return readiness.roadCount * 12000
      + defeatedGlyphs * 4200
      + readiness.avgLevel * 85
      + readiness.teamPower * 7
      + devObserverAverageTraining(player) * 3
      + readiness.crewCount * 180
      + Number(player.bounty || 0) / 5000000
      + Number(player.coins || 0) / 7000;
  }

  function devObserverCpuEndingCaptain() {
    const players = (state.gameState?.players || []).filter(Boolean);
    if (players.length < 2 || players.some((player) => !isCpuPlayer(player))) return null;
    return players.slice().sort((a, b) => devObserverCpuEndingCaptainScore(b) - devObserverCpuEndingCaptainScore(a))[0] || null;
  }

  function devObserverIsCpuEndingCaptain(player) {
    const captain = devObserverCpuEndingCaptain();
    return !captain || devObserverSamePlayer(player, captain);
  }

  function devObserverTryActivateFinalIsland(player) {
    const captain = devObserverCpuEndingCaptain();
    const isAssignedObjectiveCpu = isCpuPlayer(player) && cpuStrategyForPlayer(player) === "objective";
    if (!player) return "";
    if (captain && !devObserverSamePlayer(player, captain)) return "";
    if (!captain && !isAssignedObjectiveCpu) return "";
    if (!state.gameState.finalIslandCandidate || state.gameState.finalIslandUnlocked) return "";
    if (!playerHasAllRoadPoneglyphs(player)) return "";
    return activateFinalIslandFromBackpack(player)
      ? "終局船長集滿拓本，啟動最終之島。"
      : "";
  }

  function devObserverShouldChallengeYonkoNow(player, island, islandState = null) {
    const captain = devObserverCpuEndingCaptain();
    if (!captain) return true;
    if (!player || !devObserverSamePlayer(player, captain)) return false;
    const ready = devObserverFinalReadiness(player);
    const needsGlyph = island?.kind === "yonko"
      ? !devObserverPlayerHasYonkoGlyph(player, devObserverYonkoKeyForIsland(island, islandState))
      : true;
    return needsGlyph
      && ready.crewCount >= TEAM_LIMIT
      && ready.hpRatio >= 0.86
      && ready.ppRatio >= 0.56
      && devObserverAverageTraining(player) >= 120
      && ready.avgLevel >= 86;
  }

  function cpuSupportRouteScore(player, target, kind) {
    const humans = (state.gameState?.players || []).filter((entry) => entry && !isCpuPlayer(entry));
    if (!isCpuPlayer(player) || !target || !humans.length) return 0;
    let score = 0;
    humans.forEach((human) => {
      const location = human.location || {};
      if (human.pendingBattle && location.kind === "island" && String(target.id || "") === String(location.islandId || "")) {
        score += 980;
      }
      if (location.kind === "island") {
        if (String(target.id || "") === String(location.islandId || "")) score += 720;
        const distance = devObserverIslandRouteDistance(target, [location.islandId]);
        if (Number.isFinite(distance)) score += Math.max(0, 360 - distance * 90);
      } else if (location.kind === "route") {
        if (String(target.id || "") === String(location.toIslandId || "")) score += 430;
        if (String(target.id || "") === String(location.fromIslandId || "")) score += 140;
      }
    });
    if (["judicial", "impel_down", "marineford", "enemy"].includes(kind)) score += 130;
    return score;
  }

  function cpuStrategyRouteModifier(player, routeItem, target, kind, targetState, context = {}) {
    if (!isCpuPlayer(player)) return 0;
    const strategy = cpuStrategyForPlayer(player);
    let score = 0;
    if (context.earlySafetyMode) {
      if (kind === "tavern" && context.earlyCrewBuild) score += 220;
      if (kind === "enemy" && !targetState?.isDefeated && !context.enemyRisk?.isComfortable) score -= 260;
      if (["judicial", "impel_down", "marineford", "yonko", "final", "elbaph"].includes(kind)) score -= 320;
      if (kind === "event" && Number(player.coins || 0) < TAVERN_RECRUIT_ROLL_COST) score -= 90;
    }
    if (strategy === "balanced") return score;
    if (strategy === "level") {
      if (kind === "enemy" && !targetState?.isDefeated) score += context.enemyRisk?.isTooHard ? -120 : 260;
      if (kind === "mission") score += 230;
      if (kind === "event") score += 95;
      if (kind === "judicial") score += context.canTakeDungeon ? 210 : -90;
      if (kind === "impel_down") score += context.canTakeDungeon ? 240 : -80;
      if (kind === "marineford") score += context.canTakeHardDungeon ? 260 : -130;
      if (kind === "tavern" && context.crewCount < TEAM_LIMIT) score += 140;
      if (isMedicalServiceIslandKind(kind) && devObserverNeedsRecovery(player, true)) score += 170;
      if (["yonko", "final", "elbaph"].includes(kind) && context.needsGrowth) score -= 260;
    } else if (strategy === "support") {
      score += cpuSupportRouteScore(player, target, kind);
      if (isMedicalServiceIslandKind(kind) && devObserverNeedsRecovery(player, true)) score += 190;
      if (kind === "mission") score += 90;
      if (["shop", "tavern"].includes(kind) && context.crewCount >= TEAM_LIMIT) score -= 45;
    } else if (strategy === "objective") {
      if (target?.id === "final-island") score += context.finalReady?.hasRoads ? 1250 : -320;
      if (target?.finalGateAnchor || kind === "elbaph") score += context.finalReady?.hasRoads ? 760 : -180;
      if (kind === "yonko") score += context.finalReady?.crewCount >= TEAM_LIMIT ? 760 : -220;
      if (kind === "mission") score += 80;
      if (kind === "enemy" && !targetState?.isDefeated) score += context.enemyRisk?.isTooHard ? -120 : 90;
      if (isMedicalServiceIslandKind(kind) && devObserverNeedsRecovery(player, true)) score += 150;
      if (["shop", "tavern"].includes(kind) && !context.needsShop && context.crewCount >= TEAM_LIMIT) score -= 80;
    }
    return score;
  }

  function chooseDevObserverRoute() {
    const prompt = state.gameState.routePrompt;
    const player = currentPlayer();
    if (!prompt || !player || prompt.playerId !== player.id) return "";
    const routes = (prompt.routeIds || []).map(getRouteById).filter(Boolean);
    if (!routes.length) return "";
    const cpuEndingCaptain = devObserverCpuEndingCaptain();
    const cpuEndingFocused = Boolean(cpuEndingCaptain);
    const isCpuEndingCaptain = !cpuEndingFocused || devObserverSamePlayer(player, cpuEndingCaptain);
    const rankRoute = (routeItem) => {
      const target = routeTargetForDevObserver(routeItem, prompt.islandId);
      const targetState = target ? getIslandState(target.id) : null;
      const kind = target ? getEffectiveIslandKind(target, targetState) : "";
      const crewCount = (player.crew || []).length;
      const hpRatio = crewAverageHpRatio(player);
      const ppRatio = devObserverAveragePpRatio(player);
      const avgLevel = devObserverAverageCrewLevel(player);
      const teamPower = devObserverTeamPower(player);
      const finalReady = devObserverFinalReadiness(player);
      const needsShop = !!devObserverDesiredShopItemId(player);
      const enemyRisk = targetState?.enemyProfile ? devObserverEnemyRisk(player, targetState.enemyProfile) : null;
      const needsGrowth = crewCount < TEAM_LIMIT || avgLevel < 55 || teamPower < 52;
      const earlyCrewBuild = crewCount < 4 || (crewCount < TEAM_LIMIT && avgLevel < 12);
      const earlySafetyMode = earlyCrewBuild || (avgLevel < 10 && teamPower < 18);
      const canTakeDungeon = !earlySafetyMode && crewCount >= 4 && hpRatio >= 0.62 && ppRatio >= 0.28 && teamPower >= 22;
      const canTakeHardDungeon = crewCount >= 5 && hpRatio >= 0.72 && ppRatio >= 0.38 && teamPower >= 34;
      const yonkoTargets = cpuEndingFocused && isCpuEndingCaptain ? devObserverYonkoTargetsForPlayer(player) : [];
      const shouldApproachYonko = cpuEndingFocused
        && isCpuEndingCaptain
        && yonkoTargets.length > 0
        && finalReady.crewCount >= TEAM_LIMIT
        && finalReady.hpRatio >= 0.62
        && finalReady.ppRatio >= 0.34
        && (finalReady.avgLevel >= 48 || finalReady.teamPower >= 56);
      let score = 0;
      if (cpuEndingFocused && !isCpuEndingCaptain && (kind === "yonko" || kind === "final" || kind === "elbaph" || target?.finalGateAnchor)) {
        score -= 2200;
      }
      if (target?.id === "final-island") {
        score += finalReady.hasRoads && finalReady.readyForFinal ? 1600 : -520;
        if (cpuEndingFocused && isCpuEndingCaptain) score += finalReady.hasRoads ? 760 : -360;
      }
      if (target?.finalGateAnchor || kind === "elbaph") {
        score += finalReady.hasRoads && finalReady.readyForGate ? 980 : -220;
        if (cpuEndingFocused && isCpuEndingCaptain) score += finalReady.hasRoads ? 520 : -280;
      }
      if (kind === "yonko") {
        score += isCpuEndingCaptain ? devObserverYonkoRouteScore(player, target, targetState, enemyRisk) : -2200;
        if (cpuEndingFocused && isCpuEndingCaptain && finalReady.roadCount < 4) score += 430;
        if (cpuEndingFocused && isCpuEndingCaptain && !devObserverShouldChallengeYonkoNow(player, target, targetState)) score -= 1300;
      }
      if (shouldApproachYonko) {
        const currentDistance = devObserverIslandRouteDistance(prompt.islandId, yonkoTargets);
        const targetDistance = devObserverIslandRouteDistance(target, yonkoTargets);
        if (Number.isFinite(currentDistance) && Number.isFinite(targetDistance)) {
          score += (currentDistance - targetDistance) * 640 - targetDistance * 12;
        }
        const nextIds = devObserverNextIslandIdsTowardTargets(prompt.islandId, yonkoTargets);
        if (nextIds.size) score += nextIds.has(target?.id) ? 2600 : -580;
      }
      if (cpuEndingFocused && isCpuEndingCaptain && finalReady.hasRoads && state.gameState.finalIslandUnlocked) {
        const finalTarget = getIslandById("final-island");
        const finalTargets = finalTarget ? [finalTarget] : [];
        const currentDistance = devObserverIslandRouteDistance(prompt.islandId, finalTargets);
        const targetDistance = devObserverIslandRouteDistance(target, finalTargets);
        if (Number.isFinite(currentDistance) && Number.isFinite(targetDistance)) {
          score += (currentDistance - targetDistance) * 520 - targetDistance * 9;
        }
        const nextIds = devObserverNextIslandIdsTowardTargets(prompt.islandId, finalTargets);
        if (nextIds.size) score += nextIds.has(target?.id) ? 3200 : -760;
      }
      if (kind === "enemy") {
        if (targetState?.isDefeated) score += 8;
        else {
          score += enemyRisk?.isTooHard ? -180 : enemyRisk?.isRisky ? 80 : 220;
          if (crewCount < 3) score -= 80;
          if (earlySafetyMode && !enemyRisk?.isComfortable) score -= crewCount < 4 ? 360 : 240;
          if (earlySafetyMode && enemyRisk?.isRisky) score -= 180;
          if (hpRatio < 0.48) score -= 150;
          if (needsGrowth && enemyRisk?.isComfortable) score += earlySafetyMode ? 30 : 70;
        }
      }
      if (kind === "postgame_boss") {
        const bossDef = postgameBossDef(target?.postgameBossKey || targetState?.bossKey);
        const ownsClue = bossDef?.clueItemId ? inventoryItemCount(player, bossDef.clueItemId) > 0 : false;
        score += ownsClue ? 150 : 520;
        if (enemyRisk?.isTooHard) score -= 260;
        if (hpRatio < 0.58 || ppRatio < 0.26) score -= 320;
        if (cpuEndingFocused || cpuStrategyForPlayer(player) === "objective") score += ownsClue ? 80 : 260;
      }
      if (kind === "postgame_egghead") {
        score += cpuStrategyForPlayer(player) === "objective" ? 760 : 520;
        if (enemyRisk?.isTooHard) score -= 300;
        if (hpRatio < 0.68 || ppRatio < 0.32) score -= 360;
      }
      if (kind === "judicial") {
        score += canTakeDungeon ? 240 + Math.min(120, avgLevel * 1.2) : -260;
        if (earlySafetyMode) score -= 520;
      }
      if (kind === "impel_down") {
        score += canTakeDungeon ? ((crewCount < TEAM_LIMIT ? 240 : 120) + Math.min(130, avgLevel * 1.1)) : -220;
        if (hpRatio < 0.55 || ppRatio < 0.24) score -= 180;
        if (earlySafetyMode) score -= 620;
        else if (crewCount < TEAM_LIMIT && avgLevel < 18) score -= 180;
      }
      if (kind === "marineford") {
        score += canTakeHardDungeon && avgLevel >= 45 ? 330 + Math.min(150, avgLevel) : -310;
        if (earlySafetyMode) score -= 700;
      }
      if (kind === "event") {
        score += crewCount < 4 ? 110 : needsGrowth ? 85 : 45;
        if (earlySafetyMode && Number(player.coins || 0) < TAVERN_RECRUIT_ROLL_COST) score -= 120;
      }
      if (kind === "tavern") {
        const canAffordRecruit = player.coins >= TAVERN_RECRUIT_ROLL_COST && tavernRecruitPool(player).length;
        if (crewCount < 4 && canAffordRecruit) score += 900;
        else if (earlyCrewBuild && canAffordRecruit) score += 620;
        else if (crewCount < TEAM_LIMIT && canAffordRecruit) score += 360;
        else if (crewCount < TEAM_LIMIT) score += 70;
        else score += 5;
      }
      if (isMedicalServiceIslandKind(kind)) score += devObserverNeedsRecovery(player, true) ? 430 : 8;
      if (kind === "shop") score += needsShop ? 260 : 22;
      if (kind === "mission") score += devObserverMissionNeedScore(player) || (needsGrowth ? 120 : 35);
      if (target?.id === WATER_SEVEN_ISLAND_ID || kind === "water_seven") score += devObserverHasWaterSevenWork(player) ? 360 : -45;
      score += devObserverMissionRouteBonus(player, kind, target, targetState, enemyRisk);
      score += cpuStrategyRouteModifier(player, routeItem, target, kind, targetState, {
        crewCount,
        hpRatio,
        ppRatio,
        avgLevel,
        teamPower,
        finalReady,
        needsShop,
        needsGrowth,
        earlyCrewBuild,
        earlySafetyMode,
        canTakeDungeon,
        canTakeHardDungeon,
        enemyRisk,
      });
      if (needsGrowth && ["judicial", "marineford", "yonko"].includes(kind)) score -= 90;
      if (routeItem?.meta?.uniqueBranch && state.gameState.claimedBranchRoutes?.[routeItem.meta.branchId] && state.gameState.claimedBranchRoutes?.[routeItem.meta.branchId] !== player.id) score -= 999;
      score -= Math.max(0, Number(routeItem?.tiles?.length || 0)) * 0.8;
      return score;
    };
    const route = routes.slice().sort((a, b) => rankRoute(b) - rankRoute(a))[0] || routes[0];
    const target = routeTargetForDevObserver(route, prompt.islandId);
    chooseRouteFromMap(route.id);
    return `選航線：${target?.name || route.name || route.id}`;
  }

  function chooseDevObserverSoulChoice(prompt) {
    const options = prompt?.options || {};
    if (options.item) return "item";
    if (options.pp) return "pp";
    if (options.hp) return "hp";
    if (options.coins) return "coins";
    return "refuse";
  }

  function devObserverHandleCpuTradeFlow() {
    const prompt = state.gameState?.tradePrompt;
    if (prompt) {
      const player = tradePlayerById(prompt.playerId);
      if (canLocalDriveCpuPlayer(player)) {
        addLog(`${player.name} 略過同海格玩家交易。`);
        finishTradeInterruption({ skipped: true });
        return "CPU 略過玩家交易。";
      }
      return "";
    }
    const trade = normalizeActiveTrade(state.gameState?.activeTrade);
    if (!trade) return "";
    const participants = activeTradePlayers(trade);
    if (participants.length && participants.some((player) => isCpuPlayer(player))) {
      addLog("含 CPU 的玩家交易已自動取消。");
      finishTradeInterruption({ cancelled: true });
      return "CPU 取消玩家交易。";
    }
    return "";
  }

  function devObserverBattleMoveCanDamage(move) {
    if (!move) return false;
    const category = move.category || move.type || "";
    if (!["attack", "special"].includes(category)) return false;
    const range = move.damageRange || null;
    if (Number(range?.max || 0) > 0 || Number(range?.min || 0) > 0) return true;
    if (Number(move.power || 0) > 0) return true;
    const text = `${move.name || ""} ${move.effectText || ""}`.toLowerCase();
    if (/造成傷害|追加傷害|damage/.test(text) && !/回復|治療|heal|cure|revive/.test(text)) return true;
    return false;
  }

  function devObserverCardHasUsableDamageMove(card) {
    return (card?.moves || card?.moveSet || []).some((move) => {
      if (Number(move.currentPP ?? move.pp ?? 0) <= 0) return false;
      return devObserverBattleMoveCanDamage(move);
    });
  }

  function devObserverEnsureActiveDamageMove(view) {
    const battle = state.battleState;
    const player = battle ? battlePlayer(null, battle) : null;
    const card = player && battle ? battleActiveCard(player, battle) : null;
    if (!player || !card) return "";
    syncCardMoveSetFromCatalog(card);
    syncUnlockedMoveIds(card);
    const currentMoves = getUnlockedMoves(card).filter((move) => Number(move.currentPP ?? move.pp ?? 0) > 0);
    if (currentMoves.some(devObserverBattleMoveCanDamage)) return "";
    const level = Number(card.level || 1);
    const currentIds = new Set((card.unlockedMoveIds || []).slice(0, MAX_ACTIVE_MOVES));
    const damageCandidates = (card.moveSet || [])
      .filter((move) => effectiveMoveUnlockLevel(move) <= level)
      .filter((move) => Number(move.currentPP ?? move.pp ?? 0) > 0)
      .filter(devObserverBattleMoveCanDamage)
      .sort((a, b) => devObserverMoveScoreForCard(card, b, currentMoves) - devObserverMoveScoreForCard(card, a, currentMoves));
    const damageMove = damageCandidates.find((move) => !currentIds.has(move.id)) || damageCandidates[0];
    if (!damageMove?.id) return "";
    if (currentIds.has(damageMove.id)) {
      syncUnlockedMoveIds(card);
      return "";
    }
    const replaceTarget = currentMoves
      .filter((move) => !devObserverBattleMoveCanDamage(move))
      .sort((a, b) => devObserverMoveScoreForCard(card, a, currentMoves) - devObserverMoveScoreForCard(card, b, currentMoves))[0];
    if (replaceTarget?.id) {
      card.unlockedMoveIds = (card.unlockedMoveIds || []).map((id) => id === replaceTarget.id ? damageMove.id : id).slice(0, MAX_ACTIVE_MOVES);
      syncUnlockedMoveIds(card);
      addLog(`${cardDisplayName(card)} 調整上場招式，保留可結束戰鬥的 ${damageMove.name}。`);
      return `調整技能：${cardDisplayName(card)} 換上 ${damageMove.name}`;
    }
    if ((card.unlockedMoveIds || []).length < MAX_ACTIVE_MOVES) {
      card.unlockedMoveIds = Array.from(new Set([...(card.unlockedMoveIds || []), damageMove.id])).slice(0, MAX_ACTIVE_MOVES);
      syncUnlockedMoveIds(card);
      addLog(`${cardDisplayName(card)} 補上可攻擊招式 ${damageMove.name}。`);
      return `補上攻擊技能：${cardDisplayName(card)} / ${damageMove.name}`;
    }
    return "";
  }

  function chooseDevObserverBattleMove(view) {
    const moves = (view?.activeCard?.moves || []).filter((move) => Number(move.currentPP ?? move.pp ?? 0) > 0);
    const attacks = moves.filter(devObserverBattleMoveCanDamage);
    const hpRatio = Number(view?.activeCard?.currentHp || 0) / Math.max(1, Number(view?.activeCard?.maxHp || 1));
    const enemyHpRatio = Number(view?.enemy?.currentHp || 0) / Math.max(1, Number(view?.enemy?.maxHp || 1));
    const scoreMove = (move) => {
      const category = move.category || move.type || "";
      const effects = move.effects || {};
      if (["heal", "shield", "buff", "debuff", "control", "status"].includes(category)) {
        let utility = 0;
        if (category === "heal") utility += hpRatio < 0.55 ? 220 : hpRatio < 0.75 ? 90 : -80;
        if (effects.healRatio || effects.healTeamRatio || effects.healLowestAllyRatio || effects.reviveLowestAllyRatio) utility += hpRatio < 0.7 ? 160 : 20;
        if (category === "shield" || effects.shieldRatio || effects.shieldRatioBeforeAttack) utility += hpRatio < 0.5 ? 130 : 35;
        if (category === "buff" || effects.selfStages) utility += enemyHpRatio > 0.5 ? 70 : 15;
        if (category === "debuff" || category === "control" || effects.enemyStages || effects.enemyStagesOnHit) utility += enemyHpRatio > 0.35 ? 75 : 20;
        utility += Number(move.priority || 0) * 10;
        return utility;
      }
      const range = move.damageRange || null;
      const maxDamage = Number(range?.max || 0);
      const minDamage = Number(range?.min || 0);
      const accuracy = Math.max(0.3, Number(move.accuracy || 100) / 100);
      const attackAttribute = move.attribute || view?.activeCard?.attribute || "";
      const attr = attributeModifier(attackAttribute, view?.enemy?.attribute || "", 0.5);
      return (maxDamage * 1.35 + minDamage * 0.35 + Number(move.power || 0) * 0.2 + Number(move.priority || 0) * 12) * accuracy * attr;
    };
    return (attacks.length ? attacks : moves).slice().sort((a, b) => scoreMove(b) - scoreMove(a))[0] || null;
  }

  function devObserverBattleCrewScore(card, view) {
    if (!card || Number(card.currentHp || 0) <= 0) return -9999;
    const hpRatio = Number(card.currentHp || 0) / Math.max(1, Number(card.maxHp || card.baseStats?.hp || 1));
    const attr = attributeModifier(card.attribute || "", view?.enemy?.attribute || "", 0.5);
    const moves = (card.moves || card.moveSet || []).filter((move) => Number(move.currentPP ?? move.pp ?? 0) > 0);
    const bestPower = moves.reduce((best, move) => Math.max(best, Number(move.power || move.damageRange?.max || 0)), 0);
    return devObserverCardScore(card) * 0.015 + hpRatio * 120 + attr * 90 + bestPower * 0.35;
  }

  function devObserverBattleSwitchIndex(view) {
    if (!view?.player?.crew?.length || !view?.battle?.canAct) return -1;
    const currentIndex = Number(view.player.activeCrewIndex ?? 0);
    const current = view.player.crew[currentIndex];
    const currentScore = devObserverBattleCrewScore(current, view);
    const best = view.player.crew
      .map((card, index) => ({ card, index, score: devObserverBattleCrewScore(card, view) }))
      .filter((entry) => entry.index !== currentIndex && Number(entry.card?.currentHp || 0) > 0)
      .sort((a, b) => b.score - a.score)[0];
    if (!best) return -1;
    const hpRatio = Number(current?.currentHp || 0) / Math.max(1, Number(current?.maxHp || current?.baseStats?.hp || 1));
    const currentAttr = attributeModifier(current?.attribute || "", view.enemy?.attribute || "", 0.5);
    const bestAttr = attributeModifier(best.card?.attribute || "", view.enemy?.attribute || "", 0.5);
    if (!devObserverCardHasUsableDamageMove(current)) {
      const damageBackup = view.player.crew
        .map((card, index) => ({ card, index, score: devObserverBattleCrewScore(card, view) }))
        .filter((entry) => entry.index !== currentIndex && Number(entry.card?.currentHp || 0) > 0 && devObserverCardHasUsableDamageMove(entry.card))
        .sort((a, b) => b.score - a.score)[0];
      if (damageBackup) return damageBackup.index;
    }
    if (hpRatio < 0.24 && best.score > currentScore - 20) return best.index;
    if (currentAttr < 1 && bestAttr > currentAttr && best.score >= currentScore + 35) return best.index;
    return -1;
  }

  function devObserverTotMusicaAction(player, battle) {
    const mechanic = postgameBossMechanicFor(battle);
    if (!player || mechanic?.key !== "postgame_tot_musica" || !mechanic.assigned) return "";
    if (postgameTotUsesPlayerWorlds(battle, mechanic)) {
      const world = mechanic.coopSelectionWorld === "song" ? "song" : "real";
      const worldPlayer = postgameTotActiveWorldPlayer(battle, mechanic, world);
      if (!worldPlayer || String(worldPlayer.id) !== String(player.id)) return "等待另一個世界的玩家選擇。";
      const runtime = coopBattleRuntimeFor(worldPlayer, battle, true);
      const activeIndex = livingActiveCrewIndex(worldPlayer, runtime?.activeCrewIndex ?? worldPlayer.activeCrewIndex ?? 0);
      const card = worldPlayer.crew?.[activeIndex];
      const move = getUnlockedMoves(card)
        .filter((entry) => postgameBossMechanicDirectMove(entry) && Number(entry.currentPP ?? entry.pp ?? 0) > 0)
        .sort((a, b) => Number(b.power || 0) - Number(a.power || 0))[0];
      const action = move ? { type: "move", moveId: move.id } : null;
      return action && queueTotMusicaWorldAction(world, action) ? `${world === "real" ? "現實世界" : "歌世界"}完成行動選擇。` : "目前沒有可用的直接攻擊。";
    }
    const choose = (world) => {
      const indices = world === "real" ? mechanic.realIndices : mechanic.songIndices;
      const activeIndex = Number(world === "real" ? mechanic.realActiveIndex : mechanic.songActiveIndex);
      const card = player.crew?.[activeIndex];
      const move = getUnlockedMoves(card)
        .filter((entry) => postgameBossMechanicDirectMove(entry) && Number(entry.currentPP ?? entry.pp ?? 0) > 0)
        .sort((a, b) => Number(b.power || 0) - Number(a.power || 0))[0];
      if (move) return { type: "move", moveId: move.id };
      const replacement = indices.find((index) => index !== activeIndex && Number(player.crew?.[index]?.currentHp || 0) > 0 && getUnlockedMoves(player.crew[index]).some((entry) => postgameBossMechanicDirectMove(entry) && Number(entry.currentPP ?? entry.pp ?? 0) > 0));
      return Number.isInteger(replacement) ? { type: "switch", nextIndex: replacement } : null;
    };
    const realAction = choose("real");
    const songAction = choose("song");
    if (!realAction || !songAction) return "";
    return queueTotMusicaAction(realAction, songAction) ? "雙世界同步攻擊。" : "";
  }

  function devObserverBattleStep() {
    const view = getBattleView();
    const battle = state.battleState;
    if (!view || !battle) return "等待戰鬥畫面。";
    if (view.battle?.prebattleIntro && !view.battle.prebattleIntro.done) {
      // CPU and the developer observer share this path. The battle iframe owns the
      // dialogue timeline and reports intro-done after both speakers have appeared;
      // selecting an action here used to erase the entire opening conversation.
      return "等待戰鬥開場對話播放。";
    }
    const postgamePrompt = view.battle?.postgameBossMechanic?.prompt;
    if (postgamePrompt?.type === "katakuri_future_sight") {
      if (!postgamePrompt.canChoose) return postgamePrompt.defenseRolling ? "卡塔庫栗戰：等待防禦骰。" : "卡塔庫栗戰：等待預知骰。";
      const forecastDie = Math.max(1, Number(postgamePrompt.forecastDie || 1));
      const hpRatio = Number(view.activeCard?.currentHp || 0) / Math.max(1, Number(view.activeCard?.maxHp || 1));
      const strongestPower = Math.max(0, ...(view.activeCard?.moves || []).filter((move) => Number(move.currentPP || 0) > 0).map((move) => Number(move.power || 0)));
      const finishingChance = Number(view.enemy?.currentHp || 0) <= Math.max(1, strongestPower * 1.5);
      const choice = finishingChance || forecastDie <= 3 || (forecastDie === 4 && hpRatio > 0.5) ? "move" : "defend";
      choosePostgameKatakuriAction(choice);
      return choice === "move"
        ? `卡塔庫栗預知骰 ${forecastDie}：嘗試正面突破。`
        : `卡塔庫栗預知骰 ${forecastDie}：放棄出招改採防禦。`;
    }
    if (postgamePrompt?.type === "oars_lottery") {
      const options = Array.isArray(postgamePrompt.options) ? postgamePrompt.options : [];
      const weighted = options
        .map((entry) => ({ entry, score: Number(entry.payout || 0) * Math.max(0.0001, Number(entry.probability || 0)) + Math.random() * 0.25 }))
        .sort((a, b) => b.score - a.score);
      const availableSaltBags = Math.max(0, Math.floor(Number(postgamePrompt.availableSaltBags || 0)));
      const stakeBudget = availableSaltBags > 0 ? 1 + Math.floor(Math.random() * availableSaltBags) : 0;
      const optionCount = stakeBudget > 0 ? 1 + Math.floor(Math.random() * Math.min(3, stakeBudget, weighted.length)) : 0;
      const selected = weighted.slice(0, optionCount).map(({ entry }) => ({ entry, stake: 1 }));
      for (let assigned = selected.length; assigned < stakeBudget; assigned += 1) selected[Math.floor(Math.random() * selected.length)].stake += 1;
      const bets = selected.map(({ entry, stake }) => ({ optionId: entry.id, stake }));
      if (bets.length) lockPostgameOarsPredictions(bets);
      return bets.length ? `歐斯鹽袋下注：${selected.map(({ entry, stake }) => `${entry.label} ${stake} 包`).join("、")}` : "目前沒有鹽袋可下注。";
    }
    if (postgamePrompt?.type === "oars_purification") {
      purifyPostgameOars();
      return "集滿十五袋巨型鹽，發射鹽彈淨化歐斯。";
    }
    if (postgamePrompt?.type === "tot_team_setup") {
      const defaults = postgameTotDefaultTeams(battlePlayer(null, battle));
      confirmTotMusicaTeams(defaults.realIndices);
      return "Tot Musica：完成雙世界分隊。";
    }
    if (postgamePrompt?.type === "tesoro_forced_switch") {
      const candidate = (postgamePrompt.candidates || []).slice().sort((a, b) => Number(b.currentHp || 0) - Number(a.currentHp || 0))[0];
      if (candidate) resolvePostgameBossForcedSwitch(candidate.index);
      return candidate ? `黃金化強制換人：${candidate.name}` : "等待黃金化解除。";
    }
    if (view.battle?.needsReplacement) {
      const candidate = (view.battle.replacementCandidates || []).slice().sort((a, b) => (b.currentHp || 0) - (a.currentHp || 0))[0];
      if (candidate) {
        chooseBattleReplacement(candidate.index);
        return `替補上場：${candidate.name}`;
      }
      return "等待替補角色。";
    }
    if (view.battle?.yonkoPrompt?.pending) {
      const choice = chooseDevObserverSoulChoice(view.battle.yonkoPrompt);
      resolveBigMomSoulChoice(choice);
      return `處理靈魂拷問：${choice}`;
    }
    if (view.battle?.judicialSwitchPrompt) {
      const candidates = (view.battle.judicialSwitchPrompt.candidates || [])
        .map((entry) => {
          const card = view.player?.crew?.[entry.index];
          return { ...entry, card, score: devObserverBattleCrewScore(card, view) };
        })
        .filter((entry) => Number(entry.card?.currentHp || 0) > 0)
        .sort((a, b) => b.score - a.score);
      const best = candidates[0];
      if (best && startJudicialRaidNextPhaseAfterSwitch(best.index)) {
        return `司法島連戰：換上 ${best.name || cardDisplayName(best.card)} 進入下一階段。`;
      }
      return "等待司法島連戰換人。";
    }
    if (view.battle?.coopRescueWait?.active) {
      const commandPlayer = battleCommandPlayer(battle);
      const reviveItem = (view.player?.battleItems || []).find((item) => item.effectKind === "revive" && Number(item.count || 0) > 0);
      const downedIndex = (view.player?.crew || []).findIndex((card) => Number(card.currentHp || 0) <= 0);
      if (reviveItem && downedIndex >= 0 && queuePlayerBattleItem(reviveItem.id, downedIndex, commandPlayer?.id || view.player.id)) {
        return `待救援回合：使用${reviveItem.name}自救。`;
      }
      battleWaitForRescue();
      return `待救援回合：未能復活，剩餘 ${Math.max(0, Number(view.battle.coopRescueWait.turnsRemaining || 0) - 1)} 次。`;
    }
    if (view.battle?.canFinish) {
      finishBattle();
      return "完成本輪 / 戰鬥結算。";
    }
    if (!view.battle?.canAct) return "等待戰鬥動畫或回合結算。";
    if (view.battle?.postgameBossMechanic?.key === "postgame_tot_musica") {
      return devObserverTotMusicaAction(battlePlayer(null, battle), battle) || "雙世界沒有可用的直接攻擊。";
    }
    if (view.battle?.postgameBossMechanic?.key === "postgame_zephyr" && view.battle.postgameBossMechanic.state?.canDisarm) {
      return queuePostgameZephyrDisarm() ? "澤法戰：優先阻止最後終結點引爆。" : "澤法戰：等待阻止引爆指令。";
    }
    const hpRatio = Number(view.activeCard?.currentHp || 0) / Math.max(1, Number(view.activeCard?.maxHp || 1));
    if (hpRatio < 0.35) {
      const healItem = (view.player?.battleItems || []).find((item) => /heal|回復|治療|食物|藥|food/i.test(`${item.id} ${item.name} ${item.desc} ${item.effectKind}`));
      if (healItem) {
        queuePlayerBattleItem(healItem.id, view.player.activeCrewIndex);
        return `使用補品：${healItem.name}`;
      }
    }
    const damageMoveRepair = devObserverEnsureActiveDamageMove(view);
    if (damageMoveRepair) return damageMoveRepair;
    const switchIndex = devObserverBattleSwitchIndex(view);
    if (switchIndex >= 0 && queuePlayerBattleSwitch(switchIndex)) {
      return `換上更適合的角色：${view.player.crew[switchIndex]?.name || switchIndex}`;
    }
    const move = chooseDevObserverBattleMove(view);
    if (move) {
      queuePlayerBattleMove(move.id);
      return `使用招式：${move.name}`;
    }
    attemptEscape();
    return "沒有可用招式，嘗試逃跑。";
  }

  async function performDevObserverStep() {
    if (state.gameState.phase !== "main") {
      const clicked = devObserverHandleVisibleOverlay();
      return clicked || "等待開始遊戲或讀取存檔。";
    }
    if (state.battleState) return devObserverBattleStep();
    if (currentPlayer()?.pendingPostgameBossVoyage) {
      await processPendingPostgameBossVoyageForCurrentPlayer();
      return "執行拉夫德魯無風帶 Boss 航路。";
    }
    if (playerCrewWipedOut(currentPlayer())) {
      if (playerHasPendingCoopRescueWait(currentPlayer()) && canResumeBattle(currentPlayer())) {
        autoResumeBattleForCurrentPlayer();
        return "回到共鬥待救援回合。";
      }
      resolveCrewWipeoutIfNeeded(currentPlayer(), "全隊瀕死");
      return isPlayerInMarineford(currentPlayer()) ? "全隊瀕死，依規則移送海軍本部。" : "全隊瀕死，依規則移送推進城。";
    }
    if (state.gameState.routePrompt) return chooseDevObserverRoute() || "等待航線選擇。";
    if (state.gameState.tradePrompt || state.gameState.activeTrade) return devObserverHandleCpuTradeFlow() || "等待玩家交易。";
    if (activeSparBlocksCurrentTurn()) return "等待真人玩家完成本回合切磋。";
    if (state.gameState.islandDecision) {
      continueFromIslandDecision();
      return "抵達分流點，繼續航行。";
    }
    const visibleOverlayClicked = devObserverHandleVisibleOverlay();
    if (visibleOverlayClicked) return visibleOverlayClicked;
    if (canCpuAutoDecodeYork(currentPlayer())) {
      completeYorkCpuDecoder(currentPlayer(), { immediate: true });
      return "十三張約克線索已自動完成普通解碼，取得二階解碼器。";
    }
    const finalActivationAction = devObserverTryActivateFinalIsland(currentPlayer());
    if (finalActivationAction) return finalActivationAction;
    const missionClaimAction = devObserverTryClaimCompletedMission(currentPlayer());
    if (missionClaimAction) return missionClaimAction;
    const carryAction = devObserverTryEquipCarryItems(currentPlayer());
    if (carryAction) return carryAction;
    const evolveAction = devObserverTryEvolveCrew(currentPlayer());
    if (evolveAction) return evolveAction;
    const skillTrainingAction = devObserverTryUseSkillTrainingItems(currentPlayer());
    if (skillTrainingAction) return skillTrainingAction;
    const missionEntry = devObserverTryEnterMissionBoard(currentPlayer());
    if (missionEntry) return missionEntry;
    const waterSevenEntry = devObserverTryEnterWaterSeven(currentPlayer());
    if (waterSevenEntry) return waterSevenEntry;
    const recoveryAction = devObserverTryUseMapRecovery(currentPlayer());
    if (recoveryAction) return recoveryAction;
    if (state.gameState.pendingMove && !state.gameState.movementAnimating && !state.gameState.resolutionLock) {
      await continueMove();
      return "繼續移動。";
    }
    if (state.gameState.movementAnimating || state.gameState.diceRolling || state.gameState.resolutionLock) return "等待移動 / 演出。";
    const clicked = devObserverHandleVisibleOverlay();
    if (clicked) return clicked;
    if (refs.rollDiceBtn && !refs.rollDiceBtn.disabled && !isGameActionLocked()) {
      await rollDice();
      return "擲骰前進。";
    }
    return "目前沒有可自動處理的動作。";
  }

  async function runDevObserverStep(manual = false) {
    if (devObserver.busy) return;
    devObserver.busy = true;
    try {
      const result = await performDevObserverStep();
      setDevObserverStatus(result);
    } catch (error) {
      console.error("[dev observer]", error);
      setDevObserverStatus(`自動觀察錯誤：${error?.message || error}`);
      setDevObserverRunning(false);
    } finally {
      devObserver.busy = false;
      if (devObserver.running && !manual) scheduleDevObserverStep(devObserverDelay(950));
    }
  }

  function cpuDraftCardScore(card, player) {
    if (!card) return -9999;
    const stats = card.baseStats || {};
    const crew = Array.isArray(player?.crew) ? player.crew : [];
    const ownedRoles = new Set(crew.map((entry) => entry?.roleType).filter(Boolean));
    const ownedAttributes = new Set(crew.map((entry) => entry?.attribute).filter(Boolean));
    const role = card.roleType || "";
    const attribute = card.attribute || "";
    let score = 0;
    score += Number(stats.hp || 0) * 0.9;
    score += Math.max(Number(stats.atk || 0), Number(stats.satk || 0)) * 1.35;
    score += (Number(stats.def || 0) + Number(stats.sdef || 0)) * 0.55;
    score += Number(stats.spd || 0) * 0.85;
    score += Number(card.move || 0) * 18;
    score += Math.max(0, 7 - tierRank(card.tier)) * 35;
    if (!ownedRoles.has(role)) score += 80;
    if (!ownedAttributes.has(attribute)) score += 42;
    if (!crew.length && role === "戰鬥型") score += 70;
    if (crew.length === 1 && ["輔助型", "移動型"].includes(role)) score += 58;
    return score;
  }

  function cpuChooseDraftCard(player, rollInfo) {
    const list = (rollInfo?.allowedTiers || []).flatMap((tier) => availableRecruitCardsForTier(tier, player));
    return list.slice().sort((a, b) => cpuDraftCardScore(b, player) - cpuDraftCardScore(a, player))[0] || null;
  }

  function runCpuSetupDraftStep() {
    const game = state.gameState;
    if (!game || game.phase !== "setup-draft") return "";
    const playerId = game.draftSequence[game.draftPickIndex];
    if (!playerId) {
      finalizeCrewSetup();
      return "CPU 完成開局選角。";
    }
    const player = draftPlayerById(playerId);
    if (!canLocalDriveCpuPlayer(player)) return "";
    const playerIndex = game.players.findIndex((entry) => entry.id === playerId);
    if (playerIndex >= 0) game.currentPlayerIndex = playerIndex;
    const pickIndex = player.crew.length;
    const rollInfo = player.recruitRolls[pickIndex];
    if (!rollInfo) {
      const roll = randomInt(1, 6);
      const rolledTier = tierFromDiceRoll(roll);
      const resolvedTier = resolveRecruitTierFromRoll(roll, player);
      const allowedTiers = [resolvedTier];
      player.recruitRolls[pickIndex] = { roll, rolledTier, resolvedTier, allowedTiers };
      game.draftPickNotice = `${player.name} 的命運轉盤停在 ${tierLabel(rolledTier)}，本次可選 ${tierLabel(resolvedTier)}。`;
      addLog(`${player.name} 的第 ${pickIndex + 1} 次命運轉盤停在 ${tierLabel(rolledTier)}，本次可選 ${tierLabel(resolvedTier)}${resolvedTier !== rolledTier ? "（原階級已抽完，自動升階）" : ""}。`);
      const wheelEvent = emitBoardUiEvent("draft-wheel", {
        player,
        theme: "fate",
        title: `${player.name} 的命運轉盤`,
        subtitle: "CPU 正在轉動命運，決定本次可選夥伴階級。",
        maxFace: 6,
        result: roll,
        settleDelay: cpuTurnDelay(1450, player, 960),
        detail: { resolvedTier },
      }, { immediate: true, clearDelay: 1900 });
      renderAll();
      scheduleBoardLanStatePush("cpu-draft-roll", 100, { force: true });
      showSynchronizedDraftWheel(wheelEvent);
      return `CPU 命運轉盤：${tierLabel(resolvedTier)}`;
    }
    const pick = cpuChooseDraftCard(player, rollInfo);
    if (!pick) return "CPU 等待可選角色。";
    const recruit = cloneFreshDraftRecruit(pick);
    player.crew.push(recruit);
    player.activeCrewIndex = 0;
    game.availableCards = game.availableCards.filter((entry) => entry.id !== pick.id);
    recalcPlayerDerivedStats(player);
    game.draftPickNotice = `${player.name} 選擇了 ${pick.name}（${tierLabel(pick.tier)}・${pick.roleType}・${pick.attribute}）。`;
    addLog(`${player.name} 選擇了 ${pick.name}（${tierLabel(pick.tier)}・${pick.roleType}・${pick.attribute}）。`);
    emitBoardActionNotice("draft-pick", "選擇夥伴", `${player.name} 選擇了 ${pick.name}`, {
      player,
      cardName: pick.name,
      theme: "fate",
      symbol: "卡",
    }, { immediate: true });
    game.draftPickIndex += 1;
    renderAll();
    scheduleBoardLanStatePush("cpu-draft-pick", 100, { force: true });
    openSetupStep();
    return `CPU 選擇夥伴：${pick.name}`;
  }

  function cpuAutomationTargetPlayer() {
    if (!state.gameState) return null;
    if (state.gameState.phase === "setup-draft") {
      return draftPlayerById(state.gameState.draftSequence[state.gameState.draftPickIndex]);
    }
    if (state.battleState) {
      if (isCoopBattle(state.battleState)) {
        return coopBattleReplacementPlayer(state.battleState)
          || battleCommandPlayer(state.battleState)
          || battlePlayer(null, state.battleState);
      }
      return battlePlayer(null, state.battleState);
    }
    return currentPlayer();
  }

  function shouldRunCpuAutoStep() {
    if (!state.gameState || boardLan.applying || devObserver.running || cpuAuto.busy || draftWheelAnimationBusy) return false;
    if (state.gameState.phase === "setup-order") return false;
    if (state.gameState.phase !== "main" && state.gameState.phase !== "setup-draft") return false;
    const player = cpuAutomationTargetPlayer();
    return canLocalDriveCpuPlayer(player);
  }

  function cpuAutoDelay() {
    const player = cpuAutomationTargetPlayer();
    if (state.gameState?.phase === "setup-draft") return cpuTurnDelay(850, player, 620);
    if (state.battleState) return cpuTurnDelay(1100, player, 300);
    if (state.gameState?.pendingMove || state.gameState?.movementAnimating || state.gameState?.resolutionLock) return cpuTurnDelay(700, player, 180);
    return cpuTurnDelay(1450, player, 360);
  }

  function scheduleCpuAutoStep(delay = cpuAutoDelay()) {
    window.clearTimeout(cpuAuto.timer);
    cpuAuto.timer = window.setTimeout(runCpuAutoStep, Math.max(120, Number(delay || 0)));
  }

  async function runCpuAutoStep() {
    cpuAuto.timer = 0;
    if (!shouldRunCpuAutoStep()) return;
    cpuAuto.busy = true;
    try {
      const result = state.gameState.phase === "setup-draft"
        ? runCpuSetupDraftStep()
        : await performDevObserverStep();
      cpuAuto.lastResult = result || "";
      cpuAuto.lastError = "";
      scheduleBoardLanStatePush("cpu-auto", 140, { force: true });
    } catch (error) {
      console.error("[cpu auto]", error);
      cpuAuto.lastError = String(error?.message || error);
    } finally {
      cpuAuto.busy = false;
      if (shouldRunCpuAutoStep()) scheduleCpuAutoStep(cpuAutoDelay());
    }
  }

  function setupCpuAutomation() {
    window.setInterval(() => {
      if (shouldRunCpuAutoStep() && !cpuAuto.timer) scheduleCpuAutoStep(cpuAutoDelay());
    }, 320);
    scheduleCpuAutoStep(360);
  }

  function setupDeveloperObserverPanel() {
    loadDevObserverSettings();
    window.openBoardDevObserver = () => toggleDevObserverPanel(true);
    window.closeBoardDevObserver = () => toggleDevObserverPanel(false);
    window.toggleBoardDevObserver = () => toggleDevObserverPanel();
    window.startBoardDevObserver = () => {
      toggleDevObserverPanel(true);
      setDevObserverRunning(true);
    };
    window.stopBoardDevObserver = () => setDevObserverRunning(false);
    document.addEventListener("keydown", (event) => {
      if (event.ctrlKey && event.shiftKey && String(event.key || "").toLowerCase() === "d") {
        event.preventDefault();
        toggleDevObserverPanel();
      }
    });
    if (devObserver.visible || query.get("dev") === "1" || query.get("observer") === "1") {
      toggleDevObserverPanel(true);
    }
  }

  async function rewindCurrentPlayerBeforeFinalGate(options = {}) {
    const opts = options && typeof options === "object" ? options : {};
    const players = state.gameState?.players || [];
    const requestedIndex = Number.isFinite(Number(opts.playerIndex)) ? Number(opts.playerIndex) : state.gameState.currentPlayerIndex;
    const playerIndex = Math.max(0, Math.min(players.length - 1, Math.round(requestedIndex || 0)));
    const player = players[playerIndex] || currentPlayer();
    if (!player) return { ok: false, reason: "找不到玩家。" };

    state.gameState.currentPlayerIndex = playerIndex;
    state.gameState.finalIslandCandidate = true;
    state.gameState.finalIslandUnlocked = true;
    const layout = ensureFinalIslandLayout(state.gameState, { createIfMissing: true, randomSalt: "debug-rewind-final-gate" });
    const anchorId = finalGateAnchorIslandId() || layout?.anchorIslandId || "";
    if (!anchorId) return { ok: false, reason: "找不到最終之島連接點。" };

    if (opts.grantRoadPoneglyphs !== false) {
      player.roadPoneglyphs = Object.keys(ROAD_PONEGLYPH_BY_GLYPH);
      ROAD_PONEGLYPH_ITEM_IDS.forEach((itemId) => {
        if (inventoryItemCount(player, itemId) <= 0) addInventoryItem(player, itemId, 1);
      });
    }

    player.location = {
      kind: "island",
      islandId: anchorId,
      entryDirection: layout?.directions?.from || "",
    };
    player.routeChoice = null;
    player.pendingBattle = null;
    player.finalGateDefeated = false;
    player.finalGateAftermathSeen = false;
    player.finalGateElbaphCleared = false;
    player.finalGateElbaphStep = "";
    player.finalGateChopperHealed = false;
    player.finalGateBlackTurnCleared = false;
    player.finalGateBlackTurnCrewId = "";
    player.finalGateBlackTurnCrewName = "";
    player.finalGateAttempts = 0;
    player.finalGateRetreat = null;
    player.finalEndingSeen = [];
    player.finalEndingChoice = "";
    player.finalEndingCleared = false;
    if (opts.healCrew !== false) {
      (player.crew || []).forEach((card) => {
        if (!card) return;
        const maxHp = cardMaxHp(card);
        card.currentHp = maxHp;
        card.currentStages = { atk: 0, def: 0, satk: 0, sdef: 0, spd: 0, accuracy: 0, evasion: 0 };
        (card.moveSet || []).forEach((entry) => {
          entry.currentPP = Number(entry.pp || entry.maxPP || entry.currentPP || 0);
        });
      });
      player.activeCrewIndex = livingCrewIndices(player)[0] ?? 0;
      recalcPlayerDerivedStats(player);
    }

    state.battleState = null;
    state.gameState.pendingMove = null;
    state.gameState.routePrompt = null;
    state.gameState.islandDecision = null;
    state.gameState.movementAnimating = false;
    state.gameState.resolutionLock = false;
    state.gameState.turnStep = "已退回伊姆入口前";
    state.gameState.finalGateDefeatedBy = state.gameState.finalGateDefeatedBy && typeof state.gameState.finalGateDefeatedBy === "object"
      ? state.gameState.finalGateDefeatedBy
      : {};
    delete state.gameState.finalGateDefeatedBy[player.id];
    state.gameState.finalEndingCleared = false;
    state.gameState.finalEndingLast = null;
    if (state.gameState.finalEndingRecords && typeof state.gameState.finalEndingRecords === "object") {
      delete state.gameState.finalEndingRecords[player.id];
    }

    const finalState = getIslandState("final-island");
    if (finalState) {
      finalState.enemyProfile = finalGateEnemyProfile();
      finalState.enemyTier = FINAL_GATE_ENEMY_PROFILE.tier;
      finalState.maxHp = FINAL_GATE_ENEMY_PROFILE.maxHp;
      finalState.currentHp = FINAL_GATE_ENEMY_PROFILE.maxHp;
      finalState.isDefeated = false;
    }

    addLog(`${player.name} 的紀錄已退回艾爾巴夫，伊姆與神之騎士團尚未被擊敗。`);
    closeModal();
    renderAll();
    if (opts.save !== false) await saveManualGame();
    return { ok: true, player: player.name, islandId: anchorId, saved: opts.save !== false };
  }

